   Проверка ЗДЕСЬ, а не в меню: спрятанную кнопку можно вызвать руками. */
function crm_auth($roles) {
  $s = authUser('itc');
  $r = $s['staff_role'] ?? '';
  if (!in_array($r, $roles, true)) fail('Недостаточно прав', 403);
  return $s;
}

