/* Таблицы CRM. Создаются сами при первом обращении — отдельную миграцию
   руками запускать не нужно. */
function crm_tables() {
  static $done = false;
  if ($done) return;
  db()->exec("CREATE TABLE IF NOT EXISTS crm_clients (
      id VARCHAR(20) NOT NULL,
      alias VARCHAR(255) NOT NULL DEFAULT '',
      company VARCHAR(255) NOT NULL DEFAULT '',
      inn VARCHAR(20) NOT NULL DEFAULT '',
      kpp VARCHAR(20) NOT NULL DEFAULT '',
      ogrn VARCHAR(20) NOT NULL DEFAULT '',
      addr VARCHAR(255) NOT NULL DEFAULT '',
      bank VARCHAR(255) NOT NULL DEFAULT '',
      bik VARCHAR(20) NOT NULL DEFAULT '',
      acct VARCHAR(34) NOT NULL DEFAULT '',
      corr VARCHAR(34) NOT NULL DEFAULT '',
      site VARCHAR(255) NOT NULL DEFAULT '',
      note TEXT,
      created_at DATETIME NULL,
      created_by VARCHAR(20) NOT NULL DEFAULT '',
      PRIMARY KEY (id),
      KEY k_company (company)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  db()->exec("CREATE TABLE IF NOT EXISTS crm_contacts (
      id VARCHAR(20) NOT NULL,
      client_id VARCHAR(20) NOT NULL,
      name VARCHAR(255) NOT NULL,
      post VARCHAR(255) NOT NULL DEFAULT '',
      area VARCHAR(255) NOT NULL DEFAULT '',
      phone VARCHAR(40) NOT NULL DEFAULT '',
      email VARCHAR(255) NOT NULL DEFAULT '',
      note TEXT,
      PRIMARY KEY (id),
      KEY k_client (client_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  /* Таблица могла завестись до появления псевдонима — дописываем поле молча.
     Если оно уже есть, MySQL ругнётся, и это нормально. */
  /* СДЕЛКИ. Одна сделка — одна поставка. Тип: white (официальный импорт)
     или cargo (карго). Расходы лежат отдельной таблицей, у каждой строки
     ДВЕ суммы: по расчёту и фактическая. */
  db()->exec("CREATE TABLE IF NOT EXISTS crm_deals (
      id VARCHAR(20) NOT NULL,
      client_id VARCHAR(20) NOT NULL DEFAULT '',
      title VARCHAR(255) NOT NULL DEFAULT '',
      kind VARCHAR(10) NOT NULL DEFAULT 'white',
      status VARCHAR(20) NOT NULL DEFAULT 'open',
      sold_plan DECIMAL(14,2) NOT NULL DEFAULT 0,
      sold_fact DECIMAL(14,2) NOT NULL DEFAULT 0,
      started_on DATE NULL,
      closed_on DATE NULL,
      note TEXT,
      created_at DATETIME NULL,
      created_by VARCHAR(20) NOT NULL DEFAULT '',
      PRIMARY KEY (id),
      KEY k_client (client_id),
      KEY k_status (status)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  db()->exec("CREATE TABLE IF NOT EXISTS crm_deal_costs (
      id VARCHAR(20) NOT NULL,
      deal_id VARCHAR(20) NOT NULL,
      kind VARCHAR(40) NOT NULL DEFAULT '',
      label VARCHAR(255) NOT NULL DEFAULT '',
      plan DECIMAL(14,2) NOT NULL DEFAULT 0,
      fact DECIMAL(14,2) NOT NULL DEFAULT 0,
      sort INT NOT NULL DEFAULT 0,
      PRIMARY KEY (id),
      KEY k_deal (deal_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  /* РАСХОДЫ КОМПАНИИ. Вбивает бухгалтер, общую картину видит только босс.
     Статья может быть из списка или своя. Оплата: наличными или со счёта. */
  db()->exec("CREATE TABLE IF NOT EXISTS crm_expenses (
      id VARCHAR(20) NOT NULL,
      label VARCHAR(255) NOT NULL DEFAULT '',
      amount DECIMAL(14,2) NOT NULL DEFAULT 0,
      paid_on DATE NULL,
      pay_way VARCHAR(10) NOT NULL DEFAULT 'bank',
      note TEXT,
      created_at DATETIME NULL,
      created_by VARCHAR(20) NOT NULL DEFAULT '',
      PRIMARY KEY (id),
      KEY k_date (paid_on)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  /* ПОСТОЯННЫЕ РАСХОДЫ — аренда, зарплаты и прочее, что повторяется каждый
     месяц. Здесь лежит только образец; сами записи создаются кнопкой
     «Внести за месяц» и ложатся в обычные расходы. Так бухгалтер не вбивает
     одно и то же по кругу, а история остаётся честной: сумма и дата у
     каждого месяца свои. */
  db()->exec("CREATE TABLE IF NOT EXISTS crm_exp_fixed (
      id VARCHAR(20) NOT NULL,
      label VARCHAR(255) NOT NULL DEFAULT '',
      amount DECIMAL(14,2) NOT NULL DEFAULT 0,
      pay_way VARCHAR(10) NOT NULL DEFAULT 'bank',
      day INT NOT NULL DEFAULT 1,
      active TINYINT NOT NULL DEFAULT 1,
      note TEXT,
      PRIMARY KEY (id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  db()->exec("CREATE TABLE IF NOT EXISTS crm_kp (
      id VARCHAR(20) NOT NULL,
      client_id VARCHAR(20) NOT NULL,
      no VARCHAR(40) NOT NULL DEFAULT '',
      dt VARCHAR(40) NOT NULL DEFAULT '',
      total DECIMAL(14,2) NOT NULL DEFAULT 0,
      items MEDIUMTEXT,
      created_at DATETIME NULL,
      created_by VARCHAR(20) NOT NULL DEFAULT '',
      PRIMARY KEY (id),
      KEY k_client (client_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  try { db()->exec("ALTER TABLE crm_clients ADD COLUMN alias VARCHAR(255) NOT NULL DEFAULT '' AFTER id"); } catch (Exception $e) {}
  try { db()->exec("ALTER TABLE crm_clients MODIFY company VARCHAR(255) NOT NULL DEFAULT ''"); } catch (Exception $e) {}
  $done = true;
}

/* ============================================================
   FIREBASE — отправка уведомлений в приложение (22.08.2026)
   Три функции: завести таблицу, войти в Google по ключу, разослать.
   ============================================================ */

/* Таблица меток. Создаётся сама при первом обращении — отдельную
   миграцию руками запускать не нужно. */
function fcm_table() {
  static $done = false;
  if ($done) return;
  db()->exec("CREATE TABLE IF NOT EXISTS push_tokens (
      token    VARCHAR(255) NOT NULL,
      phone    VARCHAR(20)  NOT NULL,
      platform VARCHAR(16)  NOT NULL DEFAULT 'android',
      updated_at DATETIME   NOT NULL,
      PRIMARY KEY (token),
      KEY k_phone (phone)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $done = true;
}

/* Вход в Google. Секретный ключ — обычный файл JSON из Firebase.
   Google в обмен на подписанный запрос выдаёт пропуск на час; пропуск
   держим в файле во временной папке, чтобы не ходить за ним каждый раз. */
function fcm_access_token() {
  static $cached = null;
  if ($cached) return $cached;

  $cache = sys_get_temp_dir() . '/itc_fcm_token.json';
  if (is_file($cache)) {
    $c = json_decode(@file_get_contents($cache), true);
    if (is_array($c) && ($c['exp'] ?? 0) > time() + 60) { $cached = $c['tok']; return $cached; }
  }

  if (!defined('FCM_KEY_FILE') || !is_file(FCM_KEY_FILE))
    throw new Exception('Не найден секретный ключ Firebase. Проверьте путь FCM_KEY_FILE в config.php');
  $key = json_decode(file_get_contents(FCM_KEY_FILE), true);
  if (!is_array($key) || empty($key['private_key']) || empty($key['client_email']))
    throw new Exception('Файл ключа Firebase испорчен');

  $b64 = function($x){ return rtrim(strtr(base64_encode($x), '+/', '-_'), '='); };
  $now = time();
  $head = $b64(json_encode(['alg'=>'RS256','typ'=>'JWT']));
  $claim = $b64(json_encode([
    'iss'   => $key['client_email'],
    'scope' => 'https://www.googleapis.com/auth/firebase.messaging',
    'aud'   => 'https://oauth2.googleapis.com/token',
    'iat'   => $now,
    'exp'   => $now + 3600,
  ]));
  $sig = '';
  if (!openssl_sign($head.'.'.$claim, $sig, $key['private_key'], 'sha256WithRSAEncryption'))
    throw new Exception('Не удалось подписать запрос к Google');
  $jwt = $head.'.'.$claim.'.'.$b64($sig);

  $ch = curl_init('https://oauth2.googleapis.com/token');
  curl_setopt_array($ch, [
    CURLOPT_POST => true,
    CURLOPT_POSTFIELDS => http_build_query([
      'grant_type' => 'urn:ietf:params:oauth:grant-type:jwt-bearer',
      'assertion'  => $jwt,
    ]),
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_TIMEOUT => 20,
  ]);
  $res = curl_exec($ch);
  curl_close($ch);
  $j = json_decode($res, true);
  if (empty($j['access_token']))
    throw new Exception('Google не выдал пропуск: ' . substr((string)$res, 0, 200));

  $cached = $j['access_token'];
  @file_put_contents($cache, json_encode(['tok'=>$cached,'exp'=>$now + 3500]));
  return $cached;
}

/* Рассылка. Google принимает по одному устройству за раз, поэтому идём
   списком. Метку, на которую Google ответил «такого нет», удаляем —
   это удалённое приложение, иначе мусор копится годами. */
function fcm_send($tokens, $title, $text, $url = '/') {
  $sent = 0; $failed = 0; $dead = [];
  $access = fcm_access_token();
  $pid = defined('FCM_PROJECT_ID') ? FCM_PROJECT_ID : '';
  if (!$pid) throw new Exception('Не задан FCM_PROJECT_ID в config.php');
  $endpoint = 'https://fcm.googleapis.com/v1/projects/' . $pid . '/messages:send';

  foreach ($tokens as $tok) {
    $msg = ['message' => [
      'token' => $tok,
      'notification' => ['title' => $title, 'body' => $text],
      'data' => ['url' => $url],
      'android' => ['priority' => 'high', 'notification' => ['sound' => 'default']],
    ]];
    $ch = curl_init($endpoint);
    curl_setopt_array($ch, [
      CURLOPT_POST => true,
      CURLOPT_HTTPHEADER => ['Authorization: Bearer '.$access, 'Content-Type: application/json'],
      CURLOPT_POSTFIELDS => json_encode($msg, JSON_UNESCAPED_UNICODE),
      CURLOPT_RETURNTRANSFER => true,
      CURLOPT_TIMEOUT => 20,
    ]);
    $res = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    if ($code >= 200 && $code < 300) { $sent++; }
    else {
      $failed++;
      if ($code === 404 || $code === 400) $dead[] = $tok;
    }
  }
  if ($dead) {
    $in = implode(',', array_fill(0, count($dead), '?'));
    try { db()->prepare("DELETE FROM push_tokens WHERE token IN ($in)")->execute($dead); } catch (Exception $e) {}
  }
  return ['sent'=>$sent, 'failed'=>$failed, 'removed'=>count($dead)];
}
/* УВЕДОМЛЕНИЕ НА ТЕЛЕФОН ПО НОМЕРУ (обновление №266). В приложение (FCM) и в
   браузер (веб-уведомления), что из них есть у человека. Никогда не роняет
   вызвавшую команду: не ушло — значит не ушло, ответ всё равно сохранён. */
function itc_push_phone($phone, $title, $text, $url = '/') {
  $sent = 0;
  try {
    fcm_table();
    $st = db()->prepare('SELECT token FROM push_tokens WHERE phone = ?');
    $st->execute([ph_norm($phone) ?: $phone]);
    $toks = $st->fetchAll(PDO::FETCH_COLUMN);
    if ($toks) { $r = fcm_send($toks, $title, $text, $url); $sent += (int)($r['sent'] ?? 0); }
  } catch (Exception $e) {}
  try { if (function_exists('wp_send_to_phone')) wp_send_to_phone(db(), $phone, $title, $text, $url); } catch (Exception $e) {}
  return $sent;
}
/* ПУНКТ ВЫДАЧИ ПОКУПАТЕЛЯ (обновление №266). Берём из последнего заказа
   (оплаченные вперёд), иначе — пункт, выбранный в кабинете. Для «Обращений»:
   клиент спрашивает «где забрать», и ответ должен быть виден сразу. */
function itc_buyer_point($phone) {
  $tail = ph_tail($phone);
  try {
    if (strlen($tail) >= 10) {
      $q = db()->prepare("SELECT o.num, w.code, w.name, w.city FROM orders o JOIN warehouses w ON w.id=o.warehouse_id
                           WHERE RIGHT(".ph_sql('o.phone').",10)=? ORDER BY o.paid DESC, o.created_at DESC LIMIT 1");
      $q->execute([$tail]);
    } else {
      $q = db()->prepare("SELECT o.num, w.code, w.name, w.city FROM orders o JOIN warehouses w ON w.id=o.warehouse_id
                           WHERE o.phone=? ORDER BY o.paid DESC, o.created_at DESC LIMIT 1");
      $q->execute([$phone]);
    }
    $r = $q->fetch();
    if ($r) return ['code'=>$r['code'], 'name'=>$r['name'], 'city'=>$r['city'], 'src'=>'order', 'num'=>$r['num']];
  } catch (Exception $e) {}
  try {
    $q = db()->prepare("SELECT w.code, w.name, w.city FROM customers c JOIN warehouses w ON w.id=c.warehouse_id WHERE c.phone=? LIMIT 1");
    $q->execute([$phone]);
    $r = $q->fetch();
    if ($r) return ['code'=>$r['code'], 'name'=>$r['name'], 'city'=>$r['city'], 'src'=>'profile', 'num'=>''];
  } catch (Exception $e) {}
  return null;
}

