// Сгенерировать секретный код сотрудника
function staff_gen_code() { return strtoupper(bin2hex(random_bytes(5))); } // 10 hex-символов

// Анти-перебор: не больше $max попыток за $min минут на телефон+тип
function rl_ok($phone, $kind, $max, $min) {
  try {
    $q = db()->prepare("SELECT COUNT(*) c FROM login_attempts WHERE phone=? AND kind=? AND created_at > (NOW() - INTERVAL ? MINUTE)");
    $q->execute([$phone, $kind, $min]);
    return (int)$q->fetch()['c'] < $max;
  } catch (Exception $e) { return true; }
}
function rl_hit($phone, $kind) {
  try { db()->prepare("INSERT INTO login_attempts (id,phone,kind) VALUES (?,?,?)")->execute([substr(md5(uniqid('',true)),0,20), $phone, $kind]); } catch (Exception $e) {}
}

// ===== Расчёт «под ключ» по категории C0 (сборный груз — особые условия) =====
// Настройки расчёта (ставки). Читаются из таблицы settings, с дефолтами из приложения ИТК.
function calc_defaults() {
  return [
    'kurs_cny'     => 13.2,   // ¥ → ₽
    'kurs_usd'     => 95,     // $ → ₽
    'duty'         => 10,     // пошлина, %
    'vat'          => 22,     // НДС, %
    'station'      => 150000, // услуги станции, ₽
    'broker'       => 35000,  // услуги брокера, ₽
    'delivery'     => 250000, // доставка до клиента, ₽
    'transfer'     => 3,      // перевод денег в Китай, %
    'jinjia_fee'   => 3,      // прибыль Jinjia на закупку, % (китайские налоги)
    'cont_vol'     => 68,     // объём контейнера, м³
    'cont_weight'  => 26800,  // грузоподъёмность контейнера, кг (40', для High Cube ~26700)
    'freight_usd'  => 10000,  // фрахт контейнера, $
    'goods_markup' => 25,     // наценка на товар (особые условия), %
    'coef'         => 2.0,    // коэффициент логистики (C0)
    'x3_mult'      => 4,      // множитель кнопки ×3 (себестоимость × N, вкл. всю логистику и маржу)
    'deposit_cny'  => 1000,   // депозит поставщика при регистрации, ¥
    'delivery_days' => 25,    // срок доставки на карточках, дней
    'show_hero'    => 0,      // баннер «Прямой импорт» на главной (0/1)
    'ref_percent'  => 5,      // реферальное вознаграждение партнёру, % от оборота приведённого клиента
    'batch_period_days' => 3, // период сбора партии по поставщику для инвойсов/упаковочных, дней
    'group_variants' => 0,    // группировать варианты одного 1688-товара в одну карточку (0/1) — тест-режим
    'oversize_m3'  => 0.15,   // больше этого объёма пункт выдачи принять не может — только склад
    'oversize_kg'  => 25,     // то же по весу: тяжелее — только склад
  ];
}
// Одиночная настройка из таблицы settings (не только ценовые ключи)
function itc_setting($k, $def=null) {
  try { $q=db()->prepare('SELECT v FROM settings WHERE k=?'); $q->execute([$k]); $v=$q->fetchColumn();
        if ($v!==false && $v!==null && $v!=='') return $v; } catch (Exception $e) {}
  return $def;
}
/* №878: ДОСТАВКА ПО КИТАЮ ОТ ПРОДАВЦОВ 1688 и МИНИМАЛЬНЫЙ ЗАКАЗ ДЕШЁВЫХ ТОВАРОВ.
   Доставку продавец берёт один раз за посылку, поэтому в цену штуки её не кладём,
   а считаем в заказе: одна строка на продавца. Суммы больше потолка (999, 600 ¥ —
   доставка в дальние районы или заглушка) считаем обычной доставкой. */
function itc_cn_ship_cfg() {
  $st = get_settings(); $n = function($k, $d) use ($st) { return isset($st[$k]) && is_numeric($st[$k]) ? (float)$st[$k] : $d; };
  return ['cap'=>$n('cn_ship_cap', 30), 'def'=>$n('cn_ship_default', 5), 'mult'=>$n('cn_ship_mult', 1), 'kc'=>$n('kurs_cny', 13.2),
          'jf'=>$n('jinjia_fee', 3) / 100, 'tr'=>$n('transfer', 3) / 100, 'cheap'=>$n('cheap_price', 30), 'minsum'=>$n('cheap_min_sum', 100)];
}
function itc_min_qty($price) {
  $c = itc_cn_ship_cfg(); $price = (float)$price;
  if ($price <= 0 || $price >= $c['cheap'] || $c['minsum'] <= 0) return 1;
  return max(1, (int)ceil($c['minsum'] / $price));
}
function itc_cn_ship($pids) {
  $c = itc_cn_ship_cfg(); $groups = []; $pids = array_values(array_unique(array_filter(array_map('strval', (array)$pids))));
  if (!$pids) return ['rub'=>0, 'groups'=>[]];
  $q1 = db()->prepare("SELECT source_url FROM ds_products WHERE product_id=? AND source_url LIKE '%1688%' ORDER BY id DESC LIMIT 1");
  $q2 = db()->prepare("SELECT JSON_UNQUOTE(JSON_EXTRACT(payload,'$.item.post_fee')) f, JSON_UNQUOTE(JSON_EXTRACT(payload,'$.item.seller_info.user_num_id')) s,
                              JSON_UNQUOTE(JSON_EXTRACT(payload,'$.item.nick')) nk FROM ob_raw WHERE num_iid=? AND JSON_VALID(payload) AND JSON_EXTRACT(payload,'$.item.post_fee') IS NOT NULL ORDER BY fetched_at DESC LIMIT 1");
  foreach ($pids as $pid) {
    try {
      $q1->execute([$pid]); $u = (string)$q1->fetchColumn(); if (!preg_match('~offer/(\d+)~', $u, $m)) continue;
      $q2->execute([$m[1]]); $r = $q2->fetch(); if (!$r) continue;
      $f = (float)$r['f']; if ($f <= 0) continue; if ($f > $c['cap']) $f = $c['def'];
      $key = (string)($r['s'] ?: ($r['nk'] ?: $m[1]));
      if (!isset($groups[$key])) $groups[$key] = ['fee_cny'=>0, 'items'=>[], 'seller'=>(string)($r['nk'] ?? '')];
      $groups[$key]['fee_cny'] = max($groups[$key]['fee_cny'], $f); $groups[$key]['items'][] = $pid;
    } catch (Exception $e) {}
  }
  $tot = 0; $out = [];
  foreach ($groups as $g) { $rub = (int)(ceil($g['fee_cny'] * (1 + $c['jf']) * $c['kc'] * (1 + $c['tr']) * $c['mult'] / 5) * 5); $tot += $rub; $out[] = ['rub'=>$rub, 'items'=>$g['items']]; }
  return ['rub'=>$tot, 'groups'=>$out];
}
function get_settings() {
  $s = calc_defaults();
  try {
    $rows = db()->query('SELECT k, v FROM settings')->fetchAll();
    foreach ($rows as $r) { if (array_key_exists($r['k'], $s)) $s[$r['k']] = (float)$r['v']; }
  } catch (Exception $e) { /* таблицы ещё нет — берём дефолты */ }
  return $s;
}
// Запись действия сотрудника ИТК в журнал (безопасно, если таблицы ещё нет)
function itc_log_add($staff, $action, $ttype = '', $tid = '', $details = '') {
  try {
    db()->prepare('INSERT INTO itc_log (staff,action,target_type,target_id,details) VALUES (?,?,?,?,?)')
        ->execute([mb_substr((string)$staff,0,120), mb_substr((string)$action,0,40),
                   mb_substr((string)$ttype,0,40), mb_substr((string)$tid,0,64), mb_substr((string)$details,0,255)]);
  } catch (Exception $e) { /* нет таблицы — пропускаем */ }
}
// Итоговая цена «под ключ» в рублях по формуле C0.
// Доля товара в контейнере = максимум из доли по объёму и доли по весу (отраслевой стандарт W/M).
/* Идёт ли закупка через Jinjia: дропшиппинг всегда, фабрики — по плательщику.
   Только на такие товары ложатся +3% прибыли Jinjia (китайские налоги). */
function pays_via_jinjia($supplier_id) {
  static $c = [];
  $supplier_id = (string)$supplier_id;
  if ($supplier_id === '') return false;
  if (array_key_exists($supplier_id, $c)) return $c[$supplier_id];
  $r = false;
  try {
    $q = db()->prepare('SELECT pay_company FROM suppliers WHERE id=?');
    $q->execute([$supplier_id]);
    $r = ((string)($q->fetchColumn() ?: '') === 'jinjia');
  } catch (Exception $e) {}
  if (!$r && $supplier_id === ds_supplier_id()) $r = true;   // дропшиппинг — всегда через Jinjia
  return $c[$supplier_id] = $r;
}
// Товар куплен через Jinjia? (по id товара)
function product_via_jinjia($pid) {
  try {
    $q = db()->prepare('SELECT supplier_id FROM products WHERE id=?');
    $q->execute([$pid]);
    return pays_via_jinjia((string)($q->fetchColumn() ?: ''));
  } catch (Exception $e) { return false; }
}
function calc_landed_rub($goods_cny, $vol_m3, $wt_kg, $st, $viaJinjia = false) {
  // Через Jinjia себестоимость выше на её прибыль: ¥1000 закупка -> ¥1030 в инвойсе ИТК
  $jf   = $viaJinjia ? (1 + (float)($st['jinjia_fee'] ?? 0) / 100) : 1;
  $T    = $goods_cny * $jf * $st['kurs_cny'];
  $duty = $T * ($st['duty'] / 100);
  $vatG = $T * ($st['vat'] / 100);
  $Frub = $st['freight_usd'] * $st['kurs_usd'];
  $share_vol = $st['cont_vol'] > 0 ? $vol_m3 / $st['cont_vol'] : 0;
  $share_wt  = (!empty($st['cont_weight']) && $st['cont_weight'] > 0) ? $wt_kg / $st['cont_weight'] : 0;
  $share = max($share_vol, $share_wt);
  $vatF = (($Frub * $share) / 2) * ($st['vat'] / 100);
  $block1   = ($T + $duty + $vatG + $vatF) * (1 + $st['goods_markup'] / 100);
  $block2u  = $st['freight_usd'] * $share * $st['coef'];
  $block2r  = ($st['station'] + $st['broker'] + $st['delivery']) * $share * $st['coef'];
  $finalUsd = $block2u * (1 + $st['transfer'] / 100);
  $finalRub = ($block1 + $block2r) * (1 + $st['transfer'] / 100);
  return (int)round($finalRub + $finalUsd * $st['kurs_usd']);
}
// Суммарный вес упаковки товара из списка коробок (кг)
function boxes_weight($d) {
  $wt = 0;
  if (!empty($d['boxes']) && is_array($d['boxes'])) foreach ($d['boxes'] as $b) { if (is_array($b)) $wt += (float)($b['wt'] ?? 0); }
  return $wt;
}


$STATUSES = ['created','confirmed','at_warehouse','in_container','shipping','delivering','done'];
function next_status($cur) {
  global $STATUSES;
  $i = array_search($cur, $STATUSES);
  return ($i !== false && $i < count($STATUSES) - 1) ? $STATUSES[$i + 1] : null;
}

// Устойчивая запись характеристик (не падает, если колонка specs ещё не создана)
function save_specs($id, $d) {
  if (!array_key_exists('specs', $d)) return;
  $specs = $d['specs'];
  if (!is_array($specs)) $specs = [];
  $clean = [];
  foreach ($specs as $row) {
    if (!is_array($row)) continue;
    $k = trim((string)($row['k'] ?? ''));
    $v = trim((string)($row['v'] ?? ''));
    if ($k === '' && $v === '') continue;
    $clean[] = ['k' => $k, 'v' => $v];
  }
  try {
    db()->prepare('UPDATE products SET specs=? WHERE id=?')
        ->execute([json_encode($clean, JSON_UNESCAPED_UNICODE), $id]);
  } catch (Exception $e) {}
}
function save_dims($id, $d) {
  if (array_key_exists('assembled', $d)) {
    try { db()->prepare('UPDATE products SET assembled=? WHERE id=?')->execute([trim((string)$d['assembled']), $id]); } catch (Exception $e) {}
  }
  if (array_key_exists('boxes', $d)) {
    $boxes = is_array($d['boxes']) ? $d['boxes'] : [];
    $clean = [];
    foreach ($boxes as $b) {
      if (!is_array($b)) continue;
      $l=(float)($b['l']??0); $w=(float)($b['w']??0); $h=(float)($b['h']??0); $wt=(float)($b['wt']??0);
      if ($l>0 || $w>0 || $h>0) $clean[] = ['l'=>$l,'w'=>$w,'h'=>$h,'wt'=>$wt];
    }
    try { db()->prepare('UPDATE products SET boxes=? WHERE id=?')->execute([json_encode($clean, JSON_UNESCAPED_UNICODE), $id]); } catch (Exception $e) {}
  }
}
function save_variants($id, $d) {
  if (!array_key_exists('variants', $d)) return;
  $v = $d['variants'];
  $baseName = '';
  $items = [];
  if (is_array($v)) {
    $baseName = trim((string)($v['baseName'] ?? ''));
    $rawItems = $v['items'] ?? [];
    if (is_array($rawItems)) {
      foreach ($rawItems as $it) {
        if (!is_array($it)) continue;
        $nm = trim((string)($it['name'] ?? ''));
        $gal = $it['gallery'] ?? [];
        if (!is_array($gal)) $gal = [];
        $gal = array_values(array_filter(array_map(function($u){ return is_string($u) ? $u : ''; }, $gal)));
        if ($nm === '' && !count($gal)) continue;
        $items[] = ['name' => $nm, 'gallery' => $gal];
      }
    }
  }
  $payload = ['baseName' => $baseName, 'items' => $items];
  try { db()->prepare('UPDATE products SET variants=? WHERE id=?')->execute([json_encode($payload, JSON_UNESCAPED_UNICODE), $id]); } catch (Exception $e) {}
}

// ============================================================
//  DS — вспомогательные функции (вне switch)
// ============================================================
function gen_ds_id(){ return 'ds'.substr(md5(uniqid('',true)),0,12); }

// ============================================================
//  PDD ПАРСЕР
// ============================================================
function pdd_gen_pid(){ return 'p'.substr(md5(uniqid('ds',true)),0,16); }

function pdd_normalize_url($url) {
  $url = trim($url);
  // yangkeduo.com / pinduoduo.com → mobile.yangkeduo.com
  $url = preg_replace('#https?://(www\.)?yangkeduo\.com#', 'https://mobile.yangkeduo.com', $url);
  $url = preg_replace('#https?://(www\.)?pinduoduo\.com#', 'https://mobile.yangkeduo.com', $url);
  return $url;
}

function pdd_fetch($url) {
  // Если в config.php настроен китайский прокси — читаем PDD его руками (китайский IP).
  if (defined('PDD_PROXY_URL') && PDD_PROXY_URL) {
    $r = pdd_fetch_via_proxy($url);
    if ($r !== null) return $r; // прокси ответил; иначе откатываемся на прямой запрос ниже
  }
  $ch = curl_init();
  curl_setopt_array($ch, [
    CURLOPT_URL => $url,
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_FOLLOWLOCATION => true,
    CURLOPT_MAXREDIRS => 5,
    CURLOPT_SSL_VERIFYPEER => false,
    CURLOPT_TIMEOUT => 15,
    CURLOPT_USERAGENT => 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.6099.230 Mobile Safari/537.36',
    CURLOPT_HTTPHEADER => [
      'Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      'Accept-Language: zh-CN,zh;q=0.9,en;q=0.5',
    ],
    CURLOPT_ENCODING => '',
  ]);
  $html = curl_exec($ch);
  $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
  curl_close($ch);
  return [$html ?: '', $code];
}

// Читает PDD через фетчер на китайском VPS (pdd_proxy.php). Возвращает [$html,$code] или null при недоступности.
function pdd_fetch_via_proxy($url) {
  $ep = PDD_PROXY_URL;
  $ep .= (strpos($ep,'?')===false ? '?' : '&').'key='.urlencode(defined('PDD_PROXY_KEY')?PDD_PROXY_KEY:'').'&url='.urlencode($url);
  $hdr = [];
  $ch = curl_init($ep);
  curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_TIMEOUT => 35,
    CURLOPT_CONNECTTIMEOUT => 10,
    CURLOPT_SSL_VERIFYPEER => false,
    CURLOPT_HEADERFUNCTION => function($c,$h) use (&$hdr){ $hdr[]=$h; return strlen($h); },
  ]);
  $body = curl_exec($ch);
  $pc = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
  curl_close($ch);
  if ($body === false || $pc !== 200) return null;
  $code = 200;
  foreach ($hdr as $h) { if (stripos($h,'X-Upstream-Status:')===0) $code=(int)trim(substr($h,18)); }
  return [$body, $code];
}

function pdd_translate($text) {
  if (!$text || mb_strlen($text) < 2) return $text;
  $text = mb_substr($text, 0, 400); // лимит бесплатного API
  $apiUrl = 'https://api.mymemory.translated.net/get?q='.urlencode($text).'&langpair=zh-CN|ru';
  $ch = curl_init($apiUrl);
  curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 8,
    CURLOPT_SSL_VERIFYPEER => false, CURLOPT_USERAGENT => 'ITC/1.0',
  ]);
  $res = curl_exec($ch); curl_close($ch);
  if (!$res) return $text;
  $data = json_decode($res, true);
  $t = $data['responseData']['translatedText'] ?? '';
  return ($t && ($data['responseStatus'] ?? 0) == 200) ? $t : $text;
}

// ===== DeepSeek AI — умное обогащение карточки (перевод + нормализация названия) =====
// Ключ добавляется в config.php:  define('DEEPSEEK_API_KEY','sk-xxxx');
// Если ключа нет или API упал — вызывающий код откатывается на pdd_translate (MyMemory).
function ds_deepseek_enrich($name_zh, $desc_zh = '') {
  if (!defined('DEEPSEEK_API_KEY') || !DEEPSEEK_API_KEY) return null;
  $system = "Ты контент-менеджер российского мебельного маркетплейса ИТК. Тебе дают сырые данные товара с китайской площадки Pinduoduo. Сделай чистую карточку для русского покупателя.\n".
    "Верни СТРОГО валидный JSON (json_object) без markdown, поля:\n".
    "{\"name_ru\":\"короткое продающее название на русском в стиле Wildberries/Ozon (тип товара + материал + стиль + ключевая особенность), без иероглифов и мусора\",".
    "\"description_ru\":\"2-4 предложения продающего описания на русском, только то что следует из исходника, без выдумок\",".
    "\"category\":\"одна из: кровать, диван, шкаф, комод, стол, стул, кресло, тумба, полка, зеркало, светильник, ковёр, матрас, текстиль, декор, кухня, детская, прочее\"}\n".
    "Правила: НЕ переводи дословно — переосмысли по-русски как живой копирайтер. Убирай китайский рекламный мусор (爆款, 包邮, 工厂直销). Если данных мало — короче, ничего не выдумывай.";
  $user = "Название (zh): {$name_zh}\nОписание (zh): {$desc_zh}";
  $payload = json_encode([
    'model'=>'deepseek-v4-flash',
    'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$user]],
    'response_format'=>['type'=>'json_object'],
    'temperature'=>0.3, 'max_tokens'=>900, 'stream'=>false,
  ], JSON_UNESCAPED_UNICODE);
  $ch = curl_init('https://api.deepseek.com/chat/completions');
  curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true,
    CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.DEEPSEEK_API_KEY],
    CURLOPT_POSTFIELDS=>$payload, CURLOPT_TIMEOUT=>40, CURLOPT_CONNECTTIMEOUT=>10,
    CURLOPT_SSL_VERIFYPEER=>false,
  ]);
  $raw=curl_exec($ch); $http=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
  if($raw===false || $http!==200){ error_log("DeepSeek fail http=$http"); return null; }
  $resp=json_decode($raw,true);
  $content=$resp['choices'][0]['message']['content'] ?? '';
  if($content==='') return null;
  $content=preg_replace('/^```(?:json)?|```$/m','',trim($content));
  $data=json_decode(trim($content),true);
  if(!is_array($data) || empty($data['name_ru'])) return null;
  return [
    'name'=>trim($data['name_ru']),
    'description'=>trim($data['description_ru'] ?? ''),
    'category'=>trim($data['category'] ?? ''),
  ];
}

/* ===== ИИ-РАСКЛАДКА ПО КАТЕГОРИЯМ =====
   Словарь ключевых слов разбирает основную массу, но остаток («Прочее»)
   без человека не разложить: там названия, где нужного слова просто нет.
   Отдаём такие пачками ИИ и просим ВЫБРАТЬ из уже существующих категорий —
   выдумывать новые ему запрещено, иначе справочник расползётся.
   Движок: сначала YandexGPT (оплачен), если недоступен — DeepSeek. */
function itc_ai_cat_batch($rows, $cats) {
  if (!$rows || !$cats) return [];
  $list = []; $n = 0;
  foreach ($rows as $r) {
    $n++;
    /* ТОЛЬКО НАЗВАНИЕ. Проба боевой пачки показала: на коротких запросах Яндекс
       отвечает всегда и мгновенно, а с описаниями запрос раздувался вчетверо и
       модель замолкала. Название и так несёт тип товара — этого хватает. */
    $list[] = $n.'. '.mb_substr(trim((string)($r['name'] ?? '')), 0, 140);
  }
  $sys = "Ты товаровед интернет-магазина товаров для дома. Тебе дают пронумерованный список товаров.\n".
    "Для КАЖДОГО номера выбери ОДНУ категорию строго из предложенного списка — по смыслу названия и описания.\n".
    "Новых категорий НЕ придумывай. Если ни одна не подходит — верни \"Прочее\".\n".
    "Ответ — СТРОГО валидный JSON без markdown вида {\"1\":\"Категория\",\"2\":\"Категория\"}, по одному ключу на каждый номер.";
  $user = "Категории:\n- ".implode("\n- ", $cats)."\n\nТовары:\n".implode("\n", $list);

  $txt = null;
  if (function_exists('yx_gpt') && function_exists('yx_ready') && yx_ready()) {
    $txt = yx_gpt($sys, $user, 0.1, 900);
    /* Пустой ответ — обычно упёрлись в ограничение частоты запросов. Ждём
       полторы секунды и пробуем ещё раз: почти всегда со второго раза идёт. */
    if (!is_string($txt) || trim($txt) === '') { usleep(1500000); $txt = yx_gpt($sys, $user, 0.1, 900); }
  }
  static $dsDead = false;   // 402 «Insufficient Balance» — второй раз не ходим
  if ((!is_string($txt) || trim($txt) === '') && !$dsDead && defined('DEEPSEEK_API_KEY') && DEEPSEEK_API_KEY) {
    $payload = json_encode([
      'model'=>'deepseek-v4-flash',
      'messages'=>[['role'=>'system','content'=>$sys],['role'=>'user','content'=>$user]],
      'response_format'=>['type'=>'json_object'],
      'temperature'=>0.1, 'max_tokens'=>900, 'stream'=>false,
    ], JSON_UNESCAPED_UNICODE);
    $ch = curl_init('https://api.deepseek.com/chat/completions');
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true,
      CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.DEEPSEEK_API_KEY],
      CURLOPT_POSTFIELDS=>$payload, CURLOPT_TIMEOUT=>25, CURLOPT_CONNECTTIMEOUT=>8,
      CURLOPT_SSL_VERIFYPEER=>false,
    ]);
    $raw = curl_exec($ch); $http = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    if ($http === 402 || $http === 401 || $http === 403) $dsDead = true;
    if ($raw !== false && $http === 200) {
      $resp = json_decode($raw, true);
      $txt = $resp['choices'][0]['message']['content'] ?? '';
    }
  }
  if (!is_string($txt) || trim($txt) === '') return [];
  $txt = preg_replace('/^```(?:json)?|```$/m', '', trim($txt));
  if (preg_match('/\{.*\}/s', $txt, $m)) $txt = $m[0];
  $data = json_decode($txt, true);
  if (!is_array($data)) {
    /* Ответ пришёл, но не строгим JSON — например с пояснением вокруг или
       обрезанный. Вытаскиваем пары «номер: категория» вручную, чтобы не
       выбрасывать всю пачку из-за одной лишней запятой. */
    $data = [];
    if (preg_match_all('/"(\d{1,3})"\s*:\s*"([^"]{1,60})"/u', $txt, $mm, PREG_SET_ORDER)) {
      foreach ($mm as $one) $data[$one[1]] = $one[2];
    }
    if (!$data) return [];
  }

  // Ответ сверяем со справочником: чего нет в списке — не принимаем
  $allow = []; foreach ($cats as $c) $allow[mb_strtolower($c)] = $c;
  $out = []; $i = 0;
  foreach ($rows as $r) {
    $i++;
    $v = $data[(string)$i] ?? ($data[$i] ?? '');
    $v = trim((string)$v); if ($v === '') continue;
    $k = mb_strtolower($v);
    if (isset($allow[$k])) $out[$r['id']] = $allow[$k];
  }
  return $out;
}

/* ===== ФОНОВОЕ ЗАДАНИЕ ИИ-РАСКЛАДКИ =====
   Телефон не может крутить многочасовой цикл: свернул приложение — браузер
   усыпляет вкладку, и всё встаёт («нет связи с сервером»). Поэтому работу
   выполняет СЕРВЕР, а телефон только запускает и подсматривает, сколько сделано.
   Двигают задание двое: cron по расписанию и — пока приложение открыто —
   сам телефон, чтобы шло быстрее. Блокировка не даёт им топтаться друг по другу. */
/* ЖУРНАЛ ПОИСКА ПОКУПАТЕЛЕЙ.
   Самый честный источник «чего нам не хватает»: что люди ищут в нашем каталоге
   и с чем уходят ни с чем. Пишем сам запрос, приведённый к нижнему регистру
   ключ для группировки и сколько нашлось. Таблицу создаём один раз за запрос. */
function itc_search_log($q, $found) {
  static $ready = false;
  $q = trim(mb_substr((string)$q, 0, 120));
  if ($q === '' || mb_strlen($q) < 2) return;
  try {
    if (!$ready) {
      db()->query("CREATE TABLE IF NOT EXISTS search_log (
        id INT AUTO_INCREMENT PRIMARY KEY,
        q VARCHAR(160) NOT NULL,
        qn VARCHAR(160) NOT NULL,
        found INT NOT NULL DEFAULT 0,
        created_at DATETIME NOT NULL,
        INDEX idx_qn (qn), INDEX idx_dt (created_at)
      ) DEFAULT CHARSET=utf8mb4");
      $ready = true;
    }
    db()->prepare('INSERT INTO search_log (q,qn,found,created_at) VALUES (?,?,?,NOW())')
        ->execute([$q, mb_strtolower($q), (int)$found]);
  } catch (Exception $e) {}
}
function itc_ai_job_table() {
  try {
    db()->query("CREATE TABLE IF NOT EXISTS itc_ai_job (
      id TINYINT NOT NULL PRIMARY KEY,
      status VARCHAR(16) NOT NULL DEFAULT 'idle',
      scope VARCHAR(8) NOT NULL DEFAULT 'other',
      total INT NOT NULL DEFAULT 0,
      done INT NOT NULL DEFAULT 0,
      moved INT NOT NULL DEFAULT 0,
      msg VARCHAR(255) NOT NULL DEFAULT '',
      lock_at DATETIME NULL,
      started_at DATETIME NULL,
      updated_at DATETIME NULL
    ) DEFAULT CHARSET=utf8mb4");
  } catch (Exception $e) {}
  try { db()->query('ALTER TABLE products ADD COLUMN ai_cat_at DATETIME NULL'); } catch (Exception $e) {}
  /* watch=1 — «дежурство»: закончив разбор, задание не завершается, а остаётся
     ждать новые карточки. Cron будет подбирать их сам, руками ничего не жать. */
  try { db()->query('ALTER TABLE itc_ai_job ADD COLUMN watch TINYINT NOT NULL DEFAULT 0'); } catch (Exception $e) {}
  /* Сколько заходов подряд не дали ни одной разобранной карточки. Одиночная
     заминка ИИ не должна гасить задание — крон просто попробует через 5 минут. */
  try { db()->query('ALTER TABLE itc_ai_job ADD COLUMN fail_runs INT NOT NULL DEFAULT 0'); } catch (Exception $e) {}
  try { db()->query("INSERT IGNORE INTO itc_ai_job (id,status) VALUES (1,'idle')"); } catch (Exception $e) {}
}
function itc_ai_job_get() {
  itc_ai_job_table();
  try { $q = db()->query('SELECT * FROM itc_ai_job WHERE id=1'); $r = $q->fetch(); if ($r) return $r; }
  catch (Exception $e) {}
  return ['status'=>'idle','scope'=>'other','total'=>0,'done'=>0,'moved'=>0,'msg'=>'','started_at'=>null,'updated_at'=>null];
}
function itc_ai_job_cond($scope) {
  return ($scope === 'all') ? 'ai_cat_at IS NULL'
                            : "(cat IS NULL OR cat='' OR cat='Прочее') AND ai_cat_at IS NULL";
}
function itc_ai_job_left($scope) {
  try { return (int)db()->query('SELECT COUNT(*) FROM products WHERE '.itc_ai_job_cond($scope))->fetchColumn(); }
  catch (Exception $e) { return 0; }
}
/* Один заход работы. $budget — сколько секунд можно жевать. Возвращает
   [обработано, переложено, осталось, сообщение]. */
function itc_ai_job_run($budget = 200) {
  $job = itc_ai_job_get();
  $st0 = (string)($job['status'] ?? '');
  if ($st0 !== 'running' && $st0 !== 'watch') return [0, 0, 0, 'Задание не запущено'];
  $watch = !empty($job['watch']);

  // Замок: если кто-то уже работает и метка свежее трёх минут — не мешаем
  try {
    $busy = db()->query("SELECT COUNT(*) FROM itc_ai_job WHERE id=1 AND lock_at IS NOT NULL AND lock_at > (NOW() - INTERVAL 90 SECOND)")->fetchColumn();
    if ((int)$busy > 0) return [0, 0, itc_ai_job_left($job['scope']), 'Занято другим заходом'];
    db()->query('UPDATE itc_ai_job SET lock_at=NOW() WHERE id=1');
  } catch (Exception $e) {}

  $scope = ($job['scope'] === 'all') ? 'all' : 'other';
  $cats = [];
  try { foreach (db()->query('SELECT name FROM categories ORDER BY sort, name')->fetchAll() as $c) { $n = trim((string)$c['name']); if ($n !== '' && $n !== 'Прочее') $cats[] = $n; } }
  catch (Exception $e) {}
  if (!$cats) {
    try { db()->query("UPDATE itc_ai_job SET status='error', msg='Список категорий пуст', lock_at=NULL, updated_at=NOW() WHERE id=1"); } catch (Exception $e) {}
    return [0, 0, 0, 'Список категорий пуст'];
  }
  $ask = $cats; $ask[] = 'Прочее';

  $t0 = time(); $proc = 0; $movedTotal = 0; $fails = 0; $msg = '';
  $cond = itc_ai_job_cond($scope);
  $upd  = db()->prepare('UPDATE products SET cat=?, ai_cat_at=NOW() WHERE id=?');
  $mark = db()->prepare('UPDATE products SET ai_cat_at=NOW() WHERE id=?');
  while ((time() - $t0) < $budget) {
    $rows = [];
    try {
      $q = db()->prepare("SELECT id, name, cat, LEFT(COALESCE(descr,''),300) dsc FROM products WHERE $cond ORDER BY id LIMIT 8");
      $q->execute(); $rows = $q->fetchAll();
    } catch (Exception $e) { $msg = 'Ошибка выборки'; break; }
    if (!$rows) { $msg = $watch ? 'Новых карточек нет' : 'Готово'; break; }

    $res = itc_ai_cat_batch($rows, $ask);
    /* Пачка не разобралась целиком — НЕ помечаем эти карточки: иначе один
       сбой связи молча съедал бы 8 товаров, и вернуться к ним было бы уже
       нельзя. Просто считаем неудачу и пробуем дальше. */
    if (!$res) { $fails++; if ($fails >= 3) { $msg = 'ИИ не отвечает — откройте itc_ai_ping и посмотрите причину'; break; } continue; }
    $fails = 0;
    $batchMoved = 0;
    foreach ($rows as $r) {
      $c = $res[$r['id']] ?? '';
      if ($c !== '' && $c !== 'Прочее' && $c !== (string)($r['cat'] ?? '')) { $upd->execute([$c, $r['id']]); $batchMoved++; }
      else { $mark->execute([$r['id']]); }
      $proc++;
    }
    $movedTotal += $batchMoved;
    usleep(300000);   // передышка между пачками — бережём лимит частоты запросов
    try { db()->prepare('UPDATE itc_ai_job SET done=done+?, moved=moved+?, lock_at=NOW(), updated_at=NOW() WHERE id=1')->execute([count($rows), $batchMoved]); } catch (Exception $e) {}
    // Три пустых ответа подряд — ИИ недоступен, дальше жечь запросы незачем
  }
  $left = itc_ai_job_left($scope);
  /* Пока в очереди что-то есть — это РАБОТА (running), даже при включённом
     дежурстве. Иначе экран показывал «ИИ дежурит» посреди разбора девяти тысяч
     карточек, и выглядело так, будто он сам выключился. Дежурство (watch) —
     это состояние «разбирать нечего, жду новые». */
  $failRuns = (int)($job['fail_runs'] ?? 0);
  $failRuns = ($proc > 0) ? 0 : ($failRuns + (($fails >= 3) ? 1 : 0));
  $st = 'running';
  if ($left <= 0) { $st = $watch ? 'watch' : 'done'; $msg = $msg ?: ($watch ? 'Дежурим, ждём новые карточки' : 'Готово'); }
  elseif ($fails >= 3) {
    /* Заход впустую. Пока таких подряд меньше пяти — остаёмся в работе, крон
       вернётся через пять минут. Только после пяти признаём, что ИИ лежит. */
    if ($failRuns >= 5) { $st = $watch ? 'watch' : 'error'; $msg = 'ИИ не отвечает — откройте itc_ai_ping и посмотрите причину'; }
    else { $st = 'running'; $msg = 'ИИ не ответил, повторим через несколько минут (попытка '.$failRuns.' из 5)'; }
  }
  try { db()->prepare('UPDATE itc_ai_job SET status=?, msg=?, fail_runs=?, lock_at=NULL, updated_at=NOW() WHERE id=1')->execute([$st, mb_substr($msg, 0, 200), $failRuns]); } catch (Exception $e) {}
  return [$proc, $movedTotal, $left, $msg];
}

// ===== Генерация русских поисковых слов для карточки (Yandex → DeepSeek) =====
// По названию/категории/описанию ИИ придумывает фразы, которые покупатель
// реально набирает в поиске. Основной движок — YandexGPT (оплачен, работает),
// DeepSeek — запасной (когда пополнят баланс). Возвращает «слово, фраза…» или ''.
function ds_gen_search_tags($name, $desc = '', $cat = '') {
  $name = trim((string)$name); if ($name === '') return '';

  // Чистка списка фраз в общую строку
  $clean = function($arr){
    $out = [];
    foreach ($arr as $t) {
      $t = trim(mb_strtolower((string)$t), " \t\r\n\"'«»-•*.)0123456789");
      if ($t !== '' && mb_strlen($t) <= 40) $out[] = $t;
    }
    return implode(', ', array_slice(array_values(array_unique(array_filter($out))), 0, 20));
  };

  // ── 1) YandexGPT — основной движок ──
  if (function_exists('yx_gpt') && function_exists('yx_ready') && yx_ready()) {
    $sys = "Ты SEO-специалист российского мебельного маркетплейса. По названию, категории и описанию товара напиши поисковые слова и фразы, которые русский покупатель реально набирает в поиске этого товара.\n".
      "ПРАВИЛА:\n".
      "- 10-18 фраз, каждая с новой строки.\n".
      "- Включи синонимы (диван/софа/тахта, шкаф/гардероб, стол/столик), тип и назначение (диван в гостиную, стол компьютерный, кровать двуспальная), форму и особенности (угловой, раскладной, на колёсах, с ящиками), материал и цвет если ясен.\n".
      "- Всё на русском, строчными буквами, без иероглифов, без брендового и рекламного мусора.\n".
      "- Не выдумывай свойства, которых у товара быть не может.\n".
      "- Верни ТОЛЬКО список фраз, по одной в строке, без нумерации, кавычек и заголовков.";
    $user = "Название: {$name}\nКатегория: {$cat}\nОписание: ".mb_substr((string)$desc, 0, 600);
    $txt = yx_gpt($sys, $user, 0.5, 500);
    if (is_string($txt) && trim($txt) !== '' && !(function_exists('has_cjk') && has_cjk($txt))) {
      $res = $clean(preg_split('/[\r\n,;]+/u', $txt));
      if ($res !== '') return $res;
    }
  }

  // ── 2) DeepSeek — запасной (когда снова будет баланс) ──
  if (defined('DEEPSEEK_API_KEY') && DEEPSEEK_API_KEY) {
    $system = "Ты SEO-специалист российского мебельного маркетплейса. По названию, категории и описанию товара придумай поисковые слова и фразы, которые русский покупатель реально набирает в поиске этого товара.\n".
      "Верни СТРОГО валидный JSON без markdown: {\"tags\":[\"слово\",\"фраза из 2-3 слов\", ...]}\n".
      "Правила: 10-18 фраз. Синонимы (диван/софа/тахта, шкаф/гардероб), тип и назначение, форма и особенности, материал и цвет. Всё на русском, строчными, без иероглифов и мусора. Не выдумывай.";
    $user = "Название: {$name}\nКатегория: {$cat}\nОписание: ".mb_substr((string)$desc, 0, 600);
    $payload = json_encode([
      'model'=>'deepseek-v4-flash',
      'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$user]],
      'response_format'=>['type'=>'json_object'],
      'temperature'=>0.5, 'max_tokens'=>500, 'stream'=>false,
    ], JSON_UNESCAPED_UNICODE);
    $ch = curl_init('https://api.deepseek.com/chat/completions');
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true,
      CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.DEEPSEEK_API_KEY],
      CURLOPT_POSTFIELDS=>$payload, CURLOPT_TIMEOUT=>40, CURLOPT_CONNECTTIMEOUT=>10,
      CURLOPT_SSL_VERIFYPEER=>false,
    ]);
    $raw=curl_exec($ch); $http=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
    if($raw!==false && $http===200){
      $resp=json_decode($raw,true);
      $content=$resp['choices'][0]['message']['content'] ?? '';
      if($content!==''){
        $content=preg_replace('/^```(?:json)?|```$/m','',trim($content));
        $data=json_decode(trim($content),true);
        $tags=(is_array($data)&&isset($data['tags'])&&is_array($data['tags']))?$data['tags']:[];
        $res=$clean($tags);
        if($res!=='') return $res;
      }
    }
  }

  return '';
}

// Коэффициент упаковки (коробка ÷ изделие в сборе) по типу мебели.
// Столы/зеркала едут очень плоско, диваны/кресла — почти как есть.
// Значения — стартовые, их легко подправить.
function ob_kd_factor($text) {
  $t = mb_strtolower((string)$text);
  // мягкое / собранное — едет объёмным
  if (preg_match('/(диван|софа|тахта|кушетк|кресл|пуф|банкетк|матрас|матрац|оттоманк)/u', $t)) return 0.85;
  // электроника внутри — собранная
  if (preg_match('/(подсветк|зарядк|умн(ый|ая|ое)|led|светодиод|динамик|колонк)/u', $t)) return 0.90;
  // очень плоская упаковка
  if (preg_match('/(стол|столеш|зеркал|трюмо|полк|стеллаж|этажерк|картин|панел|дверь|столик)/u', $t)) return 0.28;
  // стулья, табуреты, вешалки, обувницы — компактно
  if (preg_match('/(стул|табурет|вешалк|обувниц|обув|подставк)/u', $t)) return 0.35;
  // корпусная разборная (шкафы, комоды, тумбы, кровати-каркасы)
  if (preg_match('/(шкаф|гардероб|шифоньер|комод|тумб|пенал|витрин|буфет|кровать|каркас)/u', $t)) return 0.40;
  return 0.38; // общий стандарт
}

// Плотность упаковки — кг на 1 м³ коробки. ГЛАВНОЕ — материал: проволока и
// пластик почти невесомы, ДСП/дерево/стекло — тяжёлые. Если материал не
// распознан — берём по типу товара. Значения легко подправить.
function ob_weight_density($text) {
  $t = mb_strtolower((string)$text);
  // --- по материалу (приоритетнее типа) ---
  // лёгкие / «воздушные»
  if (preg_match('/(проволок|сетчат|сетка|сетки|решётчат|решетчат)/u', $t)) return 55;   // проволока/сетка
  if (preg_match('/(пластик|пластмасс|пвх|полипроп|полиэтил|акрил|пэт)/u', $t))          return 45;
  if (preg_match('/(ротанг|бамбук|плетён|плетен|лоза)/u', $t))                            return 65;
  if (preg_match('/(ткан|текстиль|поролон|губк|войлок|велюр|бархат|флис|нейлон|оксфорд)/u', $t)) return 55;
  // тяжёлые
  if (preg_match('/(стекл|зеркальн|мрамор|камен)/u', $t))                                 return 340;
  if (preg_match('/(дсп|лдсп|мдф|дерев|деревян|массив|фанер|дуб|сосн|берёз|берез)/u', $t)) return 260;
  if (preg_match('/(металл|сталь|железн|чугун|алюмин|нержав)/u', $t))                     return 180; // сплошной металл (не проволока)
  // --- по типу товара (если материал не распознан) ---
  if (preg_match('/(матрас|матрац)/u', $t)) return 70;
  if (preg_match('/(диван|софа|тахта|кушетк|кресл|пуф|банкетк|оттоманк)/u', $t)) return 55;
  if (preg_match('/(шкаф|гардероб|шифоньер|комод|тумб|витрин|буфет|пенал)/u', $t)) return 240;
  if (preg_match('/(стол|столеш|полк|стеллаж|этажерк|зеркал|трюмо)/u', $t)) return 200;
  if (preg_match('/(стул|табурет|вешалк)/u', $t)) return 160;
  return 150;
}

// ===== Оценка упаковки (объём + вес) для морского фрахта =====
// Объём: если габариты в названии (100×50×75) — (Д×Ш×В)×KD (плоская упаковка).
// Вес: объём коробки × плотность по типу товара. И то, и другое считаем САМИ —
// ИИ и объём завышал (давал сборку), и вес угадывал плохо. ИИ нужен ТОЛЬКО
// когда габаритов в названии нет (прикинуть объём). Возвращает [vol,wt] или null.
function ob_ai_estimate_size($name, $cat = '', $props = '', $title = '') {
  $name = trim((string)$name);
  $text = $title.' '.$cat.' '.$name;
  $KD = ob_kd_factor($text);
  $dens = ob_weight_density($text.' '.$props);

  // 1) Объём из габаритов в названии — детерминированно, без ИИ
  $dims = function_exists('ob_dims_from_name') ? ob_dims_from_name(['name_ru'=>$name]) : [];
  if (count($dims) === 3) {
    $asm = ((float)$dims[0]/100) * ((float)$dims[1]/100) * ((float)$dims[2]/100);
    if ($asm > 0.0001) {
      $vol = round($asm * $KD, 4);
      $wt  = round($vol * $dens, 1);
      if ($vol >= 0.001 && $vol <= 5 && $wt >= 0.1) return ['volume_m3'=>$vol, 'weight_kg'=>$wt];
    }
  }

  // 2) Габаритов нет — объём прикинет ИИ (Яндекс), вес считаем по плотности
  if (!(function_exists('yx_gpt') && function_exists('yx_ready') && yx_ready())) return null;
  $sys = "Ты логист по морским перевозкам мебели из Китая. По типу товара оцени объём УПАКОВКИ (коробки) в м³ за ОДНУ штуку.\n".
    "КРИТИЧЕСКИ ВАЖНО: верни объём КОРОБКИ, а НЕ собранного изделия. Плоско-упаковываемая мебель (столы, стеллажи, шкафы, кровати, полки) едет РАЗОБРАННОЙ — объём коробки примерно 30-40% от объёма в сборе. Мягкая (диваны, кресла) и с электроникой — едет собранной.\n".
    "Верни СТРОГО валидный JSON без markdown: {\"volume_m3\": число}.";
  $user = "Товар: {$title}\nВариант: {$name}\nКатегория: {$cat}\nХарактеристики:\n".mb_substr((string)$props, 0, 600);
  $txt = yx_gpt($sys, $user, 0.3, 200);
  if (!is_string($txt) || trim($txt) === '') return null;
  $txt = preg_replace('/^```(?:json)?|```$/m', '', trim($txt));
  if (preg_match('/\{.*\}/s', $txt, $m)) $txt = $m[0];
  $data = json_decode($txt, true);
  $vol = is_array($data) ? round((float)($data['volume_m3'] ?? 0), 4) : 0;
  if ($vol < 0.001 || $vol > 5) return null;
  $wt = round($vol * $dens, 1);
  if ($wt < 0.1) return null;
  return ['volume_m3'=>$vol, 'weight_kg'=>$wt];
}

// ===== Универсальный AI-перевод поля карточки (DeepSeek) =====
// $kind: name | description | review | specs | plain
// Возвращает строку перевода или null (вызывающий откатывается на pdd_translate).
/* ===== ЗАЩИТА ОТ ОТКАЗОВ ИИ =====
   В каталоге нашлись карточки с названием «Я не могу обсуждать эту тему.
   Давайте поговорим о чём-нибудь ещё.» — это модель отказалась переводить, а мы
   записали её отговорку прямо в название товара. Ответ ИИ нельзя класть в
   карточку не глядя: сначала проверяем, что это перевод, а не разговор с нами. */
function itc_bad_ai_text($t) {
  $t = trim((string)$t);
  if ($t === '' || mb_strlen($t) < 3) return true;
  $l = mb_strtolower($t);
  $marks = [
    'я не могу', 'не могу обсуждать', 'не могу помочь', 'не могу выполнить',
    'не могу ответить', 'давайте поговорим', 'давайте обсудим что', 'поговорим о чём-нибудь',
    'как языковая модель', 'как искусственный интеллект', 'я — языковая модель',
    'извините, но', 'прошу прощения', 'к сожалению, я',
    'i cannot', "i can't", "i'm sorry", 'i am sorry', 'as an ai', 'as a language model',
    'unable to assist', 'cannot assist',
  ];
  foreach ($marks as $m) { if (mb_strpos($l, $m) !== false) return true; }
  return false;
}
/* Найти карточки, в названия которых попал отказ. Возвращает строки products. */
function itc_find_bad_names($limit = 200) {
  $like = ['%не могу%', '%Давайте поговорим%', '%языковая модель%', '%I cannot%', '%I am sorry%', '%As an AI%'];
  $out = []; $seen = [];
  foreach ($like as $lk) {
    try {
      $q = db()->prepare('SELECT id, name FROM products WHERE name LIKE ? LIMIT '.(int)$limit);
      $q->execute([$lk]);
      foreach ($q->fetchAll() as $r) {
        if (isset($seen[$r['id']])) continue;
        if (!itc_bad_ai_text($r['name'])) continue;   // «не могу» бывает и в живом тексте
        $seen[$r['id']] = 1; $out[] = $r;
      }
    } catch (Exception $e) {}
  }
  return $out;
}
/* Исходное китайское название для товара: по ссылке на 1688 находим номер
   предложения, а по нему — заголовок в нашем кэше выгрузки ob_item. */
function itc_source_title_cn($product_id) {
  try {
    $q = db()->prepare('SELECT source_url FROM ds_products WHERE product_id=? LIMIT 1');
    $q->execute([$product_id]);
    $url = (string)$q->fetchColumn();
    if ($url === '' || !preg_match('/offer\/(\d+)/', $url, $m)) return '';
    if (!function_exists('ob_row')) return '';
    $it = ob_row('SELECT title_cn FROM ob_item WHERE num_iid=?', [$m[1]]);
    return $it ? trim((string)($it['title_cn'] ?? '')) : '';
  } catch (Exception $e) { return ''; }
}

// ===== №314: ПЕРЕВОД ВСЕГО КАТАЛОГА — задание с прогрессом на сервере =====
// Решение Алексея 07.10.2026: заново всё (названия, описания, варианты,
// характеристики), ручные правки тоже перезаписываются.
// Прогресс — в api/.retr_state.json: связь оборвалась — продолжаем с того же
// товара. Работу двигают короткие шаги ~35 сек: кнопка в приложении (пока
// экран открыт) и, по желанию, расписание (retr_tick&key=itc-tr-0710).
// Два шага одновременно не идут — замок api/.retr_lock.
function retr_state_path() { return __DIR__ . '/.retr_state.json'; }
function retr_state() {
  // №315: читаем основной файл; если он пуст или битый — запасной (.bak).
  $st = json_decode((string)@file_get_contents(retr_state_path()), true);
  if (!is_array($st)) $st = json_decode((string)@file_get_contents(retr_state_path() . '.bak'), true);
  if (!is_array($st)) $st = [];
  return $st + ['running' => 0, 'after' => '', 'ok' => 0, 'err' => 0, 'done' => 0,
                'started' => '', 'updated' => '', 'finished' => '', 'last' => [], 'msg' => ''];
}
// №315: запись без «пустого окна». Раньше file_put_contents сначала обнулял
// файл, и приложение, заглянув в этот миг, видело «0 из 3577» и кнопку
// «Запустить». Теперь пишем во временный файл и подменяем одним движением.
// Плюс: битый текст в названии больше не может обнулить прогресс.
function retr_save($st) {
  $st['updated'] = date('Y-m-d H:i:s');
  $j = json_encode($st, JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE | JSON_PARTIAL_OUTPUT_ON_ERROR);
  if (!is_string($j) || $j === '') return $st;              // не пишем пустоту поверх прогресса
  $p = retr_state_path();
  $tmp = $p . '.tmp' . getmypid();
  if (@file_put_contents($tmp, $j) !== false) {
    @copy($p, $p . '.bak');
    if (!@rename($tmp, $p)) { @unlink($tmp); @file_put_contents($p, $j); }
  }
  return $st;
}
// №316: отметка у самого товара: ob_item.tr_ds = 0 ждёт, 1 переведён, 2 ошибка.
// Счётчики берём из базы — файл может пропасть, база нет.
function retr_col() {
  static $ok = false; if ($ok) return; $ok = true;
  try { ob_pdo()->exec("ALTER TABLE ob_item ADD COLUMN tr_ds TINYINT NOT NULL DEFAULT 0"); } catch (Throwable $e) {}
}
function retr_total() {
  $r = ob_row("SELECT COUNT(*) c FROM ob_item WHERE title_cn IS NOT NULL AND title_cn<>''");
  return (int)($r['c'] ?? 0);
}
function retr_counts() {
  retr_col();
  $r = ob_row("SELECT SUM(tr_ds=1) ok, SUM(tr_ds=2) er FROM ob_item WHERE title_cn IS NOT NULL AND title_cn<>''");
  return [(int)($r['ok'] ?? 0), (int)($r['er'] ?? 0)];
}
function retr_tick($budget = 35) {
  $st = retr_state();
  // №318: после полного прохода — «дежурство»: расписание подбирает новые
  // карточки, которые при заведении перевёл запасной движок (tr_ds=0).
  // Пауза (кнопка) останавливает и это.
  $duty = empty($st['running']) && !empty($st['finished']) && empty($st['paused']);
  if (empty($st['running']) && !$duty) return $st;
  if ($duty) {
    retr_col();
    $q = ob_row("SELECT 1 x FROM ob_item WHERE title_cn IS NOT NULL AND title_cn<>'' AND tr_ds IN (0,3) LIMIT 1");
    if (!$q) return $st;                       // очередь пуста — ничего не делаем
  }
  $lk = @fopen(__DIR__ . '/.retr_lock', 'c');
  if (!$lk || !flock($lk, LOCK_EX | LOCK_NB)) { $st['busy'] = 1; return $st; }
  @set_time_limit($budget + 60);
  @ignore_user_abort(true);

  if (!function_exists('ob_translate_item') || !function_exists('yx_ds_model')) {
    $st['running'] = 0; $st['msg'] = 'Не подключены ob_translate.php или ob_yandex.php';
    flock($lk, LOCK_UN); return retr_save($st);
  }
  if (yx_ds_model() === '') {
    // №317: DeepSeek молчит — НЕ останавливаемся. Задание остаётся включённым,
    // расписание раз в минуту пробует снова и само продолжит, когда DeepSeek
    // ответит. По-старому (YandexGPT) каталог не переводим.
    $st['msg'] = 'Ждём DeepSeek: ' . yx_ds_err(); $st['wait'] = 1;
    flock($lk, LOCK_UN); return retr_save($st);
  }
  $st['msg'] = ''; $st['wait'] = 0;
  $t0 = microtime(true);
  while (microtime(true) - $t0 < $budget) {
    retr_col();
    $it = ob_row("SELECT num_iid FROM ob_item WHERE title_cn IS NOT NULL AND title_cn<>'' AND tr_ds IN (0,3) ORDER BY num_iid LIMIT 1");
    // DeepSeek отвалился посреди шага (2 сбоя подряд) — не портим товары
    // запасным переводом: останавливаем шаг, следующий попробует снова
    if (!empty($GLOBALS['yx_ds_dead'])) { $st['msg'] = 'Ждём DeepSeek: ' . yx_ds_err(); $st['wait'] = 1; break; }
    if (!$it) { if (!empty($st['running'])) { $st['running'] = 0; $st['finished'] = date('Y-m-d H:i:s'); } break; }
    $iid = (string)$it['num_iid'];
    try {
      $r = ob_translate_item($iid, ['force' => true]);
      $good = !empty($r['ok']) && trim((string)$r['title_ru']) !== '';
      if (!empty($GLOBALS['yx_ds_dead'])) {
        // Товар частично переведён запасным движком — не засчитываем,
        // он останется в очереди и переведётся DeepSeek позже
        $st['msg'] = 'Ждём DeepSeek: ' . yx_ds_err(); $st['wait'] = 1;
        break;
      }
      // №320: «переведён DeepSeek» (1) — только если ни одна часть не ушла
      // в запасной движок. Частично — в «ошибки» (2): «Повторить ошибки»
      // переведёт их DeepSeek заново, а шаг не крутится на одном товаре.
      $partial = $good && !empty($GLOBALS['yx_ds_fallback']);
      ob_exec("UPDATE ob_item SET tr_ds=? WHERE num_iid=?", [($good && !$partial) ? 1 : 2, $iid]);
      if ($partial) {
        $st['err']++;
        array_unshift($st['last'], '✗ частично запасным движком, повторим: ' . mb_substr((string)$r['title_ru'], 0, 60));
      } elseif ($good) {
        $st['ok']++;
        array_unshift($st['last'], mb_substr((string)$r['title_ru'], 0, 90));
      } else {
        $st['err']++;
        array_unshift($st['last'], '✗ ' . $iid . ': ' . (string)($r['error'] ?? 'название не переведено'));
      }
    } catch (Throwable $e) {
      $st['err']++;
      ob_exec("UPDATE ob_item SET tr_ds=2 WHERE num_iid=?", [$iid]);
      array_unshift($st['last'], '✗ ' . $iid . ': ' . $e->getMessage());
    }
    $st['last'] = array_slice($st['last'], 0, 8);
    $st['after'] = $iid; $st['done']++;
    $st = retr_save($st);                    // после каждого товара — обрыв ничего не теряет
  }
  $st = retr_save($st);
  flock($lk, LOCK_UN); fclose($lk);
  return $st;
}
function retr_out($st) {
  $st['total'] = retr_total();
  list($ok, $er) = retr_counts();
  $st['ok'] = $ok; $st['err'] = $er; $st['done'] = $ok + $er;   // правда — из базы
  if ($st['done'] >= $st['total'] && $st['total'] > 0 && empty($st['running'])) $st['finished'] = $st['finished'] ?: 'да';
  unset($st['busy_x']);
  return $st;
}

function ai_translate_field($text, $kind='plain', $ctx='') {
  $text = trim((string)$text);
  if ($text==='') return '';
  /* №329 · с 05.11.2026 основной движок — DeepSeek напрямую (счёт Jinjia пополнен), Яндекс — запасной */
  $ds = ai_translate_field_ds($text, $kind, $ctx);
  if ($ds !== null && $ds !== '') return $ds;
  if (function_exists('yx_translate_field') && function_exists('yx_ready') && yx_ready()) {
    $yx = yx_translate_field($text, $kind, $ctx);
    /* Отказ или болтовню в карточку не пускаем. */
    if ($yx !== null && $yx !== '' && !itc_bad_ai_text($yx)) return $yx;
  }
  return null;
}
function ai_translate_field_ds($text, $kind='plain', $ctx='') {
  if (!defined('DEEPSEEK_API_KEY') || !DEEPSEEK_API_KEY) return null;

  $base = "Ты контент-менеджер российского маркетплейса ИТК (мебель и товары для дома, прямые поставки из Китая). ".
          "Тебе дают текст с китайской площадки (1688 / Pinduoduo / Taobao). Переведи на русский.\n".
          "ГЛАВНОЕ: не переводи дословно — переосмысли как живой русский копирайтер. ".
          "Убирай китайский рекламный мусор (爆款, 包邮, 工厂直销, 秒杀, 限时). ".
          "Не выдумывай фактов, которых нет в исходнике. Верни ТОЛЬКО результат, без пояснений и кавычек.";

  switch ($kind) {
    case 'name':
      $sys = $base."\nЗАДАЧА: короткое продающее НАЗВАНИЕ товара в стиле Wildberries/Ozon: ".
             "тип товара + материал + стиль + ключевая особенность. Без иероглифов, до 90 символов.";
      $temp=0.3; $max=120; break;
    case 'description':
      $sys = $base."\nЗАДАЧА: ОПИСАНИЕ товара, 2–5 предложений, продающее, по делу. ".
             "Пиши о материале, размерах, применении, преимуществах — только то, что следует из исходника.";
      $temp=0.4; $max=700; break;
    case 'review':
      $sys = $base."\nЗАДАЧА: перевести ОТЗЫВ покупателя. Сохрани живую разговорную интонацию и эмоцию автора, ".
             "не приукрашивай и не смягчай критику. Если отзыв короткий — перевод тоже короткий.";
      $temp=0.5; $max=500; break;
    case 'specs':
      $sys = $base."\nЗАДАЧА: перевести ХАРАКТЕРИСТИКИ товара. Сохрани структуру строк и числа/единицы измерения как есть. ".
             "Переводи только названия параметров и текстовые значения.";
      $temp=0.2; $max=700; break;
    default:
      $sys = $base."\nЗАДАЧА: аккуратно перевести текст на русский, сохранив смысл и форматирование.";
      $temp=0.3; $max=700;
  }
  if ($ctx!=='') $sys .= "\nКонтекст товара (для точности терминов): ".mb_substr($ctx,0,200);

  $payload = json_encode([
    'model'=>'deepseek-v4-flash',
    'messages'=>[['role'=>'system','content'=>$sys],['role'=>'user','content'=>$text]],
    'temperature'=>$temp, 'max_tokens'=>$max, 'stream'=>false,
  ], JSON_UNESCAPED_UNICODE);
  $ch = curl_init('https://api.deepseek.com/chat/completions');
  curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true,
    CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.DEEPSEEK_API_KEY],
    CURLOPT_POSTFIELDS=>$payload, CURLOPT_TIMEOUT=>40, CURLOPT_CONNECTTIMEOUT=>10,
    CURLOPT_SSL_VERIFYPEER=>false,
  ]);
  $raw=curl_exec($ch); $http=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
  if($raw===false || $http!==200){ error_log("DeepSeek translate fail http=$http"); return null; }
  $resp=json_decode($raw,true);
  $out=trim($resp['choices'][0]['message']['content'] ?? '');
  $out=trim(preg_replace('/^```(?:\w+)?|```$/m','',$out));
  $out=trim($out);
  // Снимаем обрамляющие кавычки, если модель их добавила (обычные и типографские)
  $out=preg_replace('/^["\x{201C}\x{201E}\x{00AB}](.*)["\x{201D}\x{201C}\x{00BB}]$/us','$1',$out);
  $out=trim($out);
  /* Та же проверка для DeepSeek: отказ — это не перевод. */
  if ($out==='' || itc_bad_ai_text($out)) return null;
  return $out;
}

// ===== Очередь выкупа: заказ оплачен клиентом -> бухгалтер выкупает товар у поставщика =====
// ВАЖНО: должна быть объявлена ДО switch, иначе PHP её не увидит.
// Создаёт строки в ds_procurement по каждой DS-позиции заказа (status='pending').
function ds_create_procurement($order_id){
  $order_id = trim((string)$order_id);
  if ($order_id==='') return 0;
  $made = 0;
  try {
    $items=db()->prepare('SELECT i.id,i.product_id,i.qty FROM order_items i WHERE i.order_id=?');
    $items->execute([$order_id]);
    foreach($items->fetchAll() as $it){
      /* №287: есть на складе в России — отдаём оттуда, в Китае не выкупаем */
      try {
        if (function_exists('stock_reserve_part')) {
          $fromStock = stock_reserve_part($order_id, $it['id'], $it['product_id'], (int)$it['qty']);
          if ($fromStock > 0) {
            // снимаем ещё не выкупленное задание (его могли создать на полную сумму) и при необходимости создаём на остаток
            try { db()->prepare("DELETE FROM ds_procurement WHERE order_id=? AND product_id=? AND (status='pending' OR status IS NULL OR status='')")->execute([$order_id, $it['product_id']]); } catch (Exception $e) {}
            if ($fromStock >= (int)$it['qty']) continue;
            $it['qty'] = (int)$it['qty'] - $fromStock;   // остаток — под выкуп в Китае
          }
        }
      } catch (Throwable $e) {}
      // Без дублей (22.09.2026): задание по этой позиции уже есть — пропускаем.
      $ex=db()->prepare('SELECT 1 FROM ds_procurement WHERE order_id=? AND product_id=? LIMIT 1');
      $ex->execute([$order_id,$it['product_id']]);
      if($ex->fetchColumn()) continue;
      $dsp=db()->prepare('SELECT id,source_url,source_price_cny,manager_id FROM ds_products WHERE product_id=?');
      $dsp->execute([$it['product_id']]);
      $dp=$dsp->fetch();
      $pcid=gen_ds_id();
      if($dp){
        db()->prepare('INSERT IGNORE INTO ds_procurement(id,order_id,product_id,ds_product_id,qty,source_url,source_price_cny,manager_id) VALUES(?,?,?,?,?,?,?,?)')
          ->execute([$pcid,$order_id,$it['product_id'],$dp['id'],(int)$it['qty'],$dp['source_url'],$dp['source_price_cny'],$dp['manager_id']]);
        $made++;
        continue;
      }
      // Не дропшип: товар с фабрики закупки, от обычного поставщика или наш собственный.
      // Раньше такие позиции в очередь выкупа не попадали вообще — бухгалтер их не видел.
      // Источником берём сайт фабрики, ценой — закупочную из карточки товара.
      $pr=db()->prepare('SELECT goods_cny, jfactory_id FROM products WHERE id=?');
      $pr->execute([$it['product_id']]);
      $prow=$pr->fetch() ?: [];
      $src='';
      if(!empty($prow['jfactory_id'])){
        try{ $jf=db()->prepare('SELECT site FROM jfactories WHERE id=?'); $jf->execute([$prow['jfactory_id']]);
             $jr=$jf->fetch(); if($jr && !empty($jr['site'])) $src=$jr['site']; }catch(Exception $e){}
      }
      try{
        db()->prepare('INSERT IGNORE INTO ds_procurement(id,order_id,product_id,ds_product_id,qty,source_url,source_price_cny,manager_id) VALUES(?,?,?,?,?,?,?,?)')
          ->execute([$pcid,$order_id,$it['product_id'],null,(int)$it['qty'],$src,(float)($prow['goods_cny'] ?? 0),null]);
        $made++;
      }catch(Exception $e){ error_log('ds_create_procurement (не-DS): '.$e->getMessage()); }
    }
  } catch(Exception $e){ error_log('ds_create_procurement: '.$e->getMessage()); }
  return $made;
}

// Есть ли в тексте китайские иероглифы (для авто-подсветки кнопки перевода).
function has_cjk($s){ return (bool)preg_match('/[\x{4e00}-\x{9fff}\x{3400}-\x{4dbf}]/u', (string)$s); }
/* №283: перевести название товара/варианта, если в нём остались иероглифы.
   Части через « · » переводим по отдельности, чтобы разделитель вариантов
   не пропал (по нему магазин показывает «название · вариант»). Если перевод
   не удался — возвращаем как было. */
function itc_tr_name($name) {
  $name = (string)$name;
  if (!has_cjk($name) || !function_exists('ai_translate_field')) return $name;
  $parts = explode(' · ', $name);
  foreach ($parts as &$pt) {
    if (!has_cjk($pt)) continue;
    try { $t = trim((string)ai_translate_field($pt, 'plain', 'Название товара или его варианта для интернет-магазина. Переведи на русский коротко, без пояснений и кавычек. Модели, вольтаж и стандарты (VDE, BS, 220V) оставь как есть.')); }
    catch (Throwable $e) { $t = ''; }
    if ($t !== '' && !has_cjk($t)) $pt = mb_substr($t, 0, 120);
  }
  unset($pt);
  return implode(' · ', $parts);
}

// Генерация вежливого ответа магазина на отзыв покупателя (DeepSeek).
function review_ai_reply($text, $rating) {
  if (!defined('DEEPSEEK_API_KEY') || !DEEPSEEK_API_KEY) return null;
  $rating = (int)$rating;
  $tone = $rating >= 4 ? 'тёплый и благодарный' : ($rating == 3 ? 'вежливый, с готовностью помочь' : 'извиняющийся, с предложением решения');
  $system = "Ты представитель магазина мебели и товаров ИТК. Напиши короткий (2-3 предложения) вежливый ответ на отзыв покупателя от лица магазина. Тон: {$tone}. Поблагодари за отзыв; если отзыв негативный — искренне извинись и предложи помощь (связаться с поддержкой, заменить, решить вопрос). Пиши по-человечески, без канцелярита и штампов, не выдумывай деталей, которых нет в отзыве. Верни ТОЛЬКО текст ответа, без кавычек и пояснений.";
  $user = "Оценка: {$rating}/5. Текст отзыва: {$text}";
  $payload = json_encode([
    'model'=>'deepseek-v4-flash',
    'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$user]],
    'temperature'=>0.6, 'max_tokens'=>300, 'stream'=>false,
  ], JSON_UNESCAPED_UNICODE);
  $ch = curl_init('https://api.deepseek.com/chat/completions');
  curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true,
    CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.DEEPSEEK_API_KEY],
    CURLOPT_POSTFIELDS=>$payload, CURLOPT_TIMEOUT=>40, CURLOPT_CONNECTTIMEOUT=>10,
    CURLOPT_SSL_VERIFYPEER=>false,
  ]);
  $raw=curl_exec($ch); $http=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch);
  if($raw===false || $http!==200) return null;
  $resp=json_decode($raw,true);
  $content=trim($resp['choices'][0]['message']['content'] ?? '');
  return $content!=='' ? $content : null;
}

// Умный перевод-обёртка: Yandex → DeepSeek → откат на MyMemory (pdd_translate).
function pdd_smart_translate($name_zh, $desc_zh = '') {
  /* №329 · сначала DeepSeek напрямую (заодно подсказывает категорию), Яндекс — запасной */
  $ai = ds_deepseek_enrich($name_zh, $desc_zh);
  if ($ai !== null && trim((string)($ai['name'] ?? '')) !== '' && !itc_bad_ai_text($ai['name'])) return ['name'=>$ai['name'], 'description'=>$ai['description'], 'category'=>$ai['category'], 'source'=>'deepseek'];
  // Yandex — запасной движок. Категорию он не отдаёт (в отличие от старого
  // ds_deepseek_enrich), и это нормально: категории берём у самой 1688
  // через cat_get → ob_cat, а не угадываем моделью.
  if (function_exists('yx_translate_field') && function_exists('yx_ready') && yx_ready()) {
    $n = yx_translate_field($name_zh, 'name');
    if ($n !== null && itc_bad_ai_text($n)) $n = null;   // отказ в название не пускаем
    if ($n !== null && $n !== '') {
      return [
        'name'        => $n,
        'description' => $desc_zh !== '' ? (string)yx_translate_field($desc_zh, 'description', $n) : '',
        'category'    => '',
        'source'      => 'yandex',
      ];
    }
  }

  return [
    'name'=>pdd_translate($name_zh),
    'description'=>$desc_zh!=='' ? pdd_translate($desc_zh) : '',
    'category'=>'',
    'source'=>'mymemory',
  ];
}

// ===== Достать детей категории из ответа cat_get =====
// РАЗГАДКА (видно в shape, а не в догадках): cat_get на cid=13 отдаёт не
// список детей, а САМУ категорию 13 объектом с полями
// [id, name, pid, root_id, sub] — дети лежат ВНУТРИ, в поле sub.
// Для cid=0 иначе: там список корневых (items > item), корень не категория.
// Отсюда и «подкатегорий нет»: мы искали список рядом, а он был вложен.
function ob_cat_node_by_id($node, $id, $depth = 0) {
  if (!is_array($node) || $depth > 5) return null;
  if (isset($node['id']) && (string)$node['id'] === (string)$id) return $node;
  foreach ($node as $v) {
    if (!is_array($v)) continue;
    $r = ob_cat_node_by_id($v, $id, $depth + 1);
    if ($r) return $r;
  }
  return null;
}

// Нормализуем sub: он бывает списком, а бывает одиночным объектом
function ob_cat_sub_list($node) {
  if (!is_array($node) || empty($node['sub']) || !is_array($node['sub'])) return null;
  $sub = $node['sub'];
  if (isset($sub['id'])) return [$sub];
  $ok = [];
  foreach ($sub as $v) if (is_array($v) && isset($v['id'])) $ok[] = $v;
  return $ok ?: null;
}

// Записать ветку целиком, вместе с вложенными sub. Вызов уже оплачен —
// брать из него один уровень и платить за следующий было бы расточительством.
function ob_cat_save_tree($list, $pid, $ppath, $plevel, &$n, $depth = 0) {
  if ($depth > 5) return;
  foreach ($list as $c) {
    $id = (string)($c['id'] ?? '');
    if ($id === '' || $id === (string)$pid) continue;   // ребёнок ≠ родитель
    $nm   = (string)($c['name'] ?? '');
    $path = $ppath !== '' ? $ppath.' > '.$nm : $nm;
    ob_exec("INSERT INTO ob_cat (id,pid,root_id,level,name_cn,path_cn,updated_at)
             VALUES (?,?,?,?,?,?,NOW())
             ON DUPLICATE KEY UPDATE name_cn=VALUES(name_cn), path_cn=VALUES(path_cn),
                                     pid=VALUES(pid), updated_at=NOW()",
            [$id, (int)$pid, (int)($c['root_id'] ?? 0), $plevel + 1, $nm, $path]);
    $n++;

    $kids = ob_cat_sub_list($c);
    if ($kids) {
      ob_cat_save_tree($kids, $id, $path, $plevel + 1, $n, $depth + 1);
      ob_exec("UPDATE ob_cat SET kids_synced=1, has_kids=1 WHERE id=?", [$id]);
    }
  }
}

// Разбор структуры ответа для глаз: имена ключей, тип, размер, первый
// элемент. Нужен ВСЕГДА, а не только при пустом списке: «added=1» тоже
// ничего не говорит о том, что именно нашлось — ребёнок или сама категория.
function ob_shape($d0) {
  $out = [];
  foreach (array_slice((array)$d0, 0, 8, true) as $k => $v) {
    if (is_scalar($v) || $v === null) { $out[$k] = $v; continue; }
    if (is_array($v)) {
      $first = reset($v);
      $out[$k] = ['ТИП'=>'массив', 'ЭЛЕМЕНТОВ'=>count($v),
                  'КЛЮЧИ'=>array_slice(array_keys($v), 0, 8),
                  'ПЕРВЫЙ'=>is_array($first) ? array_slice($first, 0, 8, true) : $first];
      continue;
    }
    $out[$k] = gettype($v);
  }
  return $out;
}

// ===== Описание товара из характеристик =====
// На 1688 описание сделано КАРТИНКАМИ — текста нет вообще, поэтому desc_ru
// пуст и карточка говорит «Продавец пока не добавил описание товара».
// Но характеристики есть и переведены: 材质 → ДСП, 产品类别 → стеллаж.
// Собираем описание из НИХ: это данные фабрики, а не выдумка модели.
// Кладём в ob_item.desc_ru — считается один раз на товар, не на каждый из
// 19 вариантов.
function ob_item_description($num_iid, $force = false) {
    $it = ob_row("SELECT num_iid,title_ru,title_cn,desc_ru FROM ob_item WHERE num_iid=?", [$num_iid]);
    if (!$it) return '';
    if (!$force && trim((string)$it['desc_ru']) !== '') return $it['desc_ru'];

    $props = ob_all("SELECT name_ru,name_cn,value_ru,value_cn FROM ob_prop
                      WHERE num_iid=? ORDER BY sort LIMIT 25", [$num_iid]);
    if (!$props) return '';

    // Отдаём модели то, что есть. Непереведённое тоже: она читает по-китайски,
    // а нам важнее не потерять факт (материал, тип), чем причесать вид.
    $lines = [];
    foreach ($props as $p) {
        $n = trim((string)($p['name_ru']  ?: $p['name_cn']));
        $v = trim((string)($p['value_ru'] ?: $p['value_cn']));
        if ($n === '' || $v === '') continue;
        if (mb_strlen($v) > 120) $v = mb_substr($v, 0, 120) . '…';   // «цвет» бывает на пол-экрана
        $lines[] = $n . ': ' . $v;
    }
    if (!$lines) return '';

    if (!function_exists('yx_gpt') || !function_exists('yx_ready') || !yx_ready()) return '';

    $sys = "Ты контент-менеджер российского маркетплейса (мебель и товары для дома из Китая).\n".
           "Тебе дают НАЗВАНИЕ товара и его ХАРАКТЕРИСТИКИ с китайской площадки 1688.\n".
           "Напиши описание для карточки: 3-5 предложений, по делу, по-русски.\n".
           "ПРАВИЛА:\n".
           "- Пиши ТОЛЬКО о том, что следует из характеристик. Ничего не выдумывай:\n".
           "  ни гарантий, ни страны, ни сертификатов, ни отзывов, ни цены.\n".
           "- Начни с того, что это за предмет и из чего сделан.\n".
           "- Упомяни материал, тип конструкции, стиль, назначение — если они есть в данных.\n".
           "- Не перечисляй характеристики списком: они и так будут в таблице под описанием.\n".
           "- Без рекламных восклицаний, без «идеально подойдёт», без обращений к покупателю.\n".
           "- Верни ТОЛЬКО текст описания, без заголовков и кавычек.";

    $user = "Товар: " . ($it['title_ru'] ?: $it['title_cn']) . "\n\nХарактеристики:\n" . implode("\n", $lines);

    $txt = yx_gpt($sys, $user, 0.4, 600);
    if (!is_string($txt) || trim($txt) === '') return '';
    $txt = trim($txt);
    if (has_cjk($txt)) return '';   // модель сорвалась в китайский — не берём

    ob_exec("UPDATE ob_item SET desc_ru=? WHERE num_iid=?", [mb_substr($txt, 0, 2000), $num_iid]);
    return $txt;
}

// ===== Найти список категорий в ответе cat_get =====
// Перебирать имена ключей бесполезно: у onebound обёртка зовётся «items»,
// а вложенный ключ — «itme» (опечатка в их API). Комбинаций больше, чем
// можно предугадать, и цепочка ?? молча останавливается на первом непустом
// значении — даже если это обёртка, а не список. Так мы 11 раз заплатили
// за ответы, которые приходили полными, и записали «подкатегорий нет».
//
// Поэтому ищем НЕ по имени, а по форме: массив, элементы которого похожи
// на категорию (есть id и name). Как бы их ни назвали.
function ob_find_cat_list($node, $depth = 0) {
  if (!is_array($node) || $depth > 4) return null;

  // Одиночная категория объектом
  if (isset($node['id']) && (isset($node['name']) || isset($node['cid']))) return [$node];

  // Список категорий
  $first = reset($node);
  if (is_array($first) && isset($first['id']) && (isset($first['name']) || isset($first['cid']))) {
    $ok = [];
    foreach ($node as $v) if (is_array($v) && isset($v['id'])) $ok[] = $v;
    if ($ok) return $ok;
  }

  // Глубже
  foreach ($node as $v) {
    if (!is_array($v)) continue;
    $r = ob_find_cat_list($v, $depth + 1);
    if ($r) return $r;
  }
  return null;
}

// ===== Перевод СПИСКА строк через YandexGPT =====
// Одним запросом на пачку, а не по строке: 20 названий по отдельности — это
// 20 обращений и полминуты ожидания. Отдаём нумерованный список, ждём такой же.
//
// @param $texts  исходные строки
// @param $sys    задача модели
// @return array  строки в том же порядке; '' там, где не вышло
// ===== Отслеживание цен поставщика 1688 =====
function ob_track_fetch_price($iid) {
  $iid = preg_replace('/[^0-9]/', '', (string)$iid);
  if ($iid === '') return null;
  $r = ob_call('item_get', ['num_iid'=>$iid], ['cache'=>'no']);
  $data = is_array($r['data'] ?? null) ? $r['data'] : [];
  $item = $data['item'] ?? ($data['items']['item'] ?? null);
  if (!is_array($item)) return null;
  $p = $item['price'] ?? ($item['orginal_price'] ?? null);
  return ($p === null || $p === '') ? null : round((float)$p, 2);
}
/* ЦЕНЫ ПО ВАРИАНТАМ (24.08.2026).
   ob_track_fetch_price отдаёт item.price — у 1688 это цена «от», то есть самый
   дешёвый вариант карточки. Найдено на карточке ножа Deli: клиент оплатил
   большой 18 мм за ¥1.60, система сравнила его с ¥1.30 маленького 9 мм и
   написала «дешевле на 19%, выгода». Цена при этом не менялась вообще.
   Опаснее другое: та же минимальная цена перезаписывала закупочную цену товара
   и пересчитывала рублёвую цену на витрине. Там, где варианты отличаются в разы,
   витрина встала бы по цене самого дешёвого.
   Ниже — чтение цен ПО КАЖДОМУ варианту и сопоставление с нашим товаром через
   ob_sku.properties (ключ варианта, по нему же карточка и заводилась). */
function ob_offer_sku_prices($iid) {
  $iid = preg_replace('/[^0-9]/', '', (string)$iid);
  if ($iid === '') return null;
  /* ПАМЯТЬ НА ВРЕМЯ ПРОГОНА (25.08.2026).
     У карточки бывает под 70 вариантов, и каждый наш товар — отдельная строка.
     Без этой памяти обход спрашивал бы ОДНУ И ТУ ЖЕ карточку у 1688 столько
     раз, сколько у неё вариантов. Спрашиваем один раз, остальные берут отсюда.
     Живёт только внутри одного запуска — на следующий день цена спросится заново. */
  static $memo = [];
  if (isset($memo[$iid])) return $memo[$iid];
  $r = ob_call('item_get', ['num_iid'=>$iid], ['cache'=>'no']);
  $data = is_array($r['data'] ?? null) ? $r['data'] : [];
  $item = $data['item'] ?? ($data['items']['item'] ?? null);
  if (is_array($item) && isset($item[0]) && is_array($item[0])) $item = $item[0];
  if (!is_array($item)) return $memo[$iid] = ['min'=>null,'by_props'=>[],'by_name'=>[],'n'=>0,'iid'=>$iid,
                                'err'=>(string)($r['error_code'] ?? 'NET')];
  $out = ['min'=>null, 'by_props'=>[], 'by_name'=>[], 'by_spec'=>[], 'n'=>0, 'iid'=>$iid];
  $p = $item['price'] ?? ($item['orginal_price'] ?? null);
  if ($p !== null && $p !== '') $out['min'] = round((float)$p, 2);
  $raw = $item['skus']['sku'] ?? ($item['sku']['sku'] ?? ($item['skus'] ?? ($item['sku'] ?? [])));
  if (is_array($raw)) {
    if (isset($raw['price']) || isset($raw['properties']) || isset($raw['properties_name'])) $raw = [$raw];
    foreach ($raw as $sk) {
      if (!is_array($sk)) continue;
      $pr = $sk['price'] ?? ($sk['sku_price'] ?? ($sk['normal_price'] ?? null));
      if ($pr === null || $pr === '') continue;
      $pr = round((float)$pr, 2);
      if ($pr <= 0) continue;
      $props = trim((string)($sk['properties'] ?? ''));
      $name  = trim((string)($sk['properties_name'] ?? ($sk['spec_name'] ?? '')));
      $spec  = trim((string)($sk['spec_id'] ?? ''));
      if ($props !== '') $out['by_props'][$props] = $pr;
      if ($name  !== '') $out['by_name'][$name]   = $pr;
      if ($spec  !== '') $out['by_spec'][$spec]   = $pr;
      $out['n']++;
    }
  }
  /* Урезанный ответ (без цены и без вариантов) НЕ запоминаем: через минуту
     карточка может прийти полной, а память держала бы пустышку весь прогон. */
  if ($out['min'] === null && $out['n'] === 0) return $out;
  return $memo[$iid] = $out;
}
/* Цена ИМЕННО нашего варианта. exact=false — вариант не опознан, цену показывать
   можно только с оговоркой и НИКОГДА не пересчитывать по ней витрину. */
function ob_variant_price($product_id, $off) {
  $res = ['price'=>null, 'exact'=>false, 'n'=>(int)($off['n'] ?? 0)];
  if (!is_array($off)) return $res;
  if (!empty($off['err'])) return $res;   // ответа по сути не было — цены нет
  /* ОСТОРОЖНО С «КАРТОЧКОЙ БЕЗ ВАРИАНТОВ».
     Пустой список у 1688 значит либо что вариантов правда нет, либо что их
     в этот раз не прислали. Отличить одно от другого можно только по своей
     базе: если мы заводили с этой карточки больше одного варианта — значит
     они есть, и минимальной цене верить нельзя. */
  $manyOurs = false;
  if ((int)($off['n'] ?? 0) <= 1) {
    $iid = trim((string)($off['iid'] ?? ''));
    if ($iid !== '') {
      try {
        $c = db()->prepare("SELECT COUNT(*) FROM ob_sku WHERE num_iid=?");
        $c->execute([$iid]);
        $manyOurs = ((int)$c->fetchColumn() > 1);
      } catch (Exception $e) {}
    }
    if (!$manyOurs) { $res['price'] = $off['min']; $res['exact'] = true; return $res; }
  }
  $product_id = trim((string)$product_id);
  if ($product_id === '') { $res['price'] = $off['min']; return $res; }
  $sk = null;
  try {
    $q = db()->prepare("SELECT spec_id,properties,properties_cn FROM ob_sku WHERE product_id=? LIMIT 1");
    $q->execute([$product_id]); $sk = $q->fetch();
  } catch (Exception $e) {}
  if ($sk) {
    $spec  = trim((string)($sk['spec_id'] ?? ''));
    $props = trim((string)($sk['properties'] ?? ''));
    $pcn   = trim((string)($sk['properties_cn'] ?? ''));
    /* Порядок важен: spec_id уникален у 1688 и не меняется — это самый
       надёжный ключ. Код свойств («0:1») уникален только внутри карточки,
       а название может измениться в любой момент. */
    if ($spec  !== '' && isset($off['by_spec'][$spec]))   { $res['price']=$off['by_spec'][$spec];   $res['exact']=true; return $res; }
    if ($props !== '' && isset($off['by_props'][$props])) { $res['price']=$off['by_props'][$props]; $res['exact']=true; return $res; }
    if ($pcn   !== '' && isset($off['by_name'][$pcn]))    { $res['price']=$off['by_name'][$pcn];    $res['exact']=true; return $res; }
    if ($props !== '') foreach ($off['by_name'] as $nm=>$pr) {
      if (strpos($nm, $props) !== false) { $res['price']=$pr; $res['exact']=true; return $res; }
    }
  }
  $res['price'] = $off['min'];   // не опознали — отдаём минимальную, но с exact=false
  return $res;
}
function ob_track_check_one($iid) {
  $iid = preg_replace('/[^0-9]/', '', (string)$iid);
  if ($iid === '') return ['error'=>'нет товара'];
  /* Один запрос вместо двух: сразу и цена карточки, и цены вариантов */
  $off = ob_offer_sku_prices($iid);
  $cur = is_array($off) ? $off['min'] : null;
  if ($cur === null) { try { db()->prepare("UPDATE ob_track SET last_checked=NOW() WHERE num_iid=?")->execute([$iid]); } catch (Exception $e) {} return ['error'=>'цена не получена','num_iid'=>$iid]; }
  $prev = null; try { $q = db()->prepare("SELECT last_price FROM ob_track WHERE num_iid=?"); $q->execute([$iid]); $rr = $q->fetch(); if ($rr && $rr['last_price'] !== null) $prev = (float)$rr['last_price']; } catch (Exception $e) {}
  try {
    db()->prepare("UPDATE ob_track SET base_price=COALESCE(base_price,?), prev_price=last_price, last_price=?, last_checked=NOW() WHERE num_iid=?")->execute([$cur, $cur, $iid]);
    db()->prepare("INSERT INTO ob_price_hist (num_iid,price) VALUES (?,?)")->execute([$iid, $cur]);
  } catch (Exception $e) {}
  $changed = ($prev !== null && abs($prev - $cur) >= 0.01);
  $recalc = false; $new_rub = null;
  {
    /* ПЕРЕСЧЁТ ВИТРИНЫ — ТОЛЬКО ПО ЦЕНЕ СВОЕГО ВАРИАНТА (24.08.2026).
       Было: брали минимальную цену карточки и ставили её ОДНОМУ товару
       (ORDER BY id DESC LIMIT 1). У карточки с несколькими вариантами это
       чужая цена, да ещё и не тому варианту.
       И проверяли только когда сдвинулась минимальная цена — а наш вариант
       мог подорожать при неизменной минимальной, и это молча пропускалось.
       Стало: идём по ВСЕМ нашим товарам этой карточки, каждому ищем его
       собственную цену. Не опознали — цену НЕ трогаем: лучше устаревшая,
       чем чужая. */
    $skipped = 0;
    try {
      $dq = db()->prepare("SELECT id,product_id,source_price_cny FROM ds_products WHERE source_url LIKE ?");
      $dq->execute(['%offer/'.$iid.'.%']);
      $dsRows = $dq->fetchAll();
      foreach ($dsRows as $ds) {
        $vp = ob_variant_price($ds['product_id'], $off);
        if ($vp['price'] === null || !$vp['exact']) { $skipped++; continue; }
        if ($ds['source_price_cny'] !== null && abs((float)$ds['source_price_cny'] - $vp['price']) < 0.01) continue;
        db()->prepare("UPDATE ds_products SET source_price_cny=? WHERE id=?")->execute([$vp['price'], $ds['id']]);
        if (function_exists('ds_sync_product_price')) { ds_sync_product_price($ds['id']); $recalc = true; }
        try { $pq = db()->prepare("SELECT p.price FROM ds_products d JOIN products p ON p.id=d.product_id WHERE d.id=?"); $pq->execute([$ds['id']]); $new_rub = $pq->fetchColumn(); } catch (Exception $e) {}
      }
    } catch (Exception $e) {}
    if ($skipped) $skipped_variants = $skipped;
  }
  return ['num_iid'=>$iid, 'price'=>$cur, 'prev'=>$prev, 'changed'=>$changed, 'recalc'=>$recalc, 'new_rub'=>($new_rub!==false?$new_rub:null),
          'skipped_variants'=>(isset($skipped_variants)?$skipped_variants:0)];
}
function ob_track_check_due($intv, $limit) {
  $due = [];
  try {
    $rows = db()->query("SELECT num_iid,tier,last_checked FROM ob_track")->fetchAll();
    $now = time();
    foreach ($rows as $r) {
      $days = $intv[$r['tier']] ?? 9999;
      $lc = $r['last_checked'] ? strtotime($r['last_checked']) : 0;
      if (!$lc || ($now - $lc) >= $days * 86400) $due[] = $r['num_iid'];
    }
  } catch (Exception $e) {}
  $due = array_slice($due, 0, $limit);
  $checked = 0; $changed = [];
  foreach ($due as $iid) {
    $res = ob_track_check_one($iid);
    if (!isset($res['error'])) { $checked++; if (!empty($res['changed'])) $changed[] = $res; }
    usleep(200000);
  }
  return ['checked'=>$checked, 'changed'=>$changed, 'due_total'=>count($due)];
}
// ===== Контроль цены выкупа: ежедневное обновление текущей цены 1688 =====
function buyout_ensure_cols() {
  static $done = false; if ($done) return; $done = true;
  try { db()->query("ALTER TABLE ds_procurement ADD COLUMN cur_price_cny DECIMAL(12,2) NULL"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE ds_procurement ADD COLUMN cur_checked_at DATETIME NULL"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE ds_procurement ADD COLUMN mgr_status VARCHAR(16) NULL"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE ds_procurement ADD COLUMN mgr_target_cny DECIMAL(12,2) NULL"); } catch (Exception $e) {}
  // 1 — цена взята по НАШЕМУ варианту, 0 — вариант не опознан, цена минимальная по карточке
  try { db()->query("ALTER TABLE ds_procurement ADD COLUMN cur_price_exact TINYINT(1) NULL"); } catch (Exception $e) {}
}
function buyout_refresh_prices($limit = 20, $dueHours = 18) {
  buyout_ensure_cols();
  $thrPct = (float)itc_setting('buyout_markup_pct', '5'); if ($thrPct < 0) $thrPct = 0;
  $mult = 1 + $thrPct / 100;
  $n = 0; $changed = 0;
  try {
    $rows = db()->query("SELECT id,product_id,source_url,source_price_cny,cur_price_cny,cur_price_exact,cur_checked_at,mgr_status FROM ds_procurement WHERE status='pending' AND source_url LIKE '%1688.com/offer/%'")->fetchAll();
    $now = time();
    foreach ($rows as $r) {
      $lc = $r['cur_checked_at'] ? strtotime($r['cur_checked_at']) : 0;
      // Заявки, проверенные ДО правки (точность неизвестна), берём сразу —
      // иначе полсуток на экране висела бы старая, неверная подсказка.
      $needExact = ($r['cur_price_exact'] === null && $r['cur_price_cny'] !== null);
      if (!$needExact && $lc && ($now - $lc) < $dueHours * 3600) continue;
      if (!preg_match('/offer\/(\d+)/', (string)$r['source_url'], $m)) continue;
      /* Спрашиваем цену НАШЕГО варианта, а не «от» по карточке (24.08.2026) */
      $off   = ob_offer_sku_prices($m[1]);
      $vp    = ob_variant_price($r['product_id'], $off);
      $price = $vp['price'];
      $exact = $vp['exact'] ? 1 : 0;
      if ($price === null) { try { db()->prepare("UPDATE ds_procurement SET cur_checked_at=NOW() WHERE id=?")->execute([$r['id']]); } catch (Exception $e) {} continue; }
      if ($r['cur_price_cny'] !== null && abs((float)$r['cur_price_cny'] - $price) >= 0.01) $changed++;
      try { db()->prepare("UPDATE ds_procurement SET cur_price_cny=?, cur_price_exact=?, cur_checked_at=NOW() WHERE id=?")->execute([$price, $exact, $r['id']]); } catch (Exception $e) {}
      // авто-маршрут менеджеру: подорожало больше чем на 5% от номинала.
      // Только по опознанной цене — по чужой звали бы менеджера впустую.
      $nom = (float)$r['source_price_cny'];
      if ($exact && $nom > 0 && $price > $nom * $mult && empty($r['mgr_status'])) {
        try { db()->prepare("UPDATE ds_procurement SET mgr_status='sent', mgr_target_cny=? WHERE id=?")->execute([$nom, $r['id']]); } catch (Exception $e) {}
      }
      $n++;
      if ($n >= $limit) break;
      usleep(150000);
    }
  } catch (Exception $e) {}
  return ['checked' => $n, 'changed' => $changed];
}
function buyout_stats_ensure() {
  static $d = false; if ($d) return; $d = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS buyout_stats (id INT AUTO_INCREMENT PRIMARY KEY, procurement_id VARCHAR(64), product_id VARCHAR(64), num_iid VARCHAR(32), prod_name VARCHAR(255), nom_cny DECIMAL(12,2), actual_cny DECIMAL(12,2), cur_cny DECIMAL(12,2), diff_cny DECIMAL(12,2), diff_pct INT, kind VARCHAR(8), qty INT, mgr_status VARCHAR(16), created_at DATETIME)"); } catch (Exception $e) {}
}
function ob_gpt_list_ru(array $texts, $sys, $chunk = 25, $maxTok = 1200) {
  $out = array_fill(0, count($texts), '');
  if (!$texts) return $out;
  if (!function_exists('yx_ready') || !yx_ready()) return $out;

  foreach (array_chunk($texts, $chunk, true) as $part) {
    $keys = array_keys($part);
    $vals = array_values($part);
    $lines = [];
    foreach ($vals as $i => $n) $lines[] = ($i+1).'. '.$n;

    $txt = function_exists('yx_gpt') ? yx_gpt($sys, implode("\n", $lines), 0.2, $maxTok) : null;

    $got = [];
    if (is_string($txt) && $txt !== '') {
      foreach (preg_split('/\r?\n/', $txt) as $l) {
        if (preg_match('/^\s*(\d+)\s*[\.\)]\s*(.+)$/u', $l, $m)) {
          $v = trim($m[2], " \t\"'«»");
          if ($v !== '' && !has_cjk($v)) $got[(int)$m[1]] = $v;
        }
      }
    }

    // Строк ровно столько, сколько просили — раскладываем.
    // Меньше — модель сбилась с нумерации, и брать ЧАСТЬ нельзя:
    // названия молча уедут не к тем строкам. Откатываемся целиком.
    if (count($got) === count($part)) {
      foreach ($keys as $i => $key) $out[$key] = $got[$i+1] ?? '';
      continue;
    }

    // Откат: дословный Translate. Хуже, но лучше китайщины на экране.
    if (function_exists('yx_translate')) {
      $ru = yx_translate($vals, 'zh', 'ru');
      if (is_array($ru)) foreach ($keys as $i => $key) {
        $v = trim((string)($ru[$i] ?? ''));
        if ($v !== '') $out[$key] = mb_strtoupper(mb_substr($v,0,1),'UTF-8').mb_substr($v,1,null,'UTF-8');
      }
    }
  }
  return $out;
}

// ===== Русские имена категорий 1688 =====
// GPT, а не дословный Translate. Основание — не рассуждение, а живая проба
// из ob_yx_env на одной и той же строке 神器多层家用简易鞋架经济型防尘收纳鞋柜:
//   Translate → «Артефактная многослойная бытовая простая стойка для обуви
//                экономичный пылезащитный шкаф для хранения обуви»
//   GPT       → «Многоуровневая обувница для дома»
// Дословный движок вдобавок транслитерирует: 家清 у него «Цзяцин» вместо
// «бытовой химии». Категория — это РУБРИКА каталога, ей нужен термин.
function ob_cat_names_ru(array $names) {
