// ===== Защита от дублей: стабильный ключ товара из ссылки =====
// PDD: goods_id из URL; 1688: номер оффера. Хвост ссылки (метки, utm) игнорируется.
function ds_source_key($url,$platform=''){
  $url=(string)$url;
  if($platform==='') $platform=ds_detect_platform($url);
  if($platform==='pdd'){
    if(preg_match('/goods_id=(\d+)/',$url,$m)) return 'pdd:'.$m[1];
    if(preg_match('#/goods(\d*)\.html\?.*?goods_id=(\d+)#',$url,$m)) return 'pdd:'.$m[2];
  }
  if($platform==='1688'){
    if(preg_match('#offer/(\d+)#',$url,$m)) return '1688:'.$m[1];
    if(preg_match('#/(\d{6,})\.html#',$url,$m)) return '1688:'.$m[1];
  }
  if($platform==='taobao'){
    if(preg_match('/[?&]id=(\d+)/',$url,$m)) return 'taobao:'.$m[1];
  }
  return '';
}

// Определяет площадку по домену ссылки.
function ds_detect_platform($url){
  $u=strtolower((string)$url);
  if(strpos($u,'pinduoduo')!==false || strpos($u,'yangkeduo')!==false) return 'pdd';
  if(strpos($u,'1688.com')!==false) return '1688';
  if(strpos($u,'alibaba.com')!==false) return 'alibaba';
  if(strpos($u,'taobao.com')!==false || strpos($u,'tmall.com')!==false) return 'taobao';
  return '';
}
// Ищет уже заведённый DS-товар с тем же источником. Возвращает инфо или null.
/* Продавец карточек дропшиппинга — наша компания Jinjia (ищем по названию, кэш на запрос).
   Если поставщик не найден — остаётся метка DS_AUTO (как было раньше). */
function ds_supplier_id(){
  static $sid = null;
  if ($sid !== null) return $sid;
  $sid = 'DS_AUTO';
  try {
    $q = db()->query("SELECT id FROM suppliers WHERE name LIKE '%\xe9\x87\x91\xe4\xbd\xb3%' OR name LIKE '%Jinjia%' OR name LIKE '%JINJIA%' ORDER BY id LIMIT 1");
    $f = $q->fetchColumn();
    if ($f) $sid = $f;
  } catch (Exception $e) {}
  return $sid;
}
/* Пометка: витринную карточку создал дропшиппинг (можно удалять вместе с DS-записью) */
function ds_mark_auto($dsid){
  try { db()->prepare('UPDATE ds_products SET auto_created=1 WHERE id=?')->execute([$dsid]); } catch (Exception $e) {}
}
function ds_find_duplicate($url,$platform='',$exclude_id=''){
  if($platform==='') $platform=ds_detect_platform($url);
  $key=ds_source_key($url,$platform);
  $cols="dp.id,dp.product_id,dp.manager_id,dp.created_at,dp.source_url,dp.source_price_cny,
         p.name prod_name,p.img prod_img,p.mod_status,m.name mgr_name";
  $ex = $exclude_id!=='' ? ' AND dp.id<>?' : '';
  try{
    if($key!==''){
      $id=substr($key,strpos($key,':')+1);
      $q=db()->prepare("SELECT $cols
        FROM ds_products dp LEFT JOIN products p ON p.id=dp.product_id LEFT JOIN ds_staff m ON m.id=dp.manager_id
        WHERE dp.source_url LIKE ?$ex ORDER BY dp.created_at ASC LIMIT 1");
      $args=['%'.$id.'%']; if($ex) $args[]=$exclude_id;
      $q->execute($args);
    } else {
      $q=db()->prepare("SELECT $cols
        FROM ds_products dp LEFT JOIN products p ON p.id=dp.product_id LEFT JOIN ds_staff m ON m.id=dp.manager_id
        WHERE dp.source_url=?$ex ORDER BY dp.created_at ASC LIMIT 1");
      $args=[$url]; if($ex) $args[]=$exclude_id;
      $q->execute($args);
    }
    return $q->fetch() ?: null;
  }catch(Exception $e){ return null; }
}

// Свежесть цены: сколько дней прошло с последней проверки. null = никогда не проверяли.
/* ВАЖНОСТЬ ТОВАРА ДЛЯ ПРОВЕРКИ ЦЕНЫ.
   Проверять все 33 000 карточек одинаково часто бессмысленно: запросы к 1688
   ограничены, а большинство товаров никогда не продавались. Делим на три группы
   и для каждой свой срок «свежести» цены.

   1 — продавался или лежит в корзинах: цена должна быть актуальной всегда
   2 — его смотрели: цена нужна свежая, но не ежедневно
   3 — мёртвый груз: проверяем изредка, чтобы не жечь лимит */
function ds_tier_days($tier) {
  if ($tier === 1) return 3;    // продавался
  if ($tier === 2) return 7;    // смотрели
  return 30;                    // остальные
}
function ds_tier_name($tier) {
  if ($tier === 1) return 'продаётся';
  if ($tier === 2) return 'смотрят';
  return 'без спроса';
}

/* Один раз в сутки размечаем каталог по важности — тяжёлые запросы с продажами
   не должны выполняться на каждый прогон проверки. */
function ds_recalc_tiers() {
  try { db()->query("ALTER TABLE ds_products ADD COLUMN prio_tier TINYINT NOT NULL DEFAULT 3"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE ds_products ADD COLUMN tier_at DATETIME NULL"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE ds_products ADD INDEX idx_tier_check (prio_tier, last_price_check)"); } catch (Exception $e) {}
  // по умолчанию — без спроса
  try { db()->query("UPDATE ds_products SET prio_tier=3"); } catch (Exception $e) {}
  // 2: товар смотрели
  try { db()->query("UPDATE ds_products dp JOIN products p ON p.id=dp.product_id
                        SET dp.prio_tier=2 WHERE COALESCE(p.clicks,0) > 0"); } catch (Exception $e) {}
  // 1: продавался или лежит в неоплаченных заказах (корзинах)
  try { db()->query("UPDATE ds_products dp JOIN order_items i ON i.product_id=dp.product_id
                        SET dp.prio_tier=1"); } catch (Exception $e) {}
  try { db()->query("UPDATE ds_products SET tier_at=NOW()"); } catch (Exception $e) {}
}

function ds_price_age_days($last_check,$created_at){
  $base = $last_check ?: $created_at;
  if(!$base) return null;
  $t=strtotime($base); if(!$t) return null;
  return (int)floor((time()-$t)/86400);
}

function pdd_parse_html($html) {
  $r = ['name'=>'','price_cny'=>0,'images'=>[],'description'=>'','sizes'=>[],'colors'=>[],'src'=>'meta',
        'weight_kg_raw'=>null,'dims_cm'=>null,'cat_zh'=>''];
  if (!$html) return $r;

  // Стратегия 1: __NEXT_DATA__ JSON
  if (preg_match('/<script[^>]+id=["\'"]__NEXT_DATA__["\'"][^>]*>\s*(.+?)\s*<\/script>/s', $html, $m)) {
    $nd = json_decode($m[1], true);
    $goods = $nd['props']['pageProps']['initDataObj']['goods']
          ?? $nd['props']['pageProps']['initData']['data']['goods']
          ?? null;
    if ($goods) {
      $r['src'] = '__NEXT_DATA__';
      $r['name'] = $goods['goods_name'] ?? $goods['goodsName'] ?? '';
      $pr = $goods['min_price'] ?? $goods['normal_price'] ?? $goods['price'] ?? 0;
      $r['price_cny'] = round($pr > 1000 ? $pr/100 : $pr, 2);
      $imgs = $goods['goods_gallery_urls'] ?? $goods['gallery'] ?? [];
      if (is_array($imgs)) $r['images'] = array_values(array_filter($imgs));
      $r['description'] = $goods['goods_desc'] ?? $goods['description'] ?? '';
      // Категория из хлебных крошек
      $cats = $goods['cats'] ?? $goods['cat'] ?? [];
      if (is_array($cats) && count($cats)) {
        $last = end($cats); $r['cat_zh'] = $last['cat_name'] ?? $last['name'] ?? '';
      }
      // Specs: размеры, цвета, вес, габариты
      $specs = $goods['spec_list'] ?? $goods['specs'] ?? [];
      if (is_array($specs)) {
        foreach ($specs as $sp) {
          $sname = $sp['name'] ?? $sp['spec'] ?? '';
          $svals = array_map(function($v){ return $v['name']??$v['spec_value']??$v['value']??(string)$v; },
                             $sp['spec_values'] ?? $sp['values'] ?? []);
          $lc = mb_strtolower($sname);
          if (strpos($lc,'尺')!==false||strpos($lc,'码')!==false||strpos($lc,'size')!==false||strpos($lc,'规格')!==false)
            $r['sizes'] = $svals;
          elseif (strpos($lc,'颜色')!==false||strpos($lc,'色')!==false||strpos($lc,'color')!==false)
            $r['colors'] = $svals;
        }
      }
      // SKU-варианты товара
      $sku_raw = $goods['sku_list'] ?? $goods['skus'] ?? [];
      if (is_array($sku_raw) && count($sku_raw)) {
        $r['skus'] = [];
        foreach ($sku_raw as $sku) {
          $pr_sku = $sku['min_price'] ?? $sku['normal_price'] ?? $sku['price'] ?? 0;
          $pr_sku = $pr_sku > 1000 ? round($pr_sku/100,2) : round((float)$pr_sku,2);
          if ($pr_sku <= 0) continue;
          $qty = $sku['quantity'] ?? $sku['sku_quantity'] ?? $sku['qty'] ?? 999;
          // Собираем название варианта из specs
          $specs_arr = $sku['specs'] ?? $sku['spec_values'] ?? [];
          $vals = [];
          foreach ($specs_arr as $sp) {
            $v = $sp['spec_value_name'] ?? $sp['value_name'] ?? $sp['spec_value'] ?? $sp['value'] ?? '';
            if ($v) $vals[] = $v;
          }
          $sku_name = count($vals) ? implode(' · ', $vals) : ($sku['spec_key'] ?? '');
          $img = $sku['img_url'] ?? $sku['img'] ?? $sku['image_url'] ?? '';
          $r['skus'][] = [
            'id'        => $sku['sku_id'] ?? $sku['id'] ?? '',
            'name'      => $sku_name,
            'price_cny' => $pr_sku,
            'img'       => $img,
            'qty'       => (int)$qty,
          ];
        }
      }
      // Вес из детальных спецификаций (detail_specs)
      $dspecs = $goods['detail_specs'] ?? $goods['goods_properties'] ?? [];
      if (is_array($dspecs)) {
        foreach ($dspecs as $ds) {
          $key = mb_strtolower($ds['name']??$ds['key']??'');
          $val = $ds['value']??$ds['val']??'';
          if (strpos($key,'重量')!==false||strpos($key,'净重')!==false||strpos($key,'毛重')!==false||strpos($key,'weight')!==false) {
            // "1.5kg", "500g", "1500克"
            if (preg_match('/([\d\.]+)\s*(kg|千克|公斤)/i', $val, $wm)) $r['weight_kg_raw']=(float)$wm[1];
            elseif (preg_match('/([\d\.]+)\s*(g|克|gram)/i', $val, $wm)) $r['weight_kg_raw']=round((float)$wm[1]/1000,3);
          }
          if (strpos($key,'尺寸')!==false||strpos($key,'规格')!==false||strpos($key,'size')!==false||strpos($key,'dimension')!==false) {
            $r['dims_cm'] = $val; // сохраняем строку, разберём позже
          }
        }
      }
    }
  }

  // Стратегия 1.5: рендер мобильной страницы PDD (Puppeteer, raw=1) — camelCase поля
  // goodsName / goodsID / topGallery[].url / viewImageData[]. URL экранированы \u002F.
  if (!$r['name'] && preg_match('/"goodsName"\s*:\s*"((?:\\\\.|[^"\\\\])*)"/', $html, $m)) {
    $r['src'] = 'rendered';
    $nm = json_decode('"'.$m[1].'"');
    if ($nm) $r['name'] = $nm;
    // ID товара
    if (preg_match('/"goodsID"\s*:\s*(\d+)/', $html, $gm)) $r['pdd_id'] = $gm[1];
    // Цена (опционально; на PDD в фэнях — делим на 100). Берём первое найденное поле.
    foreach (['minOnSaleGroupPrice','minGroupPrice','minOnSaleNormalPrice','minNormalPrice','marketPrice'] as $pf) {
      if (preg_match('/"'.$pf.'"\s*:\s*(\d+)/', $html, $pm)) {
        $pv = (int)$pm[1];
        $r['price_cny'] = round($pv > 1000 ? $pv/100 : $pv, 2);
        break;
      }
    }
    // Фото: viewImageData (приоритет) -> topGallery. Каждый URL декодируем через json_decode.
    $imgs = [];
    if (preg_match('/"viewImageData"\s*:\s*\[(.*?)\]/s', $html, $vm)) {
      if (preg_match_all('/"(https:[^"]+?)"/', $vm[1], $um)) {
        foreach ($um[1] as $u) { $d = json_decode('"'.$u.'"'); if ($d) $imgs[] = $d; }
      }
    }
    if (empty($imgs) && preg_match('/"topGallery"\s*:\s*\[(.*?)\]/s', $html, $tm)) {
      if (preg_match_all('/"url"\s*:\s*"(https:[^"]+?)"/', $tm[1], $um)) {
        foreach ($um[1] as $u) { $d = json_decode('"'.$u.'"'); if ($d) $imgs[] = $d; }
      }
    }
    if ($imgs) $r['images'] = array_values(array_unique(array_filter($imgs)));
  }

  // Стратегия 2: window.rawData
  if (!$r['name'] && preg_match('/window\.rawData\s*=\s*(\{.+?\});\s*(?=window|<\/script>)/s', $html, $m)) {
    $raw = json_decode($m[1], true);
    $goods = $raw['store']['initDataObj']['goods'] ?? $raw['goods'] ?? null;
    if ($goods) {
      $r['src'] = 'rawData';
      $r['name'] = $goods['goods_name'] ?? '';
      $pr = $goods['min_price'] ?? $goods['price'] ?? 0;
      $r['price_cny'] = round($pr > 1000 ? $pr/100 : $pr, 2);
    }
  }

  // Стратегия 3: meta-теги (запасной)
  if (!$r['name']) {
    if (preg_match('/<meta[^>]+property=["\']og:title["\'][^>]+content=["\'](.*?)["\']/i', $html, $m))
      $r['name'] = html_entity_decode($m[1], ENT_QUOTES, 'UTF-8');
    elseif (preg_match('/<title[^>]*>(.+?)<\/title>/is', $html, $m))
      $r['name'] = html_entity_decode(trim($m[1]), ENT_QUOTES, 'UTF-8');
    if (empty($r['images'])) {
      preg_match_all('/<meta[^>]+property=["\']og:image["\'][^>]+content=["\'](https?:[^"\']+)["\']/i', $html, $mm);
      if (!empty($mm[1])) $r['images'] = $mm[1];
    }
    if (!$r['description'] && preg_match('/<meta[^>]+(?:property=["\']og:description["\']|name=["\']description["\'])[^>]+content=["\'](.*?)["\']/i', $html, $m))
      $r['description'] = html_entity_decode($m[1], ENT_QUOTES, 'UTF-8');
  }

  $r['name'] = preg_replace('/\s+/', ' ', trim($r['name']));
  $r['images'] = array_values(array_unique(array_filter(array_slice($r['images'], 0, 12))));
  return $r;
}


// ── Извлечь размеры из названия SKU ──────────────────────────
// "60*184.5", "120*42*200", "Length 80cm" → {w, d, h}
function pdd_parse_sku_dims($name) {
  // 3 измерения: W*D*H или L*W*H
  if (preg_match('/(\d+\.?\d*)\s*[*xX×]\s*(\d+\.?\d*)\s*[*xX×]\s*(\d+\.?\d*)/u', $name, $m))
    return ['w'=>(float)$m[1],'d'=>(float)$m[2],'h'=>(float)$m[3],'n'=>3];
  // 2 измерения: W*H (наиболее частый у PDD)
  if (preg_match('/(\d+\.?\d*)\s*[*xX×]\s*(\d+\.?\d*)/u', $name, $m))
    return ['w'=>(float)$m[1],'d'=>null,'h'=>(float)$m[2],'n'=>2];
  // Только ширина: "Length 80"
  if (preg_match('/(?:length|длина|ширина|width|l[:\s])\s*(\d+\.?\d*)/i', $name, $m))
    return ['w'=>(float)$m[1],'d'=>null,'h'=>null,'n'=>1];
  return null;
}

// ── Рассчитать объём и вес по размерам SKU ──────────────────────
function pdd_sku_wv($dims, $cat_guess, $base_guess) {
  if (!$dims) return ['wt'=>$base_guess['weight_kg'],'vol'=>$base_guess['volume_m3'],'auto'=>false];
  $w = $dims['w'] ?? 100;
  $h = $dims['h'] ?? ($dims['n']>=2 ? 200 : $base_guess['volume_m3']*1000);
  $d = $dims['d'];
  // Дефолтная глубина по категории (если только 2 измерения)
  if (!$d) {
    $cat = $base_guess['cat']??'';
    $d_map = ['Шкаф'=>52,'Кровати'=>200,'Диван'=>90,'Кресла'=>85,'Стол'=>70,'Тумба'=>42,'Стеллаж'=>40,'Матрас'=>200,'Прихожая'=>35];
    $d = 50; // дефолт
    foreach ($d_map as $key=>$val) { if (mb_stripos($cat,$key)!==false){$d=$val;break;} }
    // Кровати: h=длина кровати, d=глубина каркаса обычно 15 (панель)
    if (mb_stripos($cat,'Кроват')!==false) { $d=15; } // только панели каркаса
  }
  // Для кровати 2 измерения — это W × H(длина), глубина каркаса мала
  $assembled = ($w/100) * ($d/100) * ($h/100);
  $kd = round($assembled * 0.38, 3); // KD-фактор 38%
  // Вес пропорционально объёму от базового
  $bv = $base_guess['volume_m3'] ?: 0.1;
  $wt = round($base_guess['weight_kg'] * ($kd / $bv), 1);
  $wt = max(1.5, min(300.0, $wt));
  $kd = max(0.003, min(5.0, $kd));
  return ['wt'=>$wt,'vol'=>$kd,'auto'=>true];
}

