function pdd_guess_category($name_zh, $name_ru='', $cat_zh='') {
  $txt = mb_strtolower($name_zh.' '.$name_ru.' '.$cat_zh);

  // ============================================================
  // БАЗА ТОВАРОВ В УПАКОВАННОМ/РАЗОБРАННОМ ВИДЕ (KD-формат)
  // Объём = размер коробок, а НЕ собранного изделия!
  // KD-упаковка экономит 40-60% объёма vs собранный вид
  // Источник: практика импорта из Китая, замеры реальных поставок
  // ============================================================
  $rules = ds_kd_rules();


  foreach ($rules as $rule) {
    $zhPat = '/('.$rule['zh'].')/u';
    $ruPat = '/('.$rule['ru'].')/ui';
    if (preg_match($zhPat, $txt) || preg_match($ruPat, $txt)) {
      return [
        'cat'        => $rule['cat'],
        'product_id' => $rule['id'],
        'weight_kg'  => $rule['вес'],
        'volume_m3'  => $rule['объём'],
        'confidence' => 'auto',
        'note'       => 'Объём в упаковке/разобранном виде (KD)',
      ];
    }
  }
  // Дефолт — «Прочее»
  return ['cat'=>'Прочее', 'product_id'=>'other', 'weight_kg'=>1.0, 'volume_m3'=>0.005, 'confidence'=>'default', 'note'=>'Дефолт'];
}

// ============================================================
// НАДЁЖНАЯ КАТЕГОРИЯ ВИТРИНЫ ПО НАЗВАНИЮ (единый источник правды).
// Прозрачные правила по ключевым словам, порядок важен: сначала узкие,
// потом широкие. Русское имя (перевод) — самое информативное поле.
// ============================================================
function itc_store_category_base($name) {
  /* Названия с 1688 устроены как «Товар какой-то · вариант, размер, цвет».
     Хвост после «·» — это описание варианта, и он врал: «Диван … · журнальный
     стол» уезжал в Столы журнальные, «Кровать … · с матрасом» — в Матрасы.
     Тип товара всегда стоит в начале, поэтому берём только голову названия. */
  $head = (string)$name;
  $cut = mb_strpos($head, '·');
  if ($cut !== false && $cut > 8) $head = mb_substr($head, 0, $cut);
  $t = ' '.mb_strtolower($head).' ';
  $h = function($re) use ($t) { return preg_match('/'.$re.'/u', $t); };
  /* №293: НОВЫЕ КАТЕГОРИИ — проверяем первыми. Красота, аксессуары, одежда,
     игрушки разъезжались по 6–7 чужим категориям (ногти в «Канцелярии»,
     заколки в «Кухне», плойки в «Электронике») или падали в «Прочее».
     Мебель и оборудование салонов (кресла, кушетки, мойки) сюда не идут. */
  $salonFurn = $h('кресл|кушетк|мойк|стул|тележк|стойк|шкаф|стол|ресепшн|ресепшен|топчан|диван|шезлонг|лежак');
  $petX = $h('для (кош|собак|живот|питом|попуга|птиц)|кошач|собач|кошек|собак|котов|кот[аеу]? |щен|питомц');
  $giftSet = $h('подарочн[а-я]* набор|набор[а-я]* в подарок|подарочн[а-я]* комплект');
  if ($petX && $h('игрушк|лежанк|когтеточк|миск|поилк|кормушк|переноск|лоток|домик')) return 'Зоотовары';
  /* №312: НОВЫЙ ГОД — строже. Решаем по самому товару (первая часть названия
     до запятой или «·»), а не по словам «новогодний подарок» в хвосте. Нож,
     доска, мебель, коврик с «новогодним» рисунком остаются в своих категориях.
     Искусственные ветки, денежное дерево, клён, овощные «гирлянды» — декор. */
  $h1 = mb_strtolower((string)$name); $p1 = preg_split('/,|·/u', $h1); $h1 = ' '.trim((string)($p1[0] ?? $h1)).' ';
  $hh = function($re) use ($h1) { return preg_match('/'.$re.'/u', $h1); };
  $otherType = $hh('нож|доск|мебел|стол|стул|полк|стойк|щ[её]тк|коврик|карт[аы]|кружк|чашк|посуд|кастрюл|сковород|полотенц|пижам|свитер|футболк|сумк|чехол|подушк|плед|шкаф|тарелк|игральн|бокал|салфет');
  $fullL = mb_strtolower((string)$name);
  $plant = (bool)preg_match('/листь|лист |денежн|фикус|кл[её]н|баньян|пальм|бонсай|монстер|эвкалипт|папоротник|золот[а-я]* ветк|красн[а-я]* ветк/u', $fullL);
  $nyStrong = $h('мишур|хлопушк|адвент|снегурочк|дед[а-я]* мороз|санта[ -]клаус|снеговик|щелкунчик|[её]лочн[а-я]* (игрушк|шар|украш|верхушк|звезд|подвеск)|новогодн[а-я]* (шар|игрушк|венок|декор|украшени|гирлянд|костюм|колпак|носок|[её]лк)|рождественск[а-я]* (венок|[её]лк|декор|украшени|носок|шар|гирлянд)');
  $nyTree = $hh('(^|[ «"(-])[её]лк|(^|[ «"(-])ель |искусственн[а-я]* ел') && !$plant;
  $nyGarl = $hh('гирлянд') && !$hh('овощ|фрукт|перц|кукуруз|виноград|листь|фонар|цвет[ы о]') ;
  $nyWord = $hh('новогодн|новый год|рождеств|снежинк');
  if (!$h('паркет|ламинат|в [её]лочку|узор [её]лочк|плитк') && !$otherType && ($nyStrong || $nyTree || $nyGarl || $nyWord))
    return 'Новый год';
  if ($h('накидк[а-я]*[^,·]{0,20}(парикмахер|стрижк)|накидк[а-я]* на плечи для стрижк|таз для мытья головы')) return 'Для салонов';
  $garden = $h('газон|для травы|куст|садов|живой изгород');
  $bathX = $h('подставк|полк[аи]|стакан|держател|полотенц|органайзер для ванн');
  if (!$salonFurn && !$petX && !$garden && !$giftSet && !$bathX && $h('ногт|маникюр|педикюр|гель-?лак|заколк|ободок|ободк|резинк[а-я]* для волос|невидимк|крабик|краб[- ]для волос|'
       . 'расч[её]ск|гребень|гребн|щ[её]тк[а-я]* для (волос|укладк)|браш|щипц[а-я]* для (завивк|волос)|плойк|выпрямител[а-я]* (для )?волос|'
       . 'утюжок для волос|бигуд|керлер|косметичк|для макияж|кист[а-я]* для (макияж|теней|пудр)|спонж|ресниц|для бровей|(^| )бров[а-я]* |'
       . 'массаж[её]р|фен для волос|фен-щ|триммер|машинк[а-я]* для стрижк|ножниц[а-я]*[^,·]{0,20}(парикмахер|для стрижк|для волос|филиров)|'
       . 'парикмахерск[а-я]* ножниц|окрашивани[а-я]* волос|для окрашивания волос|шапочк[а-я]* для (душ|волос)|тюрбан для волос|'
       . 'зеркал[а-я]* (косметич|для макияж)|эпилятор|для ухода за кожей|скребок для ног|пемз|зубн[а-я]* щ[её]т|для чистки ушей|'
       . 'массаж[а-я]* лица|для массажа лица|скребок-?чесалк|для волос|для стрижк|для укладк|шнур[а-я]* для волос|зажим[а-я]* для (волос|стрижк)|'
       . 'щ[её]тк[а-я]* для (усов|масок|лица)|косметическ|для макияжа')) return 'Красота и уход';
  if (!$giftSet && !$h('обогреват|для автомобил|автомобильн[а-я]* (обогрев|печ)') && $h('(^|[ «"(-])зонт|дождевик|наручн[а-я]* час|часы (наручн|мужск|женск|кварц|механич)|кошел[её]к|портмоне|ремень (кожан|мужск|женск|для брюк)|'
       . 'мужск[а-я]* ремень|женск[а-я]* ремень|шарф|платок|палантин|снуд|бандан|балаклав|солнцезащитн[а-я]* очк|очки солнцезащит|'
       . 'брелок|галстук|запонк|перчатк[а-я]* (кожан|зимн|женск|мужск|для сенсор)') && !$h('стойк[а-я]* для зонт|подставк[а-я]* для зонт|для зонтов|шезлонг|лежак|кушетк|диван|мебел|садов|уличн|для сада|террас|пляжн|стол|стул|кресл|навес|шат[её]р|для кафе|гриль'))
    return 'Аксессуары';
  if (!$petX && !$h('светильник|ламп|ночник|фигурк') && $h('брюк|штаны|футболк|куртк|кофт|свитер|худи|толстовк|пижам|кальсон|носк|колготк|шорты|комбинезон|жилет|'
       . 'шапк|кепк|панам|бейсболк|тапк|тапоч|кроссов|ботин|сапог|сандал|шл[её]п|туфл|сланц|кед[ыа]? |стельк|'
       . 'обувн[а-я]* ложк|ложк[а-я]* для обуви|для снятия обуви|рожок для обуви|(^| )обувь|домашн[а-я]* обув|дорожн[а-я]* обув') && !$h('чехол для|хранени|сушилк|полк|шкаф|вешалк|для обуви,|подставк'))
    return 'Одежда и обувь';
  if (!$petX && !$h('вешалк|подставк|чехол|коврик|подушк[а-я]* для|разделочн|доск|брелок') && $h('игрушк|плюшев|головоломк|пазл|настольн[а-я]* игр|игральн[а-я]* карт|покерн|карты для игры|кукл|радиоуправляем|'
       . 'конструктор|развивающ|погремушк|юла |кубик рубик|фигурк[а-я]* аниме'))
    return 'Игрушки и игры';
  if ($h('бизнес-?набор|корпоративн[а-я]* подар|набор[а-я]* для сотрудник|для ухода за сотрудник|подарочн[а-я]* открытк|аудиооткрытк'))
    return 'Подарки';
  if ($h('коврик') && !$h('для ванн|для мыш|для йог|для фитнес|автомоб|для машин|для кош|для собак|для животн|для туалет|для унитаз|для душ|кемпинг|туристич|надувн'))
    return 'Текстиль';
  /* ДЛЯ САЛОНОВ — ПЕРВЫМ ПРАВИЛОМ.
     Оборудование салонов красоты почти всегда называется через мебель:
     «кресло парикмахерское», «кушетка массажная», «мойка для волос»,
     «тележка мастера». Стой это правило ниже — кресла ушли бы в «Кресла»,
     кушетки в «Кровати», мойки в «Сантехнику», и салонный товар размазался
     бы по всему каталогу. Поэтому проверяем его раньше всех остальных. */
  /* СНАЧАЛА ОТСЕИВАЕМ ТОВАР ДВОЙНОГО НАЗНАЧЕНИЯ.
     Первый перенос забрал лишнее: «Рабочий стол … для салона красоты, КАФЕ ИЛИ
     МАГАЗИНА ОДЕЖДЫ» — обычный стол, «Шезлонг-трансформер для салонов красоты
     И ДОМА» — обычный диван. Такие названия сами говорят, что вещь не только
     салонная, и место ей там, где она была. Проверяем это ДО правила салонов,
     иначе оно заберёт их первым. */
  $dual = $h('и дома|или дома|для дома|кафе|ресторан|магазин[а-я]* одежд|офис[а-я]* и дом|дома и офис|гостин[а-я]* и салон');
  /* Для баров и гостиниц слова «кафе» и «ресторан» — свои, а не признак
     универсальности. Поэтому у них своя, более узкая проверка: отсекаем только
     то, что явно ещё и для дома. */
  $dualHome = $h('и дома|или дома|для дома|дома и офис|офис[а-я]* и дом|магазин[а-я]* одежд');

  /* ДЛЯ ГОСТИНИЦ. Проверяем раньше баров и салонов: гостиничная стойка
     ресепшен и тележка для багажа иначе уедут в мебель и в чемоданы. */
  if (!$dualHome && $h('гостиниц|отел[ья]|hotel|хостел|апарт[- ]?отел|'
       . 'тележк[а-я]*[^,·]{0,25}(багаж|чемодан)|багажн[а-я]* тележк|'
       . 'мини[- ]?бар|номер[а-я]* отел|для номеров|'
       . 'стойк[а-я]* ресепшен[а-я]* (для )?(отел|гостиниц)|ресепшн[а-я]* (отел|гостиниц)|'
       . 'сейф[а-я]* для (отел|номер|гостиниц)|карточн[а-я]* замок|'
       . 'держател[а-я]* для полотенец в номер|стойк[а-я]* для багаж')) return 'Для гостиниц';

  /* ДЛЯ РЕСТОРАНОВ. Сюда же бары, кафе и общепит — название короче, чтобы
     плитка в магазине не растягивалась. Проверяем раньше общей мебели: барный
     стул и стол для кафе иначе разойдутся по «Стульям» и «Столам». */
  if (!$dualHome && $h('барн[а-я]* (стойк|стул|табурет|мебел)|для бара|паб[а-я]* |'
       . 'ресторан|кафетери|кофейн[а-я]* (столик|мебел|оборудован)|фуд[- ]?корт|общепит|'
       . 'столов[а-я]* (для|общепит)|для кафе|'
       . 'витрин[а-я]*[^,·]{0,25}(выпечк|еды|салат|торт|кондитер|подогрев)|тепловая витрин|салат[- ]?бар|'
       . 'фритюрниц|блинниц[а-я]* профессиональн|шаурм|гриль[- ]?повер|'
       . 'кофемашин[а-я]* профессиональн|кофемолк[а-я]* профессиональн|'
       . 'поднос[а-я]* для (подач|ресторан)|менюхолдер|подставк[а-я]* для меню|'
       . 'диспенсер[а-я]* для (салфет|напитк)')) return 'Для ресторанов';

  /* ПОДАРКИ — тоже раньше остальных.
     «Подарочный набор для мужчин: ремень, кошелёк, часы» иначе разъезжается по
     аксессуарам, часам и сумкам, хотя продаётся как один подарок. Ловим только
     то, что подарком и продаётся: наборы, боксы, сувениры. Просто «подарочная
     упаковка» сюда НЕ идёт — это расходник, а не товар. */
  /* «Сувенир» иногда стоит в НАЗНАЧЕНИИ, а не в самом товаре: «Стальной
     книжный шкаф … для хранения сувениров» — это шкаф, а не подарок.
     Такие названия из правила исключаем. */
  $storeFor = $h('для хранени[а-я]* сувенир|хранени[а-я]* сувенир|под сувенир|для сувенир');

  if (!$storeFor && $h('подарочн[а-я]* (набор|бокс|коробк[а-я]* с|комплект|корзин)|набор в подарок|'
       . 'подар(ок|ки) (для |мужчин|женщин|мужу|жене|маме|папе|другу|коллег|начальник)|'
       . 'сувенир|gift ?(set|box)|подарочн[а-я]* сертификат|'
       . 'набор[а-я]* (для мужчин|для женщин)[а-я ,:]*(ремень|кошел|часы|парфюм|запонк)'))
    return 'Подарки';

  if (!$dual && $h('парикмахерск|барбер|barber|салон[а-я]* красот|для салон|бьюти|beauty ?salon|'
       . 'мойк[а-я]* для (волос|голов)|шампунь[- ]?кресл|мойк[а-я]* парикмахер|'
       . 'маникюрн|педикюрн|косметологическ|косметолог[а-я]* (кресл|кушетк|стол)|'
       . 'массажн[а-я]* (кушетк|стол|кровать|кресл|лежак|топчан)|кушетк|топчан|'
       . 'визажист|бров[а-я]* (стол|лампа)|лашмейкер|ламинировани[а-я]* ресниц|'
       . 'тележк[а-я]* (мастера|парикмахер|косметолог|для инструмент)|'
       . 'сушуар|климазон|стерилизатор[а-я]* для инструмент|сухожар|'
       . 'лампа для (маникюр|наращивани)|вытяжк[а-я]* для маникюр|'
       . 'подставк[а-я]* для ног|ванночк[а-я]* для (ног|педикюр)|'
       . 'зеркал[а-я]* (парикмахер|для салон|визажист|гримёрн|гримерн)|'
       . 'ресепшн[а-я]* для салон')) return 'Для салонов';
  if ($h('кольц|серьг|серёжк|сережк|колье|ожерель|цепоч|кулон|подвеск|брошь|браслет|бижутери|украшени|жемчужн|шкатулк[а-я]* для украшен')) return 'Украшения';
  /* Исключения к «Посуде»: слова «посуда» и «жаровня» встречаются у товаров,
     которые посудой не являются — сушилки, полотенца, садовые очаги. */
  /* ОФИСНАЯ МЕБЕЛЬ идёт ПЕРВОЙ: шкаф и картотека для документов — это мебель,
     а не принадлежности, иначе правило ниже забрало бы их себе. */
  if ($h('офисн[а-я]* (кресл|стул|стол|мебель|шкаф|перегородк|диван)|кресл[а-я]* руководител|стойка ресепшен|ресепшн|картотечн[а-я]* шкаф|шкаф[а-я]* для документ|стеллаж[а-я]* для документ')) return 'Офисная мебель';
  /* ОФИСНЫЕ ПРИНАДЛЕЖНОСТИ. Папки, лотки и органайзеры для документов уходили
     в «Хранение и уборку» по слову «органайзер» — а место им в офисе. */
  if ($h('документ|папк[а-я]* (для|с) |файл[а-я]* для бумаг|лоток для бумаг|органайзер[а-я]* для (бумаг|канцеляр|стол)|картотек|визитниц|бейдж|штемпел|печат[а-я]* оснастк|планшет с зажим|скоросшиват|архивн[а-я]* короб')) return 'Офисные принадлежности';
  /* Мебель для ванной — это Сантехника, а не Тумбы: правило «тумб» стоит
     ниже и забирало «Тумбу для ванной с раковиной и смесителем». */
  if ($h('тумб[а-я]* (для ванн|с раковин|с умывальник)|пенал для ванн|мебель для ванн|шкаф[а-я]* для ванн|столешниц[а-я]* для ванн')) return 'Сантехника';
  /* Сушилки поднимаем в самое начало: в их названиях часто есть «опора для
     обуви», а правило «для обуви» ниже забирало их в Обувницы. */
  if ($h('сушилк[а-я]* для (одежд|бель|посуд)|сушилк[а-я]* напольн|сушилк[а-я]* для посуд|полотенц[а-я]* для посуд|кухонн[а-я]* полотенц|губк[а-я]* для посуд|моющее для посуд|подставк[а-я]* для сушк')) return 'Хранение и уборка';
  if ($h('садов[а-я]* камин|камин-жаровн|жаровн[а-я]* для сада|очаг для сада|кострищ|чаша для костр')) return 'Сад и дача';
  if ($h('посуд|сервиз|столов(ый|ые|ых) прибор')) return 'Посуда';
  if ($h('органайзер|кофр|короб для хранен|ящик для хранен|вакуумн(ый|ые) пакет|крючк[а-я]* для (ванн|одежд|полотенц|кухн|сумк|ключ|штор)|крючок для (ванн|одежд|полотенц|кухн)|самоклеющ[а-я]* крючк|настенн[а-я]* крючк|держател[а-я]* самоклеющ')) return 'Хранение и уборка';
  if ($h('журнальн'))                                   return 'Стол журнальный';
  if ($h('обувниц|для обуви|обувная|стойка для обуви')) return 'Обувницы';
  if ($h('вешалк|стойка для одежды|плечик|напольная вешалк')) return 'Вешалки';
  if ($h('матрас'))                                     return 'Матрасы';
  if ($h('диван|софа|кушетк|канапе'))                   return 'Диваны';
  if ($h('манеж|детск|кроватк|пеленаль|игрушк|плюшев|конструктор|коляск|автокресл'))  return 'Детская';
  if ($h('комод'))                                      return 'Комоды';
  if ($h('тумб'))                                       return 'Тумбы';
  if ($h('кроват|спальное место|двуспальн|односпальн')) return 'Кровати';
  if ($h('гардероб|шкаф|купе'))                         return 'Шкафы';
  if ($h('стеллаж|этажерк|полк'))                       return 'Стеллажи и полки';
  if ($h('компьютерн(ый|ые)? стол|письменн(ый)? стол|рабочий стол|туалетн(ый)? стол|комплект мебели|мебельн(ый)? комплект|обеденн(ая|ые)? групп')) return 'Столы';
  if ($h('табурет|стул'))                               return 'Стулья';
  if ($h('кресл'))                                      return 'Кресла';
  if ($h('пуф|банкетк'))                                return 'Пуфы';
  if ($h('трельяж|зеркал'))                                     return 'Зеркала';
  if ($h('светильник|люстр|торшер|освещени| лампа|ночник| бра ')) return 'Освещение';
  // --- ХОЗЯЙСТВЕННЫЕ ТОВАРЫ И ТЕХНИКА (добавлено под каталог 1688) ---
  // Стоит ДО «кухн» и «стол», иначе «столовые приборы» уедут в мебель,
  // а «кухонная посуда» — в кухонные гарнитуры.
  if ($h('столов(ый|ые|ых) прибор|ложк|ложек|вилк|вилок|нож(и|ей)? кухон|набор ножей|поварёшк|половник|лопатк[а-я]* кухон')) return 'Посуда';
  if ($h('посуд|тарел|блюдц|блюдо|миск|мисок|салатник|пиал|сервиз|супниц|соусник|сахарниц|маслёнк|маслёнок|хлебниц|чайн(ый|ые)? набор|для чаепити|сервировочн')) return 'Посуда';
  if ($h('кружк|кружек|чашк|чашек|стакан|бокал|фужер|рюмк|рюмок|графин|кувшин|термокружк|термос[а-я]{0,2}[ ,]')) return 'Посуда';
  if ($h('кастрюл|сковород|сотейник|казан|вок |жаровн|противень|форма для выпечк|дуршлаг|тёрк|терка кухон')) return 'Посуда';
  if ($h('разделочн(ая|ые)? доск|контейнер для (еды|продукт)|ланч-?бокс|судок')) return 'Посуда';

  if ($h('электрочайник|чайник электр|блендер|миксер|кофеварк|кофемашин|тостер|мультиварк|пароварк|соковыжималк|мясорубк|кухонн(ый|ая) комбайн|вафельниц|микроволнов')) return 'Бытовая техника';
  if ($h('пылесос|увлажнител|осушител|очистител воздуха|аэрогриль|вентилятор|обогреват|конвектор|тепловентилятор|кондиционер')) return 'Бытовая техника';
  if ($h('утюг|отпариват|фен |машинка для стрижк|эпилятор|электробритв|весы (напольн|кухонн)')) return 'Бытовая техника';
  if ($h('чайник|турк(а|и)|френч-?пресс|заварник|кофеварка гейзерн')) return 'Посуда';

  if ($h('сушилк[а-я]* для (одежд|бель)|сушилка для одежд|гладильн(ая)? доск|бельев(ая)? верёвк|прищепк')) return 'Хранение и уборка';
  if ($h('органайзер|кофр|короб для хранен|ящик для хранен|корзин[а-я]* для (бель|игрушек|хранен)|вакуумн(ый|ые) пакет|чехол для одежд')) return 'Хранение и уборка';
  if ($h('швабр|ведро|щётк[а-я]* для уборк|щетка для уборк|совок|мусорн(ое|ый|ая)|тряпк|салфетк[а-я]* для уборк|перчатк[а-я]* хозяйств')) return 'Хранение и уборка';

  /* САНТЕХНИКА — про установку и подключение к воде. Ставим ВЫШЕ «Ванной»:
     та про обстановку (коврики, шторки, дозаторы), а это про трубы. */
  if ($h('унитаз|биде|писсуар|инсталляц|раковин|умывальник|мойка кухонн|сифон|смесител|кран для| душ | душ,| душ в комплект|тропическ(ий)? душ|душев(ая|ой) кабин|поддон душев|держател(ь|я)? для душ|лейк(а|и)? для душ|душев(ая|ой) систем|излив|ванна (акрилов|чугунн|стальн)|бойлер|водонагреват|полотенцесушител|фильтр для воды|насос(ная)? станц|гофр|шланг для (воды|душ)')) return 'Сантехника';
  /* ЭНЕРГЕТИКА — автономное питание. Отдельно от бытовой техники: это не
     кухонный прибор, а источник тока, и покупатель ищет его по своему. */
  if ($h('генератор|электростанц|источник питания|блок питания|аккумуляторн(ый)? блок|зарядн(ая)? станц|повербанк на|аккумулятор(ная)? станц|внешн[а-я]* аккумулятор|портативн(ый|ая) (внешний )?аккумулятор|солнечн(ая|ые)? панел|солнечн(ый)? модул|инвертор|стабилизатор напряж|акб |lifepo4|бесперебойн')) return 'Энергетика';
  if ($h('коврик для ванн|занавеск[а-я]* для душ|штор(а|ы) для ванн|дозатор|мыльниц|держател[а-я]* для туалетн|ёршик|ершик|полотенцесушител|смесител|душев(ая|ой)|лейка для душ')) return 'Ванная';

  if ($h('мангал|шашлычниц|шезлонг|гамак|качел|качалк|москитн|уличн[а-я]* (камин|очаг|печ)|переносн[а-я]* очаг|садов(ая|ый|ые)|уличн(ая|ые)? мебель|мебель для (сада|дачи|террас)|ротанг|теплиц|лейк[а-я]* для полив|шланг поливочн|секатор|грабл|тяпк|палатк|туристическ')) return 'Сад и дача';

  if ($h('дрель|шуруповёрт|шуруповерт|отвёртк|отвёрток|отвертк|отверток|крючк[а-я]*-захват|захват[а-я]* для ремонт|съёмник|съемник|для ремонта (бытовой )?техник|гаечн[а-я]* ключ|обжимн|шлем[а-я]* (для )?сварщик|маск[а-я]* сварщик|сварочн|лестниц|подставк[а-я]* для инструмент|тиск|напильник|зубил|перфоратор|болгарк|лобзик|пил(а|ы) |молоток|плоскогубц|пассатиж|набор инструмент|рулетк[а-я]* измерит|уровень строит|стремянк')) return 'Инструменты';

  if ($h('гантел|штанг|тренажёр|тренажер|коврик для йог|скакалк|эспандер|фитнес-?резинк|турник|боксёрск|боксерск|велосипед|самокат|ролик')) return 'Спорт и отдых';

  if ($h('чемодан|рюкзак|сумк|барсетк|кошелёк|кошелек|портфель')) return 'Сумки и чемоданы';
  if ($h('рукодели|игольниц|швейн[а-я]* (набор|принадлежност|машин)|набор для (шить|вышив|вязан|рисован|лепк|творчеств)|мулине|пряж[а-я]* для вязан|спиц[а-я]* для вязан|крючок для вязан|алмазн[а-я]* мозаик|пазл')) return 'Хобби и творчество';
  if ($h('канцеляр|тетрад|ручк[а-я]* шариков|шариков[а-я]* ручк|карандаш|пенал|блокнот|скотч|степлер|маркер|фломастер|альбом для|визитниц|держател[а-я]* для карт')) return 'Канцелярия';

  if ($h('наушник|зарядн(ое|ая)|кабель usb|повербанк|пауэрбанк|павербанк|power ?bank|держател для телефон|штатив|селфи-?палк|колонк bluetooth|умн(ая|ые) колонк|мышь компьютерн|клавиатур|коврик для мыш|веб-?камер')) return 'Электроника';

  if ($h('канистр|бак для (бензин|топлив|масл|дизел)|бензобак|бочка для (масл|бензин|топлив)|насадка для масла|автомобильн|для авто|для мытья машин|мойк(а|и) авто|чехл(ы|ов)? на сидень|видеорегистратор|компрессор автомоб|щётк стеклоочистител|автохолодильник')) return 'Автотовары';

  if ($h('для кошек|для собак|когтеточк|лежанк[а-я]* для (кошк|собак|животн)|поилк[а-я]* для (кошк|собак|животн)|переноск[а-я]* для (кошк|собак|животн)|лоток для кошек|аквариум|клетк[а-я]* для (птиц|грызун)')) return 'Зоотовары';

  if ($h('кухн|кухон|обеденн|барн'))                    return 'Кухня';
  if ($h('одеял|пододеяльник|простын|наволочк|постельн|наматрасник|комплект бель')) return 'Текстиль';
  if ($h('шарф|снуд|косынк|банн[а-я]* шапочк|штор|ковер|ковёр|ковр|плед|подушк|скатерт|текстиль|покрывал|полотенц|тюль|занавес')) return 'Текстиль';
  if ($h('искусственн[а-я]*( [а-я]+)? (пальм|ёлк|елк|дерев|растен|фикус|лист|трав|цвет)|копилк|ваза|вазон|кашпо|горшок для (цвет|растен)|картин|панно|статуэтк|декор|часы настен|подсвечник|рамка для фото|фоторамк|гирлянд|искусственн(ые)? цвет')) return 'Декор';
  if ($h('стол'))                                       return 'Столы';
  return itc_cat_v2_rescue($h);
}
/* №293: ПОСЛЕДНИЙ ШАНС ДЛЯ «ПРОЧЕГО». Эти товары должны были попасть в уже
   существующие категории, но прежние правила их не узнавали. */
function itc_cat_v2_rescue($h) {
  if ($h('нож[а-я]* |нож$|разделочн')) return 'Кухня';
  if ($h('набор[а-я]* мебел|комплект[а-я]* мебел')) return 'Столы';
  if ($h('перстен|кольц')) return 'Украшения';
  if ($h('халат')) return 'Текстиль';
  if ($h('ванн[а-я]* чаш|стойк[а-я]* для ванн')) return 'Ванная';
  if ($h('стойк[а-я]* для (хранени|зонт|шап|головн|купальн)|стойк[а-я]* для зонт|пакет[а-я-]*[^,·]{0,15}(застёжк|застежк|молни|для одежд)|чехол-мешок|'
       . 'корзин[а-я]* для мусор|урна|вешалок|вешалк|контейнер для (витамин|таблет)|поддон для стиральн|насадка-поддон|губк[а-я]* для уборк')) return 'Хранение и уборка';
  if ($h('искусствен|имитаци[а-я]* пальм|пальм|лимонное дерево|модел[ьи][- ](реплик|овощ|фрукт)|модель овощ|свеч|канделябр|муляж|гранат')) return 'Декор';
  if ($h('ручк[аи]([ ,.]|$)|линейк|зажим[а-я]* для файл|раскраск|дневник|подарочн[а-я]* коробк|коробк[а-я]* (подароч|для мелоч|для электрон)|упаковк[а-я]* для одежд')) return 'Канцелярия';
  if ($h('инструмент|станок|валик[а-я]* для покраск|для защиты стен при покраск|фрез|маслян[а-я]* (маркерн|марокерн) крас')) return 'Инструменты';
  if ($h('поломоечн|робот-мойщик|весы')) return 'Бытовая техника';
  if ($h('солнечн[а-я]* панел|газов[а-я]* баллон')) return 'Энергетика и отопление';
  if ($h('термоконтейнер|термос|кофейн[а-я]* (набор|cup|чашк)|кофейник|cup')) return 'Посуда';
  if ($h('садов|костр|курятник|шат[её]р')) return 'Сад и дача';
  if ($h('бассейн|спортивн[а-я]* инвентар')) return 'Спорт, туризм и отдых';
  if ($h('умн[а-я]* замок|мотор для жалюзи|зарядн')) return 'Электроника';
  if ($h('кемпинг|поход|туристич|рыбалк|рыболов|палатк|спальн[а-я]* мешок|удилищ|снаст|фонар[а-я]* (кемпинг|налобн)')) return 'Спорт, туризм и отдых';
  if ($h('печь|печк|камин|буржуйк|дров|для обогрева')) return 'Энергетика и отопление';
  if ($h('насос|помп[аы]')) return 'Энергетика и отопление';
  if ($h('ручк[а-я]* |ручка$|маркер|блокнот|ежедневник|тетрад|скотч|клейк[а-я]* лент|упаковочн|коробк[а-я]* для (конфет|подар|упаков)|'
       . 'разделител[а-я]* для папок|папк|открытк|визитк|альбом для|наклейк')) return 'Канцелярия';
  if ($h('тележк|аптечк|контейнер для таблеток|таблетниц|кронштейн для сушки|сушилк|стойк[а-я]* для (сушки|вешания|купальн)|чехол для (костюм|одежд)|сундуч')) return 'Хранение и уборка';
  if ($h('подстилк|циновк|летн[а-я]* коврик')) return 'Текстиль';
  if ($h('кусачк|ключ[а-я]* |ключ$|рулетк|клещ|плоскогубц|пассатиж|электрод|резак|паяльник|лак для пола|ультразвуков[а-я]* мойк')) return 'Инструменты';
  if ($h('опрыскивател|лейк|для растений|для цветов|полив|беседк|навес|скамейк|гриль|барбекю|удобрен|снегоубор')) return 'Сад и дача';
  if ($h('статуэтк|фигурк|талисман|аромакурител|благовон|кубок|копилк|муляж|модель-?копи')) return 'Декор';
  if ($h('салатниц|щипц[а-я]* для (кревет|кухн|салат)|кофемолк')) return 'Кухня';
  if ($h('розетк|удлинител')) return 'Электроника';
  return 'Прочее';
}
/* Переименования и объединения категорий (решение 06.10.2026) */
function itc_cat_v2_rename($c) {
  static $m = ['Спорт и отдых'=>'Спорт, туризм и отдых', 'Энергетика'=>'Энергетика и отопление',
               'Полка для обуви'=>'Обувницы', 'Офисные принадлежности'=>'Канцелярия'];
  return $m[$c] ?? $c;
}
function itc_store_category($name) { return itc_cat_v2_rename(itc_store_category_base($name)); }

