  $c = itc_cat_v2_rename((string)$cat);
  if (empty($R[$c])) return '';
  $head = (string)$name; $cut = mb_strpos($head, '·'); if ($cut !== false && $cut > 8) $head = mb_substr($head, 0, $cut);
  $t = ' '.mb_strtolower($head).' ';
  foreach ($R[$c] as $r) if (preg_match('/'.$r[1].'/u', $t)) return $r[0];
  return '';
}
/* То же, но с заглядыванием в описание. Описание берём ТОЛЬКО если по
   названию ничего не вышло: длинный текст легко даёт ложные срабатывания
   («подходит для кухни и спальни» утащило бы товар в мебель). */
function itc_store_category_deep($name, $descr = '') {
  $c = itc_store_category($name);
  if ($c !== 'Прочее') return $c;
  $d = trim((string)$descr);
  if ($d === '') return 'Прочее';
  return itc_store_category($name.' '.mb_substr($d, 0, 400));
}

// Вычислить объём из строки габаритов "30x20x10 cm"
function pdd_dims_to_volume($dims_str) {  if (!$dims_str) return null;
  if (preg_match('/([\d\.]+)\s*[xX×*]\s*([\d\.]+)\s*[xX×*]\s*([\d\.]+)\s*(cm|см|mm|мм)?/u', $dims_str, $m)) {
    $unit = strtolower($m[4]??'cm');
    $factor = ($unit==='mm'||$unit==='мм') ? 0.001 : 0.01; // мм→м или см→м
    return round((float)$m[1]*$factor * (float)$m[2]*$factor * (float)$m[3]*$factor, 6);
  }
  return null;
}
// ============================================================

/* ПРОВЕРКА ТОВАРА 1688 — И НАЛИЧИЕ, И ЦЕНА (25.08.2026).
   Было: открывали страницу обычным запросом и искали слова «снято с продажи».
   Цену так взять нельзя — 1688 отдаёт её скриптами, в тексте страницы её нет.
   Стало: спрашиваем API, оттуда сразу и жив ли товар, и цены всех вариантов.
   Цену берём ПО СВОЕМУ варианту (ob_variant_price), а не минимальную по карточке. */
function ds_check_1688_api($url, $product_id) {
  if (!preg_match('/offer\/(\d+)/', (string)$url, $m)) return null;
  $off = ob_offer_sku_prices($m[1]);
  if (!is_array($off)) return ['available'=>false, 'status'=>'no_answer', 'http_code'=>0];
  if (!empty($off['err'])) {
    /* ВАЖНО: сбой сети или самого посредника — НЕ повод считать товар снятым.
       Иначе одна авария у onebound отправила бы в архив весь каталог.
       Пропажей считаем только честный ответ «товар не найден» (код 2000). */
    $err = (string)$off['err'];
    if ($err === '2000') return ['available'=>false, 'status'=>'removed', 'http_code'=>0];
    return ['available'=>true, 'status'=>'skip_'.$err, 'http_code'=>0, 'variant_exact'=>true];
  }
  if ($off['min'] === null && (int)$off['n'] === 0) {
    /* НАЙДЕНО НА ПРОВЕРКЕ 25.08.2026: посредник иногда отдаёт карточку
       урезанной — без цены и без вариантов, и при этом без признака ошибки.
       Через 4 минуты та же карточка пришла полной. Считать такой ответ
       «товар снят» нельзя: живой товар уехал бы в архив, а на 36 тысячах
       товаров это массовый ложный снос. Пропало — только по коду 2000. */
    return ['available'=>true, 'status'=>'empty_answer', 'http_code'=>0, 'variant_exact'=>true];
  }
  $vp = ob_variant_price($product_id, $off);
  $res = ['available'=>true, 'status'=>'ok', 'http_code'=>200, 'variant_exact'=>!empty($vp['exact'])];
  if ($vp['price'] !== null && !empty($vp['exact'])) $res['price_cny'] = $vp['price'];
  return $res;
}
function ds_check_url($url,$platform){
  $result=['available'=>true,'status'=>'ok','http_code'=>0];
  if(!$url) return ['available'=>false,'status'=>'no_url','http_code'=>0];
  $ctx=stream_context_create(['http'=>['timeout'=>8,'method'=>'GET',
    'header'=>"User-Agent: Mozilla/5.0 (compatible; ITC-Monitor/1.0)\r\n",
    'follow_location'=>1,'max_redirects'=>3]]);
  try {
    $body=@file_get_contents($url,false,$ctx);
    $code=0;
    if(isset($http_response_header)){
      foreach($http_response_header as $h){
        if(preg_match('/HTTP\/[\d.]+ (\d+)/',$h,$m)) $code=(int)$m[1];
      }
    }
    $result['http_code']=$code;
    if(in_array($code,[404,410,403])){ $result['available']=false; $result['status']='http_'.$code; return $result; }
    $nfp=['1688'=>['该商品已下架','商品不存在','item has been removed','已下架'],
          'pdd' =>['该商品已下架','商品不存在','找不到该商品']];
    $pats=$nfp[$platform]??array_merge(...array_values($nfp));
    if($body!==false){
      $bl=mb_strtolower(substr($body,0,8000));
      foreach($pats as $pat){ if(mb_strpos($bl,mb_strtolower($pat))!==false){ $result['available']=false; $result['status']='removed'; return $result; } }
    } elseif($code===0){ $result['available']=false; $result['status']='connect_error'; }
  } catch(Exception $e){ $result['available']=false; $result['status']='exception'; }
  return $result;
}
function ds_sync_product_price($ds_id) {
  // Единая точка: пересчитывает our_price_rub и обновляет products.price
  // Если old_price не задан — устанавливает рекомендованную цену (без скидки)
  try {
    $dp = db()->prepare('SELECT product_id, source_price_cny, declared_volume_m3, declared_weight_kg, old_price_rub, x3_pending, x3_mult FROM ds_products WHERE id=?');
    $dp->execute([$ds_id]); $dp = $dp->fetch();
    if (!$dp) return;
    $pcny  = (float)($dp['source_price_cny']   ?? 0);
    $dvol  = (float)($dp['declared_volume_m3']  ?? 0);
    $dwt   = (float)($dp['declared_weight_kg']  ?? 0);
    $pid   = $dp['product_id'] ?? '';
    $oldPriceRub = (int)($dp['old_price_rub'] ?? 0);
    if (!$pid) return;
    // Режим ×N: цена по себестоимости × множитель (объём/вес не нужны, до замера на складе)
    if (!empty($dp['x3_pending']) && $pcny > 0) {
      $prub = ds_calc_price_x3($pcny, (isset($dp['x3_mult']) && $dp['x3_mult'] > 0) ? (float)$dp['x3_mult'] : null);
      db()->prepare('UPDATE ds_products SET our_price_rub=?, price_changed=0 WHERE id=?')->execute([$prub, $ds_id]);
      $oldPrub = ($oldPriceRub > $prub) ? $oldPriceRub : 0;
      db()->prepare('UPDATE products SET price=?, old_price=?, blocked=0 WHERE id=?')->execute([$prub, $oldPrub, $pid]);
      return;
    }
    if ($pcny > 0 && $dvol > 0) {
      $prub = ds_calc_price_rub($pcny, $dvol, $dwt);
      db()->prepare('UPDATE ds_products SET our_price_rub=?, price_changed=0 WHERE id=?')
           ->execute([$prub, $ds_id]);
      // old_price: если задана старая цена DS → показываем скидку покупателям
      $oldPrub = ($oldPriceRub > $prub) ? $oldPriceRub : 0;
      db()->prepare('UPDATE products SET price=?, old_price=?, blocked=0 WHERE id=?')
           ->execute([$prub, $oldPrub, $pid]);
    } else {
      db()->prepare('UPDATE ds_products SET our_price_rub=NULL WHERE id=?')
           ->execute([$ds_id]);
      db()->prepare('UPDATE products SET blocked=1 WHERE id=?')
           ->execute([$pid]);
    }
  } catch (Exception $e) {}
}

function ds_calc_price_rub($goods_cny, $vol_m3, $wt_kg = 0) {
  // Зеркало JS-функции calcLandedRub — та же формула категории C (сборный груз)
  $st = get_settings();
  $n = function($k, $d) use ($st) { return isset($st[$k]) && is_numeric($st[$k]) ? (float)$st[$k] : $d; };
  $kc = $n('kurs_cny', 13.2);  $ku = $n('kurs_usd', 95);
  // Дропшиппинг выкупает Jinjia -> её прибыль ложится в себестоимость
  $goods_cny = $goods_cny * (1 + $n('jinjia_fee', 3) / 100);
  $dr = $n('duty', 10) / 100;  $vr = $n('vat', 22) / 100;
  $station = $n('station', 150000);  $broker = $n('broker', 35000);
  $delivery = $n('delivery', 250000);  $tr = $n('transfer', 3) / 100;
  $cv = $n('cont_vol', 68);  $cw = $n('cont_weight', 26800);
  $fu = $n('freight_usd', 10000);  $gm = $n('goods_markup', 25) / 100;
  $coef = $n('coef', 2.0);
  $wt_kg = (float)($wt_kg ?: 0);
  $share_vol = $cv > 0 ? (float)$vol_m3 / $cv : 0;
  $share_wt  = ($cw > 0 && $wt_kg > 0) ? $wt_kg / $cw : 0;
  $share = max($share_vol, $share_wt);
  $T = (float)$goods_cny * $kc;
  $duty = $T * $dr;  $vatG = $T * $vr;
  $vatF = (($fu * $ku * $share) / 2) * $vr;
  $b1  = ($T + $duty + $vatG + $vatF) * (1 + $gm);
  $b2u = $fu * $share * $coef;
  $b2r = ($station + $broker + $delivery) * $share * $coef;
  return (int)round(($b1 + $b2r) * (1 + $tr) + $b2u * (1 + $tr) * $ku);
}

// ===== Цена по кнопке ×3 =====
// Себестоимость для РФ = закупка × (1 + прибыль Джинджи). На неё:
//   ×N (множитель x3_mult — вся логистика, брокер и маржа уже внутри)
//   + пошлина + НДС + перевод денег в Китай.
// Объём/вес НЕ участвуют — это временная цена «пока не померили на складе».
function ds_calc_price_x3($goods_cny, $mult = null) {
  $st = get_settings();
  $n = function($k, $d) use ($st) { return isset($st[$k]) && is_numeric($st[$k]) ? (float)$st[$k] : $d; };
  $kc = $n('kurs_cny', 13.2);
  $jf = $n('jinjia_fee', 3) / 100;
  $dr = $n('duty', 10) / 100;  $vr = $n('vat', 22) / 100;  $tr = $n('transfer', 3) / 100;
  $mult = ($mult !== null && is_numeric($mult) && $mult > 0) ? (float)$mult : $n('x3_mult', 4);
  $inv_rub = (float)$goods_cny * (1 + $jf) * $kc;   // инвойс = себестоимость для РФ
  return (int)round($inv_rub * ($mult + $dr + $vr + $tr));
}

/* Стоит ли карточка на множителе ×N.
   Вернёт null — цена считается по объёму и весу (обычная карточка).
   Вернёт число > 0 — множитель из ds_products; 0 — на множителе, но значение
   не задано, тогда берётся настройка по умолчанию.
   Нужна, чтобы при сохранении карточки не требовать объём: при цене по
   множителю объём приезжает после замера на складе. */
/* ОДНА АКЦИЯ — МНОГО QR-КОДОВ.
   Раньше привязка хранилась НА АКЦИИ (колонка promos.mkt_tag), поэтому акция
   физически могла держать только один код: стоило привязать её ко второму QR,
   как первый отваливался. Регионов много, статистику надо считать по каждому
   отдельно, а акция при этом одна на всех. Поэтому привязка переехала НА САМ
   QR-код: у каждого кода своя акция, а сколько кодов ведут на одну акцию —
   не ограничено. Старые привязки переносятся один раз, при первом вызове. */
function itc_mkt_promo_ensure() {
  static $done = false;
  if ($done) return;
  $done = true;
  try {
    db()->query("ALTER TABLE mkt_campaign ADD COLUMN promo_id VARCHAR(40) NULL");
    // колонки не было — значит переносим то, что успели привязать по-старому
    try { db()->query("UPDATE mkt_campaign c JOIN promos p ON p.mkt_tag=c.tag SET c.promo_id=p.id"); } catch (Exception $e) {}
  } catch (Exception $e) {}
}
/* Какие QR-коды ведут на каждую акцию: id акции => список кодов. */
function itc_promo_tags() {
  itc_mkt_promo_ensure();
  $by = [];
  try {
    foreach (db()->query("SELECT tag, promo_id FROM mkt_campaign WHERE promo_id IS NOT NULL AND promo_id<>''")->fetchAll() as $r) {
      $by[$r['promo_id']][] = $r['tag'];
    }
  } catch (Exception $e) {}
  return $by;
}


function itc_x3_mult_of_product($pid) {
  if (!$pid) return null;
  try {
    $q = db()->prepare('SELECT x3_pending, x3_mult FROM ds_products WHERE product_id=? ORDER BY id DESC LIMIT 1');
    $q->execute([$pid]);
    $r = $q->fetch();
    if (!$r || empty($r['x3_pending'])) return null;
    return (isset($r['x3_mult']) && $r['x3_mult'] > 0) ? (float)$r['x3_mult'] : 0.0;
  } catch (Exception $e) { return null; }
}

/* АРХИВ ПРОПАВШИХ ТОВАРОВ (25.08.2026, решение Алексея).
   Раньше пропавший товар просто вставал на паузу и лежал так вечно.
   Теперь: пропал → архив с датой → переспрос через неделю → ещё через неделю.
   Ожил — сам вернулся на витрину. Не ожил за две недели: если товар НИКОГДА
   не покупали, он удаляется вместе с витринной карточкой; если покупали хоть
   раз — остаётся в архиве навсегда, чтобы не рвать старые заказы.
   Всё без участия человека — менеджеров на это нет. */
function ds_archive_cols() {
  static $done = false; if ($done) return; $done = true;
  // когда пропал впервые
  try { db()->query("ALTER TABLE ds_products ADD COLUMN gone_at DATETIME NULL"); } catch (Exception $e) {}
  // сколько раз переспрашивали после пропажи (0,1,2)
  try { db()->query("ALTER TABLE ds_products ADD COLUMN gone_tries TINYINT NOT NULL DEFAULT 0"); } catch (Exception $e) {}
  // когда переспрашивали в последний раз
  try { db()->query("ALTER TABLE ds_products ADD COLUMN gone_last_try DATETIME NULL"); } catch (Exception $e) {}
  // итог: to_delete — ждёт удаления, dead/kept — оставлен из-за истории заказов
  try { db()->query("ALTER TABLE ds_products ADD COLUMN gone_result VARCHAR(16) NULL"); } catch (Exception $e) {}
  // КАРАНТИН: приговор выносится сразу, а исполняется через месяц (решение Алексея 25.08.2026)
  try { db()->query("ALTER TABLE ds_products ADD COLUMN gone_delete_at DATETIME NULL"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE ds_products ADD INDEX idx_gone (gone_at, gone_tries)"); } catch (Exception $e) {}
}
/* Покупали ли этот товар хоть раз — от этого зависит, удалять или хранить.
   Проверяем ТРИ места: состав заказов, заявки на выкуп и живые корзины
   покупателей. Корзина важна не меньше заказа: удалить товар, который у
   человека лежит в корзине, — значит сломать её у него на глазах. */
function ds_was_ever_ordered($product_id) {
  $product_id = trim((string)$product_id);
  if ($product_id === '') return false;
  foreach ([
    "SELECT COUNT(*) FROM order_items WHERE product_id=?",
    "SELECT COUNT(*) FROM ds_procurement WHERE product_id=?",
  ] as $sql) {
    try { $q = db()->prepare($sql); $q->execute([$product_id]); if ((int)$q->fetchColumn() > 0) return true; }
    catch (Exception $e) { /* таблицы может не быть — пробуем следующую */ }
  }
  // корзины хранятся строкой JSON — ищем по вхождению кода товара
  try {
    $q = db()->prepare("SELECT COUNT(*) FROM carts WHERE items LIKE ?");
    $q->execute(['%"'.$product_id.'"%']);
    if ((int)$q->fetchColumn() > 0) return true;
  } catch (Exception $e) {}
  return false;
}

function ds_apply_check_result($dp,$result){
  $now=date('Y-m-d H:i:s');
  if($result['available']){
    // Если мониторинг вернул новую цену — пересчитываем по формуле ИТК
    $newCny=isset($result['price_cny'])&&$result['price_cny']>0?(float)$result['price_cny']:null;
    $oldCny=(float)($dp['source_price_cny']??0);
    if($newCny&&abs($newCny-$oldCny)>0.01){
      try{
        db()->prepare('UPDATE ds_products SET source_price_cny=?,price_changed=1,last_check_at=?,check_fail_count=0 WHERE id=?')
          ->execute([$newCny,$now,$dp['id']]);
        // Пересчёт по формуле ИТК + синхронизация с каталогом покупателей
        ds_sync_product_price($dp['id']);
        $newRub=null;try{$r2=db()->prepare('SELECT our_price_rub FROM ds_products WHERE id=?');$r2->execute([$dp['id']]);$newRub=(int)($r2->fetch()['our_price_rub']??0);}catch(Exception $e){}
        $lid='ds'.substr(md5(uniqid('',true)),0,12);
        db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$dp['id'],'check_ok','Цена: ¥'.$oldCny.' → ¥'.$newCny.($newRub?' / ₽'.$newRub:'')]);
      }catch(Exception $e){}
    } else {
      try{ db()->prepare('UPDATE ds_products SET source_available=1,last_check_at=?,check_fail_count=0 WHERE id=?')->execute([$now,$dp['id']]); }catch(Exception $e){}
      try{ $lid='ds'.substr(md5(uniqid('',true)),0,12); db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$dp['id'],'check_ok','HTTP '.$result['http_code']]); }catch(Exception $e){}
    }
  } else {
    ds_archive_cols();
    $fails=(int)($dp['check_fail_count']??0)+1;
    try{ db()->prepare('UPDATE ds_products SET source_available=0,last_check_at=?,check_fail_count=? WHERE id=?')->execute([$now,$fails,$dp['id']]); }catch(Exception $e){}
    try{ $lid='ds'.substr(md5(uniqid('',true)),0,12); db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$dp['id'],'check_fail',$result['status']]); }catch(Exception $e){}
    if($fails>=2){
      try{
        db()->prepare("UPDATE ds_products SET ds_status='paused_auto',pause_reason=?,paused_at=? WHERE id=? AND ds_status='active'")
          ->execute(['Автопауза: товар снят на источнике',$now,$dp['id']]);
        if(!empty($dp['product_id'])) db()->prepare("UPDATE products SET blocked=1 WHERE id=?")->execute([$dp['product_id']]);
        // в архив — с этого дня пойдёт отсчёт двух недель на переспрос
        db()->prepare("UPDATE ds_products SET gone_at=COALESCE(gone_at,?), gone_last_try=? WHERE id=?")->execute([$now,$now,$dp['id']]);
        $lid2='ds'.substr(md5(uniqid('',true)),0,12);
        db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid2,$dp['id'],'auto_paused',$result['status']]);
      }catch(Exception $e){}
    }
  }
}

/* ОБХОД АРХИВА: переспрос пропавших и уборка (25.08.2026).
   Через неделю после пропажи спрашиваем ещё раз, потом ещё через неделю.
   Ожил — возвращаем на витрину. Два неудачных переспроса — приговор:
   не покупали ни разу → удаляем товар и витринную карточку;
   покупали → оставляем в архиве навсегда (пометка kept).
   ПРЕДОХРАНИТЕЛЬ: если под удаление в один день попадает больше $maxDel,
   в этот день не удаляем ничего. Две ошибки подряд у посредника не должны
   стоить нам полкаталога — мёртвые никуда не денутся, уйдут следующим кругом. */
function ds_archive_pass($limit = 50, $maxDel = 100) {
  ds_archive_cols();
  $now = date('Y-m-d H:i:s');
  $out = ['переспрошено'=>0, 'вернулось'=>0, 'поставлено_на_удаление'=>0, 'удалено'=>0, 'оставлено_с_историей'=>0];
  $rows = [];
  try {
    $rows = db()->query("SELECT id, product_id, source_url, source_platform, source_price_cny, gone_tries
                           FROM ds_products
                          WHERE gone_at IS NOT NULL AND gone_result IS NULL AND gone_tries < 2
                            AND (gone_last_try IS NULL OR gone_last_try < DATE_SUB(NOW(), INTERVAL 7 DAY))
                          ORDER BY gone_last_try ASC LIMIT ".(int)$limit)->fetchAll();
  } catch (Exception $e) { return $out; }

  $toKill = [];
  foreach ($rows as $dp) {
    $r = ds_check_1688_api($dp['source_url'], $dp['product_id']);
    if ($r === null) $r = ds_check_url($dp['source_url'], $dp['source_platform']);
    $out['переспрошено']++;
    $tries = (int)$dp['gone_tries'] + 1;
    if (!empty($r['available'])) {
      // ожил — возвращаем на витрину
      try {
        if (isset($r['price_cny']) && $r['price_cny'] > 0) {
          db()->prepare("UPDATE ds_products SET source_price_cny=? WHERE id=?")->execute([$r['price_cny'], $dp['id']]);
        }
        db()->prepare("UPDATE ds_products SET ds_status='active',source_available=1,check_fail_count=0,pause_reason=NULL,paused_at=NULL,
                              gone_at=NULL,gone_tries=0,gone_last_try=NULL,gone_result=NULL,last_check_at=? WHERE id=?")->execute([$now,$dp['id']]);
        ds_sync_product_price($dp['id']);   // сам снимет blocked у витринной карточки
        $lid='ds'.substr(md5(uniqid('',true)),0,12);
        db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$dp['id'],'revived','Товар вернулся в продажу']);
        $out['вернулось']++;
      } catch (Exception $e) {}
      continue;
    }
    try { db()->prepare("UPDATE ds_products SET gone_tries=?, gone_last_try=? WHERE id=?")->execute([$tries,$now,$dp['id']]); } catch (Exception $e) {}
    if ($tries >= 2) $toKill[] = $dp;
  }

  if (count($toKill) > $maxDel) {
    $out['карантин_отложен'] = count($toKill);
    return $out;   // подозрительно много — сегодня приговоров не выносим
  }
  foreach ($toKill as $dp) {
    $keep = ds_was_ever_ordered($dp['product_id']);
    if ($keep) {
      try {
        db()->prepare("UPDATE ds_products SET gone_result='kept' WHERE id=?")->execute([$dp['id']]);
        $lid='ds'.substr(md5(uniqid('',true)),0,12);
        db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$dp['id'],'archived','Мёртв 2 недели, оставлен — были заказы или лежит в корзине']);
      } catch (Exception $e) {}
      $out['оставлено_с_историей']++;
      continue;
    }
    /* КАРАНТИН НА МЕСЯЦ. Товар помечается к удалению, но ещё 30 дней лежит
       на сервере: его видно в статистике и списке, и если случился массовый
       сбой — есть время заметить и отменить, пока ничего не пропало. */
    try {
      db()->prepare("UPDATE ds_products SET gone_result='to_delete', gone_delete_at=DATE_ADD(NOW(), INTERVAL 30 DAY) WHERE id=?")->execute([$dp['id']]);
      $lid='ds'.substr(md5(uniqid('',true)),0,12);
      db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$dp['id'],'to_delete','Мёртв 2 недели, покупок не было — удаление через 30 дней']);
      $out['поставлено_на_удаление']++;
    } catch (Exception $e) {}
  }

  /* Исполнение приговора: удаляем то, что отлежало месяц.
     Тот же предохранитель — больше $maxDel за день не трогаем. */
  $due = [];
  try {
    $due = db()->query("SELECT id, product_id FROM ds_products
                         WHERE gone_result='to_delete' AND gone_delete_at IS NOT NULL AND gone_delete_at <= NOW()
                         ORDER BY gone_delete_at ASC LIMIT ".(int)($maxDel + 1))->fetchAll();
  } catch (Exception $e) {}
  if (count($due) > $maxDel) { $out['удаление_отложено'] = count($due); return $out; }
  foreach ($due as $dp) {
    // последняя проверка перед удалением: за месяц товар мог попасть в заказ или корзину
    if (ds_was_ever_ordered($dp['product_id'])) {
      try { db()->prepare("UPDATE ds_products SET gone_result='kept', gone_delete_at=NULL WHERE id=?")->execute([$dp['id']]); } catch (Exception $e) {}
      $out['оставлено_с_историей']++;
      continue;
    }
    try {
      $pid = $dp['product_id']; $auto = 0;
      try { $aq=db()->prepare('SELECT auto_created FROM ds_products WHERE id=?'); $aq->execute([$dp['id']]); $auto=(int)$aq->fetchColumn(); } catch (Exception $e) {}
      $lid='ds'.substr(md5(uniqid('',true)),0,12);
      try { db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$dp['id'],'deleted','Отлежал месяц в карантине — удалён']); } catch (Exception $e) {}
      if ($pid) {
        if ($auto === 1) db()->prepare('DELETE FROM products WHERE id=?')->execute([$pid]);
        else            db()->prepare("DELETE FROM products WHERE id=? AND supplier_id='DS_AUTO'")->execute([$pid]);
      }
      db()->prepare('DELETE FROM ds_products WHERE id=?')->execute([$dp['id']]);
      $out['удалено']++;
    } catch (Exception $e) {}
  }
  return $out;
}

/* ============================================================
   ЕДИНЫЙ ВИД ТЕЛЕФОНА (17.08.2026).
   Один и тот же человек завёлся дважды: 01.07 как «+79787214750» и 17.08 как
   «9787214750». Проверка на существующего сравнивала строки как введено.
   Теперь: из введённого берём только цифры; 11 цифр с 8 или 7 → +7 и хвост;
   10 цифр → +7 и они же. Иностранные номера не трогаем, оставляем с плюсом.
   Сравниваем ВСЕГДА по последним десяти цифрам — так находится запись в любом
   старом виде, и её собственный номер остаётся прежним, чтобы не оторвались
   заказы, бонусы и приглашения.
   ============================================================ */
/* УСТРОЙСТВО ПРИ РЕГИСТРАЦИИ (18.08.2026, просьба Алексея).
   Пишем, с чего человек пришёл, чтобы в CRM было видно, какая аудитория
   приходит по QR-кодам и рекламе: Android или айфон, приложение или браузер.
   Определяем на сервере по строке браузера — её подделать сложнее, чем
   присланное клиентом поле, и старые записи не ломаются. */
/* АДРЕС ДОСТАВКИ ПО СТРОКАМ (19.08.2026, просьба Алексея).
   Одной строкой было непонятно, в какой населённый пункт везти: к складу в
   Гвардейском относятся и Софиевка, и Мирное. Храним разложенным и подставляем
   при следующем заказе. */
function addr_col(){
  static $done=false;
  if($done) return; $done=true;
  try{ db()->query("ALTER TABLE customers ADD COLUMN addr_json TEXT NULL"); }catch(Exception $e){}
}

function dev_col(){
  static $done=false;
  if($done) return; $done=true;
  try{ db()->query("ALTER TABLE customers ADD COLUMN device VARCHAR(32) NULL"); }catch(Exception $e){}
}
function dev_guess(){
  $ua = (string)($_SERVER['HTTP_USER_AGENT'] ?? '');
  if($ua==='') return '';
  $app = (stripos($ua,'ITCApp')!==false);
  if(preg_match('/iphone|ipad|ipod/i',$ua))  return $app ? 'iPhone · приложение' : 'iPhone · браузер';
  if(preg_match('/android/i',$ua))           return $app ? 'Android · приложение' : 'Android · браузер';
  if(preg_match('/windows|macintosh|linux/i',$ua)) return 'Компьютер';
  return 'Другое';
}

function ph_norm($p){
  $d = preg_replace('/\D+/', '', (string)$p);
  if ($d === '') return '';
  if (strlen($d) === 11 && ($d[0] === '8' || $d[0] === '7')) $d = '7' . substr($d, 1);
  elseif (strlen($d) === 10) $d = '7' . $d;
  if (strlen($d) === 11 && $d[0] === '7') return '+7' . substr($d, 1);
  return '+' . $d;
}
function ph_tail($p){
  $d = preg_replace('/\D+/', '', (string)$p);
  return substr($d, -10);
}
/* ПАРТНЁР ПО НОМЕРУ В ЛЮБОМ НАПИСАНИИ (обновление №265).
   Номер в заявке человек пишет как хочет — 8978…, 7978…, +7 978 … — а при входе
   по СМС он приходит как +7978…. Раньше партнёра искали точным совпадением
   строки: одобрение заявки не узнавало уже вошедшего по СМС человека и заводило
   ему ВТОРУЮ карточку (с точкой и кодом), а вход находил первую — пустую, без
   точки и неактивную. Код верный, а войти нельзя.
   Теперь сравниваем последние 10 цифр. Если карточек несколько, берём ту, где
   доступ открыт, есть точка и код. */
function itc_partner_by_phone($phone, $cols = 'id,phone,name,code,warehouse_id,status') {
  $tail = ph_tail($phone);
  try {
    if (strlen($tail) < 10) {
      $q = db()->prepare("SELECT $cols FROM partners WHERE phone=? LIMIT 1");
      $q->execute([trim((string)$phone)]);
      return $q->fetch() ?: null;
    }
    $q = db()->prepare("SELECT $cols FROM partners WHERE RIGHT(".ph_sql('phone').",10)=?
                        ORDER BY (status='active') DESC,
                                 (warehouse_id IS NOT NULL AND warehouse_id<>'') DESC,
                                 (code IS NOT NULL AND code<>'') DESC
                        LIMIT 1");
    $q->execute([$tail]);
    return $q->fetch() ?: null;
  } catch (Exception $e) { return null; }
}
// Выражение для SQL: из столбца остаются одни цифры (без regexp — работает везде)
function ph_sql($col){
  return "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE($col,' ',''),'-',''),'(',''),')',''),'+','')";
}
// Найти покупателя по любому виду номера. Возвращает строку таблицы или null.
function ph_find_customer($phone){
  $tail = ph_tail($phone);
  if ($tail === '' || strlen($tail) < 10) return null;
  try {
    $q = db()->prepare('SELECT * FROM customers WHERE RIGHT(' . ph_sql('phone') . ',10)=? ORDER BY created_at ASC, phone ASC LIMIT 1');
    $q->execute([$tail]);
    return $q->fetch() ?: null;
  } catch (Exception $e) {
    try {
      $q = db()->prepare('SELECT * FROM customers WHERE RIGHT(' . ph_sql('phone') . ',10)=? LIMIT 1');
      $q->execute([$tail]);
      return $q->fetch() ?: null;
    } catch (Exception $e2) { return null; }
  }
}

