    $prodPending = 0; try { $prodPending = (int)db()->query("SELECT COUNT(*) FROM products WHERE mod_status='pending'")->fetchColumn(); } catch (Exception $e) {}
    $prodRejected = 0; try { $prodRejected = (int)db()->query("SELECT COUNT(*) FROM products WHERE mod_status='rejected'")->fetchColumn(); } catch (Exception $e) {}
    jout(['ok' => true, 'srv_ms' => (int)round((microtime(true) - $__b0) * 1000), 'srv_now' => $srvNow, 'partial' => ($since !== '' ? 1 : 0), 'pids' => $pids, 'prod_pending' => $prodPending, 'prod_rejected' => $prodRejected, 'suppliers' => $sup, 'products' => $pr, 'products_total' => $products_total, 'calc' => get_settings(), 'banners' => $banners, 'warehouses' => $warehouses, 'categories' => $categories, 'reviews_pending' => $rev_pending, 'support_unread' => $support_unread, 'supplier_unread' => $supplier_unread, 'accept_pending' => $accept_pending, 'acct_pending' => $acct_pending, 'partner_unread' => $partner_unread, 'warehouse_unread' => $warehouse_unread, 'buyout_pending' => $buyout_pending, 'pvz_pending' => $pvz_pending, 'paid_today' => $paid_today, 'paid_today_sum' => $paid_today_sum, 'paid_unseen' => $paid_unseen, 'pvz_ready' => $pvz_ready,
      'month_cnt' => $month_cnt, 'month_sum' => $month_sum, 'unpaid_cnt' => $unpaid_cnt]);
  }

  // ---- отправка кода (демо: код в ответе; боевой режим: реальное SMS) ----
  case 'send_code': {
    global $SMS_ENABLED;
    $d = body();
    $phone = trim($d['phone'] ?? '');
    if (strlen($phone) < 5) fail('Введите номер телефона');
    $phoneN = str_replace(' ', '', $phone);
    // анти-спам: не больше 5 SMS за 15 минут и не больше 15 за сутки на номер
    if (!rl_ok($phoneN, 'sms', 5, 15)) fail('Слишком часто. Запросите код через несколько минут.', 429);
    if (!rl_ok($phoneN, 'sms', 15, 1440)) fail('Превышен суточный лимит запросов кода.', 429);
    rl_hit($phoneN, 'sms');
    $code = (string) random_int(1000, 9999);
    $st = db()->prepare(
      'INSERT INTO sms_codes (phone,code,expires_at) VALUES (?,?, DATE_ADD(NOW(), INTERVAL 10 MINUTE))
       ON DUPLICATE KEY UPDATE code = VALUES(code), expires_at = VALUES(expires_at)');
    $st->execute([$phone, $code]);

    if ($SMS_ENABLED) {
      $resp = sms_send($phone, 'Kod podtverzhdeniya ITK Mebel: ' . $code);
      $ok = ($resp && (($resp['status'] ?? '') === 'OK'));
      if ($ok && !empty($resp['sms']) && is_array($resp['sms'])) {
        $first = reset($resp['sms']);
        if (($first['status'] ?? '') !== 'OK') {
          $ok = false;
          $resp['status_text'] = $first['status_text'] ?? ($first['status_code'] ?? '');
        }
      }
      if (!$ok) {
        $err = $resp['status_text'] ?? ($resp['status_code'] ?? 'нет ответа');
        fail('SMS не отправлено (sms.ru: ' . $err . ')', 502);
      }
      jout(['ok' => true]);
    }
    jout(['ok' => true, 'demo_code' => $code]);
  }

  // ---- проверка кода ----
  case 'verify': {
    $d = body();
    $phone = trim($d['phone'] ?? '');
    $code  = trim($d['code'] ?? '');
    $role  = $d['role'] ?? 'buyer';

    // ---- сотрудник ИТК: вход по секретному коду ----
    if ($role === 'itc') {
      if (strlen($phone) < 5) fail('Введите номер телефона');
      $phoneN = str_replace(' ', '', $phone);
      if (!rl_ok($phoneN, 'staff', 8, 15)) fail('Слишком много попыток. Подождите 15 минут.');

      // 1) сотрудник из таблицы staff (длинный код)
      try {
        $sq = db()->prepare("SELECT id,role,name,active FROM staff WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') AND code=? LIMIT 1");
        $sq->execute([$phone, $code]);
        $stf = $sq->fetch();
        if ($stf) {
          if ((int)$stf['active'] !== 1) { rl_hit($phoneN,'staff'); fail('Доступ сотрудника отключён. Обратитесь к руководителю.'); }
          $whRoles = ['wh_manager','wh_worker','wh_keeper'];
          if (in_array($stf['role'], $whRoles, true)) {
            $whid = ''; try { $wq2=db()->prepare('SELECT warehouse_id FROM staff WHERE id=?'); $wq2->execute([$stf['id']]); $whid=$wq2->fetchColumn()?:''; } catch (Exception $e) {}
            if (!$whid) { rl_hit($phoneN,'staff'); fail('Сотруднику склада не назначен склад. Обратитесь к руководителю.'); }
            $winfo = null; try { $wq3=db()->prepare('SELECT id,code,name,city,country FROM warehouses WHERE id=?'); $wq3->execute([$whid]); $winfo=$wq3->fetch()?:null; } catch (Exception $e) {}
            $token = make_session($phone, 'itc', $whid, 'warehouse');
            jout(['ok'=>true,'status'=>'login','role'=>'itc','token'=>$token,'staff_role'=>'warehouse','staff_name'=>$stf['name'],'wh_role'=>$stf['role'],
                  'wh_id'=>$whid,'wh_name'=>($winfo['name']??''),'wh_code'=>($winfo['code']??''),'wh_city'=>($winfo['city']??'')]);
          }
          $token = make_session($phone, 'itc', null, $stf['role']);
          jout(['ok'=>true,'status'=>'login','role'=>'itc','token'=>$token,'staff_role'=>$stf['role'],'staff_name'=>$stf['name']]);
        }
      } catch (Exception $e) {}

      // 2) код склада → оператор склада
      try {
        $wq = db()->prepare("SELECT id,code,name,city,country FROM warehouses WHERE access_code<>'' AND access_code=?");
        $wq->execute([$code]);
        $w = $wq->fetch();
        if ($w) {
          $token = make_session($phone, 'itc', $w['id'], 'warehouse');
          jout(['ok'=>true,'status'=>'login','role'=>'itc','token'=>$token,'staff_role'=>'warehouse',
                'wh_id'=>$w['id'],'wh_name'=>$w['name'],'wh_code'=>$w['code'],'wh_city'=>$w['city']]);
        }
      } catch (Exception $e) {}

      // 3) аварийный мастер-код (всегда босс)
      if (hash_equals(ITC_MASTER_CODE, (string)$code)) {
        $token = make_session($phone, 'itc', null, 'boss');
        jout(['ok'=>true,'status'=>'login','role'=>'itc','token'=>$token,'staff_role'=>'boss','staff_name'=>'Босс']);
      }

      // 3b) кабинет главного бухгалтера — полный доступ как у босса, но без изменения формулы расчёта
      if (hash_equals('2525254444', (string)$code)) {
        $token = make_session($phone, 'itc', null, 'bossacct');
        jout(['ok'=>true,'status'=>'login','role'=>'itc','token'=>$token,'staff_role'=>'bossacct','staff_name'=>'Мацепа Анна Петровна']);
      }

      // 4) безопасный бутстрап: пока в staff нет ни одного активного босса —
      //    временно работают старые короткие коды 1–40 (чтобы не закрыть доступ при переходе).
      $hasBoss = 0;
      try { $hasBoss = (int)db()->query("SELECT COUNT(*) c FROM staff WHERE role='boss' AND active=1")->fetch()['c']; } catch (Exception $e) {}
      if ($hasBoss === 0 && preg_match('/^\d{4}$/', $code)) {
        $cn = (int)$code; $staff_role = '';
        if ($cn>=1 && $cn<=10) $staff_role='boss';
        elseif ($cn>=11 && $cn<=20) $staff_role='manager';
        elseif ($cn>=21 && $cn<=30) $staff_role='moderator';
        elseif ($cn>=31 && $cn<=40) $staff_role='accountant';
        elseif ($cn>=41 && $cn<=50) $staff_role='chief_accountant';
        elseif ($cn>=51 && $cn<=60) $staff_role='supervisor';
        if ($staff_role) {
          $token = make_session($phone, 'itc', null, $staff_role);
          jout(['ok'=>true,'status'=>'login','role'=>'itc','token'=>$token,'staff_role'=>$staff_role,'bootstrap'=>true]);
        }
      }

      rl_hit($phoneN, 'staff');
      fail('Неверный код доступа ИТК');
    }

    // ---- покупатель / поставщик: вход по SMS-коду ----
    $st = db()->prepare('SELECT code FROM sms_codes WHERE phone = ? AND expires_at > NOW()');
    $st->execute([$phone]);
    $row = $st->fetch();
    if (!$row || $row['code'] !== $code) fail('Неверный или просроченный код');
    db()->prepare('DELETE FROM sms_codes WHERE phone = ?')->execute([$phone]);

    if ($role === 'supplier') {
      $st = db()->prepare("SELECT id,status,deposit_paid FROM suppliers WHERE REPLACE(phone,' ','') = REPLACE(?,' ','') ORDER BY id ASC LIMIT 1");
      $st->execute([$phone]);
      $s = $st->fetch();
      if ($s) {
        if (($s['status'] ?? 'active') === 'blocked') fail('Аккаунт поставщика заблокирован. Обратитесь в ИТК.');
        $token = make_session($phone, 'supplier', $s['id']);
        jout(['ok' => true, 'status' => 'login', 'role' => 'supplier', 'supplierId' => $s['id'], 'token' => $token]);
      }
      jout(['ok' => true, 'status' => 'register']);
    }
    if ($role === 'trader') {
      $t = null;
      try { $tq=db()->prepare("SELECT id,name,status FROM traders WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') LIMIT 1"); $tq->execute([$phone]); $t=$tq->fetch()?:null; } catch (Exception $e) {}
      if ($t) {
        if (($t['status'] ?? 'active') === 'blocked') fail('Доступ трейдера приостановлен. Свяжитесь с ИТК.');
        $token = make_session($phone, 'trader', $t['id']);
        jout(['ok'=>true,'status'=>'login','role'=>'trader','token'=>$token,'traderId'=>$t['id'],'name'=>$t['name']]);
      }
      $appSt = '';
      try { $aq=db()->prepare("SELECT status FROM trader_applications WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') ORDER BY created_at DESC LIMIT 1"); $aq->execute([$phone]); $appSt=$aq->fetchColumn() ?: ''; } catch (Exception $e) {}
      jout(['ok'=>true,'status'=>'trader_pending','app_status'=>$appSt]);
    }
    if ($role === 'partner') {
      $p = itc_partner_by_phone($phone);
      if ($p && $p['status'] === 'active' && $p['code'] !== '') {
        // уже активирован — сразу вход
        $token = make_session($phone, 'partner', $p['id']);
        jout(['ok'=>true,'status'=>'login','role'=>'partner','token'=>$token,'name'=>$p['name']]);
      }
      if (!$p) {
        $id = gen('pt');
        try { db()->prepare('INSERT INTO partners (id,phone,name,status) VALUES (?,?,?,?)')->execute([$id,(ph_norm($phone) ?: $phone),'','pending']); } catch (Exception $e) {}
      }
      jout(['ok'=>true,'status'=>'partner_pending']);
    }
    // buyer
    /* Ищем по последним десяти цифрам, а не по строке: человек мог войти
       и как «+7978…», и как «978…». Если нашли — дальше работаем с ТЕМ
       номером, что записан у него в базе, иначе оторвутся заказы и бонусы. */
    $c = ph_find_customer($phone);
    addr_col();
    if ($c && !empty($c['phone'])) $phone = $c['phone'];
    if ($c && trim($c['name']) !== '') {
      // регистрация завершена (есть ФИО) — вход
      $token = make_session($phone, 'buyer', null);
      /* Отдаём сохранённый адрес доставки, чтобы при оформлении он подставился
         сам и человек не вбивал его каждый раз заново. */
      $__addr = null;
      try{ $__addr = json_decode((string)($c['addr_json'] ?? ''), true); }catch(Exception $e){}
      jout(['ok' => true, 'status' => 'login', 'role' => 'buyer', 'token' => $token,
            'name' => $c['name'], 'email' => $c['email'], 'city' => $c['city'], 'street' => $c['street'],
            'addr' => is_array($__addr) ? $__addr : null]);
    }
    // телефон подтверждён, но регистрация не завершена — фиксируем «трафик»: заводим запись-заглушку
    if (!$c) {
      $phone = ph_norm($phone) ?: $phone;   // новый покупатель — сразу в едином виде
      dev_col();
      try{ $__d=dev_guess(); }catch(Exception $e){ $__d=''; }
      try { db()->prepare("INSERT INTO customers (phone,name,email,city,street,zip) VALUES (?,'','','','','') ON DUPLICATE KEY UPDATE phone=phone")->execute([$phone]); } catch (Exception $e) {}
      /* Устройство пишем только если оно ещё не записано — первое появление
         человека и есть то, что интересно для рекламы. */
      if($__d!=='') { try{ db()->prepare("UPDATE customers SET device=? WHERE phone=? AND (device IS NULL OR device='')")->execute([$__d,$phone]); }catch(Exception $e){} }
    }
    $src = preg_replace('/[^a-zA-Z0-9_]/', '', substr($d['src'] ?? '', 0, 24));
    if ($src !== '') { try { db()->prepare("UPDATE customers SET src=? WHERE phone=? AND (src IS NULL OR src='')")->execute([$src, $phone]); } catch (Exception $e) {} }
    jout(['ok' => true, 'status' => 'register']);
  }

  /* ============================================================
     РАЗОВАЯ СКЛЕЙКА ДУБЛЕЙ ПО ТЕЛЕФОНУ (17.08.2026).
     Открывается один раз по адресу:
       /api/?action=fix_phones&key=МАСТЕР-КОД        — только показать, что найдено
       /api/?action=fix_phones&key=МАСТЕР-КОД&do=1   — склеить
     Оставляем САМУЮ СТАРУЮ карточку: к ней привязаны бонусы и приглашения.
     Заказы, отзывы, обращения, подписки и бонусы переводим на неё, пустые поля
     дозаполняем из младшей, младшую удаляем. Номер приводим к виду +7…
     ============================================================ */
  // ---- адрес доставки покупателя: сохранить ----
  case 'addr_save': {
    $s = authUser();
    addr_col();
    $a = body()['addr'] ?? [];
    if(!is_array($a)) fail('Пустой адрес');
    $keep = [];
    foreach(['city','street','house','block','floor','flat','person','cphone','note'] as $k){
      $keep[$k] = mb_substr(trim((string)($a[$k] ?? '')), 0, 160);
    }
    try{
      db()->prepare('UPDATE customers SET addr_json=? WHERE phone=?')
         ->execute([json_encode($keep, JSON_UNESCAPED_UNICODE), $s['phone']]);
    }catch(Exception $e){ fail('Не сохранилось'); }
    jout(['ok'=>true,'addr'=>$keep]);
  }

  /* ============================================================
     БАЗЫ ДАННЫХ ДЛЯ БОССА (20.08.2026, просьба Алексея).
     Просмотр таблицами прямо в кабинете и выгрузка в CSV — он открывается
     в Excel двойным щелчком, весит копейки и собирается быстро, в отличие
     от настоящего xlsx. Доступ только у босса: в выгрузке телефоны и адреса.
     ============================================================ */
  case 'db_defs':
  case 'db_rows':
  case 'db_export': {
    $s = authUser('itc');
    $sr = $s['staff_role'] ?? '';
    if (!($sr === 'boss' || $sr === '')) fail('Доступ только у босса', 403);

    $defs = [
      'customers' => ['Покупатели',   'SELECT phone,name,city,street,zip,device,created_at FROM customers ORDER BY created_at DESC'],
      'orders'    => ['Заказы',       'SELECT id,num,phone,total,paid,addr_name,addr_phone,addr_city,addr_street,warehouse_id,pay_kind,created_at FROM orders ORDER BY created_at DESC'],
      'items'     => ['Заказы построчно', 'SELECT order_id,product_id,name,qty,price FROM order_items ORDER BY order_id DESC'],
      'products'  => ['Товары каталога', 'SELECT id,name,price,cat,subcat,blocked FROM products ORDER BY id DESC'],
      'suppliers' => ['Поставщики',   'SELECT * FROM suppliers ORDER BY id DESC'],
      'partners'  => ['Партнёры ПВЗ', 'SELECT * FROM partners ORDER BY id DESC'],
      'staff'     => ['Сотрудники',   'SELECT * FROM staff ORDER BY id DESC'],
      'warehouses'=> ['Склады',       'SELECT * FROM warehouses ORDER BY id DESC'],
      'reviews'   => ['Отзывы',       'SELECT * FROM reviews ORDER BY id DESC'],
    ];

    if ($action === 'db_defs') {
      $out = [];
      foreach ($defs as $k => $d) {
        $tbl = '';
        if (preg_match('/FROM\s+([a-z_]+)/i', $d[1], $m)) $tbl = $m[1];
        $cnt = 0;
        try { $cnt = (int)db()->query('SELECT COUNT(*) FROM `'.$tbl.'`')->fetchColumn(); } catch (Exception $e) { $cnt = -1; }
        $out[] = ['key'=>$k, 'title'=>$d[0], 'rows'=>$cnt];
      }
      jout(['ok'=>true,'tables'=>$out]);
    }

    $key = (string)($_GET['key'] ?? (body()['key'] ?? ''));
    if (!isset($defs[$key])) fail('Нет такой таблицы');
    $sql = $defs[$key][1];

    if ($action === 'db_rows') {
      $page = max(1, (int)($_GET['page'] ?? 1));
      $per  = 50;
      $off  = ($page - 1) * $per;
      $rows = [];
      try { $rows = db()->query($sql.' LIMIT '.$per.' OFFSET '.$off)->fetchAll(); }
      catch (Exception $e) { fail('Не читается: '.$e->getMessage()); }
      $cols = $rows ? array_keys($rows[0]) : [];
      jout(['ok'=>true,'title'=>$defs[$key][0],'cols'=>$cols,'rows'=>$rows,'page'=>$page,'per'=>$per]);
    }

    // db_export — отдаём файл CSV
    $rows = [];
    try { $rows = db()->query($sql)->fetchAll(); } catch (Exception $e) { fail('Не читается'); }
    $name = 'itc-'.$key.'-'.date('Y-m-d').'.csv';
    header('Content-Type: text/csv; charset=utf-8');
    header('Content-Disposition: attachment; filename="'.$name.'"');
    echo "\xEF\xBB\xBF";                      // метка кодировки, иначе Excel покажет кракозябры
    $out = fopen('php://output', 'w');
    if ($rows) fputcsv($out, array_keys($rows[0]), ';');
    foreach ($rows as $r) fputcsv($out, array_map(function($v){ return (string)$v; }, $r), ';');
    fclose($out);
    exit;
  }

  case 'fix_phones': {
    if (!hash_equals(ITC_MASTER_CODE, (string)($_GET['key'] ?? ''))) fail('Нет доступа', 403);
    $doIt = (($_GET['do'] ?? '') === '1');
    $rows = [];
    try { $rows = db()->query('SELECT * FROM customers')->fetchAll(); } catch (Exception $e) { fail('Не читается таблица покупателей'); }

    $groups = [];
    foreach ($rows as $r) {
      $t = ph_tail($r['phone'] ?? '');
      if (strlen($t) < 10) continue;
      $groups[$t][] = $r;
    }

    $merged = []; $renamed = []; $errors = [];
    // на какие таблицы завязан телефон покупателя
    $tables = [
      ['orders','phone'], ['orders','addr_phone'], ['reviews','phone'],
      ['support_messages','phone'], ['push_subs','phone'], ['itc_bonus','phone'],
      ['sessions','phone'], ['customers','ref_by'],
    ];
    $movePhone = function($from, $to) use ($tables, &$errors) {
      foreach ($tables as $t) {
        try { db()->prepare('UPDATE '.$t[0].' SET '.$t[1].'=? WHERE '.$t[1].'=?')->execute([$to, $from]); }
        catch (Exception $e) { $errors[] = $t[0].'.'.$t[1].': '.$e->getMessage(); }
      }
    };

    foreach ($groups as $tail => $list) {
      // самая старая карточка первой
      usort($list, function($a,$b){
        $x = (string)($a['created_at'] ?? ''); $y = (string)($b['created_at'] ?? '');
        if ($x === $y) return strcmp((string)$a['phone'], (string)$b['phone']);
        return strcmp($x, $y);
      });
      $keep = $list[0];
      $keepPhone = (string)$keep['phone'];

      // 1) склейка младших карточек в старшую
      for ($i = 1; $i < count($list); $i++) {
        $dup = $list[$i];
        $dupPhone = (string)$dup['phone'];
        if (!$doIt) { $merged[] = ['оставляем' => $keepPhone, 'убираем' => $dupPhone, 'имя' => ($dup['name'] ?: $keep['name'])]; continue; }
        // пустые поля старшей дозаполняем из младшей
        foreach (['name','email','city','street','zip','last_name','first_name','mid_name','warehouse_id','src','ref_by','ref_partner_id'] as $f) {
          if (!array_key_exists($f, $dup)) continue;
          $newV = trim((string)($dup[$f] ?? ''));
          $oldV = trim((string)($keep[$f] ?? ''));
          if ($newV !== '' && $oldV === '') {
            try { db()->prepare('UPDATE customers SET '.$f.'=? WHERE phone=?')->execute([$newV, $keepPhone]); $keep[$f] = $newV; }
            catch (Exception $e) { $errors[] = 'customers.'.$f.': '.$e->getMessage(); }
          }
        }
        $movePhone($dupPhone, $keepPhone);
        try { db()->prepare('DELETE FROM customers WHERE phone=?')->execute([$dupPhone]); }
        catch (Exception $e) { $errors[] = 'удаление '.$dupPhone.': '.$e->getMessage(); }
        $merged[] = ['оставили' => $keepPhone, 'убрали' => $dupPhone];
      }

      // 2) приводим номер оставшейся карточки к единому виду
      $norm = ph_norm($keepPhone);
      if ($norm !== '' && $norm !== $keepPhone) {
        if (!$doIt) { $renamed[] = ['было' => $keepPhone, 'станет' => $norm]; }
        else {
          $busy = 0;
          try { $q = db()->prepare('SELECT COUNT(*) FROM customers WHERE phone=?'); $q->execute([$norm]); $busy = (int)$q->fetchColumn(); } catch (Exception $e) {}
          if ($busy === 0) {
            try {
              db()->prepare('UPDATE customers SET phone=? WHERE phone=?')->execute([$norm, $keepPhone]);
              $movePhone($keepPhone, $norm);
              $renamed[] = ['было' => $keepPhone, 'стало' => $norm];
            } catch (Exception $e) { $errors[] = 'переименование '.$keepPhone.': '.$e->getMessage(); }
          }
        }
      }
    }

    jout([
      'ok' => true,
      'режим' => $doIt ? 'СКЛЕЕНО' : 'только показ, ничего не менялось',
      'всего_карточек' => count($rows),
      'дублей' => count($merged),
      'склейка' => $merged,
      'приведено_к_виду_+7' => $renamed,
      'ошибки' => $errors,
    ]);
  }

  // ============================================================
  //  УВЕДОМЛЕНИЯ В ПРИЛОЖЕНИЕ (Firebase) — добавлено 22.08.2026
  //  Приложение 1.5 получает от Firebase «метку телефона» и присылает её
  //  сюда. Метка живёт в таблице push_tokens и привязана к телефону
  //  покупателя. Отправка идёт через сервер Google, вход по секретному
  //  ключу из config.php (FCM_KEY_FILE).
  // ============================================================

  // ---- Robokassa сообщила об оплате → пуш боссу (вызывает robokassa.php) ----

  // ===================== №325 · eSIM «Интернет в Китае» =====================
  // ---- Тарифы для покупателя (цены уже в рублях с наценкой) ----
  case 'esim_plans': {
    $s = authUser();
    esim_table();
    $staff = ($s['role'] ?? '') === 'itc';
    $loc = (string)($_GET['loc'] ?? 'CN');
    $L = array_map(function($p) use ($staff) { return esim_plan_out($p, $staff); }, esim_plans(!empty($_GET['force']) && $staff, $loc));
    $out = ['ok'=>true, 'list'=>$L, 'loc'=>strtoupper($loc), 'art'=>esim_art_list(), 'rk'=>esim_rk(), 'configured'=>esim_cfg()['access'] !== ''];
    // №329 · картинки «страна и соседи» ещё нет — отдаём тарифы и рисуем её после ответа (раз в 6 часов попытка)
    $lc = strtoupper(preg_replace('/[^A-Za-z]/', '', $loc));
    if (preg_match('/^[A-Z]{2}$/', $lc) && !isset($out['art'][$lc . '_R']) && trim((string)itc_setting('dashscope_key', '')) !== '' && time() - (int)itc_setting('esim_rart_try_' . $lc, 0) > 6 * 3600) {
      $hasM = false; foreach ($L as $pp) if (!empty($pp['multi'])) { $hasM = true; break; }
      if ($hasM) { esim_set('esim_rart_try_' . $lc, (string)time());
        ignore_user_abort(true); @set_time_limit(300); $b = json_encode($out, JSON_UNESCAPED_UNICODE); while (ob_get_level() > 0) @ob_end_clean();
        if (!headers_sent()) { header('Content-Type: application/json; charset=utf-8'); header('Connection: close'); header('Content-Encoding: none'); header('Content-Length: ' . strlen($b)); }
        echo $b; @flush(); if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request();
        try { esim_region_art($lc); } catch (Throwable $e) {} exit; }
    }
    jout($out);
  }
  case 'esim_countries': {
    authUser();
    jout(['ok'=>true, 'list'=>esim_countries(), 'art'=>esim_art_list()]);
  }
  // ---- Покупка: создаём заказ магазина, дальше клиент идёт на оплату (robokassa.php?rk=pay&order=ID) ----
  case 'esim_buy': {
    $s = authUser();
    esim_table();
    $d = body();
    $code = trim((string)($d['code'] ?? ''));
    $plan = esim_plan_find($code);
    if (!$plan) fail('Тариф не найден — обновите список');
    list($pUsd, $pDays, $pName) = esim_pick($plan, $d['days'] ?? 0);
    $rub = esim_rub($pUsd); if ($rub <= 0) fail('Цена не рассчитана');
    $pdo = db();
    $oid = gen('o');
    $cnt = (int)$pdo->query("SELECT COUNT(*) c FROM esim_orders")->fetch()['c'];
    $num = 'E-' . (1001 + $cnt);
    $pdo->prepare('INSERT INTO orders (id,num,phone,total,addr_name,addr_phone,addr_city,addr_street,addr_zip,addr_note,email,warehouse_id,pay_kind) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')
        ->execute([$oid, $num, $s['phone'], $rub, (string)($s['name'] ?? ''), $s['phone'], '', '', '', 'eSIM: '.$pName.' · выдаётся в приложении «eSIM», доставки нет', '', '', '']);
    $eid = gen('e');
    $pdo->prepare('INSERT INTO esim_orders (id,order_id,phone,package_code,package_name,volume,days,usd_cost,rub_price,status) VALUES (?,?,?,?,?,?,?,?,?,?)')
        ->execute([$eid, $oid, $s['phone'], $plan['code'], $pName, $plan['volume'], $pDays, $pUsd, $rub, 'new']);
    try { itc_log_add((string)($s['name'] ?? $s['phone']), 'esim_buy', 'esim', $eid, $pName.' · '.$rub.' ₽'); } catch (Throwable $e) {}
    jout(['ok'=>true, 'order_id'=>$oid, 'num'=>$num, 'esim_id'=>$eid, 'rub'=>$rub, 'pay_url'=>'/robokassa.php?rk=pay&order='.rawurlencode($oid)]);
  }
  // ---- Мои eSIM: список; оплаченные, но не выданные — выдаём прямо сейчас ----
  case 'esim_my': {
    $s = authUser();
    esim_table();
    $q = db()->prepare("SELECT e.*, IF(e.order_id='gift',1,COALESCE(o.paid,0)) paid, o.num FROM esim_orders e LEFT JOIN orders o ON o.id=e.order_id WHERE REPLACE(e.phone,' ','')=REPLACE(?,' ','') ORDER BY e.created_at DESC LIMIT 50"); $q->execute([$s['phone']]);
    $out = [];
    foreach ($q->fetchAll() as $r) {
      if ((int)$r['paid'] === 1 && $r['status'] !== 'ready') { esim_provision($r['id']); }
      elseif ($r['status'] === 'ready') { esim_refresh($r['id']); }
      $q2 = db()->prepare('SELECT * FROM esim_orders WHERE id=?'); $q2->execute([$r['id']]); $rr = $q2->fetch();
      $o = esim_row_out($rr); $o['paid'] = (int)$r['paid']; $o['num'] = $r['order_id'] === 'gift' ? '' : $r['num']; $o['gift'] = $r['order_id'] === 'gift' ? 1 : 0; $o['pay_url'] = '/robokassa.php?rk=pay&order='.rawurlencode($r['order_id']);
      $out[] = $o;
    }
    jout(['ok'=>true, 'list'=>$out]);
  }
  // ---- Удалить неоплаченный заказ eSIM ----
  case 'esim_drop': {
    $s = authUser();
    esim_table();
    $id = trim((string)(body()['id'] ?? ''));
    $q = db()->prepare("SELECT e.order_id, IF(e.order_id='gift',1,COALESCE(o.paid,0)) paid FROM esim_orders e LEFT JOIN orders o ON o.id=e.order_id WHERE e.id=? AND REPLACE(e.phone,' ','')=REPLACE(?,' ','')"); $q->execute([$id, $s['phone']]); $r = $q->fetch();
    if (!$r) fail('Не найдено');
    if ((int)$r['paid'] === 1) fail('Оплаченный заказ удалить нельзя');
    db()->prepare('DELETE FROM esim_orders WHERE id=?')->execute([$id]);
    db()->prepare('DELETE FROM orders WHERE id=? AND paid=0')->execute([$r['order_id']]);
    jout(['ok'=>true]);
  }
  // ---- Босс: настройки, баланс, все заказы ----
  case 'esim_admin': {
    $s = authUser('itc'); if (($s['staff_role'] ?? '') !== 'boss' && ($s['staff_role'] ?? '') !== '') fail('Только босс', 403);
    esim_table();
    $c = esim_cfg();
    $bal = null; $balErr = '';
    if ($c['access'] !== '') { $b = esim_call('/balance/query', []); if (!empty($b['success'])) $bal = round(((int)($b['obj']['balance'] ?? 0)) / 10000, 2); else $balErr = (string)($b['errorMsg'] ?? 'нет ответа'); }
    $rows = db()->query("SELECT e.*, IF(e.order_id='gift',1,COALESCE(o.paid,0)) paid, o.num, c.name cname FROM esim_orders e LEFT JOIN orders o ON o.id=e.order_id LEFT JOIN customers c ON c.phone=e.phone ORDER BY e.created_at DESC LIMIT 200")->fetchAll();
    $L = []; $sumRub = 0; $sumUsd = 0; $giftUsd = 0; $giftN = 0;
    foreach ($rows as $r) { $o = esim_row_out($r, true); $o['paid'] = (int)$r['paid']; $o['gift'] = $r['order_id'] === 'gift' ? 1 : 0; $o['num'] = $o['gift'] ? 'Выдана бесплатно' : $r['num']; $o['who'] = (string)($r['cname'] ?? ''); $o['gift_by'] = (string)($r['gift_by'] ?? ''); $o['gift_note'] = (string)($r['gift_note'] ?? ''); $L[] = $o;
      if ($o['gift']) { if ($r['status'] === 'ready') { $giftUsd += (float)$r['usd_cost']; $giftN++; } } elseif ((int)$r['paid'] === 1) { $sumRub += (int)$r['rub_price']; $sumUsd += (float)$r['usd_cost']; } }
    jout(['ok'=>true, 'settings'=>['access'=>$c['access'] !== '' ? '•••• '.substr($c['access'], -4) : '', 'secret'=>$c['secret'] !== '' ? '•••• '.substr($c['secret'], -4) : '', 'markup'=>$c['markup'], 'usd'=>$c['usd'], 'usd_manual'=>(float)itc_setting('esim_usd_rub', 0), 'usd_src'=>$c['usd_src'], 'round'=>$c['round'], 'auth'=>$c['auth']],
          'art_key'=>(($ak = trim((string)itc_setting('dashscope_key', ''))) !== '' ? '•••• '.substr($ak, -4) : ''), 'art'=>esim_art_list(), 'balance'=>$bal, 'balance_error'=>$balErr, 'list'=>$L, 'sum_rub'=>$sumRub, 'sum_usd'=>round($sumUsd, 2), 'gift_n'=>$giftN, 'gift_usd'=>round($giftUsd, 2), 'me_phone'=>(string)($s['phone'] ?? ''), 'loc'=>strtoupper((string)($_GET['loc'] ?? 'CN')), 'rk'=>esim_rk(), 'plans'=>array_map(function($p){ return esim_plan_out($p, true); }, esim_plans(false, (string)($_GET['loc'] ?? 'CN')))]);
  }
  case 'esim_settings': {
    $s = authUser('itc'); if (($s['staff_role'] ?? '') !== 'boss' && ($s['staff_role'] ?? '') !== '') fail('Только босс', 403);
    $d = body();
    if (isset($d['access']) && trim($d['access']) !== '') { esim_set('esim_access_code', trim($d['access'])); esim_set('esim_auth_mode', ''); }
    if (isset($d['secret'])) { esim_set('esim_secret_key', trim($d['secret'])); esim_set('esim_auth_mode', ''); }
    if (isset($d['markup'])) esim_set('esim_markup_pct', max(0, (float)$d['markup']));
    if (isset($d['usd'])) esim_set('esim_usd_rub', max(0, (float)$d['usd']));
    if (isset($d['round'])) esim_set('esim_round', max(1, (int)$d['round']));
    esim_set('esim_plans_cache', ''); @unlink(__DIR__ . '/.esim_plans.json');
    try { itc_log_add((string)($s['name'] ?? $s['phone']), 'esim_settings', 'esim', '', 'изменены настройки eSIM'); } catch (Throwable $e) {}
    jout(['ok'=>true]);
  }
  // ---- Босс: повторить выдачу (после пополнения баланса) ----
  case 'esim_retry': {
    $s = authUser('itc'); if (($s['staff_role'] ?? '') !== 'boss' && ($s['staff_role'] ?? '') !== '') fail('Только босс', 403);
    esim_table();
    $id = trim((string)(body()['id'] ?? ''));
    $r = esim_provision($id);
    jout(['ok'=>!empty($r['ok']), 'error'=>$r['error'] ?? '']);
