  // ---- №330 · Босс: выдать eSIM бесплатно со своего баланса у провайдера — себе, сотруднику или покупателю ----
  case 'esim_gift_find': {
    $s = authUser('itc'); if (($s['staff_role'] ?? '') !== 'boss' && ($s['staff_role'] ?? '') !== '') fail('Только босс', 403);
    $q = trim((string)(body()['q'] ?? ''));
    if (mb_strlen($q) < 2) jout(['ok'=>true, 'list'=>[]]);
    $digits = preg_replace('/\D+/', '', $q);
    if (strlen($digits) >= 4 && strlen($digits) >= mb_strlen($q) - 4) {
      $st = db()->prepare("SELECT phone,name,city FROM customers WHERE REPLACE(REPLACE(REPLACE(REPLACE(phone,' ',''),'-',''),'(',''),')','') LIKE ? ORDER BY created_at DESC LIMIT 20");
      $st->execute(['%' . $digits . '%']);
    } else { $st = db()->prepare("SELECT phone,name,city FROM customers WHERE name LIKE ? ORDER BY name LIMIT 20"); $st->execute(['%' . $q . '%']); }
    $L = []; $seen = []; foreach ($st->fetchAll() as $r) { $k = preg_replace('/\D+/', '', (string)$r['phone']); $seen[$k] = count($L); $L[] = ['phone'=>$r['phone'], 'name'=>(string)$r['name'], 'city'=>(string)$r['city']]; }
    // №305 · сотрудники тоже: ищем в списке сотрудников (менеджеры, кладовщики и т. д.), даже если человек ещё не входил в магазин
    $RN = ['boss'=>'руководитель','manager'=>'менеджер','moderator'=>'модератор','accountant'=>'бухгалтер','chief_accountant'=>'главный бухгалтер','supervisor'=>'руководитель отдела','warehouse'=>'склад','pvz'=>'пункт выдачи','sales'=>'менеджер по продажам'];
    try {
      if (strlen($digits) >= 4 && strlen($digits) >= mb_strlen($q) - 4) { $sq = db()->prepare("SELECT phone,name,role FROM staff WHERE active=1 AND REPLACE(REPLACE(REPLACE(REPLACE(phone,' ',''),'-',''),'(',''),')','') LIKE ? LIMIT 20"); $sq->execute(['%' . $digits . '%']); }
      else { $sq = db()->prepare("SELECT phone,name,role FROM staff WHERE active=1 AND name LIKE ? LIMIT 20"); $sq->execute(['%' . $q . '%']); }
      foreach ($sq->fetchAll() as $r) { $k = preg_replace('/\D+/', '', (string)$r['phone']); if ($k === '') continue; $rl = 'сотрудник' . (isset($RN[$r['role']]) ? ' · ' . $RN[$r['role']] : '');
        if (isset($seen[$k])) { $i = $seen[$k]; if ($L[$i]['name'] === '') $L[$i]['name'] = (string)$r['name']; $L[$i]['city'] = $rl; continue; }
        $seen[$k] = count($L); $L[] = ['phone'=>$r['phone'], 'name'=>(string)$r['name'], 'city'=>$rl]; }
    } catch (Throwable $e) {}
    jout(['ok'=>true, 'list'=>$L]);
  }
  case 'esim_gift': {
    $s = authUser('itc'); if (($s['staff_role'] ?? '') !== 'boss' && ($s['staff_role'] ?? '') !== '') fail('Только босс', 403);
    esim_table();
    $d = body();
    $code = trim((string)($d['code'] ?? ''));
    $phone = trim((string)($d['phone'] ?? ''));
    $note = mb_substr(trim((string)($d['note'] ?? '')), 0, 190);
    if ($phone === '') fail('Укажите, кому выдать');
    $c = db()->prepare("SELECT phone FROM customers WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') LIMIT 1"); $c->execute([$phone]); $cp = $c->fetchColumn();
    if (!$cp) {   // №305 · сотрудник ещё не входил в магазин — заводим его покупателем по номеру из списка сотрудников
      try { $sq = db()->prepare("SELECT phone,name FROM staff WHERE active=1 AND REPLACE(phone,' ','')=REPLACE(?,' ','') LIMIT 1"); $sq->execute([$phone]); $sr = $sq->fetch();
        if ($sr) { $np = str_replace(' ', '', (string)$sr['phone']); db()->prepare("INSERT INTO customers (phone,name,email,city,street,zip) VALUES (?,?,'','','','') ON DUPLICATE KEY UPDATE phone=phone")->execute([$np, (string)$sr['name']]); $cp = $np; } } catch (Throwable $e) {}
    }
    if (!$cp) fail('Такого номера нет среди покупателей магазина. Пусть человек один раз войдёт в магазин по этому номеру — и выдайте снова.');
    $phone = $cp;
    $plan = esim_plan_find($code);
    if (!$plan) fail('Тариф не найден — обновите список');
    list($pUsd, $pDays, $pName) = esim_pick($plan, $d['days'] ?? 0);
    $by = (string)($s['staff_name'] ?? ($s['name'] ?? ($s['phone'] ?? 'босс')));
    if (itc_setting('esim_gift_cols', '') !== '1') { try { db()->query('ALTER TABLE esim_orders ADD COLUMN gift_by VARCHAR(100) NULL, ADD COLUMN gift_note VARCHAR(200) NULL'); } catch (Throwable $e) {} try { esim_set('esim_gift_cols', '1'); } catch (Throwable $e) {} }
    $eid = gen('e');
    db()->prepare('INSERT INTO esim_orders (id,order_id,phone,package_code,package_name,volume,days,usd_cost,rub_price,status) VALUES (?,?,?,?,?,?,?,?,?,?)')
        ->execute([$eid, 'gift', $phone, $plan['code'], $pName, $plan['volume'], $pDays, $pUsd, 0, 'new']);
    try { db()->prepare('UPDATE esim_orders SET gift_by=?, gift_note=? WHERE id=?')->execute([mb_substr($by, 0, 99), $note, $eid]); } catch (Throwable $e) {}
    // приложение «eSIM Китай» сразу открываем получателю в «Моих приложениях»
    try { apps_table(); db()->prepare("INSERT IGNORE INTO customer_apps (phone, app, granted_by) VALUES (?,?,?)")->execute([$phone, 'esim', mb_substr($by, 0, 99)]); } catch (Throwable $e) {}
    try { itc_log_add($by, 'esim_gift', 'esim', $eid, $pName.' → '.$phone.' бесплатно, '.$pUsd.' $ с баланса'); } catch (Throwable $e) {}
    @set_time_limit(60);
    $r = esim_provision($eid);
    try { if (!empty($r['ok'])) itc_push_phone($phone, 'Вам выдана eSIM', $pName.' — откройте «eSIM» → «Мои eSIM» и установите', '/esim/?my=1'); } catch (Throwable $e) {}
    jout(['ok'=>true, 'id'=>$eid, 'ready'=>!empty($r['ok']), 'error'=>$r['error'] ?? '']);
  }
