    if ($png === '' || strncmp($png, "\x89PNG", 4) !== 0) { http_response_code(404); exit; }
    $sz = @getimagesize($f); $w = (int)($sz[0] ?? 0); $h = (int)($sz[1] ?? 0);
    if ($w > 256 || $h > 256) { $im = @imagecreatefromstring($png); if ($im) { $o = imagecreatetruecolor(256, 256); imagealphablending($o, false); imagesavealpha($o, true); imagecopyresampled($o, $im, 0, 0, 0, 0, 256, 256, imagesx($im), imagesy($im)); ob_start(); imagepng($o); $png = ob_get_clean(); $w = $h = 256; } }
    header('Content-Type: image/x-icon'); header('Cache-Control: public, max-age=604800');
    echo pack('vvv', 0, 1, 1) . pack('CCCCvvVV', $w >= 256 ? 0 : $w, $h >= 256 ? 0 : $h, 0, 0, 1, 32, strlen($png), 22) . $png; exit;
