  // ===================== №354 · ОТЕЛИ (приложение /apps/hotels/) =====================
  // ---- Поиск: город (по-русски, по-английски или по-китайски), даты, гости ----
  case 'htl_search': {
    $s = authUser(); htl_tables();
    $dt = htl_dates($_GET['in'] ?? '', $_GET['out'] ?? ''); if (!$dt) fail('Проверьте даты заезда и выезда');
    list($in, $out, $n) = $dt; $g = max(1, min(10, (int)($_GET['guests'] ?? 2)));
    $city = htl_s($_GET['city'] ?? '', 80);
    $test = htl_is_boss($s) && !empty($_GET['all']);   // босс видит и черновики — для проверки
    $sql = "SELECT * FROM htl_hotels WHERE src='own' AND " . ($test ? "status<>'off'" : "status='active'");
    $par = [];
    if ($city !== '') { $sql .= ' AND (city LIKE ? OR city_local LIKE ? OR name LIKE ? OR name_local LIKE ? OR address LIKE ?)'; $l = '%' . $city . '%'; $par = [$l, $l, $l, $l, $l]; }
    $q = db()->prepare($sql . ' ORDER BY stars DESC, name LIMIT 200'); $q->execute($par);
    $L = [];
    foreach ($q->fetchAll() as $h) {
      $rq = db()->prepare('SELECT * FROM htl_rooms WHERE hotel_id=? AND active=1 AND guests>=?'); $rq->execute([$h['id'], $g]);
      $best = null;
      foreach ($rq->fetchAll() as $r) { $qt = htl_room_quote($r, $in, $out, $n); if ($qt['free'] > 0 && $qt['total'] > 0 && (!$best || $qt['total'] < $best)) $best = $qt['total']; }
      $o = htl_hotel_out($h); $o['from_rub'] = $best ? htl_rub($best, $h['cur']) : 0; $o['avail'] = $best ? 1 : 0;
      $L[] = $o;
    }
    foreach (htl_provider_search($city, $in, $out, $g) as $o) $L[] = $o;
    usort($L, function ($a, $b) { return ($b['avail'] <=> $a['avail']) ?: (($a['from_rub'] ?: PHP_INT_MAX) <=> ($b['from_rub'] ?: PHP_INT_MAX)); });
    jout(['ok'=>true, 'list'=>$L, 'nights'=>$n, 'providers'=>htl_providers()]);
  }
  case 'htl_cities': {
    authUser(); htl_tables();
    $L = db()->query("SELECT city, city_local, country, COUNT(*) n FROM htl_hotels WHERE status='active' AND city<>'' GROUP BY city, city_local, country ORDER BY n DESC LIMIT 50")->fetchAll();
    jout(['ok'=>true, 'list'=>$L]);
