          ->execute([$bid, $num, $oid, $s['phone'], $r['hotel_id'], $r['id'], 'own', $in, $out, $n, $g, 1, $gname, $gphone, htl_s($d['note'] ?? '', 600), $qt['total'], $r['hcur'], $rub, (float)$r['hcomm'], 'new']);
