    htl_can($s, $r['hotel_id']);
    $from = preg_match('~^\d{4}-\d{2}-\d{2}$~', (string)($_GET['from'] ?? '')) ? $_GET['from'] : date('Y-m-d'); $days = max(7, min(92, (int)($_GET['days'] ?? 42)));
    $to = date('Y-m-d', strtotime($from) + $days * 86400);
    $cq = db()->prepare('SELECT day, price, avail, closed FROM htl_cal WHERE room_id=? AND day>=? AND day<?'); $cq->execute([$r['id'], $from, $to]); $cal = [];
    foreach ($cq->fetchAll() as $c) $cal[$c['day']] = $c;
    $bq = db()->prepare("SELECT date_in, date_out, rooms FROM htl_bookings WHERE room_id=? AND status IN ('paid','confirmed') AND date_in<? AND date_out>?"); $bq->execute([$r['id'], $to, $from]); $busy = [];
    foreach ($bq->fetchAll() as $b) for ($t = strtotime($b['date_in']); $t < strtotime($b['date_out']); $t += 86400) { $k = date('Y-m-d', $t); $busy[$k] = ($busy[$k] ?? 0) + (int)$b['rooms']; }
    $L = [];
    for ($i = 0; $i < $days; $i++) { $k = date('Y-m-d', strtotime($from) + $i * 86400); $c = $cal[$k] ?? null;
      $L[] = ['day'=>$k, 'price'=>$c && $c['price'] !== null ? (int)$c['price'] : (int)$r['price'], 'own_price'=>$c && $c['price'] !== null ? 1 : 0, 'avail'=>$c && $c['avail'] !== null ? (int)$c['avail'] : (int)$r['qty'], 'closed'=>$c ? (int)$c['closed'] : 0, 'busy'=>$busy[$k] ?? 0]; }
