  case 'htl_cab_cal_set': {
    $s = authUser(); htl_tables(); $d = body();
    $q = db()->prepare('SELECT * FROM htl_rooms WHERE id=?'); $q->execute([(string)($d['room_id'] ?? '')]); $r = $q->fetch(); if (!$r) fail('Номер не найден');
    htl_can($s, $r['hotel_id']);
    $a = (string)($d['from'] ?? ''); $b = (string)($d['to'] ?? $a);
    if (!preg_match('~^\d{4}-\d{2}-\d{2}$~', $a) || !preg_match('~^\d{4}-\d{2}-\d{2}$~', $b) || $b < $a) fail('Проверьте даты');
    if ((strtotime($b) - strtotime($a)) / 86400 > 400) fail('Не больше года за раз');
    $wd = array_map('intval', (array)($d['weekdays'] ?? [])); // 1=пн … 7=вс; пусто — все дни
    $price = isset($d['price']) && $d['price'] !== '' && $d['price'] !== null ? max(0, (int)$d['price']) : null;
    $avail = isset($d['avail']) && $d['avail'] !== '' && $d['avail'] !== null ? max(0, (int)$d['avail']) : null;
    $closed = isset($d['closed']) ? (!empty($d['closed']) ? 1 : 0) : null;
    $reset = !empty($d['reset']);
    $n = 0;
    $ins = db()->prepare('INSERT INTO htl_cal (room_id, day, price, avail, closed) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE price=IF(?,VALUES(price),price), avail=IF(?,VALUES(avail),avail), closed=IF(?,VALUES(closed),closed)');
    for ($t = strtotime($a); $t <= strtotime($b); $t += 86400) {
      if ($wd && !in_array((int)date('N', $t), $wd, true)) continue; $k = date('Y-m-d', $t);
      if ($reset) { db()->prepare('DELETE FROM htl_cal WHERE room_id=? AND day=?')->execute([$r['id'], $k]); $n++; continue; }
      $ins->execute([$r['id'], $k, $price, $avail, (int)($closed ?? 0), $price !== null ? 1 : 0, $avail !== null ? 1 : 0, $closed !== null ? 1 : 0]); $n++;
    }
