    db()->prepare('UPDATE htl_bookings SET status=?, hotel_note=IF(?<>\'\',?,hotel_note) WHERE id=?')->execute([$st, htl_s($d['note'] ?? '', 600), htl_s($d['note'] ?? '', 600), (string)($d['id'] ?? '')]);
