    // не тому. Поэтому ключ таблицы — сама метка, а не телефон.
    db()->prepare('INSERT INTO push_tokens (token,phone,platform,updated_at) VALUES (?,?,?,NOW())
                   ON DUPLICATE KEY UPDATE phone=VALUES(phone),platform=VALUES(platform),updated_at=NOW()')
        ->execute([$tok, $s['phone'], $plat]);
