  // ============================================================
  //  CRM · КЛИЕНТСКАЯ БАЗА (22.08.2026)
  //  Компания, её реквизиты и контактные лица. Контактных лиц может быть
  //  несколько: у крупного клиента разные люди ведут разные направления —
  //  посуду, мебель. Поэтому у каждого своё поле «направление».
  //  ПРАВА проверяются здесь, а не только в меню.
  // ============================================================

  // ============================================================
  //  CRM · РАСХОДЫ КОМПАНИИ (22.08.2026)
  //  Вбивает бухгалтер, общую картину «в плюсе или в убытке» видит только
  //  босс — она собирается отдельной командой.
  // ============================================================

  // ============================================================
  //  CRM · СВОДКА БОССА (22.08.2026)
  //  Прибыль по закрытым сделкам минус расходы компании за тот же период.
  //  Доступ только боссу — эту команду больше никто вызвать не может.
  // ============================================================
  case 'crm_summary': {
    crm_auth(['boss']);
    crm_tables();
    $p = trim($_GET['period'] ?? 'month');
    $to = date('Y-m-d');
    if     ($p === 'week')    $from = date('Y-m-d', strtotime('-6 days'));
    elseif ($p === 'quarter') $from = date('Y-m-d', strtotime('-2 months', strtotime(date('Y-m-01'))));
    elseif ($p === 'year')    $from = date('Y-01-01');
    else { $p = 'month'; $from = date('Y-m-01'); }
    if (!empty($_GET['from'])) { $from = trim($_GET['from']); $p = 'custom'; }
    if (!empty($_GET['to']))   { $to   = trim($_GET['to']);   $p = 'custom'; }

    /* СДЕЛКИ. В сводку берём ЗАКРЫТЫЕ — по ним поставка завершена и цифры
       окончательные. Открытые считаем отдельно, чтобы было видно, что ещё
       в работе, но в прибыль их не тянем. */
    $q = db()->prepare("SELECT d.id, d.title, d.kind, d.status, d.sold_plan, d.sold_fact, d.closed_on,
                               c.alias, c.company
                        FROM crm_deals d LEFT JOIN crm_clients c ON c.id=d.client_id
                        WHERE (d.status='closed' AND d.closed_on BETWEEN ? AND ?)
                           OR d.status='open'");
    $q->execute([$from, $to]);
    $deals = $q->fetchAll();

    $ids = array_column($deals, 'id');
    $cost = [];
    if ($ids) {
      $in = implode(',', array_fill(0, count($ids), '?'));
      $q2 = db()->prepare("SELECT deal_id, SUM(plan) p, SUM(fact) f FROM crm_deal_costs WHERE deal_id IN ($in) GROUP BY deal_id");
      $q2->execute($ids);
      foreach ($q2->fetchAll() as $x) $cost[$x['deal_id']] = ['p'=>(float)$x['p'], 'f'=>(float)$x['f']];
    }

    $closed = []; $open = [];
    $revenue = 0; $spent = 0; $white = 0; $cargo = 0;
    foreach ($deals as $d) {
      $cp = $cost[$d['id']]['p'] ?? 0;
      $cf = $cost[$d['id']]['f'] ?? 0;
      /* Считаем по факту, а где факта нет — по расчёту. Иначе свежая
         сделка без фактических цифр обнулила бы всю картину. */
      $sold = (float)$d['sold_fact'] ?: (float)$d['sold_plan'];
      $used = $cf ?: $cp;
      $row = ['id'=>$d['id'], 'title'=>$d['title'], 'kind'=>$d['kind'],
              'who'=>($d['alias'] ?: $d['company']), 'sold'=>$sold, 'cost'=>$used,
              'margin'=>$sold - $used, 'closed_on'=>$d['closed_on']];
      if ($d['status'] === 'closed') {
        $closed[] = $row;
        $revenue += $sold; $spent += $used;
        if ($d['kind'] === 'cargo') $cargo += $sold - $used; else $white += $sold - $used;
      } else {
        $open[] = $row;
      }
    }
    $dealProfit = $revenue - $spent;

    /* РАСХОДЫ КОМПАНИИ за тот же период. */
    $q = db()->prepare('SELECT label, SUM(amount) s FROM crm_expenses WHERE paid_on BETWEEN ? AND ? GROUP BY label ORDER BY s DESC');
    $q->execute([$from, $to]);
    $expRows = $q->fetchAll();
    $expTotal = 0;
    foreach ($expRows as $r) $expTotal += (float)$r['s'];

    usort($closed, function($a,$b){ return $b['margin'] <=> $a['margin']; });

    jout([
      'ok'=>true, 'period'=>$p, 'from'=>$from, 'to'=>$to,
      'revenue'=>$revenue,           // за сколько продано
      'deal_cost'=>$spent,           // расходы по сделкам
      'deal_profit'=>$dealProfit,    // заработано на сделках
      'exp_total'=>$expTotal,        // расходы компании
      'bottom'=>$dealProfit - $expTotal,   // в плюсе или в убытке
      'white'=>$white, 'cargo'=>$cargo,
      'closed'=>$closed, 'open'=>$open,
      'expenses'=>$expRows,
    ]);
  }

  // ---- Обычные статьи расходов компании ----
  case 'crm_exp_kinds': {
    crm_auth(['boss','accountant','chief_accountant']);
    jout(['ok'=>true, 'rows'=>crm_exp_kinds()]);
  }

  // ---- Список расходов за период ----
  case 'crm_expenses': {
    crm_auth(['boss','accountant','chief_accountant']);
    crm_tables();
    $from = trim($_GET['from'] ?? '');
    $to   = trim($_GET['to'] ?? '');
    if ($from === '') $from = date('Y-m-01');
    if ($to === '')   $to   = date('Y-m-d');
    $st = db()->prepare('SELECT * FROM crm_expenses WHERE paid_on BETWEEN ? AND ? ORDER BY paid_on DESC, id DESC LIMIT 500');
    $st->execute([$from, $to]);
    $rows = $st->fetchAll();
    $sum = 0; $cash = 0; $bank = 0;
    foreach ($rows as $r) {
      $sum += (float)$r['amount'];
      if ($r['pay_way'] === 'cash') $cash += (float)$r['amount']; else $bank += (float)$r['amount'];
    }
    jout(['ok'=>true, 'rows'=>$rows, 'from'=>$from, 'to'=>$to,
          'sum'=>$sum, 'cash'=>$cash, 'bank'=>$bank]);
  }

  // ---- Записать или изменить расход ----
  case 'crm_exp_save': {
    $s = crm_auth(['boss','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $label = trim($d['label'] ?? '');
    $amount = (float)($d['amount'] ?? 0);
    if ($label === '') fail('Впишите статью расхода');
    if ($amount <= 0) fail('Сумма должна быть больше нуля');
    $paid = trim($d['paid_on'] ?? '');
    if ($paid === '') $paid = date('Y-m-d');
    $way = (($d['pay_way'] ?? '') === 'cash') ? 'cash' : 'bank';
    $id = trim($d['id'] ?? '');
    if ($id !== '') {
      db()->prepare('UPDATE crm_expenses SET label=?,amount=?,paid_on=?,pay_way=?,note=? WHERE id=?')
          ->execute([$label, $amount, $paid, $way, trim($d['note'] ?? ''), $id]);
    } else {
      $id = gen('ex');
      db()->prepare('INSERT INTO crm_expenses (id,label,amount,paid_on,pay_way,note,created_at,created_by)
                     VALUES (?,?,?,?,?,?,NOW(),?)')
          ->execute([$id, $label, $amount, $paid, $way, trim($d['note'] ?? ''), $s['phone']]);
    }
    jout(['ok'=>true, 'id'=>$id]);
  }

  // ---- Постоянные расходы: список с отметкой, внесён ли уже этот месяц ----
  case 'crm_fixed': {
    crm_auth(['boss','accountant','chief_accountant']);
    crm_tables();
    $rows = db()->query('SELECT * FROM crm_exp_fixed WHERE active=1 ORDER BY day, label')->fetchAll();
    /* Смотрим, есть ли уже такая статья в расходах текущего месяца —
       чтобы бухгалтер случайно не внёс аренду дважды. */
    $from = date('Y-m-01'); $to = date('Y-m-t');
    $st = db()->prepare('SELECT label FROM crm_expenses WHERE paid_on BETWEEN ? AND ?');
    $st->execute([$from, $to]);
    $done = [];
    foreach ($st->fetchAll(PDO::FETCH_COLUMN) as $l) $done[mb_strtolower(trim($l))] = true;
    foreach ($rows as &$r) $r['done'] = isset($done[mb_strtolower(trim($r['label']))]);
    jout(['ok'=>true, 'rows'=>$rows, 'month'=>date('m.Y')]);
  }

  // ---- Сделать расход постоянным (или изменить образец) ----
  case 'crm_fixed_save': {
    crm_auth(['boss','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $label = trim($d['label'] ?? '');
    if ($label === '') fail('Впишите статью расхода');
    $way = (($d['pay_way'] ?? '') === 'cash') ? 'cash' : 'bank';
    $day = (int)($d['day'] ?? 1);
    if ($day < 1 || $day > 28) $day = 1;
    $id = trim($d['id'] ?? '');
    if ($id !== '') {
      db()->prepare('UPDATE crm_exp_fixed SET label=?,amount=?,pay_way=?,day=?,note=? WHERE id=?')
          ->execute([$label, (float)($d['amount'] ?? 0), $way, $day, trim($d['note'] ?? ''), $id]);
    } else {
      /* Дубликат по названию не заводим — иначе список зарастёт. */
      $q = db()->prepare('SELECT id FROM crm_exp_fixed WHERE label=? AND active=1');
      $q->execute([$label]);
      if ($q->fetchColumn()) fail('Такой постоянный расход уже есть');
      $id = gen('fx');
      db()->prepare('INSERT INTO crm_exp_fixed (id,label,amount,pay_way,day,note) VALUES (?,?,?,?,?,?)')
          ->execute([$id, $label, (float)($d['amount'] ?? 0), $way, $day, trim($d['note'] ?? '')]);
    }
    jout(['ok'=>true, 'id'=>$id]);
  }

  // ---- Убрать из постоянных ----
  case 'crm_fixed_del': {
    crm_auth(['boss','accountant','chief_accountant']);
    crm_tables();
    $id = trim(body()['id'] ?? '');
    if ($id !== '') db()->prepare('DELETE FROM crm_exp_fixed WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }

  // ---- Внести постоянные расходы за месяц ----
  //  Кладём в обычные расходы. Что уже внесено в этом месяце — пропускаем.
  case 'crm_fixed_apply': {
    $s = crm_auth(['boss','accountant','chief_accountant']);
    crm_tables();
    $ids = body()['ids'] ?? [];
    if (!is_array($ids) || !$ids) fail('Не выбрано ни одного расхода');
    $in = implode(',', array_fill(0, count($ids), '?'));
    $q = db()->prepare("SELECT * FROM crm_exp_fixed WHERE id IN ($in)");
    $q->execute($ids);
    $rows = $q->fetchAll();

    $from = date('Y-m-01'); $to = date('Y-m-t');
    $st = db()->prepare('SELECT label FROM crm_expenses WHERE paid_on BETWEEN ? AND ?');
    $st->execute([$from, $to]);
    $done = [];
    foreach ($st->fetchAll(PDO::FETCH_COLUMN) as $l) $done[mb_strtolower(trim($l))] = true;

    $added = 0; $skipped = 0;
    foreach ($rows as $r) {
      if (isset($done[mb_strtolower(trim($r['label']))])) { $skipped++; continue; }
      $day = max(1, min(28, (int)$r['day']));
      $date = date('Y-m-') . str_pad($day, 2, '0', STR_PAD_LEFT);
      db()->prepare('INSERT INTO crm_expenses (id,label,amount,paid_on,pay_way,note,created_at,created_by)
                     VALUES (?,?,?,?,?,?,NOW(),?)')
          ->execute([gen('ex'), $r['label'], (float)$r['amount'], $date, $r['pay_way'],
                     trim($r['note'] ?? ''), $s['phone']]);
      $added++;
    }
    jout(['ok'=>true, 'added'=>$added, 'skipped'=>$skipped]);
  }

  // ---- Удалить расход ----
  case 'crm_exp_del': {
    crm_auth(['boss','accountant','chief_accountant']);
    crm_tables();
    $id = trim(body()['id'] ?? '');
    if ($id !== '') db()->prepare('DELETE FROM crm_expenses WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }

  // ============================================================
  //  CRM · СДЕЛКИ (22.08.2026)
  //  Каждая сделка — одна поставка. У расходов две суммы: по расчёту и
  //  фактическая. Маржу показываем ТОЛЬКО боссу — остальные видят состав
  //  расходов, но не заработок.
  // ============================================================

  // ---- Статьи расходов по умолчанию ----
  case 'crm_cost_kinds': {
    crm_auth(['boss','manager','accountant','chief_accountant']);
    jout(['ok'=>true, 'rows'=>crm_cost_kinds()]);
  }

  // ---- Список сделок ----
  case 'crm_deals': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $st = trim($_GET['status'] ?? 'open');
    $sql = "SELECT d.*, c.alias, c.company FROM crm_deals d
            LEFT JOIN crm_clients c ON c.id=d.client_id";
    $args = [];
    if ($st === 'open' || $st === 'closed') { $sql .= " WHERE d.status=?"; $args[] = $st; }
    $sql .= " ORDER BY d.created_at DESC LIMIT 300";
    $q = db()->prepare($sql); $q->execute($args);
    $rows = $q->fetchAll();
    // суммы расходов одним запросом, чтобы не дёргать базу по кругу
    $ids = array_column($rows, 'id');
    $sum = [];
    if ($ids) {
      $in = implode(',', array_fill(0, count($ids), '?'));
      $q2 = db()->prepare("SELECT deal_id, SUM(plan) p, SUM(fact) f FROM crm_deal_costs WHERE deal_id IN ($in) GROUP BY deal_id");
      $q2->execute($ids);
      foreach ($q2->fetchAll() as $x) $sum[$x['deal_id']] = ['p'=>(float)$x['p'], 'f'=>(float)$x['f']];
    }
    $boss = (($s['staff_role'] ?? '') === 'boss');
    foreach ($rows as &$r) {
      $p = $sum[$r['id']]['p'] ?? 0;
      $f = $sum[$r['id']]['f'] ?? 0;
      $r['cost_plan'] = $p;
      $r['cost_fact'] = $f;
      if ($boss) {
        $r['margin_plan'] = (float)$r['sold_plan'] - $p;
        $r['margin_fact'] = (float)$r['sold_fact'] - $f;
      } else {
        unset($r['sold_plan'], $r['sold_fact'], $r['cost_plan'], $r['cost_fact']);
      }
    }
    jout(['ok'=>true, 'rows'=>$rows, 'margin'=>$boss]);
  }

  // ---- Одна сделка со всеми расходами ----
  case 'crm_deal': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $id = trim($_GET['id'] ?? '');
    $q = db()->prepare("SELECT d.*, c.alias, c.company FROM crm_deals d
                        LEFT JOIN crm_clients c ON c.id=d.client_id WHERE d.id=?");
    $q->execute([$id]);
    $d = $q->fetch();
    if (!$d) fail('Сделка не найдена', 404);
    $q = db()->prepare('SELECT * FROM crm_deal_costs WHERE deal_id=? ORDER BY sort, id');
    $q->execute([$id]);
    $costs = $q->fetchAll();
    $boss = (($s['staff_role'] ?? '') === 'boss');
    $p = 0; $f = 0;
    foreach ($costs as $c) { $p += (float)$c['plan']; $f += (float)$c['fact']; }
    $out = ['ok'=>true, 'deal'=>$d, 'costs'=>$costs, 'cost_plan'=>$p, 'cost_fact'=>$f, 'margin'=>$boss];
    if ($boss) {
      $out['margin_plan'] = (float)$d['sold_plan'] - $p;
      $out['margin_fact'] = (float)$d['sold_fact'] - $f;
    } else {
      unset($out['deal']['sold_plan'], $out['deal']['sold_fact']);
    }
    jout($out);
  }

  // ---- Завести или изменить сделку ----
  case 'crm_deal_save': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $title = trim($d['title'] ?? '');
    if ($title === '') fail('Впишите название сделки');
    $kind = (($d['kind'] ?? '') === 'cargo') ? 'cargo' : 'white';
    $st   = (($d['status'] ?? '') === 'closed') ? 'closed' : 'open';
    $id = trim($d['id'] ?? '');
    /* Суммы продажи меняет только босс: это и есть заработок. */
    $boss = (($s['staff_role'] ?? '') === 'boss');
    if ($id !== '') {
      if ($boss) {
        db()->prepare('UPDATE crm_deals SET client_id=?,title=?,kind=?,status=?,sold_plan=?,sold_fact=?,note=?,closed_on=? WHERE id=?')
            ->execute([trim($d['client_id'] ?? ''), $title, $kind, $st,
                       (float)($d['sold_plan'] ?? 0), (float)($d['sold_fact'] ?? 0),
                       trim($d['note'] ?? ''), ($st==='closed' ? date('Y-m-d') : null), $id]);
      } else {
        db()->prepare('UPDATE crm_deals SET client_id=?,title=?,kind=?,status=?,note=?,closed_on=? WHERE id=?')
            ->execute([trim($d['client_id'] ?? ''), $title, $kind, $st,
                       trim($d['note'] ?? ''), ($st==='closed' ? date('Y-m-d') : null), $id]);
      }
    } else {
      $id = gen('dl');
      db()->prepare('INSERT INTO crm_deals (id,client_id,title,kind,status,sold_plan,sold_fact,started_on,note,created_at,created_by)
                     VALUES (?,?,?,?,?,?,?,?,?,NOW(),?)')
          ->execute([$id, trim($d['client_id'] ?? ''), $title, $kind, $st,
                     $boss ? (float)($d['sold_plan'] ?? 0) : 0,
                     $boss ? (float)($d['sold_fact'] ?? 0) : 0,
                     date('Y-m-d'), trim($d['note'] ?? ''), $s['phone']]);
      /* Сразу кладём обычные статьи расходов, чтобы не вбивать их руками. */
      $i = 0;
      foreach (crm_cost_kinds() as $k) {
        db()->prepare('INSERT INTO crm_deal_costs (id,deal_id,kind,label,plan,fact,sort) VALUES (?,?,?,?,0,0,?)')
            ->execute([gen('dc'), $id, $k['kind'], $k['label'], $i++]);
      }
    }
    jout(['ok'=>true, 'id'=>$id]);
  }

  // ---- Сохранить суммы расходов (сразу пачкой) ----
  case 'crm_deal_costs_save': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $deal = trim($d['deal_id'] ?? '');
    if ($deal === '') fail('Не указана сделка');
    foreach (($d['rows'] ?? []) as $r) {
      $rid = trim($r['id'] ?? '');
      if ($rid === '') continue;
      db()->prepare('UPDATE crm_deal_costs SET plan=?,fact=?,label=? WHERE id=? AND deal_id=?')
          ->execute([(float)($r['plan'] ?? 0), (float)($r['fact'] ?? 0),
                     trim($r['label'] ?? ''), $rid, $deal]);
    }
    jout(['ok'=>true]);
  }

  // ---- Добавить свою статью расходов ----
  case 'crm_deal_cost_add': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $deal = trim($d['deal_id'] ?? '');
    $label = trim($d['label'] ?? '');
    if ($deal === '' || $label === '') fail('Нужны сделка и название статьи');
    $id = gen('dc');
    db()->prepare('INSERT INTO crm_deal_costs (id,deal_id,kind,label,plan,fact,sort) VALUES (?,?,?,?,?,?,99)')
        ->execute([$id, $deal, 'own', $label, (float)($d['plan'] ?? 0), (float)($d['fact'] ?? 0)]);
    jout(['ok'=>true, 'id'=>$id]);
  }

  // ---- Убрать статью ----
  case 'crm_deal_cost_del': {
    crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $id = trim(body()['id'] ?? '');
    if ($id !== '') db()->prepare('DELETE FROM crm_deal_costs WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }

  // ---- Удалить сделку (только босс) ----
  case 'crm_deal_del': {
    crm_auth(['boss']);
    crm_tables();
    $id = trim(body()['id'] ?? '');
    if ($id !== '') {
      db()->prepare('DELETE FROM crm_deal_costs WHERE deal_id=?')->execute([$id]);
      db()->prepare('DELETE FROM crm_deals WHERE id=?')->execute([$id]);
    }
    jout(['ok'=>true]);
  }

  // ---- Сохранить КП в карточку клиента ----
  case 'crm_kp_save': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $cid = trim($d['client_id'] ?? '');
    if ($cid === '') fail('Не выбран клиент');
    $id = gen('kp');
    db()->prepare('INSERT INTO crm_kp (id,client_id,no,dt,total,items,created_at,created_by)
                   VALUES (?,?,?,?,?,?,NOW(),?)')
        ->execute([
          $id, $cid,
          trim($d['no'] ?? ''), trim($d['dt'] ?? ''),
          (float)($d['total'] ?? 0),
          json_encode($d['items'] ?? [], JSON_UNESCAPED_UNICODE),
          $s['phone'],
        ]);
    jout(['ok'=>true, 'id'=>$id]);
  }

  // ---- Список КП клиента ----
  case 'crm_kp_list': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $cid = trim($_GET['client_id'] ?? '');
    $st = db()->prepare('SELECT id,no,dt,total,created_at FROM crm_kp WHERE client_id=? ORDER BY created_at DESC LIMIT 100');
    $st->execute([$cid]);
    jout(['ok'=>true, 'rows'=>$st->fetchAll()]);
  }

  // ---- Подтянуть реквизиты по ИНН из открытых реестров ----
  //  Пользуемся тем же DaData, что и счета юрлиц. Ответ НЕ сохраняем —
  //  человек смотрит, что подтянулось, и сам нажимает «Сохранить».
  case 'crm_inn': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    $inn = preg_replace('/\D+/', '', $_GET['inn'] ?? '');
    if (strlen($inn) < 10) fail('ИНН должен быть 10 или 12 цифр');
    $r = dadata_call('findById/party', ['query'=>$inn, 'count'=>1]);
    if (!$r || empty($r['suggestions'][0])) fail('По этому ИНН ничего не найдено');
    $x = $r['suggestions'][0];
    $d = $x['data'] ?? [];
    jout([
      'ok'      => true,
      'company' => $x['value'] ?? '',
      'full'    => $d['name']['full_with_opf'] ?? '',
      'inn'     => $d['inn'] ?? $inn,
      'kpp'     => $d['kpp'] ?? '',
      'ogrn'    => $d['ogrn'] ?? '',
      'addr'    => $d['address']['unrestricted_value'] ?? ($d['address']['value'] ?? ''),
      'status'  => $d['state']['status'] ?? '',
      'head'    => $d['management']['name'] ?? '',
    ]);
  }

  // ---- Список клиентов ----
  case 'crm_clients': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $q = trim($_GET['q'] ?? '');
    if ($q !== '') {
      $st = db()->prepare("SELECT * FROM crm_clients
                           WHERE alias LIKE ? OR company LIKE ? OR inn LIKE ? OR site LIKE ?
                           ORDER BY IF(alias<>'',alias,company) LIMIT 300");
      $like = '%'.$q.'%';
      $st->execute([$like,$like,$like,$like]);
    } else {
      $st = db()->query("SELECT * FROM crm_clients ORDER BY IF(alias<>'',alias,company) LIMIT 300");
    }
    $rows = $st->fetchAll();
    // К каждому клиенту — сколько у него контактных лиц, чтобы список был живее
    $ids = array_column($rows, 'id');
    $cnt = [];
    if ($ids) {
      $in = implode(',', array_fill(0, count($ids), '?'));
      $st2 = db()->prepare("SELECT client_id, COUNT(*) c FROM crm_contacts WHERE client_id IN ($in) GROUP BY client_id");
      $st2->execute($ids);
      foreach ($st2->fetchAll() as $x) $cnt[$x['client_id']] = (int)$x['c'];
    }
    foreach ($rows as &$r) $r['contacts'] = $cnt[$r['id']] ?? 0;
    jout(['ok'=>true, 'rows'=>$rows]);
  }

  // ---- Одна карточка: клиент + его контактные лица ----
  case 'crm_client': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $id = trim($_GET['id'] ?? '');
    $st = db()->prepare('SELECT * FROM crm_clients WHERE id=?');
    $st->execute([$id]);
    $c = $st->fetch();
    if (!$c) fail('Клиент не найден', 404);
    $st = db()->prepare('SELECT * FROM crm_contacts WHERE client_id=? ORDER BY name');
    $st->execute([$id]);
    $contacts = $st->fetchAll();
    $st = db()->prepare('SELECT id,no,dt,total,created_at FROM crm_kp WHERE client_id=? ORDER BY created_at DESC LIMIT 50');
    $st->execute([$id]);
    jout(['ok'=>true, 'client'=>$c, 'contacts'=>$contacts, 'kp'=>$st->fetchAll()]);
  }

  // ---- Завести или изменить клиента ----
  case 'crm_client_save': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $company = trim($d['company'] ?? '');
    $alias   = trim($d['alias'] ?? '');
    /* Клиента часто заводят до того, как узнают его юридическое имя —
       «магазин Яблоко». Поэтому хватает любого из двух названий. */
    if ($alias === '' && $company === '') fail('Впишите хотя бы псевдоним');
    $f = [
      'alias'   => $alias,
      'company' => $company,
      'inn'     => trim($d['inn'] ?? ''),
      'kpp'     => trim($d['kpp'] ?? ''),
      'ogrn'    => trim($d['ogrn'] ?? ''),
      'addr'    => trim($d['addr'] ?? ''),
      'bank'    => trim($d['bank'] ?? ''),
      'bik'     => trim($d['bik'] ?? ''),
      'acct'    => trim($d['acct'] ?? ''),
      'corr'    => trim($d['corr'] ?? ''),
      'site'    => trim($d['site'] ?? ''),
      'note'    => trim($d['note'] ?? ''),
    ];
    $id = trim($d['id'] ?? '');
    if ($id !== '') {
      $sets = implode(',', array_map(function($k){ return "$k=?"; }, array_keys($f)));
      $st = db()->prepare("UPDATE crm_clients SET $sets WHERE id=?");
      $st->execute(array_merge(array_values($f), [$id]));
    } else {
      $id = gen('cl');
      $cols = implode(',', array_keys($f));
      $qs   = implode(',', array_fill(0, count($f), '?'));
      db()->prepare("INSERT INTO crm_clients (id,$cols,created_at,created_by) VALUES (?,$qs,NOW(),?)")
          ->execute(array_merge([$id], array_values($f), [$s['phone']]));
    }
    jout(['ok'=>true, 'id'=>$id]);
  }

  // ---- Контактное лицо: добавить или изменить ----
  case 'crm_contact_save': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $d = body();
    $client_id = trim($d['client_id'] ?? '');
    $name = trim($d['name'] ?? '');
    if ($client_id === '' || $name === '') fail('Нужны клиент и имя');
    $f = [
      'client_id' => $client_id,
      'name'      => $name,
      'post'      => trim($d['post'] ?? ''),
      'area'      => trim($d['area'] ?? ''),   // направление: посуда, мебель…
      'phone'     => trim($d['phone'] ?? ''),
      'email'     => trim($d['email'] ?? ''),
      'note'      => trim($d['note'] ?? ''),
    ];
    $id = trim($d['id'] ?? '');
    if ($id !== '') {
      $sets = implode(',', array_map(function($k){ return "$k=?"; }, array_keys($f)));
      db()->prepare("UPDATE crm_contacts SET $sets WHERE id=?")
          ->execute(array_merge(array_values($f), [$id]));
    } else {
      $id = gen('ct');
      $cols = implode(',', array_keys($f));
      $qs   = implode(',', array_fill(0, count($f), '?'));
      db()->prepare("INSERT INTO crm_contacts (id,$cols) VALUES (?,$qs)")
          ->execute(array_merge([$id], array_values($f)));
    }
    jout(['ok'=>true, 'id'=>$id]);
  }

  // ---- Удалить контактное лицо ----
  case 'crm_contact_del': {
    $s = crm_auth(['boss','manager','accountant','chief_accountant']);
    crm_tables();
    $id = trim(body()['id'] ?? '');
    if ($id !== '') db()->prepare('DELETE FROM crm_contacts WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }

  // ---- Удалить клиента (только босс) ----
  case 'crm_client_del': {
    $s = crm_auth(['boss']);
    crm_tables();
    $id = trim(body()['id'] ?? '');
    if ($id !== '') {
      db()->prepare('DELETE FROM crm_contacts WHERE client_id=?')->execute([$id]);
      db()->prepare('DELETE FROM crm_clients WHERE id=?')->execute([$id]);
    }
    jout(['ok'=>true]);
  }

  // ---- №237 · Вся история клиента: сделки воронок, учёт сделок, КП, счета,
