  // ---- Найти файл ключа Firebase на сервере ----
  //  Служебная команда: показывает точный путь к ключу и проверяет, что он
  //  читается. Нужна один раз, при настройке.
  case 'fcm_find': {
    if (($_GET['key'] ?? '') !== 'a7f3c9e15b2d84itc') fail('Нет доступа', 403);
    header('Content-Type: text/plain; charset=utf-8');
    $home = dirname(dirname(dirname(__DIR__)));   // от api/ вверх до дома
    $roots = array_unique([
      $home, dirname($home), dirname(dirname(__DIR__)), '/var/www/'.get_current_user(),
    ]);
    echo "Папка этого файла: " . __DIR__ . "\n";
    echo "Ищу ключ...\n\n";
    $found = [];
    foreach ($roots as $r) {
      foreach (['/private/firebase-key', '/private/firebase-key.json', '/data/private/firebase-key'] as $suf) {
        $f = $r . $suf;
        if (is_file($f)) $found[] = $f;
      }
    }
    if (!$found) {
      echo "НЕ НАЙДЕН. Проверял в:\n";
      foreach ($roots as $r) echo "  " . $r . "/private/\n";
    } else {
      foreach (array_unique($found) as $f) {
        echo "НАЙДЕН: " . $f . "\n";
        $j = json_decode(@file_get_contents($f), true);
        echo "  читается: " . (is_array($j) ? "да" : "НЕТ") . "\n";
        if (is_array($j)) {
          echo "  проект: " . ($j['project_id'] ?? '?') . "\n";
          echo "  ключ внутри: " . (empty($j['private_key']) ? "НЕТ" : "есть") . "\n";
        }
        echo "\n  ВПИСАТЬ В config.php:\n";
        echo "  define('FCM_KEY_FILE', '" . $f . "');\n";
      }
    }
    echo "\nСейчас в config.php записано: " . (defined('FCM_KEY_FILE') ? FCM_KEY_FILE : '(строки нет)') . "\n";
    exit;
  }

