  // ---- PUSH: сохранить подписку покупателя ----
  case 'push_subscribe': {
    $s = authUser('buyer');
    $d = body();
    $endpoint = trim($d['endpoint'] ?? '');
    $p256dh = trim($d['p256dh'] ?? '');
    $auth = trim($d['auth'] ?? '');
    if (!$endpoint || !$p256dh || !$auth) fail('Неполные данные подписки');
    $hash = hash('sha256', $endpoint);
    try {
      db()->prepare('INSERT INTO push_subs (id,phone,endpoint,endpoint_hash,p256dh,auth) VALUES (?,?,?,?,?,?)
                     ON DUPLICATE KEY UPDATE phone=VALUES(phone),p256dh=VALUES(p256dh),auth=VALUES(auth),endpoint=VALUES(endpoint)')
          ->execute([gen('ps'), $s['phone'], $endpoint, $hash, $p256dh, $auth]);
    } catch (Exception $e) { fail('Сначала выполните миграцию (push_subs)'); }
    jout(['ok'=>true]);
  }
  // ---- PUSH: удалить подписку ----
  case 'push_unsubscribe': {
    $s = authUser('buyer');
    $endpoint = trim(body()['endpoint'] ?? '');
    if ($endpoint) { try { db()->prepare('DELETE FROM push_subs WHERE endpoint_hash=?')->execute([hash('sha256',$endpoint)]); } catch (Exception $e) {} }
    jout(['ok'=>true]);
  }
