  // ---- КОРЗИНА: получить серверную корзину ----
  case 'cart_get': {
    $s = authUser('buyer');
    $items = [];
    try { $q = db()->prepare('SELECT items FROM carts WHERE phone=?'); $q->execute([$s['phone']]); $j = $q->fetchColumn(); if ($j) { $arr = json_decode($j, true); if (is_array($arr)) $items = $arr; } }
    catch (Exception $e) {}
    jout(['ok' => true, 'items' => $items]);
  }
  // ---- КОРЗИНА: сохранить серверную корзину ----
  case 'cart_save': {
    $s = authUser('buyer');
    $d = body();
    $items = $d['items'] ?? [];
    if (!is_array($items)) $items = [];
    // нормализуем — только нужные поля
    $clean = [];
    foreach ($items as $it) {
      if (!is_array($it) || empty($it['id'])) continue;
      $clean[] = ['id' => (string)$it['id'], 'qty' => max(1, (int)($it['qty'] ?? 1)), 'color' => mb_substr((string)($it['color'] ?? ''), 0, 60)];
      if (count($clean) >= 200) break;
    }
    $json = json_encode($clean, JSON_UNESCAPED_UNICODE);
    try { db()->prepare('INSERT INTO carts (phone,items) VALUES (?,?) ON DUPLICATE KEY UPDATE items=VALUES(items)')->execute([$s['phone'], $json]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (carts)'); }
    jout(['ok' => true]);
  }

