  // ---- регистрация покупателя ----
  // ---- покупателя заводит сотрудник вручную (босс или менеджер) ----
  // ---- отметить поставщика как «это наша компания» ----
  case 'supplier_set_own': {
    $s = authUser('itc'); require_staff($s, ['boss','manager']);
    itc_own_supplier_ensure();
    $d = body();
    $id = trim($d['id'] ?? '');
    $on = !empty($d['on']) ? 1 : 0;
    if (!$id) fail('Не указан поставщик');
    try {
      if ($on) db()->query("UPDATE suppliers SET is_own=0");   // «наша» может быть только одна
      db()->prepare("UPDATE suppliers SET is_own=? WHERE id=?")->execute([$on, $id]);
    } catch (Exception $e) { fail('Не удалось сохранить'); }
    // Уже заведённые карточки без поставщика привязываем к ней — иначе счётчик соврёт.
    $moved = 0;
    if ($on) {
      try { $st = db()->prepare("UPDATE products SET supplier_id=? WHERE supplier_id IS NULL OR supplier_id=''");
            $st->execute([$id]); $moved = $st->rowCount(); } catch (Exception $e) {}
    }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'supplier_set_own', 'supplier', $id, (string)$on);
    jout(['ok' => true, 'is_own' => $on, 'moved' => $moved]);
  }

  // ---- удалить покупателя (тестовые записи) ----
  case 'customer_delete': {
    $s = authUser('itc'); require_staff($s, ['boss','manager']);
    $d = body();
    $phone = trim($d['phone'] ?? '');
    if ($phone === '') fail('Не указан телефон');
    // Покупателя с оплаченными заказами не удаляем: за ним стоят деньги и документы
    $paid = 0;
    try { $q = db()->prepare('SELECT COUNT(*) FROM orders WHERE phone=? AND paid=1'); $q->execute([$phone]); $paid = (int)$q->fetchColumn(); }
    catch (Exception $e) {}
    if ($paid > 0) fail('У покупателя есть оплаченные заказы ('.$paid.') — удалять нельзя');
    $name = '';
    try { $g = db()->prepare('SELECT name FROM customers WHERE phone=?'); $g->execute([$phone]); $name = (string)$g->fetchColumn(); } catch (Exception $e) {}
    try { db()->prepare('DELETE FROM customers WHERE phone=?')->execute([$phone]); }
    catch (Exception $e) { fail('Не удалось удалить покупателя'); }
    // хвосты: неоплаченные заказы, вход в приложении, коды из SMS
    try { db()->prepare('DELETE FROM order_items WHERE order_id IN (SELECT id FROM orders WHERE phone=? AND paid=0)')->execute([$phone]); } catch (Exception $e) {}
    try { db()->prepare('DELETE FROM orders   WHERE phone=? AND paid=0')->execute([$phone]); } catch (Exception $e) {}
    try { db()->prepare('DELETE FROM sessions WHERE phone=?')->execute([$phone]); } catch (Exception $e) {}
    try { db()->prepare('DELETE FROM sms_codes WHERE phone=?')->execute([$phone]); } catch (Exception $e) {}
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'customer_delete', 'customer', $phone, $name);
    jout(['ok' => true]);
  }

  case 'customer_create': {
    $s = authUser('itc'); require_staff($s, ['boss','manager']);
    $d = body();
    $phone = preg_replace('/[^0-9+]/', '', trim($d['phone'] ?? ''));
    $name  = trim($d['name'] ?? '');
    $email = trim($d['email'] ?? '');
    if ($phone === '') fail('Укажите телефон');
    if ($name === '')  fail('Укажите ФИО');
    $__c1 = ph_find_customer($phone);
    $phone = ($__c1 && !empty($__c1['phone'])) ? $__c1['phone'] : (ph_norm($phone) ?: $phone);
    $exists = 0;
    try { $c = db()->prepare('SELECT COUNT(*) FROM customers WHERE phone=?'); $c->execute([$phone]); $exists = (int)$c->fetchColumn(); } catch (Exception $e) {}
    try {
      db()->prepare('INSERT INTO customers (phone,name,email,city,street,zip) VALUES (?,?,?,?,?,?)
                     ON DUPLICATE KEY UPDATE name=VALUES(name),email=VALUES(email),city=VALUES(city),street=VALUES(street),zip=VALUES(zip)')
        ->execute([$phone, $name, $email, trim($d['city'] ?? ''), trim($d['street'] ?? ''), trim($d['zip'] ?? '')]);
    } catch (Exception $e) { fail('Не удалось сохранить покупателя'); }
    $wh = trim($d['warehouse_id'] ?? '');
    if ($wh !== '') { try { db()->prepare('UPDATE customers SET warehouse_id=? WHERE phone=?')->execute([$wh, $phone]); } catch (Exception $e) {} }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), ($exists ? 'customer_update' : 'customer_add'), 'customer', $phone, $name);
    jout(['ok' => true, 'phone' => $phone, 'existed' => $exists ? 1 : 0]);
  }

  case 'register_buyer': {
    $d = body();
    $phone = trim($d['phone'] ?? '');
    $name = trim($d['name'] ?? ''); $email = trim($d['email'] ?? '');
    $city = trim($d['city'] ?? ''); $street = trim($d['street'] ?? ''); $zip = trim($d['zip'] ?? '');
    // ФИО теперь тремя отдельными полями — храним и раздельно, и одной строкой
    $last  = trim($d['last_name']  ?? '');
    $first = trim($d['first_name'] ?? '');
    $mid   = trim($d['mid_name']   ?? '');
    if ($name === '' && ($last !== '' || $first !== '')) $name = trim($last.' '.$first.' '.$mid);
    if (!$phone) fail('Укажите телефон');
    /* Тот же единый вид, что и при входе: иначе человек, вошедший как
       «978…», заводил вторую карточку рядом с «+7978…». */
    $__c0 = ph_find_customer($phone);
    $phone = ($__c0 && !empty($__c0['phone'])) ? $__c0['phone'] : (ph_norm($phone) ?: $phone);
    if ($last === '')  fail('Укажите фамилию');
    if ($first === '') fail('Укажите имя');
    if ($mid === '')   fail('Укажите отчество');
    if (!$email) fail('Укажите e-mail');
    $st = db()->prepare(
      'INSERT INTO customers (phone,name,email,city,street,zip) VALUES (?,?,?,?,?,?)
       ON DUPLICATE KEY UPDATE name=VALUES(name),email=VALUES(email),city=VALUES(city),street=VALUES(street),zip=VALUES(zip)');
    $st->execute([$phone, $name, $email, $city, $street, $zip]);
    try { db()->query("ALTER TABLE customers ADD COLUMN last_name VARCHAR(80) NULL"); }  catch (Exception $e) {}
    try { db()->query("ALTER TABLE customers ADD COLUMN first_name VARCHAR(80) NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE customers ADD COLUMN mid_name VARCHAR(80) NULL"); }   catch (Exception $e) {}
    try { db()->prepare('UPDATE customers SET last_name=?, first_name=?, mid_name=? WHERE phone=?')
            ->execute([$last, $first, $mid, $phone]); } catch (Exception $e) {}
    try { db()->prepare('UPDATE customers SET consent_at=NOW() WHERE phone=? AND consent_at IS NULL')->execute([$phone]); } catch (Exception $e) {}
    $src = preg_replace('/[^a-zA-Z0-9_]/', '', substr($d['src'] ?? '', 0, 24));
    if ($src !== '') { try { db()->prepare("UPDATE customers SET src=? WHERE phone=? AND (src IS NULL OR src='')")->execute([$src, $phone]); } catch (Exception $e) {} }
    // реферальная привязка (первый партнёр навсегда)
    $ref = trim($d['ref'] ?? '');
    if ($ref !== '') {
      try {
        $pq = db()->prepare("SELECT id FROM partners WHERE ref_code=? AND status<>'blocked' LIMIT 1"); $pq->execute([$ref]);
        $rpid = $pq->fetchColumn();
        if ($rpid) db()->prepare("UPDATE customers SET ref_partner_id=?, ref_at=NOW() WHERE phone=? AND (ref_partner_id='' OR ref_partner_id IS NULL)")->execute([$rpid, $phone]);
      } catch (Exception $e) {}
    }
    $token = make_session($phone, 'buyer', null);
    /* ПРИВЯЗКА К ПРИГЛАСИВШЕМУ (обновление №220).
       Код приходит из ссылки или QR. Привязываем ОДИН РАЗ и навсегда: если
       человек уже привязан, повторная ссылка ничего не меняет — иначе его
       можно было бы «перехватить» чужим кодом после первой покупки.
       Себя пригласить нельзя. */
    itc_ref_ensure();
    $refc = strtoupper(trim($d['refc'] ?? ''));
    if ($refc !== '') {
      try {
        $iq = db()->prepare('SELECT phone FROM customers WHERE ref_code=? LIMIT 1');
        $iq->execute([$refc]);
        $inviter = (string)$iq->fetchColumn();
        if ($inviter !== '' && $inviter !== $phone) {
          db()->prepare("UPDATE customers SET ref_by=?, ref_by_at=NOW()
                         WHERE phone=? AND (ref_by IS NULL OR ref_by='')")
              ->execute([$refc, $phone]);
        }
      } catch (Exception $e) {}
    }
    itc_ref_code($phone);   // сразу выдаём человеку его собственный код

    /* КОНВЕРТ ЗА РЕГИСТРАЦИЮ. Выдаётся, только если включено в кабинете босса.
       Проверяем, что человек регистрируется ВПЕРВЫЕ: запись в customers
       обновляется и при повторном заходе, а конверт положен один раз. */
    try {
      if (itc_set_get('env_reg_on', '0') === '1') {
        $amt = (int)itc_set_get('env_reg_amount', '200');
        if ($amt > 0) {
          $ch = db()->prepare("SELECT COUNT(*) FROM itc_envelope WHERE phone=? AND reason='За регистрацию'");
          $ch->execute([$phone]);
          if ((int)$ch->fetchColumn() === 0) {
            db()->prepare("INSERT INTO itc_envelope (phone,amount,status,reason,sent_at,open_by)
                           VALUES (?,?,'new','За регистрацию',NOW(),(NOW() + INTERVAL 7 DAY))")
                ->execute([$phone, $amt]);
          }
        }
      }
    } catch (Exception $e) {}
    jout(['ok' => true, 'token' => $token, 'role' => 'buyer', 'name' => $name, 'email' => $email]);
  }

  // ---- регистрация поставщика ----
  case 'register_supplier': {
    $d = body();
    $phone = trim($d['phone'] ?? '');
    $company = trim($d['company'] ?? '');
    $jur = (($d['jurisdiction'] ?? 'ru') === 'cn') ? 'cn' : 'ru';
    $contact = trim($d['contact'] ?? '');
    $email = trim($d['email'] ?? '');
    $zh = trim($d['zh'] ?? '');
    $reg = $d['reg_data'] ?? [];
    // категория оплаты (выбирает поставщик) и налог КНР (справочно)
    // По умолчанию: китайскую фабрику оплачивает Jinjia, российского поставщика — ИТК
    $payco = isset($d['pay_company'])
      ? (($d['pay_company'] === 'jinjia') ? 'jinjia' : 'itk')
      : (($jur === 'cn') ? 'jinjia' : 'itk');
    $cnTax = in_array(($d['cn_tax_status'] ?? ''), ['general','small'], true) ? $d['cn_tax_status'] : null;
    $cnVat = (isset($d['cn_vat_refund']) && $d['cn_vat_refund'] !== '') ? (float)$d['cn_vat_refund'] : null;
    $cnFap = !empty($d['cn_fapiao']) ? 1 : 0;
    if (!$phone || !$company) fail('Укажите телефон и название компании');
    $regJson = json_encode(is_array($reg) ? $reg : [], JSON_UNESCAPED_UNICODE);
    // не создаём дубликат: если телефон уже есть — обновляем существующего
    $ex = db()->prepare("SELECT id FROM suppliers WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') ORDER BY id ASC LIMIT 1");
    $ex->execute([$phone]);
    $exId = $ex->fetchColumn();
    if ($exId) {
      $id = $exId;
      db()->prepare("UPDATE suppliers SET name=?,zh=?,jurisdiction=?,contact=?,email=?,reg_data=?,deposit_paid=1,pay_company=?,cn_tax_status=?,cn_vat_refund=?,cn_fapiao=?,status=CASE WHEN status='blocked' THEN 'blocked' ELSE 'active' END WHERE id=?")
          ->execute([$company, $zh, $jur, $contact, $email, $regJson, $payco, $cnTax, $cnVat, $cnFap, $id]);
    } else {
      $id = gen('s');
      db()->prepare('INSERT INTO suppliers (id,name,zh,phone,jurisdiction,contact,email,status,deposit_paid,reg_data,pay_company,cn_tax_status,cn_vat_refund,cn_fapiao,mod_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
          ->execute([$id, $company, $zh, $phone, $jur, $contact, $email, 'active', 1, $regJson, $payco, $cnTax, $cnVat, $cnFap, 'pending']);
    }
    $token = make_session($phone, 'supplier', $id);
    jout(['ok' => true, 'supplierId' => $id, 'token' => $token, 'role' => 'supplier']);
  }

  // ---- депозит поставщика: создать платёж в ЮKassa ----
  case 'create_deposit': {
    global $SITE_URL;
    $d = body();
    $st = db()->prepare('SELECT * FROM suppliers WHERE id = ?');
    $st->execute([$d['supplierId'] ?? '']);
    $s = $st->fetch();
    if (!$s) fail('Поставщик не найден');
    if ((int)($s['deposit_paid'] ?? 0) === 1) fail('Депозит уже внесён');
    $cny = (float)get_settings()['deposit_cny'];
    $rub = (int)round($cny * get_settings()['kurs_cny']);
    $payload = [
      'amount' => ['value' => number_format($rub, 2, '.', ''), 'currency' => 'RUB'],
      'capture' => true,
      'confirmation' => ['type' => 'redirect', 'return_url' => $SITE_URL . '/?deposit=' . rawurlencode($s['id'])],
      'description' => 'Депозит поставщика — ИТК Мебель',
      'metadata' => ['type' => 'deposit', 'supplier_id' => $s['id']],
    ];
    $pp = yk_request('POST', '/payments', $payload);
    if (!$pp || empty($pp['confirmation']['confirmation_url'])) {
      fail('ЮKassa: не удалось создать платёж' . (isset($pp['description']) ? ' — '.$pp['description'] : ''), 502);
    }
    db()->prepare('UPDATE suppliers SET deposit_payment_id = ? WHERE id = ?')->execute([$pp['id'], $s['id']]);
    jout(['ok' => true, 'confirmation_url' => $pp['confirmation']['confirmation_url']]);
  }

  // ---- загрузка фото/видео в папку uploads (поставщик) ----
  case 'upload_media': {
    global $S3_ENABLED, $S3_PUBLIC_URL;
    authUser();
    if (empty($_FILES['file'])) fail('Файл не получен');
    $f = $_FILES['file'];
    if ($f['error'] !== UPLOAD_ERR_OK) fail('Ошибка загрузки (код ' . $f['error'] . ')');
    if ($f['size'] > 60 * 1024 * 1024) fail('Файл больше 60 МБ');
    $ext = strtolower(pathinfo($f['name'], PATHINFO_EXTENSION));
    // PDF нужен для контракта с фабрикой закупки. Правка уже была, но потерялась
    // при одной из последующих — если её снова не станет, приложить контракт нельзя.
    $allowed = ['jpg','jpeg','png','webp','gif','mp4','webm','mov','m4v','pdf'];
    if (!in_array($ext, $allowed)) fail('Недопустимый тип файла');
    $isImg = in_array($ext, ['jpg','jpeg','png','webp','gif']);
    $isDoc = ($ext === 'pdf');
    if ($isDoc) {
      if ($f['size'] > 25 * 1024 * 1024) fail('Документ больше 25 МБ');
    } elseif ($isImg) {
      $info = @getimagesize($f['tmp_name']);
      if ($info === false) fail('Файл не является изображением');
      if ($f['size'] > 15 * 1024 * 1024) fail('Изображение больше 15 МБ');
    } else {
      $mime = function_exists('finfo_open') ? @finfo_file(finfo_open(FILEINFO_MIME_TYPE), $f['tmp_name']) : '';
      if ($mime && strpos($mime, 'video/') !== 0) fail('Файл не является видео');
    }
    $name = gen('m') . '.' . $ext;
    $ctype = s3_content_type($ext);

    // СЖАТИЕ. Раньше картинка уходила в S3 как есть: баннер на 2.44 МБ так и
    // лёг, а проверялось только «не больше 15 МБ». Жмём тем же ob_img_compress(),
    // которым уже жмутся фото с 1688 — 1000 px, webp, цель 300 КБ.
    // Второе сжатие рядом писать незачем: это ровно та же задача.
    $srcPath = $f['tmp_name'];
    $tmpMade = null;
    if ($isImg && function_exists('ob_img_compress')) {
      $cp = ob_img_compress($f['tmp_name']);
      if (!empty($cp['ok'])) {
        $srcPath = $tmpMade = $cp['path'];
        $ext     = $cp['ext'];                 // png/jpg могли стать webp
        $name    = gen('m') . '.' . $ext;      // имя вслед за расширением
        $ctype   = s3_content_type($ext);
      }
      // Не вышло сжать — не теряем файл, кладём как есть: лучше тяжёлый,
      // чем никакой. Но в лог, чтобы это не осталось незамеченным.
      elseif (!empty($cp['error'])) @error_log('[upload_media] сжатие не вышло: '.$cp['error']);
    }

    if ($S3_ENABLED) {
      $ok = s3_put_object($name, $srcPath, $ctype);
      if ($tmpMade) @unlink($tmpMade);
      if (!$ok) fail('Не удалось загрузить в облако (S3). Проверьте ключи/бакет/регион.', 502);
      jout(['ok' => true, 'url' => rtrim($S3_PUBLIC_URL, '/') . '/' . $name]);
    }
    $dir = __DIR__ . '/../uploads';
    if (!is_dir($dir)) @mkdir($dir, 0755, true);
    if (!is_dir($dir) || !is_writable($dir)) fail('Папка uploads недоступна для записи', 500);
    // Сжатый файл создан нами — move_uploaded_file его не примет, он только
    // для того, что пришло из формы
    $moved = $tmpMade ? @rename($tmpMade, $dir . '/' . $name)
                      : move_uploaded_file($f['tmp_name'], $dir . '/' . $name);
    if (!$moved) fail('Не удалось сохранить файл', 500);
    jout(['ok' => true, 'url' => 'uploads/' . $name]);
  }

  // ---- товары поставщика: добавить ----
  case 'add_product': {
    $s = authUser('supplier');
    $d = body();
    $name = trim($d['name'] ?? '');
    $goods = (int)($d['goods_cny'] ?? 0);
    $vol = (float)($d['volume_m3'] ?? 0);
    if (!$name) fail('Укажите название');
    if ($goods <= 0) fail('Укажите стоимость товара (¥)');
    if ($vol <= 0) fail('Укажите объём упаковки (м³)');
    $wt = boxes_weight($d); if ($wt <= 0) $wt = (float)($d['weight_kg'] ?? 0); $price = calc_landed_rub($goods, $vol, $wt, get_settings(), pays_via_jinjia($s['id'] ?? ''));
    $gallery = $d['gallery'] ?? [];
    $cover = is_array($gallery) && count($gallery) ? $gallery[0] : ($d['img'] ?? '');
    $id = gen('p');
    db()->prepare('INSERT INTO products (id,supplier_id,cat,subcat,name,price,old_price,goods_cny,volume_m3,descr,img,gallery,video,stock,warehouse_id,original) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
        ->execute([$id, $s['supplier_id'], trim($d['cat'] ?? 'Прочее'), trim($d['subcat'] ?? ''), $name, $price, (int)($d['old_price'] ?? 0), $goods, $vol,
                   trim($d['descr'] ?? ''), $cover,
                   json_encode(is_array($gallery) ? $gallery : [], JSON_UNESCAPED_UNICODE),
                   trim($d['video'] ?? ''), (int)($d['stock'] ?? 0), trim($d['warehouse_id'] ?? ''), (int)($d['original'] ?? 1)]);
    stamp_creator($id, $s);
    $disc = max(0, min(95, (int)($d['discount'] ?? 0)));
    if ($disc > 0) { db()->prepare('UPDATE products SET price=?, old_price=? WHERE id=?')->execute([(int)round($price*(100-$disc)/100), $price, $id]); }
    try { db()->prepare('UPDATE products SET discount_percent=? WHERE id=?')->execute([$disc, $id]); } catch (Exception $e) {}
    save_specs($id, $d);
    save_dims($id, $d);
    save_variants($id, $d);
    try { db()->prepare('UPDATE products SET weight_kg=?, pcs_per_box=?, ready_type=?, production_days=? WHERE id=?')->execute([($wt>0?$wt:null), (((int)($d['pcs_per_box']??0))?:null), ((($d['ready_type']??'')==='production')?'production':'in_stock'), (((($d['ready_type']??'')==='production')&&((int)($d['production_days']??0)>0))?(int)$d['production_days']:null), $id]); } catch (Exception $e) {}
    try { db()->prepare("UPDATE products SET mod_status=? WHERE id=?")->execute([(!empty($d['draft'])?'draft':'pending'), $id]); } catch (Exception $e) {}
    jout(['ok' => true, 'id' => $id, 'price' => $price]);
  }

  // ---- товар ОТ ИМЕНИ ИТК: заводит сотрудник, поставщика нет ----
  // Мы сами закупаем у фабрики и продаём на своей площадке, поэтому supplier_id
  // остаётся пустым, а источник закупки хранится в jfactory_id — контакты фабрики
  // (сайт, телефон, WeChat, WhatsApp) сотрудник видит прямо в карточке товара.
  case 'itc_add_product': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    $d = body();
    $name = trim($d['name'] ?? '');
    $goods = (int)($d['goods_cny'] ?? 0);
    $vol = (float)($d['volume_m3'] ?? 0);
    if (!$name) fail('Укажите название');
    if ($goods <= 0) fail('Укажите закупочную цену (¥)');
    if ($vol <= 0) fail('Укажите объём упаковки (м³)');
    $wt = boxes_weight($d); if ($wt <= 0) $wt = (float)($d['weight_kg'] ?? 0);
    $price = calc_landed_rub($goods, $vol, $wt, get_settings(), true);
    $gallery = $d['gallery'] ?? [];
    $cover = is_array($gallery) && count($gallery) ? $gallery[0] : ($d['img'] ?? '');
    $fid = trim($d['jfactory_id'] ?? '');
    $own = itc_own_supplier_id();   // если отмечена «наша» запись — товар числится за ней
    $id = gen('p');
    try { db()->query("ALTER TABLE products ADD COLUMN goods_cny_at DATE NULL"); } catch (Exception $e) {}
    db()->prepare('INSERT INTO products (id,supplier_id,cat,subcat,name,price,old_price,goods_cny,volume_m3,descr,img,gallery,video,stock,warehouse_id,original) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
        ->execute([$id, $own, trim($d['cat'] ?? 'Прочее'), trim($d['subcat'] ?? ''), $name, $price, (int)($d['old_price'] ?? 0), $goods, $vol,
                   trim($d['descr'] ?? ''), $cover,
                   json_encode(is_array($gallery) ? $gallery : [], JSON_UNESCAPED_UNICODE),
                   trim($d['video'] ?? ''), (int)($d['stock'] ?? 0), trim($d['warehouse_id'] ?? ''), (int)($d['original'] ?? 1)]);
    try { stamp_creator($id, $s); } catch (Exception $e) {}
    if ($fid !== '') { try { db()->prepare('UPDATE products SET jfactory_id=? WHERE id=?')->execute([$fid, $id]); } catch (Exception $e) {} }
    // дата закупочной цены — чтобы было видно, на какой день она актуальна
    try { db()->prepare('UPDATE products SET goods_cny_at=CURDATE() WHERE id=?')->execute([$id]); } catch (Exception $e) {}
    $disc = max(0, min(95, (int)($d['discount'] ?? 0)));
    if ($disc > 0) { db()->prepare('UPDATE products SET price=?, old_price=? WHERE id=?')->execute([(int)round($price*(100-$disc)/100), $price, $id]); }
    try { db()->prepare('UPDATE products SET discount_percent=? WHERE id=?')->execute([$disc, $id]); } catch (Exception $e) {}
    save_specs($id, $d);
    save_dims($id, $d);
    save_variants($id, $d);
    try { db()->prepare('UPDATE products SET weight_kg=?, pcs_per_box=?, ready_type=?, production_days=? WHERE id=?')->execute([($wt>0?$wt:null), (((int)($d['pcs_per_box']??0))?:null), ((($d['ready_type']??'')==='production')?'production':'in_stock'), (((($d['ready_type']??'')==='production')&&((int)($d['production_days']??0)>0))?(int)$d['production_days']:null), $id]); } catch (Exception $e) {}
    // свой товар модерацию не проходит — сотрудник сам его и завёл
    try { db()->prepare("UPDATE products SET mod_status=? WHERE id=?")->execute([(!empty($d['draft'])?'draft':'approved'), $id]); } catch (Exception $e) {}
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'itc_product_add', 'product', $id, $fid);
    jout(['ok' => true, 'id' => $id, 'price' => $price]);
  }

  // ---- товары поставщика: редактировать ----
