  // ---- ИТК: пометка «Оригинал» у любого товара ----
  case 'set_original': {
    authUser('itc');
    $d = body();
    $id = $d['id'] ?? '';
    if (!$id) fail('Не указан товар');
    $val = !empty($d['original']) ? 1 : 0;
    db()->prepare('UPDATE products SET original=? WHERE id=?')->execute([$val, $id]);
    jout(['ok' => true, 'id' => $id, 'original' => $val]);
