  // ---- ИТК: модерация товара ----
  case 'approve_all_products': {
    $s = authUser('itc');
    require_staff($s, ['boss','moderator']);
    $by = mb_substr(trim(body()['by'] ?? ''), 0, 120);
    try {
      db()->prepare("UPDATE products SET mod_status='approved', moderated_by=?, moderated_at=NOW() WHERE mod_status IS NULL OR mod_status='' OR mod_status='pending'")->execute([$by]);
      $cnt = db()->query("SELECT COUNT(*) FROM products WHERE mod_status='approved'")->fetchColumn();
      itc_log_add($by,'approve','product','all','Одобрено все товары: '.(int)$cnt);
      jout(['ok'=>true,'approved'=>(int)$cnt]);
    } catch(Exception $e){ fail('Ошибка: '.$e->getMessage()); }
  }

  case 'product_moderate': {
    $s = authUser('itc');
    require_staff($s, ['moderator']);
    $d = body();
    $id = trim($d['id'] ?? '');
    $st = $d['status'] ?? '';
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    if (!$id) fail('Не указан товар');
    if (!in_array($st, ['approved','pending','rejected'], true)) fail('Неверный статус');
    try {
      try {
        db()->prepare('UPDATE products SET mod_status=?, moderated_by=?, moderated_at=NOW() WHERE id=?')->execute([$st, $by, $id]);
      } catch (Exception $e2) {
        db()->prepare('UPDATE products SET mod_status=? WHERE id=?')->execute([$st, $id]);
      }
    } catch (Exception $e) { fail('Сначала выполните миграцию (mod_status)'); }
    $pn = '';
    try { $pr = db()->prepare('SELECT name FROM products WHERE id=?'); $pr->execute([$id]); $pn = $pr->fetchColumn() ?: ''; } catch (Exception $e) {}
    itc_log_add($by, $st==='approved'?'approve':($st==='rejected'?'reject':'unpublish'), 'product', $id, $pn);
    jout(['ok'=>true,'id'=>$id,'mod_status'=>$st]);
  }

  // ---- ИТК: блокировка/разблокировка любого товара ----
  case 'set_blocked': {
    authUser('itc');
    $d = body();
    $id = $d['id'] ?? '';
    if (!$id) fail('Не указан товар');
    $val = !empty($d['blocked']) ? 1 : 0;
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    db()->prepare('UPDATE products SET blocked=? WHERE id=?')->execute([$val, $id]);
    $pn=''; try { $pr=db()->prepare('SELECT name FROM products WHERE id=?'); $pr->execute([$id]); $pn=$pr->fetchColumn()?:''; } catch (Exception $e) {}
    itc_log_add($by, $val?'block':'unblock', 'product', $id, $pn);
    jout(['ok' => true, 'id' => $id, 'blocked' => $val]);
  }

  // ---- ИТК: полное редактирование любого товара (без привязки к поставщику) ----
  case 'itc_update_product': {
    authUser('itc');
    $d = body();
    $id = $d['id'] ?? '';
    $name = trim($d['name'] ?? '');
    $goods = (int)($d['goods_cny'] ?? 0);
    $vol = (float)($d['volume_m3'] ?? 0);
    if (!$id) fail('Не указан товар');
    if (!$name) fail('Укажите название');
    if ($goods <= 0) fail('Укажите стоимость товара (¥)');
    /* Что уже сохранено в товаре. Пустые поля формы НЕ должны стирать замеры
       склада, а при цене по множителю объёма и веса может не быть вовсе. */
    $curPrice = 0; $curVol = 0.0; $curWt = 0.0;
    try {
      $cr = db()->prepare('SELECT price, volume_m3, weight_kg FROM products WHERE id=?');
      $cr->execute([$id]); $cr = $cr->fetch();
      if ($cr) { $curPrice = (int)($cr['price'] ?? 0); $curVol = (float)($cr['volume_m3'] ?? 0); $curWt = (float)($cr['weight_kg'] ?? 0); }
    } catch (Exception $e) {}
    if ($vol <= 0 && $curVol > 0) $vol = $curVol;          // форма пустая — оставляем прежний объём
    $x3m = itc_x3_mult_of_product($id);                    // не null → карточка стоит на множителе ×N
    $wt = boxes_weight($d); if ($wt <= 0) $wt = (float)($d['weight_kg'] ?? 0); if ($wt <= 0 && !empty($d['material']) && $vol > 0 && function_exists('ob_weight_density')) $wt = round($vol * ob_weight_density((string)$d['material']), 1); if ($wt <= 0) { try { $wq = db()->prepare('SELECT declared_weight_kg FROM ds_products WHERE product_id=? ORDER BY id DESC LIMIT 1'); $wq->execute([$id]); $dw = (float)$wq->fetchColumn(); if ($dw > 0) $wt = $dw; } catch (Exception $e) {} }
    if ($wt <= 0 && $curWt > 0) $wt = $curWt;              // форма пустая — оставляем прежний вес
    /* Три пути расчёта цены:
       множитель ×N — от себестоимости, объём и вес не нужны (придут после замера);
       есть объём    — обычная точная формула по объёму и весу;
       нет ничего    — цену не трогаем, оставляем ту, что уже стоит у товара.
       Отказ в сохранении только если цены нет и посчитать её не из чего. */
    if ($x3m !== null)  $price = ds_calc_price_x3($goods, $x3m > 0 ? $x3m : null);
    elseif ($vol > 0)   $price = calc_landed_rub($goods, $vol, $wt, get_settings(), product_via_jinjia($id));
    else {
      $price = $curPrice;
      if ($price <= 0) fail('Укажите объём упаковки (м³) — без него цену не посчитать');
    }
    $gallery = $d['gallery'] ?? [];
    $cover = is_array($gallery) && count($gallery) ? $gallery[0] : ($d['img'] ?? '');
    db()->prepare('UPDATE products SET cat=?,subcat=?,name=?,price=?,old_price=?,goods_cny=?,volume_m3=?,descr=?,img=?,gallery=?,video=?,stock=?,warehouse_id=?,original=?,color=?,material=? WHERE id=?')
        ->execute([trim($d['cat'] ?? 'Прочее'), trim($d['subcat'] ?? ''), $name, $price, (int)($d['old_price'] ?? 0), $goods, $vol, trim($d['descr'] ?? ''), $cover,
                   json_encode(is_array($gallery) ? $gallery : [], JSON_UNESCAPED_UNICODE),
                   trim($d['video'] ?? ''), (int)($d['stock'] ?? 0), trim($d['warehouse_id'] ?? ''), (int)($d['original'] ?? 0), mb_substr(trim($d['color'] ?? ''),0,60), mb_substr(trim($d['material'] ?? ''),0,80), $id]);
    $disc = max(0, min(95, (int)($d['discount'] ?? 0)));
    if ($disc > 0) { db()->prepare('UPDATE products SET price=?, old_price=? WHERE id=?')->execute([(int)round($price*(100-$disc)/100), $price, $id]); }
    try { db()->prepare('UPDATE products SET discount_percent=? WHERE id=?')->execute([$disc, $id]); } catch (Exception $e) {}
    save_specs($id, $d);
    save_dims($id, $d);
    save_variants($id, $d);
    try { db()->prepare('UPDATE products SET weight_kg=?, pcs_per_box=?, ready_type=?, production_days=? WHERE id=?')->execute([($wt>0?$wt:($curWt>0?$curWt:null)), (((int)($d['pcs_per_box']??0))?:null), ((($d['ready_type']??'')==='production')?'production':'in_stock'), (((($d['ready_type']??'')==='production')&&((int)($d['production_days']??0)>0))?(int)$d['production_days']:null), $id]); } catch (Exception $e) {}
    // Синхронизируем карточку дропшиппинга: она показывает our_price_rub, и без
    // этого после правки объёма на карточке осталась бы старая цена.
    try {
      /* Объём пишем только если он есть — иначе стёрли бы замер склада. */
      if ($vol > 0) db()->prepare('UPDATE ds_products SET declared_volume_m3=?, our_price_rub=?, price_changed=0 WHERE product_id=?')
          ->execute([$vol, $price, $id]);
      else          db()->prepare('UPDATE ds_products SET our_price_rub=?, price_changed=0 WHERE product_id=?')
          ->execute([$price, $id]);
    } catch (Exception $e) {}
    jout(['ok' => true, 'price' => $price]);
  }

  // ---- ИТК: лёгкое редактирование содержимого (без цены/объёма/веса) ----
  case 'itc_update_content': {
    authUser('itc');
    $d = body();
    $id = trim($d['id'] ?? '');
    $name = trim($d['name'] ?? '');
    if (!$id) fail('Не указан товар');
    if (!$name) fail('Укажите название');
    $gallery = $d['gallery'] ?? [];
    if (!is_array($gallery)) $gallery = [];
    $cover = count($gallery) ? $gallery[0] : ($d['img'] ?? '');
    db()->prepare('UPDATE products SET name=?,cat=?,subcat=?,color=?,descr=?,img=?,gallery=?,video=? WHERE id=?')
        ->execute([$name, trim($d['cat'] ?? 'Прочее'), trim($d['subcat'] ?? ''),
                   mb_substr(trim($d['color'] ?? ''),0,60), trim($d['descr'] ?? ''), $cover,
                   json_encode($gallery, JSON_UNESCAPED_UNICODE), trim($d['video'] ?? ''), $id]);
    save_specs($id, $d);
    jout(['ok' => true]);
  }

  // ---- ИТК: удаление любого товара ----
  case 'itc_delete_product': {
    authUser('itc');
    $d = body();
    $id = $d['id'] ?? '';
    if (!$id) fail('Не указан товар');
    if ($stop = product_delete_block($id)) fail($stop);
    db()->prepare('DELETE FROM products WHERE id=?')->execute([$id]);
    jout(['ok' => true]);
  }

  // ---- склады (ИТК): полный список ----
  case 'warehouses_all': {
    authUser('itc');
    try { db()->query("ALTER TABLE warehouses ADD COLUMN geo_manual TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
    // descr, photos и ready заполняет партнёр в своём кабинете — сотруднику надо их видеть
    try { db()->query("ALTER TABLE warehouses ADD COLUMN photos TEXT NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN descr TEXT NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN ready TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
      itc_wh_geo_ensure();   // колонки координат должны существовать до запроса
    try { $wh = db()->query('SELECT id,code,name,city,country,address,region,district,active,access_code,kind,parent_id,descr,photos,ready,lat,lon,geo_manual FROM warehouses ORDER BY country,name')->fetchAll(); }
    catch (Exception $e) {
      try { $wh = db()->query('SELECT id,code,name,city,country,address,active,access_code FROM warehouses ORDER BY country,name')->fetchAll(); }
      catch (Exception $e2) { $wh = db()->query('SELECT id,code,name,city,country,address,active FROM warehouses ORDER BY country,name')->fetchAll(); }
    }
    jout(['ok' => true, 'warehouses' => $wh]);
  }

  // ---- Логистика хаб→ПВЗ: что едет к хабу и что развезти по ПВЗ (объём/вес/кол-во) ----
  case 'hub_dispatch': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    // Все точки с типами
    $pts = [];
    try { foreach (db()->query("SELECT id,code,name,city,kind,parent_id FROM warehouses")->fetchAll() as $w) $pts[$w['id']] = $w; }
    catch (Exception $e) { foreach (db()->query("SELECT id,code,name,city FROM warehouses")->fetchAll() as $w) { $w['kind']='hub'; $w['parent_id']=null; $pts[$w['id']] = $w; } }
    // Заказы (оплаченные и в работе) с их точкой назначения + объём/вес по позициям
    $rows = [];
    try {
      $q = db()->query("SELECT o.id, o.num, o.warehouse_id, o.status, o.paid,
                               UNIX_TIMESTAMP(o.created_at)*1000 ts,
                               o.wh_received_at rcv, o.wh_shipped_at shp, o.wh_picked_at pick,
                               COALESCE(SUM(p.volume_m3*i.qty),0) vol,
                               COALESCE(SUM(COALESCE(p.weight_kg,0)*i.qty),0) wt,
                               COALESCE(SUM(i.qty),0) qty
                        FROM orders o
                        JOIN order_items i ON i.order_id=o.id AND (i.oversize=0 OR i.oversize IS NULL)
                        LEFT JOIN products p ON p.id=i.product_id
                        WHERE o.paid=1
                        GROUP BY o.id ORDER BY o.created_at DESC LIMIT 2000");
      foreach ($q->fetchAll() as $r) $rows[] = $r;
    } catch (Exception $e) {}
    // Группируем по ПВЗ (точка назначения типа pvz). Для хабов — «прямой самовывоз».
    $pvz = []; $hubIncoming = ['vol'=>0,'wt'=>0,'qty'=>0,'orders'=>0];
    foreach ($rows as $r) {
      $wid = $r['warehouse_id']; $pt = $pts[$wid] ?? null;
      $isPvz = $pt && (($pt['kind'] ?? 'hub') === 'pvz');
      // статус движения
      $picked = !empty($r['pick']); $shipped = !empty($r['shp']); $received = !empty($r['rcv']);
      $stage = $picked ? 'выдан' : ($shipped ? 'на_пвз' : ($received ? 'на_хабе' : 'в_пути'));
      if ($isPvz) {
        $k = $wid;
        if (!isset($pvz[$k])) $pvz[$k] = ['id'=>$wid,'name'=>$pt['name'],'city'=>$pt['city'],'code'=>$pt['code'],
          'parent_id'=>$pt['parent_id']??null,'to_ship_vol'=>0,'to_ship_wt'=>0,'to_ship_qty'=>0,'to_ship_orders'=>0,'orders'=>[]];
        // «к отправке» = уже на хабе, но ещё не на ПВЗ и не выдан
        if ($stage === 'на_хабе') {
          $pvz[$k]['to_ship_vol'] += (float)$r['vol']; $pvz[$k]['to_ship_wt'] += (float)$r['wt'];
          $pvz[$k]['to_ship_qty'] += (int)$r['qty']; $pvz[$k]['to_ship_orders']++;
        }
        if (count($pvz[$k]['orders']) < 200)
          $pvz[$k]['orders'][] = ['num'=>$r['num'],'stage'=>$stage,'vol'=>round((float)$r['vol'],3),
            'wt'=>round((float)$r['wt'],1),'qty'=>(int)$r['qty'],'ts'=>(int)$r['ts']];
      }
      // что ещё едет к хабу (не принято на точке) — общая сводка
      if ($stage === 'в_пути') { $hubIncoming['vol']+=(float)$r['vol']; $hubIncoming['wt']+=(float)$r['wt']; $hubIncoming['qty']+=(int)$r['qty']; $hubIncoming['orders']++; }
    }
    $hubIncoming['vol']=round($hubIncoming['vol'],3); $hubIncoming['wt']=round($hubIncoming['wt'],1);
    foreach ($pvz as &$pp) { $pp['to_ship_vol']=round($pp['to_ship_vol'],3); $pp['to_ship_wt']=round($pp['to_ship_wt'],1); } unset($pp);
    $hubs = [];
    foreach ($pts as $w) { if (($w['kind'] ?? 'hub')==='hub') $hubs[] = ['id'=>$w['id'],'name'=>$w['name'],'city'=>$w['city'],'code'=>$w['code']]; }
    jout(['ok'=>true,'pvz'=>array_values($pvz),'hubs'=>$hubs,'incoming'=>$hubIncoming]);
  }

  // ---- ИТК (босс): выдать/сбросить код доступа оператора склада ----
  case 'warehouse_code': {
    $s = authUser('itc');
    require_staff($s, []);
    $d = body();
    $id = trim($d['id'] ?? '');
    if (!$id) fail('Не указан склад');
    $reset = !empty($d['reset']);
    $code = $reset ? '' : strtoupper(substr(bin2hex(random_bytes(4)), 0, 6));
    try { db()->prepare('UPDATE warehouses SET access_code=? WHERE id=?')->execute([$code, $id]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (warehouses.access_code)'); }
    jout(['ok'=>true,'code'=>$code]);
  }

  // ---- склады (ИТК): создать/изменить ----
  case 'warehouse_save': {
    authUser('itc');
    $d = body();
    $code = strtoupper(trim($d['code'] ?? ''));
    $name = trim($d['name'] ?? '');
    if (!$code) fail('Укажите код склада');
    if (!$name) fail('Укажите название склада');
    $city = trim($d['city'] ?? '');
    $country = trim($d['country'] ?? 'RU');
    $address = trim($d['address'] ?? '');
    $street = trim($d['street'] ?? '');
    try { db()->query("ALTER TABLE warehouses ADD COLUMN street VARCHAR(255) NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN region VARCHAR(120) NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN district VARCHAR(120) NULL"); } catch (Exception $e) {}
    $region = trim($d['region'] ?? '');
    $district = trim($d['district'] ?? '');
    $active = (int)($d['active'] ?? 1);
    $kind = (($d['kind'] ?? 'hub') === 'pvz') ? 'pvz' : 'hub';
    $parent = ($kind === 'pvz') ? trim($d['parent_id'] ?? '') : '';
    $id = $d['id'] ?? '';
    /* Запоминаем прежний город и адрес: если они поменялись, координаты надо
       пересчитать, иначе метка останется на старом месте. */
    $wasId = $id; $oldAddr = null; $oldLat = null; $oldLon = null;
    if ($id) {
      try { $oq = db()->prepare('SELECT city,address,lat,lon FROM warehouses WHERE id=?'); $oq->execute([$id]); $ow = $oq->fetch();
            if ($ow) { $oldAddr = trim((string)$ow['city']).'|'.trim((string)$ow['address']);
                       $oldLat = ($ow['lat'] !== null) ? (float)$ow['lat'] : null; $oldLon = ($ow['lon'] !== null) ? (float)$ow['lon'] : null; } }
      catch (Exception $e) {
        try { $oq = db()->prepare('SELECT city,address FROM warehouses WHERE id=?'); $oq->execute([$id]); $ow = $oq->fetch();
              if ($ow) $oldAddr = trim((string)$ow['city']).'|'.trim((string)$ow['address']); } catch (Exception $e2) {}
      }
    }
    if ($id) {
      try {
        db()->prepare('UPDATE warehouses SET code=?,name=?,city=?,country=?,address=?,street=?,active=?,kind=?,parent_id=? WHERE id=?')
            ->execute([$code, $name, $city, $country, $address, $street, $active, $kind, ($parent?:null), $id]);
      } catch (Exception $e) {
        db()->prepare('UPDATE warehouses SET code=?,name=?,city=?,country=?,address=?,active=? WHERE id=?')
            ->execute([$code, $name, $city, $country, $address, $active, $id]);
      }
    } else {
      $id = gen('w');
      try {
        db()->prepare('INSERT INTO warehouses (id,code,name,city,country,address,street,active,kind,parent_id) VALUES (?,?,?,?,?,?,?,?,?,?)')
            ->execute([$id, $code, $name, $city, $country, $address, $street, $active, $kind, ($parent?:null)]);
      } catch (Exception $e) {
        db()->prepare('INSERT INTO warehouses (id,code,name,city,country,address,active) VALUES (?,?,?,?,?,?,?)')
            ->execute([$id, $code, $name, $city, $country, $address, $active]);
      }
    }
    // Регион и район пишем отдельно: колонки добавляются на лету, и старая база
    // без них не должна ронять основное сохранение склада.
    try { db()->prepare('UPDATE warehouses SET region=?, district=? WHERE id=?')->execute([$region, $district, $id]); } catch (Exception $e) {}

    /* КООРДИНАТЫ РУКАМИ (обновление №212).
       Раньше метку ставил только справочник адресов по строке адреса, и на
       посёлках он мажет — точка уезжала на другой конец улицы, а поправить её
       было нечем. Теперь координаты можно прислать прямо в сохранении.
       Пустые поля НЕ трогают то, что уже стоит: стереть метку случайно нельзя.
       Помечаем такие точки geo_manual=1, чтобы ночная простановка координат по
       адресу их больше не перезаписывала. */
    if (array_key_exists('lat', $d) || array_key_exists('lon', $d)) {
      $mlat = (trim((string)($d['lat'] ?? '')) !== '') ? (float)$d['lat'] : null;
      $mlon = (trim((string)($d['lon'] ?? '')) !== '') ? (float)$d['lon'] : null;
      /* Форма правки показывает текущие координаты в полях и присылает их обратно
         при каждом сохранении. Такие НЕ считаем ручной меткой — иначе любая
         правка (даже названия) навсегда запирала бы точку от пересчёта по
         адресу. Ручная метка — только если сотрудник цифры действительно поменял. */
      $sameAsOld = ($mlat !== null && $mlon !== null && $oldLat !== null && $oldLon !== null
                    && abs($mlat - $oldLat) < 0.000002 && abs($mlon - $oldLon) < 0.000002);
      if (!$sameAsOld && $mlat !== null && $mlon !== null && abs($mlat) <= 90 && abs($mlon) <= 180 && ($mlat != 0 || $mlon != 0)) {
        try { db()->query("ALTER TABLE warehouses ADD COLUMN geo_manual TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
        try {
          db()->prepare('UPDATE warehouses SET lat=?, lon=?, geo_manual=1 WHERE id=?')->execute([$mlat, $mlon, $id]);
          itc_log_add(trim((string)($d['by'] ?? '')), 'wh_geo_manual', 'warehouse', $id, $mlat.', '.$mlon);
          $manualSet = true;
        } catch (Exception $e) {}
      }
    }
    /* Координаты по адресу — сами (обновление №264). Новая точка или точка без
       метки — считаем. Адрес сменился — старая метка неверна: снимаем признак
       «вручную» и пересчитываем. Если сотрудник в этом же сохранении поставил
       метку руками — её и оставляем. */
    /* geo_note — короткая подпись для сотрудника, что стало с меткой. */
    $geo = null; $geoNote = '';
    if (!empty($manualSet)) {
      $geoNote = 'метка поставлена вручную';
    } else {
      $newAddr = trim($city).'|'.trim($address);
      $changed = ($wasId === '' || $oldAddr === null || $oldAddr !== $newAddr);
      if ($changed && $wasId !== '') {
        try { db()->prepare('UPDATE warehouses SET geo_manual=0 WHERE id=?')->execute([$id]); } catch (Exception $e) {}
      }
      $geo = itc_wh_autogeo($id, $changed);
      if ($geo) $geoNote = ($geo['qc'] > 0) ? 'координаты по адресу — примерно, проверьте на карте' : 'координаты определены по адресу';
      else {
        $hasGeo = false;
        try { $cq = db()->prepare('SELECT lat FROM warehouses WHERE id=?'); $cq->execute([$id]); $hasGeo = ($cq->fetchColumn() !== null); } catch (Exception $e) {}
        if (!$hasGeo) $geoNote = 'адрес не распознан — точки не будет на карте, уточните адрес или впишите координаты';
      }
    }
    jout(['ok' => true, 'id' => $id, 'geo_note' => $geoNote,
          'geo' => $geo ? ['lat'=>$geo['lat'],'lon'=>$geo['lon'],'approx'=>($geo['qc'] > 0)] : null]);
  }

  // ---- склады (ИТК): удалить ----
  /* Проставить координаты точкам, у которых их ещё нет (или всем — force=1).
     Считает по адресу через DaData и сохраняет. */
  case 'wh_geocode': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','chief_accountant']);
    itc_wh_geo_ensure();
    $d = body();
    $one   = trim($d['id'] ?? '');
    $force = ((int)($d['force'] ?? 0) === 1);
    $rows = [];
    try {
      if ($one !== '') { $q = db()->prepare('SELECT id,name,city,address,lat,lon FROM warehouses WHERE id=?'); $q->execute([$one]); $rows = $q->fetchAll(); }
      else {
        $sql = 'SELECT id,name,city,address,lat,lon FROM warehouses';
        if (!$force) $sql .= ' WHERE lat IS NULL OR lon IS NULL';
        $rows = db()->query($sql)->fetchAll();
      }
    } catch (Exception $e) { fail('Не удалось прочитать точки'); }
    $done = []; $failed = [];
    /* Точки с меткой, поставленной вручную, не трогаем: сотрудник её поправил
       именно потому, что справочник промахнулся, — незачем возвращать промах. */
    $manual = [];
    try {
      db()->query("ALTER TABLE warehouses ADD COLUMN geo_manual TINYINT(1) NOT NULL DEFAULT 0");
    } catch (Exception $e) {}
    try {
      foreach (db()->query("SELECT id FROM warehouses WHERE geo_manual=1")->fetchAll() as $mr) $manual[$mr['id']] = 1;
    } catch (Exception $e) {}

    foreach ($rows as $w) {
      if (isset($manual[$w['id']])) { $failed[] = ($w['name'] ?: $w['id']).' — метка поставлена вручную, пропущено'; continue; }
      $addr = trim(trim((string)($w['city'] ?? '')).' '.trim((string)($w['address'] ?? '')));
      if ($addr === '') { $failed[] = ($w['name'] ?: $w['id']).' — нет адреса'; continue; }
      $g = itc_geocode($addr);
      if (!$g) { $failed[] = ($w['name'] ?: $w['id']).' — адрес не распознан'; continue; }
      try {
        db()->prepare('UPDATE warehouses SET lat=?, lon=? WHERE id=?')->execute([$g['lat'], $g['lon'], $w['id']]);
        $done[] = ($w['name'] ?: $w['id']).' ('.round($g['lat'],4).', '.round($g['lon'],4).')'.($g['qc'] > 0 ? ' — примерно' : '');
      } catch (Exception $e) { $failed[] = ($w['name'] ?: $w['id']).' — не сохранилось'; }
    }
    jout(['ok'=>true,'done'=>$done,'failed'=>$failed]);
  }

  /* Ближайшие пункты выдачи по адресу покупателя. Адрес НЕ сохраняем —
     он нужен только чтобы посчитать расстояние здесь и сейчас. */
  case 'wh_nearest': {
    itc_wh_geo_ensure();
    $q = trim($_GET['q'] ?? '');
    $lat = isset($_GET['lat']) ? (float)$_GET['lat'] : 0;
    $lon = isset($_GET['lon']) ? (float)$_GET['lon'] : 0;
    $found = '';
    if ((!$lat || !$lon) && $q !== '') {
      /* ЗАЩИТА ПЛАТНОГО СПРАВОЧНИКА АДРЕСОВ (обновление №212).
         Команда открыта без входа — её достаточно позвать в цикле, чтобы за
         вечер выесть суточный лимит DaData, и тогда адрес не определится уже
         у настоящих покупателей. Держим два ограничения:
         одинаковый адрес спрашиваем у справочника один раз в сутки (дальше
         берём из своей таблицы), и с одного адреса в сети — не чаще 40 новых
         адресов в час. Сами точки при этом отдаются всегда. */
      $qkey = mb_strtolower(preg_replace('/\s+/u', ' ', $q));
      $hit = null;
      try {
        db()->query("CREATE TABLE IF NOT EXISTS itc_geo_cache (
          k VARCHAR(190) NOT NULL PRIMARY KEY, lat DOUBLE NULL, lon DOUBLE NULL,
          val VARCHAR(255) NULL, ts DATETIME NOT NULL
        ) DEFAULT CHARSET=utf8mb4");
        $c = db()->prepare("SELECT lat,lon,val FROM itc_geo_cache WHERE k=? AND ts > (NOW() - INTERVAL 1 DAY)");
        $c->execute([mb_substr($qkey, 0, 190)]);
        $hit = $c->fetch();
      } catch (Exception $e) {}

      if ($hit && $hit['lat'] !== null) {
        $lat = (float)$hit['lat']; $lon = (float)$hit['lon']; $found = (string)$hit['val'];
      } else {
        // Считаем ТОЛЬКО обращения к справочнику, а не все запросы
        $ip = (string)($_SERVER['REMOTE_ADDR'] ?? '');
        $cnt = 0;
        try {
          db()->query("CREATE TABLE IF NOT EXISTS itc_geo_rate (
            ip VARCHAR(64) NOT NULL, ts DATETIME NOT NULL, KEY idx_geo_rate (ip, ts)
          ) DEFAULT CHARSET=utf8mb4");
          try { db()->query("DELETE FROM itc_geo_rate WHERE ts < (NOW() - INTERVAL 1 DAY)"); } catch (Exception $e) {}
          $r = db()->prepare("SELECT COUNT(*) FROM itc_geo_rate WHERE ip=? AND ts > (NOW() - INTERVAL 1 HOUR)");
          $r->execute([$ip]); $cnt = (int)$r->fetchColumn();
        } catch (Exception $e) {}
        if ($cnt >= 40) jout(['ok'=>false,'error'=>'Слишком много запросов адреса. Попробуйте через несколько минут.']);

        $g = itc_geocode($q);
        try { db()->prepare('INSERT INTO itc_geo_rate (ip,ts) VALUES (?,NOW())')->execute([$ip]); } catch (Exception $e) {}
        if (!$g) jout(['ok'=>false,'error'=>'Не удалось определить адрес']);
        $lat = $g['lat']; $lon = $g['lon']; $found = $g['value'];
        try {
          db()->prepare('REPLACE INTO itc_geo_cache (k,lat,lon,val,ts) VALUES (?,?,?,?,NOW())')
              ->execute([mb_substr($qkey, 0, 190), $lat, $lon, mb_substr($found, 0, 255)]);
        } catch (Exception $e) {}
      }
    }
    if (!$lat || !$lon) jout(['ok'=>false,'error'=>'Укажите адрес']);
    $rows = [];
    try { $rows = db()->query("SELECT id,code,name,city,address,kind,lat,lon FROM warehouses
                               WHERE (active IS NULL OR active<>0) AND country='RU'")->fetchAll(); }
    catch (Exception $e) { jout(['ok'=>false,'error'=>'Не удалось прочитать точки']); }
    $out = [];
    foreach ($rows as $w) {
      if ($w['lat'] === null || $w['lon'] === null) continue;   // без координат сравнивать не с чем
      $w['km'] = round(itc_km($lat, $lon, (float)$w['lat'], (float)$w['lon']), 1);
      $out[] = $w;
    }
    usort($out, function ($a, $b) { return $a['km'] <=> $b['km']; });
    jout(['ok'=>true,'lat'=>$lat,'lon'=>$lon,'address'=>$found,'points'=>array_slice($out, 0, 20),
          'total'=>count($rows),'with_geo'=>count($out)]);
  }

  /* СОХРАНЕНИЕ PDF КОММЕРЧЕСКОГО ПРЕДЛОЖЕНИЯ.
     Внутри приложения файл, собранный в самом телефоне, скачать нельзя —
     обработчик загрузок понимает только обычные адреса сайта. Поэтому кладём
     готовый PDF к нам на сервер и возвращаем ссылку: по ней приложение
     скачивает файл штатно, как любой документ из интернета.
     Файлы живут неделю и подчищаются сами. */
  case 'kp_pdf_put': {
    $d = body();
    $b64 = (string)($d['pdf'] ?? '');
    $pos = strpos($b64, 'base64,');
    if ($pos !== false) $b64 = substr($b64, $pos + 7);
    $bin = base64_decode($b64, true);
    if ($bin === false || strlen($bin) < 500) fail('Пустой файл');
    if (strlen($bin) > 8 * 1024 * 1024) fail('Файл слишком большой');
    if (substr($bin, 0, 4) !== '%PDF') fail('Это не PDF');

    $dir = __DIR__ . '/../kp';
    if (!is_dir($dir)) @mkdir($dir, 0755, true);
    if (!is_dir($dir)) fail('Нет папки для файлов');

    /* Старые файлы убираем, чтобы папка не росла бесконечно. */
    $now = time();
    foreach ((array)glob($dir . '/*.pdf') as $old) {
      if (@filemtime($old) < $now - 7 * 86400) @unlink($old);
    }

    $no   = preg_replace('/[^0-9A-Za-z\-]/', '', (string)($d['no'] ?? 'kp'));
    $name = 'KP-' . ($no !== '' ? $no : 'file') . '-' . substr(bin2hex(random_bytes(6)), 0, 8) . '.pdf';
    if (@file_put_contents($dir . '/' . $name, $bin) === false) fail('Не удалось сохранить файл');

    $base = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off' ? 'https' : 'http')
          . '://' . ($_SERVER['HTTP_HOST'] ?? 'itcpartner.store');
    jout(['ok' => true, 'url' => $base . '/kp/' . $name, 'name' => $name, 'size' => strlen($bin)]);
  }

  case 'warehouse_del': {
    authUser('itc');
    $d = body();
    $id = $d['id'] ?? '';
    if (!$id) jout(['ok' => true]);
    /* Раньше удалялся ТОЛЬКО сам склад. Партнёр оставался в списке, да ещё со
       ссылкой на несуществующую точку — списки захламлялись «мёртвыми» именами.
       Теперь наводим порядок за собой: отвязываем партнёров, а тех, кто был
       заведён под эту точку и не успел ничего заработать, убираем совсем.
       Партнёра с историей выплат НЕ трогаем — его удаление разорвало бы
       бухгалтерию; он просто остаётся без склада, и его видно в списке. */
    $freed = []; $removed = []; $kept = [];
    try {
      $pq = db()->prepare('SELECT id,name,phone FROM partners WHERE warehouse_id=?');
      $pq->execute([$id]);
      foreach ($pq->fetchAll() as $pr) {
        $freed[] = $pr['id'];
        $hasMoney = false;
        try {
          $c = db()->prepare('SELECT COUNT(*) FROM partner_payouts WHERE partner_id=?');
          $c->execute([$pr['id']]);
          $hasMoney = ((int)$c->fetchColumn() > 0);
        } catch (Exception $e) { $hasMoney = true; }   // не смогли проверить — не удаляем
        if ($hasMoney) {
          try { db()->prepare('UPDATE partners SET warehouse_id=NULL WHERE id=?')->execute([$pr['id']]); } catch (Exception $e) {}
          $kept[] = trim(($pr['name'] ?? '').' '.($pr['phone'] ?? ''));
        } else {
          try { db()->prepare('DELETE FROM partners WHERE id=?')->execute([$pr['id']]); $removed[] = trim(($pr['name'] ?? '').' '.($pr['phone'] ?? '')); }
          catch (Exception $e) { try { db()->prepare('UPDATE partners SET warehouse_id=NULL WHERE id=?')->execute([$pr['id']]); } catch (Exception $e2) {} }
        }
      }
    } catch (Exception $e) {}
    /* Подчинённые пункты выдачи остались бы висеть на несуществующем хабе —
       отвязываем, сами точки не трогаем. */
    $orphans = 0;
    try {
      $oq = db()->prepare('SELECT COUNT(*) FROM warehouses WHERE parent_id=?');
      $oq->execute([$id]); $orphans = (int)$oq->fetchColumn();
      if ($orphans > 0) db()->prepare('UPDATE warehouses SET parent_id=NULL WHERE parent_id=?')->execute([$id]);
    } catch (Exception $e) {}
    /* Заявку, из которой выросла точка, тоже отвязываем — иначе одобренная
       заявка ссылается в пустоту. */
    try { db()->prepare('UPDATE pvz_applications SET warehouse_id=NULL WHERE warehouse_id=?')->execute([$id]); } catch (Exception $e) {}
    db()->prepare('DELETE FROM warehouses WHERE id=?')->execute([$id]);
    jout(['ok' => true, 'partners_removed' => $removed, 'partners_kept' => $kept, 'orphan_points' => $orphans]);
  }

  // ---- ИТК: сменить/закрепить партнёра на складе (один склад — один партнёр) ----
  case 'wh_set_partner': {
    $s = authUser('itc');
    require_staff($s, ['manager']);
    $d = body();
    $wh = trim($d['warehouse_id'] ?? '');
    $pid = trim($d['partner_id'] ?? '');
    if (!$wh) fail('Не указан склад');
    // снять этот склад с других партнёров
    db()->prepare("UPDATE partners SET warehouse_id='' WHERE warehouse_id=? AND id<>?")->execute([$wh, $pid]);
    // закрепить за выбранным
    if ($pid !== '') db()->prepare('UPDATE partners SET warehouse_id=? WHERE id=?')->execute([$wh, $pid]);
    try { itc_log_add($d['by'] ?? '', 'wh_set_partner', 'warehouse', $wh, $pid); } catch (Exception $e) {}
    jout(['ok'=>true]);
  }

  // ---- настройки расчёта (ИТК): получить ----
  case 'get_settings': {
    authUser('itc');
    jout(['ok' => true, 'calc' => get_settings()]);
  }

  // ---- настройки расчёта (ИТК): сохранить ----
  case 'update_settings': {
    $s = authUser('itc');
    require_staff($s, []);
    if (($s['staff_role'] ?? '') === 'bossacct') fail('Главный бухгалтер не может менять формулу расчёта', 403);
    $d = body();
    $vals = $d['calc'] ?? [];
    $allowed = array_keys(calc_defaults());
    $st = db()->prepare('INSERT INTO settings (k,v) VALUES (?,?) ON DUPLICATE KEY UPDATE v=VALUES(v)');
    foreach ($allowed as $k) {
      if (isset($vals[$k]) && is_numeric($vals[$k])) $st->execute([$k, (string)$vals[$k]]);
    }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'settings', 'calc', '', 'Изменены ставки расчёта');
    jout(['ok' => true, 'calc' => get_settings()]);
  }

  // ---- пересчитать цены всех товаров по текущим ставкам (ИТК) ----
  case 'recalc_all': {
    $s = authUser('itc');
    require_staff($s, []);
    $st = get_settings();
    $rows = db()->query('SELECT id, supplier_id, goods_cny, volume_m3, COALESCE(weight_kg,0) weight_kg FROM products WHERE goods_cny > 0 AND volume_m3 > 0')->fetchAll();
    $updP = db()->prepare('UPDATE products SET price = ? WHERE id = ?');
    $updPO = db()->prepare('UPDATE products SET price = ?, old_price = ? WHERE id = ?');
    $discMap = [];
    try { foreach (db()->query('SELECT id, discount_percent FROM products WHERE discount_percent>0')->fetchAll() as $dr) $discMap[$dr['id']] = (int)$dr['discount_percent']; } catch (Exception $e) {}
    $n = 0;
    foreach ($rows as $r) {
      $base = calc_landed_rub((int)$r['goods_cny'], (float)$r['volume_m3'], (float)$r['weight_kg'], $st, pays_via_jinjia($r['supplier_id']));
      $dp = $discMap[$r['id']] ?? 0;
      if ($dp > 0) $updPO->execute([(int)round($base*(100-$dp)/100), $base, $r['id']]);
      else $updP->execute([$base, $r['id']]);
      $n++;
    }
    jout(['ok' => true, 'count' => $n]);
  }

  // ---- товары поставщика: удалить ----
  case 'delete_product': {
    $s = authUser('supplier');
    $d = body();
    if ($stop = product_delete_block($d['id'] ?? '')) fail($stop);
    db()->prepare('DELETE FROM products WHERE id = ? AND supplier_id = ?')
        ->execute([$d['id'] ?? '', $s['supplier_id']]);
    jout(['ok' => true]);
  }

  // ---- оформление заказа (покупатель) ----
  case 'place_order': {
    $s = authUser();
    $role = $s['role'] ?? ''; $sr = $s['staff_role'] ?? '';
    $byStaff = ($role === 'itc' && ($sr === 'boss' || $sr === '' || $sr === 'manager' || $sr === 'supervisor'));
    if ($role !== 'buyer' && !$byStaff) fail('Недостаточно прав', 403);
    $d = body();
    $items = $d['items'] ?? [];
    $addr = $d['addr'] ?? [];
    if ($byStaff) { $addr['note'] = trim((!empty($addr['note']) ? $addr['note'].' · ' : '').'Оформлен сотрудником: '.($s['name'] ?? ($s['phone'] ?? 'ИТК'))); }
    if (!$items) fail('Корзина пуста');
    if (empty($d['warehouse_id'])) fail('Выберите склад получения');
    if (!$byStaff && !empty($d['consent'])) { try { db()->prepare('UPDATE customers SET consent_at=NOW() WHERE phone=? AND consent_at IS NULL')->execute([$s['phone']]); } catch (Exception $e) {} }

    /* ЗАЩИТА ОТ ПОВТОРА (24.08.2026).
       У Батечко за 20 секунд создалось 17 одинаковых заказов по 77 864 ₽ —
       по три в секунду. Человек столько нажать не может: это либо повторные
       отправки при плохой связи, либо многократное срабатывание кнопки.
       Если бы такой заказ оплачивали, могло уйти несколько списаний.
       Смотрим: не было ли у этого же человека НЕОПЛАЧЕННОГО заказа на ту же
       сумму за последние две минуты. Если был — возвращаем его же, а не
       плодим новый. Оплаченные не трогаем: повторная покупка законна. */
    try {
      $sum0 = 0.0;
      foreach ($items as $it0) $sum0 += ((float)($it0['price'] ?? 0)) * ((int)($it0['qty'] ?? 1));
      if ($sum0 > 0) {
        $q0 = db()->prepare("SELECT id,num FROM orders
                             WHERE ".ph_sql_eq('phone')." AND paid=0
                               AND ABS(total - ?) < 1
                               AND created_at > (NOW() - INTERVAL 2 MINUTE)
                             ORDER BY created_at DESC LIMIT 1");
        $q0->execute([ph_tail10($s['phone']), $sum0]);
        $dup = $q0->fetch();
        if ($dup) {
          itc_log_add(($s['name'] ?? ''), 'place_order_dup', 'order', $dup['id'], 'повтор за 2 мин, отдали прежний '.$dup['num']);
          jout(['ok'=>true, 'id'=>$dup['id'], 'num'=>$dup['num'], 'repeat'=>true]);
        }
      }
    } catch (Exception $e) {}

    $pdo = db();
    $pdo->beginTransaction();
    $oid = gen('o');
    $cnt = (int)$pdo->query('SELECT COUNT(*) c FROM orders')->fetch()['c'];
    $num = 'М-' . (1001 + $cnt);
    $total = 0;
    $rows = [];
    // активные позиции трейдеров на складе получения: product_id => [markup_pct, trader_id]
    $trPos = []; $trFee = 0.0; $trId = '';
    try {
      $wq = $pdo->prepare("SELECT p.product_id, p.markup_pct, p.trader_id FROM trader_positions p JOIN warehouses w ON w.id=p.warehouse_id WHERE p.status='active' AND LOWER(TRIM(COALESCE(NULLIF(w.region,''),w.city)))=(SELECT LOWER(TRIM(COALESCE(NULLIF(region,''),city))) FROM warehouses WHERE id=?)");
      $wq->execute([trim($d['warehouse_id'] ?? '')]);
      foreach ($wq->fetchAll() as $tp) { if($tp['product_id']) $trPos[$tp['product_id']] = $tp; }
    } catch (Exception $e) {
      try {
        $wq = $pdo->prepare("SELECT p.product_id, p.markup_pct, p.trader_id FROM trader_positions p JOIN warehouses w ON w.id=p.warehouse_id WHERE p.status='active' AND LOWER(TRIM(w.city))=(SELECT LOWER(TRIM(city)) FROM warehouses WHERE id=?)");
        $wq->execute([trim($d['warehouse_id'] ?? '')]);
        foreach ($wq->fetchAll() as $tp) { if($tp['product_id']) $trPos[$tp['product_id']] = $tp; }
      } catch (Exception $e2) {}
    }
    foreach ($items as $it) {
      $st = $pdo->prepare('SELECT id,name,price,supplier_id,cat, EXISTS(SELECT 1 FROM ds_products dz WHERE dz.product_id=products.id) AS ds FROM products WHERE id = ?');
      $st->execute([$it['id'] ?? '']);
      $p = $st->fetch();
      if (!$p) continue;
      $qty = max(1, (int)($it['qty'] ?? 1));
      $colorTxt = trim((string)($it['color'] ?? ''));
      $nm = $p['name'] . ($colorTxt !== '' ? ' · Расцветка: ' . $colorTxt : '');
      $unit = (float)$p['price'];
      if ($colorTxt !== '') {
        try {
          $vst = $pdo->prepare('SELECT volume_m3, COALESCE(weight_kg,0) weight_kg, variants FROM products WHERE id = ?');
          $vst->execute([$p['id']]);
          $vrow = $vst->fetch();
          if ($vrow && !empty($vrow['variants'])) {
            $pv = json_decode($vrow['variants'], true);
            if (is_array($pv) && !empty($pv['items'])) {
              foreach ($pv['items'] as $vi) {
                if (trim((string)($vi['name'] ?? '')) === $colorTxt) {
                  $vg = (float)($vi['goodsCny'] ?? 0);
                  if ($vg > 0 && (float)$vrow['volume_m3'] > 0) { $unit = calc_landed_rub($vg, (float)$vrow['volume_m3'], (float)$vrow['weight_kg'], get_settings()); $vd=0; try { $dq=$pdo->prepare('SELECT discount_percent FROM products WHERE id=?'); $dq->execute([$p['id']]); $vd=(int)$dq->fetchColumn(); } catch (Exception $e) {} if ($vd>0) $unit = round($unit*(100-$vd)/100); }
                  break;
                }
              }
            }
          }
        } catch (Exception $e) {}
      }
      // цена трейдера: к минимальной цене прибавляется его надбавка, вознаграждение — за вычетом НДС
      if (isset($trPos[$p['id']])) {
        $mk = (float)($trPos[$p['id']]['markup_pct'] ?? 0);
        if ($mk > 0) {
          $delta = $unit * $mk / 100;
          $unit  = $unit + $delta;
          $trFee += ($delta / 1.22) * $qty;
          $trId   = (string)$trPos[$p['id']]['trader_id'];
        }
      }
      $qty = max($qty, itc_min_qty($unit));   // №878: дешёвые товары — не меньше минимального заказа
      $total += $unit * $qty;
      $rows[] = [$p['id'], $p['supplier_id'], $nm, $qty, $unit, $p['cat'] ?? '', (int)($p['ds'] ?? 0)];
    }
    if (!$rows) { $pdo->rollBack(); fail('Товары не найдены'); }
    /* №879: минимальная сумма заказа (по товарам, без доставки) — настройка min_order, по умолчанию 200 ₽ */
    $minOrder = 200; try { $stm = get_settings(); if (isset($stm['min_order']) && is_numeric($stm['min_order'])) $minOrder = (float)$stm['min_order']; } catch (Exception $e) {}
    if ($minOrder > 0 && $total < $minOrder) { $pdo->rollBack(); fail('Минимальная сумма заказа — ' . (int)$minOrder . ' ₽. Добавьте товаров ещё на ' . (int)ceil($minOrder - $total) . ' ₽'); }

    /* ===== ЗАЧЁТ КРАСНЫХ КОНВЕРТОВ (обновление №225) =====
       Потолок — 20% от стоимости товаров заказа. Конверт НЕ ДРОБИТСЯ: берём
       только те, что укладываются в потолок целиком, самые крупные вперёд.
       Списываем ЗДЕСЬ ЖЕ, внутри той же транзакции, что и заказ: иначе можно
       получить оплаченный заказ со сгоревшим конвертом или наоборот. */
    $envUsed = 0; $envIds = [];
    try {
      $want = $d['env_ids'] ?? [];
      if (is_array($want) && $want) {
        itc_env_burn($s['phone']);
        $cap = (int)floor($total * 0.20);
        $ph  = implode(',', array_fill(0, count($want), '?'));
        $q = $pdo->prepare("SELECT id,amount FROM itc_envelope
                            WHERE phone=? AND status='opened' AND (spend_by IS NULL OR spend_by >= NOW())
                            AND id IN ($ph) ORDER BY amount DESC");
        $q->execute(array_merge([$s['phone']], array_map('intval', $want)));
        foreach ($q->fetchAll() as $e) {
          $a = (int)round((float)$e['amount']);
          if ($envUsed + $a <= $cap) { $envUsed += $a; $envIds[] = (int)$e['id']; }
        }
        if ($envIds) {
          $up = $pdo->prepare("UPDATE itc_envelope SET status='spent', order_id=? WHERE id=? AND status='opened'");
          foreach ($envIds as $eid) $up->execute([$oid, $eid]);
          $total = max(0, $total - $envUsed);
        }
      }
    } catch (Exception $e) { /* конверты не должны ломать оформление заказа */ }

    /* ===== ОПЛАТА БОНУСАМИ =====
       Потолка нет: бонусами можно закрыть весь остаток. Списываем ПОСЛЕ
       конвертов — от того, что осталось. Проверяем остаток на сервере: на
       клиенте его можно подрисовать. */
    $bonusUsed = 0;
    try {
      $wantB = (int)($d['bonus_use'] ?? 0);
      if ($wantB > 0) {
        itc_ref_ensure();
        $bq = $pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM itc_bonus WHERE phone=? AND status='available'");
        $bq->execute([$s['phone']]);
        $have = (int)round((float)$bq->fetchColumn());
        $bonusUsed = max(0, min($wantB, $have, (int)$total));
        if ($bonusUsed > 0) {
          $pdo->prepare("INSERT INTO itc_bonus (phone,kind,amount,status,order_id,created_at)
                         VALUES (?,'spend',?, 'available', ?, NOW())")
              ->execute([$s['phone'], -$bonusUsed, $oid]);
          $total = max(0, $total - $bonusUsed);
        }
      }
    } catch (Exception $e) { /* бонусы не должны ломать оформление заказа */ }

    /* №878: доставка по Китаю от продавцов 1688 — одной строкой на продавца, бонусами не закрывается */
    $cnShip = 0;
    try { $cs = itc_cn_ship(array_map(function($r){ return $r[0]; }, array_filter($rows, function($r){ return !empty($r[6]); }))); $cnShip = (int)$cs['rub']; } catch (Exception $e) { $cnShip = 0; }
    $total += $cnShip;
    $payKind = (($d['pay_kind'] ?? '') === 'invoice') ? 'invoice' : '';
    $lg = $d['legal'] ?? [];
    $pdo->prepare('INSERT INTO orders (id,num,phone,total,addr_name,addr_phone,addr_city,addr_street,addr_zip,addr_note,email,warehouse_id,pay_kind,inv_company,inv_inn,inv_kpp,inv_addr,inv_at)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
        ->execute([$oid, $num, $s['phone'], $total,
                   $addr['name'], $s['phone'], $addr['city'], $addr['street'],
                   $addr['zip'] ?? '', $addr['note'] ?? '', $addr['email'] ?? '', trim($d['warehouse_id'] ?? ''),
                   $payKind,
                   mb_substr(trim($lg['company'] ?? ''),0,200), mb_substr(trim($lg['inn'] ?? ''),0,20),
                   mb_substr(trim($lg['kpp'] ?? ''),0,20), mb_substr(trim($lg['addr'] ?? ''),0,300),
                   $payKind==='invoice' ? date('Y-m-d H:i:s') : null]);
    // обновим профиль покупателя
    $pdo->prepare('UPDATE customers SET name=?,city=?,street=?,zip=? WHERE phone=?')
        ->execute([$addr['name'], $addr['city'], $addr['street'], $addr['zip'] ?? '', $s['phone']]);
    try {
      $ins = $pdo->prepare('INSERT INTO order_items (order_id,product_id,supplier_id,name,qty,price,cat,ds) VALUES (?,?,?,?,?,?,?,?)');
      foreach ($rows as $r) $ins->execute([$oid, $r[0], $r[1], $r[2], $r[3], $r[4], $r[5], $r[6]]);
    } catch (Exception $e) {
      try {
        $ins = $pdo->prepare('INSERT INTO order_items (order_id,product_id,supplier_id,name,qty,price,cat) VALUES (?,?,?,?,?,?,?)');
        foreach ($rows as $r) $ins->execute([$oid, $r[0], $r[1], $r[2], $r[3], $r[4], $r[5]]);
      } catch (Exception $e2) {
        $ins = $pdo->prepare('INSERT INTO order_items (order_id,product_id,supplier_id,name,qty,price) VALUES (?,?,?,?,?,?)');
        foreach ($rows as $r) $ins->execute([$oid, $r[0], $r[1], $r[2], $r[3], $r[4]]);
      }
    }
    // товары по прямому контракту с фабрикой — отметка для закупки и бухгалтерии
    try {
      $jf = [];
      foreach ($rows as $rw) {
        $q2 = $pdo->prepare("SELECT p.jfactory_id, f.name FROM products p JOIN jfactories f ON f.id=p.jfactory_id WHERE p.id=? AND p.jfactory_id IS NOT NULL AND p.jfactory_id<>''");
        $q2->execute([$rw[0]]);
        $a2 = $q2->fetch();
        if ($a2 && $a2['jfactory_id']) $jf[$a2['jfactory_id']] = $a2['name'];
      }
      if (count($jf)) {
        $note = 'Прямой контракт: ' . implode('; ', array_values($jf));
        try { $pdo->query("ALTER TABLE orders ADD COLUMN buy_note VARCHAR(400) NULL"); } catch (Exception $e2) {}
        $pdo->prepare('UPDATE orders SET buy_note=? WHERE id=?')->execute([mb_substr($note, 0, 400), $oid]);
      }
    } catch (Exception $e) {}
    if ($cnShip > 0) {
      try { $pdo->query("ALTER TABLE orders ADD COLUMN cn_ship INT NOT NULL DEFAULT 0"); } catch (Exception $e2) {}
      try { $pdo->prepare('UPDATE orders SET cn_ship=? WHERE id=?')->execute([$cnShip, $oid]); } catch (Exception $e2) {}
    }
    if ($trId !== '' && $trFee > 0) {
      try { $pdo->prepare('UPDATE orders SET trader_id=?, trader_fee=? WHERE id=?')->execute([$trId, round($trFee, 2), $oid]); } catch (Exception $e) {}
    }
    $pdo->commit();

    /* ЧИСТИМ КОРЗИНУ ЗДЕСЬ, А НЕ НА САЙТЕ (24.08.2026).
       Жалоба: «оплатил заказ, товар остался в корзине». Причина — гонка:
       сайт убирал товары и отправлял корзину на сервер, но тут же
       перебрасывал человека на оплату. Браузер при переходе обрывает
       незавершённые запросы, сохранение не доезжало, и после возврата
       корзина подгружалась с сервера в прежнем виде — с товарами.
       Теперь заказанное убирается на сервере, где обрыву взяться неоткуда.
       Сравниваем по паре «товар + цвет»: один товар может лежать в корзине
       в двух цветах, и заказать могли только один из них. */
    if (!$byStaff) {
      try {
        $q = db()->prepare('SELECT items FROM carts WHERE phone=?');
        $q->execute([$s['phone']]);
        $j = $q->fetchColumn();
        if ($j) {
          $cart = json_decode($j, true);
          if (is_array($cart)) {
            $done = [];
            foreach ($items as $it) {
              $done[((string)($it['id'] ?? '')) . '|' . ((string)($it['color'] ?? ''))] = true;
            }
            $left = [];
            foreach ($cart as $c) {
              $key = ((string)($c['id'] ?? '')) . '|' . ((string)($c['color'] ?? ''));
              if (!isset($done[$key])) $left[] = $c;
            }
            if (count($left) !== count($cart)) {
              db()->prepare('INSERT INTO carts (phone,items) VALUES (?,?) ON DUPLICATE KEY UPDATE items=VALUES(items)')
                  ->execute([$s['phone'], json_encode($left, JSON_UNESCAPED_UNICODE)]);
            }
          }
        }
      } catch (Exception $e) {}
    }

    jout(['ok' => true, 'num' => $num, 'order_id' => $oid, 'pay_kind' => $payKind, 'env_used' => $envUsed, 'bonus_used' => $bonusUsed, 'cn_ship' => $cnShip, 'total' => (int)round($total)]);
  }

  // ---- СЧЁТ ЮРЛИЦ: данные для печати (покупатель) ----
  case 'invoice_data': {
    $sess = authUser('buyer');
    $oid = body()['order_id'] ?? '';
    $st = db()->prepare('SELECT id,num,total,paid,inv_company,inv_inn,inv_kpp,inv_addr,UNIX_TIMESTAMP(COALESCE(inv_at,created_at))*1000 ts FROM orders WHERE id=? AND phone=?');
    $st->execute([$oid, $sess['phone']]);
    $o = $st->fetch();
    if (!$o) fail('Заказ не найден');
    $iq = db()->prepare('SELECT name,qty,price FROM order_items WHERE order_id=?'); $iq->execute([$oid]);
    jout(['ok'=>true,'num'=>$o['num'],'total'=>(float)$o['total'],'paid'=>(int)$o['paid'],'ts'=>(int)$o['ts'],
          'buyer'=>['company'=>$o['inv_company'],'inn'=>$o['inv_inn'],'kpp'=>$o['inv_kpp'],'addr'=>$o['inv_addr']],
          'items'=>$iq->fetchAll(),'seller'=>get_req()]);
  }
  // ---- РЕКВИЗИТЫ ИТК: получить (босс) ----
  case 'requisites_get': {
    $s = authUser('itc'); require_staff($s, []);
    jout(['ok'=>true,'req'=>get_req()]);
  }
  // ---- РЕКВИЗИТЫ ИТК: сохранить (босс) ----
  case 'requisites_save': {
    $s = authUser('itc'); require_staff($s, []);
    $d = body(); $r = $d['req'] ?? [];
    $keys = ['req_company','req_inn','req_kpp','req_addr','req_bank','req_bik','req_account','req_corr','req_director','req_vat'];
    $st = db()->prepare('INSERT INTO settings (k,v) VALUES (?,?) ON DUPLICATE KEY UPDATE v=VALUES(v)');
    foreach ($keys as $k) { if (isset($r[$k])) $st->execute([$k, mb_substr((string)$r[$k],0,255)]); }
    jout(['ok'=>true,'req'=>get_req()]);
  }
  // ---- СЧЕТА ЮРЛИЦ: список (бухгалтер/босс) ----
  case 'invoices_list': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $rows = [];
    try {
      foreach (db()->query("SELECT id,num,total,paid,phone,inv_company,inv_inn,inv_kpp,UNIX_TIMESTAMP(inv_at)*1000 ts FROM orders WHERE pay_kind='invoice' ORDER BY (paid=0) DESC, inv_at DESC LIMIT 300")->fetchAll() as $r)
        $rows[] = ['id'=>$r['id'],'num'=>$r['num'],'total'=>(float)$r['total'],'paid'=>(int)$r['paid'],'phone'=>$r['phone'],'company'=>$r['inv_company'],'inn'=>$r['inv_inn'],'kpp'=>$r['inv_kpp'],'ts'=>(int)$r['ts']];
    } catch (Exception $e) {}
    jout(['ok'=>true,'invoices'=>$rows]);
  }
  // ---- СЧЁТ ЮРЛИЦ: подтвердить оплату (бухгалтер/босс) ----
  case 'invoice_confirm': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $d = body(); $oid = trim($d['order_id'] ?? ''); $paid = (int)($d['paid'] ?? 1) ? 1 : 0;
    try { db()->prepare("UPDATE orders SET paid=?, status=IF(?=1 AND status='created','confirmed',status) WHERE id=? AND pay_kind='invoice'")->execute([$paid,$paid,$oid]); } catch (Exception $e) { fail('Ошибка'); }
    if($paid) ds_create_procurement($oid);
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), $paid?'invoice_paid':'invoice_unpaid', 'order', $oid, $paid?'Счёт оплачен':'Отметка снята');
    jout(['ok'=>true]);
  }

  // ---- создать платёж в ЮKassa, вернуть ссылку на оплату ----
  case 'create_payment': {
    global $SITE_URL, $YK_SEND_RECEIPT;
    $sess = authUser();
    { $_r = $sess['role'] ?? ''; $_sr = $sess['staff_role'] ?? ''; if ($_r !== 'buyer' && !($_r === 'itc' && ($_sr==='boss'||$_sr===''||$_sr==='manager'||$_sr==='supervisor'))) fail('Недостаточно прав', 403); }
    $d = body();
    $st = db()->prepare('SELECT * FROM orders WHERE id = ? AND '.ph_sql_eq('phone'));
    $st->execute([$d['order_id'] ?? '', ph_tail10($sess['phone'])]);
    $o = $st->fetch();
    if (!$o) fail('Заказ не найден');
    if ((int)$o['paid'] === 1) fail('Заказ уже оплачен');

    $payload = [
      'amount' => ['value' => number_format($o['total'], 2, '.', ''), 'currency' => 'RUB'],
      'capture' => true,
      'confirmation' => ['type' => 'redirect', 'return_url' => $SITE_URL . '/?order=' . rawurlencode($o['num'])],
      'description' => 'Заказ ' . $o['num'] . ' — ИТК Мебель',
      'metadata' => ['order_id' => $o['id'], 'num' => $o['num']],
    ];
    // способ оплаты: 'sbp' — сразу Система быстрых платежей; иначе общая страница ЮKassa
    if (($d['method'] ?? '') === 'sbp') $payload['payment_method_data'] = ['type' => 'sbp'];
    // Чек (54-ФЗ) — включается флагом, когда настроена онлайн-касса
    if ($YK_SEND_RECEIPT && !empty($o['email'])) {
      $iq = db()->prepare('SELECT name,qty,price,0 AS oversize FROM order_items WHERE order_id = ?');
      $iq->execute([$o['id']]);
      $rcItems = [];
      foreach ($iq->fetchAll() as $it) {
        $rcItems[] = ['description' => mb_substr($it['name'],0,128), 'quantity' => (string)$it['qty'],
                      'amount' => ['value' => number_format($it['price'],2,'.',''), 'currency' => 'RUB'],
                      'vat_code' => 1, 'payment_subject' => 'commodity', 'payment_mode' => 'full_payment'];
      }
      $payload['receipt'] = ['customer' => ['email' => $o['email']], 'items' => $rcItems];
    }

    $p = yk_request('POST', '/payments', $payload);
    if (!$p || empty($p['confirmation']['confirmation_url'])) {
      fail('ЮKassa: не удалось создать платёж' . (isset($p['description']) ? ' — '.$p['description'] : ''), 502);
    }
    db()->prepare('UPDATE orders SET payment_id = ? WHERE id = ?')->execute([$p['id'], $o['id']]);
    jout(['ok' => true, 'confirmation_url' => $p['confirmation']['confirmation_url']]);
  }

  // ---- заказы покупателя ----
  // ---- отзывы товара: список + может ли текущий покупатель оставить ----
  case 'product_reviews': {
    $pid = trim($_GET['product_id'] ?? '');
    if (!$pid) fail('Товар не указан');
    try {
      $st = db()->prepare("SELECT name,rating,text,photos,video,answer,phone,pinned,UNIX_TIMESTAMP(created_at)*1000 AS ts FROM reviews WHERE product_id=? AND (mod_status='approved' OR mod_status='' OR mod_status IS NULL) ORDER BY pinned DESC, created_at DESC");
      $st->execute([$pid]);
    } catch (Exception $e) {
      $st = db()->prepare('SELECT name,rating,text,photos,video,answer,phone,pinned,UNIX_TIMESTAMP(created_at)*1000 AS ts FROM reviews WHERE product_id=? ORDER BY pinned DESC, created_at DESC');
      $st->execute([$pid]);
    }
    $list = []; $sum = 0;
    foreach ($st->fetchAll() as $r) {
      $sum += (int)$r['rating'];
      $list[] = ['name'=>$r['name'],'rating'=>(int)$r['rating'],'text'=>$r['text'],
                 'photos'=>json_decode($r['photos'] ?: '[]', true) ?: [], 'video'=>$r['video'] ?? '', 'answer'=>$r['answer'] ?? '', 'verified'=>(strpos((string)($r['phone'] ?? ''),'itc-')!==0), 'pinned'=>(int)($r['pinned'] ?? 0), 'ts'=>$r['ts']];
    }
    $count = count($list);
    $avg = $count ? round($sum/$count, 1) : 0;
    $can = false; $reviewed = false;
    $t = $_GET['t'] ?? '';
    if ($t) {
      $ss = db()->prepare('SELECT phone,role FROM sessions WHERE token=?'); $ss->execute([$t]); $sr = $ss->fetch();
      if ($sr && $sr['role'] === 'buyer') {
        $ph = $sr['phone'];
        $rv = db()->prepare('SELECT id FROM reviews WHERE product_id=? AND phone=?'); $rv->execute([$pid,$ph]);
        $reviewed = (bool)$rv->fetch();
        if (!$reviewed) {
          $ck = db()->prepare('SELECT 1 FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.phone=? AND o.paid=1 AND i.product_id=? LIMIT 1');
          $ck->execute([$ph,$pid]);
          $can = (bool)$ck->fetch();
        }
      }
    }
    jout(['ok'=>true,'reviews'=>$list,'avg'=>$avg,'count'=>$count,'can_review'=>$can,'reviewed'=>$reviewed]);
  }

  // ---- оставить отзыв (только покупатель, оплативший товар; один на товар) ----
  case 'add_review': {
    $s = authUser('buyer');
    $d = body();
    $pid = trim($d['product_id'] ?? '');
    $rating = (int)($d['rating'] ?? 0);
    $text = trim($d['text'] ?? '');
    $photos = $d['photos'] ?? [];
    $video = trim($d['video'] ?? '');
    if (!$pid) fail('Товар не указан');
    if ($rating < 1 || $rating > 5) fail('Поставьте оценку от 1 до 5');
    $ck = db()->prepare('SELECT 1 FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.phone=? AND o.paid=1 AND i.product_id=? LIMIT 1');
    $ck->execute([$s['phone'], $pid]);
    if (!$ck->fetch()) fail('Отзыв можно оставить только после покупки этого товара');
    $ex = db()->prepare('SELECT id FROM reviews WHERE product_id=? AND phone=?');
    $ex->execute([$pid, $s['phone']]);
    if ($ex->fetch()) fail('Вы уже оставили отзыв на этот товар');
    $nm = ''; $nq = db()->prepare('SELECT name FROM customers WHERE phone=?'); $nq->execute([$s['phone']]); $cr = $nq->fetch();
    if ($cr) $nm = $cr['name'];
    if (!is_array($photos)) $photos = [];
    $photos = array_slice($photos, 0, 3);
    $id = gen('rv');
    try {
      db()->prepare('INSERT INTO reviews (id,product_id,phone,name,rating,text,photos,video,mod_status) VALUES (?,?,?,?,?,?,?,?,?)')
          ->execute([$id, $pid, $s['phone'], $nm, $rating, $text, json_encode($photos, JSON_UNESCAPED_UNICODE), $video, 'pending']);
    } catch (Exception $e) {
      db()->prepare('INSERT INTO reviews (id,product_id,phone,name,rating,text,photos,video) VALUES (?,?,?,?,?,?,?,?)')
          ->execute([$id, $pid, $s['phone'], $nm, $rating, $text, json_encode($photos, JSON_UNESCAPED_UNICODE), $video]);
    }
    jout(['ok'=>true,'pending'=>true]);
  }

  // ---- товар: установить отображаемое количество покупок (модератор/босс) ----
  case 'product_sales_set': {
    $s = authUser('itc'); require_staff($s, ['moderator']);
    $d = body();
    $pid = trim($d['product_id'] ?? '');
    if (!$pid) fail('Не указан товар');
    $target = max(0, (int)($d['target'] ?? 0));
    // реальные продажи
    $real = 0;
    try { $q = db()->prepare('SELECT COALESCE(SUM(i.qty),0) FROM order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1 WHERE i.product_id=?'); $q->execute([$pid]); $real = (int)$q->fetchColumn(); } catch (Exception $e) {}
    $boost = max(0, $target - $real);
    try { db()->prepare('UPDATE products SET sales_boost=? WHERE id=?')->execute([$boost, $pid]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (products.sales_boost)'); }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'sales_set', 'product', $pid, 'показывать '.$target.' (реальные '.$real.', накрутка '.$boost.')');
    jout(['ok'=>true,'target'=>$real + $boost,'real'=>$real,'boost'=>$boost]);
  }

  // ---- отзывы: модерация (ИТК) ----
  case 'reviews_admin': {
    authUser('itc');
    try {
      $rows = db()->query("SELECT r.id,r.product_id,r.name,r.rating,r.text,r.photos,r.video,r.answer,r.phone,r.pinned,COALESCE(r.mod_status,'approved') mod_status,UNIX_TIMESTAMP(r.created_at)*1000 AS ts, p.name AS product_name FROM reviews r LEFT JOIN products p ON p.id=r.product_id ORDER BY (COALESCE(r.mod_status,'approved')='pending') DESC, r.pinned DESC, r.created_at DESC LIMIT 500")->fetchAll();
    } catch (Exception $e) {
      $rows = db()->query('SELECT r.id,r.product_id,r.name,r.rating,r.text,r.photos,r.video,r.answer,r.phone,r.pinned,UNIX_TIMESTAMP(r.created_at)*1000 AS ts, p.name AS product_name FROM reviews r LEFT JOIN products p ON p.id=r.product_id ORDER BY r.pinned DESC, r.created_at DESC LIMIT 500')->fetchAll();
    }
    $list = [];
    foreach ($rows as $r) {
      $list[] = ['id'=>$r['id'],'product_id'=>$r['product_id'],'product_name'=>$r['product_name'],
                 'name'=>$r['name'],'rating'=>(int)$r['rating'],'text'=>$r['text'],
                 'photos'=>json_decode($r['photos'] ?: '[]', true) ?: [], 'video'=>$r['video'] ?? '', 'answer'=>$r['answer'] ?? '', 'verified'=>(strpos((string)($r['phone'] ?? ''),'itc-')!==0), 'pinned'=>(int)($r['pinned'] ?? 0), 'mod_status'=>$r['mod_status'] ?? 'approved', 'ts'=>$r['ts']];
    }
    jout(['ok'=>true,'reviews'=>$list]);
  }

  // ---- отзыв: модерация (ИТК) ----
  case 'review_moderate': {
    $s = authUser('itc');
    require_staff($s, ['moderator']);
    $d = body();
    $id = trim($d['id'] ?? '');
    $st = $d['status'] ?? '';
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    if (!$id) fail('Не указан отзыв');
    if (!in_array($st, ['approved','pending','rejected'], true)) fail('Неверный статус');
    try {
      db()->prepare('UPDATE reviews SET mod_status=? WHERE id=?')->execute([$st, $id]);
    } catch (Exception $e) { fail('Сначала выполните миграцию (reviews.mod_status)'); }
    itc_log_add($by, $st==='approved'?'review_approve':($st==='rejected'?'review_reject':'review_pending'), 'review', $id, '');
    jout(['ok'=>true,'id'=>$id,'mod_status'=>$st]);
  }

