    authUser('itc');
    $d = body();
    $text = trim($d['text'] ?? '');
    $rating = (int)($d['rating'] ?? 5);
    if ($text === '') fail('Нет текста отзыва');
    if (!defined('DEEPSEEK_API_KEY') || !DEEPSEEK_API_KEY) fail('DeepSeek не настроен');
    $reply = review_ai_reply($text, $rating);
    if ($reply === null) fail('Не удалось сгенерировать ответ');
    jout(['ok'=>true, 'reply'=>$reply]);
  }

  case 'review_save': {
    authUser('itc');
    $d = body();
    $id = trim($d['id'] ?? '');
    $pid = trim($d['product_id'] ?? '');
    $name = trim($d['name'] ?? '');
    $rating = (int)($d['rating'] ?? 0);
    $text = trim($d['text'] ?? '');
    $photos = $d['photos'] ?? [];
    if (!is_array($photos)) $photos = [];
    $photos = array_slice($photos, 0, 3);
    $video = trim($d['video'] ?? '');
    $answer = trim($d['answer'] ?? '');
    if ($rating < 1 || $rating > 5) fail('Поставьте оценку от 1 до 5');
    if ($id) {
      db()->prepare('UPDATE reviews SET name=?,rating=?,text=?,photos=?,video=?,answer=? WHERE id=?')
          ->execute([$name, $rating, $text, json_encode($photos, JSON_UNESCAPED_UNICODE), $video, $answer, $id]);
    } else {
      if (!$pid) fail('Выберите товар');
      if ($name === '') $name = 'ИТК';
      $ph = 'itc-' . bin2hex(random_bytes(6));
      $nid = gen('rv');
      db()->prepare('INSERT INTO reviews (id,product_id,phone,name,rating,text,photos,video,answer) VALUES (?,?,?,?,?,?,?,?,?)')
          ->execute([$nid, $pid, $ph, $name, $rating, $text, json_encode($photos, JSON_UNESCAPED_UNICODE), $video, $answer]);
    }
    jout(['ok'=>true]);
  }

  case 'review_pin': {
    authUser('itc');
    $d = body();
    $id = trim($d['id'] ?? '');
    $pin = (int)($d['pinned'] ?? 0);
    if (!$id) fail('Нет id');
    $q = db()->prepare('SELECT product_id FROM reviews WHERE id=?'); $q->execute([$id]); $rr = $q->fetch();
    if (!$rr) fail('Отзыв не найден');
    if ($pin) {
      db()->prepare('UPDATE reviews SET pinned=0 WHERE product_id=?')->execute([$rr['product_id']]);
      db()->prepare('UPDATE reviews SET pinned=1 WHERE id=?')->execute([$id]);
    } else {
      db()->prepare('UPDATE reviews SET pinned=0 WHERE id=?')->execute([$id]);
    }
    jout(['ok'=>true]);
  }

  case 'review_delete': {
    authUser('itc');
    $d = body();
    $id = trim($d['id'] ?? '');
    if ($id) db()->prepare('DELETE FROM reviews WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }

  // ---- чат поддержки: покупатель отправляет сообщение ----
  case 'support_send': {
    $s = authUser();
    $d = body();
    $text = mb_substr(trim($d['text'] ?? ''), 0, 2000);
    $topic = mb_substr(trim($d['topic'] ?? ''), 0, 60);
    $imgIn = trim($d['img'] ?? '');
    if ($text === '' && $imgIn === '') fail('Введите сообщение или прикрепите фото');
    $imgUrl = '';
    if ($imgIn !== '') { try { $imgUrl = s3_put_base64($imgIn); } catch (Exception $e) {} }
    $nm = ''; try { $nq = db()->prepare('SELECT name FROM customers WHERE phone=?'); $nq->execute([$s['phone']]); $nm = $nq->fetchColumn() ?: ''; } catch (Exception $e) {}
    try {
      db()->prepare("INSERT INTO support_messages (phone,name,sender,topic,text,img,kind,read_itc,read_buyer) VALUES (?,?,?,?,?,?,'buyer',0,1)")
          ->execute([$s['phone'], $nm, 'buyer', $topic, $text, $imgUrl]);
    } catch (Exception $e) {
      try { db()->prepare('INSERT INTO support_messages (phone,name,sender,topic,text,read_itc,read_buyer) VALUES (?,?,?,?,?,0,1)')->execute([$s['phone'], $nm, 'buyer', $topic, $text]); }
      catch (Exception $e2) { fail('Сначала выполните миграцию (support_messages)'); }
    }
    jout(['ok'=>true]);
  }

  // ---- чат поддержки: покупатель читает свою переписку ----
  case 'support_thread': {
    $s = authUser('buyer');
    try { db()->prepare("UPDATE support_messages SET read_buyer=1 WHERE phone=? AND sender='itc'")->execute([$s['phone']]); } catch (Exception $e) {}
    $rows = [];
    try {
      $q = db()->prepare("SELECT sender,text,COALESCE(img,'') img,topic,staff,UNIX_TIMESTAMP(created_at)*1000 ts FROM support_messages WHERE phone=? AND (kind='buyer' OR kind='' OR kind IS NULL) ORDER BY id ASC");
      $q->execute([$s['phone']]); $rows = $q->fetchAll();
      foreach ($rows as &$r) { $r['ts'] = (int)$r['ts']; } unset($r);
    } catch (Exception $e) {
      try {
        $q = db()->prepare("SELECT sender,text,topic,staff,UNIX_TIMESTAMP(created_at)*1000 ts FROM support_messages WHERE phone=? AND (kind='buyer' OR kind='' OR kind IS NULL) ORDER BY id ASC");
        $q->execute([$s['phone']]); $rows = $q->fetchAll();
        foreach ($rows as &$r) { $r['ts'] = (int)$r['ts']; $r['img']=''; } unset($r);
      } catch (Exception $e2) { $rows = []; }
    }
    jout(['ok'=>true,'messages'=>$rows]);
  }

  // ---- чат поставщика «Связь с компанией»: поставщик отправляет ----
  case 'supplier_support_send': {
    $s = authUser('supplier');
