    $nm = ''; try { $nq = db()->prepare('SELECT name FROM suppliers WHERE id=?'); $nq->execute([$s['supplier_id']]); $nm = $nq->fetchColumn() ?: ''; } catch (Exception $e) {}
    try {
      db()->prepare("INSERT INTO support_messages (phone,name,sender,topic,text,kind,read_itc,read_buyer) VALUES (?,?,?,?,?,'supplier',0,1)")
          ->execute([$s['phone'], $nm, 'supplier', $topic, $text]);
