  case 'supplier_support_thread': {
    $s = authUser('supplier');
    try { db()->prepare("UPDATE support_messages SET read_buyer=1 WHERE phone=? AND kind='supplier' AND sender='itc'")->execute([$s['phone']]); } catch (Exception $e) {}
    $rows = [];
    try {
      $q = db()->prepare("SELECT sender,text,topic,staff,UNIX_TIMESTAMP(created_at)*1000 ts FROM support_messages WHERE phone=? AND kind='supplier' ORDER BY id ASC");
      $q->execute([$s['phone']]); $rows = $q->fetchAll();
      foreach ($rows as &$r) { $r['ts'] = (int)$r['ts']; } unset($r);
    } catch (Exception $e) { $rows = []; }
