  // ---- чат поддержки (ИТК): список обращений (kind: buyer|supplier) ----
  case 'support_list': {
    authUser('itc');
    $d = body();
    $kind = $d['kind'] ?? ($_GET['kind'] ?? 'buyer');
    if (!in_array($kind, ['buyer','supplier','partner','warehouse'], true)) $kind = 'buyer';
    $rows = [];
    try {
      $q = db()->prepare(
        "SELECT m.phone,
                UNIX_TIMESTAMP(MAX(m.created_at))*1000 ts,
                (SELECT name  FROM support_messages WHERE phone=m.phone AND name<>''  ORDER BY id DESC LIMIT 1) name,
                (SELECT text  FROM support_messages WHERE phone=m.phone               ORDER BY id DESC LIMIT 1) last_text,
                (SELECT sender FROM support_messages WHERE phone=m.phone              ORDER BY id DESC LIMIT 1) last_sender,
                (SELECT topic FROM support_messages WHERE phone=m.phone AND topic<>'' ORDER BY id ASC  LIMIT 1) topic,
                SUM(CASE WHEN m.sender<>'itc' AND m.read_itc=0 THEN 1 ELSE 0 END) unread
           FROM support_messages m WHERE (m.kind=? OR (?='buyer' AND (m.kind='' OR m.kind IS NULL))) GROUP BY m.phone ORDER BY MAX(m.created_at) DESC");
      $q->execute([$kind, $kind]); $rows = $q->fetchAll();
      foreach ($rows as &$r) { $r['ts'] = (int)$r['ts']; $r['unread'] = (int)$r['unread']; } unset($r);
    } catch (Exception $e) { $rows = []; }
    /* Пункт выдачи рядом с именем покупателя (№266). */
    if ($kind === 'buyer') {
      foreach ($rows as &$r) { $r['point'] = itc_buyer_point($r['phone']); } unset($r);
    }
    jout(['ok'=>true,'threads'=>$rows,'kind'=>$kind]);
  }

  // ---- чат поддержки (ИТК): переписка ----
  case 'support_thread_itc': {
    authUser('itc');
    $d = body();
    $phone = trim($d['phone'] ?? '');
    $kind = ($d['kind'] ?? 'buyer') === 'supplier' ? 'supplier' : 'buyer';
    if (!$phone) fail('Не указан телефон');
    try { db()->prepare("UPDATE support_messages SET read_itc=1 WHERE phone=? AND sender<>'itc'")->execute([$phone]); } catch (Exception $e) {}
    $rows = [];
    try {
      $q = db()->prepare("SELECT sender,text,COALESCE(img,'') img,topic,staff,name,UNIX_TIMESTAMP(created_at)*1000 ts FROM support_messages WHERE phone=? ORDER BY id ASC");
      $q->execute([$phone]); $rows = $q->fetchAll();
      foreach ($rows as &$r) { $r['ts'] = (int)$r['ts']; } unset($r);
    } catch (Exception $e) {
      try {
        $q = db()->prepare("SELECT sender,text,topic,staff,name,UNIX_TIMESTAMP(created_at)*1000 ts FROM support_messages WHERE phone=? ORDER BY id ASC");
        $q->execute([$phone]); $rows = $q->fetchAll();
        foreach ($rows as &$r) { $r['ts'] = (int)$r['ts']; $r['img']=''; } unset($r);
      } catch (Exception $e2) { $rows = []; }
    }
    jout(['ok'=>true,'messages'=>$rows,'phone'=>$phone]);
  }

  // ---- чат поддержки (ИТК): ответ ----
  case 'support_reply': {
    authUser('itc');
    $d = body();
    $phone = trim($d['phone'] ?? '');
    $text = mb_substr(trim($d['text'] ?? ''), 0, 2000);
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    $kind = $d['kind'] ?? 'buyer';
    if (!in_array($kind, ['buyer','supplier','partner','warehouse'], true)) $kind = 'buyer';
    if (!$phone) fail('Не указан получатель');
    if ($text === '') fail('Введите сообщение');
    $nm = '';
    try {
      if ($kind === 'supplier') { $nq = db()->prepare('SELECT name FROM suppliers WHERE phone=?'); $nq->execute([$phone]); }
      elseif ($kind === 'partner') { $nq = db()->prepare('SELECT name FROM partners WHERE phone=?'); $nq->execute([$phone]); }
      elseif ($kind === 'warehouse') { $nq = db()->prepare('SELECT name FROM warehouses WHERE id=?'); $nq->execute([$phone]); }
      else { $nq = db()->prepare('SELECT name FROM customers WHERE phone=?'); $nq->execute([$phone]); }
      $nm = $nq->fetchColumn() ?: '';
    } catch (Exception $e) {}
    try {
      db()->prepare("INSERT INTO support_messages (phone,name,sender,text,staff,kind,read_itc,read_buyer) VALUES (?,?,?,?,?,?,1,0)")
          ->execute([$phone, $nm, 'itc', $text, $by, $kind]);
    } catch (Exception $e) {
      try { db()->prepare('INSERT INTO support_messages (phone,name,sender,text,staff,read_itc,read_buyer) VALUES (?,?,?,?,?,1,0)')->execute([$phone, $nm, 'itc', $text, $by]); }
      catch (Exception $e2) { fail('Сначала выполните миграцию (support_messages)'); }
    }
    itc_log_add($by, $kind==='supplier'?'supplier_reply':'support_reply', 'support', $phone, mb_substr($text,0,80));
    /* Уведомление на телефон (№266). Раньше ответ просто ложился в базу, и
       человек узнавал о нём, только случайно открыв чат. Покупателю ссылка
       открывает сразу чат с поддержкой. Склад (kind=warehouse) — это не номер
       телефона, ему не шлём. */
    $pushed = 0;
    if ($kind !== 'warehouse') {
      $ptxt = mb_strlen($text) > 140 ? (mb_substr($text, 0, 137) . '…') : $text;
      $pushed = itc_push_phone($phone, 'Ответ от ИТК', $ptxt, $kind === 'buyer' ? '/?chat=1' : '/');
    }
    jout(['ok'=>true, 'pushed'=>$pushed]);
  }

  // ---- ПАРТНЁР: вход по коду, выданному ИТК ----
  case 'partner_login': {
    $d = body();
    $phone = trim($d['phone'] ?? '');
    $code = trim($d['code'] ?? '');
    if (!$phone || !$code) fail('Введите телефон и код');
    $p = itc_partner_by_phone($phone);
    if (!$p) fail('Партнёр не найден. Сначала зарегистрируйтесь по SMS.');
    if ($p['status'] === 'blocked') fail('Доступ закрыт. Обратитесь в ИТК.');
    if ($p['status'] !== 'active') fail('Доступ ещё не открыт. ИТК выдаст код после активации.');
    if ($p['code'] === '' || $p['code'] !== $code) fail('Неверный код доступа');
    $token = make_session($phone, 'partner', $p['id']);
    jout(['ok'=>true,'status'=>'login','role'=>'partner','token'=>$token,'name'=>$p['name']]);
  }

  // ---- ПАРТНЁР: движение товара к его складу + экономика ----
  case 'partner_state': {
    $prevPid = $_GET['pid'] ?? '';
    if ($prevPid !== '') { $s = authUser('itc'); $pid = $prevPid; }   // предпросмотр боссом/сотрудником
    else { $s = authUser('partner'); $pid = $s['supplier_id'] ?? ''; }
    $pt = db()->prepare('SELECT id,name,warehouse_id,markup,share,status,payout_req,company,inn,kpp,addr,bank,bik,account,corr,contact,email FROM partners WHERE id=?');
    $pt->execute([$pid]);
    $p = $pt->fetch();
    if (!$p) fail('Партнёр не найден');
    $profile = ['name'=>$p['name'],'company'=>$p['company'],'inn'=>$p['inn'],'kpp'=>$p['kpp'],'addr'=>$p['addr'],'bank'=>$p['bank'],'bik'=>$p['bik'],'account'=>$p['account'],'corr'=>$p['corr'],'contact'=>$p['contact'],'email'=>$p['email']];
    itc_bonus_ensure();
    $wh = $p['warehouse_id'];
    $markup = (float)($p['markup'] ?? 15);
    $share = (float)($p['share'] ?? 10);
    $whInfo = null; $wh_kind = 'hub';
    if ($wh) {
      try { $wq = db()->prepare('SELECT id,code,name,city,country,kind FROM warehouses WHERE id=?'); $wq->execute([$wh]); $whInfo = $wq->fetch() ?: null; }
      catch (Exception $e) { $wq = db()->prepare('SELECT id,code,name,city,country FROM warehouses WHERE id=?'); $wq->execute([$wh]); $whInfo = $wq->fetch() ?: null; }
      if ($whInfo) $wh_kind = $whInfo['kind'] ?? 'hub';
    }
    $pct  = itc_partner_pct($wh_kind, $wh);          // база + региональный бонус
    $base = itc_partner_base_pct($wh_kind);
    $bonus = $pct - $base;
    $orders = [];
    $cost_paid = 0; $cost_transit = 0; $units = 0; $paid_cnt = 0;
    $monthly = []; // ключ YYYY-MM => доля
    if ($wh) {
      $oq = db()->prepare("SELECT id,num,status,paid,addr_city,addr_name,wh_cell,wh_weight,wh_damage,(wh_photo IS NOT NULL AND wh_photo<>'') has_photo,box_checked,box_ok,box_act_m3,
                                  UNIX_TIMESTAMP(created_at)*1000 ts,UNIX_TIMESTAMP(wh_received_at)*1000 rts,UNIX_TIMESTAMP(wh_shipped_at)*1000 sts,UNIX_TIMESTAMP(picked_up_at)*1000 pts,
                                  DATE_FORMAT(created_at,'%Y-%m') ym FROM orders WHERE warehouse_id=? AND paid=1 ORDER BY created_at DESC LIMIT 300");
      /* №270: только ОПЛАЧЕННЫЕ. Неоплаченный заказ — это брошенная корзина или
         оборванная оплата: он никогда не поедет на пункт. Раньше такие заказы
         висели у партнёра с пометками «В пути» и «Ваши 8%», хотя товара не будет
         и денег за них тоже. Склад (warehouse_state) так и работал — только paid=1. */
      $oq->execute([$wh]);
      $ordersRaw = $oq->fetchAll();
      /* №355 · заказы, где этот пункт — ПОЛУЧАТЕЛЬ (едут со склада на пункт): раньше их не было в списке,
         поэтому принятый товар не появлялся в «У вас на пункте». «Принят» для них — dest_received_at. */
      try {
        $dq = db()->prepare("SELECT id,num,status,paid,addr_city,addr_name,wh_cell,wh_weight,wh_damage,(wh_photo IS NOT NULL AND wh_photo<>'') has_photo,box_checked,box_ok,box_act_m3,
                                    UNIX_TIMESTAMP(created_at)*1000 ts,UNIX_TIMESTAMP(dest_received_at)*1000 rts,0 sts,UNIX_TIMESTAMP(picked_up_at)*1000 pts,
                                    DATE_FORMAT(created_at,'%Y-%m') ym FROM orders WHERE dest_warehouse_id=? AND (warehouse_id IS NULL OR warehouse_id<>?) AND paid=1 ORDER BY created_at DESC LIMIT 300");
        $dq->execute([$wh, $wh]);
        foreach ($dq->fetchAll() as $x) $ordersRaw[] = $x;
      } catch (Exception $e) {}
      /* СКЛАДУ ДОБАВЛЯЕМ крупногабарит из заказов его пунктов: товар физически
         остаётся у него и выдаётся с него, значит и в списке к выдаче, и в
         обороте он должен быть у склада. */
      if ($wh_kind !== 'pvz') {
        try {
          $eq = db()->prepare("SELECT o.id,o.num,o.status,o.paid,o.addr_city,o.addr_name,o.wh_cell,o.wh_weight,o.wh_damage,
                                      0 has_photo,o.box_checked,o.box_ok,o.box_act_m3,
                                      UNIX_TIMESTAMP(o.created_at)*1000 ts,UNIX_TIMESTAMP(o.wh_received_at)*1000 rts,
                                      UNIX_TIMESTAMP(o.wh_shipped_at)*1000 sts,UNIX_TIMESTAMP(o.picked_up_at)*1000 pts,
                                      DATE_FORMAT(o.created_at,'%Y-%m') ym, 1 AS from_pvz
                                 FROM orders o
                                 JOIN order_items i ON i.order_id=o.id AND i.oversize=1
                                 JOIN warehouses w ON w.id=o.warehouse_id AND w.parent_id=?
                                WHERE o.paid=1
                                GROUP BY o.id ORDER BY o.created_at DESC LIMIT 300");
          $eq->execute([$wh]);
          foreach ($eq->fetchAll() as $x) $ordersRaw[] = $x;
        } catch (Exception $e) {}
      }
      foreach ($ordersRaw as $o) {
        /* КРУПНОГАБАРИТ ПУНКТУ НЕ ПОКАЗЫВАЕМ ВООБЩЕ. Товар к нему не приедет:
           он остаётся на родительском складе и выдаётся оттуда. Значит и в списке
           к выдаче, и в обороте пункта его быть не должно — иначе оператор будет
           ждать коробку, которой не будет. */
        try { $iq = db()->prepare('SELECT name,qty,price,COALESCE(oversize,0) oversize FROM order_items WHERE order_id=?'); $iq->execute([$o['id']]); $its=$iq->fetchAll(); }
        catch (Exception $e) { $iq = db()->prepare('SELECT name,qty,price FROM order_items WHERE order_id=?'); $iq->execute([$o['id']]); $its=$iq->fetchAll(); }
        $items = []; $osum = 0;
        foreach ($its as $it) {
          if ($wh_kind === 'pvz' && !empty($it['oversize'])) continue;   // этой позиции у пункта нет
          // заказ пришёл от подчинённого пункта — складу принадлежит только крупногабарит
          if (!empty($o['from_pvz']) && empty($it['oversize'])) continue;
          $line = (int)$it['price'] * (int)$it['qty'];
          $osum += $line; $units += (int)$it['qty'];
          $items[] = ['name'=>$it['name'],'qty'=>(int)$it['qty'],'price'=>(int)$it['price'],'oversize'=>!empty($it['oversize'])?1:0];
        }
        if (!$items) continue;   // показывать нечего
        /* №271: выкуплен ли заказ у поставщика — чтобы партнёр видел, на каком
           этапе оплаченный заказ ещё до того, как он доехал до склада в Китае. */
        $bought = null;
        try {
          $bq = db()->prepare("SELECT COUNT(*) c, SUM(CASE WHEN status IN ('ordered','received') THEN 1 ELSE 0 END) b FROM ds_procurement WHERE order_id=?");
          $bq->execute([$o['id']]); $br = $bq->fetch();
          if ($br && (int)$br['c'] > 0) $bought = ((int)$br['b'] >= (int)$br['c']) ? 1 : 0;
        } catch (Exception $e) {}
        $oShare = round($osum * $pct/100);
        if ((int)$o['paid'] === 1) { $cost_paid += $osum; $paid_cnt++; if (!isset($monthly[$o['ym']])) $monthly[$o['ym']]=0; $monthly[$o['ym']] += $oShare; } else { $cost_transit += $osum; }
        $orders[] = ['num'=>$o['num'],'status'=>$o['status'],'paid'=>(int)$o['paid'],'ts'=>(int)$o['ts'],'sum'=>$osum,'items'=>$items,'my_share'=>$oShare,
                     'city'=>$o['addr_city'],'name'=>$o['addr_name'],'cell'=>$o['wh_cell'],'weight'=>(float)$o['wh_weight'],'damage'=>(int)$o['wh_damage'],'has_photo'=>(int)$o['has_photo'],
                     'box_checked'=>(int)$o['box_checked'],'box_ok'=>(int)$o['box_ok'],'act_m3'=>(float)$o['box_act_m3'],'id'=>$o['id'],
                     'received'=>$o['rts']?1:0,'shipped'=>$o['sts']?1:0,'picked'=>$o['pts']?1:0,'bought'=>$bought];
      }
    }
    $markup_amount = round($cost_paid * $markup / 100); // устар. поле, в выплате не участвует
    $partner_share = round($cost_paid * $pct / 100);
    // выплаты
    $paid_out = 0; $payouts = [];
    try {
      $pq = db()->prepare("SELECT amount,note,UNIX_TIMESTAMP(created_at)*1000 ts FROM partner_payouts WHERE partner_id=? ORDER BY created_at DESC LIMIT 50");
      $pq->execute([$pid]);
      foreach ($pq->fetchAll() as $po) { $paid_out += (float)$po['amount']; $payouts[] = ['amount'=>(int)$po['amount'],'note'=>$po['note'],'ts'=>(int)$po['ts']]; }
    } catch (Exception $e) {}
    $balance = $partner_share - $paid_out;
    // рейтинг/статус по обороту
    $turnover = $cost_paid;
    $tiers = [['Бронза','🥉',0,5],['Серебро','🥈',500000,7],['Золото','🥇',2000000,10],['Платина','💎',5000000,12]];
    $tier = $tiers[0]; $next = null;
    foreach ($tiers as $i=>$t) { if ($turnover >= $t[2]) { $tier = $t; if (isset($tiers[$i+1])) $next = $tiers[$i+1]; } }
    $tierInfo = ['name'=>$tier[0],'icon'=>$tier[1],'bonus'=>$tier[3],'turnover'=>(int)$turnover,
                 'next_name'=>$next?$next[0]:'','next_at'=>$next?(int)$next[2]:0,'next_bonus'=>$next?$next[3]:0];
    // помесячно — последние 6
    $mk = array_keys($monthly); rsort($mk); $mk = array_slice($mk, 0, 6); sort($mk);
    $month_series = []; foreach ($mk as $m) $month_series[] = ['m'=>$m,'v'=>(int)$monthly[$m]];
    // рефералы
    $ref_code = ensure_ref_code($pid);
    $ref_percent = (float)(get_settings()['ref_percent'] ?? 0);
    $ref_count = 0; $ref_orders_total = 0; $ref_orders_cnt = 0;
    try {
      $rc = db()->prepare('SELECT COUNT(*) FROM customers WHERE ref_partner_id=?'); $rc->execute([$pid]); $ref_count = (int)$rc->fetchColumn();
      $ro = db()->prepare("SELECT COALESCE(SUM(o.total),0) tot, COUNT(*) c FROM orders o JOIN customers c ON c.phone=o.phone WHERE c.ref_partner_id=? AND o.paid=1");
      $ro->execute([$pid]); $rr = $ro->fetch(); $ref_orders_total = (int)$rr['tot']; $ref_orders_cnt = (int)$rr['c'];
    } catch (Exception $e) {}
    $ref_income = (int)round($ref_orders_total * $ref_percent / 100);
    jout(['ok'=>true,'name'=>$p['name'],'status'=>$p['status'],'warehouse'=>$whInfo,'markup'=>$markup,'share'=>$share,'pct'=>$pct,'base_pct'=>$base,'bonus_pct'=>$bonus,'bonus_until'=>ITC_BONUS_UNTIL,'wh_kind'=>$wh_kind,'profile'=>$profile,
          'ref_code'=>$ref_code,'ref_percent'=>$ref_percent,'ref_count'=>$ref_count,'ref_orders'=>$ref_orders_cnt,'ref_orders_total'=>$ref_orders_total,'ref_income'=>$ref_income,
          'payout_req'=>(int)$p['payout_req'],'paid_out'=>(int)$paid_out,'balance'=>(int)$balance,'payouts'=>$payouts,'monthly'=>$month_series,'tier'=>$tierInfo,
          'orders'=>$orders,'econ'=>['cost_paid'=>$cost_paid,'cost_transit'=>$cost_transit,'units'=>$units,'paid_orders'=>$paid_cnt,'orders_total'=>count($orders),'markup_amount'=>$markup_amount,'partner_share'=>$partner_share]]);
  }

  // ---- СКЛАД: чат с ИТК (kind=warehouse, ветка = id склада) ----
  case 'wh_chat_send': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??'';
    if (!($role==='itc' && $sr==='warehouse')) fail('Только оператор склада', 403);
    $wh = $s['supplier_id'] ?? ''; if (!$wh) fail('Нет склада');
    $d = body(); $text = mb_substr(trim($d['text'] ?? ''), 0, 2000);
    if ($text === '') fail('Пустое сообщение');
    $nm = ''; try { $nq=db()->prepare('SELECT name FROM warehouses WHERE id=?'); $nq->execute([$wh]); $nm=$nq->fetchColumn()?:'Склад'; } catch (Exception $e) { $nm='Склад'; }
    try {
      db()->prepare("INSERT INTO support_messages (phone,name,sender,topic,text,kind,read_itc,read_buyer) VALUES (?,?,?,?,?,?,0,1)")
          ->execute([$wh,$nm,'buyer',mb_substr(trim($d['topic']??''),0,80),$text,'warehouse']);
    } catch (Exception $e) { fail('Сначала выполните миграцию (support_messages.kind)'); }
    jout(['ok'=>true]);
  }
  case 'wh_chat_thread': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??'';
    if (!($role==='itc' && $sr==='warehouse')) fail('Только оператор склада', 403);
    $wh = $s['supplier_id'] ?? '';
    $msgs = [];
    try {
      $st = db()->prepare("SELECT sender,text,staff,UNIX_TIMESTAMP(created_at)*1000 ts FROM support_messages WHERE phone=? AND kind='warehouse' ORDER BY created_at ASC LIMIT 200");
      $st->execute([$wh]);
      foreach ($st->fetchAll() as $m) $msgs[] = ['sender'=>$m['sender'],'text'=>$m['text'],'staff'=>$m['staff'],'ts'=>(int)$m['ts']];
      db()->prepare("UPDATE support_messages SET read_buyer=1 WHERE phone=? AND kind='warehouse' AND sender='itc'")->execute([$wh]);
    } catch (Exception $e) {}
    jout(['ok'=>true,'messages'=>$msgs]);
  }

  // ---- ПАРТНЁР: запрос выплаты ----
  case 'partner_payout_request': {
    $s = authUser('partner');
    $pid = $s['supplier_id'] ?? '';
    try { db()->prepare('UPDATE partners SET payout_req=1,payout_req_at=NOW() WHERE id=?')->execute([$pid]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (payout_req)'); }
    jout(['ok'=>true]);
  }

  // ---- ПАРТНЁР: чат с ИТК (kind=partner) ----
  case 'partner_support_send': {
    $s = authUser('partner');
    $pid = $s['supplier_id'] ?? ''; $phone = $s['phone'];
    $d = body(); $text = mb_substr(trim($d['text'] ?? ''), 0, 2000);
    if ($text === '') fail('Пустое сообщение');
    $nm = '';
    try { $nq=db()->prepare('SELECT name FROM partners WHERE id=?'); $nq->execute([$pid]); $nm=$nq->fetchColumn()?:''; } catch (Exception $e) {}
    try {
      db()->prepare("INSERT INTO support_messages (phone,name,sender,topic,text,kind,read_itc,read_buyer) VALUES (?,?,?,?,?,?,0,1)")
          ->execute([$phone,$nm,'buyer',mb_substr(trim($d['topic']??''),0,80),$text,'partner']);
    } catch (Exception $e) { fail('Сначала выполните миграцию (support_messages.kind)'); }
    jout(['ok'=>true]);
  }
  case 'partner_support_thread': {
    $s = authUser('partner');
    $phone = $s['phone'];
    $msgs = [];
    try {
      $st = db()->prepare("SELECT sender,text,topic,staff,UNIX_TIMESTAMP(created_at)*1000 ts FROM support_messages WHERE phone=? AND kind='partner' ORDER BY created_at ASC LIMIT 200");
      $st->execute([$phone]);
      foreach ($st->fetchAll() as $m) $msgs[] = ['sender'=>$m['sender'],'text'=>$m['text'],'topic'=>$m['topic'],'staff'=>$m['staff'],'ts'=>(int)$m['ts']];
      db()->prepare("UPDATE support_messages SET read_buyer=1 WHERE phone=? AND kind='partner' AND sender='itc'")->execute([$phone]);
    } catch (Exception $e) {}
    jout(['ok'=>true,'messages'=>$msgs]);
  }

  // ---- СОТРУДНИКИ ИТК (только босс) ----
  case 'staff_list': {
    $s = authUser('itc'); require_staff($s, []);
    $rows = [];
    try {
      foreach (db()->query("SELECT s.id,s.phone,s.code,s.role,s.name,s.active,s.warehouse_id, w.name wh_name, w.city wh_city, UNIX_TIMESTAMP(s.created_at)*1000 ts FROM staff s LEFT JOIN warehouses w ON w.id=s.warehouse_id ORDER BY (s.role='boss') DESC, s.created_at ASC")->fetchAll() as $r)
        $rows[] = ['id'=>$r['id'],'phone'=>$r['phone'],'code'=>$r['code'],'role'=>$r['role'],'name'=>$r['name'],'active'=>(int)$r['active'],'warehouse_id'=>$r['warehouse_id'],'wh_name'=>$r['wh_name'],'wh_city'=>$r['wh_city'],'ts'=>(int)$r['ts']];
    } catch (Exception $e) {
      try {
        foreach (db()->query("SELECT id,phone,code,role,name,active,UNIX_TIMESTAMP(created_at)*1000 ts FROM staff ORDER BY (role='boss') DESC, created_at ASC")->fetchAll() as $r)
          $rows[] = ['id'=>$r['id'],'phone'=>$r['phone'],'code'=>$r['code'],'role'=>$r['role'],'name'=>$r['name'],'active'=>(int)$r['active'],'ts'=>(int)$r['ts']];
      } catch (Exception $e2) {}
    }
    jout(['ok'=>true,'staff'=>$rows,'roles'=>['boss','supervisor','manager','sales','moderator','accountant','chief_accountant','wh_manager','wh_worker','wh_keeper']]);
  }
  case 'staff_save': {
    $s = authUser('itc'); require_staff($s, []);
    $d = body();
    $id = trim($d['id'] ?? '');
    $name = mb_substr(trim($d['name'] ?? ''), 0, 120);
    $phone = trim($d['phone'] ?? '');
    $officeRoles = ['boss','supervisor','manager','sales','moderator','accountant','chief_accountant'];
    $whRoles = ['wh_manager','wh_worker','wh_keeper'];
    $role = in_array(($d['role'] ?? ''), array_merge($officeRoles, $whRoles), true) ? $d['role'] : 'manager';
    $warehouse_id = trim($d['warehouse_id'] ?? '');
    if (in_array($role, $whRoles, true)) {
      if (!$warehouse_id) fail('Выберите склад для сотрудника склада');
      try { $wc=db()->prepare('SELECT id FROM warehouses WHERE id=?'); $wc->execute([$warehouse_id]); if (!$wc->fetchColumn()) fail('Склад не найден'); } catch (Exception $e) {}
    } else { $warehouse_id = null; }
    if (!$phone) fail('Укажите телефон сотрудника');
    if ($id) {
      try { db()->prepare('UPDATE staff SET name=?,phone=?,role=?,warehouse_id=? WHERE id=?')->execute([$name,$phone,$role,$warehouse_id,$id]); }
      catch (Exception $e) {
        if ($warehouse_id) fail('Нужна миграция (staff.warehouse_id) — она требуется для сотрудников склада');
        try { db()->prepare('UPDATE staff SET name=?,phone=?,role=? WHERE id=?')->execute([$name,$phone,$role,$id]); }
        catch (Exception $e2) { fail('Не удалось сохранить (телефон уже используется?)'); }
      }
      jout(['ok'=>true,'id'=>$id]);
    } else {
      // не дублируем по телефону
      try { $ex=db()->prepare("SELECT id FROM staff WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') LIMIT 1"); $ex->execute([$phone]); if ($ex->fetchColumn()) fail('Сотрудник с таким телефоном уже есть'); } catch (Exception $e) {}
      $nid = gen('stf'); $code = staff_gen_code();
      try { db()->prepare('INSERT INTO staff (id,phone,code,role,name,active,warehouse_id) VALUES (?,?,?,?,?,1,?)')->execute([$nid,$phone,$code,$role,$name,$warehouse_id]); }
      catch (Exception $e) {
        if ($warehouse_id) fail('Сначала выполните миграцию (staff.warehouse_id) — она требуется для сотрудников склада');
        try { db()->prepare('INSERT INTO staff (id,phone,code,role,name,active) VALUES (?,?,?,?,?,1)')->execute([$nid,$phone,$code,$role,$name]); }
        catch (Exception $e2) { fail('Сначала выполните миграцию (staff)'); }
      }
      jout(['ok'=>true,'id'=>$nid,'code'=>$code]);
    }
  }
