  case 'movement_all': {
    $s = authUser('itc'); require_staff($s, ['chief_accountant']);
    $num = trim($_GET['num'] ?? (body()['num'] ?? ''));
    $events = [];
    try {
      if ($num !== '') {
        $lq = db()->prepare("SELECT l.staff,l.action,l.order_num,l.note,UNIX_TIMESTAMP(l.created_at)*1000 ts, w.name wh_name, w.country wh_country FROM wh_log l LEFT JOIN warehouses w ON w.id=l.warehouse_id WHERE l.order_num=? ORDER BY l.created_at ASC LIMIT 200");
        $lq->execute([$num]);
      } else {
        $lq = db()->query("SELECT l.staff,l.action,l.order_num,l.note,UNIX_TIMESTAMP(l.created_at)*1000 ts, w.name wh_name, w.country wh_country FROM wh_log l LEFT JOIN warehouses w ON w.id=l.warehouse_id ORDER BY l.created_at DESC LIMIT 200");
      }
      foreach ($lq->fetchAll() as $l) $events[] = ['staff'=>$l['staff'],'action'=>$l['action'],'num'=>$l['order_num'],'note'=>$l['note'],'wh_name'=>$l['wh_name'],'wh_country'=>$l['wh_country'],'ts'=>(int)$l['ts']];
    } catch (Exception $e) {}
    $track = null;
    if ($num !== '') {
      try {
        $oq = db()->prepare("SELECT o.num,o.status,o.addr_city,o.addr_name, wo.name origin_name, wd.name dest_name,
                                    UNIX_TIMESTAMP(o.created_at)*1000 cts, UNIX_TIMESTAMP(o.wh_received_at)*1000 rts, UNIX_TIMESTAMP(o.wh_shipped_at)*1000 sts,
                                    UNIX_TIMESTAMP(o.dest_received_at)*1000 drts, UNIX_TIMESTAMP(o.picked_up_at)*1000 pts
                             FROM orders o LEFT JOIN warehouses wo ON wo.id=o.warehouse_id LEFT JOIN warehouses wd ON wd.id=o.dest_warehouse_id WHERE o.num=? LIMIT 1");
        $oq->execute([$num]); $t=$oq->fetch();
        if ($t) $track = ['num'=>$t['num'],'status'=>$t['status'],'city'=>$t['addr_city'],'name'=>$t['addr_name'],'origin'=>$t['origin_name'],'dest'=>$t['dest_name'],
                          'cts'=>(int)$t['cts'],'rts'=>(int)$t['rts'],'sts'=>(int)$t['sts'],'drts'=>(int)$t['drts'],'pts'=>(int)$t['pts']];
        if ($track) { try { $bq=db()->prepare('SELECT COUNT(*) c, COALESCE(SUM(weight),0) w, COALESCE(SUM(volume),0) v FROM order_boxes WHERE order_id=(SELECT id FROM orders WHERE num=? LIMIT 1) AND origin_at IS NOT NULL'); $bq->execute([$num]); $br=$bq->fetch(); if ($br) { $track['boxes_recv']=(int)$br['c']; $track['recv_w']=round((float)$br['w'],1); $track['recv_v']=round((float)$br['v'],3); } } catch (Exception $e) {} }
      } catch (Exception $e) {}
    }
    jout(['ok'=>true,'events'=>$events,'track'=>$track]);
  }

  // ---- ИТК: список партнёров ----
  // ---- Аналитика по складам и ПВЗ (для кабинета босса) ----
  case 'wh_analytics': {
    $s = authUser('itc');
    $whs = [];
    try { $whs = db()->query("SELECT id,code,name,city,country,kind,parent_id,active,access_code FROM warehouses ORDER BY (kind='pvz'),code")->fetchAll(); }
    catch (Exception $e) {
      try { $whs = db()->query("SELECT id,code,name,city,country,active FROM warehouses ORDER BY code")->fetchAll(); }
      catch (Exception $e2) { jout(['ok'=>false,'error'=>'Ошибка выборки складов']); }
    }
    // партнёр по складу
    $partnerByWh = [];
    try { foreach (db()->query("SELECT id,name,warehouse_id,share,status FROM partners")->fetchAll() as $p) { if (!empty($p['warehouse_id'])) $partnerByWh[$p['warehouse_id']] = $p; } } catch (Exception $e) {}
    // фактически выплачено партнёру
    $paidByPartner = [];
    try { foreach (db()->query("SELECT partner_id, SUM(amount) s FROM partner_payouts GROUP BY partner_id")->fetchAll() as $r) { $paidByPartner[$r['partner_id']] = (float)$r['s']; } } catch (Exception $e) {}
    // агрегаты заказов по складу
    $agg = [];
    try {
      $q = "SELECT warehouse_id,
              COUNT(*) cnt,
              SUM(CASE WHEN paid=1 THEN 1 ELSE 0 END) paid_cnt,
              SUM(CASE WHEN paid=1 THEN total ELSE 0 END) revenue,
              SUM(CASE WHEN wh_received_at IS NOT NULL THEN 1 ELSE 0 END) received,
              SUM(CASE WHEN picked_up_at IS NOT NULL THEN 1 ELSE 0 END) picked,
              MAX(UNIX_TIMESTAMP(created_at)*1000) last_ts
            FROM orders WHERE warehouse_id IS NOT NULL AND warehouse_id<>'' GROUP BY warehouse_id";
      foreach (db()->query($q)->fetchAll() as $r) { $agg[$r['warehouse_id']] = $r; }
    } catch (Exception $e) {}
    $rows = [];
    $tot = ['hubs'=>0,'pvz'=>0,'orders'=>0,'revenue'=>0,'payout'=>0,'balance'=>0,'apps'=>0];
    foreach ($whs as $w) {
      $isPvz = ((isset($w['kind']) ? $w['kind'] : 'hub') === 'pvz');
      $a = isset($agg[$w['id']]) ? $agg[$w['id']] : [];
      $rev = (float)(isset($a['revenue']) ? $a['revenue'] : 0);
      $pt = isset($partnerByWh[$w['id']]) ? $partnerByWh[$w['id']] : null;
      $rate = $isPvz ? 0.05 : 0.03; // ПВЗ 5%, склад 3%
      $accrued = $pt ? round($rev * $rate) : 0;
      $paid = $pt ? (float)(isset($paidByPartner[$pt['id']]) ? $paidByPartner[$pt['id']] : 0) : 0;
      $rows[] = [
        'id'=>$w['id'], 'code'=>$w['code'], 'name'=>$w['name'], 'city'=>(isset($w['city'])?$w['city']:''),
        'country'=>(isset($w['country'])?$w['country']:'RU'),
        'kind'=>($isPvz?'pvz':'hub'), 'active'=>(int)(isset($w['active'])?$w['active']:1),
        'partner'=>($pt ? $pt['name'] : ''), 'partner_id'=>($pt ? $pt['id'] : ''), 'partner_status'=>($pt ? (isset($pt['status'])?$pt['status']:'') : ''),
        'orders'=>(int)(isset($a['cnt'])?$a['cnt']:0), 'paid_orders'=>(int)(isset($a['paid_cnt'])?$a['paid_cnt']:0),
        'received'=>(int)(isset($a['received'])?$a['received']:0), 'picked'=>(int)(isset($a['picked'])?$a['picked']:0),
        'revenue'=>round($rev), 'accrued'=>(int)$accrued, 'paid_out'=>(int)round($paid),
        'balance'=>(int)round($accrued - $paid), 'last_ts'=>(int)(isset($a['last_ts'])?$a['last_ts']:0),
        'rate'=>$rate,
      ];
      if ($isPvz) $tot['pvz']++; else $tot['hubs']++;
      $tot['orders'] += (int)(isset($a['cnt'])?$a['cnt']:0);
      $tot['revenue'] += (int)round($rev);
      $tot['payout'] += (int)$accrued;
      $tot['balance'] += (int)round($accrued - $paid);
    }
    // заявки ПВЗ в ожидании
    /* Заявки кладутся со статусом 'new' (см. pvz_apply). Здесь искали 'pending' —
       такого статуса не бывает, поэтому счётчик всегда показывал ноль, сколько бы
       заявок ни пришло. Считаем и 'new', и пустой статус, на случай старых строк. */
    try { $tot['apps'] = (int)db()->query("SELECT COUNT(*) FROM pvz_applications WHERE status='new' OR status='pending' OR status='' OR status IS NULL")->fetchColumn(); } catch (Exception $e) {}
    jout(['ok'=>true, 'rows'=>$rows, 'totals'=>$tot]);
  }

  // ---- Авто-исправление найденных проблем ----
  case 'selfcheck_fix': {
