  // ---- Самодиагностика: проверка БД, таблиц, колонок ----
  case 'selfcheck': {
    $s = authUser('itc');
    $checks = [];
    $add = function($name,$ok,$detail='') use (&$checks){ $checks[] = ['name'=>$name,'ok'=>$ok?1:0,'detail'=>$detail]; };
    try { db()->query("SELECT 1"); $add('Соединение с БД',1,'OK'); } catch(Exception $e){ $add('Соединение с БД',0,'нет связи'); }
    foreach (['products','orders','warehouses','partners','ds_products','ob_sku','ob_item','sessions'] as $t){
      try { $n=(int)db()->query("SELECT COUNT(*) FROM `$t`")->fetchColumn(); $add('Таблица '.$t,1,$n.' зап.'); }
      catch(Exception $e){ $add('Таблица '.$t,0,'НЕТ таблицы'); }
    }
    $cols=[]; try { foreach (db()->query("SHOW COLUMNS FROM products")->fetchAll() as $c) $cols[strtolower($c['Field'])]=1; } catch(Exception $e){}
    foreach (['name','price','blocked','warehouse_id','search_tags','goods_cny','volume_m3','mod_status'] as $c){
      $add('products.'.$c, isset($cols[$c])?1:0, isset($cols[$c])?'есть':'НЕТ колонки');
    }
    foreach (['pvz_applications','partner_payouts','ob_img'] as $t){
      try { db()->query("SELECT 1 FROM `$t` LIMIT 1"); $add('Таблица '.$t,1,'есть'); }
      catch(Exception $e){ $add('Таблица '.$t,0,'нет (не критично)'); }
    }
    $ok=0; foreach($checks as $c) if($c['ok'])$ok++;
    jout(['ok'=>true,'checks'=>$checks,'passed'=>$ok,'total'=>count($checks)]);
  }

  // ===== Просмотр карточки товара 1688 (детали без импорта) =====
  case 'ob_item_view': {
    $s = authUser('itc'); require_staff($s, ['supervisor','manager']);
    $iid = preg_replace('/[^0-9]/', '', (string)($_GET['num_iid'] ?? (body()['num_iid'] ?? '')));
    if ($iid === '') fail('Не указан товар');
    $r = ob_call('item_get', ['num_iid'=>$iid], ['cache'=>'yes']);
    $data = is_array($r['data'] ?? null) ? $r['data'] : [];
    $item = $data['item'] ?? ($data['items']['item'] ?? ($data['itmes']['itme'] ?? ($r['item'] ?? null)));
    if (is_array($item) && isset($item[0]) && is_array($item[0])) $item = $item[0];
    if (!is_array($item)) {
      jout(['ok'=>false,
            'error'=>trim((string)($r['reason'] ?? '')) ?: ($r['reason_ru'] ?? 'Карточка не пришла от 1688'),
            'error_code'=>$r['error_code'] ?? null,
            'keys'=>array_keys($data)]);
    }
    $imgs = [];
    if (!empty($item['item_imgs']) && is_array($item['item_imgs'])) {
      foreach ($item['item_imgs'] as $im) { $u = is_array($im) ? ($im['url'] ?? '') : $im; if ($u) $imgs[] = $u; }
    }
    if (!$imgs && !empty($item['images']) && is_array($item['images'])) {
      foreach ($item['images'] as $u) { $u = is_array($u) ? ($u['url'] ?? '') : $u; if ($u) $imgs[] = $u; }
    }
    if (!$imgs && !empty($item['pic_url'])) $imgs[] = $item['pic_url'];
    $props = [];
    if (!empty($item['props']) && is_array($item['props'])) {
      foreach ($item['props'] as $pr) { if (is_array($pr)) { $nm = $pr['name'] ?? ($pr['prop_name'] ?? ''); $vl = $pr['value'] ?? ($pr['prop_value'] ?? ''); if ($nm !== '') $props[] = ['name'=>(string)$nm,'value'=>(string)$vl]; } }
    }
    if (!$props && !empty($item['item_params']) && is_array($item['item_params'])) {
      foreach ($item['item_params'] as $k=>$vv) $props[] = ['name'=>(string)$k,'value'=>(is_array($vv)?implode(', ',$vv):(string)$vv)];
    }
    $props = array_slice($props, 0, 30);
    $descImgs = [];
    $desc = (string)($item['desc'] ?? ($item['description'] ?? ''));
    if ($desc !== '' && preg_match_all('/https?:\/\/[^"\'\s]+\.(?:jpg|jpeg|png|gif|webp)/i', $desc, $mm)) {
      $descImgs = array_slice(array_values(array_unique($mm[0])), 0, 15);
    }
    $imgs = array_slice(array_values(array_unique($imgs)), 0, 12);
    // варианты (модификации / sku)
    $skus = [];
    $skuRaw = $item['skus']['sku'] ?? ($item['sku']['sku'] ?? ($item['skus'] ?? ($item['sku'] ?? [])));
    if (is_array($skuRaw)) {
      if (isset($skuRaw['price']) || isset($skuRaw['properties_name']) || isset($skuRaw['spec_id'])) $skuRaw = [$skuRaw];
      foreach ($skuRaw as $sk) {
        if (!is_array($sk)) continue;
        $nm = $sk['properties_name'] ?? ($sk['spec_name'] ?? ($sk['properties'] ?? ''));
        if (is_string($nm) && strpos($nm, '&gt;&gt;') !== false) $nm = str_replace('&gt;&gt;', ' ', $nm);
        $pr = $sk['price'] ?? ($sk['sku_price'] ?? ($sk['normal_price'] ?? null));
        $qty = $sk['quantity'] ?? ($sk['sku_quantity'] ?? ($sk['can_book_count'] ?? null));
        $skus[] = ['name'=>trim((string)$nm), 'price'=>($pr!==null?(string)$pr:null), 'qty'=>($qty!==null?(int)$qty:null)];
      }
    }
    $skus = array_slice($skus, 0, 40);
    // перевод названия, характеристик и названий вариантов одним запросом
    $title = (string)($item['title'] ?? '');
    $title_ru = '';
    $toTr = [$title];
    foreach ($props as $pp) { $toTr[] = $pp['name']; $toTr[] = $pp['value']; }
    $skuStart = count($toTr);
    foreach ($skus as $sk) { $toTr[] = $sk['name']; }
    $sys = 'Ты переводчик с китайского на русский для карточек товаров с 1688. Переведи каждую пронумерованную строку на русский. Сохрани ту же нумерацию (1., 2., 3. ...), один перевод на строку. Технические термины переводи корректно; коды, единицы, стандарты (ISO9001, CE, артикулы) оставляй как есть. Без пояснений и лишнего текста.';
    $tr = function_exists('ob_gpt_list_ru') ? ob_gpt_list_ru($toTr, $sys) : [];
    if (is_array($tr) && $tr) {
      $title_ru = trim((string)($tr[0] ?? ''));
      $k = 1;
      foreach ($props as $idx=>$pp) {
        $props[$idx]['name_ru']  = trim((string)($tr[$k] ?? ''));
        $props[$idx]['value_ru'] = trim((string)($tr[$k+1] ?? ''));
        $k += 2;
      }
      foreach ($skus as $idx=>$sk) { $skus[$idx]['name_ru'] = trim((string)($tr[$skuStart + $idx] ?? '')); }
    }
    jout(['ok'=>true, 'num_iid'=>$iid,
          'title'=>$title, 'title_ru'=>$title_ru,
          'price'=>$item['price'] ?? ($item['orginal_price'] ?? null),
          'imgs'=>$imgs, 'desc_imgs'=>$descImgs, 'props'=>$props, 'skus'=>$skus,
          'url'=>'https://detail.1688.com/offer/'.$iid.'.html']);
  }

  // ===== Отслеживание цен: категории A/B/C, история, автопроверка =====
  case 'ob_track_set': case 'ob_track_list': case 'ob_track_settier': case 'ob_track_del': case 'ob_track_check': case 'ob_track_run': case 'ob_track_cron': case 'ob_track_candidates': case 'ob_track_set_cat': case 'ob_track_map': case 'ob_track_set_prod': case 'ob_track_map_num': {
    try {
      db()->query("CREATE TABLE IF NOT EXISTS ob_track (num_iid VARCHAR(32) PRIMARY KEY, tier CHAR(1), title VARCHAR(255), base_price DECIMAL(12,2) NULL, last_price DECIMAL(12,2) NULL, prev_price DECIMAL(12,2) NULL, last_checked DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) DEFAULT CHARSET=utf8mb4");
      db()->query("CREATE TABLE IF NOT EXISTS ob_price_hist (id INT AUTO_INCREMENT PRIMARY KEY, num_iid VARCHAR(32), price DECIMAL(12,2), checked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY k_ni (num_iid)) DEFAULT CHARSET=utf8mb4");
    } catch (Exception $e) {}
    $intv = ['A'=>7, 'B'=>21, 'C'=>90];

    if ($action === 'ob_track_cron') {
      $cron_key = trim($_GET['cron_key'] ?? '');
      $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
      if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
      echo json_encode(ob_track_check_due($intv, 20)); exit;
    }

    $s = authUser('itc'); require_staff($s, ['boss','supervisor','manager']);
    $d = body();

    if ($action === 'ob_track_set') {
      $iid = preg_replace('/[^0-9]/', '', (string)($d['num_iid'] ?? ''));
      $tier = strtoupper(trim($d['tier'] ?? ''));
      if ($iid === '') fail('Нет товара');
      if (!in_array($tier, ['A','B','C'], true)) fail('Категория A/B/C');
      $price = (isset($d['price']) && $d['price'] !== '' && $d['price'] !== null) ? round((float)$d['price'], 2) : null;
      $title = mb_substr(trim($d['title'] ?? ''), 0, 250);
      try {
        if ($price !== null) {
          db()->prepare("INSERT INTO ob_track (num_iid,tier,title,base_price,last_price,last_checked) VALUES (?,?,?,?,?,NOW())
                         ON DUPLICATE KEY UPDATE tier=VALUES(tier), title=VALUES(title)")
            ->execute([$iid, $tier, $title, $price, $price]);
          db()->prepare("INSERT INTO ob_price_hist (num_iid,price) VALUES (?,?)")->execute([$iid, $price]);
        } else {
          // уже заведённый товар без известной базовой цены — откалибруется при первой проверке (last_checked=NULL => сразу к проверке)
          db()->prepare("INSERT INTO ob_track (num_iid,tier,title,base_price,last_price,last_checked) VALUES (?,?,?,NULL,NULL,NULL)
                         ON DUPLICATE KEY UPDATE tier=VALUES(tier), title=VALUES(title)")
            ->execute([$iid, $tier, $title]);
        }
      } catch (Exception $e) { fail('Ошибка сохранения'); }
      jout(['ok'=>true, 'tier'=>$tier]);
    }
    if ($action === 'ob_track_settier') {
      $iid = preg_replace('/[^0-9]/', '', (string)($d['num_iid'] ?? ''));
      $tier = strtoupper(trim($d['tier'] ?? ''));
      if (!in_array($tier, ['A','B','C'], true)) fail('Категория A/B/C');
      try { db()->prepare("UPDATE ob_track SET tier=? WHERE num_iid=?")->execute([$tier, $iid]); } catch (Exception $e) {}
      jout(['ok'=>true]);
    }
    if ($action === 'ob_track_del') {
      $iid = preg_replace('/[^0-9]/', '', (string)($d['num_iid'] ?? ''));
      try { db()->prepare("DELETE FROM ob_track WHERE num_iid=?")->execute([$iid]); db()->prepare("DELETE FROM ob_price_hist WHERE num_iid=?")->execute([$iid]); } catch (Exception $e) {}
      jout(['ok'=>true]);
    }
    if ($action === 'ob_track_check') {
      $iid = preg_replace('/[^0-9]/', '', (string)($d['num_iid'] ?? ''));
      $r = ob_track_check_one($iid);
      jout(array_merge(['ok'=>true], $r));
    }
    if ($action === 'ob_track_run') {
      jout(array_merge(['ok'=>true], ob_track_check_due($intv, 12)));
    }
    if ($action === 'ob_track_map_num') {
      $map = [];
      try { foreach (db()->query("SELECT num_iid,tier FROM ob_track")->fetchAll() as $t) $map[(string)$t['num_iid']] = $t['tier']; } catch (Exception $e) {}
      jout(['ok'=>true, 'map'=>$map]);
    }
    if ($action === 'ob_track_map') {
      $map = [];
      $now = time();
      try {
        $tk = [];
        foreach (db()->query("SELECT num_iid,tier,last_checked FROM ob_track")->fetchAll() as $t) $tk[$t['num_iid']] = $t;
        foreach (db()->query("SELECT source_url, product_id FROM ds_products WHERE source_url LIKE '%1688.com/offer/%' AND product_id IS NOT NULL")->fetchAll() as $r) {
          if (!preg_match('/offer\/(\d+)/', (string)$r['source_url'], $m)) continue;
          $iid = $m[1]; $pid = (string)$r['product_id'];
          $tier = 'N'; $due = 0;
          if (isset($tk[$iid])) {
            $tier = $tk[$iid]['tier'];
            $lc = $tk[$iid]['last_checked'] ? strtotime($tk[$iid]['last_checked']) : 0;
            $days = $intv[$tier] ?? 9999;
            if (!$lc || ($now - $lc) >= $days * 86400) $due = 1;
          }
          $map[$pid] = ['t'=>$tier, 'd'=>$due];
        }
      } catch (Exception $e) {}
      jout(['ok'=>true, 'map'=>$map]);
    }
    if ($action === 'ob_track_set_prod') {
      $pid = trim((string)($d['product_id'] ?? ''));
      $tier = strtoupper(trim($d['tier'] ?? ''));
      if ($pid === '') fail('Нет товара');
      if (!in_array($tier, ['A','B','C','N'], true)) fail('A/B/C/N');
      $iid = ''; $title = '';
      try {
        $qy = db()->prepare("SELECT d.source_url, p.name FROM ds_products d LEFT JOIN products p ON p.id=d.product_id WHERE d.product_id=? AND d.source_url LIKE '%1688.com/offer/%' ORDER BY d.id DESC LIMIT 1");
        $qy->execute([$pid]);
        $r = $qy->fetch();
        if ($r && preg_match('/offer\/(\d+)/', (string)$r['source_url'], $m)) { $iid = $m[1]; $title = (string)($r['name'] ?? ''); }
      } catch (Exception $e) {}
      if ($iid === '') fail('Товар не связан с 1688');
      if ($tier === 'N') { try { db()->prepare("DELETE FROM ob_track WHERE num_iid=?")->execute([$iid]); } catch (Exception $e) {} }
      else { try { db()->prepare("INSERT INTO ob_track (num_iid,tier,title,base_price,last_price,last_checked) VALUES (?,?,?,NULL,NULL,NULL) ON DUPLICATE KEY UPDATE tier=VALUES(tier)")->execute([$iid, $tier, mb_substr($title, 0, 250)]); } catch (Exception $e) {} }
      jout(['ok'=>true, 'tier'=>$tier, 'num_iid'=>$iid, 'product_id'=>$pid]);
    }
    if ($action === 'ob_track_candidates') {
      $q = trim($d['q'] ?? '');
      $rows = [];
      try {
        $tracked = [];
        foreach (db()->query("SELECT num_iid FROM ob_track")->fetchAll() as $t) $tracked[$t['num_iid']] = 1;
        foreach (db()->query("SELECT d.source_url, d.source_price_cny, p.name FROM ds_products d LEFT JOIN products p ON p.id=d.product_id WHERE d.source_url LIKE '%1688.com/offer/%' ORDER BY d.id DESC LIMIT 1000")->fetchAll() as $r) {
          if (!preg_match('/offer\/(\d+)/', (string)$r['source_url'], $m)) continue;
          $iid = $m[1];
          if (isset($tracked[$iid]) || isset($rows[$iid])) continue;
          $nm = (string)($r['name'] ?? '');
          if ($q !== '' && mb_stripos($nm, $q) === false && strpos($iid, $q) === false) continue;
          $rows[$iid] = ['num_iid'=>$iid, 'title'=>$nm, 'price_cny'=>$r['source_price_cny']];
          if (count($rows) >= 200) break;
        }
      } catch (Exception $e) {}
      jout(['ok'=>true, 'items'=>array_values($rows)]);
    }
    if ($action === 'ob_track_set_cat') {
      $cat = trim($d['cat'] ?? '');
      $tier = strtoupper(trim($d['tier'] ?? ''));
      if ($cat === '') fail('Категория не указана');
      if (!in_array($tier, ['A','B','C','N'], true)) fail('Категория A/B/C/N');
      $iids = [];
      try {
        $qy = db()->prepare("SELECT d.source_url FROM ds_products d JOIN products p ON p.id=d.product_id WHERE d.source_url LIKE '%1688.com/offer/%' AND COALESCE(NULLIF(p.cat,''),'Без категории')=?");
        $qy->execute([$cat]);
        foreach ($qy->fetchAll() as $r) { if (preg_match('/offer\/(\d+)/', (string)$r['source_url'], $m)) $iids[$m[1]] = 1; }
      } catch (Exception $e) {}
      $iids = array_keys($iids);
      $n = 0;
      if ($tier === 'N') {
        foreach ($iids as $iid) { try { db()->prepare("DELETE FROM ob_track WHERE num_iid=?")->execute([$iid]); $n++; } catch (Exception $e) {} }
      } else {
        foreach ($iids as $iid) { try { db()->prepare("INSERT INTO ob_track (num_iid,tier,base_price,last_price,last_checked) VALUES (?,?,NULL,NULL,NULL) ON DUPLICATE KEY UPDATE tier=VALUES(tier)")->execute([$iid, $tier]); $n++; } catch (Exception $e) {} }
      }
      jout(['ok'=>true, 'affected'=>$n, 'tier'=>$tier]);
    }
    // ob_track_list — все заведённые 1688 товары; категория по умолчанию «без» (N)
    $q = trim($d['q'] ?? '');
    $catf = trim($d['cat'] ?? '');
    $trk = [];
    try { foreach (db()->query("SELECT num_iid,tier,base_price,last_price,UNIX_TIMESTAMP(last_checked)*1000 lc FROM ob_track")->fetchAll() as $t) $trk[$t['num_iid']] = $t; } catch (Exception $e) {}
    $cnt = ['A'=>0,'B'=>0,'C'=>0]; foreach ($trk as $t) if (isset($cnt[$t['tier']])) $cnt[$t['tier']]++;
    // список категорий с количеством
    $cats = [];
    try {
      foreach (db()->query("SELECT COALESCE(NULLIF(p.cat,''),'Без категории') cat, COUNT(DISTINCT d.source_url) c FROM ds_products d JOIN products p ON p.id=d.product_id WHERE d.source_url LIKE '%1688.com/offer/%' GROUP BY cat ORDER BY c DESC LIMIT 80")->fetchAll() as $cc) {
        $cats[] = ['name'=>(string)$cc['cat'], 'count'=>(int)$cc['c']];
      }
    } catch (Exception $e) {}
    $rows = []; $seen = []; $totImp = 0;
    try {
      $totImp = (int)db()->query("SELECT COUNT(DISTINCT source_url) FROM ds_products WHERE source_url LIKE '%1688.com/offer/%'")->fetchColumn();
      foreach (db()->query("SELECT d.source_url, d.source_price_cny, p.name, p.img, COALESCE(NULLIF(p.cat,''),'Без категории') cat FROM ds_products d LEFT JOIN products p ON p.id=d.product_id WHERE d.source_url LIKE '%1688.com/offer/%' ORDER BY d.id DESC LIMIT 5000")->fetchAll() as $r) {
        if (!preg_match('/offer\/(\d+)/', (string)$r['source_url'], $m)) continue;
        $iid = $m[1];
        if (isset($seen[$iid])) continue; $seen[$iid] = 1;
        $rcat = (string)($r['cat'] ?? '');
        if ($catf !== '' && $rcat !== $catf) continue;
        $nm = (string)($r['name'] ?? '');
        if ($q !== '' && mb_stripos($nm, $q) === false && strpos($iid, $q) === false) continue;
        $t = $trk[$iid] ?? null;
        $rows[] = ['num_iid'=>$iid, 'title'=>$nm, 'img'=>($r['img'] ?? ''), 'cat'=>$rcat, 'price_cny'=>$r['source_price_cny'],
                   'tier'=>$t ? $t['tier'] : 'N',
                   'base_price'=>$t ? $t['base_price'] : null,
                   'last_price'=>$t ? $t['last_price'] : null,
                   'last_checked'=>($t && $t['lc']) ? (int)$t['lc'] : null];
        if (count($rows) >= 300) break;
      }
    } catch (Exception $e) {}
    $cnt['N'] = max(0, $totImp - ($cnt['A'] + $cnt['B'] + $cnt['C']));
    jout(['ok'=>true, 'items'=>$rows, 'counts'=>$cnt, 'cats'=>$cats, 'total'=>$totImp, 'shown'=>count($rows), 'intervals'=>$intv]);
  }

  // ===== QR-КАМПАНИИ: метки рекламы и учёт переходов =====
  case 'mkt_hit': case 'mkt_create': case 'mkt_list': case 'mkt_del': {
    itc_mkt_promo_ensure();
    try {
      db()->query("CREATE TABLE IF NOT EXISTS mkt_campaign (tag VARCHAR(24) PRIMARY KEY, name VARCHAR(160), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) DEFAULT CHARSET=utf8mb4");
      db()->query("CREATE TABLE IF NOT EXISTS mkt_hit (id INT AUTO_INCREMENT PRIMARY KEY, tag VARCHAR(24), d DATE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY k_tag (tag)) DEFAULT CHARSET=utf8mb4");
    } catch (Exception $e) {}
    try { db()->query("ALTER TABLE customers ADD COLUMN src VARCHAR(24) NULL"); } catch (Exception $e) {}
    $d = body();

    if ($action === 'mkt_hit') {
      // ПУБЛИЧНЫЙ вызов — посетитель по QR не залогинен
      $tag = preg_replace('/[^a-zA-Z0-9_]/', '', substr(trim($_GET['tag'] ?? ($d['tag'] ?? '')), 0, 24));
      if ($tag !== '') {
        try { $ex = db()->prepare("SELECT 1 FROM mkt_campaign WHERE tag=?"); $ex->execute([$tag]);
          if ($ex->fetchColumn()) db()->prepare("INSERT INTO mkt_hit (tag,d) VALUES (?,CURDATE())")->execute([$tag]); } catch (Exception $e) {}
      }
      jout(['ok'=>true]);
    }

    $s = authUser('itc'); // остальное — только сотрудники

    if ($action === 'mkt_create') {
      $name = trim($d['name'] ?? ''); if ($name === '') fail('Введите название кампании');
      $tag = 'q'.substr(bin2hex(random_bytes(5)), 0, 7);
      try { db()->prepare("INSERT INTO mkt_campaign (tag,name) VALUES (?,?)")->execute([$tag, mb_substr($name,0,160)]); }
      catch (Exception $e) { fail('Не удалось создать кампанию'); }
      jout(['ok'=>true, 'tag'=>$tag, 'name'=>$name]);
    }
    if ($action === 'mkt_del') {
      $tag = preg_replace('/[^a-zA-Z0-9_]/', '', ($d['tag'] ?? ''));
      if ($tag !== '') { try { db()->prepare("DELETE FROM mkt_hit WHERE tag=?")->execute([$tag]); db()->prepare("DELETE FROM mkt_campaign WHERE tag=?")->execute([$tag]); } catch (Exception $e) {} }
      jout(['ok'=>true]);
    }
    // mkt_list
    $rows = [];
    try {
      $cs = db()->query("SELECT tag,name,UNIX_TIMESTAMP(created_at)*1000 ts FROM mkt_campaign ORDER BY created_at DESC")->fetchAll();
      $prBy=[]; $prAll=[]; $prById=[];
      try{ foreach(db()->query("SELECT id,title,ends_at,(ends_at > NOW()) active FROM promos WHERE status<>'deleted' ORDER BY created_at DESC LIMIT 200")->fetchAll() as $pp){
        $one=['id'=>$pp['id'],'title'=>$pp['title'],'active'=>(int)$pp['active']];
        $prAll[]=$one; $prById[$pp['id']]=$one;
      } }catch(Exception $e){}
      /* Акцию для кода берём из самой кампании. Одна и та же акция может стоять
         у скольких угодно кодов — это и нужно для разных регионов. */
      try{ foreach(db()->query("SELECT tag,promo_id FROM mkt_campaign WHERE promo_id IS NOT NULL AND promo_id<>''")->fetchAll() as $mm){
        if(isset($prById[$mm['promo_id']])) $prBy[$mm['tag']]=$prById[$mm['promo_id']];
      } }catch(Exception $e){}
      $tot = []; foreach (db()->query("SELECT tag,COUNT(*) c FROM mkt_hit GROUP BY tag")->fetchAll() as $r) $tot[$r['tag']] = (int)$r['c'];
      $tod = []; foreach (db()->query("SELECT tag,COUNT(*) c FROM mkt_hit WHERE d=CURDATE() GROUP BY tag")->fetchAll() as $r) $tod[$r['tag']] = (int)$r['c'];
      $reg = []; $regd = [];
      try { foreach (db()->query("SELECT src, COUNT(*) c, SUM(CASE WHEN name<>'' THEN 1 ELSE 0 END) dc FROM customers WHERE src IS NOT NULL AND src<>'' GROUP BY src")->fetchAll() as $r) { $reg[$r['src']] = (int)$r['c']; $regd[$r['src']] = (int)$r['dc']; } } catch (Exception $e) {}
      /* Привязанную акцию НАДО положить в ответ. Раньше она вычислялась выше в
         отдельный массив, а здесь список собирался заново — и акция терялась.
         Снаружи это выглядело так: подсказка «Акция привязана к QR» появлялась,
         а в списке по-прежнему стояло «без акции». */
      foreach ($cs as $c) $rows[] = ['tag'=>$c['tag'],'name'=>$c['name'],'ts'=>(int)$c['ts'],'hits'=>($tot[$c['tag']] ?? 0),'today'=>($tod[$c['tag']] ?? 0),'regs'=>($reg[$c['tag']] ?? 0),'regs_done'=>($regd[$c['tag']] ?? 0),'promo'=>($prBy[$c['tag']] ?? null)];
    } catch (Exception $e) {}
    jout(['ok'=>true, 'campaigns'=>$rows, 'promos'=>$prAll]);
  }

  case 'partners_admin': {
    $s = authUser('itc');
    $rows = [];
    try {
      try { $rows = db()->query('SELECT pt.id,pt.phone,pt.name,pt.code,pt.warehouse_id,pt.markup,pt.share,pt.status,pt.company,pt.inn,pt.kpp,pt.addr,pt.bank,pt.bik,pt.account,pt.corr,pt.contact,pt.email,UNIX_TIMESTAMP(pt.created_at)*1000 ts, w.code wh_code, w.name wh_name, w.city wh_city, w.kind wh_kind FROM partners pt LEFT JOIN warehouses w ON w.id=pt.warehouse_id ORDER BY pt.created_at DESC')->fetchAll(); }
      catch (Exception $e) { $rows = db()->query('SELECT pt.id,pt.phone,pt.name,pt.code,pt.warehouse_id,pt.markup,pt.share,pt.status,pt.company,pt.inn,pt.kpp,pt.addr,pt.bank,pt.bik,pt.account,pt.corr,pt.contact,pt.email,UNIX_TIMESTAMP(pt.created_at)*1000 ts, w.code wh_code, w.name wh_name, w.city wh_city FROM partners pt LEFT JOIN warehouses w ON w.id=pt.warehouse_id ORDER BY pt.created_at DESC')->fetchAll(); foreach ($rows as &$r0) { $r0['wh_kind']='hub'; } unset($r0); }
      foreach ($rows as &$r) { $r['ts']=(int)$r['ts']; $r['markup']=(float)$r['markup']; $r['share']=(float)$r['share']; $r['wh_kind']=$r['wh_kind'] ?? 'hub'; } unset($r);
    } catch (Exception $e) { $rows = []; }
    jout(['ok'=>true,'partners'=>$rows]);
  }

  // ---- ИТК: назначить склад/код/статус партнёру ----
  case 'partner_set': {
    $s = authUser('itc');
    require_staff($s, ['manager']);
    $d = body();
    $id = trim($d['id'] ?? '');
    if (!$id) fail('Не указан партнёр');
    $pt = db()->prepare('SELECT id,code,status FROM partners WHERE id=?'); $pt->execute([$id]); $p = $pt->fetch();
    if (!$p) fail('Партнёр не найден');
    $name = mb_substr(trim($d['name'] ?? ''), 0, 160);
    $wh = trim($d['warehouse_id'] ?? '');
    $status = $d['status'] ?? $p['status'];
    if (!in_array($status, ['pending','active','blocked'], true)) $status = $p['status'];
    $markup = isset($d['markup']) ? (float)$d['markup'] : null;
    $share = isset($d['share']) ? (float)$d['share'] : null;
    $code = trim($d['code'] ?? '');
    // при активации без кода — сгенерировать
    if ($status === 'active' && $code === '' && $p['code'] === '') {
      $code = strtoupper(substr(bin2hex(random_bytes(4)), 0, 6));
    } elseif ($code === '') {
      $code = $p['code'];
    }
    $sets = ['name=?','warehouse_id=?','status=?','code=?'];
    $vals = [$name,$wh,$status,$code];
    if ($markup !== null) { $sets[] = 'markup=?'; $vals[] = $markup; }
    if ($share !== null) { $sets[] = 'share=?'; $vals[] = $share; }
    $vals[] = $id;
    db()->prepare('UPDATE partners SET '.implode(',', $sets).' WHERE id=?')->execute($vals);
    itc_log_add($d['by'] ?? '', 'partner_set', 'partner', $id, $status.' · '.$code);
    jout(['ok'=>true,'code'=>$code,'status'=>$status]);
  }

  // ---- ИТК: завести партнёра вручную (босс/менеджер) ----
  case 'partner_create': {
    $s = authUser('itc');
    require_staff($s, ['manager']);
    $d = body();
    $phone = preg_replace('/[^0-9+]/', '', trim($d['phone'] ?? ''));
    $name = mb_substr(trim($d['name'] ?? ''), 0, 160);
    if (strlen($phone) < 5) fail('Укажите телефон партнёра');
    if ($name === '') fail('Укажите имя / название партнёра');
    if (itc_partner_by_phone($phone)) fail('Партнёр с таким телефоном уже есть в списке');
    $pid = gen('pt');
    db()->prepare('INSERT INTO partners (id,phone,name,status) VALUES (?,?,?,?)')->execute([$pid,(ph_norm($phone) ?: $phone),$name,'pending']);
    itc_log_add($d['by'] ?? '', 'partner_create', 'partner', $pid, $name.' · '.$phone);
    jout(['ok'=>true,'id'=>$pid]);
  }

  /* Разовая уборка: партнёры, оставшиеся от УЖЕ удалённых складов. Их
     warehouse_id указывает в пустоту — в списках они висят «мёртвыми» именами.
     Убираем только тех, у кого нет ни одной выплаты; остальных отвязываем. */
  case 'partners_cleanup': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','chief_accountant']);
    $removed = []; $kept = [];
    try {
      $q = db()->query("SELECT p.id, p.name, p.phone FROM partners p
                        WHERE p.warehouse_id IS NOT NULL AND p.warehouse_id<>''
                          AND NOT EXISTS (SELECT 1 FROM warehouses w WHERE w.id=p.warehouse_id)");
      foreach ($q->fetchAll() as $pr) {
        $hasMoney = false;
        try {
          $c = db()->prepare('SELECT COUNT(*) FROM partner_payouts WHERE partner_id=?');
          $c->execute([$pr['id']]);
          $hasMoney = ((int)$c->fetchColumn() > 0);
        } catch (Exception $e) { $hasMoney = true; }
        $who = trim(($pr['name'] ?? '').' '.($pr['phone'] ?? ''));
        if ($hasMoney) {
          try { db()->prepare('UPDATE partners SET warehouse_id=NULL WHERE id=?')->execute([$pr['id']]); $kept[] = $who; } catch (Exception $e) {}
        } else {
          try { db()->prepare('DELETE FROM partners WHERE id=?')->execute([$pr['id']]); $removed[] = $who; } catch (Exception $e) {}
        }
      }
    } catch (Exception $e) { fail('Не удалось проверить: '.$e->getMessage()); }
    try { itc_log_add(mb_substr(trim(body()['by'] ?? ''),0,120), 'partners_cleanup', 'partner', '', count($removed).' убрано'); } catch (Exception $e) {}
    jout(['ok'=>true,'removed'=>$removed,'kept'=>$kept]);
  }

  // ---- ИТК: удалить партнёра ----
  case 'partner_delete': {
    $s = authUser('itc');
    require_staff($s, ['manager']);
    $d = body();
    $id = trim($d['id'] ?? '');
    if (!$id) fail('Не указан партнёр');
    db()->prepare('DELETE FROM partners WHERE id=?')->execute([$id]);
    try { itc_log_add($d['by'] ?? '', 'partner_delete', 'partner', $id, ''); } catch (Exception $e) {}
    jout(['ok'=>true]);
  }

  // ---- ПАРТНЁР: сохранить свои реквизиты ----
  case 'partner_profile_save': {
    $s = authUser('partner');
    $pid = $s['supplier_id'] ?? '';
    $d = body(); $p = $d['profile'] ?? [];
    db()->prepare('UPDATE partners SET name=?,company=?,inn=?,kpp=?,addr=?,bank=?,bik=?,account=?,corr=?,contact=?,email=? WHERE id=?')
       ->execute([
         mb_substr(trim($p['name'] ?? ''),0,160), mb_substr(trim($p['company'] ?? ''),0,200),
         mb_substr(trim($p['inn'] ?? ''),0,20), mb_substr(trim($p['kpp'] ?? ''),0,20),
         mb_substr(trim($p['addr'] ?? ''),0,300), mb_substr(trim($p['bank'] ?? ''),0,200),
         mb_substr(trim($p['bik'] ?? ''),0,20), mb_substr(trim($p['account'] ?? ''),0,40),
         mb_substr(trim($p['corr'] ?? ''),0,40), mb_substr(trim($p['contact'] ?? ''),0,120),
         mb_substr(trim($p['email'] ?? ''),0,120), $pid]);
    jout(['ok'=>true]);
  }

  /* Фотография покупателя. Приходит картинкой в теле запроса, сжимается тем же
     путём, что и все фото товаров, и уходит в общее хранилище — в базе остаётся
     только ссылка. Пустая картинка означает «убрать фото». */
  case 'my_avatar_save': {
    $s = authUser();
    $d = body();
    try { db()->query("ALTER TABLE customers ADD COLUMN avatar VARCHAR(300) NULL"); } catch (Exception $e) {}
    $raw = (string)($d['avatar'] ?? '');
    if (trim($raw) === '') {
      try { db()->prepare('UPDATE customers SET avatar=NULL WHERE phone=?')->execute([$s['phone']]); } catch (Exception $e) { fail('Не удалось убрать фото'); }
      jout(['ok'=>true,'avatar'=>'']);
    }
    $url = itc_store_b64_image($raw);
    if ($url === '') fail('Не удалось обработать фото');
    try { db()->prepare('UPDATE customers SET avatar=? WHERE phone=?')->execute([$url, $s['phone']]); }
    catch (Exception $e) { fail('Не удалось сохранить фото'); }
    jout(['ok'=>true,'avatar'=>$url]);
  }

  case 'my_profile': {
    $s = authUser();
    $st = db()->prepare('SELECT name,email,city,street FROM customers WHERE phone = ?');
    $st->execute([$s['phone']]);
    $c = $st->fetch() ?: ['name'=>'','email'=>'','city'=>'','street'=>''];
    $zip = ''; $consent = 0;
    try { $z = db()->prepare('SELECT zip,consent_at FROM customers WHERE phone=?'); $z->execute([$s['phone']]); $zr=$z->fetch(); $zip=$zr['zip']??''; $consent=!empty($zr['consent_at'])?1:0; } catch (Exception $e) {}
    $whid = '';
    try { $wq = db()->prepare('SELECT warehouse_id FROM customers WHERE phone=?'); $wq->execute([$s['phone']]); $wr=$wq->fetch(); $whid=$wr['warehouse_id']??''; } catch (Exception $e) {}
    $avatar = '';
    try { db()->query("ALTER TABLE customers ADD COLUMN avatar VARCHAR(300) NULL"); } catch (Exception $e) {}
    try { $aq = db()->prepare('SELECT avatar FROM customers WHERE phone=?'); $aq->execute([$s['phone']]); $avatar = (string)$aq->fetchColumn(); } catch (Exception $e) {}
    jout(['ok' => true, 'name' => $c['name'], 'email' => $c['email'], 'city' => $c['city'], 'street' => $c['street'], 'zip' => $zip, 'warehouse_id' => $whid, 'consent' => $consent, 'phone' => $s['phone'], 'avatar' => $avatar, 'apps' => apps_of($s['phone'])]);
  }

  case 'my_profile_save': {
    $s = authUser();
    $d = body();
    $name = mb_substr(trim($d['name'] ?? ''), 0, 120);
    $city = mb_substr(trim($d['city'] ?? ''), 0, 120);
    $street = mb_substr(trim($d['street'] ?? ''), 0, 200);
    $zip = mb_substr(trim($d['zip'] ?? ''), 0, 20);
    $email = mb_substr(trim($d['email'] ?? ''), 0, 120);
    $wh = mb_substr(trim($d['warehouse_id'] ?? ''), 0, 64);
    $ok = false;
    try {
      db()->prepare('INSERT INTO customers (phone,name,email,city,street,zip,warehouse_id) VALUES (?,?,?,?,?,?,?)
                     ON DUPLICATE KEY UPDATE name=VALUES(name),email=VALUES(email),city=VALUES(city),street=VALUES(street),zip=VALUES(zip),warehouse_id=VALUES(warehouse_id)')
          ->execute([$s['phone'],$name,$email,$city,$street,$zip,$wh]);
      $ok = true;
    } catch (Exception $e) {
      // запасной путь без warehouse_id (колонка ещё не добавлена)
      try {
        db()->prepare('INSERT INTO customers (phone,name,email,city,street,zip) VALUES (?,?,?,?,?,?)
                       ON DUPLICATE KEY UPDATE name=VALUES(name),email=VALUES(email),city=VALUES(city),street=VALUES(street),zip=VALUES(zip)')
            ->execute([$s['phone'],$name,$email,$city,$street,$zip]);
        $ok = true;
      } catch (Exception $e2) {
        // запасной путь, если и колонки zip ещё нет
        try { db()->prepare('UPDATE customers SET name=?,city=?,street=?,email=? WHERE phone=?')->execute([$name,$city,$street,$email,$s['phone']]); $ok=true; } catch (Exception $e3) {}
      }
    }
    if (!$ok) fail('Не удалось сохранить. Выполните миграцию (customers.zip).');
    jout(['ok' => true]);
  }

  case 'my_orders': {
    $s = authUser('buyer');
    jout(['ok' => true, 'orders' => orders_for_phone($s['phone'])]);
  }

  /* ПРОВЕРКА ЗАКАЗОВ ПО ТЕЛЕФОНУ (24.08.2026). Открывать в браузере:
     ?action=orders_check&key=…&phone=+79787812901
     Показывает, в каком виде номер записан в заказах и в учётной записи —
     сразу видно, почему список у покупателя мог быть пустым. */
  case 'orders_check': {
    header('Content-Type: text/plain; charset=utf-8');
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) { echo "Нужен ключ\n"; exit; }
    /* ВНИМАНИЕ (24.08.2026): в веб-адресе «+» означает ПРОБЕЛ. Из-за этого
       первая версия проверки сравнивала « 79787812901» и давала ноль —
       и я чуть не принял это за доказательство несовпадения номеров.
       Поэтому приводим номер к единому виду САМИ и показываем оба варианта. */
    $raw = (string)($_GET['phone'] ?? '');
    $p    = ph_norm($raw);
    $tail = ph_tail($raw);
    echo "=== ПРОВЕРКА ЗАКАЗОВ ===\n";
    /* Кавычка » приклеивается к имени переменной — PHP ищет переменную с кавычкой в имени и не находит.
       Пишем в фигурных скобках, тогда граница имени понятна. */
    echo "Пришло из адреса: «{$raw}»\n";
    echo "Приведено к виду: «{$p}» (последние 10 цифр: {$tail})\n\n";
    $cmp = "RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(%F%,'+',''),'-',''),' ',''),'(',''),')',''), 10) = ?";

    $q = db()->prepare("SELECT phone,name FROM customers WHERE ".str_replace('%F%','phone',$cmp));
    $q->execute([$tail]);
    foreach ($q->fetchAll() as $c) echo "Покупатель: «".$c['phone']."» — ".$c['name']."\n";

    $q = db()->prepare("SELECT num,phone,total,paid,status,created_at FROM orders WHERE ".str_replace('%F%','phone',$cmp)." ORDER BY created_at DESC LIMIT 30");
    $q->execute([$tail]);
    $rows = $q->fetchAll();
    echo "\nЗаказов найдено по цифрам: ".count($rows)."\n";
    foreach ($rows as $r)
      echo "  ".$r['num']." · номер в заказе: «".$r['phone']."» · ".$r['total']." ₽ · ".($r['paid']?'ОПЛАЧЕН':'не оплачен')." · ".$r['status']." · ".$r['created_at']."\n";

    $q = db()->prepare("SELECT COUNT(*) FROM orders WHERE phone = ?");
    $q->execute([$p]);
    echo "\nТочным совпадением строки «{$p}» нашлось бы: ".(int)$q->fetchColumn()."\n";

    /* Под каким номером человек реально входил — это и есть то, по чему
       ему подбирались заказы. */
    echo "\n--- ВХОДЫ (сессии) ---\n";
    try {
      $q = db()->prepare("SELECT phone,role,staff_role FROM sessions WHERE ".ph_sql_eq('phone')." LIMIT 20");
      $q->execute([$tail]);
      $ss = $q->fetchAll();
      if (!$ss) echo "Действующих входов нет — человек вышел или срок истёк.\n";
      foreach ($ss as $x) echo "  номер во входе: «".$x['phone']."» · роль ".$x['role']."\n";
    } catch (Exception $e) { echo "не удалось прочитать: ".$e->getMessage()."\n"; }

    /* ГЛАЗАМИ ПОКУПАТЕЛЯ. Показываем ровно то, что сервер отдаёт ему в
       «Мои заказы», и что лежит в его корзине — не заходя под ним. */
    echo "\n--- ЧТО ВИДИТ ПОКУПАТЕЛЬ В «МОИХ ЗАКАЗАХ» ---\n";
    try {
      $mine = orders_for_phone($p);
      echo "Заказов отдаётся: ".count($mine)."\n";
      foreach ($mine as $o) {
        echo "  ".$o['num']." · ".(int)round($o['total'])." ₽ · "
           . ((int)$o['paid'] ? 'ОПЛАЧЕН' : 'не оплачен') . " · " . $o['status']
           . " · склад: " . ($o['wh_name'] ?: '—') . "\n";
        foreach (($o['items'] ?? []) as $it)
          echo "        ".$it['name']." × ".$it['qty']."\n";
      }
    } catch (Exception $e) { echo "ошибка: ".$e->getMessage()."\n"; }

    echo "\n--- ЧТО ЛЕЖИТ У НЕГО В КОРЗИНЕ ---\n";
    try {
      $q = db()->prepare("SELECT items FROM carts WHERE ".ph_sql_eq('phone'));
      $q->execute([$tail]);
      $j = $q->fetchColumn();
      $cart = $j ? json_decode($j, true) : [];
      if (!is_array($cart) || !$cart) echo "Корзина пуста.\n";
      else {
        echo "Позиций: ".count($cart)."\n";
        foreach ($cart as $c) {
          $nm = '';
          try {
            $qq = db()->prepare("SELECT name FROM products WHERE id=?");
            $qq->execute([$c['id'] ?? '']);
            $nm = (string)$qq->fetchColumn();
          } catch (Exception $e2) {}
          echo "  ".($nm ?: ($c['id'] ?? '?'))." × ".($c['qty'] ?? 1)
             . (!empty($c['color']) ? " · ".$c['color'] : "")."\n";
        }
      }
    } catch (Exception $e) { echo "ошибка: ".$e->getMessage()."\n"; }

    echo "\n--- СКРЫТЫЕ ЗАКАЗЫ ---\n";
    try {
      $q = db()->prepare("SELECT num,hidden FROM orders WHERE ".ph_sql_eq('phone')." AND hidden=1");
      $q->execute([$tail]);
      $hh = $q->fetchAll();
      echo "Скрыто покупателем: ".count($hh)."\n";
      foreach ($hh as $x) echo "  ".$x['num']."\n";
    } catch (Exception $e) { echo "столбца hidden нет\n"; }
    echo "=== КОНЕЦ ===\n";
    exit;
  }

  /* УБОРКА ПОСЛЕ ОШИБКИ С ПУСТЫМИ ЗАКАЗАМИ (24.08.2026).
     Из-за недостающих столбцов покупатель не видел свои заказы, жал
     «Оформить» снова и снова — и наплодил одинаковых неоплаченных.
     Плюс в корзине остались товары, уже попавшие в ОПЛАЧЕННЫЙ заказ.
     Команда убирает и то, и другое.
     СНАЧАЛА ПОКАЗЫВАЕТ, что сделает. Удаляет только с &go=1.
     ?action=orders_cleanup&key=…&phone=79787812901
     ?action=orders_cleanup&key=…&phone=79787812901&go=1  */
  case 'orders_cleanup': {
    header('Content-Type: text/plain; charset=utf-8');
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) { echo "Нужен ключ\n"; exit; }
    $raw  = (string)($_GET['phone'] ?? '');
    $tail = ph_tail($raw);
    $go   = ((string)($_GET['go'] ?? '') === '1');
    if (strlen($tail) < 10) { echo "Укажите телефон\n"; exit; }

    echo "=== УБОРКА ЗАКАЗОВ ===\n";
    echo "Телефон: {$raw}\n";
    echo $go ? "РЕЖИМ: УДАЛЯЕМ\n\n" : "РЕЖИМ: только показываю, ничего не трогаю\n\n";

    /* 1. ОДИНАКОВЫЕ НЕОПЛАЧЕННЫЕ. Считаем одинаковыми заказы с той же
       суммой. Оставляем САМЫЙ РАННИЙ — он первый и настоящий, остальные
       родились от повторных нажатий. Оплаченные не трогаем никогда. */
    $q = db()->prepare("SELECT id,num,total,created_at FROM orders
                        WHERE ".ph_sql_eq('phone')." AND paid=0
                        ORDER BY total, created_at");
    $q->execute([$tail]);
    $rows = $q->fetchAll();

    $keep = []; $kill = [];
    foreach ($rows as $r) {
      $k = (string)round((float)$r['total']);
      if (!isset($keep[$k])) { $keep[$k] = $r; } else { $kill[] = $r; }
    }

    echo "--- НЕОПЛАЧЕННЫЕ ЗАКАЗЫ ---\n";
    foreach ($keep as $k => $r)
      echo "  ОСТАВЛЯЕМ ".$r['num']." · ".(int)round($r['total'])." ₽ · ".$r['created_at']."\n";
    echo "  Лишних дубликатов: ".count($kill)."\n";
    foreach ($kill as $r)
      echo "     удалить ".$r['num']." · ".(int)round($r['total'])." ₽ · ".$r['created_at']."\n";

    /* 2. КОРЗИНА. Убираем то, что уже лежит в ОПЛАЧЕННОМ заказе. */
    $q = db()->prepare("SELECT i.product_id FROM order_items i
                        JOIN orders o ON o.id=i.order_id
                        WHERE ".ph_sql_eq('o.phone')." AND o.paid=1");
    $q->execute([$tail]);
    $paidIds = [];
    foreach ($q->fetchAll(PDO::FETCH_COLUMN) as $pid) $paidIds[(string)$pid] = true;

    $q = db()->prepare("SELECT items FROM carts WHERE ".ph_sql_eq('phone'));
    $q->execute([$tail]);
    $j = $q->fetchColumn();
    $cart = $j ? json_decode($j, true) : [];
    if (!is_array($cart)) $cart = [];
    $left = []; $drop = [];
    foreach ($cart as $c) {
      if (isset($paidIds[(string)($c['id'] ?? '')])) $drop[] = $c; else $left[] = $c;
    }

    echo "\n--- КОРЗИНА ---\n";
    echo "  Позиций сейчас: ".count($cart).", уже оплачено: ".count($drop)."\n";
    foreach ($drop as $c) {
      $nm=''; try { $qq=db()->prepare("SELECT name FROM products WHERE id=?"); $qq->execute([$c['id']]); $nm=(string)$qq->fetchColumn(); } catch (Exception $e) {}
      echo "     убрать: ".($nm ?: $c['id'])."\n";
    }

    if (!$go) {
      echo "\nНичего не тронуто. Чтобы выполнить — добавьте в конец адреса &go=1\n";
      echo "=== КОНЕЦ ===\n"; exit;
    }

    $done = 0;
    foreach ($kill as $r) {
      try {
        db()->prepare('DELETE FROM order_items WHERE order_id=?')->execute([$r['id']]);
        db()->prepare('DELETE FROM orders WHERE id=? AND paid=0')->execute([$r['id']]);
        $done++;
      } catch (Exception $e) { echo "не удалось удалить ".$r['num'].": ".$e->getMessage()."\n"; }
    }
    if ($drop) {
      try {
        db()->prepare('INSERT INTO carts (phone,items) VALUES (?,?) ON DUPLICATE KEY UPDATE items=VALUES(items)')
            ->execute([ph_norm($raw), json_encode($left, JSON_UNESCAPED_UNICODE)]);
      } catch (Exception $e) { echo "корзина не сохранилась: ".$e->getMessage()."\n"; }
    }
    echo "\nУдалено заказов: $done · из корзины убрано: ".count($drop)."\n";
    echo "=== ГОТОВО ===\n";
    exit;
  }

  case 'order_hide': {
    $s = authUser('buyer');
    $d = body();
    $id = trim($d['id'] ?? '');
    if ($id === '') fail('Не указан заказ');
    try {
      db()->prepare('UPDATE orders SET hidden=1 WHERE id=? AND '.ph_sql_eq('phone').' AND paid=0')->execute([$id, ph_tail10($s['phone'])]);
    } catch (Exception $e) { fail('Выполните миграцию: orders.hidden'); }
    jout(['ok' => true]);
  }

  // ---- заказы поставщика (БЕЗ данных покупателя) ----
  case 'supplier_orders': {
    $s = authUser('supplier');
    $sid = $s['supplier_id'];
    $st = db()->prepare(
      'SELECT DISTINCT o.id,o.num,o.status,o.warehouse_id, w.code AS wh_code, w.name AS wh_name, w.country AS wh_country, UNIX_TIMESTAMP(o.created_at)*1000 AS ts, UNIX_TIMESTAMP(o.wh_received_at)*1000 AS wh_rts,
              o.box_checked, o.box_ok, o.box_decl_m3, o.box_act_m3, o.box_dims, o.box_extra_rub, o.box_deduct, o.wh_damage, o.wh_damage_note
         FROM orders o JOIN order_items i ON i.order_id = o.id
         LEFT JOIN warehouses w ON w.id = o.warehouse_id
        WHERE i.supplier_id = ? AND o.paid = 1 ORDER BY o.created_at DESC');
    $st->execute([$sid]);
    $orders = $st->fetchAll();
    $iq = db()->prepare('SELECT name,qty,price FROM order_items WHERE order_id = ? AND supplier_id = ?');
    foreach ($orders as &$o) {
      $iq->execute([$o['id'], $sid]);
      $items = $iq->fetchAll();
      $sum = 0; foreach ($items as $it) $sum += $it['price'] * $it['qty'];
      $o['items'] = $items; $o['sum'] = $sum;
      $o['ts'] = (int)$o['ts'];
      $o['places'] = order_places_ensure($o['id']);
      $o['box_list'] = order_box_list($o['id']);
      $__lk = order_lbl_keys([$o['id']]); $o['lbl_key'] = $__lk[$o['id']] ?? '';   // №284
      $o['wh_received'] = !empty($o['wh_rts']) ? 1 : 0;
      $o['box_checked'] = (int)$o['box_checked']; $o['box_ok'] = (int)$o['box_ok'];
      $o['box_decl_m3'] = (float)$o['box_decl_m3']; $o['box_act_m3'] = (float)$o['box_act_m3']; $o['box_extra_rub'] = (int)round($o['box_extra_rub']); $o['box_deduct'] = (int)$o['box_deduct']; $o['wh_damage'] = (int)$o['wh_damage'];
      $o['accepted'] = 0; $o['accepted_at'] = 0;
      try {
        $aq = db()->prepare('SELECT UNIX_TIMESTAMP(accepted_at)*1000 t FROM order_accept WHERE order_id=? AND supplier_id=?');
        $aq->execute([$o['id'], $sid]); $ar = $aq->fetch();
        if ($ar) { $o['accepted'] = 1; $o['accepted_at'] = (int)$ar['t']; }
      } catch (Exception $e) {}
    }
    jout(['ok' => true, 'orders' => $orders]);
  }

  // ---- поставщик подтверждает приём заказа ----
  // ---- ПОДТВЕРЖДЕНИЕ СКЛАДОМ: товар выкуплен и доехал ----
  case 'wh_accept': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager']);
    $d = body();
    $oid = trim($d['order_id'] ?? '');
    $sid = trim($d['supplier_id'] ?? '');
    if (!$oid) fail('Не указан заказ');
    /* ПРИЁМКА ОДНОЙ ПОЗИЦИИ (обновление №267): товары с 1688 приходят порознь. */
    $itemId = trim($d['item_id'] ?? '');
    if ($itemId !== '') {
      $iq = db()->prepare('SELECT order_id, product_id, supplier_id FROM order_items WHERE id=? AND order_id=?');
      $iq->execute([$itemId, $oid]);
      $itm = $iq->fetch();
      if (!$itm) fail('Позиция не найдена');
      $pq = db()->prepare("SELECT COUNT(*) c, SUM(CASE WHEN status IN ('ordered','received') THEN 1 ELSE 0 END) b FROM ds_procurement WHERE order_id=? AND product_id=?");
      $pq->execute([$oid, $itm['product_id']]);
      $pr = $pq->fetch() ?: ['c'=>0,'b'=>0];
      if ((int)$pr['c'] === 0) fail('По этой позиции нет выкупа');
      if ((int)$pr['b'] < (int)$pr['c']) fail('Сначала выкуп: эта позиция ещё не выкуплена');
      db()->prepare("UPDATE ds_procurement SET status='received', received_at=NOW() WHERE order_id=? AND product_id=? AND status='ordered'")
        ->execute([$oid, $itm['product_id']]);
      $isid = (string)$itm['supplier_id'];
      /* Все позиции заказа от этого поставщика приняты — отмечаем заказ целиком. */
      $lq = db()->prepare("SELECT COUNT(*) FROM ds_procurement pc JOIN order_items i ON i.order_id=pc.order_id AND i.product_id=pc.product_id
                            WHERE pc.order_id=? AND i.supplier_id=? AND pc.status<>'received'");
      $lq->execute([$oid, $isid]);
      $left = (int)$lq->fetchColumn();
      /* У этого поставщика в заказе могут быть и товары без выкупа — их принимают отдельной карточкой. */
      $nq = db()->prepare("SELECT COUNT(*) FROM order_items i WHERE i.order_id=? AND i.supplier_id=?
                             AND NOT EXISTS (SELECT 1 FROM ds_procurement x WHERE x.order_id=i.order_id AND x.product_id=i.product_id)");
      $nq->execute([$oid, $isid]);
      $nonDs = (int)$nq->fetchColumn();
      if ($left === 0 && $nonDs === 0) {
        try { db()->prepare('INSERT IGNORE INTO order_accept (order_id,supplier_id) VALUES (?,?)')->execute([$oid, $isid]); } catch (Exception $e) {}
      }
      itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'wh_accept', 'order', $oid, 'item '.$itemId);
      itc_order_mark_at_wh($oid);   // №309
      jout(['ok' => true, 'left' => $left]);
    }
    $chk = db()->prepare("SELECT COUNT(*) c, SUM(CASE WHEN status IN ('ordered','received') THEN 1 ELSE 0 END) b FROM ds_procurement WHERE order_id=?");
    $chk->execute([$oid]);
    $cr = $chk->fetch() ?: ['c'=>0,'b'=>0];
    if ((int)$cr['c'] > 0 && (int)$cr['b'] < (int)$cr['c']) fail('Сначала выкуп: по заказу выкуплены не все позиции');
    try { db()->prepare('INSERT IGNORE INTO order_accept (order_id,supplier_id) VALUES (?,?)')->execute([$oid, $sid]); }
    catch (Exception $e) { fail('Не удалось подтвердить (order_accept)'); }
    /* СВЯЗКА С ВЫКУПОМ (25.09.2026). Раньше подтверждение склада писало только
       «заказ принят», а строки выкупа оставались в «выкуплено, ждём на складе»
       и висели там вечно: перевести их могла лишь отдельная кнопка в другом
       разделе, которую никто не нажимал. Теперь закрываем их здесь же. */
    try {
      if ($sid !== '') {
        db()->prepare("UPDATE ds_procurement SET status='received', received_at=NOW()
                        WHERE order_id=? AND status='ordered'
                          AND product_id IN (SELECT product_id FROM order_items
                                              WHERE order_id=? AND supplier_id=?)")
          ->execute([$oid, $oid, $sid]);
      } else {
        db()->prepare("UPDATE ds_procurement SET status='received', received_at=NOW()
                        WHERE order_id=? AND status='ordered'")->execute([$oid]);
      }
    } catch (Throwable $e) { error_log('wh_accept -> procurement: '.$e->getMessage()); }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'wh_accept', 'order', $oid, $sid);
    itc_order_mark_at_wh($oid);   // №309
    jout(['ok' => true]);
  }

  case 'supplier_accept': {
    $s = authUser('supplier');
    $sid = $s['supplier_id'];
    $d = body();
    $oid = trim($d['order_id'] ?? '');
    if (!$oid) fail('Не указан заказ');
    $ck = db()->prepare('SELECT 1 FROM order_items WHERE order_id=? AND supplier_id=? LIMIT 1');
    $ck->execute([$oid, $sid]);
    if (!$ck->fetch()) fail('Этот заказ не относится к вам');
    try {
      db()->prepare('INSERT IGNORE INTO order_accept (order_id,supplier_id) VALUES (?,?)')->execute([$oid, $sid]);
    } catch (Exception $e) { fail('Сначала выполните миграцию (order_accept)'); }
    jout(['ok' => true]);
  }

  // ---- ОПЕРАТОР СКЛАДА: что едет / на складе / отгружено ----
  case 'warehouse_state': {
    $s = authUser();
    $role = $s['role'] ?? ''; $sr = $s['staff_role'] ?? ''; $wh = '';
    $prevWh = $_GET['wh'] ?? '';
    if ($prevWh !== '' && $role === 'itc') { $wh = $prevWh; }   // предпросмотр боссом/сотрудником ИТК
    elseif ($role === 'partner') { try { $pq=db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']??'']); $wh=$pq->fetchColumn()?:''; } catch (Exception $e) {} }
    elseif ($role === 'itc' && $sr === 'warehouse') { $wh = $s['supplier_id'] ?? ''; }
    else fail('Доступ только для оператора склада или партнёра', 403);
    if (!$wh) fail('Склад не определён');
    $wq = db()->prepare('SELECT id,code,name,city,country FROM warehouses WHERE id=?'); $wq->execute([$wh]); $whInfo = $wq->fetch() ?: null;
    $incoming = []; $atwh = []; $shipped = [];
    try {
      $q = db()->prepare("SELECT id,num,status,addr_city,addr_name,warehouse_id,dest_warehouse_id,box_checked,box_ok,box_extra_rub,box_decl_m3,box_act_m3,
                                 wh_weight,wh_cell,wh_damage,wh_damage_note,wh_partial,(wh_photo IS NOT NULL AND wh_photo<>'') has_photo,
                                 UNIX_TIMESTAMP(created_at)*1000 ts,
                                 UNIX_TIMESTAMP(wh_received_at)*1000 rts,
                                 UNIX_TIMESTAMP(wh_shipped_at)*1000 sts,
                                 UNIX_TIMESTAMP(dest_received_at)*1000 drts,
                                 UNIX_TIMESTAMP(picked_up_at)*1000 pts
                            FROM orders WHERE (warehouse_id=? OR dest_warehouse_id=?) AND paid=1 ORDER BY created_at DESC LIMIT 300");
      $q->execute([$wh, $wh]);
      foreach ($q->fetchAll() as $o) {
        $iq = db()->prepare('SELECT SUM(qty) u FROM order_items WHERE order_id=?'); $iq->execute([$o['id']]); $u = (int)($iq->fetchColumn() ?: 0);
        $asDest = (!empty($o['dest_warehouse_id']) && $o['dest_warehouse_id'] === $wh && $o['warehouse_id'] !== $wh);
        /* №277: пункт выдачи заказа — вместо города, который вписал покупатель */
        $pvzName = '';
        try { $pn = db()->prepare("SELECT name FROM warehouses WHERE id=? AND kind='pvz'"); $pn->execute([$o['warehouse_id']]); $pvzName = (string)($pn->fetchColumn() ?: ''); } catch (Exception $e) {}
        $row = ['id'=>$o['id'],'num'=>$o['num'],'status'=>$o['status'],'city'=>$o['addr_city'],'pvz'=>$pvzName,'name'=>$o['addr_name'],'units'=>$u,
                'box_checked'=>(int)$o['box_checked'],'box_ok'=>(int)$o['box_ok'],'box_extra'=>(int)round($o['box_extra_rub']),'decl_m3'=>(float)$o['box_decl_m3'],'act_m3'=>(float)$o['box_act_m3'],
                'weight'=>(float)$o['wh_weight'],'cell'=>$o['wh_cell'],'damage'=>(int)$o['wh_damage'],'damage_note'=>$o['wh_damage_note'],'partial'=>(int)$o['wh_partial'],'has_photo'=>(int)$o['has_photo'],
                'ts'=>(int)$o['ts'],'rts'=>$o['rts']?(int)$o['rts']:0,'sts'=>$o['sts']?(int)$o['sts']:0,'drts'=>$o['drts']?(int)$o['drts']:0,'pts'=>$o['pts']?(int)$o['pts']:0,'is_dest'=>$asDest?1:0];
        if ($asDest) {
          if ($o['pts']) { $row['done']=1; $shipped[] = $row; }
          elseif ($o['drts']) $atwh[] = $row;      // принят на складе РФ → готов к выдаче
          elseif ($o['sts']) $incoming[] = $row;   // отгружен из Китая, едет к нам → ждём приёмки
          // ещё не отгружен из Китая — на складе-получателе не показываем
        } else {
          if ($o['pts']) { $row['done']=1; $shipped[] = $row; }
          elseif ($o['sts']) $shipped[] = $row;
          elseif ($o['rts']) $atwh[] = $row;
          else $incoming[] = $row;
        }
      }
    } catch (Exception $e) {}
    // число мест и прогресс приёмки (поштучный трек); устойчиво к отсутствию миграции
    foreach ([&$incoming, &$atwh] as &$__lst) {
      foreach ($__lst as &$__r) {
        try {
          $pq=db()->prepare('SELECT places FROM orders WHERE id=?'); $pq->execute([$__r['id']]); $pl=(int)$pq->fetchColumn();
          if ($pl>1) { $__r['places']=$pl;
            $c1=db()->prepare('SELECT COUNT(*) FROM order_boxes WHERE order_id=? AND origin_at IS NOT NULL'); $c1->execute([$__r['id']]); $__r['obr']=(int)$c1->fetchColumn();
            $c2=db()->prepare('SELECT COUNT(*) FROM order_boxes WHERE order_id=? AND dest_at IS NOT NULL'); $c2->execute([$__r['id']]); $__r['dbr']=(int)$c2->fetchColumn();
            try { $isD=(!empty($__r['is_dest'])); $cw=db()->prepare('SELECT COALESCE(SUM(weight),0) w, COALESCE(SUM(volume),0) v FROM order_boxes WHERE order_id=? AND '.($isD?'dest_at':'origin_at').' IS NOT NULL'); $cw->execute([$__r['id']]); $rw=$cw->fetch(); $__r['rec_w']=round((float)$rw['w'],1); $__r['rec_v']=round((float)$rw['v'],3); } catch (Exception $e) {}
          }
        } catch (Exception $e) {}
      }
      unset($__r);
    }
    unset($__lst);
    // склады-получатели для выбора при отгрузке (все активные, кроме текущего)
    $dest_whs = [];
    try { $dwq = db()->prepare("SELECT id,code,name,city,country FROM warehouses WHERE active=1 AND id<>? ORDER BY (country='RU') DESC, name"); $dwq->execute([$wh]);
          foreach ($dwq->fetchAll() as $dw) $dest_whs[] = ['id'=>$dw['id'],'code'=>$dw['code'],'name'=>$dw['name'],'city'=>$dw['city'],'country'=>$dw['country']]; } catch (Exception $e) {}
    // статистика оператора по складу
    $stats = ['received'=>count($atwh)+count($shipped),'incoming'=>count($incoming),'shipped'=>0,'handed'=>0,'damaged'=>0,'today'=>0];
    try {
      $sst = db()->prepare("SELECT
          SUM(wh_shipped_at IS NOT NULL) shipped,
          SUM(picked_up_at IS NOT NULL) handed,
          SUM(wh_damage=1) damaged,
          SUM(DATE(wh_received_at)=CURDATE()) today
        FROM orders WHERE warehouse_id=?");
      $sst->execute([$wh]); $sr2 = $sst->fetch();
      $stats['shipped'] = (int)($sr2['shipped'] ?? 0);
      $stats['handed']  = (int)($sr2['handed'] ?? 0);
      $stats['damaged'] = (int)($sr2['damaged'] ?? 0);
      $stats['today']   = (int)($sr2['today'] ?? 0);
    } catch (Exception $e) {}
    jout(['ok'=>true,'warehouse'=>$whInfo,'incoming'=>$incoming,'atwh'=>$atwh,'shipped'=>array_slice($shipped,0,40),'stats'=>$stats,'dest_warehouses'=>$dest_whs]);
  }

  // ---- СКЛАД/ПАРТНЁР: контейнеры (консолидация + массовая отгрузка) ----
  case 'container_list': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??''; $wh='';
    if ($role==='partner') { try { $pq=db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $wh=$pq->fetchColumn()?:''; } catch (Exception $e) {} }
    elseif ($role==='itc' && $sr==='warehouse') { $wh=$s['supplier_id']??''; }
    else fail('Недостаточно прав',403);
    $cont_vol = max(1,(float)get_settings()['cont_vol']);
    $list = [];
    try {
      $cq = db()->prepare("SELECT id,num,status,note,UNIX_TIMESTAMP(created_at)*1000 ts,UNIX_TIMESTAMP(dispatched_at)*1000 dts FROM containers WHERE warehouse_id=? AND status='open' ORDER BY created_at DESC");
      $cq->execute([$wh]);
      foreach ($cq->fetchAll() as $c) {
        $oq = db()->prepare("SELECT num,addr_city,box_act_m3,box_decl_m3,wh_weight FROM orders WHERE container_id=?");
        $oq->execute([$c['id']]); $ords=[]; $vol=0; $wt=0;
        foreach ($oq->fetchAll() as $o) { $m=(float)$o['box_act_m3']?:(float)$o['box_decl_m3']; $vol+=$m; $wt+=(float)$o['wh_weight']; $ords[]=['num'=>$o['num'],'city'=>$o['addr_city'],'m3'=>round($m,3),'weight'=>(float)$o['wh_weight']]; }
        /* №308: складские партии ИТК в этом контейнере */
        $stk = []; try { stock_cols(); $sq = db()->prepare("SELECT b.id,b.qty,COALESCE(NULLIF((SELECT p.name FROM products p WHERE p.id=b.product_id),''),b.name) name FROM stock_batches b WHERE b.container_id=?"); $sq->execute([$c['id']]);
          foreach ($sq->fetchAll() as $sb) $stk[] = ['id'=>(int)$sb['id'],'num'=>str_pad((string)$sb['id'],4,'0',STR_PAD_LEFT),'qty'=>(int)$sb['qty'],'name'=>$sb['name']]; } catch (Exception $e) {}
        $list[] = ['stock'=>$stk,'id'=>$c['id'],'num'=>$c['num'],'status'=>$c['status'],'note'=>$c['note'],'ts'=>(int)$c['ts'],'orders'=>$ords,'count'=>count($ords),'vol'=>round($vol,3),'weight'=>round($wt,1),'fill'=>min(100,round($vol/$cont_vol*100))];
      }
    } catch (Exception $e) {}
    // готовые к загрузке (на складе, не в контейнере, не отгружены)
    $avail = [];
    try {
      $aq = db()->prepare("SELECT num,addr_city,box_act_m3,box_decl_m3,wh_weight FROM orders WHERE warehouse_id=? AND paid=1 AND wh_received_at IS NOT NULL AND wh_shipped_at IS NULL AND (container_id='' OR container_id IS NULL) ORDER BY wh_received_at DESC LIMIT 200");
      $aq->execute([$wh]);
      foreach ($aq->fetchAll() as $o) { $m=(float)$o['box_act_m3']?:(float)$o['box_decl_m3']; $avail[]=['num'=>$o['num'],'city'=>$o['addr_city'],'m3'=>round($m,3),'weight'=>(float)$o['wh_weight']]; }
    } catch (Exception $e) {}
    // недавно отгруженные контейнеры
    $recent = [];
    try {
      $rq = db()->prepare("SELECT num,UNIX_TIMESTAMP(dispatched_at)*1000 dts,(SELECT COUNT(*) FROM orders WHERE container_id=containers.id) cnt FROM containers WHERE warehouse_id=? AND status='dispatched' ORDER BY dispatched_at DESC LIMIT 10");
      $rq->execute([$wh]);
      foreach ($rq->fetchAll() as $c) $recent[]=['num'=>$c['num'],'dts'=>(int)$c['dts'],'count'=>(int)$c['cnt']];
    } catch (Exception $e) {}
    /* №308: складские партии, готовые к отправке (подтверждены в Китае, ещё не в контейнере) */
    $availStock = [];
    try { stock_cols(); foreach (db()->query("SELECT b.id,b.qty,COALESCE(NULLIF((SELECT p.name FROM products p WHERE p.id=b.product_id),''),b.name) name FROM stock_batches b WHERE b.cn_rcv_at IS NOT NULL AND b.ship_id IS NULL AND (b.container_id IS NULL OR b.container_id='') ORDER BY b.id")->fetchAll() as $sb)
      $availStock[] = ['id'=>(int)$sb['id'],'num'=>str_pad((string)$sb['id'],4,'0',STR_PAD_LEFT),'qty'=>(int)$sb['qty'],'name'=>$sb['name']]; } catch (Exception $e) {}
    jout(['ok'=>true,'containers'=>$list,'available'=>$avail,'available_stock'=>$availStock,'recent'=>$recent,'cont_vol'=>$cont_vol]);
  }
  case 'container_create': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??''; $wh=''; $who='';
    if ($role==='partner') { try { $pq=db()->prepare('SELECT warehouse_id,name FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $r=$pq->fetch(); $wh=$r['warehouse_id']??''; $who=$r['name']??''; } catch (Exception $e) {} }
    elseif ($role==='itc' && $sr==='warehouse') { $wh=$s['supplier_id']??''; $who='Оператор'; }
    else fail('Недостаточно прав',403);
    if (!$wh) fail('Нет склада');
    $n = 0; try { $cc=db()->prepare("SELECT COUNT(*) c FROM containers WHERE warehouse_id=?"); $cc->execute([$wh]); $n=(int)$cc->fetch()['c']; } catch (Exception $e) {}
    $num = 'CNT-'.str_pad($n+1,4,'0',STR_PAD_LEFT);
    $id = gen('cnt');
    try { db()->prepare('INSERT INTO containers (id,warehouse_id,num,status,note) VALUES (?,?,?,?,?)')->execute([$id,$wh,$num,'open',mb_substr(trim(body()['note']??''),0,200)]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (containers)'); }
    wh_log_add($wh,$who,'container_new',$num,'');
    jout(['ok'=>true,'id'=>$id,'num'=>$num]);
  }
  case 'container_add': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??''; $wh='';
    if ($role==='partner') { try { $pq=db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $wh=$pq->fetchColumn()?:''; } catch (Exception $e) {} }
    elseif ($role==='itc' && $sr==='warehouse') { $wh=$s['supplier_id']??''; }
    else fail('Недостаточно прав',403);
    $d = body(); $cid = trim($d['container_id']??''); $nums = $d['nums']??[];
    if (!$cid) fail('Не указан контейнер');
    if (is_string($nums)) $nums = array_filter(array_map('trim', explode(',', $nums)));
    // проверка контейнера
    $cq=db()->prepare("SELECT id FROM containers WHERE id=? AND warehouse_id=? AND status='open'"); $cq->execute([$cid,$wh]);
    if (!$cq->fetch()) fail('Контейнер не найден');
    $added = 0;
    /* №308: складская партия ИТК в контейнер */
    foreach ((array)($d['batch_ids'] ?? []) as $bid) { try { stock_cols(); $ub = db()->prepare("UPDATE stock_batches SET container_id=? WHERE id=? AND cn_rcv_at IS NOT NULL AND ship_id IS NULL AND (container_id IS NULL OR container_id='')"); $ub->execute([$cid, (int)$bid]); $added += $ub->rowCount(); } catch (Exception $e) {} }
    foreach ((array)$nums as $num) {
      $num = preg_replace('/[^0-9A-Za-z]/','',$num); if ($num==='') continue;
      try { $u=db()->prepare("UPDATE orders SET container_id=? WHERE warehouse_id=? AND num=? AND wh_received_at IS NOT NULL AND wh_shipped_at IS NULL AND (container_id='' OR container_id IS NULL)"); $u->execute([$cid,$wh,$num]); $added += $u->rowCount(); } catch (Exception $e) {}
    }
    jout(['ok'=>true,'added'=>$added]);
  }
  case 'container_remove': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??''; $wh='';
    if ($role==='partner') { try { $pq=db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $wh=$pq->fetchColumn()?:''; } catch (Exception $e) {} }
    elseif ($role==='itc' && $sr==='warehouse') { $wh=$s['supplier_id']??''; }
    else fail('Недостаточно прав',403);
    $d = body(); $num = preg_replace('/[^0-9A-Za-z]/','',trim($d['num']??''));
    if (!empty($d['batch_id'])) { try { stock_cols(); db()->prepare("UPDATE stock_batches SET container_id=NULL WHERE id=? AND ship_id IS NULL")->execute([(int)$d['batch_id']]); } catch (Exception $e) {} jout(['ok'=>true]); }
    try { db()->prepare("UPDATE orders SET container_id='' WHERE warehouse_id=? AND num=?")->execute([$wh,$num]); } catch (Exception $e) {}
    jout(['ok'=>true]);
  }
  case 'container_dispatch': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??''; $wh=''; $who='';
    if ($role==='partner') { try { $pq=db()->prepare('SELECT warehouse_id,name FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $r=$pq->fetch(); $wh=$r['warehouse_id']??''; $who=$r['name']??''; } catch (Exception $e) {} }
    elseif ($role==='itc' && $sr==='warehouse') { $wh=$s['supplier_id']??''; $who='Оператор'; }
    else fail('Недостаточно прав',403);
    $d = body(); $cid = trim($d['container_id']??'');
    $cq=db()->prepare("SELECT id,num FROM containers WHERE id=? AND warehouse_id=? AND status='open'"); $cq->execute([$cid,$wh]); $c=$cq->fetch();
    if (!$c) fail('Контейнер не найден');
    $cnt = 0;
    try {
      // соберём телефоны заказов для уведомления
      $phs = [];
      try { $pq = db()->prepare("SELECT num,phone FROM orders WHERE container_id=? AND wh_shipped_at IS NULL AND phone<>''"); $pq->execute([$cid]); $phs = $pq->fetchAll(); } catch (Exception $e) {}
      $u = db()->prepare("UPDATE orders SET wh_shipped_at=NOW(), status='delivering' WHERE container_id=? AND wh_shipped_at IS NULL");
      $u->execute([$cid]); $cnt = $u->rowCount();
      db()->prepare("UPDATE containers SET status='dispatched', dispatched_at=NOW() WHERE id=?")->execute([$cid]);
      /* №308: складские партии в контейнере — одна общая отгрузка (номер контейнера) */
      try { stock_cols();
        $nb = db()->prepare("SELECT COUNT(*) FROM stock_batches WHERE container_id=? AND ship_id IS NULL"); $nb->execute([$cid]);
        if ((int)$nb->fetchColumn() > 0) {
          db()->prepare("INSERT INTO stock_shipments (carrier,ref,note,status,created_by,sent_at,container_id) VALUES (?,?,?,'sent',?,NOW(),?)")
              ->execute(['Контейнер', $c['num'], 'вместе с заказами покупателей', $who ?: 'Склад', $cid]);
          $shid = (int)db()->lastInsertId();
          db()->prepare("UPDATE stock_batches SET ship_id=? WHERE container_id=? AND ship_id IS NULL")->execute([$shid, $cid]);
        }
      } catch (Exception $e) {}
      if (function_exists('wp_send_to_phone')) foreach ($phs as $ph) { wp_send_to_phone(db(), $ph['phone'], '🚚 Заказ '.$ph['num'].' едет к вам', 'Контейнер отгружен. Ваш заказ направляется на выдачу.', '/'); }
    } catch (Exception $e) { fail('Ошибка отгрузки'); }
    wh_log_add($wh,$who,'container_dispatch',$c['num'],'заказов: '.$cnt);
    jout(['ok'=>true,'num'=>$c['num'],'dispatched'=>$cnt]);
  }
  // ---- СКЛАД: лог действий оператора ----
  case 'wh_log_list': {
    $s = authUser(); $role=$s['role']; $sr=$s['staff_role']??''; $wh='';
    if ($role==='partner') { try { $pq=db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $wh=$pq->fetchColumn()?:''; } catch (Exception $e) {} }
    elseif ($role==='itc') { $wh = ($sr==='warehouse') ? ($s['supplier_id']??'') : trim(body()['warehouse_id']??''); }
    else fail('Недостаточно прав',403);
    $log = [];
    try {
      $lq = $wh ? db()->prepare("SELECT staff,action,order_num,note,UNIX_TIMESTAMP(created_at)*1000 ts FROM wh_log WHERE warehouse_id=? ORDER BY created_at DESC LIMIT 100") : db()->prepare("SELECT staff,action,order_num,note,UNIX_TIMESTAMP(created_at)*1000 ts FROM wh_log ORDER BY created_at DESC LIMIT 100");
      $wh ? $lq->execute([$wh]) : $lq->execute();
      foreach ($lq->fetchAll() as $l) $log[]=['staff'=>$l['staff'],'action'=>$l['action'],'num'=>$l['order_num'],'note'=>$l['note'],'ts'=>(int)$l['ts']];
    } catch (Exception $e) {}
    jout(['ok'=>true,'log'=>$log]);
