                           FROM orders WHERE warehouse_id=? AND num=? AND paid=1");
    $oq->execute([$wh,$code]); $o=$oq->fetch();
    if (!$o) jout(['ok'=>true,'found'=>false]);
    jout(['ok'=>true,'found'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'name'=>$o['addr_name'],'cell'=>$o['wh_cell'],'weight'=>(float)$o['wh_weight'],'damage'=>(int)$o['wh_damage'],
          'received'=>$o['rts']?1:0,'shipped'=>$o['sts']?1:0,'picked'=>$o['pts']?1:0]);
  }

  // ---- СКЛАД/ИТК: фото приёмки заказа ----
  case 'wh_photo_get': {
    $s = authUser();
    $role = $s['role']; $sr = $s['staff_role'] ?? '';
    if (!($role==='partner' || ($role==='itc'))) fail('Недостаточно прав', 403);
    $d = body(); $oid = trim($d['order_id'] ?? '');
