  // ---- СКЛАД/ПАРТНЁР: предпросмотр заказа (для ввода габаритов) ----
  // ================= ПРИЁМКА ЗАКУПОК НА КИТАЙСКОМ СКЛАДЕ =================
  // Кладовщик видит, что выкуплено и едет к нему, опознаёт посылку по коду заказа
  // 1688 и сам вносит вес, объём и коробки. Замер уходит в карточку товара и
  // ПЕРЕСЧИТЫВАЕТ цену — менеджер к этому не прикасается.

  // Журнал пересчётов после замера: по нему босс и бухгалтер видят,
  // где множитель покрывал логистику, а где мы уходили в минус.
  // Пересчёты по одному товару — для строки в карточке
  case 'recalc_for_product': {
    authUser('itc');
    recalc_log_ensure();
    $pid = trim($_GET['id'] ?? '');
    if ($pid === '') jout(['ok'=>true,'last'=>null]);
    $r = null;
    try { $q=db()->prepare('SELECT old_rub,new_rub,diff_rub,diff_pct,weight_kg,volume_m3,UNIX_TIMESTAMP(created_at)*1000 ts FROM price_recalc WHERE product_id=? ORDER BY created_at DESC LIMIT 1');
          $q->execute([$pid]); $r=$q->fetch(); } catch (Exception $e) {}
    jout(['ok'=>true,'last'=>($r?:null)]);
  }

  /* Отчёт по выручке считает САМА БАЗА и отдаёт готовые суммы: при десятках тысяч
     заказов гонять их все в приложение нельзя. Только оплаченные. */
  // ---- бонус на развитие по регионам: список и правка ----
  // ---- принятие условий партнёром: оферта + акцепт = соглашение ----
  case 'pt_offer_state': {
    $s = authUser('partner');
    itc_offer_ensure();
    $row = null;
    try { $q = db()->prepare('SELECT ver, UNIX_TIMESTAMP(accepted_at)*1000 ts FROM partner_offer WHERE partner_id=? ORDER BY id DESC LIMIT 1');
          $q->execute([$s['supplier_id'] ?? '']); $row = $q->fetch(); } catch (Exception $e) {}
    $cur = ITC_OFFER_VER;
    $ok  = ($row && (string)$row['ver'] === $cur);
    jout(['ok'=>true,'accepted'=>$ok?1:0,'ver'=>$cur,'accepted_ver'=>($row['ver'] ?? ''),'accepted_ts'=>($row['ts'] ?? null)]);
  }

  case 'pt_offer_accept': {
    $s = authUser('partner');
    itc_offer_ensure();
    $pid = $s['supplier_id'] ?? '';
    if (!$pid) fail('Партнёр не найден');
    $kind = 'pvz';
    try { $w = partner_wh($s);
          if ($w) { $k = db()->prepare('SELECT kind FROM warehouses WHERE id=?'); $k->execute([$w]); $kind = $k->fetchColumn() ?: 'pvz'; } }
    catch (Exception $e) {}
    $ip = substr((string)($_SERVER['REMOTE_ADDR'] ?? ''), 0, 45);
    try {
      db()->prepare('INSERT INTO partner_offer (partner_id, phone, kind, ver, ip) VALUES (?,?,?,?,?)')
        ->execute([$pid, ($s['phone'] ?? ''), $kind, ITC_OFFER_VER, $ip]);
    } catch (Exception $e) { fail('Не удалось сохранить: '.$e->getMessage()); }
    itc_log_add(mb_substr(($s['phone'] ?? ''),0,120), 'offer_accept', 'partner', $pid, ITC_OFFER_VER);
