    // регионы, где у нас уже есть точки — чтобы боссу было из чего выбирать
    $regions = [];
    try { foreach (db()->query("SELECT DISTINCT COALESCE(NULLIF(region,''),city) r FROM warehouses WHERE country<>'CN' AND COALESCE(NULLIF(region,''),city)<>'' ORDER BY r")->fetchAll() as $x) $regions[] = $x['r']; }
    catch (Exception $e) {}
    jout(['ok'=>true,'rows'=>$rows,'regions'=>$regions,'default_pct'=>2,'until'=>ITC_BONUS_UNTIL,
