  case 'bonus_save': {
    $s = authUser('itc'); require_staff($s, ['boss','chief_accountant']);
    itc_bonus_ensure();
    $d = body();
    $region = trim($d['region'] ?? '');
    $kind = (($d['kind'] ?? 'pvz') === 'hub') ? 'hub' : 'pvz';
    $pct = (float)($d['pct'] ?? 2);
