    if ($region === '') fail('Укажите регион');
    if ($pct < 0 || $pct > 20) fail('Бонус должен быть от 0 до 20%');
    try {
      db()->prepare('INSERT INTO partner_bonus (region,kind,pct,until,note) VALUES (?,?,?,?,?)
                     ON DUPLICATE KEY UPDATE pct=VALUES(pct), until=VALUES(until), note=VALUES(note)')
        ->execute([$region,$kind,$pct,($until?:null),$note]);
    } catch (Exception $e) { fail('Не удалось сохранить: '.$e->getMessage()); }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'bonus_save', 'region', $region, $kind.' '.$pct.'%');
    jout(['ok'=>true]);
