  case 'bonus_delete': {
    $s = authUser('itc'); require_staff($s, ['boss','chief_accountant']);
    itc_bonus_ensure();
    $d = body(); $id = (int)($d['id'] ?? 0);
    if (!$id) fail('Не указана строка');
    try { db()->prepare('DELETE FROM partner_bonus WHERE id=?')->execute([$id]); }
    catch (Exception $e) { fail('Не удалось удалить'); }
    jout(['ok'=>true]);
  }

  case 'revenue_report': {
    $s = authUser('itc'); require_staff($s, ['boss','chief_accountant','accountant','manager','supervisor']);
    // индекс под этот отчёт — без него на больших объёмах будет медленно
    try { db()->query("ALTER TABLE orders ADD INDEX idx_paid_created (paid, created_at)"); } catch (Exception $e) {}
    $mode = (($_GET['mode'] ?? 'month') === 'week') ? 'week' : 'month';
    $rows = [];
    try {
      if ($mode === 'month') {
        $rows = db()->query("SELECT DATE_FORMAT(created_at,'%Y-%m') AS k,
                                    YEAR(created_at) AS y, MONTH(created_at) AS m,
                                    COUNT(*) AS cnt, COALESCE(SUM(total),0) AS sum
                               FROM orders WHERE paid=1
                              GROUP BY k, y, m ORDER BY k DESC LIMIT 24")->fetchAll();
      } else {
        // режим 1 = неделя начинается с понедельника
        $rows = db()->query("SELECT YEARWEEK(created_at,1) AS k,
                                    DATE(DATE_SUB(created_at, INTERVAL WEEKDAY(created_at) DAY)) AS d1,
                                    COUNT(*) AS cnt, COALESCE(SUM(total),0) AS sum
                               FROM orders WHERE paid=1
                              GROUP BY k, d1 ORDER BY k DESC LIMIT 16")->fetchAll();
      }
    } catch (Exception $e) { jout(['ok'=>false,'error'=>$e->getMessage()]); }
    $total = 0; foreach ($rows as $r) { $total += (int)$r['sum']; }
    jout(['ok'=>true,'mode'=>$mode,'rows'=>$rows,'total'=>$total]);
  }

  case 'recalc_report': {
    $s = authUser('itc'); require_staff($s, ['boss','chief_accountant','accountant','manager']);
    recalc_log_ensure();
    $rows = [];
    try {
      $rows = db()->query("SELECT r.*, p.name pname, p.img pimg
                             FROM price_recalc r LEFT JOIN products p ON p.id = r.product_id
                            ORDER BY r.created_at DESC LIMIT 300")->fetchAll();
    } catch (Exception $e) {}
    $up = 0; $down = 0; $sumUp = 0; $sumDown = 0;
    foreach ($rows as $r) {
      $d = (int)$r['diff_rub'];
      if ($d > 0) { $up++;  $sumUp  += $d; }      // цена выросла — продавали дешевле себестоимости
      if ($d < 0) { $down++; $sumDown += -$d; }   // цена упала — брали лишнего
    }
    jout(['ok'=>true,'items'=>$rows,'stat'=>['up'=>$up,'down'=>$down,'sum_up'=>$sumUp,'sum_down'=>$sumDown,'total'=>count($rows)]]);
  }

  case 'wh_purchases': {
    $s = authUser('itc');
    $sr = $s['staff_role'] ?? '';
    if ($sr !== 'warehouse' && $sr !== 'wh_manager' && $sr !== 'wh_worker' && $sr !== 'boss' && $sr !== 'supervisor') fail('Недостаточно прав', 403);
    $rows = [];
    try {
      $rows = db()->query("SELECT pc.id, pc.source_order_id, pc.qty, pc.status, pc.product_id,
                                  pc.buyout_price_cny, pc.source_price_cny, pc.source_url,
                                  pc.actual_weight_kg, pc.actual_volume_m3, pc.weighed_at,
                                  UNIX_TIMESTAMP(pc.ordered_at)*1000 ordered_ts,
                                  COALESCE(NULLIF(p.name,''),(SELECT i2.name FROM order_items i2
                                    WHERE i2.order_id=pc.order_id AND i2.product_id=pc.product_id LIMIT 1)) pname,
                                  p.img pimg, p.volume_m3, p.weight_kg,
                                  o.num order_num, o.addr_city order_city,
                                  w.code wh_code, w.name wh_name, w.city wh_city
                             FROM ds_procurement pc
                             LEFT JOIN products p ON p.id = pc.product_id
                             LEFT JOIN orders   o ON o.id = pc.order_id
                             LEFT JOIN warehouses w ON w.id = o.warehouse_id
                            WHERE pc.status IN ('ordered','received')
                            ORDER BY (pc.weighed_at IS NULL) DESC, pc.ordered_at DESC
                            LIMIT 300")->fetchAll();
    } catch (Exception $e) {}
    $wait = 0; foreach ($rows as $r) { if (empty($r['weighed_at'])) $wait++; }
    jout(['ok' => true, 'items' => $rows, 'waiting' => $wait]);
  }

  // Опознание посылки: кладовщик сканирует наклейку или вбивает номер вручную
  case 'wh_purchase_find': {
    $s = authUser('itc');
    $sr = $s['staff_role'] ?? '';
    if ($sr !== 'warehouse' && $sr !== 'wh_manager' && $sr !== 'wh_worker' && $sr !== 'boss' && $sr !== 'supervisor') fail('Недостаточно прав', 403);
    $d = body();
    $code = trim($d['code'] ?? '');
    if ($code === '') fail('Пустой код');
    // на наклейке может быть лишнее — ищем и по полному совпадению, и по хвосту номера
    $tail = preg_replace('/[^0-9]/', '', $code);
    $rows = [];
    try {
      $q = db()->prepare("SELECT pc.id, pc.source_order_id, pc.qty, pc.status, pc.product_id, pc.source_url,
                                 pc.actual_weight_kg, pc.actual_volume_m3, pc.weighed_at,
                                 p.name pname, p.img pimg, p.volume_m3, p.weight_kg, o.num order_num
                            FROM ds_procurement pc
                            LEFT JOIN products p ON p.id = pc.product_id
                            LEFT JOIN orders   o ON o.id = pc.order_id
                           WHERE pc.status IN ('ordered','received')
                             AND (pc.source_order_id = ? OR pc.source_order_id LIKE ? OR (? <> '' AND pc.source_order_id LIKE ?))
                           LIMIT 20");
      $q->execute([$code, '%'.$code.'%', $tail, '%'.$tail.'%']);
      $rows = $q->fetchAll();
    } catch (Exception $e) {}
    jout(['ok' => true, 'found' => $rows]);
  }

  // Замер кладовщиком: вес, объём, коробки, фото → в карточку и пересчёт цены
  case 'wh_purchase_measure': {
    $s = authUser('itc');
    $sr = $s['staff_role'] ?? '';
    if ($sr !== 'warehouse' && $sr !== 'wh_manager' && $sr !== 'wh_worker' && $sr !== 'boss' && $sr !== 'supervisor') fail('Недостаточно прав', 403);
    $d = body();
    $id  = trim($d['id'] ?? '');
    $awt = (float)($d['weight_kg'] ?? 0);
    $avol= (float)($d['volume_m3'] ?? 0);
    if ($id === '') fail('Не указана закупка');
    if ($awt <= 0 && $avol <= 0) fail('Укажите вес и объём');

    $pq = db()->prepare('SELECT dp.id dsid, dp.product_id pid, dp.declared_weight_kg dswt
                           FROM ds_procurement pc LEFT JOIN ds_products dp ON dp.id = pc.ds_product_id
                          WHERE pc.id = ?');
    $pq->execute([$id]); $row = $pq->fetch();
    if (!$row) fail('Закупка не найдена');
    $decl = (float)($row['dswt'] ?? 0);
    $variance = ($decl > 0 && $awt > 0) ? round((($awt - $decl) / $decl) * 100, 2) : null;

    // коробки — как есть, строкой: «60x40x30 · 8 кг» через точку с запятой
    $boxes = mb_substr(trim($d['boxes'] ?? ''), 0, 500);
    try { db()->query("ALTER TABLE ds_procurement ADD COLUMN box_dims VARCHAR(500) NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE orders ADD COLUMN oversize_moved TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE orders ADD COLUMN oversize_from VARCHAR(32) NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE orders ADD COLUMN oversize_at DATETIME NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE ds_procurement ADD COLUMN wh_photos TEXT NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE ds_procurement ADD COLUMN weighed_by VARCHAR(120) NULL"); } catch (Exception $e) {}

    // фото приёмки
    $ph = [];
    $add = $d['photos'] ?? [];
    if (is_array($add)) { $n=0; foreach ($add as $one) { if ($n >= 4) break; $u = itc_store_b64_image($one); if ($u !== '') { $ph[] = $u; $n++; } } }

    try {
      db()->prepare('UPDATE ds_procurement SET actual_weight_kg=?, actual_volume_m3=?, weight_variance_pct=?, weighed_at=NOW(), box_dims=?, weighed_by=?'
        .($ph ? ', wh_photos=?' : '').' WHERE id=?')
        ->execute($ph
          ? [$awt?:null, $avol?:null, $variance, $boxes, mb_substr(($s['phone']??''),0,120), json_encode($ph, JSON_UNESCAPED_UNICODE), $id]
          : [$awt?:null, $avol?:null, $variance, $boxes, mb_substr(($s['phone']??''),0,120), $id]);
    } catch (Exception $e) { fail('Не удалось сохранить: '.$e->getMessage()); }

    // Тот же путь, что и у ds_weigh: факт в карточку, снимаем режим ×N, пересчитываем цену
    $dsid = (string)($row['dsid'] ?? ''); $pid = (string)($row['pid'] ?? '');
    $oldRub = null; $newRub = null;
    if ($dsid) {
      try { $oq=db()->prepare('SELECT our_price_rub FROM ds_products WHERE id=?'); $oq->execute([$dsid]); $oldRub=(int)$oq->fetchColumn(); } catch (Exception $e) {}
      $sets=[]; $args=[];
      if ($awt > 0) { $sets[]='declared_weight_kg=?'; $args[]=$awt; }
      if ($avol> 0) { $sets[]='declared_volume_m3=?'; $args[]=$avol; }
      $sets[]='x3_pending=0'; $args[]=$dsid;
      try { db()->prepare('UPDATE ds_products SET '.implode(',',$sets).' WHERE id=?')->execute($args); } catch (Exception $e) {}
      if ($pid) {
        $ps=[]; $pa=[];
        if ($awt > 0) { $ps[]='weight_kg=?';  $pa[]=$awt; }
        if ($avol> 0) { $ps[]='volume_m3=?'; $pa[]=$avol; }
        if ($ps) { $pa[]=$pid; try { db()->prepare('UPDATE products SET '.implode(',',$ps).' WHERE id=?')->execute($pa); } catch (Exception $e) {} }
      }
      ds_sync_product_price($dsid);
      try { $rq=db()->prepare('SELECT our_price_rub FROM ds_products WHERE id=?'); $rq->execute([$dsid]); $newRub=(int)$rq->fetchColumn(); } catch (Exception $e) {}
      // Пишем в журнал: он нужен боссу и бухгалтеру для разбора, кому цена ушла в плюс, кому в минус
      if ($oldRub > 0 && $newRub > 0 && $oldRub !== $newRub) {
        recalc_log_ensure();
        $diff = $newRub - $oldRub;
        $pct  = (int)round($diff * 100 / $oldRub);
        $soid = '';
        try { $sq=db()->prepare('SELECT source_order_id FROM ds_procurement WHERE id=?'); $sq->execute([$id]); $soid=(string)$sq->fetchColumn(); } catch (Exception $e) {}
        try { db()->prepare('INSERT INTO price_recalc (procurement_id,product_id,ds_id,old_rub,new_rub,diff_rub,diff_pct,weight_kg,volume_m3,source_order_id,by_phone) VALUES (?,?,?,?,?,?,?,?,?,?,?)')
          ->execute([$id,$pid,$dsid,$oldRub,$newRub,$diff,$pct,($awt?:null),($avol?:null),$soid,mb_substr(($s['phone']??''),0,40)]); } catch (Exception $e) {}
      }
    }
    itc_log_add(mb_substr(($s['phone']??''),0,120), 'wh_measure', 'procurement', $id, ($awt.' кг / '.$avol.' м³'));
    // Крупногабарит — переводим выдачу на склад и предупреждаем покупателей
    $moved = [];
    try { $moved = itc_mark_oversize_items($pid, $avol, $awt); } catch (Exception $e) {}
    // Кладовщику цену НЕ отдаём: он китаец, работает с коробками, рубли ему не нужны.
    // Но про перевод сказать полезно — он поймёт, что товар пойдёт на склад, а не в ПВЗ.
    jout(['ok'=>true,'variance'=>$variance,'photos'=>$ph,'oversize'=>itc_is_oversize($avol,$awt),'moved'=>count($moved)]);
  }

  case 'wh_order_lookup': {
    $s = authUser();
    $role = $s['role']; $sr = $s['staff_role'] ?? '';
    $wh = '';
    if ($role === 'partner') { try { $pq=db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $wh=$pq->fetchColumn()?:''; } catch (Exception $e) {} }
    elseif ($role === 'itc' && $sr === 'warehouse') { $wh = $s['supplier_id'] ?? ''; }
    else fail('Недостаточно прав', 403);
    if (!$wh) fail('За вами не закреплён склад');
    $d = body(); $rawcode = trim($d['code'] ?? '');
    list($code, $box_seq, $box_w, $box_v) = parse_scan_code($rawcode);
    /* Номер заказа пишется русской «М» (М-1024), а из наклейки приходит
       латиница или одни цифры — при точном сравнении заказ не находился.
       Сверяем по цифрам номера (25.09.2026). */
    $oq = db()->prepare("SELECT id,num,addr_city,addr_name,warehouse_id,dest_warehouse_id,wh_received_at,wh_shipped_at,dest_received_at,box_checked,box_decl_m3 FROM orders WHERE (num=? OR REGEXP_REPLACE(num,'[^0-9]','')=REGEXP_REPLACE(?,'[^0-9]','')) AND paid=1 AND (warehouse_id=? OR dest_warehouse_id=?)");
    $oq->execute([$code, $code, $wh, $wh]); $o = $oq->fetch();
    if (!$o) fail('Заказ '.$code.' не найден среди адресованных вашему складу');
    scan_key_check($o['id']);   // №284
    $asDest = (!empty($o['dest_warehouse_id']) && $o['dest_warehouse_id'] === $wh && $o['warehouse_id'] !== $wh);
    $places = order_places_ensure($o['id']);
    $recv_places = 0;
    if ($places > 1) { try { $cq=db()->prepare('SELECT COUNT(*) FROM order_boxes WHERE order_id=? AND '.($asDest?'dest_at':'origin_at').' IS NOT NULL'); $cq->execute([$o['id']]); $recv_places=(int)$cq->fetchColumn(); } catch (Exception $e) {} }
    $decl = (float)$o['box_decl_m3']; if ($decl <= 0) $decl = order_decl_m3($o['id']);
    jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'name'=>$o['addr_name'],
          'received'=>$asDest ? ($o['dest_received_at']?1:0) : ($o['wh_received_at']?1:0),
          'is_dest'=>$asDest?1:0,'shipped'=>$o['wh_shipped_at']?1:0,
          'places'=>$places,'box_seq'=>$box_seq,'received_places'=>$recv_places,
          'checked'=>(int)$o['box_checked'],'decl_m3'=>round($decl,4)]);
  }

  // ---- ЕДИНОЕ СКАНИРОВАНИЕ (оператор склада ИЛИ партнёр): приёмка/отправка/выдача ----
  /* №275: ПРИЁМКА ОДНОГО ТОВАРА НА ПУНКТЕ ПО НАКЛЕЙКЕ ТОВАРА (М-1069-2).
     Один товар — одна наклейка. Товары одного заказа приходят в разные дни,
     каждый приходуется отдельно, покупателю — уведомление про этот товар. */
  case 'pvz_item_receive': {
    $s = authUser();
    $role = $s['role']; $sr = $s['staff_role'] ?? '';
    $wh = ''; $whoName = '';
    if ($role === 'partner') {
      try { $pq = db()->prepare('SELECT warehouse_id,name FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $pr = $pq->fetch();
            $wh = $pr['warehouse_id'] ?? ''; $whoName = ($pr['name'] ?? '') ?: 'Партнёр'; } catch (Exception $e) {}
    } elseif ($role === 'itc' && $sr === 'warehouse') {
      $wh = $s['supplier_id'] ?? '';
      try { $nq=db()->prepare('SELECT name FROM warehouses WHERE id=?'); $nq->execute([$wh]); $whoName=($nq->fetchColumn()?:'Склад').' · оператор'; } catch (Exception $e) { $whoName='Оператор'; }
    } else {
      fail('Приёмка доступна пункту выдачи или оператору склада', 403);
    }
    if (!$wh) fail('За вами не закреплена точка');
    $d = body();
    $raw = trim((string)($d['code'] ?? ''));
    /* №287: складская наклейка С-… проданной единицы — это товар покупателя */
    $stockOK = false;
    $__j = json_decode($raw, true);
    if ((is_array($__j) && ($__j['t'] ?? '') === 's') || preg_match('/^\s*[СC]-\d{1,6}-\d{1,3}\s*$/u', $raw)) {
      $su = stock_unit_by_code($raw);
      if (!$su) fail('Складская наклейка не распознана');
      if ($su['status'] !== 'sold' || empty($su['order_item_id'])) fail('Товар '.$su['code'].' ещё не продан — это складской запас, на пункт его не принимают');
      $sq = db()->prepare('SELECT o.num, i.sub_no FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.id=?'); $sq->execute([$su['order_item_id']]); $sr0 = $sq->fetch();
      if (!$sr0) fail('Заказ для '.$su['code'].' не найден');
      itc_item_subno_many([$su['order_id']]);
      if (empty($sr0['sub_no'])) { $sq->execute([$su['order_item_id']]); $sr0 = $sq->fetch(); }
      $raw = $sr0['num'].'-'.(int)$sr0['sub_no'];
      $stockOK = true;
    }
    $j = json_decode($raw, true);
    $isScan = is_array($j); $scanKey = $isScan ? (string)($j['k'] ?? '') : '';
    if (is_array($j) && !empty($j['c'])) $raw = (string)$j['c'];
    $raw = strtoupper(strtr($raw, ['М'=>'M','м'=>'M',' '=>'']));
    if (!preg_match('/^(.*\d)-(\d{1,3})$/', $raw, $m)) fail('Это не наклейка товара: '.$raw);
    $digits = preg_replace('/\D/', '', $m[1]); $sub = (int)$m[2];
    if ($digits === '' || $sub < 1) fail('Не удалось разобрать номер товара');
    $oq = db()->prepare("SELECT o.id,o.num,o.phone,o.warehouse_id,o.dest_warehouse_id,o.wh_received_at,w.name wname
                           FROM orders o LEFT JOIN warehouses w ON w.id=o.warehouse_id
                          WHERE REGEXP_REPLACE(o.num,'[^0-9]','')=? AND o.paid=1 ORDER BY o.created_at DESC LIMIT 1");
    $oq->execute([$digits]);
    $o = $oq->fetch();
    if (!$o) fail('Заказ для товара '.$raw.' не найден');
    if ($o['warehouse_id'] !== $wh && ($o['dest_warehouse_id'] ?? '') !== $wh)
      fail('Товар '.$raw.' едет на другой пункт: '.($o['wname'] ?: 'не указан').'. Не принимайте его.');
    itc_items_cols();
    itc_item_subno_many([$o['id']]);
    $iq = db()->prepare('SELECT id,name,qty,pvz_rcv_at,COALESCE(oversize,0) oversize FROM order_items WHERE order_id=? AND sub_no=? LIMIT 1');
    try { $iq->execute([$o['id'], $sub]); $it = $iq->fetch(); }
    catch (Exception $e) { $iq = db()->prepare('SELECT id,name,qty,pvz_rcv_at,0 oversize FROM order_items WHERE order_id=? AND sub_no=? LIMIT 1'); $iq->execute([$o['id'], $sub]); $it = $iq->fetch(); }
    if (!$it) fail('В заказе '.$o['num'].' нет товара с номером '.$sub);
    $code = $o['num'].'-'.$sub;
    /* №284: подлинность наклейки. Скан QR — ключ обязан совпасть.
       Номер, набранный руками, принимается, но с пометкой в журнале. */
    $km = itc_item_keys_many([$o['id']]); $realKey = (string)($km[$it['id']] ?? '');
    $manual = !$isScan && !$stockOK;
    if (!$stockOK && $isScan && ($scanKey === '' || $realKey === '' || !hash_equals($realKey, $scanKey)))
      fail('Наклейка не подлинная: ключ не совпадает. Не принимайте товар '.$code.', сообщите в ИТК');
    $nm = (string)$it['name']; if (mb_strlen($nm) > 60) $nm = mb_substr($nm, 0, 58).'…';
    // сколько товаров заказа уже на пункте
    $cnt = function() use ($o) {
      $c = db()->prepare('SELECT COUNT(*) t, SUM(CASE WHEN pvz_rcv_at IS NOT NULL THEN 1 ELSE 0 END) r FROM order_items WHERE order_id=? AND COALESCE(oversize,0)=0');
      try { $c->execute([$o['id']]); } catch (Exception $e) { $c = db()->prepare('SELECT COUNT(*) t, SUM(CASE WHEN pvz_rcv_at IS NOT NULL THEN 1 ELSE 0 END) r FROM order_items WHERE order_id=?'); $c->execute([$o['id']]); }
      $x = $c->fetch(); return [(int)$x['t'], (int)$x['r']];
    };
    /* №355 · «заказ целиком на пункте»: если пункт — получатель (заказ едет со склада), отмечаем
       dest_received_at, иначе wh_received_at. Раньше всегда ставилось wh_received_at, и у пункта-получателя
       принятый товар не попадал в «У вас на пункте». Повторный скан доделывает отметку, если её не было. */
    $asDest = (($o['dest_warehouse_id'] ?? '') === $wh && $o['warehouse_id'] !== $wh);
    $markAll = function () use ($o, $asDest) {
      if ($asDest) {
        try { db()->prepare("UPDATE orders SET dest_received_at=COALESCE(dest_received_at,NOW()), status=IF(status IN ('done','picked','closed'),status,'at_dest') WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {}
      } else {
        try { db()->prepare('UPDATE orders SET wh_received_at=COALESCE(wh_received_at,NOW()) WHERE id=?')->execute([$o['id']]); } catch (Exception $e) {}
        try { db()->prepare("UPDATE orders SET status='at_warehouse' WHERE id=? AND status IN('created','confirmed','shipping','paid','new')")->execute([$o['id']]); } catch (Exception $e) {}
      }
    };
    if (!empty($it['pvz_rcv_at'])) {
      list($t, $r) = $cnt();
      if ($t > 0 && $r >= $t) $markAll();
      jout(['ok'=>true,'already'=>1,'code'=>$code,'name'=>$nm,'msg'=>'Товар '.$code.' уже принят · на пункте '.$r.' из '.$t]);
    }
    db()->prepare('UPDATE order_items SET pvz_rcv_at=NOW(), pvz_rcv_wh=? WHERE id=?')->execute([$wh, $it['id']]);
    /* №290: полка на пункте. Номер полки — со скана наклейки полки или введён руками. */
    $shelf = ''; $shRaw = trim((string)($d['shelf'] ?? ''));
    if ($shRaw !== '') { $sj = json_decode($shRaw, true); $shelf = (is_array($sj) && ($sj['t'] ?? '') === 'pshelf') ? (string)(int)($sj['n'] ?? 0) : preg_replace('/\D/', '', $shRaw); if ($shelf === '0') $shelf = ''; }
    $others = [];
    try { $oq2 = db()->prepare("SELECT DISTINCT pvz_shelf FROM order_items WHERE order_id=? AND id<>? AND pvz_shelf IS NOT NULL AND pvz_shelf<>'' AND handed_at IS NULL"); $oq2->execute([$o['id'], $it['id']]); $others = $oq2->fetchAll(PDO::FETCH_COLUMN); } catch (Exception $e) {}
    if ($shelf !== '') { try { db()->prepare('UPDATE order_items SET pvz_shelf=? WHERE id=?')->execute([$shelf, $it['id']]); } catch (Exception $e) {} }
    $shelfMsg = $shelf !== '' ? ' → полка '.$shelf : '';
    if ($others && !in_array($shelf, $others, true)) $shelfMsg .= ' · остальное по этому заказу на полке '.implode(', ', $others);
    list($t, $r) = $cnt();
    /* Пришло всё — заказ целиком «на пункте», как при старой приёмке заказа. */
    if ($t > 0 && $r >= $t) $markAll();
    wh_log_add($wh, $whoName, 'item_receive', $code, ($manual ? 'ВРУЧНУЮ, без скана · ' : '').$nm);
    if (function_exists('wp_send_to_phone') && !empty($o['phone'])) {
      try { wp_send_to_phone(db(), $o['phone'], 'Товар поступил на пункт выдачи',
              $nm.' (№ '.$code.') ждёт вас'.($o['wname'] ? ' в пункте «'.$o['wname'].'»' : '').'. Из заказа '.$o['num'].' на пункте '.$r.' из '.$t.'.', '/'); } catch (Exception $e) {}
    }
    jout(['ok'=>true,'code'=>$code,'name'=>$nm,'received'=>$r,'total'=>$t,'shelf'=>$shelf,'msg'=>'Принят товар '.$code.$shelfMsg.' · на пункте '.$r.' из '.$t]);
  }

  /* №276: QR ПОКУПАТЕЛЯ НА ОДИН ДЕНЬ. Покупатель открывает его в кабинете;
     на сегодня выдаётся один код, завтра — новый. Внутри не номер заказа,
     а случайный код, его не подделать по номеру. */
  case 'pickup_token': {
    $s = authUser('buyer');
    $d = body();
    $id = trim((string)($d['id'] ?? ($_GET['id'] ?? '')));
    if ($id === '') fail('Не указан заказ');
    $oq = db()->prepare('SELECT o.id,o.num,o.paid,o.picked_up_at,w.name wname FROM orders o LEFT JOIN warehouses w ON w.id=o.warehouse_id WHERE o.id=? AND '.ph_sql_eq('o.phone'));
    $oq->execute([$id, ph_tail10($s['phone'])]); $o = $oq->fetch();
    if (!$o) fail('Заказ не найден');
    if ((int)$o['paid'] !== 1) fail('Заказ не оплачен');
    pickup_tokens_table();
    $tq = db()->prepare('SELECT token FROM pickup_tokens WHERE order_id=? AND day=CURDATE() LIMIT 1');
    $tq->execute([$o['id']]); $tok = (string)$tq->fetchColumn();
    if ($tok === '') {
      $tok = bin2hex(random_bytes(8));
      db()->prepare('INSERT INTO pickup_tokens (token,order_id,day,created_at) VALUES (?,?,CURDATE(),NOW())')->execute([$tok, $o['id']]);
    }
    $day = (string)db()->query("SELECT DATE_FORMAT(CURDATE(), '%d.%m.%Y')")->fetchColumn();
    $st = itc_items_state($o['id']);
    $retOk = 0;
    try { returns_table(); $rq = db()->prepare("SELECT COUNT(*) FROM item_returns WHERE order_id=? AND kind='claim' AND status='approved' AND received_at IS NULL"); $rq->execute([$o['id']]); $retOk = (int)$rq->fetchColumn(); } catch (Exception $e) {}
    jout(['ok'=>true,'token'=>$tok,'day'=>$day,'num'=>$o['num'],'pvz'=>$o['wname'] ?: '','state'=>$st,'ret_ok'=>$retOk,'memo'=>return_memo_text()]);
  }

  /* №276: ПУНКТ СКАНИРУЕТ QR ПОКУПАТЕЛЯ — что можно выдать прямо сейчас. */
  case 'pickup_lookup': {
    $s = authUser();
    list($wh, $who) = pvz_ctx($s);
    $d = body();
    $o = pickup_by_token($d['code'] ?? '', $wh);
    $st = itc_items_state($o['id']);
    jout(['ok'=>true,'token'=>$o['token'],'order_id'=>$o['id'],'num'=>$o['num'],'client'=>$o['addr_name'],'state'=>$st,'memo'=>return_memo_text()]);
  }

  /* №276: ВЫДАТЬ ВСЁ, ЧТО ЛЕЖИТ НА ПУНКТЕ. Остальное едет дальше и будет
     выдано потом по новому QR. Заказ закрыт, когда выдан последний товар. */
  case 'pickup_handover': {
    $s = authUser();
    list($wh, $who) = pvz_ctx($s);
    $d = body();
    $o = pickup_by_token($d['code'] ?? '', $wh);
    $st = itc_items_state($o['id']);
    $give = []; foreach ($st['items'] as $it) if ($it['st'] === 'point') $give[] = $it;
    if ($give && empty($d['memo'])) fail('Отметьте, что покупатель получил памятку о возврате');
    if (!$give) jout(['ok'=>true,'given'=>0,'msg'=>'Сейчас выдавать нечего: на пункте нет товаров этого заказа'.($st['way'] ? ' · ещё в пути '.$st['way'] : '')]);
    $up = db()->prepare('UPDATE order_items SET handed_at=NOW(), handed_wh=?, memo_at=NOW(), pvz_rcv_at=COALESCE(pvz_rcv_at,NOW()), pvz_rcv_wh=COALESCE(pvz_rcv_wh,?) WHERE id=? AND handed_at IS NULL');
    $codes = [];
    foreach ($give as $it) { $up->execute([$wh, $wh, $it['id']]); $codes[] = $it['code']; }
    $st2 = itc_items_state($o['id']);
    $closed = ($st2['point'] === 0 && $st2['way'] === 0);
    if ($closed && empty($o['picked_up_at'])) {
      try { db()->prepare('UPDATE orders SET picked_up_at=NOW() WHERE id=?')->execute([$o['id']]); } catch (Exception $e) {}
      try { db()->prepare("UPDATE orders SET status='done' WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {}
    }
    wh_log_add($wh, $who, 'item_handover', $o['num'], 'выдано '.count($codes).': '.implode(', ', $codes));
    if (function_exists('wp_send_to_phone') && !empty($o['phone'])) {
      $txt = 'Из заказа '.$o['num'].' выдано товаров: '.count($codes).'.'.($closed ? ' Заказ получен полностью. Спасибо за покупку!' : ' Ещё в пути: '.$st2['way'].' — придёт уведомление, когда поступят на пункт.');
      try { wp_send_to_phone(db(), $o['phone'], $closed ? 'Заказ получен' : 'Выдана часть заказа', $txt, '/'); } catch (Exception $e) {}
      try { wp_send_to_phone(db(), $o['phone'], 'Памятка о возврате', return_memo_text(), '/'); } catch (Exception $e) {}
    }
    jout(['ok'=>true,'given'=>count($codes),'codes'=>$codes,'closed'=>$closed?1:0,'way'=>$st2['way'],
          'msg'=>'Выдано '.count($codes).' · '.($closed ? 'заказ '.$o['num'].' получен полностью' : 'ещё в пути '.$st2['way'])]);
  }

  /* №277: СОСТАВ ЗАКАЗА ДЛЯ ПУНКТА — что именно заказал клиент: фото, номер
     товара, название, количество и где каждый товар сейчас. Пункт видит только
     заказы своей точки, сотрудник ИТК — любые (в том числе в предпросмотре). */
  case 'order_items_view': {
    $s = authUser();
    $d = body();
    $id = trim((string)($d['id'] ?? ($_GET['id'] ?? '')));
    if ($id === '') fail('Не указан заказ');
    $oq = db()->prepare('SELECT id,num,addr_name,warehouse_id,dest_warehouse_id FROM orders WHERE id=? AND paid=1');
    $oq->execute([$id]); $o = $oq->fetch();
    if (!$o) fail('Заказ не найден');
    $role = $s['role'] ?? ''; $sr = $s['staff_role'] ?? '';
    if ($role === 'partner' || ($role === 'itc' && $sr === 'warehouse')) {
      list($wh, $who) = pvz_ctx($s);
      if ($o['warehouse_id'] !== $wh && ($o['dest_warehouse_id'] ?? '') !== $wh) fail('Этот заказ не вашей точки', 403);
    } elseif ($role !== 'itc') {
      fail('Нет доступа', 403);
    }
    jout(['ok'=>true,'id'=>$o['id'],'num'=>$o['num'],'client'=>$o['addr_name'],'state'=>itc_items_state($o['id'])]);
  }

  /* №278: ПУНКТ — что можно оформить как отказ при получении. */
  case 'return_item_info': {
    $s = authUser();
    list($wh, $who) = pvz_ctx($s);
    returns_table();
    $d = body();
    list($o, $sub) = order_for_return($d['code'] ?? '', $wh);
    /* №280: заявления покупателя по этому заказу — принять можно только одобренное ИТК */
    $claims = [];
    try {
      $cq = db()->prepare("SELECT r.id,r.code,r.status,r.reasons,r.descr,r.photos,r.heavy,i.name,i.qty,p.img FROM item_returns r LEFT JOIN order_items i ON i.id=r.item_id LEFT JOIN products p ON p.id=i.product_id WHERE r.order_id=? AND r.kind='claim' AND r.status IN ('new','approved') AND r.received_at IS NULL ORDER BY r.id");
      $cq->execute([$o['id']]);
      foreach ($cq->fetchAll() as $c) $claims[] = ['id'=>(int)$c['id'],'code'=>$c['code'],'status'=>$c['status'],'name'=>$c['name'],'qty'=>(int)$c['qty'],'img'=>$c['img'],'heavy'=>(int)$c['heavy'],
        'reasons'=>json_decode($c['reasons'] ?: '[]', true) ?: [],'descr'=>$c['descr'],'photos'=>json_decode($c['photos'] ?: '[]', true) ?: []];
    } catch (Exception $e) {}
    jout(['ok'=>true,'order_id'=>$o['id'],'num'=>$o['num'],'client'=>$o['addr_name'],'sub'=>$sub,'state'=>itc_items_state($o['id']),'claims'=>$claims]);
  }

  /* №278: ОТКАЗ ПРИ ПОЛУЧЕНИИ НА ПУНКТЕ. Товар лежит на пункте, покупатель его
     не берёт. Пункт фиксирует причину, описание и не меньше 3 фото. Заявка уходит
     в ИТК, товар остаётся на пункте со статусом «Отказ». */
  case 'return_create': {
    $s = authUser();
    list($wh, $who) = pvz_ctx($s);
    returns_table();
    $d = body();
    $oid = trim((string)($d['order_id'] ?? ''));
    $ids = is_array($d['items'] ?? null) ? array_values(array_unique(array_map('strval', $d['items']))) : [];
    $reasons = is_array($d['reasons'] ?? null) ? array_slice(array_map(function($x){ return mb_substr(trim((string)$x), 0, 80); }, $d['reasons']), 0, 10) : [];
    $descr = trim((string)($d['descr'] ?? ''));
    $photos = is_array($d['photos'] ?? null) ? array_slice($d['photos'], 0, 8) : [];
    if ($oid === '' || !$ids) fail('Отметьте товар');
    if (!$reasons) fail('Отметьте причину');
    if (mb_strlen($descr) < 10) fail('Опишите, почему покупатель не принял товар (не короче 10 знаков)');
    if (count($photos) < 3) fail('Нужно минимум 3 фото');
    $oq = db()->prepare('SELECT id,num,phone,warehouse_id,dest_warehouse_id FROM orders WHERE id=? AND paid=1'); $oq->execute([$oid]); $o = $oq->fetch();
    if (!$o) fail('Заказ не найден');
    if ($o['warehouse_id'] !== $wh && ($o['dest_warehouse_id'] ?? '') !== $wh) fail('Этот заказ не вашей точки', 403);
    $st = itc_items_state($o['id']); $byId = []; foreach ($st['items'] as $it) $byId[(string)$it['id']] = $it;
    foreach ($ids as $iid) {
      if (!isset($byId[$iid])) fail('Товар не из этого заказа');
      if ($byId[$iid]['st'] !== 'point') fail('Товар '.$byId[$iid]['code'].' не лежит на пункте (или уже выдан) — отказ при получении невозможен');
    }
    $urls = [];
    foreach ($photos as $ph) { $u = itc_store_b64_image((string)$ph); if ($u !== '') $urls[] = $u; }
    if (count($urls) < 3) fail('Не удалось сохранить фото — нужно минимум 3. Попробуйте ещё раз');
    $ins = db()->prepare('INSERT INTO item_returns (order_id,item_id,code,kind,reasons,descr,photos,wh_id,by_name,phone,amount,heavy,status,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())');
    $codes = [];
    foreach ($ids as $iid) {
      $it = $byId[$iid];
      $ins->execute([$o['id'], $iid, $it['code'], 'refuse', json_encode($reasons, JSON_UNESCAPED_UNICODE), $descr, json_encode($urls, JSON_UNESCAPED_SLASHES),
                     $wh, $who, $o['phone'], (int)$it['price'] * (int)$it['qty'], (int)$it['heavy'], 'new']);
      db()->prepare("UPDATE order_items SET ret_status='refused' WHERE id=?")->execute([$iid]);
      $codes[] = $it['code'];
    }
    /* Если после отказа на пункте и в пути ничего не осталось, а что-то уже выдано — заказ закрыт */
    $st2 = itc_items_state($o['id']);
    if ($st2['point'] === 0 && $st2['way'] === 0 && $st2['handed'] > 0) { try { db()->prepare("UPDATE orders SET picked_up_at=COALESCE(picked_up_at,NOW()), status='done' WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {} }
    wh_log_add($wh, $who, 'item_refuse', $o['num'], 'отказ: '.implode(', ', $codes).' · '.implode(', ', $reasons));
    if (function_exists('wp_send_to_phone') && !empty($o['phone'])) {
      try { wp_send_to_phone(db(), $o['phone'], 'Оформлен отказ от товара', 'Заказ '.$o['num'].': отказ от '.implode(', ', $codes).' принят пунктом выдачи. ИТК рассмотрит заявку на возврат денег и сообщит решение.', '/'); } catch (Exception $e) {}
    }
    notify_boss('Новый возврат', 'Отказ при получении: '.implode(', ', $codes).' · '.implode(', ', $reasons));
    jout(['ok'=>true,'codes'=>$codes,'msg'=>'Отказ оформлен: '.implode(', ', $codes).'. Заявка ушла в ИТК']);
  }

  /* №279: ПОКУПАТЕЛЬ — что из заказа можно вернуть и до какого числа.
     Сроки по закону (ст. 19 и 26.1 ЗоЗПП):
     · брак — 2 года с выдачи (гарантия не установлена);
     · без брака («не подошёл») — 7 дней, если при выдаче дана памятка о возврате,
       иначе 3 месяца (90 дней). */
  case 'claim_info': {
    $s = authUser('buyer');
    returns_table();
    $d = body();
    $id = trim((string)($d['id'] ?? ($_GET['id'] ?? '')));
    $oq = db()->prepare('SELECT o.id,o.num,o.picked_up_at,w.name wname FROM orders o LEFT JOIN warehouses w ON w.id=o.warehouse_id WHERE o.id=? AND o.paid=1 AND '.ph_sql_eq('o.phone'));
    $oq->execute([$id, ph_tail10($s['phone'])]); $o = $oq->fetch();
    if (!$o) fail('Заказ не найден');
    $q = db()->prepare('SELECT i.id,i.handed_at,i.memo_at,i.ret_status FROM order_items i WHERE i.order_id=?'); $q->execute([$o['id']]);
    $meta = []; foreach ($q->fetchAll() as $r) $meta[(string)$r['id']] = $r;
    $st = itc_items_state($o['id']); $items = [];
    foreach ($st['items'] as $it) {
      $m = $meta[(string)$it['id']] ?? [];
      $hAt = $m['handed_at'] ?? null; if (!$hAt && !empty($o['picked_up_at'])) $hAt = $o['picked_up_at'];
      $days = $hAt ? (int)floor((time() - strtotime($hAt)) / 86400) : null;
      $nobrakLimit = !empty($m['memo_at']) ? 7 : 90;
      $it['handed_date'] = $hAt ? date('d.m.Y', strtotime($hAt)) : '';
      $it['can_brak'] = ($it['st'] === 'handed' && $days !== null && $days <= 730) ? 1 : 0;
      $it['can_nobrak'] = ($it['st'] === 'handed' && $days !== null && $days <= $nobrakLimit) ? 1 : 0;
      $it['nobrak_until'] = $hAt ? date('d.m.Y', strtotime($hAt) + $nobrakLimit * 86400) : '';
      $it['brak_until'] = $hAt ? date('d.m.Y', strtotime($hAt) + 730 * 86400) : '';
      $it['ret_status'] = (string)($m['ret_status'] ?? '');
      $items[] = $it;
    }
    jout(['ok'=>true,'order_id'=>$o['id'],'num'=>$o['num'],'pvz'=>$o['wname'] ?: '','items'=>$items]);
  }

  /* №279: ПОКУПАТЕЛЬ — заявление на возврат полученного товара. Причины
     галочками, своё описание, не меньше 4 фото. Заявка уходит в ИТК. */
  case 'claim_create': {
    $s = authUser('buyer');
    returns_table();
    $d = body();
    $oid = trim((string)($d['order_id'] ?? ''));
    $ids = is_array($d['items'] ?? null) ? array_values(array_unique(array_map('strval', $d['items']))) : [];
    $reasons = is_array($d['reasons'] ?? null) ? array_slice(array_map(function($x){ return mb_substr(trim((string)$x), 0, 80); }, $d['reasons']), 0, 10) : [];
    $descr = trim((string)($d['descr'] ?? ''));
    $photos = is_array($d['photos'] ?? null) ? array_slice($d['photos'], 0, 8) : [];
    if ($oid === '' || !$ids) fail('Отметьте товар');
    if (!$reasons) fail('Отметьте причину');
    if (mb_strlen($descr) < 20) fail('Опишите подробно, что не так с товаром (не короче 20 знаков)');
    if (count($photos) < 4) fail('Нужно минимум 4 фото');
    $oq = db()->prepare('SELECT o.id,o.num,o.phone,o.warehouse_id,o.picked_up_at FROM orders o WHERE o.id=? AND o.paid=1 AND '.ph_sql_eq('o.phone'));
    $oq->execute([$oid, ph_tail10($s['phone'])]); $o = $oq->fetch();
    if (!$o) fail('Заказ не найден');
    $onlyNobrak = (count($reasons) === 1 && mb_stripos($reasons[0], 'не подош') !== false);
    $st = itc_items_state($o['id']); $byId = []; foreach ($st['items'] as $it) $byId[(string)$it['id']] = $it;
    $q = db()->prepare('SELECT handed_at,memo_at FROM order_items WHERE id=?');
    foreach ($ids as $iid) {
      if (!isset($byId[$iid])) fail('Товар не из этого заказа');
      $it = $byId[$iid];
      if ($it['st'] !== 'handed') fail('Заявление можно подать только на полученный товар ('.$it['code'].')');
      $q->execute([$iid]); $m = $q->fetch() ?: [];
      $hAt = $m['handed_at'] ?? null; if (!$hAt) $hAt = $o['picked_up_at'];
      $days = $hAt ? (int)floor((time() - strtotime($hAt)) / 86400) : 0;
      $lim = $onlyNobrak ? (!empty($m['memo_at']) ? 7 : 90) : 730;
      if ($days > $lim) fail($onlyNobrak ? 'Срок возврата товара без брака для '.$it['code'].' истёк ('.$lim.' дн. с получения)' : 'Срок предъявления требований по '.$it['code'].' истёк');
    }
    $urls = [];
    foreach ($photos as $ph) { $u = itc_store_b64_image((string)$ph); if ($u !== '') $urls[] = $u; }
    if (count($urls) < 4) fail('Не удалось сохранить фото — нужно минимум 4. Попробуйте ещё раз');
    $ins = db()->prepare('INSERT INTO item_returns (order_id,item_id,code,kind,reasons,descr,photos,wh_id,by_name,phone,amount,heavy,status,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())');
    $codes = [];
    foreach ($ids as $iid) {
      $it = $byId[$iid];
      $ins->execute([$o['id'], $iid, $it['code'], 'claim', json_encode($reasons, JSON_UNESCAPED_UNICODE), $descr, json_encode($urls, JSON_UNESCAPED_SLASHES),
                     $o['warehouse_id'], 'Покупатель', $o['phone'], (int)$it['price'] * (int)$it['qty'], (int)$it['heavy'], 'new']);
      db()->prepare("UPDATE order_items SET ret_status='claimed' WHERE id=?")->execute([$iid]);
      $codes[] = $it['code'];
    }
    notify_boss('Заявление на возврат', implode(', ', $codes).' · '.implode(', ', $reasons));
    jout(['ok'=>true,'codes'=>$codes,'msg'=>'Заявление отправлено в ИТК. Мы рассмотрим его и сообщим решение. Не сдавайте товар до одобрения.']);
  }

  /* №280: ПУНКТ ПРИНИМАЕТ ТОВАР ПО ОДОБРЕННОМУ ЗАЯВЛЕНИЮ. Только после решения
     ИТК. Фото состояния товара при приёмке — не меньше 3 (фиксация, чтобы не было
     спора о состоянии возвращённого товара). */
  case 'return_accept': {
    $s = authUser();
    list($wh, $who) = pvz_ctx($s);
    returns_table();
    $d = body();
    $id = (int)($d['id'] ?? 0);
    $note = trim((string)($d['note'] ?? ''));
    $photos = is_array($d['photos'] ?? null) ? array_slice($d['photos'], 0, 8) : [];
    $q = db()->prepare('SELECT r.*, o.num, o.warehouse_id owh, o.dest_warehouse_id odest FROM item_returns r LEFT JOIN orders o ON o.id=r.order_id WHERE r.id=?'); $q->execute([$id]); $r = $q->fetch();
    if (!$r) fail('Заявление не найдено');
    if ($r['owh'] !== $wh && ($r['odest'] ?? '') !== $wh) fail('Этот заказ получали в другом пункте — принимать возврат должен он', 403);
    if ($r['status'] === 'new') fail('Заявление ещё не одобрено ИТК. Товар не принимайте');
    if ($r['status'] !== 'approved') fail('По этому заявлению возврат не одобрен');
    if (!empty($r['received_at'])) fail('Товар по этому заявлению уже принят');
    if (count($photos) < 3) fail('Нужно минимум 3 фото товара при приёмке');
    $urls = []; foreach ($photos as $ph) { $u = itc_store_b64_image((string)$ph); if ($u !== '') $urls[] = $u; }
    if (count($urls) < 3) fail('Не удалось сохранить фото — нужно минимум 3. Попробуйте ещё раз');
    db()->prepare('UPDATE item_returns SET received_at=NOW(), recv_photos=?, recv_by=?, recv_note=? WHERE id=?')->execute([json_encode($urls, JSON_UNESCAPED_SLASHES), $who, $note, $id]);
    try { db()->prepare("UPDATE order_items SET ret_status='returned' WHERE id=?")->execute([$r['item_id']]); } catch (Exception $e) {}
    wh_log_add($wh, $who, 'item_return_in', $r['num'], 'принят возврат '.$r['code']);
    if (function_exists('wp_send_to_phone') && !empty($r['phone'])) { try { wp_send_to_phone(db(), $r['phone'], 'Возврат принят', 'Товар '.$r['code'].' принят пунктом выдачи. Деньги вернём в течение 10 дней со дня заявки.', '/'); } catch (Exception $e) {} }
    notify_boss('Возврат сдан на пункт', $r['code'].' принят пунктом');
    jout(['ok'=>true,'msg'=>'Возврат '.$r['code'].' принят']);
  }

  /* №278: ИТК — все заявки на возврат. */
  case 'returns_list': {
    $s = authUser('itc'); require_staff($s, ['boss','manager']);
    returns_table();
    $rows = db()->query("SELECT r.*, UNIX_TIMESTAMP(r.created_at)*1000 ts, UNIX_TIMESTAMP(r.decided_at)*1000 dts,
                                o.num, o.addr_name client, w.name wname, i.name iname, i.qty, i.product_id pid, p.img
                           FROM item_returns r
                           LEFT JOIN orders o ON o.id=r.order_id
                           LEFT JOIN warehouses w ON w.id=r.wh_id
                           LEFT JOIN order_items i ON i.id=r.item_id
                           LEFT JOIN products p ON p.id=i.product_id
                          ORDER BY (r.status='new') DESC, (r.status='approved') DESC, r.created_at DESC LIMIT 300")->fetchAll();
    $out = [];
    foreach ($rows as $r) {
      $daysPassed = (int)floor((time() - (int)($r['ts'] / 1000)) / 86400);
      $out[] = ['id'=>(int)$r['id'],'code'=>$r['code'],'kind'=>$r['kind'],'status'=>$r['status'],'num'=>$r['num'],'client'=>$r['client'],'phone'=>$r['phone'],
                'pvz'=>$r['wname'],'name'=>$r['iname'],'qty'=>(int)$r['qty'],'pid'=>$r['pid'],'img'=>$r['img'],'amount'=>(int)$r['amount'],'heavy'=>(int)$r['heavy'],
                'reasons'=>json_decode($r['reasons'] ?: '[]', true) ?: [],'descr'=>$r['descr'],'photos'=>json_decode($r['photos'] ?: '[]', true) ?: [],
                'by'=>$r['by_name'],'ts'=>(int)$r['ts'],'fault'=>$r['fault'],'note'=>$r['decision_note'],'decided_by'=>$r['decided_by'],'dts'=>(int)$r['dts'],
                'days_left'=>10 - $daysPassed,
                'received'=>!empty($r['received_at']) ? date('d.m.Y H:i', strtotime($r['received_at'])) : '',
                'recv_photos'=>json_decode($r['recv_photos'] ?? '[]', true) ?: [],'recv_by'=>$r['recv_by'] ?? '','recv_note'=>$r['recv_note'] ?? ''];
    }
    jout(['ok'=>true,'rows'=>$out]);
  }

  /* №278: ИТК — решение по заявке. Одобрить / отказать — с указанием, чья вина
     (с кого списывать). Отказ — только с основанием. «Деньги возвращены» —
     запись в возвраты клиентам. */
  case 'return_decide': {
    $s = authUser('itc'); require_staff($s, ['boss','manager']);
    returns_table();
    $d = body();
    $id = (int)($d['id'] ?? 0); $act = (string)($d['act'] ?? '');
    $fault = (string)($d['fault'] ?? ''); $note = trim((string)($d['note'] ?? ''));
    $q = db()->prepare('SELECT r.*, o.num FROM item_returns r LEFT JOIN orders o ON o.id=r.order_id WHERE r.id=?'); $q->execute([$id]); $r = $q->fetch();
    if (!$r) fail('Заявка не найдена');
    $who = trim((string)($s['name'] ?? '')) ?: 'ИТК';
    if ($act === 'approve' || $act === 'reject') {
      if ($r['status'] !== 'new') fail('Решение по заявке уже принято');
      if (!in_array($fault, ['pvz','warehouse','itc','supplier','buyer'], true)) fail('Укажите, чья вина');
      if ($act === 'reject' && mb_strlen($note) < 10) fail('Укажите основание отказа (не короче 10 знаков)');
      $new = $act === 'approve' ? 'approved' : 'rejected';
      db()->prepare('UPDATE item_returns SET status=?, fault=?, decision_note=?, decided_by=?, decided_at=NOW() WHERE id=?')->execute([$new, $fault, $note, $who, $id]);
      if ($act === 'reject') { try { db()->prepare("UPDATE order_items SET ret_status='rejected' WHERE id=?")->execute([$r['item_id']]); } catch (Exception $e) {} }
      if (function_exists('wp_send_to_phone') && !empty($r['phone'])) {
        $txt = $act === 'approve'
          ? ($r['kind'] === 'claim'
              ? 'Возврат по товару '.$r['code'].' одобрен. Сдать товар можно в пункте выдачи, где вы его получили, — он примет его по вашей заявке. Если привезти не получается, напишите в ИТК, согласуем способ.'
              : 'Возврат по товару '.$r['code'].' одобрен. Деньги вернём в течение 10 дней со дня заявки.')
          : 'По товару '.$r['code'].' в возврате отказано. Основание: '.$note;
        try { wp_send_to_phone(db(), $r['phone'], $act === 'approve' ? 'Возврат одобрен' : 'В возврате отказано', $txt, '/'); } catch (Exception $e) {}
      }
      jout(['ok'=>true,'msg'=>$act === 'approve' ? 'Возврат одобрен' : 'В возврате отказано']);
    }
    if ($act === 'refunded') {
      if ($r['status'] !== 'approved') fail('Сначала одобрите возврат');
      db()->prepare("UPDATE item_returns SET status='refunded' WHERE id=?")->execute([$id]);
      try { db()->prepare('INSERT INTO client_refunds (id,order_id,amount,reason,staff) VALUES (?,?,?,?,?)')->execute([gen('cr'), $r['order_id'], (int)$r['amount'], mb_substr('Возврат '.$r['code'], 0, 200), $who]); } catch (Exception $e) {}
      if (function_exists('wp_send_to_phone') && !empty($r['phone'])) { try { wp_send_to_phone(db(), $r['phone'], 'Деньги возвращены', 'По товару '.$r['code'].' деньги возвращены.', '/'); } catch (Exception $e) {} }
      jout(['ok'=>true,'msg'=>'Отмечено: деньги возвращены']);
    }
    fail('Неизвестное действие');
  }

  case 'scan_order':
  case 'warehouse_scan': {
    $s = authUser();
    $role = $s['role']; $sr = $s['staff_role'] ?? '';
    $wh = '';
    if ($role === 'partner') {
      try { $pq = db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $wh = $pq->fetchColumn() ?: ''; } catch (Exception $e) {}
    } elseif ($role === 'itc' && $sr === 'warehouse') {
      $wh = $s['supplier_id'] ?? '';
    } else {
      fail('Сканирование доступно оператору склада или партнёру', 403);
    }
    if (!$wh) fail('За вами не закреплён склад');
    $whoName = '';
    if ($role === 'partner') { try { $nq=db()->prepare('SELECT name FROM partners WHERE id=?'); $nq->execute([$s['supplier_id']]); $whoName=$nq->fetchColumn()?:'Партнёр'; } catch (Exception $e) { $whoName='Партнёр'; } }
    else { try { $nq=db()->prepare('SELECT name FROM warehouses WHERE id=?'); $nq->execute([$wh]); $whoName=($nq->fetchColumn()?:'Склад').' · оператор'; } catch (Exception $e) { $whoName='Оператор'; } }
    $d = body();
    $code = trim($d['code'] ?? '');
    $action = $d['action'] ?? 'receive';
    if ($role === 'itc' && $sr === 'warehouse') {
      list($wc_ignore, $wc_role) = wh_ctx($s);
      if ($wc_role === 'wh_worker' && $action === 'handover') fail('Выдача клиенту доступна кладовщику или управляющему складом', 403);
    }
    if ($code === '') fail('Пустой код');
    list($code, $box_seq, $box_w, $box_v) = parse_scan_code($code);
    if ($code === '') fail('Не удалось распознать код наклейки');
    /* Та же сверка по цифрам номера, что и в wh_order_lookup (25.09.2026). */
    $oq = db()->prepare("SELECT id,num,status,phone,addr_city,addr_name,warehouse_id,dest_warehouse_id,wh_received_at,wh_shipped_at,dest_received_at,picked_up_at FROM orders WHERE (num=? OR REGEXP_REPLACE(num,'[^0-9]','')=REGEXP_REPLACE(?,'[^0-9]','')) AND paid=1 AND (warehouse_id=? OR dest_warehouse_id=?)");
    $oq->execute([$code, $code, $wh, $wh]);
    $o = $oq->fetch();
    if (!$o) fail('Заказ '.$code.' не найден среди адресованных вашему складу');
    scan_key_check($o['id']);   // №284
    $places = order_places_ensure($o['id']);
    if ($box_seq > 0 && ($box_w === null || $box_v === null)) {
      $bl = order_box_list($o['id']);
      if (isset($bl[$box_seq-1])) { if ($box_w === null) $box_w = (float)$bl[$box_seq-1]['wt']; if ($box_v === null) $box_v = (float)$bl[$box_seq-1]['vol']; }
    }
    $asDest = (!empty($o['dest_warehouse_id']) && $o['dest_warehouse_id'] === $wh && $o['warehouse_id'] !== $wh);
    if ($asDest) {
      // Склад-получатель в РФ: приёмка контейнера/заказа и выдача клиенту
      if ($action === 'receive') {
        if (!$o['wh_shipped_at']) fail('Заказ ещё не отгружен со склада отправления (Китай)');
        if ($places > 1) {
          if ($box_seq < 1) fail('У заказа '.$places.' мест — отсканируйте наклейку с номером места (M1…M'.$places.')');
          if ($box_seq > $places) fail('Номер места '.$box_seq.' больше числа мест ('.$places.')');
          try { db()->prepare('INSERT INTO order_boxes (order_id,seq,dest_at) VALUES (?,?,NOW()) ON DUPLICATE KEY UPDATE dest_at=COALESCE(dest_at,NOW())')->execute([$o['id'],$box_seq]); }
          catch (Exception $e) { fail('Сначала выполните миграцию (order_boxes)'); }
          try { db()->prepare('UPDATE order_boxes SET weight=COALESCE(weight,?), volume=COALESCE(volume,?) WHERE order_id=? AND seq=?')->execute([$box_w,$box_v,$o['id'],$box_seq]); } catch (Exception $e) {}
          $cnt = 0; try { $cq=db()->prepare('SELECT COUNT(*) FROM order_boxes WHERE order_id=? AND dest_at IS NOT NULL'); $cq->execute([$o['id']]); $cnt=(int)$cq->fetchColumn(); } catch (Exception $e) {}
          wh_log_add($wh,$whoName,'dest_receive',$o['num'],'место '.$box_seq.'/'.$places);
          if ($cnt >= $places) {
            db()->prepare('UPDATE orders SET dest_received_at=NOW() WHERE id=?')->execute([$o['id']]);
            try { db()->prepare("UPDATE orders SET status='at_dest' WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {}
            if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '📦 Заказ '.$o['num'].' на складе выдачи', 'Ваш заказ (все '.$places.' мест) прибыл на склад в России и готов к выдаче.', '/');
            jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'name'=>$o['addr_name'],'msg'=>'Принято мест '.$cnt.'/'.$places.' — заказ на складе РФ','places'=>$places,'received_places'=>$cnt,'full'=>1]);
          }
          jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Принято место '.$box_seq.' · всего '.$cnt.' из '.$places,'places'=>$places,'received_places'=>$cnt,'full'=>0]);
        }
        if ($o['dest_received_at']) jout(['ok'=>true,'already'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Уже принят на складе РФ']);
        db()->prepare('UPDATE orders SET dest_received_at=NOW() WHERE id=?')->execute([$o['id']]);
        try { db()->prepare("UPDATE orders SET status='at_dest' WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {}
        wh_log_add($wh,$whoName,'dest_receive',$o['num'],$o['addr_city']);
        if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '📦 Заказ '.$o['num'].' на складе выдачи', 'Ваш заказ прибыл на склад в России и готов к выдаче.', '/');
        jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'name'=>$o['addr_name'],'msg'=>'Принят на складе РФ']);
      } elseif ($action === 'handover') {
        if ($o['picked_up_at']) jout(['ok'=>true,'already'=>true,'num'=>$o['num'],'name'=>$o['addr_name'],'msg'=>'Уже выдан клиенту']);
        if (!$o['dest_received_at']) fail('Заказ ещё не принят на складе получателя');
        db()->prepare('UPDATE orders SET picked_up_at=NOW() WHERE id=?')->execute([$o['id']]);
        try { db()->prepare("UPDATE orders SET status='done' WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {}
        wh_log_add($wh,$whoName,'handover',$o['num'],$o['addr_name']);
        if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '✅ Заказ '.$o['num'].' выдан', 'Спасибо за покупку в ИТК Мебель! Будем рады видеть вас снова.', '/');
        jout(['ok'=>true,'num'=>$o['num'],'name'=>$o['addr_name'],'msg'=>'Выдан клиенту ✓']);
      } else {
        fail('Этот склад — получатель: здесь приёмка и выдача, отгрузка не требуется');
      }
    }
    if ($action === 'receive') {
      if ($places > 1) {
        if ($box_seq < 1) fail('У заказа '.$places.' мест — отсканируйте наклейку с номером места (M1…M'.$places.')');
        if ($box_seq > $places) fail('Номер места '.$box_seq.' больше числа мест ('.$places.')');
        try { db()->prepare('INSERT INTO order_boxes (order_id,seq,origin_at) VALUES (?,?,NOW()) ON DUPLICATE KEY UPDATE origin_at=COALESCE(origin_at,NOW())')->execute([$o['id'],$box_seq]); }
        catch (Exception $e) { fail('Сначала выполните миграцию (order_boxes)'); }
        try { db()->prepare('UPDATE order_boxes SET weight=COALESCE(weight,?), volume=COALESCE(volume,?) WHERE order_id=? AND seq=?')->execute([$box_w,$box_v,$o['id'],$box_seq]); } catch (Exception $e) {}
        $cnt = 0; try { $cq=db()->prepare('SELECT COUNT(*) FROM order_boxes WHERE order_id=? AND origin_at IS NOT NULL'); $cq->execute([$o['id']]); $cnt=(int)$cq->fetchColumn(); } catch (Exception $e) {}
        wh_log_add($wh,$whoName,'receive',$o['num'],'место '.$box_seq.'/'.$places);
        if ($cnt >= $places) {
          if (!$o['wh_received_at']) db()->prepare('UPDATE orders SET wh_received_at=NOW() WHERE id=?')->execute([$o['id']]);
          try { db()->prepare("UPDATE orders SET status='at_warehouse' WHERE id=? AND status IN('created','confirmed')")->execute([$o['id']]); } catch (Exception $e) {}
          if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '📦 Заказ '.$o['num'].' на складе', 'Все '.$places.' мест приняты на складе ИТК в Китае.', '/');
          jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Принято мест '.$cnt.'/'.$places.' — заказ полностью на складе','places'=>$places,'received_places'=>$cnt,'full'=>1]);
        }
        jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Принято место '.$box_seq.' · всего '.$cnt.' из '.$places,'places'=>$places,'received_places'=>$cnt,'full'=>0]);
      }
      if ($o['wh_received_at']) jout(['ok'=>true,'already'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Уже на складе']);
      // габариты
      $act = isset($d['act_m3']) ? (float)$d['act_m3'] : 0;
      $dims = mb_substr(trim($d['dims'] ?? ''), 0, 48);
      $decl = order_decl_m3($o['id']);
      $box_ok = 1; $extra = 0; $checked = 0;
      if ($act > 0) {
        $checked = 1;
        $tol = max(0.01, $decl * 0.05);
        if (abs($act - $decl) > $tol) $box_ok = 0;
        if ($act > $decl) $extra = round(($act - $decl) * freight_per_m3(), 2);
        try { db()->prepare('UPDATE orders SET box_decl_m3=?,box_act_m3=?,box_dims=?,box_extra_rub=?,box_ok=?,box_checked=1 WHERE id=?')->execute([$decl,$act,$dims,$extra,$box_ok,$o['id']]); } catch (Exception $e) {}
      }
      // доп. данные приёмки: вес, ячейка, повреждение, частичная, фото
      $weight = isset($d['weight']) ? (float)$d['weight'] : 0;
      $cell = mb_substr(trim($d['cell'] ?? ''), 0, 40);
      $damage = !empty($d['damage']) ? 1 : 0;
      $dnote = mb_substr(trim($d['damage_note'] ?? ''), 0, 255);
      $partial = !empty($d['partial']) ? 1 : 0;
      $photo = trim($d['photo'] ?? '');
      if (strlen($photo) > 4000000) $photo = ''; // защита от слишком больших
      try { db()->prepare('UPDATE orders SET wh_weight=?,wh_cell=?,wh_damage=?,wh_damage_note=?,wh_partial=? WHERE id=?')->execute([$weight,$cell,$damage,$dnote,$partial,$o['id']]); } catch (Exception $e) {}
      if ($photo !== '') { try { db()->prepare('UPDATE orders SET wh_photo=? WHERE id=?')->execute([$photo,$o['id']]); } catch (Exception $e) {} }
      db()->prepare('UPDATE orders SET wh_received_at=NOW() WHERE id=?')->execute([$o['id']]);
      try { db()->prepare("UPDATE orders SET status='at_warehouse' WHERE id=? AND status IN('created','confirmed')")->execute([$o['id']]); } catch (Exception $e) {}
      wh_log_add($wh,$whoName,'receive',$o['num'],$damage?'повреждение':($box_ok?'габарит OK':'габарит не совпал'));
      if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '📦 Заказ '.$o['num'].' прибыл на склад', 'Ваш заказ принят на склад и готовится к выдаче.', '/');
      jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'name'=>$o['addr_name'],'msg'=>'Принят на склад',
            'box_ok'=>$box_ok,'box_checked'=>$checked,'decl_m3'=>round($decl,4),'act_m3'=>round($act,4),'extra_rub'=>$extra,'damage'=>$damage]);
    } elseif ($action === 'handover') {
      if ($o['picked_up_at']) jout(['ok'=>true,'already'=>true,'num'=>$o['num'],'name'=>$o['addr_name'],'msg'=>'Уже выдан клиенту']);
      if (!$o['wh_received_at']) fail('Заказ ещё не прибыл на склад');
      db()->prepare('UPDATE orders SET picked_up_at=NOW() WHERE id=?')->execute([$o['id']]);
      try { db()->prepare("UPDATE orders SET status='done' WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {}
      wh_log_add($wh,$whoName,'handover',$o['num'],$o['addr_name']);
      if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '✅ Заказ '.$o['num'].' выдан', 'Спасибо за покупку в ИТК Мебель! Будем рады видеть вас снова.', '/');
      jout(['ok'=>true,'num'=>$o['num'],'name'=>$o['addr_name'],'msg'=>'Выдан клиенту ✓']);
    } else { // ship
      if (!$o['wh_received_at']) fail('Сначала примите заказ на склад');
      if ($o['wh_shipped_at']) jout(['ok'=>true,'already'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Уже отгружен']);
      $dest = trim($d['dest_wh'] ?? '');
      if ($dest === '' && !empty($o['dest_warehouse_id'])) $dest = $o['dest_warehouse_id'];
      if ($dest !== '') {
        if ($dest === $wh) fail('Склад-получатель не может совпадать со складом отправления');
        try { $dc=db()->prepare('SELECT id FROM warehouses WHERE id=?'); $dc->execute([$dest]); if (!$dc->fetchColumn()) fail('Склад-получатель не найден'); } catch (Exception $e) {}
        db()->prepare('UPDATE orders SET dest_warehouse_id=?, wh_shipped_at=NOW() WHERE id=?')->execute([$dest,$o['id']]);
        try { db()->prepare("UPDATE orders SET status='shipping' WHERE id=? AND status NOT IN('done')")->execute([$o['id']]); } catch (Exception $e) {}
        wh_log_add($wh,$whoName,'ship',$o['num'],'→ склад РФ');
        if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '🚚 Заказ '.$o['num'].' в пути в Россию', 'Ваш заказ отгружен со склада в Китае и направляется на склад выдачи в России.', '/');
        jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Отгружен → склад РФ (в пути)']);
      } else {
        db()->prepare('UPDATE orders SET wh_shipped_at=NOW() WHERE id=?')->execute([$o['id']]);
        try { db()->prepare("UPDATE orders SET status='delivering' WHERE id=? AND status NOT IN('done')")->execute([$o['id']]); } catch (Exception $e) {}
        wh_log_add($wh,$whoName,'ship',$o['num'],$o['addr_city']);
        if (function_exists('wp_send_to_phone') && !empty($o['phone'])) wp_send_to_phone(db(), $o['phone'], '🚚 Заказ '.$o['num'].' едет к вам', 'Ваш заказ отгружен со склада и направляется на выдачу.', '/');
        jout(['ok'=>true,'num'=>$o['num'],'city'=>$o['addr_city'],'msg'=>'Отгружен со склада']);
      }
    }
  }

  // ---- ИТК БУХГАЛТЕРИЯ: заказы по стадиям + оплата поставщику ----
  case 'accounting_list': {
    $s = authUser('itc');
    require_staff($s, ['accountant','chief_accountant']);
    $rows = [];
    $hasCny = true; try { db()->query('SELECT goods_cny FROM products LIMIT 1'); } catch (Exception $e) { $hasCny = false; }
    try {
      $hasDsCol = true;
      try { db()->query('SELECT ds FROM order_items LIMIT 1'); } catch (Exception $e) { $hasDsCol = false; }
      // Дроп-позиции в инвойсную цепочку не попадают — они оплачиваются через выкуп (Alipay Jinjia)
      $dsSkip = $hasDsCol ? " AND i.ds=0 " : " AND NOT EXISTS(SELECT 1 FROM ds_products dz WHERE dz.product_id=i.product_id) ";
      $sql = "SELECT o.id, o.num, o.status, UNIX_TIMESTAMP(o.created_at)*1000 ts,
                     o.wh_received_at, o.box_checked, o.box_ok, o.box_extra_rub, o.box_decl_m3, o.box_act_m3, o.box_deduct,
                     i.supplier_id, s.name sup_name, s.phone sup_phone, s.pay_company, s.pay_moment,
                     SUM(i.price*i.qty) sale, SUM(i.qty) units,
                     ".($hasCny ? "COALESCE(SUM(p.goods_cny*i.qty),0)" : "0")." owed_cny,
                     MIN(i.paid_supplier) paid_min,
                     UNIX_TIMESTAMP(a.accepted_at)*1000 acc_ts
                FROM order_items i
                JOIN orders o ON o.id=i.order_id AND o.paid=1 ".$dsSkip."
                LEFT JOIN suppliers s ON s.id=i.supplier_id
                ".($hasCny ? "LEFT JOIN products p ON p.id=i.product_id" : "")."
                LEFT JOIN order_accept a ON a.order_id=i.order_id AND a.supplier_id=i.supplier_id
               GROUP BY o.id, i.supplier_id
               ORDER BY (o.wh_received_at IS NOT NULL AND MIN(i.paid_supplier)=0) DESC, o.created_at DESC LIMIT 500";
      $rows = db()->query($sql)->fetchAll();
      $shipped_set = ['at_warehouse','in_container','shipping','delivering','done'];
      // суммы оплат по (заказ, поставщик)
      $payMap = [];
      try { foreach (db()->query("SELECT order_id,supplier_id,SUM(amount_cny) pc FROM supplier_payments GROUP BY order_id,supplier_id")->fetchAll() as $pm) { $payMap[$pm['order_id'].'|'.$pm['supplier_id']] = (float)$pm['pc']; } } catch (Exception $e) {}
      foreach ($rows as &$r) {
        $r['ts']=(int)$r['ts']; $r['sale']=(int)$r['sale']; $r['units']=(int)$r['units']; $r['owed_cny']=(int)round($r['owed_cny']);
        $r['accepted']=$r['acc_ts']?1:0;
        $r['shipped']=in_array($r['status'],$shipped_set,true)?1:0;
        $r['wh_received']=!empty($r['wh_received_at'])?1:0;
        $r['paid_cny']=(int)round($payMap[$r['id'].'|'.$r['supplier_id']] ?? 0);
        $r['remain_cny']=max(0,$r['owed_cny']-$r['paid_cny']);
        $r['paid_supplier']=((int)$r['paid_min']===1 || ($r['owed_cny']>0 && $r['remain_cny']<=0 && $r['paid_cny']>0))?1:0;
        $r['box_checked']=(int)$r['box_checked']; $r['box_ok']=(int)$r['box_ok']; $r['box_extra_rub']=(int)round($r['box_extra_rub']); $r['box_deduct']=(int)$r['box_deduct'];
        $r['box_decl_m3']=(float)$r['box_decl_m3']; $r['box_act_m3']=(float)$r['box_act_m3'];
        unset($r['wh_received_at'],$r['paid_min'],$r['acc_ts']);
      } unset($r);
    } catch (Exception $e) { $rows=[]; }
    jout(['ok'=>true,'rows'=>$rows]);
  }

  // ---- ИТК БУХГАЛТЕРИЯ: отметить оплату поставщику по заказу ----
  case 'acct_pay': {
    $s = authUser('itc');
    require_staff($s, ['accountant','chief_accountant']);
    $d = body();
    $oid = trim($d['order_id'] ?? '');
    $sid = trim($d['supplier_id'] ?? '');
    if (!$oid || !$sid) fail('Не указан заказ/поставщик');
    $val = isset($d['paid']) ? (!empty($d['paid']) ? 1 : 0) : 1;
    try {
      db()->prepare('UPDATE order_items SET paid_supplier=? WHERE order_id=? AND supplier_id=?')->execute([$val, $oid, $sid]);
    } catch (Exception $e) { fail('Сначала выполните миграцию (paid_supplier)'); }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'acct_pay', 'order', $oid, ($val?'оплачено':'снято').' · поставщик '.$sid);
    jout(['ok'=>true,'paid'=>$val]);
  }

  // ---- БУХГАЛТЕРИЯ/БОСС: решение об удержании за габарит ----
  case 'acct_box_deduct': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $d = body();
    $oid = trim($d['order_id'] ?? '');
    if (!$oid) fail('Не указан заказ');
    $apply = !empty($d['apply']) ? 1 : 0;
    try { db()->prepare('UPDATE orders SET box_deduct=? WHERE id=?')->execute([$apply, $oid]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (box_deduct)'); }
    itc_log_add(mb_substr(trim($d['by']??''),0,120),'box_deduct','order',$oid,$apply?'удержать':'не удерживать');
    jout(['ok'=>true,'apply'=>$apply]);
  }

  // ---- БУХГАЛТЕРИЯ: записать платёж поставщику (аванс/остаток/полностью) ----
  case 'acct_pay_record': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $d = body();
    $oid = trim($d['order_id'] ?? ''); $sid = trim($d['supplier_id'] ?? '');
    if (!$oid || !$sid) fail('Не указан заказ/поставщик');
    $kind = $d['kind'] ?? 'full';
    // сколько должны этому поставщику по заказу (¥)
    $owed = 0;
    try { $oq=db()->prepare('SELECT COALESCE(SUM(p.goods_cny*i.qty),0) FROM order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=? AND i.supplier_id=?'); $oq->execute([$oid,$sid]); $owed=(float)$oq->fetchColumn(); } catch (Exception $e) {}
    $paid = 0;
    try { $pq=db()->prepare('SELECT COALESCE(SUM(amount_cny),0) FROM supplier_payments WHERE order_id=? AND supplier_id=?'); $pq->execute([$oid,$sid]); $paid=(float)$pq->fetchColumn(); } catch (Exception $e) {}
    $remain = max(0, $owed - $paid);
    $amt = isset($d['amount_cny']) && $d['amount_cny']!=='' ? (float)$d['amount_cny'] : 0;
    if ($kind === 'advance' && $amt<=0) $amt = round($owed * 0.30, 2);
    if (($kind === 'balance' || $kind === 'full') && $amt<=0) $amt = $remain;
    if ($amt <= 0) fail('Нечего оплачивать (сумма 0)');
    $kurs = (float)get_settings()['kurs_cny'];
    $rub = round($amt * $kurs, 2);
    try {
      db()->prepare('INSERT INTO supplier_payments (id,order_id,supplier_id,amount_cny,amount_rub,kurs,kind,note,staff) VALUES (?,?,?,?,?,?,?,?,?)')
          ->execute([gen('sp'),$oid,$sid,$amt,$rub,$kurs,$kind,mb_substr(trim($d['note']??''),0,200),mb_substr(trim($d['by']??''),0,120)]);
    } catch (Exception $e) { fail('Сначала выполните миграцию (supplier_payments)'); }
    // полностью оплачено → флаг
    $paid2 = $paid + $amt;
    if ($owed>0 && $paid2 >= $owed) { try { db()->prepare('UPDATE order_items SET paid_supplier=1 WHERE order_id=? AND supplier_id=?')->execute([$oid,$sid]); } catch (Exception $e) {} }
    itc_log_add(mb_substr(trim($d['by']??''),0,120),'acct_pay','order',$oid,$kind.' ¥'.$amt.' пост.'.$sid);
    jout(['ok'=>true,'amount_cny'=>$amt,'amount_rub'=>$rub,'paid_cny'=>$paid2,'owed_cny'=>$owed]);
  }

  // ---- БУХГАЛТЕРИЯ: реестр всех платежей ----
  case 'acct_ledger': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $items = [];
    try {
      foreach (db()->query("SELECT sp.id,sp.order_id,o.num,sp.amount_cny,sp.amount_rub,sp.kind,sp.staff,UNIX_TIMESTAMP(sp.created_at)*1000 ts, s.name nm FROM supplier_payments sp LEFT JOIN orders o ON o.id=sp.order_id LEFT JOIN suppliers s ON s.id=sp.supplier_id ORDER BY sp.created_at DESC LIMIT 500")->fetchAll() as $r) {
        $items[] = ['type'=>'supplier','ts'=>(int)$r['ts'],'num'=>$r['num'],'name'=>$r['nm'],'cny'=>(float)$r['amount_cny'],'rub'=>(float)$r['amount_rub'],'kind'=>$r['kind'],'staff'=>$r['staff']];
      }
    } catch (Exception $e) {}
    try {
      foreach (db()->query("SELECT cr.id,cr.order_id,o.num,cr.amount,cr.reason,cr.staff,UNIX_TIMESTAMP(cr.created_at)*1000 ts FROM client_refunds cr LEFT JOIN orders o ON o.id=cr.order_id ORDER BY cr.created_at DESC LIMIT 300")->fetchAll() as $r) {
        $items[] = ['type'=>'refund','ts'=>(int)$r['ts'],'num'=>$r['num'],'name'=>$r['reason'],'cny'=>0,'rub'=>-(float)$r['amount'],'kind'=>'refund','staff'=>$r['staff']];
      }
    } catch (Exception $e) {}
    try {
      foreach (db()->query("SELECT pp.id,pp.amount,pp.note,pp.staff,UNIX_TIMESTAMP(pp.created_at)*1000 ts, pt.name nm FROM partner_payouts pp LEFT JOIN partners pt ON pt.id=pp.partner_id ORDER BY pp.created_at DESC LIMIT 300")->fetchAll() as $r) {
        $items[] = ['type'=>'partner','ts'=>(int)$r['ts'],'num'=>'','name'=>$r['nm'],'cny'=>0,'rub'=>-(float)$r['amount'],'kind'=>'payout','staff'=>$r['staff']];
      }
    } catch (Exception $e) {}
    usort($items, function($a,$b){ return $b['ts']-$a['ts']; });
    jout(['ok'=>true,'items'=>$items]);
  }

  // ---- БУХГАЛТЕРИЯ: долги — кредиторка, дебиторка, партнёры ----
  case 'acct_debts': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    // кредиторка: по поставщикам (должны ¥)
    $creditors = [];
    try {
      $payMap = [];
      foreach (db()->query("SELECT supplier_id,SUM(amount_cny) pc FROM supplier_payments GROUP BY supplier_id")->fetchAll() as $pm) $payMap[$pm['supplier_id']]=(float)$pm['pc'];
      foreach (db()->query("SELECT i.supplier_id, s.name nm, s.phone ph, COALESCE(SUM(p.goods_cny*i.qty),0) owed, COUNT(DISTINCT i.order_id) orders FROM order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1 LEFT JOIN products p ON p.id=i.product_id LEFT JOIN suppliers s ON s.id=i.supplier_id GROUP BY i.supplier_id")->fetchAll() as $r) {
        $owed=(float)$r['owed']; $paid=$payMap[$r['supplier_id']]??0; $bal=$owed-$paid;
        if ($bal>0.5) $creditors[] = ['name'=>$r['nm'],'phone'=>$r['ph'],'owed'=>round($owed),'paid'=>round($paid),'balance'=>round($bal),'orders'=>(int)$r['orders']];
      }
      usort($creditors,function($a,$b){return $b['balance']-$a['balance'];});
    } catch (Exception $e) {}
    // дебиторка: заказы не оплачены клиентом
    $debtors = []; $deb_total = 0;
    try {
      foreach (db()->query("SELECT num,total,addr_name,addr_city,UNIX_TIMESTAMP(created_at)*1000 ts FROM orders WHERE paid=0 ORDER BY created_at DESC LIMIT 200")->fetchAll() as $r) {
        $debtors[] = ['num'=>$r['num'],'total'=>(int)$r['total'],'name'=>$r['addr_name'],'city'=>$r['addr_city'],'ts'=>(int)$r['ts']];
        $deb_total += (int)$r['total'];
      }
    } catch (Exception $e) {}
    // партнёры: начислено vs выплачено
    $partners = [];
    try {
      $poMap = [];
      foreach (db()->query("SELECT partner_id,SUM(amount) a FROM partner_payouts GROUP BY partner_id")->fetchAll() as $pm) $poMap[$pm['partner_id']]=(float)$pm['a'];
      foreach (db()->query("SELECT id,name,phone,warehouse_id,markup,share,status,payout_req FROM partners WHERE status='active'")->fetchAll() as $p) {
        $wh_kind='hub';
        if($p['warehouse_id']){ try{ $kq=db()->prepare("SELECT kind FROM warehouses WHERE id=?"); $kq->execute([$p['warehouse_id']]); $wh_kind=$kq->fetchColumn() ?: 'hub'; }catch(Exception $e){ $wh_kind='hub'; } }
        $pct = itc_partner_pct($wh_kind, $p['warehouse_id']);
        $cost = $p['warehouse_id'] ? itc_partner_turnover($p['warehouse_id'], $wh_kind) : 0;
        $accrued = round($cost*$pct/100);
        $paidp = $poMap[$p['id']]??0; $bal=$accrued-$paidp;
        // принял ли партнёр текущую редакцию условий — это и есть заключённое соглашение
        itc_offer_ensure();
        $ofVer=''; $ofTs=null;
        try { $oq=db()->prepare('SELECT ver, UNIX_TIMESTAMP(accepted_at)*1000 ts FROM partner_offer WHERE partner_id=? ORDER BY id DESC LIMIT 1');
              $oq->execute([$p['id']]); $orow=$oq->fetch();
              if ($orow) { $ofVer=(string)$orow['ver']; $ofTs=$orow['ts']; } } catch (Exception $e) {}
        $partners[] = ['id'=>$p['id'],'name'=>$p['name'],'phone'=>$p['phone'],'accrued'=>$accrued,'paid'=>round($paidp),'balance'=>round($bal),'requested'=>(int)$p['payout_req'],'pct'=>$pct,
                       'offer_ver'=>$ofVer,'offer_ts'=>$ofTs,'offer_ok'=>($ofVer===ITC_OFFER_VER?1:0)];
      }
      usort($partners,function($a,$b){return $b['balance']-$a['balance'];});
    } catch (Exception $e) {}
    jout(['ok'=>true,'creditors'=>$creditors,'debtors'=>$debtors,'debtors_total'=>$deb_total,'partners'=>$partners]);
  }

  // ---- БУХГАЛТЕРИЯ: выплата партнёру ----
  case 'acct_partner_payout': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $d = body(); $pid = trim($d['partner_id'] ?? ''); $amt=(float)($d['amount'] ?? 0);
    if (!$pid || $amt<=0) fail('Укажите партнёра и сумму');
    try { db()->prepare('INSERT INTO partner_payouts (id,partner_id,amount,note,staff) VALUES (?,?,?,?,?)')->execute([gen('po'),$pid,$amt,mb_substr(trim($d['note']??''),0,200),mb_substr(trim($d['by']??''),0,120)]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (partner_payouts)'); }
    try { db()->prepare('UPDATE partners SET payout_req=0 WHERE id=?')->execute([$pid]); } catch (Exception $e) {}
    itc_log_add(mb_substr(trim($d['by']??''),0,120),'partner_payout','partner',$pid,'₽'.$amt);
    jout(['ok'=>true]);
  }

  // ---- БУХГАЛТЕРИЯ: поступления ЮKassa + возвраты ----
  case 'acct_clients': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $income = []; $inc_total = 0;
    try {
      foreach (db()->query("SELECT id,num,total,payment_id,addr_name,addr_city,UNIX_TIMESTAMP(created_at)*1000 ts FROM orders WHERE paid=1 ORDER BY created_at DESC LIMIT 300")->fetchAll() as $r) {
        $income[] = ['id'=>$r['id'],'num'=>$r['num'],'total'=>(int)$r['total'],'pid'=>$r['payment_id'],'name'=>$r['addr_name'],'city'=>$r['addr_city'],'ts'=>(int)$r['ts']];
        $inc_total += (int)$r['total'];
      }
    } catch (Exception $e) {}
    $refunds = []; $ref_total = 0;
    try {
      foreach (db()->query("SELECT cr.amount,cr.reason,cr.staff,o.num,UNIX_TIMESTAMP(cr.created_at)*1000 ts FROM client_refunds cr LEFT JOIN orders o ON o.id=cr.order_id ORDER BY cr.created_at DESC LIMIT 200")->fetchAll() as $r) {
        $refunds[] = ['num'=>$r['num'],'amount'=>(int)$r['amount'],'reason'=>$r['reason'],'staff'=>$r['staff'],'ts'=>(int)$r['ts']];
        $ref_total += (int)$r['amount'];
      }
    } catch (Exception $e) {}
    jout(['ok'=>true,'income'=>$income,'income_total'=>$inc_total,'refunds'=>$refunds,'refunds_total'=>$ref_total]);
  }

  // ---- БУХГАЛТЕРИЯ: оформить возврат клиенту ----
  case 'acct_refund': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $d = body(); $oid = trim($d['order_id'] ?? ''); $amt=(float)($d['amount'] ?? 0);
    if (!$oid || $amt<=0) fail('Укажите заказ и сумму возврата');
    try { db()->prepare('INSERT INTO client_refunds (id,order_id,amount,reason,staff) VALUES (?,?,?,?,?)')->execute([gen('cr'),$oid,$amt,mb_substr(trim($d['reason']??''),0,200),mb_substr(trim($d['by']??''),0,120)]); }
    catch (Exception $e) { fail('Сначала выполните миграцию (client_refunds)'); }
    itc_log_add(mb_substr(trim($d['by']??''),0,120),'refund','order',$oid,'₽'.$amt);
    jout(['ok'=>true]);
  }

  // ---- БУХГАЛТЕРИЯ: отчёт за период ----
  case 'acct_report': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $d = body();
    $from = trim($d['from'] ?? ''); $to = trim($d['to'] ?? '');
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)) $from = date('Y-m-01');
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)) $to = date('Y-m-d');
    $to2 = $to.' 23:59:59';
    $vat = (float)get_settings()['vat']; $kurs=(float)get_settings()['kurs_cny'];
    $revenue=0;$orders_cnt=0;
    try { $q=db()->prepare("SELECT COALESCE(SUM(total),0) r, COUNT(*) c FROM orders WHERE paid=1 AND created_at BETWEEN ? AND ?"); $q->execute([$from,$to2]); $row=$q->fetch(); $revenue=(int)$row['r']; $orders_cnt=(int)$row['c']; } catch (Exception $e) {}
    $sup_paid_rub=0;
    try { $q=db()->prepare("SELECT COALESCE(SUM(amount_rub),0) FROM supplier_payments WHERE created_at BETWEEN ? AND ?"); $q->execute([$from,$to2]); $sup_paid_rub=(int)$q->fetchColumn(); } catch (Exception $e) {}
    $refunds_rub=0;
    try { $q=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM client_refunds WHERE created_at BETWEEN ? AND ?"); $q->execute([$from,$to2]); $refunds_rub=(int)$q->fetchColumn(); } catch (Exception $e) {}
    $payouts_rub=0;
    try { $q=db()->prepare("SELECT COALESCE(SUM(amount),0) FROM partner_payouts WHERE created_at BETWEEN ? AND ?"); $q->execute([$from,$to2]); $payouts_rub=(int)$q->fetchColumn(); } catch (Exception $e) {}
    // себестоимость товара (¥→₽) по оплаченным заказам периода
    $cogs_rub=0;
    try { $q=db()->prepare("SELECT COALESCE(SUM(p.goods_cny*i.qty),0) FROM orders o JOIN order_items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id WHERE o.paid=1 AND o.created_at BETWEEN ? AND ?"); $q->execute([$from,$to2]); $cogs_rub=(int)round((float)$q->fetchColumn()*$kurs); } catch (Exception $e) {}
    $net_revenue = $revenue - $refunds_rub;
    $vat_due = (int)round($net_revenue * $vat / (100+$vat)); // НДС в т.ч.
    $margin = $net_revenue - $cogs_rub - $payouts_rub;
    jout(['ok'=>true,'from'=>$from,'to'=>$to,'revenue'=>$revenue,'orders'=>$orders_cnt,'refunds'=>$refunds_rub,'net_revenue'=>$net_revenue,
          'supplier_paid'=>$sup_paid_rub,'partner_payouts'=>$payouts_rub,'cogs'=>$cogs_rub,'vat_rate'=>$vat,'vat_due'=>$vat_due,'margin'=>$margin]);
  }

  // ---- ИТК: приёмка заказов поставщиками (подтверждено / нет) ----
  case 'acceptance_list': {
    authUser('itc');
    $rows = [];
    try {
      $rows = db()->query(
        "SELECT o.id, o.num, o.status, UNIX_TIMESTAMP(o.created_at)*1000 ts,
                i.supplier_id, s.name sup_name, s.phone sup_phone,
                SUM(i.price*i.qty) sum, SUM(i.qty) units,
                UNIX_TIMESTAMP(a.accepted_at)*1000 acc_ts,
                SUM(CASE WHEN pc.status IN ('ordered','received') THEN 1 ELSE 0 END) bought_cnt,
                COUNT(pc.id) proc_cnt,
                MAX(dp.source_url) src_url
           FROM order_items i
           JOIN orders o ON o.id = i.order_id AND o.paid = 1
           LEFT JOIN suppliers s ON s.id = i.supplier_id
           LEFT JOIN order_accept a ON a.order_id = i.order_id AND a.supplier_id = i.supplier_id
           LEFT JOIN ds_procurement pc ON pc.order_id = i.order_id AND pc.product_id = i.product_id
           LEFT JOIN ds_products dp ON dp.product_id = i.product_id
          WHERE NOT EXISTS (SELECT 1 FROM ds_procurement x WHERE x.order_id = i.order_id AND x.product_id = i.product_id)
          GROUP BY o.id, i.supplier_id
          ORDER BY (a.accepted_at IS NULL) DESC, o.created_at DESC LIMIT 400")->fetchAll();
      foreach ($rows as &$r) {
        $r['ts'] = (int)$r['ts']; $r['sum'] = (int)$r['sum']; $r['units'] = (int)$r['units'];
        $r['accepted'] = $r['acc_ts'] ? 1 : 0; $r['acc_ts'] = $r['acc_ts'] ? (int)$r['acc_ts'] : 0;
        // Порядок: сперва выкуп, и только потом подтверждение склада.
        $r['bought'] = ((int)($r['proc_cnt'] ?? 0) > 0 && (int)($r['bought_cnt'] ?? 0) >= (int)$r['proc_cnt']) ? 1 : 0;
      } unset($r);
      /* Состав заказа с фото (25.09.2026). Раньше приёмка видела только номер,
         поставщика и сумму — кладовщик не понимал, что именно принимает.
         Название берём из карточки, а если её удалили — из самого заказа. */
      $ids = array_values(array_unique(array_map(function($x){ return $x['id']; }, $rows)));
      if ($ids) {
        $in = implode(',', array_fill(0, count($ids), '?'));
        $q2 = db()->prepare("SELECT i.id iid, i.product_id pid, i.order_id, i.supplier_id, i.qty,
                                    COALESCE(NULLIF(p.name,''), i.name) nm, p.img img
                               FROM order_items i LEFT JOIN products p ON p.id=i.product_id
                              WHERE i.order_id IN ($in)");
        $q2->execute($ids);
        $by = [];
        foreach ($q2->fetchAll() as $it) {
          $k = $it['order_id'].'|'.(string)$it['supplier_id'];
          if (!isset($by[$k])) $by[$k] = [];
          if (count($by[$k]) < 8) $by[$k][] = ['iid'=>$it['iid'], 'pid'=>$it['pid'], 'nm'=>$it['nm'], 'img'=>$it['img'], 'qty'=>(int)$it['qty']];
        }
        foreach ($rows as &$r2) { $r2['items'] = $by[$r2['id'].'|'.(string)$r2['supplier_id']] ?? []; }
        unset($r2);
      }
    } catch (Exception $e) { $rows = []; }
    /* ВЫКУП С 1688 — ОТДЕЛЬНО ПО КАЖДОЙ ПОЗИЦИИ (обновление №267).
       БЫЛО: всё, что в заказе числится за Jinjia, шло одной карточкой. Но эти
       товары выкупаются в разных магазинах 1688, едут разными машинами и
       приходят в разные дни — одна общая кнопка «Товар доехал» не подходила.
       ТЕПЕРЬ: у каждой выкупаемой позиции своя карточка и своя приёмка. Признак
       «доехал» — строка выкупа в статусе received. Когда приняты все позиции
       заказа от этого поставщика, заказ отмечается принятым целиком, как раньше. */
    try {
      $it = db()->query(
        "SELECT i.id item_id, i.product_id, o.id, o.num, o.status, UNIX_TIMESTAMP(o.created_at)*1000 ts,
                i.supplier_id, s.name sup_name, s.phone sup_phone,
                (i.price*i.qty) sum, i.qty units,
                MAX(pc.status='received') acc, MAX(pc.status IN ('ordered','received')) bought,
                MIN(pc.status IN ('ordered','received')) bought_all,
                UNIX_TIMESTAMP(MAX(pc.received_at))*1000 acc_ts,
                MAX(dp.source_url) src_url,
                COALESCE(NULLIF(p.name,''), i.name) nm, p.img img
           FROM order_items i
           JOIN orders o ON o.id = i.order_id AND o.paid = 1
           JOIN ds_procurement pc ON pc.order_id = i.order_id AND pc.product_id = i.product_id
           LEFT JOIN suppliers s ON s.id = i.supplier_id
           LEFT JOIN ds_products dp ON dp.product_id = i.product_id
           LEFT JOIN products p ON p.id = i.product_id
          GROUP BY i.id
          ORDER BY o.created_at DESC, i.id ASC LIMIT 600")->fetchAll();
      $cnt = [];
      foreach ($it as $x) { $cnt[$x['id']] = ($cnt[$x['id']] ?? 0) + 1; }
      $pos = [];
      foreach ($it as $x) {
        $pos[$x['id']] = ($pos[$x['id']] ?? 0) + 1;
        $acc = (int)$x['acc'] === 1;
        $rows[] = ['id'=>$x['id'], 'num'=>$x['num'], 'status'=>$x['status'], 'ts'=>(int)$x['ts'],
                   'item_id'=>$x['item_id'], 'product_id'=>$x['product_id'],
                   'pos'=>$pos[$x['id']], 'pos_of'=>$cnt[$x['id']],
                   'supplier_id'=>$x['supplier_id'], 'sup_name'=>$x['sup_name'], 'sup_phone'=>$x['sup_phone'],
                   'sum'=>(int)$x['sum'], 'units'=>(int)$x['units'],
                   'accepted'=>$acc ? 1 : 0, 'acc_ts'=>($acc && $x['acc_ts']) ? (int)$x['acc_ts'] : 0,
                   'bought'=>((int)$x['bought'] === 1 && (int)$x['bought_all'] === 1) ? 1 : 0,
                   'src_url'=>$x['src_url'],
                   'items'=>[['iid'=>$x['item_id'], 'pid'=>$x['product_id'], 'nm'=>$x['nm'], 'img'=>$x['img'], 'qty'=>(int)$x['units']]]];
      }
      /* №309: заказы, принятые раньше, — сразу «на складе в Гуанчжоу» */
      try { $__seen = []; foreach ($rows as $__r) { if (!empty($__r['accepted']) && !isset($__seen[$__r['id']])) { $__seen[$__r['id']] = 1; itc_order_mark_at_wh($__r['id']); } } } catch (Throwable $e) {}
      usort($rows, function($a, $b){ if ($a['accepted'] !== $b['accepted']) return $a['accepted'] - $b['accepted']; if ($b['ts'] !== $a['ts']) return $b['ts'] - $a['ts']; if ($a['id'] !== $b['id']) return strcmp($a['id'], $b['id']); return (int)($a['pos'] ?? 0) - (int)($b['pos'] ?? 0); });
    } catch (Exception $e) {}
    /* №274: СВОЙ НОМЕР У КАЖДОГО ТОВАРА. Один товар — одна наклейка — свой номер
       (М-1069-1, М-1069-2…). Товары одного заказа выкупаются в разных местах,
       приходят на склад в разные дни и едут отдельно, поэтому и наклейка у каждого
       своя. Номер постоянный: раз выдан — не меняется. Плюс пункт выдачи заказа —
       он печатается на наклейке. */
    try {
      $oids = array_values(array_unique(array_map(function($x){ return $x['id']; }, $rows)));
      $sub = itc_item_subno_many($oids);
      $keys = itc_item_keys_many($oids);   // №284
      $pvz = [];
      if ($oids) {
        $in = implode(',', array_fill(0, count($oids), '?'));
        $pq = db()->prepare("SELECT o.id, w.name, w.code FROM orders o LEFT JOIN warehouses w ON w.id=o.warehouse_id WHERE o.id IN ($in)");
        $pq->execute($oids);
        $pvzc = [];
        foreach ($pq->fetchAll() as $pr) { $pvz[$pr['id']] = (string)($pr['name'] ?? ''); $pvzc[$pr['id']] = (string)($pr['code'] ?? ''); }
      }
      foreach ($rows as &$r3) {
        $r3['pvz'] = $pvz[$r3['id']] ?? ''; $r3['pvz_code'] = $pvzc[$r3['id']] ?? '';
        if (!empty($r3['items']) && is_array($r3['items'])) {
          foreach ($r3['items'] as &$it3) {
            if (!empty($it3['iid']) && isset($sub[$it3['iid']])) { $it3['code'] = $r3['num'].'-'.$sub[$it3['iid']]; $it3['key'] = $keys[$it3['iid']] ?? ''; }
          } unset($it3);
        }
      } unset($r3);
    } catch (Exception $e) {}
    jout(['ok' => true, 'rows' => $rows]);
  }

  // ---- профиль/реквизиты поставщика (своё) ----
  case 'supplier_profile': {
    $s = authUser('supplier');
    $q = db()->prepare('SELECT id,name,zh,phone,jurisdiction,contact,email,status,reg_data,mod_status,pay_company,contract_no,contract_status,contract_signed_url,UNIX_TIMESTAMP(contract_at)*1000 cat FROM suppliers WHERE id=?');
    $q->execute([$s['supplier_id']]);
    $row = $q->fetch();
    if (!$row) fail('Поставщик не найден');
    $row['reg_data'] = json_decode($row['reg_data'] ?: '{}', true) ?: [];
    $row['cat'] = (int)$row['cat'];
    jout(['ok' => true, 'profile' => $row]);
  }

  // ---- сохранение реквизитов поставщика ----
  case 'supplier_profile_save': {
    $s = authUser('supplier');
    $d = body();
    $name = trim($d['name'] ?? '');
    if (!$name) fail('Укажите название компании');
    $zh = trim($d['zh'] ?? '');
    $contact = trim($d['contact'] ?? '');
    $email = trim($d['email'] ?? '');
    $jur = (($d['jurisdiction'] ?? 'ru') === 'cn') ? 'cn' : 'ru';
    $reg = $d['reg_data'] ?? [];
    if (!is_array($reg)) $reg = [];
    db()->prepare('UPDATE suppliers SET name=?,zh=?,contact=?,email=?,jurisdiction=?,reg_data=? WHERE id=?')
        ->execute([$name, $zh, $contact, $email, $jur, json_encode($reg, JSON_UNESCAPED_UNICODE), $s['supplier_id']]);
    $q = db()->prepare('SELECT id,name,zh,phone,jurisdiction,contact,email,status,reg_data FROM suppliers WHERE id=?');
    $q->execute([$s['supplier_id']]);
    $row = $q->fetch();
    $row['reg_data'] = json_decode($row['reg_data'] ?: '{}', true) ?: [];
    jout(['ok' => true, 'profile' => $row]);
  }

  // ---- авто-перевод текста (бесплатный публичный сервис; для продакшена можно подключить DeepL/Yandex с ключом) ----
  case 'translate': {
    authUser();
    $d = body();
    $text = trim($d['text'] ?? '');
    $from = preg_replace('/[^a-zA-Z\-]/', '', (string)($d['from'] ?? 'zh-CN')) ?: 'auto';
    $to   = preg_replace('/[^a-zA-Z\-]/', '', (string)($d['to'] ?? 'ru')) ?: 'ru';
    if ($text === '') fail('Пустой текст');
    if (mb_strlen($text) > 5000) $text = mb_substr($text, 0, 5000);
    $url = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=' . urlencode($from) . '&tl=' . urlencode($to) . '&dt=t&q=' . urlencode($text);
    $resp = '';
    if (function_exists('curl_init')) {
      $ch = curl_init($url);
      curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 12, CURLOPT_USERAGENT => 'Mozilla/5.0']);
      $resp = curl_exec($ch);
      curl_close($ch);
    } else {
      $resp = @file_get_contents($url);
    }
    if (!$resp) fail('Сервис перевода недоступен, попробуйте позже', 502);
    $j = json_decode($resp, true);
    if (!is_array($j) || !isset($j[0]) || !is_array($j[0])) fail('Не удалось разобрать перевод', 502);
    $outTxt = '';
    foreach ($j[0] as $seg) { if (isset($seg[0])) $outTxt .= $seg[0]; }
    jout(['ok' => true, 'translated' => $outTxt]);
  }

  // ---- Поиск по фото: распознать изображение и найти похожие товары ----
  case 'photo_search': {
    $d = body();
    $img = $d['image'] ?? '';
    if ($img === '') fail('Нет изображения');
    $key = $GLOBALS['VISION_API_KEY'] ?? '';
    if (!$key) { jout(['ok' => false, 'error' => 'Поиск по фото не настроен: добавьте VISION_API_KEY в config.php']); }
    $model = $GLOBALS['VISION_MODEL'] ?? 'claude-3-5-sonnet-latest';
    if (strpos($img, 'base64,') !== false) $img = substr($img, strpos($img, 'base64,') + 7);
    $img = trim($img);

    // список категорий из БД (или дефолт)
    $cats = [];
    try { foreach (db()->query('SELECT name FROM categories ORDER BY sort,name')->fetchAll() as $cr) { $cats[] = $cr['name']; } } catch (Exception $e) {}
    if (!$cats) $cats = ['Диваны','Кровати','Шкафы','Столы','Стулья','Кресла','Комоды'];
    $catList = implode(', ', $cats);

    $sys = 'Ты ассистент мебельного маркетплейса. По фото определи товар и верни СТРОГО JSON без пояснений и без markdown.';
    $userText = "Категории на выбор: $catList.\n".
      'Верни JSON формата: {"category":"одна из категорий или пустая строка","keywords":["3-7 ключевых слов по-русски: тип, форма, особенности"],"colors":["цвета по-русски"],"materials":["материалы по-русски"],"style":"стиль одним словом"}';

    $payload = json_encode([
      'model' => $model, 'max_tokens' => 400,
      'system' => $sys,
      'messages' => [[ 'role' => 'user', 'content' => [
        ['type' => 'image', 'source' => ['type' => 'base64', 'media_type' => 'image/jpeg', 'data' => $img]],
        ['type' => 'text', 'text' => $userText]
      ]]]
    ], JSON_UNESCAPED_UNICODE);

    $resp = ''; $httpCode = 0;
    if (function_exists('curl_init')) {
      $ch = curl_init('https://api.anthropic.com/v1/messages');
      curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 30, CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => $payload,
        CURLOPT_HTTPHEADER => ['content-type: application/json', 'x-api-key: '.$key, 'anthropic-version: 2023-06-01']
      ]);
      $resp = curl_exec($ch);
      $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
      curl_close($ch);
    } else { fail('На сервере недоступен curl'); }
    if (!$resp) fail('Сервис распознавания недоступен, попробуйте позже', 502);
    $rj = json_decode($resp, true);
    if ($httpCode >= 400 || !is_array($rj)) {
      $em = is_array($rj) && isset($rj['error']['message']) ? $rj['error']['message'] : 'Ошибка распознавания';
      jout(['ok' => false, 'error' => $em]);
    }
    $txt = '';
    if (isset($rj['content']) && is_array($rj['content'])) {
      foreach ($rj['content'] as $blk) { if (($blk['type'] ?? '') === 'text') $txt .= $blk['text']; }
    }
    if (preg_match('/\{.*\}/s', $txt, $mm)) $txt = $mm[0];
    $attrs = json_decode($txt, true);
    if (!is_array($attrs)) $attrs = ['category' => '', 'keywords' => []];
    $cat = trim($attrs['category'] ?? '');
    $kws = [];
    foreach (['keywords','colors','materials'] as $kk) { if (!empty($attrs[$kk]) && is_array($attrs[$kk])) foreach ($attrs[$kk] as $w) { $w = trim((string)$w); if (mb_strlen($w) >= 3) $kws[] = mb_strtolower($w); } }
    if (!empty($attrs['style'])) { $st = mb_strtolower(trim((string)$attrs['style'])); if (mb_strlen($st) >= 3) $kws[] = $st; }
    $kws = array_values(array_unique($kws));

    // кандидаты из каталога (устойчиво к отсутствию колонок)
    $fetchCand = function($where, $params) {
      foreach (['id,name,cat,subcat,descr,blocked,mod_status','id,name,cat,subcat,descr,blocked','id,name,cat,subcat,descr'] as $cols) {
        try { $q = db()->prepare("SELECT $cols FROM products WHERE $where LIMIT 600"); $q->execute($params); return $q->fetchAll(); }
        catch (Exception $e) { continue; }
      }
      return [];
    };
    if ($cat !== '') { $cand = $fetchCand('cat=?', [$cat]); }
    else {
      $likes = []; $params = [];
      foreach (array_slice($kws, 0, 6) as $w) { $likes[] = '(name LIKE ? OR descr LIKE ? OR subcat LIKE ?)'; $params[] = "%$w%"; $params[] = "%$w%"; $params[] = "%$w%"; }
      $where = $likes ? implode(' OR ', $likes) : '1';
      $cand = $fetchCand($where, $params);
    }

    $scored = [];
    foreach ($cand as $p) {
      if (!empty($p['blocked'])) continue;
      $ms = $p['mod_status'] ?? '';
      if ($ms === 'pending' || $ms === 'rejected') continue;
      $hay = mb_strtolower($p['name'].' '.($p['subcat'] ?? '').' '.($p['descr'] ?? '').' '.$p['cat']);
      $score = 0;
      if ($cat !== '' && $p['cat'] === $cat) $score += 6;
      foreach ($kws as $w) { if (mb_stripos($hay, $w) !== false) $score += 2; }
      if ($score > 0) $scored[] = ['id' => $p['id'], 'score' => $score];
    }
    usort($scored, function($a, $b){ return $b['score'] - $a['score']; });
    $ids = array_map(function($x){ return $x['id']; }, array_slice($scored, 0, 24));
    jout(['ok' => true, 'attrs' => $attrs, 'ids' => $ids]);
  }

  // ---- все заказы (ИТК — видит всё) ----
  case 'all_orders': {
    authUser('itc');
    $orders = db()->query(
      'SELECT o.id,o.num,o.phone,o.total,o.status,o.paid,
              o.addr_name,o.addr_phone,o.addr_city,o.addr_street,o.addr_zip,o.addr_note,
              o.warehouse_id, w.code AS wh_code, w.name AS wh_name, w.city AS wh_city, w.country AS wh_country,
              UNIX_TIMESTAMP(o.created_at)*1000 AS ts
         FROM orders o LEFT JOIN warehouses w ON w.id = o.warehouse_id ORDER BY o.created_at DESC')->fetchAll();
    $hasCat = true;
    try { db()->query('SELECT cat FROM order_items LIMIT 1'); } catch (Exception $e) { $hasCat = false; }
    $hasDs = true;
    try { db()->query('SELECT ds FROM order_items LIMIT 1'); } catch (Exception $e) { $hasDs = false; }
    $catSel = $hasCat ? "COALESCE(NULLIF(i.cat,''), p.cat, '')" : "COALESCE(p.cat,'')";
    $dsSel  = $hasDs  ? "i.ds" : "EXISTS(SELECT 1 FROM ds_products dz WHERE dz.product_id=i.product_id)";
    $iq = db()->prepare(
      "SELECT i.product_id,i.name,i.qty,i.price,i.supplier_id, s.name AS supplier_name,
              {$catSel} AS cat, {$dsSel} AS ds
         FROM order_items i LEFT JOIN suppliers s ON s.id = i.supplier_id
         LEFT JOIN products p ON p.id = i.product_id
        WHERE i.order_id = ?");
    /* РАЗБОР ОПЛАТЫ (22.08.2026, просьба Алексея).
       Данные уже были: потраченный конверт хранит номер заказа, списанные
       бонусы тоже. Не хватало только места, где на это посмотреть. Собираем
       разбор прямо здесь — работает и для СТАРЫХ заказов, ничего задним
       числом дописывать в базу не нужно. */
    $envQ = null; $bonQ = null;
    try { $envQ = db()->prepare("SELECT COALESCE(SUM(amount),0) FROM itc_envelope WHERE order_id=? AND status='spent'"); } catch (Exception $e) {}
    try { $bonQ = db()->prepare("SELECT COALESCE(SUM(ABS(amount)),0) FROM itc_bonus WHERE order_id=? AND amount<0"); } catch (Exception $e) {}

    $__lkeys = order_lbl_keys(array_column($orders, 'id'));   // №284: ключ наклейки на коробку
    foreach ($orders as &$o) {
      $iq->execute([$o['id']]);
      $o['items'] = $iq->fetchAll();
      $o['lbl_key'] = $__lkeys[$o['id']] ?? '';

      $envSum = 0; $bonSum = 0;
      if ($envQ) { try { $envQ->execute([$o['id']]); $envSum = (int)$envQ->fetchColumn(); } catch (Exception $e) {} }
      if ($bonQ) { try { $bonQ->execute([$o['id']]); $bonSum = (int)$bonQ->fetchColumn(); } catch (Exception $e) {} }
      $o['pay_env']   = $envSum;
      $o['pay_bonus'] = $bonSum;
      $o['pay_money'] = max(0, (int)$o['total'] - $envSum - $bonSum);
      foreach ($o['items'] as &$__it) { $__it['ds'] = (int)($__it['ds'] ?? 0); } unset($__it);
      $o['ts'] = (int)$o['ts'];
      $o['paid'] = (int)$o['paid'];
      $o['addr'] = ['name'=>$o['addr_name'],'phone'=>$o['addr_phone'],'city'=>$o['addr_city'],
                    'street'=>$o['addr_street'],'zip'=>$o['addr_zip'],'note'=>$o['addr_note']];
    }
    unset($o);
    $trk = [];
    try { foreach (db()->query('SELECT id,tracking,note FROM orders')->fetchAll() as $tr) { $trk[$tr['id']] = $tr; } } catch (Exception $e) {}
    foreach ($orders as &$o) { $o['tracking'] = $trk[$o['id']]['tracking'] ?? ''; $o['order_note'] = $trk[$o['id']]['note'] ?? ''; }
    unset($o);
    jout(['ok' => true, 'orders' => $orders]);
  }

