  case 'apps_search': {           // босс: найти покупателя по телефону или фамилии
    $s = authUser('itc'); require_staff($s, []);
    apps_table();
    $q = trim((string)(body()['q'] ?? ''));
    if (mb_strlen($q) < 2) jout(['ok'=>true,'list'=>[]]);
    $digits = preg_replace('/\D+/', '', $q);
    if (strlen($digits) >= 4 && strlen($digits) >= mb_strlen($q) - 4) {
      $st = db()->prepare("SELECT phone,name,city FROM customers WHERE REPLACE(REPLACE(REPLACE(REPLACE(phone,' ',''),'-',''),'(',''),')','') LIKE ? ORDER BY created_at DESC LIMIT 30");
      $st->execute(['%' . $digits . '%']);
    } else {
      $st = db()->prepare("SELECT phone,name,city FROM customers WHERE name LIKE ? ORDER BY name LIMIT 30");
      $st->execute(['%' . $q . '%']);
    }
    $list = [];
    foreach ($st->fetchAll() as $r) $list[] = ['phone'=>$r['phone'],'name'=>$r['name'],'city'=>$r['city'],'apps'=>apps_of($r['phone'])];
    jout(['ok'=>true,'list'=>$list]);
