  // ---- ИТК: финансовая сводка и выплаты поставщикам ----
  case 'finance_summary': {
    authUser('itc');
    $rev = (int)db()->query('SELECT COALESCE(SUM(total),0) v FROM orders WHERE paid=1')->fetch()['v'];
    $kurs = (float)(get_settings()['kurs_cny'] ?? 13.2);
    $hasFlag = true;
    try { db()->query('SELECT paid_supplier FROM order_items LIMIT 1'); } catch (Exception $e) { $hasFlag = false; }
    if ($hasFlag) {
      $sql = 'SELECT i.supplier_id, s.name,
                     COALESCE(SUM(CASE WHEN i.paid_supplier=0 THEN p.goods_cny*i.qty ELSE 0 END),0) owed_cny,
                     COALESCE(SUM(CASE WHEN i.paid_supplier=1 THEN p.goods_cny*i.qty ELSE 0 END),0) paid_cny,
                     COALESCE(SUM(p.goods_cny*i.qty),0) total_cny,
                     COUNT(DISTINCT CASE WHEN i.paid_supplier=0 THEN i.order_id END) unpaid_orders
                FROM order_items i
                JOIN orders o ON o.id=i.order_id AND o.paid=1
                LEFT JOIN products p ON p.id=i.product_id
                LEFT JOIN suppliers s ON s.id=i.supplier_id
               GROUP BY i.supplier_id, s.name';
    } else {
      $sql = 'SELECT i.supplier_id, s.name,
                     COALESCE(SUM(p.goods_cny*i.qty),0) owed_cny, 0 paid_cny,
                     COALESCE(SUM(p.goods_cny*i.qty),0) total_cny,
                     COUNT(DISTINCT i.order_id) unpaid_orders
                FROM order_items i
                JOIN orders o ON o.id=i.order_id AND o.paid=1
                LEFT JOIN products p ON p.id=i.product_id
                LEFT JOIN suppliers s ON s.id=i.supplier_id
               GROUP BY i.supplier_id, s.name';
    }
    $rows = db()->query($sql)->fetchAll();
    $sup = []; $cogs = 0; $owed = 0;
    foreach ($rows as $r) {
      $oc = (int)$r['owed_cny']; $pc = (int)$r['paid_cny']; $tc = (int)$r['total_cny'];
      $cogs += $tc; $owed += $oc;
      $sup[] = ['id'=>$r['supplier_id'],'name'=>$r['name'] ?: $r['supplier_id'],
                'owed_cny'=>$oc,'paid_cny'=>$pc,'total_cny'=>$tc,'unpaid_orders'=>(int)$r['unpaid_orders']];
    }
    usort($sup, function($a,$b){ return $b['owed_cny'] - $a['owed_cny']; });
    jout(['ok'=>true,'kurs'=>$kurs,'revenue_rub'=>$rev,
          'cogs_cny'=>$cogs,'cogs_rub'=>(int)round($cogs*$kurs),
          'owed_cny'=>$owed,'owed_rub'=>(int)round($owed*$kurs),
          'spread_rub'=>$rev-(int)round($cogs*$kurs),
          'has_flag'=>$hasFlag,'suppliers'=>$sup]);
  }

