  // ---- ИТК: серверная аналитика (агрегаты) ----
  case 'analytics': {
    authUser('itc');
    $days = (int)($_GET['days'] ?? ($_POST['days'] ?? 30));
    $since = $days > 0 ? date('Y-m-d H:i:s', time() - $days * 86400) : null;
    $cO = $since ? ' AND o.created_at>=?' : '';          // условие по дате (alias o)
    $pO = $since ? [$since] : [];

    // KPI по оплаченным заказам
    $k = db()->prepare('SELECT COALESCE(SUM(o.total),0) revenue, COUNT(*) cnt, COUNT(DISTINCT o.phone) buyers FROM orders o WHERE o.paid=1'.$cO);
    $k->execute($pO); $kpi = $k->fetch();
    $u = db()->prepare('SELECT COALESCE(SUM(i.qty),0) units FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.paid=1'.$cO);
    $u->execute($pO); $units = (int)$u->fetch()['units'];
    $clicks = (int)db()->query('SELECT COALESCE(SUM(clicks),0) c FROM products')->fetch()['c'];

    // продажи по дням
    $sd = db()->prepare('SELECT DATE(o.created_at) d, COALESCE(SUM(o.total),0) v FROM orders o WHERE o.paid=1'.$cO.' GROUP BY DATE(o.created_at) ORDER BY d');
    $sd->execute($pO);
    $byDay = [];
    foreach ($sd->fetchAll() as $r) { $byDay[$r['d']] = (int)$r['v']; }

    // топ товаров
    $tp = db()->prepare('SELECT i.name, SUM(i.qty) qty, SUM(i.price*i.qty) rev FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.paid=1'.$cO.' GROUP BY i.product_id, i.name ORDER BY rev DESC LIMIT 8');
    $tp->execute($pO);
    $topProd = array_map(function($r){ return ['name'=>$r['name'],'qty'=>(int)$r['qty'],'rev'=>(int)$r['rev']]; }, $tp->fetchAll());

    // топ поставщиков
    $ts = db()->prepare('SELECT COALESCE(s.name,i.supplier_id) name, SUM(i.price*i.qty) rev FROM order_items i JOIN orders o ON o.id=i.order_id LEFT JOIN suppliers s ON s.id=i.supplier_id WHERE o.paid=1'.$cO.' GROUP BY i.supplier_id, s.name ORDER BY rev DESC LIMIT 8');
    $ts->execute($pO);
    $topSup = array_map(function($r){ return ['name'=>$r['name'],'rev'=>(int)$r['rev']]; }, $ts->fetchAll());

    // топ категорий
    try {
      $tc = db()->prepare('SELECT COALESCE(NULLIF(i.cat,\'\'),p.cat,\'Прочее\') cat, SUM(i.price*i.qty) rev FROM order_items i JOIN orders o ON o.id=i.order_id LEFT JOIN products p ON p.id=i.product_id WHERE o.paid=1'.$cO.' GROUP BY COALESCE(NULLIF(i.cat,\'\'),p.cat,\'Прочее\') ORDER BY rev DESC LIMIT 8');
      $tc->execute($pO);
    } catch (Exception $e) {
      $tc = db()->prepare('SELECT COALESCE(p.cat,\'Прочее\') cat, SUM(i.price*i.qty) rev FROM order_items i JOIN orders o ON o.id=i.order_id LEFT JOIN products p ON p.id=i.product_id WHERE o.paid=1'.$cO.' GROUP BY COALESCE(p.cat,\'Прочее\') ORDER BY rev DESC LIMIT 8');
      $tc->execute($pO);
    }
    $topCat = array_map(function($r){ return ['name'=>$r['cat'],'rev'=>(int)$r['rev']]; }, $tc->fetchAll());

    // топ по кликам (всё время)
    $tk = db()->query('SELECT name, clicks FROM products WHERE clicks>0 ORDER BY clicks DESC LIMIT 8')->fetchAll();
    $topClicks = array_map(function($r){ return ['name'=>$r['name'],'clicks'=>(int)$r['clicks']]; }, $tk);

    // воронка статусов (все заказы периода)
    $cOf = $since ? ' WHERE o.created_at>=?' : '';
    $fs = db()->prepare('SELECT o.status, COUNT(*) c FROM orders o'.$cOf.' GROUP BY o.status');
    $fs->execute($pO);
    $statusCnt = [];
    foreach ($fs->fetchAll() as $r) { $statusCnt[$r['status']] = (int)$r['c']; }

    /* Поисковые запросы за тот же период. Отдельно — «пустые»: те, по которым
       ни разу ничего не нашлось. Это и есть готовый список на закупку. */
    $srchTop = []; $srchMiss = []; $srchAll = 0; $srchMissCnt = 0;
    $sinceS = $since ? $since : '1970-01-01 00:00:00';
    try {
      $sq = db()->prepare("SELECT qn, MAX(q) q, COUNT(*) n, MAX(found) mx
                           FROM search_log WHERE created_at>=? GROUP BY qn ORDER BY n DESC LIMIT 40");
      $sq->execute([$sinceS]);
      foreach ($sq->fetchAll() as $r) $srchTop[] = ['q'=>$r['q'], 'n'=>(int)$r['n'], 'found'=>(int)$r['mx']];
      $sq2 = db()->prepare("SELECT qn, MAX(q) q, COUNT(*) n FROM search_log WHERE created_at>=?
                            GROUP BY qn HAVING MAX(found)=0 ORDER BY n DESC LIMIT 40");
      $sq2->execute([$sinceS]);
      foreach ($sq2->fetchAll() as $r) $srchMiss[] = ['q'=>$r['q'], 'n'=>(int)$r['n']];
      $c1 = db()->prepare('SELECT COUNT(*) FROM search_log WHERE created_at>=?'); $c1->execute([$sinceS]); $srchAll = (int)$c1->fetchColumn();
      $c2 = db()->prepare('SELECT COUNT(*) FROM search_log WHERE found=0 AND created_at>=?'); $c2->execute([$sinceS]); $srchMissCnt = (int)$c2->fetchColumn();
    } catch (Exception $e) {}

    jout(['ok'=>true,'days'=>$days,
          'revenue'=>(int)$kpi['revenue'],'orders'=>(int)$kpi['cnt'],'buyers'=>(int)$kpi['buyers'],
          'units'=>$units,'clicks'=>$clicks,
          'by_day'=>$byDay,'top_products'=>$topProd,'top_suppliers'=>$topSup,
          'top_categories'=>$topCat,'top_clicks'=>$topClicks,'status'=>$statusCnt,
          'search_total'=>$srchAll,'search_miss'=>$srchMissCnt,
          'search_top'=>$srchTop,'search_empty'=>$srchMiss]);
  }

  // ---- ИТК: добавить категорию ----
  case 'category_add': {
    authUser('itc');
    $d = body();
    $name = trim($d['name'] ?? '');
    if ($name === '') fail('Укажите название группы');
    $mx = db()->query('SELECT COALESCE(MAX(sort),0) m FROM categories')->fetch();
    db()->prepare('INSERT IGNORE INTO categories (name,sort) VALUES (?,?)')->execute([$name, ((int)$mx['m']) + 1]);
    jout(['ok'=>true]);
  }

  // ---- ИТК: удалить категорию ----
  case 'category_del': {
    authUser('itc');
    $d = body();
    $name = trim($d['name'] ?? '');
    if ($name === '') fail('Не указана группа');
    db()->prepare('DELETE FROM categories WHERE name=?')->execute([$name]);
    jout(['ok'=>true]);
  }

  // ---- ИТК: переименовать категорию (с переносом товаров) ----
  case 'category_rename': {
    authUser('itc');
    $d = body();
    $old = trim($d['old'] ?? '');
    $new = trim($d['new'] ?? '');
    if ($old === '' || $new === '') fail('Укажите старое и новое название');
    $s = db()->prepare('SELECT sort FROM categories WHERE name=?'); $s->execute([$old]); $row = $s->fetch();
    $sort = $row ? (int)$row['sort'] : 0;
    db()->prepare('DELETE FROM categories WHERE name=?')->execute([$old]);
    db()->prepare('INSERT IGNORE INTO categories (name,sort) VALUES (?,?)')->execute([$new, $sort]);
    db()->prepare('UPDATE products SET cat=? WHERE cat=?')->execute([$new, $old]);
    jout(['ok'=>true]);
  }

  // ---- ИТК: порядок категорий ----
  case 'categories_order': {
    authUser('itc');
    $d = body();
    $names = $d['names'] ?? [];
    if (!is_array($names)) fail('Неверные данные');
    $i = 1;
    foreach ($names as $n) {
      db()->prepare('UPDATE categories SET sort=? WHERE name=?')->execute([$i, trim((string)$n)]);
      $i++;
    }
    jout(['ok'=>true]);
  }

  // ---- смена статуса (поставщик или ИТК) ----
  case 'advance_status': {
    $s = authUser();
    if ($s['role'] !== 'supplier' && $s['role'] !== 'itc') fail('Недостаточно прав', 403);
    $d = body();
    $st = db()->prepare('SELECT status FROM orders WHERE id = ?');
    $st->execute([$d['order_id'] ?? '']);
    $o = $st->fetch();
    if (!$o) fail('Заказ не найден');
    $cur = $o['status'];
    // поставщик двигает только created/confirmed; ИТК — после склада
    if ($s['role'] === 'supplier' && !in_array($cur, ['created','confirmed'])) fail('Заказ уже у логистики ИТК', 403);
    if ($s['role'] === 'itc' && !in_array($cur, ['in_container','shipping','delivering'])) fail('Этот статус двигает поставщик или контейнер', 403);
    $nx = next_status($cur);
    if (!$nx) fail('Это финальный статус');
    db()->prepare('UPDATE orders SET status = ? WHERE id = ?')->execute([$nx, $d['order_id']]);
    if ($s['role'] === 'itc') { $by = mb_substr(trim($d['by'] ?? ''), 0, 120); itc_log_add($by, 'order_status', 'order', $d['order_id'] ?? '', $nx); }
    jout(['ok' => true, 'status' => $nx]);
  }

  // ---- сформировать контейнер (ИТК): склад → контейнер ----
  case 'form_container': {
    authUser('itc');
    db()->query("UPDATE orders SET status='in_container' WHERE status='at_warehouse'");
    jout(['ok' => true]);
  }

  // ---- отправить контейнер (ИТК): контейнер → в пути ----
  case 'ship_container': {
    authUser('itc');
    db()->query("UPDATE orders SET status='shipping' WHERE status='in_container'");
    jout(['ok' => true]);
  }

  // ---- популярность: клик по карточке (публично) ----
  case 'track_click': {
    $d = body();
    $id = $d['id'] ?? '';
    if ($id) { try { db()->prepare('UPDATE products SET clicks = clicks + 1 WHERE id = ?')->execute([$id]); } catch (Exception $e) {} }
    jout(['ok' => true]);
  }

  // ---- оплата по QR (WeChat Pay / Alipay), зачисление на ВТБ Шанхай ----
  case 'create_cn_payment': {
    global $CN_PAY_ENABLED, $CN_PAY_PROVIDER, $SITE_URL;
    $sess = authUser('buyer');
    $d = body();
    $st = db()->prepare('SELECT * FROM orders WHERE id = ? AND '.ph_sql_eq('phone'));
    $st->execute([$d['order_id'] ?? '', ph_tail10($sess['phone'])]);
    $o = $st->fetch();
    if (!$o) fail('Заказ не найден');
    if ((int)$o['paid'] === 1) fail('Заказ уже оплачен');
    $kurs = (float)get_settings()['kurs_cny'];
    $amount_cny = $kurs > 0 ? round($o['total'] / $kurs, 2) : 0;
    $provider = $CN_PAY_PROVIDER ?: 'wechat';
    if ($CN_PAY_ENABLED) {
      $code_url = cn_pay_create($provider, $o['num'], $amount_cny, $SITE_URL);
      if (!$code_url) fail('Не удалось создать платёж у провайдера', 502);
    } else {
      // провайдер ещё не подключён — тестовый payload для отображения QR
      $code_url = ($provider === 'alipay' ? 'https://qr.alipay.com/DEMO-' : 'weixin://wxpay/bizpayurl?pr=DEMO-') . $o['num'];
    }
    jout(['ok' => true, 'provider' => $provider, 'amount_cny' => $amount_cny, 'qr' => $code_url, 'num' => $o['num'], 'enabled' => (bool)$CN_PAY_ENABLED]);
  }

  case 'cn_payment_status': {
    $sess = authUser('buyer');
    $d = body();
    $st = db()->prepare('SELECT paid FROM orders WHERE id = ? AND '.ph_sql_eq('phone'));
    $st->execute([$d['order_id'] ?? '', ph_tail10($sess['phone'])]);
    $o = $st->fetch();
    jout(['ok' => true, 'paid' => $o ? (int)$o['paid'] : 0]);
  }

  // тестовое подтверждение оплаты — РАБОТАЕТ ТОЛЬКО пока CN-оплата НЕ подключена
  case 'cn_pay_test_confirm': {
    global $CN_PAY_ENABLED;
    if ($CN_PAY_ENABLED) fail('Недоступно: подтверждение приходит от провайдера', 403);
    $sess = authUser('buyer');
    $d = body();
    db()->prepare("UPDATE orders SET paid = 1, status = IF(status='created','confirmed',status) WHERE id = ? AND ".ph_sql_eq('phone'))
        ->execute([$d['order_id'] ?? '', ph_tail10($sess['phone'])]);
    ds_create_procurement($d['order_id'] ?? '');
