  // ---- РЕКЛАМА (ИТК): список всех баннеров ----
  case 'itc_banners': {
    authUser('itc');
    try { $rows = db()->query('SELECT id,title,subtitle,img,link,active,sort,start_at,end_at,pos_title,pos_sub,font_title,font_sub,size_title,size_sub,img_zoom,img_focus_x,img_focus_y FROM banners ORDER BY sort, created_at')->fetchAll(); }
    catch (Exception $e) { $rows = db()->query('SELECT id,title,subtitle,img,link,active,sort,start_at,end_at FROM banners ORDER BY sort, created_at')->fetchAll(); }
    foreach ($rows as &$r) { $r['active'] = (int)$r['active']; $r['sort'] = (int)$r['sort']; }
    jout(['ok' => true, 'banners' => $rows]);
  }

  // ---- РЕКЛАМА (ИТК): создать/обновить баннер ----
  case 'save_banner': {
    authUser('itc');
    $d = body();
    $title = trim($d['title'] ?? '');
    $sub   = trim($d['subtitle'] ?? '');
    $img   = trim($d['img'] ?? '');
    $link  = trim($d['link'] ?? '');
    $active = isset($d['active']) ? (int)!!$d['active'] : 1;
    $sort  = (int)($d['sort'] ?? 0);
    $start = trim($d['start_at'] ?? ''); $start = ($start !== '') ? $start : null;
    $end   = trim($d['end_at'] ?? '');   $end   = ($end !== '') ? $end : null;
    if ($img === '' && $title === '') fail('Добавьте картинку или заголовок баннера');
    // v195: опциональные поля редактора (расположение/шрифт/размер текста, кадрирование фото).
    // Обновляются ТОЛЬКО если пришли в запросе — чтобы toggle/старый клиент не сбрасывал настройки.
    $bn_opt = ['pos_title'=>'s','pos_sub'=>'s','font_title'=>'s','font_sub'=>'s','size_title'=>'i','size_sub'=>'i','img_zoom'=>'f','img_focus_x'=>'f','img_focus_y'=>'f'];
    $bn_cast = function($v,$t){ return $t==='i' ? (int)$v : ($t==='f' ? (float)$v : trim((string)$v)); };
    if (!empty($d['id'])) {
      $sets = ['title=?','subtitle=?','img=?','link=?','active=?','sort=?','start_at=?','end_at=?'];
      $vals = [$title, $sub, $img, $link, $active, $sort, $start, $end];
      foreach ($bn_opt as $col=>$t) { if (array_key_exists($col,$d)) { $sets[]="$col=?"; $vals[]=$bn_cast($d[$col],$t); } }
      $vals[] = $d['id'];
      db()->prepare('UPDATE banners SET '.implode(',',$sets).' WHERE id=?')->execute($vals);
      jout(['ok' => true, 'id' => $d['id']]);
    } else {
      $id = gen('b');
      $cols = ['id','title','subtitle','img','link','active','sort','start_at','end_at'];
      $vals = [$id, $title, $sub, $img, $link, $active, $sort, $start, $end];
      foreach ($bn_opt as $col=>$t) { if (array_key_exists($col,$d)) { $cols[]=$col; $vals[]=$bn_cast($d[$col],$t); } }
      $ph = implode(',', array_fill(0, count($cols), '?'));
      db()->prepare('INSERT INTO banners ('.implode(',',$cols).') VALUES ('.$ph.')')->execute($vals);
      jout(['ok' => true, 'id' => $id]);
    }
  }

  // ---- РЕКЛАМА (ИТК): порядок показа ----
  case 'reorder_banners': {
    authUser('itc');
    $d = body();
    $ids = $d['ids'] ?? [];
    if (!is_array($ids)) fail('Неверный список');
    $st = db()->prepare('UPDATE banners SET sort = ? WHERE id = ?');
    $i = 0;
    foreach ($ids as $id) { $st->execute([$i, $id]); $i++; }
    jout(['ok' => true]);
  }

  // ---- РЕКЛАМА (ИТК): удалить баннер ----
  case 'delete_banner': {
    authUser('itc');
    $d = body();
    if (empty($d['id'])) fail('Не указан баннер');
    db()->prepare('DELETE FROM banners WHERE id = ?')->execute([$d['id']]);
    jout(['ok' => true]);
  }

  // ==================== ЭТАП 1: поставщики и платежи ====================

  // ---- МОДЕРАТОР: одобрить/отклонить поставщика + назначить момент оплаты ----
  case 'supplier_moderate': {
    $s = authUser('itc'); require_staff($s, ['moderator']);
    $d = body();
    $id = trim($d['id'] ?? '');
    $decision = (($d['decision'] ?? '') === 'reject') ? 'rejected' : 'approved';
    $moment = in_array(($d['pay_moment'] ?? ''), ['prepay30','prepay100','warehouse','received_ru'], true) ? $d['pay_moment'] : 'prepay30';
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    $note = mb_substr(trim($d['note'] ?? ''), 0, 255);
    if (!$id) fail('Не указан поставщик');
    if ($decision === 'approved' && !$moment) fail('Назначьте момент оплаты перед одобрением');
    db()->prepare("UPDATE suppliers SET mod_status=?, pay_moment=?, moderated_by=?, moderated_at=NOW(), mod_note=? WHERE id=?")
        ->execute([$decision, ($decision === 'approved' ? $moment : null), $by, $note, $id]);
    itc_log_add($by, ($decision === 'approved' ? 'supplier_approve' : 'supplier_reject'), 'supplier', $id, $note);
    if ($decision === 'approved') {
      $cur = db()->prepare("SELECT contract_no FROM suppliers WHERE id=?"); $cur->execute([$id]);
      if (!$cur->fetchColumn()) {
        $cno = 'ITK-'.date('Y').'/'.strtoupper(substr($id, -5));
        db()->prepare("UPDATE suppliers SET contract_no=?, contract_at=NOW(), contract_status='generated' WHERE id=?")->execute([$cno, $id]);
      }
    }
    jout(['ok'=>true,'id'=>$id,'mod_status'=>$decision]);
  }

  // ---- БУХГАЛТЕРИЯ/МЕНЕДЖЕР: реестр платежей поставщикам ----
  case 'supplier_payments': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant','manager']);
    $rows = db()->query("SELECT i.order_id,i.supplier_id,i.name,i.qty,i.price,i.paid_supplier,
        UNIX_TIMESTAMP(i.paid_supplier_at)*1000 pst, i.paid_supplier_by, p.goods_cny, p.img, i.product_id,
        d.source_url, d.source_price_cny, jf.name jfact_name, jf.phone jfact_phone, jf.wechat jfact_wechat, jf.site jfact_site, o.num,
        UNIX_TIMESTAMP(o.created_at)*1000 ots, UNIX_TIMESTAMP(o.wh_received_at)*1000 rts, UNIX_TIMESTAMP(o.picked_up_at)*1000 pts,
        s.name sup_name, s.pay_company, s.pay_moment
      FROM order_items i
      JOIN orders o ON o.id=i.order_id AND o.paid=1
      JOIN suppliers s ON s.id=i.supplier_id
      LEFT JOIN products p ON p.id=i.product_id
      LEFT JOIN ds_products d ON d.product_id=i.product_id
      LEFT JOIN jfactories jf ON jf.id=p.jfactory_id
      ORDER BY o.created_at DESC LIMIT 800")->fetchAll();
    $list = [];
    foreach ($rows as $r) {
      $moment = $r['pay_moment'];
      $due = false;
      if ($moment === 'prepay') $due = true;
      elseif ($moment === 'warehouse') $due = !empty($r['rts']);
      elseif ($moment === 'received') $due = !empty($r['pts']);
      // закупка: берём из карточки, если пусто — из цены источника 1688
      $unitCny = (float)$r['goods_cny'];
      $cnySrc  = 'card';
      if ($unitCny <= 0 && (float)$r['source_price_cny'] > 0) { $unitCny = (float)$r['source_price_cny']; $cnySrc = 'source'; }
      if ($unitCny <= 0) $cnySrc = 'none';
      $cny = round($unitCny * (int)$r['qty'], 2);
      $list[] = ['order_id'=>$r['order_id'],'num'=>$r['num'],'supplier_id'=>$r['supplier_id'],'sup_name'=>$r['sup_name'],
        'pay_company'=>$r['pay_company'],'pay_moment'=>$moment,'name'=>$r['name'],'qty'=>(int)$r['qty'],
        'cny'=>$cny,'rub'=>(float)$r['price'],'paid'=>(int)$r['paid_supplier'],'pst'=>(int)$r['pst'],'paid_by'=>$r['paid_supplier_by'],
        'due'=>$due?1:0,'ots'=>(int)$r['ots'],
        'unit_cny'=>$unitCny,'cny_src'=>$cnySrc,'product_id'=>$r['product_id'],'img'=>$r['img'],
        'source_url'=>$r['source_url'],'source_price_cny'=>$r['source_price_cny'],
        'jfact_name'=>$r['jfact_name'],'jfact_phone'=>$r['jfact_phone'],'jfact_wechat'=>$r['jfact_wechat'],'jfact_site'=>$r['jfact_site']];
    }
    jout(['ok'=>true,'payments'=>$list]);
  }

  // ---- БУХГАЛТЕРИЯ: отметить оплату поставщику ----
  case 'pay_supplier_mark': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant']);
    $d = body();
    $oid = trim($d['order_id'] ?? ''); $sid = trim($d['supplier_id'] ?? '');
    $paid = ((int)($d['paid'] ?? 1)) ? 1 : 0;
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    if (!$oid || !$sid) fail('Не указан заказ/поставщик');
    db()->prepare("UPDATE order_items SET paid_supplier=?, paid_supplier_at=IF(?=1,NOW(),NULL), paid_supplier_by=IF(?=1,?,NULL) WHERE order_id=? AND supplier_id=?")
        ->execute([$paid, $paid, $paid, $by, $oid, $sid]);
    itc_log_add($by, ($paid ? 'supplier_paid' : 'supplier_unpaid'), 'order', $oid, 'Оплата поставщику '.$sid);
    jout(['ok'=>true]);
  }

  // ---- БУХГАЛТЕРИЯ/МЕНЕДЖЕР: выгрузка реестра в CSV (Excel) ----
  case 'supplier_payments_csv': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant','manager']);
    $rows = db()->query("SELECT i.qty,i.price,i.name,i.paid_supplier, p.goods_cny, o.num,
        UNIX_TIMESTAMP(o.wh_received_at)*1000 rts, UNIX_TIMESTAMP(o.picked_up_at)*1000 pts,
        s.name sup_name, s.pay_company, s.pay_moment
      FROM order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1
      JOIN suppliers s ON s.id=i.supplier_id LEFT JOIN products p ON p.id=i.product_id
      ORDER BY o.created_at DESC LIMIT 2000")->fetchAll();
    $co = ['jinjia'=>'Jinjia (КНР)','itk'=>'ИТК (РФ)'];
    $mo = ['prepay30'=>'30% предоплата + 70% при приёмке','prepay100'=>'100% предоплата','warehouse'=>'По факту поставки на склад','received_ru'=>'По получению в России','prepay'=>'100% предоплата','received'=>'По получению в России'];
    $csv = "\xEF\xBB\xBF";
    $csv .= "Заказ;Поставщик;Категория;Момент оплаты;Товар;Кол-во;Сумма CNY;Сумма RUB;Оплачено поставщику\r\n";
    foreach ($rows as $r) {
      $cny = round(((float)$r['goods_cny']) * (int)$r['qty'], 2);
      $line = [$r['num'], $r['sup_name'], ($co[$r['pay_company']] ?? '—'), ($mo[$r['pay_moment']] ?? 'не задано'),
               str_replace(';',',',$r['name']), (int)$r['qty'], $cny, (float)$r['price'], ((int)$r['paid_supplier'] ? 'да' : 'нет')];
      $csv .= implode(';', $line) . "\r\n";
    }
    jout(['ok'=>true,'csv'=>base64_encode($csv),'filename'=>'payments_'.date('Y-m-d').'.csv']);
  }

  // ---- ГЛАВБУХ: получить печати/подписи компаний ----
  case 'seals_get': {
    $s = authUser('itc'); require_staff($s, ['chief_accountant']);
    $rows = db()->query("SELECT company,seal_img,sign_img,updated_by,UNIX_TIMESTAMP(updated_at)*1000 uts FROM company_seals")->fetchAll();
    jout(['ok'=>true,'seals'=>$rows]);
  }

  // ---- ГЛАВБУХ: сохранить печать/подпись (url из upload_media) ----
  case 'seal_save': {
    $s = authUser('itc'); require_staff($s, ['chief_accountant']);
    $d = body();
    $company = (($d['company'] ?? '') === 'jinjia') ? 'jinjia' : 'itk';
    $kind = (($d['kind'] ?? '') === 'sign') ? 'sign_img' : 'seal_img';
    $url = trim($d['url'] ?? '');
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    db()->prepare("INSERT INTO company_seals (company,$kind,updated_by,updated_at) VALUES (?,?,?,NOW())
                   ON DUPLICATE KEY UPDATE $kind=VALUES($kind), updated_by=VALUES(updated_by), updated_at=NOW()")
        ->execute([$company, $url, $by]);
    itc_log_add($by, 'seal_save', 'company', $company, $kind);
    jout(['ok'=>true]);
  }

  // ==================== ЭТАП 2: договоры с поставщиками ====================

  // ---- Просмотр договора (HTML): поставщик — свой; сотрудник — по sid ----
  case 'contract_view': {
    $sess = authUser();
    $d = body();
    $sid = (($sess['role'] ?? '') === 'supplier') ? ($sess['supplier_id'] ?? '') : trim($d['sid'] ?? '');
    if (!$sid) fail('Не указан поставщик');
    $st = db()->prepare("SELECT id,name,zh,reg_data,pay_company,contract_no,contract_at FROM suppliers WHERE id=?");
    $st->execute([$sid]); $sup = $st->fetch();
    if (!$sup) fail('Поставщик не найден');
    $seals = [];
    foreach (db()->query("SELECT company,seal_img,sign_img FROM company_seals")->fetchAll() as $r) $seals[$r['company']] = $r;
    $html = supplier_contract_html($sup, $seals);
    jout(['ok'=>true,'html'=>base64_encode($html),'no'=>$sup['contract_no']]);
  }

  // ---- Поставщик: загрузить подписанный скан договора ----
  case 'contract_upload_signed': {
    $sess = authUser('supplier');
    $sid = $sess['supplier_id'] ?? '';
    $d = body(); $url = trim($d['url'] ?? '');
    if (!$sid) fail('Нет доступа');
    if (!$url) fail('Файл не загружен');
    db()->prepare("UPDATE suppliers SET contract_signed_url=?, contract_signed_at=NOW(), contract_status='signed' WHERE id=?")->execute([$url, $sid]);
    itc_log_add('supplier:'.$sid, 'contract_signed', 'supplier', $sid, 'Загружен подписанный договор');
    jout(['ok'=>true]);
  }

  // ---- Менеджер/бухгалтер: список договоров ----
  case 'contracts_list': {
    $s = authUser('itc'); require_staff($s, ['manager','accountant','chief_accountant']);
    $rows = [];
    foreach (db()->query("SELECT id,name,zh,pay_company,contract_no,contract_status,contract_signed_url,
        UNIX_TIMESTAMP(contract_at)*1000 cat, UNIX_TIMESTAMP(contract_signed_at)*1000 sat
        FROM suppliers WHERE mod_status='approved' AND contract_no IS NOT NULL
        ORDER BY (contract_status='signed') DESC, contract_at DESC")->fetchAll() as $r) {
      $rows[] = ['id'=>$r['id'],'name'=>$r['name'],'zh'=>$r['zh'],'pay_company'=>$r['pay_company'],
                 'contract_no'=>$r['contract_no'],'status'=>$r['contract_status'],'signed_url'=>$r['contract_signed_url'],
                 'cat'=>(int)$r['cat'],'sat'=>(int)$r['sat']];
    }
    jout(['ok'=>true,'contracts'=>$rows]);
  }

  // ==================== ЭТАП 3: партии и документы ====================

  // ---- Сформировать партии по поставщикам за период ----
  case 'batches_build': {
    $s = authUser('itc'); require_staff($s, ['manager','accountant','chief_accountant']);
    $d = body();
    $days = (int)($d['days'] ?? 0); if ($days <= 0) $days = (int)get_settings()['batch_period_days']; if ($days <= 0) $days = 3;
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    $q = db()->prepare("SELECT DISTINCT i.supplier_id FROM order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1 JOIN suppliers s ON s.id=i.supplier_id AND s.mod_status='approved' WHERE i.batch_id IS NULL AND o.created_at >= (NOW() - INTERVAL ? DAY)");
    $q->execute([$days]);
    $sids = $q->fetchAll(PDO::FETCH_COLUMN);
    $created = 0;
    foreach ($sids as $sid) {
      $bid = gen('b');
      $bno = 'B-'.date('Ymd').'-'.strtoupper(substr($sid, -4));
      db()->prepare("INSERT INTO supply_batches (id,supplier_id,batch_no,dt_from,dt_to,status,created_by,created_at) VALUES (?,?,?,(NOW()-INTERVAL ? DAY),NOW(),'draft',?,NOW())")
          ->execute([$bid, $sid, $bno, $days, $by]);
      db()->prepare("UPDATE order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1 SET i.batch_id=? WHERE i.supplier_id=? AND i.batch_id IS NULL AND o.created_at >= (NOW() - INTERVAL ? DAY)")
          ->execute([$bid, $sid, $days]);
      $created++;
    }
    itc_log_add($by, 'batches_build', 'batch', (string)$created, 'Сформировано партий: '.$created.' (период '.$days.' дн.)');
    jout(['ok'=>true,'created'=>$created,'days'=>$days]);
  }

  // ---- Список партий ----
  case 'batches_list': {
    $s = authUser('itc'); require_staff($s, ['manager','accountant','chief_accountant']);
    $rows = [];
    foreach (db()->query("SELECT b.id,b.batch_no,b.supplier_id,b.status,UNIX_TIMESTAMP(b.created_at)*1000 cat, s.name sup_name, s.pay_company, COUNT(i.id) items, COALESCE(SUM(i.qty),0) qty FROM supply_batches b JOIN suppliers s ON s.id=b.supplier_id LEFT JOIN order_items i ON i.batch_id=b.id GROUP BY b.id,b.batch_no,b.supplier_id,b.status,b.created_at,s.name,s.pay_company ORDER BY b.created_at DESC LIMIT 300")->fetchAll() as $r) {
      $rows[] = ['id'=>$r['id'],'no'=>$r['batch_no'],'supplier_id'=>$r['supplier_id'],'sup_name'=>$r['sup_name'],'pay_company'=>$r['pay_company'],'status'=>$r['status'],'items'=>(int)$r['items'],'qty'=>(int)$r['qty'],'cat'=>(int)$r['cat']];
    }
    jout(['ok'=>true,'batches'=>$rows]);
  }

  // ---- Документ партии (spec / invoice / packing) ----
  case 'batch_doc': {
    $s = authUser('itc'); require_staff($s, ['manager','accountant','chief_accountant']);
    $d = body();
    $bid = trim($d['batch_id'] ?? '');
    $type = in_array(($d['type'] ?? ''), ['spec','invoice','packing'], true) ? $d['type'] : 'spec';
    if (!$bid) fail('Не указана партия');
    $bq = db()->prepare("SELECT b.*, s.name,s.zh,s.reg_data,s.pay_company FROM supply_batches b JOIN suppliers s ON s.id=b.supplier_id WHERE b.id=?");
    $bq->execute([$bid]); $b = $bq->fetch();
    if (!$b) fail('Партия не найдена');
    $iq = db()->prepare("SELECT i.name,i.qty,p.goods_cny,p.volume_m3,p.weight_kg,p.pcs_per_box FROM order_items i LEFT JOIN products p ON p.id=i.product_id WHERE i.batch_id=?");
    $iq->execute([$bid]); $items = $iq->fetchAll();
    $seals = []; foreach (db()->query("SELECT company,seal_img,sign_img FROM company_seals")->fetchAll() as $r) $seals[$r['company']] = $r;
    $sup = ['name'=>$b['name'],'zh'=>$b['zh'],'reg_data'=>$b['reg_data'],'pay_company'=>$b['pay_company']];
    $html = batch_doc_html($type, $b, $sup, $items, $seals);
    jout(['ok'=>true,'html'=>base64_encode($html)]);
  }

  // ---- Настройка периода сбора партий (дней) ----
  case 'batch_period_set': {
    $s = authUser('itc'); require_staff($s, ['manager','accountant','chief_accountant']);
    $d = body(); $days = (int)($d['days'] ?? 3); if ($days < 1) $days = 1; if ($days > 90) $days = 90;
    db()->prepare("INSERT INTO settings (k,v) VALUES ('batch_period_days',?) ON DUPLICATE KEY UPDATE v=VALUES(v)")->execute([$days]);
    jout(['ok'=>true,'days'=>$days]);
  }

  // ==================== ЭТАП 4: выгрузки для 1С / Excel ====================
  case 'export_csv': {
    $s = authUser('itc'); require_staff($s, ['accountant','chief_accountant','manager']);
    $d = body(); $type = $d['type'] ?? 'suppliers';
    $q = function($x){ return str_replace([';',"\r","\n"], [',',' ',' '], (string)$x); };
    $co = ['jinjia'=>'Jinjia (КНР)','itk'=>'ИТК (РФ)'];
    $mo = ['prepay30'=>'30% предоплата + 70% при приёмке','prepay100'=>'100% предоплата','warehouse'=>'По факту поставки на склад','received_ru'=>'По получению в России','prepay'=>'100% предоплата','received'=>'По получению в России'];
    $csv = "\xEF\xBB\xBF"; $fn = '1c_export.csv';
    if ($type === 'suppliers') {
      $fn = '1c_kontragenty.csv';
      $csv .= "Наименование;Кит. наименование;Категория оплаты;Момент оплаты;ИНН/USCC;Телефон;E-mail;Банк;Счёт;Договор №\r\n";
      foreach (db()->query("SELECT name,zh,pay_company,pay_moment,reg_data,phone,email,contract_no FROM suppliers WHERE mod_status='approved' ORDER BY name")->fetchAll() as $r) {
        $rd = json_decode($r['reg_data'] ?: '{}', true) ?: [];
        $tax = $rd['inn'] ?? ($rd['usci'] ?? '');
        $csv .= implode(';', [$q($r['name']),$q($r['zh']),($co[$r['pay_company']] ?? ''),($mo[$r['pay_moment']] ?? 'не задано'),$q($tax),$q($r['phone']),$q($r['email']),$q($rd['bank'] ?? ''),$q($rd['account'] ?? ''),$q($r['contract_no'])]) . "\r\n";
      }
    } elseif ($type === 'batches') {
      $fn = '1c_postuplenia.csv';
      $csv .= "Партия;Дата;Поставщик;Категория;Товар;Кол-во;Цена CNY;Сумма CNY\r\n";
      foreach (db()->query("SELECT b.batch_no, DATE_FORMAT(b.created_at,'%d.%m.%Y') dt, s.name sup, s.pay_company, i.name nm, i.qty, p.goods_cny FROM supply_batches b JOIN suppliers s ON s.id=b.supplier_id JOIN order_items i ON i.batch_id=b.id LEFT JOIN products p ON p.id=i.product_id ORDER BY b.created_at DESC LIMIT 5000")->fetchAll() as $r) {
        $sum = (int)$r['qty'] * (float)$r['goods_cny'];
        $csv .= implode(';', [$q($r['batch_no']),$r['dt'],$q($r['sup']),($co[$r['pay_company']] ?? ''),$q($r['nm']),(int)$r['qty'],(float)$r['goods_cny'],$sum]) . "\r\n";
      }
    } else { // payments
      $fn = '1c_platezhi.csv';
      $csv .= "Заказ;Поставщик;Категория;Момент оплаты;Товар;Кол-во;Сумма CNY;Оплачено\r\n";
      foreach (db()->query("SELECT o.num, s.name sup, s.pay_company, s.pay_moment, i.name nm, i.qty, p.goods_cny, i.paid_supplier FROM order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1 JOIN suppliers s ON s.id=i.supplier_id LEFT JOIN products p ON p.id=i.product_id ORDER BY o.created_at DESC LIMIT 5000")->fetchAll() as $r) {
        $sum = (int)$r['qty'] * (float)$r['goods_cny'];
        $csv .= implode(';', [$q($r['num']),$q($r['sup']),($co[$r['pay_company']] ?? ''),($mo[$r['pay_moment']] ?? 'не задано'),$q($r['nm']),(int)$r['qty'],$sum,((int)$r['paid_supplier'] ? 'да' : 'нет')]) . "\r\n";
      }
    }
    jout(['ok'=>true,'csv'=>base64_encode($csv),'filename'=>$fn]);
  }

  // ==================== ЭТАП 5: управляемые поставщики ====================

  // ---- Создать управляемую фабрику (менеджер/босс) ----
  case 'managed_supplier_create': {
    $s = authUser('itc'); require_staff($s, ['manager','supervisor']);
    $d = body();
    $name = trim($d['name'] ?? ''); if (!$name) fail('Укажите название фабрики');
    $payco = (($d['pay_company'] ?? 'jinjia') === 'itk') ? 'itk' : 'jinjia';
    $moment = in_array(($d['pay_moment'] ?? ''), ['prepay30','prepay100','warehouse','received_ru'], true) ? $d['pay_moment'] : 'prepay30';
    $cnTax = in_array(($d['cn_tax_status'] ?? ''), ['general','small'], true) ? $d['cn_tax_status'] : null;
    $cnVat = (isset($d['cn_vat_refund']) && $d['cn_vat_refund'] !== '') ? (float)$d['cn_vat_refund'] : null;
    $cnFap = !empty($d['cn_fapiao']) ? 1 : 0;
    $reg = is_array($d['reg_data'] ?? null) ? $d['reg_data'] : [];
    $by = mb_substr(trim($d['by'] ?? ''), 0, 120);
    $staffId = current_staff_id($s);
    $mgr = trim($d['managed_by'] ?? '');
    if (!$mgr) {
      if ($staffId) { $mgr = $staffId; } // supervisor/manager создаёт — на себя
      else { // босс (нет staff-записи) — по умолчанию на первого супервайзера
        try { $sv = db()->query("SELECT id FROM staff WHERE role='supervisor' AND active=1 ORDER BY created_at ASC LIMIT 1")->fetchColumn(); if ($sv) $mgr = (string)$sv; } catch (Exception $e) {}
      }
    }
    $id = gen('s');
    $cno = 'ITK-'.date('Y').'/'.strtoupper(substr($id, -5));
    db()->prepare('INSERT INTO suppliers (id,name,zh,phone,jurisdiction,contact,email,status,deposit_paid,reg_data,pay_company,pay_moment,cn_tax_status,cn_vat_refund,cn_fapiao,mod_status,moderated_by,moderated_at,sup_kind,created_by,managed_by,contract_no,contract_at,contract_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),?,?,?,?,NOW(),?)')
      ->execute([$id,$name,trim($d['zh'] ?? ''),'m:'.$id,($d['jurisdiction'] ?? 'cn'),trim($d['contact'] ?? ''),trim($d['email'] ?? ''),'active',1,json_encode($reg,JSON_UNESCAPED_UNICODE),$payco,$moment,$cnTax,$cnVat,$cnFap,'approved',$by,'managed',$staffId,$mgr,$cno,'generated']);
    itc_log_add($by, 'managed_create', 'supplier', $id, $name);
    jout(['ok'=>true,'id'=>$id]);
  }

  // ---- Список управляемых фабрик (менеджер — свои, босс — все) ----
  case 'managed_suppliers_list': {
    $s = authUser('itc'); require_staff($s, ['manager','supervisor']);
    $boss = staff_can_see_all($s);
    $staffId = current_staff_id($s);
    $sql = "SELECT s.id,s.name,s.zh,s.pay_company,s.pay_moment,s.created_by,s.managed_by,s.contract_no,s.contract_status,
        (SELECT COUNT(*) FROM products p WHERE p.supplier_id=s.id) prod,
        cs.name created_name, ms.name manager_name
        FROM suppliers s
        LEFT JOIN staff cs ON cs.id=s.created_by
        LEFT JOIN staff ms ON ms.id=s.managed_by
        WHERE s.sup_kind='managed'";
    if (!$boss) $sql .= " AND s.managed_by=?";
    $sql .= " ORDER BY s.created_at DESC";
    $st = db()->prepare($sql);
    $st->execute($boss ? [] : [$staffId]);
    $rows = [];
    foreach ($st->fetchAll() as $r) {
      $rows[] = ['id'=>$r['id'],'name'=>$r['name'],'zh'=>$r['zh'],'pay_company'=>$r['pay_company'],'pay_moment'=>$r['pay_moment'],
        'created_by'=>$r['created_by'],'created_name'=>$r['created_name'],'managed_by'=>$r['managed_by'],'manager_name'=>$r['manager_name'],
        'contract_no'=>$r['contract_no'],'contract_status'=>$r['contract_status'],'products'=>(int)$r['prod']];
    }
    jout(['ok'=>true,'managed'=>$rows,'is_boss'=>$boss?1:0]);
  }

  // ---- Переназначить менеджера управляемой фабрики (только босс) ----
  case 'managed_supplier_reassign': {
    $s = authUser('itc'); require_staff($s, ['manager','supervisor']);
    if (!staff_can_see_all($s)) fail('Переназначать может только руководитель или супервайзер', 403);
    $d = body();
    $id = trim($d['id'] ?? ''); $mgr = trim($d['managed_by'] ?? '');
    if (!$id || !$mgr) fail('Укажите фабрику и менеджера');
    db()->prepare("UPDATE suppliers SET managed_by=? WHERE id=? AND sup_kind='managed'")->execute([$mgr, $id]);
    itc_log_add(mb_substr(trim($d['by'] ?? ''), 0, 120), 'managed_reassign', 'supplier', $id, '→ '.$mgr);
    jout(['ok'=>true]);
  }

  // ---- Список менеджеров (для назначения) ----
  case 'managers_list': {
    $s = authUser('itc'); require_staff($s, ['manager','supervisor']);
    $rows = [];
    try { foreach (db()->query("SELECT id,name,role FROM staff WHERE role IN ('manager','supervisor') AND active=1 ORDER BY (role='supervisor') DESC, name")->fetchAll() as $r) $rows[] = ['id'=>$r['id'],'name'=>($r['name'] ?: $r['role']),'role'=>$r['role']]; } catch (Exception $e) {}
    jout(['ok'=>true,'managers'=>$rows]);
  }

  // ---- Удаление поставщика (и его товаров) ----
  case 'supplier_delete': {
    $s = authUser('itc'); require_staff($s, ['moderator']);
    $d = body();
    $id = trim($d['id'] ?? '');
    if (!$id) fail('Не указан поставщик');
    try { db()->prepare("DELETE FROM products WHERE supplier_id=?")->execute([$id]); } catch (Exception $e) {}
    db()->prepare("DELETE FROM suppliers WHERE id=?")->execute([$id]);
    itc_log_add(mb_substr(trim($d['by'] ?? ''), 0, 120), 'supplier_delete', 'supplier', $id, 'Удалён поставщик');
    jout(['ok'=>true]);
  }

  // ---- Поставщик: мои расчёты (сколько должны / оплачено) ----
  case 'supplier_my_payments': {
    $s = authUser('supplier');
    $sid = $s['supplier_id'] ?? '';
    if (!$sid) fail('Нет доступа');
    $st = db()->prepare("SELECT i.order_id,i.name,i.qty,i.paid_supplier,UNIX_TIMESTAMP(i.paid_supplier_at)*1000 pst, p.goods_cny, o.num, UNIX_TIMESTAMP(o.created_at)*1000 ots, s.pay_moment FROM order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1 JOIN suppliers s ON s.id=i.supplier_id LEFT JOIN products p ON p.id=i.product_id WHERE i.supplier_id=? ORDER BY o.created_at DESC LIMIT 500");
    $st->execute([$sid]);
    $list = []; $totDue = 0; $totPaid = 0;
    foreach ($st->fetchAll() as $r) {
      $cny = round(((float)$r['goods_cny']) * (int)$r['qty'], 2);
      $paid = (int)$r['paid_supplier'];
      if ($paid) $totPaid += $cny; else $totDue += $cny;
      $list[] = ['num'=>$r['num'],'name'=>$r['name'],'qty'=>(int)$r['qty'],'cny'=>$cny,'paid'=>$paid,'pst'=>(int)$r['pst'],'pay_moment'=>$r['pay_moment'],'ots'=>(int)$r['ots']];
    }
    jout(['ok'=>true,'items'=>$list,'total_due'=>round($totDue,2),'total_paid'=>round($totPaid,2)]);
  }

  // ---- Поставщик: опубликовать черновик ----
  case 'product_publish': {
    $s = authUser('supplier'); $sid = $s['supplier_id'] ?? '';
    $d = body(); $id = trim($d['id'] ?? '');
    if (!$sid || !$id) fail('Нет данных');
    $chk = db()->prepare("SELECT COUNT(*) FROM products WHERE id=? AND supplier_id=?");
    $chk->execute([$id, $sid]);
    if (!$chk->fetchColumn()) fail('Нет доступа');
    db()->prepare("UPDATE products SET mod_status='pending' WHERE id=?")->execute([$id]);
    jout(['ok'=>true]);
  }

  // ---- Поставщик: отзывы на мои товары ----
  case 'supplier_my_reviews': {
    $s = authUser('supplier'); $sid = $s['supplier_id'] ?? '';
    if (!$sid) fail('Нет доступа');
    $st = db()->prepare("SELECT r.id,r.product_id,r.name,r.rating,r.text,r.answer,UNIX_TIMESTAMP(r.created_at)*1000 ts, p.name pname FROM reviews r JOIN products p ON p.id=r.product_id WHERE p.supplier_id=? AND (r.mod_status='approved' OR r.mod_status='' OR r.mod_status IS NULL) ORDER BY r.created_at DESC LIMIT 300");
    $st->execute([$sid]);
    jout(['ok'=>true,'reviews'=>$st->fetchAll()]);
  }

  // ---- Поставщик: ответить на отзыв ----
  case 'supplier_review_answer': {
    $s = authUser('supplier'); $sid = $s['supplier_id'] ?? '';
    $d = body(); $rid = trim($d['id'] ?? ''); $ans = mb_substr(trim($d['answer'] ?? ''), 0, 1000);
    if (!$sid || !$rid) fail('Нет данных');
    $chk = db()->prepare("SELECT COUNT(*) FROM reviews r JOIN products p ON p.id=r.product_id WHERE r.id=? AND p.supplier_id=?");
    $chk->execute([$rid, $sid]);
    if (!$chk->fetchColumn()) fail('Нет доступа к отзыву');
    db()->prepare("UPDATE reviews SET answer=? WHERE id=?")->execute([$ans, $rid]);
    jout(['ok'=>true]);
  }

  // ============================================================
  //  ДРОПШИППИНГ — сотрудники, каталог, очередь закупок
  // ============================================================

  // --- Хелперы ---
  function ds_role($s){ return $s['ds_role'] ?? null; }
  function require_ds($s){ if(empty($s['ds_id'])) fail('Нет доступа к модулю дропшиппинга'); }
  function require_ds_boss($s){ require_ds($s); if(!in_array(ds_role($s),['ds_boss'])) fail('Только DS-босс'); }
  function require_ds_sup($s){ require_ds($s); if(!in_array(ds_role($s),['ds_boss','ds_supervisor'])) fail('Только DS-босс или супервайзер'); }
  function ds_auth($token){
    if(!$token) return [];
    $q=db()->prepare('SELECT id,name,phone,role as ds_role,supervisor_id,active FROM ds_staff WHERE code=? AND active=1');
    $q->execute([$token]);
    $r=$q->fetch();
    return $r ? array_merge($r,['ds_id'=>$r['id']]) : [];
  }
  // --- DS Staff ---
  case 'ds_staff_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $q=db()->query('SELECT s.*,sup.name sup_name FROM ds_staff s LEFT JOIN ds_staff sup ON sup.id=s.supervisor_id ORDER BY s.role,s.name');
    jout(['ok'=>true,'staff'=>$q->fetchAll()]);
  }
  case 'ds_staff_save': {
    $s=authUser('itc'); require_staff($s,['boss','supervisor']);
    $d=body();
    $id=trim($d['id']??'');
    $name=trim($d['name']??''); $phone=trim($d['phone']??'');
    $role=trim($d['role']??'ds_manager'); $sup=trim($d['supervisor_id']??'');
    if(!$name||!$phone) fail('Укажите имя и телефон');
    if(!in_array($role,['ds_boss','ds_supervisor','ds_manager'])) fail('Неверная роль');
    if($role==='ds_manager'&&!$sup&&!$id) fail('DS-менеджер должен быть прикреплён к супервайзеру');
    if($id){
      db()->prepare('UPDATE ds_staff SET name=?,phone=?,role=?,supervisor_id=? WHERE id=?')
        ->execute([$name,$phone,$role,$sup?:null,$id]);
    } else {
      $id=gen_ds_id();
      $code=staff_gen_code(); // 10-значный hex как у ИТК-сотрудников
      db()->prepare('INSERT INTO ds_staff(id,name,phone,role,supervisor_id,code) VALUES(?,?,?,?,?,?)')
        ->execute([$id,$name,$phone,$role,$sup?:null,$code]);
    }
    jout(['ok'=>true,'id'=>$id]);
  }
  case 'ds_staff_regen': {
    $s=authUser('itc'); require_staff($s,['boss','supervisor']);
    $d=body(); $id=trim($d['id']??'');
    if(!$id) fail('id обязателен');
    $code=staff_gen_code(); // 10-значный hex как у ИТК-сотрудников
    db()->prepare('UPDATE ds_staff SET code=? WHERE id=?')->execute([$code,$id]);
    jout(['ok'=>true,'code'=>$code]);
  }
  case 'ds_staff_toggle': {
    $s=authUser('itc'); require_staff($s,['boss']);
    $d=body(); $id=trim($d['id']??'');
    db()->prepare('UPDATE ds_staff SET active=1-active WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }

  // --- DS Products ---
  /* ---- Модерация дропшиппинга: считаем дерево НА СЕРВЕРЕ ----
     Раньше раздел брал ds_product_list — это все 33 000 карточек целиком, около
     десятка мегабайт JSON. На телефоне экран так и висел в «Загрузка…».
     Теперь отдаём тремя маленькими порциями:
       lvl=1 — верхние группы (дни либо сотрудники) со счётчиками
       lvl=2 — вложенные группы внутри выбранной (категории либо дни)
       lvl=3 — сами товары, страницами по 60
     mode=date  : день → категория → товары
     mode=staff : сотрудник → день → товары                                  */
  case 'ds_mod': {
    $s = authUser('itc'); require_staff($s, ['supervisor','manager','moderator']);
    $plat = ((($_GET['plat'] ?? '1688') === 'pdd') ? 'pdd' : '1688');
    $mode = ((($_GET['mode'] ?? 'date') === 'staff') ? 'staff' : 'date');
    $lvl  = (int)($_GET['lvl'] ?? 1); if ($lvl < 1 || $lvl > 3) $lvl = 1;
    $k1   = (string)($_GET['k1'] ?? '');
    $k2   = (string)($_GET['k2'] ?? '');
    $off  = max(0, (int)($_GET['offset'] ?? 0));
    $lim  = (int)($_GET['limit'] ?? 60); if ($lim < 1 || $lim > 200) $lim = 60;

    $dayE = 'DATE(dp.created_at)';
    $catE = "COALESCE(NULLIF(p.cat,''),'Без категории')";
    /* КТО ЗАВЁЛ. Поле dp.manager_id (назначенный менеджер) на импорте почти
       никогда не заполняется — все 33 000 карточек оказывались в группе
       «сотрудник не указан». Настоящий след лежит в двух других местах:
       products.created_by — имя, которое проставляет stamp_creator при создании
       карточки, и ds_products.created_by — ТЕЛЕФОН сотрудника, по нему находим
       имя в таблице staff. Берём первое, что нашлось. */
    $whoE = "COALESCE(NULLIF(m.name,''), NULLIF(p.created_by,''), NULLIF(st.name,''), '')";

    $w = ["COALESCE(NULLIF(dp.source_platform,''),'1688')=?"]; $a = [$plat];
    if ($lvl >= 2) { $w[] = ($mode === 'date' ? "$dayE=?" : "$whoE=?"); $a[] = $k1; }
    if ($lvl >= 3) { $w[] = ($mode === 'date' ? "$catE=?" : "$dayE=?"); $a[] = $k2; }
    $where = 'WHERE '.implode(' AND ', $w);
    $join  = "FROM ds_products dp LEFT JOIN products p ON p.id=dp.product_id"
           . " LEFT JOIN ds_staff m ON m.id=dp.manager_id"
           . " LEFT JOIN staff st ON COALESCE(dp.created_by,'')<>'' AND REPLACE(st.phone,' ','')=REPLACE(dp.created_by,' ','')";
    $nwE   = 'SUM(CASE WHEN COALESCE(p.weight_kg,0)<=0 THEN 1 ELSE 0 END)';

    if ($lvl < 3) {
      if ($lvl === 1) { $grpE = ($mode === 'date') ? $dayE : $whoE; }
      else            { $grpE = ($mode === 'date') ? $catE : $dayE; }
      $lblE = "''"; // на вкладке «По сотрудникам» ключ группы — это уже само имя
      if ($lvl === 1) $ord = ($mode === 'date') ? 'k DESC' : 'n DESC, k ASC';
      else            $ord = ($mode === 'date') ? 'n DESC, k ASC' : 'k DESC';
      $rows = [];
      try {
        $q = db()->prepare("SELECT $grpE k, $lblE lbl, COUNT(*) n, $nwE nw $join $where GROUP BY k ORDER BY $ord LIMIT 500");
        $q->execute($a);
        foreach ($q->fetchAll() as $r) {
          $rows[] = ['k'=>(string)$r['k'], 'lbl'=>(string)$r['lbl'], 'n'=>(int)$r['n'], 'nw'=>(int)$r['nw']];
        }
      } catch (Exception $e) { fail('Не удалось собрать список: '.$e->getMessage()); }
      jout(['ok'=>true, 'lvl'=>$lvl, 'mode'=>$mode, 'groups'=>$rows]);
    }

    $total = 0;
    try { $qc = db()->prepare("SELECT COUNT(*) $join $where"); $qc->execute($a); $total = (int)$qc->fetchColumn(); }
    catch (Exception $e) {}
    $items = [];
    try {
      $q = db()->prepare("SELECT dp.id, dp.product_id, dp.created_at, dp.ds_status, dp.our_price_rub, dp.source_url,
              $whoE mgr_name, p.name prod_name, p.img prod_img, p.price prod_price,
              $catE cat, COALESCE(p.weight_kg,0) weight_kg, COALESCE(p.volume_m3,0) volume_m3
            $join $where ORDER BY dp.created_at DESC, dp.id ASC LIMIT $lim OFFSET $off");
      $q->execute($a);
      $items = $q->fetchAll();
    } catch (Exception $e) { fail('Не удалось получить товары: '.$e->getMessage()); }
    jout(['ok'=>true, 'lvl'=>3, 'mode'=>$mode, 'items'=>$items, 'total'=>$total, 'offset'=>$off]);
  }
  case 'ds_product_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $q=db()->query('SELECT dp.*,p.name prod_name,p.img prod_img,p.price prod_price,p.created_by created_by,m.name mgr_name
      FROM ds_products dp
      LEFT JOIN products p ON p.id=dp.product_id
      LEFT JOIN ds_staff m ON m.id=dp.manager_id
      ORDER BY dp.created_at DESC');
    $items=$q->fetchAll();
    /* Цену надо проверять ТОЛЬКО у товаров, поставленных на отслеживание в разделе
       «Отслеживание цен 1688» (таблица ob_track, категории A/B/C со сроками 7/21/90
       дней). Остальное отслеживать не нужно — раньше счётчик считал весь каталог
       подряд и показывал 31 931 из 33 100, что не имело смысла. */
    $trackMap = [];
    try { foreach (db()->query("SELECT num_iid, tier FROM ob_track")->fetchAll() as $t) $trackMap[(string)$t['num_iid']] = $t['tier']; }
    catch (Exception $e) {}
    $trkDays = ['A'=>7, 'B'=>21, 'C'=>90];
    foreach($items as &$it){
      $age=ds_price_age_days($it['last_price_check']??null, $it['created_at']??null);
      $it['price_age_days']=$age;
      $iid = '';
      if (preg_match('/offer\\/(\\d+)/', (string)($it['source_url'] ?? ''), $mm)) $iid = $mm[1];
      $tier = ($iid !== '' && isset($trackMap[$iid])) ? strtoupper((string)$trackMap[$iid]) : '';
      $lim  = $trkDays[$tier] ?? 0;
      $it['track_tier'] = $tier;
      $it['track_days'] = $lim;
      // важность по спросу оставляем — она подсказывает, что стоит поставить на отслеживание
      $pt = (int)($it['prio_tier'] ?? 3); if ($pt<1||$pt>3) $pt=3;
      $it['prio_tier'] = $pt;
      $it['tier_name'] = ds_tier_name($pt);
      if (!$lim) { $it['price_status'] = 'untracked'; }
      else { $it['price_status'] = ($age===null) ? 'unknown' : ($age < $lim ? 'fresh' : ($age < $lim*2 ? 'warn' : 'stale')); }
    }
    unset($it);
    jout(['ok'=>true,'items'=>$items]);
  }
  // ---- Справочник типовых товаров (KD-объёмы) для ручного ввода ----
  case 'ds_kd_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $out=[];
    foreach(ds_kd_rules() as $r){
      $out[]=['id'=>$r['id'],'cat'=>$r['cat'],'weight_kg'=>(float)$r['вес'],'volume_m3'=>(float)$r['объём']];
    }
    // Сортируем по категории, затем по объёму — так менеджеру легче искать
    usort($out,function($a,$b){ return $a['cat']===$b['cat'] ? ($a['volume_m3']<=>$b['volume_m3']) : strcmp($a['cat'],$b['cat']); });
    jout(['ok'=>true,'types'=>$out]);
  }

  // ---- РУЧНОЙ ДРОПШИППИНГ: карточка целиком + ссылка на источник за один шаг ----
  // Гибрид карточки поставщика (фото, описание, характеристики, габариты)
  // и DS-карточки (ссылка на 1688/PDD, закупочная цена ¥, менеджер).
  case 'ds_manual_create': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body();
    $id    = trim($d['ds_id']??'');            // при редактировании
    $url   = trim($d['source_url']??'');
    $name  = trim($d['name']??'');
    if(!$url)  fail('Вставьте ссылку на товар — без неё карточку не найти потом');
    if(!$name) fail('Укажите название товара');

    $plat = trim($d['source_platform']??'');
    if($plat==='') { $plat=ds_detect_platform($url); if($plat==='') $plat='1688'; }

    // Дубль — предупреждение, а не блок: менеджер решает сам (force).
    if(empty($d['force']) && ($dup=ds_find_duplicate($url,$plat,$id))){
      jout(['ok'=>false,'duplicate'=>$dup,'error'=>'Товар с этой ссылкой уже заведён']); break;
    }

    $pcny  = (float)($d['source_price_cny']??0);
    $color = mb_substr(trim($d['color']??''),0,60);
    $mgr   = trim($d['manager_id']??'');
    $tpl   = trim($d['weight_template_id']??'');
    $descr = trim($d['descr']??'');
    $cat   = trim($d['cat']??'Прочее')?:'Прочее';
    $subcat= trim($d['subcat']??'');
    $imgs  = is_array($d['gallery']??null)?array_values(array_filter($d['gallery'])):[];
    $video = trim($d['video']??'');
    $stock = (int)($d['stock']??0);
    $orig  = (int)($d['original']??1);
    $oldPrub = isset($d['old_price_rub'])&&$d['old_price_rub']>0?(int)$d['old_price_rub']:null;

    // Вес/объём: из шаблона или введённые вручную. Без объёма цена не считается.
    $dwt  = (isset($d['declared_weight_kg']) && (float)$d['declared_weight_kg']>0) ? (float)$d['declared_weight_kg'] : null;
    $dvol = (isset($d['declared_volume_m3']) && (float)$d['declared_volume_m3']>0) ? (float)$d['declared_volume_m3'] : null;

    $cover   = count($imgs)?$imgs[0]:'';
    $gallery = json_encode(array_slice($imgs,0,10),JSON_UNESCAPED_UNICODE);
    $price   = ($pcny>0 && $dvol) ? ds_calc_price_rub($pcny,$dvol,$dwt?:0) : 0;
    $draft   = !empty($d['draft']);
    // Карточку заводит сотрудник ИТК — модерация не нужна (она для сторонних поставщиков).
    // Черновик остаётся черновиком, опубликованная сразу уходит в каталог.
    $modStatus = $draft ? 'draft' : 'approved';

    if($id){
      // --- Редактирование существующей ручной карточки ---
      $q=db()->prepare('SELECT product_id FROM ds_products WHERE id=?'); $q->execute([$id]);
      $pid=$q->fetchColumn();
      if(!$pid) fail('Карточка не найдена');
      db()->prepare('UPDATE products SET cat=?,subcat=?,name=?,price=?,old_price=?,goods_cny=?,volume_m3=?,descr=?,img=?,gallery=?,video=?,stock=?,original=?,weight_kg=?,color=? WHERE id=?')
        ->execute([$cat,$subcat,$name,$price,$oldPrub?:0,$pcny?:0,$dvol,$descr,$cover,$gallery,$video,$stock,$orig,$dwt,$color,$pid]);
      db()->prepare('UPDATE ds_products SET source_url=?,source_platform=?,source_price_cny=?,manager_id=?,price_changed=0,declared_weight_kg=?,declared_volume_m3=?,weight_template_id=?,old_price_rub=?,last_price_check=NOW() WHERE id=?')
        ->execute([$url,$plat,$pcny?:null,$mgr?:null,$dwt,$dvol,$tpl?:null,$oldPrub,$id]);
    } else {
      // --- Создание новой карточки ---
      $pid = pdd_gen_pid();
      db()->prepare('INSERT INTO products(id,supplier_id,cat,subcat,name,price,old_price,goods_cny,volume_m3,descr,img,gallery,video,stock,original,mod_status,weight_kg,color) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
        ->execute([$pid,ds_supplier_id(),$cat,$subcat,$name,$price,$oldPrub?:0,$pcny?:0,$dvol,$descr,$cover,$gallery,$video,$stock,$orig,$modStatus,$dwt,$color]);
      stamp_creator($pid, $s);
      $id=gen_ds_id();
      db()->prepare('INSERT INTO ds_products(id,product_id,source_url,source_platform,source_price_cny,manager_id,declared_weight_kg,declared_volume_m3,weight_template_id,old_price_rub,created_by,last_price_check) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())')
        ->execute([$id,$pid,$url,$plat,$pcny?:null,$mgr?:null,$dwt,$dvol,$tpl?:null,$oldPrub,$s['phone']??'']);
    }

    ds_mark_auto($id);
    // Характеристики, габариты, варианты — как в карточке поставщика
    save_specs($pid,$d);
    save_dims($pid,$d);
    save_variants($pid,$d);
    try{ db()->prepare('UPDATE products SET pcs_per_box=?,ready_type=?,production_days=? WHERE id=?')
      ->execute([(((int)($d['pcs_per_box']??0))?:null),
                 ((($d['ready_type']??'')==='production')?'production':'in_stock'),
                 (((($d['ready_type']??'')==='production')&&((int)($d['production_days']??0)>0))?(int)$d['production_days']:null),$pid]); }catch(Exception $e){}
    // Публикуем сразу от имени сотрудника (без очереди модерации)
    try{ db()->prepare('UPDATE products SET mod_status=?, moderated_by=?, moderated_at=NOW() WHERE id=?')
      ->execute([$modStatus, ($draft?null:mb_substr(trim($d['by']??($s['phone']??'ИТК')),0,120)), $pid]); }
    catch(Exception $e){ try{ db()->prepare('UPDATE products SET mod_status=? WHERE id=?')->execute([$modStatus,$pid]); }catch(Exception $e2){} }

    ds_sync_product_price($id);
    $blocked = (!$dvol || $pcny<=0);
    jout(['ok'=>true,'ds_id'=>$id,'product_id'=>$pid,'price'=>$price,'blocked'=>$blocked,
          'msg'=>$blocked ? '⚠ Сохранено, но цена не рассчитана: нужны закупочная цена ¥ и объём'
                          : ($draft?'💾 Черновик сохранён':'✅ Карточка опубликована в каталоге')]);
    break;
  }

  // ---- Данные одной ручной DS-карточки для редактирования ----
  case 'ds_manual_get': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    if(!$id) fail('id обязателен');
    $q=db()->prepare('SELECT dp.*, p.name,p.cat,p.subcat,p.descr,p.img,p.gallery,p.video,p.stock,p.original,
                             p.pcs_per_box,p.ready_type,p.production_days,p.mod_status,p.variants,
                             p.specs,p.boxes,p.assembled
                      FROM ds_products dp LEFT JOIN products p ON p.id=dp.product_id WHERE dp.id=?');
    $q->execute([$id]); $row=$q->fetch();
    if(!$row) fail('Карточка не найдена');
    $row['gallery'] = json_decode($row['gallery']??'[]',true) ?: [];
    $row['variants']= json_decode($row['variants']??'null',true);
    $row['specs']   = json_decode($row['specs']??'[]',true) ?: [];
    $row['boxes']   = json_decode($row['boxes']??'[]',true) ?: [];
    jout(['ok'=>true,'item'=>$row]);
  }

  // ---- AI-перевод одного поля (кнопка ✨ возле поля) ----
  case 'ai_translate': {
    $s=authUser(); // доступно и поставщику, и сотруднику ИТК
    $d=body();
    $text=trim($d['text']??'');
    $kind=trim($d['kind']??'plain');
    $ctx=trim($d['ctx']??'');
    if($text==='') fail('Нечего переводить — поле пустое');
    if(mb_strlen($text)>4000) fail('Слишком длинный текст (максимум 4000 символов)');
    $out=ai_translate_field($text,$kind,$ctx);
    $src='deepseek';
    if($out===null){ $out=pdd_translate($text); $src='mymemory'; }  // откат, если DeepSeek недоступен
    if($out===null||$out===''){ fail('Переводчик недоступен, попробуйте позже',502); }
    jout(['ok'=>true,'text'=>$out,'source'=>$src,'had_cjk'=>has_cjk($text)]);
  }
  // ---- AI-перевод всей карточки одной кнопкой ----
  case 'ai_translate_card': {
    $s=authUser();
    $d=body();
    $name=trim($d['name']??''); $descr=trim($d['descr']??''); $specs=trim($d['specs']??'');
    if($name===''&&$descr===''&&$specs==='') fail('Карточка пуста — нечего переводить');
    $res=['ok'=>true,'source'=>'deepseek'];
    // Название переводим первым — оно служит контекстом для остальных полей.
    if($name!==''){
      $n=ai_translate_field($name,'name');
      if($n===null){ $n=pdd_translate($name); $res['source']='mymemory'; }
      $res['name']=$n;
    }
    $ctx=$res['name']??$name;
    if($descr!==''){
      $ds=ai_translate_field($descr,'description',$ctx);
      if($ds===null){ $ds=pdd_translate($descr); $res['source']='mymemory'; }
      $res['descr']=$ds;
    }
    if($specs!==''){
      $sp=ai_translate_field($specs,'specs',$ctx);
      if($sp===null){ $sp=pdd_translate($specs); $res['source']='mymemory'; }
      $res['specs']=$sp;
    }
    jout($res);
  }
  // ---- Менеджер подтверждает: цена у поставщика не изменилась ----
  case 'ds_price_confirm': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    if(!$id) fail('id обязателен');
    $newp=isset($d['source_price_cny'])&&$d['source_price_cny']!=='' ? (float)$d['source_price_cny'] : null;
    if($newp!==null && $newp>0){
      db()->prepare('UPDATE ds_products SET source_price_cny=?,last_price_check=NOW(),price_changed=0 WHERE id=?')->execute([$newp,$id]);
      ds_sync_product_price($id);
    } else {
      db()->prepare('UPDATE ds_products SET last_price_check=NOW() WHERE id=?')->execute([$id]);
    }
    $r=db()->prepare('SELECT source_price_cny,our_price_rub,last_price_check FROM ds_products WHERE id=?');
    $r->execute([$id]); $row=$r->fetch();
    jout(['ok'=>true,'row'=>$row,'msg'=>$newp?'✅ Цена обновлена':'✅ Цена подтверждена']);
  }
  // ---- Поиск карточки по ссылке источника (для менеджера) ----
  case 'ds_search_by_url': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $url=trim($d['url']??'');
    if($url==='') fail('Вставьте ссылку на товар');
    $plat=ds_detect_platform($url);
    $found=ds_find_duplicate($url,$plat);
    jout(['ok'=>true,'platform'=>$plat?:'unknown','key'=>ds_source_key($url,$plat),'found'=>$found]);
  }
  // ---- Счётчик товаров с устаревшей ценой (для дашборда) ----
  case 'ds_stale_count': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $q=db()->query("SELECT COUNT(*) c FROM ds_products
      WHERE COALESCE(last_price_check,created_at) < DATE_SUB(NOW(), INTERVAL 7 DAY)");
    $warn=(int)($q->fetch()['c']??0);
    $q2=db()->query("SELECT COUNT(*) c FROM ds_products
      WHERE COALESCE(last_price_check,created_at) < DATE_SUB(NOW(), INTERVAL 14 DAY)");
    $stale=(int)($q2->fetch()['c']??0);
    jout(['ok'=>true,'need_check'=>$warn,'critical'=>$stale]);
  }
  case 'ds_templates_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $q=db()->query('SELECT * FROM ds_weight_templates ORDER BY sort_order,category,label');
    jout(['ok'=>true,'templates'=>$q->fetchAll()]);
  }
  case 'ds_templates_save': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $id=trim($d['id']??''); $cat=trim($d['category']??''); $lbl=trim($d['label']??'');
    $wt=(float)($d['weight_kg']??0); $vol=(float)($d['volume_m3']??0); $sort=(int)($d['sort_order']??0);
    if(!$cat||!$lbl||$wt<=0||$vol<=0) fail('Заполните все поля');
    if($id){
      db()->prepare('UPDATE ds_weight_templates SET category=?,label=?,weight_kg=?,volume_m3=?,sort_order=? WHERE id=?')->execute([$cat,$lbl,$wt,$vol,$sort,$id]);
      /* Замер принят в шаблон — накопленное обнуляем, иначе кнопка «принять»
         висела бы вечно и предлагала принять то, что уже принято. */
      if (!empty($d['reset_fact'])) {
        try { db()->prepare('UPDATE ds_weight_templates SET fact_weight_kg=NULL,fact_volume_m3=NULL,fact_count=0 WHERE id=?')->execute([$id]); }
        catch (Exception $e) {}
      }
    } else {
      $id=gen_ds_id();
      db()->prepare('INSERT INTO ds_weight_templates(id,category,label,weight_kg,volume_m3,sort_order) VALUES(?,?,?,?,?,?)')->execute([$id,$cat,$lbl,$wt,$vol,$sort]);
    }
    jout(['ok'=>true,'id'=>$id]);
  }
  case 'ds_templates_delete': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    db()->prepare('DELETE FROM ds_weight_templates WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }
  case 'ds_weigh': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    $awt=(float)($d['actual_weight_kg']??0); $avol=(float)($d['actual_volume_m3']??0);
    if(!$id) fail('id обязателен');
    $pq=db()->prepare('SELECT dp.id dsid, dp.product_id pid, dp.declared_weight_kg dswt FROM ds_procurement pc LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id WHERE pc.id=?');
    $pq->execute([$id]); $row=$pq->fetch();
    $decl=(float)($row['dswt']??0);
    $variance=($decl>0&&$awt>0)?round((($awt-$decl)/$decl)*100,2):null;
    db()->prepare('UPDATE ds_procurement SET actual_weight_kg=?,actual_volume_m3=?,weight_variance_pct=?,weighed_at=NOW() WHERE id=?')->execute([$awt?:null,$avol?:null,$variance,$id]);
    // Замер → переносим факт в карточку, снимаем режим ×3, пересчитываем на ТОЧНУЮ цену (кат. C).
    // Оформленные заказы не трогаются — цена там зафиксирована в order_items.
    $dsid=(string)($row['dsid']??''); $pid=(string)($row['pid']??''); $newRub=null;
    if($dsid && ($awt>0 || $avol>0)){
      $sets=[]; $args=[];
      if($awt>0){ $sets[]='declared_weight_kg=?'; $args[]=$awt; }
      if($avol>0){ $sets[]='declared_volume_m3=?'; $args[]=$avol; }
      $sets[]='x3_pending=0'; $args[]=$dsid;
      try{ db()->prepare('UPDATE ds_products SET '.implode(',',$sets).' WHERE id=?')->execute($args); }catch(Exception $e){}
      if($pid){
        $ps=[]; $pa=[];
        if($awt>0){ $ps[]='weight_kg=?'; $pa[]=$awt; }
        if($avol>0){ $ps[]='volume_m3=?'; $pa[]=$avol; }
        if($ps){ $pa[]=$pid; try{ db()->prepare('UPDATE products SET '.implode(',',$ps).' WHERE id=?')->execute($pa); }catch(Exception $e){} }
      }
      ds_sync_product_price($dsid);   // x3_pending=0 → точная формула
      try{ $rq=db()->prepare('SELECT our_price_rub FROM ds_products WHERE id=?'); $rq->execute([$dsid]); $newRub=(int)$rq->fetchColumn(); }catch(Exception $e){}

      /* ЗАМЕР КОПИТСЯ В ШАБЛОНЕ ВЕСА (обновление №212).
         Раньше факт с весов расходился по карточке товара и на этом всё —
         шаблон, из которого брали предварительный вес, оставался прежним.
         Значит следующая такая же позиция снова заводилась с тем же неверным
         числом, и так по кругу.
         Шаблон НЕ перезаписываем: он общий для многих товаров, и одно
         взвешивание не повод менять цену всем. Копим среднее по замерам
         отдельными колонками — менеджер видит «по факту столько-то, замеров
         столько-то» и одной кнопкой принимает его в шаблон. */
      try {
        $tq=db()->prepare('SELECT weight_template_id FROM ds_products WHERE id=?');
        $tq->execute([$dsid]); $tplId=(string)$tq->fetchColumn();
      } catch (Exception $e) { $tplId=''; }
      if ($tplId !== '') {
        foreach ([
          "ALTER TABLE ds_weight_templates ADD COLUMN fact_weight_kg DECIMAL(10,3) NULL",
          "ALTER TABLE ds_weight_templates ADD COLUMN fact_volume_m3 DECIMAL(10,4) NULL",
          "ALTER TABLE ds_weight_templates ADD COLUMN fact_count INT NOT NULL DEFAULT 0",
          "ALTER TABLE ds_weight_templates ADD COLUMN fact_at DATETIME NULL",
        ] as $q) { try { db()->query($q); } catch (Exception $e) {} }
        try {
          $cur=db()->prepare('SELECT fact_weight_kg,fact_volume_m3,fact_count FROM ds_weight_templates WHERE id=?');
          $cur->execute([$tplId]); $c=$cur->fetch();
          if ($c) {
            $n  = (int)($c['fact_count'] ?? 0);
            $fw = ($c['fact_weight_kg']  !== null) ? (float)$c['fact_weight_kg']  : 0;
            $fv = ($c['fact_volume_m3']  !== null) ? (float)$c['fact_volume_m3']  : 0;
            // среднее пересчитываем по-старому среднему и числу замеров
            $nw = ($awt > 0) ? (($fw * $n + $awt) / ($n + 1)) : $fw;
            $nv = ($avol > 0) ? (($fv * $n + $avol) / ($n + 1)) : $fv;
            db()->prepare('UPDATE ds_weight_templates SET fact_weight_kg=?,fact_volume_m3=?,fact_count=?,fact_at=NOW() WHERE id=?')
                ->execute([round($nw,3), round($nv,4), $n + 1, $tplId]);
          }
        } catch (Exception $e) {}
      }
    }
    jout(['ok'=>true,'variance'=>$variance,'new_price_rub'=>$newRub]);
  }
  case 'ds_product_save': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body();
    $id=trim($d['id']??''); $pid=trim($d['product_id']??''); $url=trim($d['source_url']??'');
    $plat=trim($d['source_platform']??''); $pcny=(float)($d['source_price_cny']??0);
    $mgr=trim($d['manager_id']??'');
    $dwt=isset($d['declared_weight_kg'])&&$d['declared_weight_kg']!==''?(float)$d['declared_weight_kg']:null;
    $dvol=isset($d['declared_volume_m3'])&&$d['declared_volume_m3']!==''?(float)$d['declared_volume_m3']:null;
    $tpl=trim($d['weight_template_id']??'');
    $oldPrub=isset($d['old_price_rub'])&&$d['old_price_rub']>0?(int)$d['old_price_rub']:null;
    if(!$pid||!$url) fail('product_id и source_url обязательны');
    // Платформа определяется по ссылке; явно переданная имеет приоритет.
    if($plat==='') { $plat=ds_detect_platform($url); if($plat==='') $plat='1688'; }
    // Предупреждение о дубле (не блокировка): менеджер может подтвердить через force.
    if(empty($d['force']) && ($dup=ds_find_duplicate($url,$plat,$id))){
      jout(['ok'=>false,'duplicate'=>$dup,'error'=>'Товар с этой ссылкой уже заведён']); break;
    }
    if($id){
      db()->prepare('UPDATE ds_products SET product_id=?,source_url=?,source_platform=?,source_price_cny=?,manager_id=?,price_changed=0,declared_weight_kg=?,declared_volume_m3=?,weight_template_id=?,old_price_rub=?,last_price_check=NOW() WHERE id=?')
        ->execute([$pid,$url,$plat,$pcny?:null,$mgr?:null,$dwt,$dvol,$tpl?:null,$oldPrub,$id]);
    } else {
      $id=gen_ds_id();
      db()->prepare('INSERT INTO ds_products(id,product_id,source_url,source_platform,source_price_cny,manager_id,declared_weight_kg,declared_volume_m3,weight_template_id,old_price_rub,created_by,last_price_check) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())')
        ->execute([$id,$pid,$url,$plat,$pcny?:null,$mgr?:null,$dwt,$dvol,$tpl?:null,$oldPrub,$s['phone']??'']);
    }
    // Синхронизируем цену в каталоге (или блокируем если нет объёма)
    ds_sync_product_price($id);
    $blocked=($pcny<=0||!$dvol)?1:0;
    jout(['ok'=>true,'id'=>$id,'blocked'=>$blocked,'msg'=>$blocked?'⚠ Товар заблокирован: нет цены или объёма':'✅ Цена обновлена в каталоге']);
  }
  case 'ds_product_price_update': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $id=trim($d['id']??'');
    $pcny=(float)($d['source_price_cny']??0);
    if(!$id) fail('id обязателен');
    db()->prepare('UPDATE ds_products SET source_price_cny=?,last_price_check=NOW() WHERE id=?')
      ->execute([$pcny?:null,$id]);
    // Пересчитываем и синхронизируем с каталогом
    ds_sync_product_price($id);
    $dp=db()->prepare('SELECT our_price_rub FROM ds_products WHERE id=?');
    $dp->execute([$id]); $dprow=$dp->fetch();
    jout(['ok'=>true,'our_price_rub'=>$dprow['our_price_rub']]);
  }
  case 'ds_product_delete': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    // Удаляем и связанную витринную карточку, но ТОЛЬКО если она авто-создана дропшипом (DS_AUTO).
    // Товары из реального каталога, привязанные вручную, не трогаем.
    try {
      $q=db()->prepare('SELECT product_id FROM ds_products WHERE id=?');
      $q->execute([$id]);
      $pid=$q->fetchColumn();
      if($pid){
        $auto=0;
        try { $aq=db()->prepare('SELECT auto_created FROM ds_products WHERE id=?'); $aq->execute([$id]); $auto=(int)$aq->fetchColumn(); } catch(Exception $e){}
        if($auto===1){ db()->prepare('DELETE FROM products WHERE id=?')->execute([$pid]); }
        else { db()->prepare("DELETE FROM products WHERE id=? AND supplier_id='DS_AUTO'")->execute([$pid]); }
      }
    } catch(Exception $e){}
    db()->prepare('DELETE FROM ds_products WHERE id=?')->execute([$id]);
    jout(['ok'=>true]);
  }

  case 'ds_group_delete': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $ids = is_array($d['ids']??null) ? $d['ids'] : [];
    $n=0;
    foreach($ids as $id){
      $id=trim((string)$id); if($id==='') continue;
      try {
        $q=db()->prepare('SELECT product_id,auto_created FROM ds_products WHERE id=?'); $q->execute([$id]); $row=$q->fetch();
        if($row){
          $pid=$row['product_id']; $auto=(int)($row['auto_created']??0);
          if($pid){
            if($auto===1) db()->prepare('DELETE FROM products WHERE id=?')->execute([$pid]);
            else db()->prepare("DELETE FROM products WHERE id=? AND supplier_id='DS_AUTO'")->execute([$pid]);
          }
        }
        db()->prepare('DELETE FROM ds_products WHERE id=?')->execute([$id]); $n++;
      } catch(Exception $e){}
    }
    jout(['ok'=>true,'deleted'=>$n]);
  }

  // --- DS Procurement Queue ---
  case 'ds_procurement_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    // ВАЖНО: у товара 1688 бывает под 70 вариантов (проверено: offer 709411502301 = 69 SKU).
    // Ссылка ведёт на страницу товара — без кода варианта бухгалтер не поймёт,
    // что именно выкупать. Подцепляем ob_sku по product_id и отдаём точный SKU.
    /* Название берём из карточки, а если её удалили — из самого заказа (25.09.2026):
       иначе в очереди вместо товара стоял прочерк. */
    $sql='SELECT pc.*,COALESCE(NULLIF(p.name,\'\'),(SELECT i2.name FROM order_items i2 WHERE i2.order_id=pc.order_id AND i2.product_id=pc.product_id LIMIT 1)) prod_name,p.img prod_img,m.name mgr_name,
           dp.source_platform,
           o.addr_name client_name,COALESCE((SELECT w9.name FROM warehouses w9 WHERE w9.id=o.warehouse_id AND LENGTH(w9.name)>0 LIMIT 1),o.addr_city) client_city,o.phone client_phone,
           sk.properties_cn sku_code, sk.name_ru sku_name, sk.price_cny sku_price_cny,
           sk.quantity sku_stock, sk.seller_warn sku_warn,
           ob.title_cn ob_title, ob.shop_name ob_shop, ob.location ob_city,
           ob.moq ob_moq, ob.detail_url ob_url
           FROM ds_procurement pc
           LEFT JOIN products p ON p.id=pc.product_id
           LEFT JOIN ds_staff m ON m.id=pc.manager_id
           LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
           LEFT JOIN orders o ON o.id=pc.order_id
           LEFT JOIN ob_sku sk ON sk.product_id=pc.product_id
           LEFT JOIN ob_item ob ON ob.num_iid=sk.num_iid
           ORDER BY pc.created_at DESC';
    $q=db()->query($sql);
    $rows=$q->fetchAll();
    // Готовый блок для бухгалтера: скопировал -> вставил в чат 1688 или в заявку.
    foreach ($rows as &$r) {
      if (!empty($r['sku_code'])) {
        $r['buy_note'] = implode("\n", array_filter([
          'ВЫКУП · заказ ' . ($r['order_id'] ?? '—'),
          '',
          'Ссылка : ' . ($r['ob_url'] ?: $r['source_url']),
          'Фабрика: ' . trim(($r['ob_shop'] ?? '') . ' ' . ($r['ob_city'] ?? '')),
          '',
          'Вариант: ' . ($r['sku_name'] ?? '—'),
          'Код SKU: ' . $r['sku_code'],
          '',
          'Цена   : ' . ($r['sku_price_cny'] ?? $r['source_price_cny']) . ' CNY',
          'Кол-во : ' . ($r['qty'] ?? 1),
          'MOQ    : ' . ($r['ob_moq'] ?? '—'),
          'Остаток: ' . ($r['sku_stock'] ?? '—'),
        ]));
      }
    }
    unset($r);

    /* Складские закупки (без дропшиппинга) в очереди площадок не считаем:
       у них нет площадки, и раньше они молча падали в очередь 1688. */
    $pend_1688=count(array_filter($rows,function($r){return $r['status']==='pending'&&!empty($r['ds_product_id'])&&($r['source_platform']??'1688')==='1688';}));
    $pend_pdd=count(array_filter($rows,function($r){return $r['status']==='pending'&&!empty($r['ds_product_id'])&&($r['source_platform']??'1688')==='pdd';}));
    $pending=$pend_1688+$pend_pdd;
    jout(['ok'=>true,'items'=>$rows,'pending'=>$pending,'pending_1688'=>$pend_1688,'pending_pdd'=>$pend_pdd]);
  }
