  // ==== Панель ВЫКУПА для бухгалтера («Товар на выкуп») ====
  case 'ds_buyout_list': {
    $s=authUser('itc'); require_staff($s,['accountant','chief_accountant']);
    buyout_ensure_cols();
    buyout_backfill_once();
    procurement_received_backfill_once();
    $sql="SELECT pc.id,pc.ds_product_id,pc.qty,pc.status,pc.source_url,pc.source_price_cny,pc.source_order_id,pc.buyout_price_cny,pc.ordered_at,pc.created_at,
            pc.pay_route,pc.ds_invoice_id,pc.cur_price_cny,pc.cur_price_exact,UNIX_TIMESTAMP(pc.cur_checked_at)*1000 cur_checked_ms,pc.mgr_status,pc.mgr_target_cny,
            i.invoice_no inv_no, i.status inv_status, i.total_cny inv_total,
            pc.product_id, COALESCE(NULLIF(p.name,''),(SELECT i2.name FROM order_items i2 WHERE i2.order_id=pc.order_id AND i2.product_id=pc.product_id LIMIT 1)) prod_name,p.img prod_img,p.price prod_price_rub,
            dp.source_platform, su.name supplier_name,
            o.num order_num,o.addr_name client_name,COALESCE((SELECT w9.name FROM warehouses w9 WHERE w9.id=o.warehouse_id AND LENGTH(w9.name)>0 LIMIT 1),o.addr_city) client_city,o.phone client_phone
          FROM ds_procurement pc
          LEFT JOIN products p ON p.id=pc.product_id
          LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
          LEFT JOIN suppliers su ON su.id=p.supplier_id
          LEFT JOIN ds_invoices i ON i.id=pc.ds_invoice_id
          LEFT JOIN orders o ON o.id=pc.order_id
          WHERE pc.status IN ('pending','ordered')
          ORDER BY (pc.status='pending') DESC, pc.created_at DESC";
    $rows=db()->query($sql)->fetchAll();
    $pending=count(array_filter($rows,function($r){return $r['status']==='pending';}));
    $strict=(int)itc_setting('ds_buyout_strict','1');
    jout(['ok'=>true,'items'=>$rows,'pending'=>$pending,'strict'=>$strict,
          'markup_pct'=>(float)itc_setting('buyout_markup_pct','5'),
          /* Должность сотрудника лежит в staff_role; в role всегда «itc».
             Из-за этого кнопка досрочного выкупа и смена порога не показывались
             никому, включая босса (25.09.2026). Пустая должность — старая
             сессия с полным доступом, как в require_staff. */
          'can_force'=>in_array(($s['staff_role']??''),['boss','chief_accountant',''],true),
          'can_threshold'=>in_array(($s['staff_role']??''),['boss','chief_accountant',''],true)]);
  }

  /* СКЛАДСКАЯ ЗАКУПКА ВЫКУПЛЕНА (25.09.2026). У товара не из дропшиппинга нет
     номера заказа 1688/PDD, поэтому обычная форма выкупа для него не годится.
     Кнопка просто переводит строку в «выкуплено» — дальше она сама попадает
     к кладовщику в список закупок, где печатается наш QR. */
  case 'ds_buyout_stock_done': {
