    $d=body(); $id=trim($d['id']??''); if(!$id) fail('id обязателен');
    $q=db()->prepare('SELECT ds_product_id,status FROM ds_procurement WHERE id=?'); $q->execute([$id]);
    $row=$q->fetch();
    if(!$row) fail('Заявка не найдена');
    if(($row['status']??'')!=='pending') fail('Заявка уже не ждёт выкупа');
    $isDs = !empty($row['ds_product_id']);
    // Дропшиппинг мимо инвойса Jinjia отмечать может только босс или главбух.
    if ($isDs) require_staff($s,['chief_accountant']);
    db()->prepare("UPDATE ds_procurement SET status='ordered',ordered_at=NOW() WHERE id=?")->execute([$id]);
    itc_log_add($s['phone']??'','ds_buyout_stock_done','ds_procurement',$id,
      $isDs?'отмечено выкупленным вручную, в обход инвойса':'складская закупка отмечена выкупленной');
    jout(['ok'=>true]);
