  case 'ds_buyout_stats': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant','supervisor','accountant']);
    buyout_stats_ensure();
    $agg=['profit_cny'=>0,'loss_cny'=>0,'profit_n'=>0,'loss_n'=>0,'even_n'=>0,
          'mgr_found'=>0,'mgr_notfound'=>0,'mgr_sent'=>0];
    try {
      $rows=db()->query("SELECT kind, SUM(diff_cny*qty) sc, COUNT(*) c FROM buyout_stats GROUP BY kind")->fetchAll();
      foreach($rows as $r){
        if($r['kind']==='profit'){ $agg['profit_cny']=abs((float)$r['sc']); $agg['profit_n']=(int)$r['c']; }
        elseif($r['kind']==='loss'){ $agg['loss_cny']=(float)$r['sc']; $agg['loss_n']=(int)$r['c']; }
        else { $agg['even_n']=(int)$r['c']; }
      }
    } catch (Exception $e) {}
    try {
      $mr=db()->query("SELECT mgr_status, COUNT(*) c FROM buyout_stats WHERE mgr_status IS NOT NULL AND mgr_status<>'' GROUP BY mgr_status")->fetchAll();
      foreach($mr as $r){ if($r['mgr_status']==='found')$agg['mgr_found']=(int)$r['c']; elseif($r['mgr_status']==='notfound')$agg['mgr_notfound']=(int)$r['c']; elseif($r['mgr_status']==='sent')$agg['mgr_sent']=(int)$r['c']; }
    } catch (Exception $e) {}
    try { $agg['mgr_sent']=(int)db()->query("SELECT COUNT(*) c FROM ds_procurement WHERE status='pending' AND mgr_status='sent'")->fetch()['c']; } catch (Exception $e) {}
    $recent=[];
    try { $recent=db()->query("SELECT prod_name,nom_cny,actual_cny,diff_cny,diff_pct,kind,qty,mgr_status,UNIX_TIMESTAMP(created_at)*1000 ts FROM buyout_stats ORDER BY id DESC LIMIT 60")->fetchAll(); } catch (Exception $e) {}
    jout(['ok'=>true,'agg'=>$agg,'recent'=>$recent]);
  }
  case 'ds_buyout_mgr_list': {
    $s=authUser('itc'); require_staff($s,['manager','supervisor','chief_accountant','boss']);
    buyout_ensure_cols();
    $sql="SELECT pc.id,pc.qty,pc.source_url,pc.source_price_cny,pc.cur_price_cny,pc.mgr_status,pc.mgr_target_cny,UNIX_TIMESTAMP(pc.cur_checked_at)*1000 cur_checked_ms,
            p.name prod_name,p.img prod_img,p.price prod_price_rub,dp.source_platform,
            o.num order_num,COALESCE((SELECT w9.name FROM warehouses w9 WHERE w9.id=o.warehouse_id AND LENGTH(w9.name)>0 LIMIT 1),o.addr_city) client_city
          FROM ds_procurement pc
          LEFT JOIN products p ON p.id=pc.product_id
          LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
          LEFT JOIN orders o ON o.id=pc.order_id
          WHERE pc.status='pending' AND pc.mgr_status IN ('sent','found','notfound')
          ORDER BY (pc.mgr_status='sent') DESC, pc.created_at DESC";
    $rows=db()->query($sql)->fetchAll();
    $sent=count(array_filter($rows,function($r){return $r['mgr_status']==='sent';}));
    jout(['ok'=>true,'items'=>$rows,'sent'=>$sent]);
  }
  case 'ds_buyout_mgr_action': {
    $s=authUser('itc'); require_staff($s,['manager','supervisor','chief_accountant','boss']);
    buyout_ensure_cols();
    $d=body(); $id=trim($d['id']??''); $act=trim($d['action']??''); $newp=(float)($d['new_price_cny']??0);
    if(!$id) fail('Нет id');
    if($act==='found'){ db()->prepare("UPDATE ds_procurement SET mgr_status='found', mgr_target_cny=? WHERE id=?")->execute([$newp>0?$newp:null,$id]); }
    elseif($act==='notfound'){ db()->prepare("UPDATE ds_procurement SET mgr_status='notfound' WHERE id=?")->execute([$id]); }
    elseif($act==='reset'){ db()->prepare("UPDATE ds_procurement SET mgr_status=NULL, mgr_target_cny=NULL WHERE id=?")->execute([$id]); }
    else fail('Неизвестное действие');
    jout(['ok'=>true]);
  }

  case 'ds_buyout_pay': {
    $s=authUser('itc'); require_staff($s,['accountant','chief_accountant']);
    $d=body();
    $id=trim($d['id']??'');
    $soid=trim($d['source_order_id']??'');
    $bprice=(float)($d['buyout_price_cny']??0);
    $force=!empty($d['force']);
    if(!$id||!$soid) fail('Укажите номер заказа PDD/1688');
    // Jinjia выкупает только после того, как ИТК оплатил инвойс.
    // Досрочно разрешить может только босс или главбух (кнопка «Выкупить всё равно»).
    $strict=(int)itc_setting('ds_buyout_strict','1');
    if($strict && !$force){
      $chk=db()->prepare("SELECT pc.pay_route, pc.ds_invoice_id, i.status inv_status
                            FROM ds_procurement pc LEFT JOIN ds_invoices i ON i.id=pc.ds_invoice_id
                           WHERE pc.id=?");
      $chk->execute([$id]); $row=$chk->fetch();
      if(!$row) fail('Заявка не найдена');
      if(($row['pay_route']??'alipay')==='alipay'){
        if(empty($row['ds_invoice_id'])) fail('Заявка ещё не попала в инвойс — Jinjia не получила деньги. Дождитесь сборки инвойса.');
        if(($row['inv_status']??'')!=='paid') fail('Инвойс ещё не оплачен ИТК — выкупать нельзя. Босс или главбух может разрешить досрочно.');
      }
    }
    if($force) require_staff($s,['boss','chief_accountant']);
    db()->prepare("UPDATE ds_procurement SET status='ordered',source_order_id=?,buyout_price_cny=?,ordered_at=NOW() WHERE id=?")
      ->execute([$soid,$bprice?:null,$id]);
    // статистика выкупа: выгода (купили дешевле) / убыток (дороже номинала)
    try {
      buyout_stats_ensure();
      $pcq=db()->prepare("SELECT pc.source_price_cny,pc.cur_price_cny,pc.qty,pc.product_id,pc.source_url,pc.mgr_status,p.name pn FROM ds_procurement pc LEFT JOIN products p ON p.id=pc.product_id WHERE pc.id=?");
      $pcq->execute([$id]); $pr=$pcq->fetch();
      if($pr){
        $nom=(float)$pr['source_price_cny']; $act=$bprice?:(float)$pr['cur_price_cny'];
        $num=''; if(preg_match('/offer\/(\d+)/',(string)$pr['source_url'],$mm)) $num=$mm[1];
        $diff=$act-$nom; $pct=$nom>0?(int)round($diff/$nom*100):0;
        $kind=$diff<-0.01?'profit':($diff>0.01?'loss':'even');
        db()->prepare("INSERT INTO buyout_stats (procurement_id,product_id,num_iid,prod_name,nom_cny,actual_cny,cur_cny,diff_cny,diff_pct,kind,qty,mgr_status,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,NOW())")
          ->execute([$id,$pr['product_id'],$num,$pr['pn'],$nom?:null,$act?:null,$pr['cur_price_cny'],$diff,$pct,$kind,$pr['qty'],$pr['mgr_status']]);
      }
    } catch (Exception $e) {}
    itc_log_add($s['phone']??'','ds_buyout_pay','ds_procurement',$id,($force?'ДОСРОЧНО (в обход инвойса) · ':'').'выкуп ¥'.$bprice.' · заказ '.$soid);
    jout(['ok'=>true]);
  }

  // --- DS: способ оплаты заявки (Alipay Jinjia или прямой инвойс ИТК) ---
  case 'ds_route_set': {
    $s=authUser('itc'); require_staff($s,['boss','accountant','chief_accountant']);
    $d=body();
    $id=trim($d['id']??'');
    $r=trim($d['route']??'alipay');
    if(!$id) fail('id обязателен');
    if(!in_array($r,['alipay','itk_direct'],true)) fail('Неизвестный способ оплаты');
    $chk=db()->prepare("SELECT pc.ds_invoice_id, i.status inv_status FROM ds_procurement pc
                          LEFT JOIN ds_invoices i ON i.id=pc.ds_invoice_id WHERE pc.id=?");
    $chk->execute([$id]); $row=$chk->fetch();
    if(!$row) fail('Заявка не найдена');
    if(($row['inv_status']??'')==='paid') fail('Инвойс уже оплачен — способ оплаты менять нельзя');
    // из несобранного инвойса вынимаем: пересоберётся при следующей сборке
    db()->prepare("UPDATE ds_procurement SET pay_route=?, ds_invoice_id=NULL WHERE id=?")->execute([$r,$id]);
    itc_log_add($s['phone']??'','ds_route_set','ds_procurement',$id,'способ оплаты: '.($r==='alipay'?'Alipay Jinjia':'прямой инвойс ИТК'));
    jout(['ok'=>true]);
  }
  // ds_create_procurement() вынесена на верхний уровень (см. выше switch)

  // --- DS: Обновление трек-номера менеджером ---
  case 'ds_tracking_update': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $id=trim($d['id']??'');
    $trk=trim($d['logistics_tracking']??'');
    $src=trim($d['tracking_source']??'manual');
    if(!$id) fail('id обязателен');
    db()->prepare("UPDATE ds_procurement SET logistics_tracking=?,tracking_source=?,tracking_at=NOW() WHERE id=?")
      ->execute([$trk?:null,$src,$id]);
    jout(['ok'=>true]);
  }

  // --- DS: Поиск заказа по трек-номеру (кладовщик) ---
  case 'ds_find_by_tracking': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $trk=trim($d['tracking']??'');
    if(!$trk) fail('Введите трек-номер');
    $q=db()->prepare("SELECT pc.*,p.name prod_name,p.img prod_img,dp.source_platform,
        m.name mgr_name, o.num order_num,o.addr_name client_name,COALESCE((SELECT w9.name FROM warehouses w9 WHERE w9.id=o.warehouse_id AND LENGTH(w9.name)>0 LIMIT 1),o.addr_city) client_city,o.phone client_phone
        FROM ds_procurement pc
        LEFT JOIN products p ON p.id=pc.product_id
        LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
        LEFT JOIN ds_staff m ON m.id=pc.manager_id
        LEFT JOIN orders o ON o.id=pc.order_id
        WHERE pc.logistics_tracking=?");
    $q->execute([$trk]);
    $row=$q->fetch();
    if(!$row) fail('Заказ с трек-номером '.$trk.' не найден');
    jout(['ok'=>true,'item'=>$row]);
