  // --- DS: Список ожидаемых поступлений (кладовщик) ---
  case 'ds_expected_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $q=db()->query("SELECT pc.*,p.name prod_name,p.img prod_img,dp.source_platform,
        m.name mgr_name, o.num order_num,o.addr_name client_name,COALESCE((SELECT w9.name FROM warehouses w9 WHERE w9.id=o.warehouse_id AND LENGTH(w9.name)>0 LIMIT 1),o.addr_city) client_city
        FROM ds_procurement pc
        LEFT JOIN products p ON p.id=pc.product_id
        LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
        LEFT JOIN ds_staff m ON m.id=pc.manager_id
        LEFT JOIN orders o ON o.id=pc.order_id
        WHERE pc.status='ordered'
        ORDER BY pc.ordered_at DESC");
