  // --- DS: Принятие заказа кладовщиком (через трек или из списка) ---
  case 'ds_keeper_receive': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    if(!$id) fail('id обязателен');
    db()->prepare("UPDATE ds_procurement SET status='received',received_at=NOW() WHERE id=?")
      ->execute([$id]);
    jout(['ok'=>true]);
