  // ============================================================
  //  TELEGRAM BOT WEBHOOK
  //  URL: /api/api.php?action=ds_telegram_webhook&bot_token=XXX
  //  Настройка: https://api.telegram.org/bot{TOKEN}/setWebhook?url=...
  // ============================================================
  case 'ds_telegram_webhook': {
    // Проверяем токен бота
    $bot_token=trim($_GET['bot_token']??'');
    $allowed_token=defined('DS_TELEGRAM_TOKEN')?DS_TELEGRAM_TOKEN:'';
    // Если токен задан в config — проверяем
    if($allowed_token&&$bot_token!==$allowed_token) { http_response_code(403); exit; }

    $update=json_decode(file_get_contents('php://input'),true);
    if(!$update) { echo 'ok'; exit; }

    $chat_id=$update['message']['chat']['id']??null;
    $text=$update['message']['text']??'';
    $from_id=$update['message']['from']['id']??null;

    if(!$chat_id||!$text) { echo 'ok'; exit; }

    // Ищем трек-номера в тексте (паттерны: SF顺丰, ZTO中通, YTO圆通, YTOF, PDD номера и т.д.)
    $tracking=null;
    // Универсальный паттерн: 10-20 символов, буквы+цифры
    if(preg_match('/\b([A-Z]{2,4}\d{8,18}|\d{12,15}|[A-Z]{1,4}\d{9,15}[A-Z]{0,2})\b/',$text,$m)){
      $tracking=$m[1];
    }
    // Паттерн PDD (拼多多 номера заказов)
    if(!$tracking&&preg_match('/运单号[：:]\s*([A-Z0-9]{10,20})/',$text,$m2)) $tracking=$m2[1];
    if(!$tracking&&preg_match('/快递单号[：:]\s*([A-Z0-9]{10,20})/',$text,$m3)) $tracking=$m3[1];

    // Ищем привязку менеджера по chat_id
    $bt=null;
    try { $bq=db()->prepare('SELECT bt.*,m.name mgr_name FROM ds_bot_tokens bt LEFT JOIN ds_staff m ON m.id=bt.manager_id WHERE bt.chat_id=? AND bt.platform=? AND bt.active=1');
          $bq->execute([(string)$chat_id,'telegram']); $bt=$bq->fetch(); } catch(Exception $e){}

    // Команда /start или /link — привязка менеджера
    if(preg_match('/^\/start\s+([a-z0-9_]+)$/i',$text,$mc)){
      $link_code=$mc[1];
      try {
        $mgq=db()->prepare('SELECT id,name FROM ds_staff WHERE code=? AND active=1');
        $mgq->execute([$link_code]); $mgr=$mgq->fetch();
        if($mgr){
          $tid=gen_ds_id();
          db()->prepare('INSERT INTO ds_bot_tokens(id,manager_id,platform,chat_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE chat_id=?,active=1')
            ->execute([$tid,$mgr['id'],'telegram',(string)$chat_id,(string)$chat_id]);
          $reply="✅ Привязан как ".$mgr['name'].".\n\nТеперь пересылайте уведомления об отправке из 1688/PDD — трек-номер подхватится автоматически.";
        } else { $reply="❌ Код не найден. Попросите DS-босса выдать код в системе ИТК."; }
      } catch(Exception $e){ $reply="Ошибка: ".$e->getMessage(); }
      // Отправляем ответ в Telegram
      if($allowed_token) @file_get_contents("https://api.telegram.org/bot{$allowed_token}/sendMessage?chat_id={$chat_id}&text=".urlencode($reply));
      echo 'ok'; exit;
    }

    // Найден трек-номер — ищем незакрытый заказ менеджера
    if($tracking&&$bt){
      try {
        // Ищем активный заказ этого менеджера без трек-номера
        $pq=db()->prepare("SELECT id,product_id FROM ds_procurement WHERE manager_id=? AND status='ordered' AND (logistics_tracking IS NULL OR logistics_tracking='') ORDER BY ordered_at ASC LIMIT 1");
        $pq->execute([$bt['manager_id']]); $pending=$pq->fetch();
        if($pending){
          db()->prepare("UPDATE ds_procurement SET logistics_tracking=?,tracking_source='telegram',tracking_at=NOW() WHERE id=?")
            ->execute([$tracking,$pending['id']]);
          $reply="✅ Трек-номер {$tracking} привязан к заказу автоматически!";
        } else {
          $reply="📦 Трек-номер {$tracking} найден, но нет активных ожидающих заказов без трека. Проверьте очередь в ИТК.";
        }
      } catch(Exception $e){ $reply="⚠ Трек найден ({$tracking}), но ошибка записи: ".$e->getMessage(); }
      if($allowed_token) @file_get_contents("https://api.telegram.org/bot{$allowed_token}/sendMessage?chat_id={$chat_id}&text=".urlencode($reply));
    } elseif(!$bt&&$tracking) {
      // Менеджер не привязан
      $reply="⚠ Вы не привязаны к системе ИТК.\nОтправьте /start [ваш_код] для привязки.";
      if($allowed_token) @file_get_contents("https://api.telegram.org/bot{$allowed_token}/sendMessage?chat_id={$chat_id}&text=".urlencode($reply));
    }
    echo 'ok'; exit;
  }

  // ============================================================
  //  WECHAT WEBHOOK (запасной канал)
  //  Приоритет ниже Telegram — подключается если Telegram недоступен
  // ============================================================
  case 'ds_wechat_webhook': {
    $echostr=$_GET['echostr']??'';
    if($echostr){ echo $echostr; exit; } // верификация WeChat сервера

    $xml=simplexml_load_string(file_get_contents('php://input'),'SimpleXMLElement',LIBXML_NOCDATA);
    if(!$xml){ echo 'ok'; exit; }

    $from=(string)($xml->FromUserName??'');
    $to=(string)($xml->ToUserName??'');
    $content=(string)($xml->Content??'');
    $msgtype=(string)($xml->MsgType??'');

    if($msgtype!=='text'||!$content){ echo 'ok'; exit; }

    // Паттерны трек-номеров (аналогично Telegram)
    $tracking=null;
    if(preg_match('/\b([A-Z]{2,4}\d{8,18}|\d{12,15})\b/',$content,$m)) $tracking=$m[1];
    if(!$tracking&&preg_match('/运单号[：:]\s*([A-Z0-9]{10,20})/',$content,$m2)) $tracking=$m2[1];

    // Ищем менеджера по WeChat openid
    $bt=null;
    try { $bq=db()->prepare('SELECT bt.*,m.name mgr_name FROM ds_bot_tokens bt LEFT JOIN ds_staff m ON m.id=bt.manager_id WHERE bt.chat_id=? AND bt.platform=? AND bt.active=1');
          $bq->execute([$from,'wechat']); $bt=$bq->fetch(); } catch(Exception $e){}

    $reply_text='';
    if($tracking&&$bt){
      try {
        $pq=db()->prepare("SELECT id FROM ds_procurement WHERE manager_id=? AND status='ordered' AND (logistics_tracking IS NULL OR logistics_tracking='') ORDER BY ordered_at ASC LIMIT 1");
        $pq->execute([$bt['manager_id']]); $pending=$pq->fetch();
        if($pending){
          db()->prepare("UPDATE ds_procurement SET logistics_tracking=?,tracking_source='wechat',tracking_at=NOW() WHERE id=?")->execute([$tracking,$pending['id']]);
          $reply_text="✅ Трек {$tracking} записан автоматически!";
        } else { $reply_text="📦 Трек {$tracking} найден, но нет заказов без трека."; }
      } catch(Exception $e){ $reply_text="Ошибка: ".$e->getMessage(); }
    } elseif($content==='привязать'||$content==='link'){
      $reply_text="Введите /link [ваш_код] для привязки к системе ИТК.";
    } elseif(preg_match('/^\/link\s+([a-z0-9_]+)$/i',$content,$mc)){
      try {
        $mgq=db()->prepare('SELECT id,name FROM ds_staff WHERE code=? AND active=1');
        $mgq->execute([$mc[1]]); $mgr=$mgq->fetch();
        if($mgr){
          $tid=gen_ds_id();
          db()->prepare('INSERT INTO ds_bot_tokens(id,manager_id,platform,chat_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE chat_id=?,active=1')
            ->execute([$tid,$mgr['id'],'wechat',$from,$from]);
          $reply_text="✅ Привязан как ".$mgr['name'].". Пересылайте уведомления об отправке!";
        } else { $reply_text="❌ Код не найден."; }
      } catch(Exception $e){ $reply_text="Ошибка: ".$e->getMessage(); }
    }

    if($reply_text){
      $time=time();
      echo "<xml><ToUserName><![CDATA[{$from}]]></ToUserName><FromUserName><![CDATA[{$to}]]></FromUserName><CreateTime>{$time}</CreateTime><MsgType><![CDATA[text]]></MsgType><Content><![CDATA[{$reply_text}]]></Content></xml>";
    } else { echo 'ok'; }
    exit;
  }

  // --- DS: Получить ссылку для привязки бота ---
  case 'ds_bot_link': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $mid=trim($d['manager_id']??'');
    if(!$mid) fail('manager_id обязателен');
    $mq=db()->prepare('SELECT code,name FROM ds_staff WHERE id=? AND active=1');
    $mq->execute([$mid]); $mgr=$mq->fetch();
    if(!$mgr) fail('Менеджер не найден');
    jout(['ok'=>true,'code'=>$mgr['code'],'name'=>$mgr['name']]);
  }

  case 'ds_pending_count': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    try {
      $q=db()->query("SELECT dp.source_platform,COUNT(*) cnt FROM ds_procurement pc LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id WHERE pc.status='pending' GROUP BY dp.source_platform");
      $p1688=0;$ppdd=0;
      foreach($q->fetchAll() as $r){if(($r['source_platform']??'1688')==='pdd')$ppdd=(int)$r['cnt'];else $p1688=(int)$r['cnt'];}
      jout(['ok'=>true,'pending'=>$p1688+$ppdd,'pending_1688'=>$p1688,'pending_pdd'=>$ppdd]);
    } catch(Exception $e){ jout(['ok'=>true,'pending'=>0,'pending_1688'=>0,'pending_pdd'=>0]); }
  }

  // ============================================================
  //  DS-ИНВОЙСЫ: Jinjia → ИТК (каждые 3 дня)
  // ============================================================

  case 'ds_invoice_build': {
    // Инвойс Jinjia -> ИТК. Собираем заявки ДО выкупа, отдельным инвойсом на каждую площадку.
    // Механика: ИТК оплачивает инвойс -> только после этого Jinjia выкупает товар.
    $s=authUser('itc'); require_staff($s,['accountant','chief_accountant','manager']);
    $d=body();
    $days=(int)($d['days']??3); if($days<1)$days=1;
    $by=mb_substr(trim($d['by']??''),0,120);
    $only=trim($d['platform']??'');                        // можно собрать одну площадку
    $st=get_settings(); $fee=(float)($st['jinjia_fee']??3); // прибыль Jinjia, %
    $q=db()->prepare("SELECT pc.id, pc.qty,
             COALESCE(NULLIF(pc.source_price_cny,0), dp.source_price_cny, 0) unit_cny,
             COALESCE(NULLIF(dp.source_platform,''),'1688') platform
        FROM ds_procurement pc
        LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
       WHERE pc.ds_invoice_id IS NULL
         AND pc.status='pending'
         AND pc.pay_route='alipay'
         AND pc.created_at >= (NOW() - INTERVAL ? DAY)");
    $q->execute([$days]);
    $items=$q->fetchAll();
    if(!$items) fail('Нет новых заявок за период — инвойс не нужен');
    $groups=[];
    foreach($items as $it){ $groups[$it['platform']][]=$it; }
    $made=[];
    foreach($groups as $plat=>$rows){
      if($only!=='' && $only!==$plat) continue;
      $goods=0; foreach($rows as $r){ $goods += (float)$r['unit_cny'] * (int)$r['qty']; }
      $goods=round($goods,2);
      $total=round($goods*(1+$fee/100),2);
      $iid='dsi'.substr(md5(uniqid('',true)),0,10);
      $ino='DS-'.strtoupper($plat).'-'.date('Ymd').'-'.strtoupper(substr($iid,-4));
      db()->prepare("INSERT INTO ds_invoices(id,invoice_no,dt_from,dt_to,platform,goods_cny,fee_pct,total_cny,status,created_by)
        VALUES(?,?,NOW()-INTERVAL ? DAY,NOW(),?,?,?,?,'draft',?)")
        ->execute([$iid,$ino,$days,$plat,$goods,$fee,$total,$by]);
      foreach($rows as $r){ db()->prepare("UPDATE ds_procurement SET ds_invoice_id=? WHERE id=?")->execute([$iid,$r['id']]); }
      itc_log_add($by,'ds_invoice_build','ds_invoice',$ino,$plat.': закупка ¥'.$goods.' + '.$fee.'% = ¥'.$total.' · '.count($rows).' поз.');
      $made[]=['id'=>$iid,'no'=>$ino,'platform'=>$plat,'goods_cny'=>$goods,'fee_pct'=>$fee,'total_cny'=>$total,'items'=>count($rows)];
    }
    if(!$made) fail('Нет заявок по выбранной площадке');
    jout(['ok'=>true,'invoices'=>$made]);
  }

  case 'ds_invoice_list': {
    $s=authUser('itc'); require_staff($s,['accountant','chief_accountant','manager']);
