      FROM ds_procurement pc
      LEFT JOIN products p ON p.id=pc.product_id
      LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
      WHERE pc.ds_invoice_id=? ORDER BY dp.source_platform,pc.created_at");
    $pq->execute([$iid]); $items=$pq->fetchAll();
    $seals=[]; foreach(db()->query("SELECT company,seal_img,sign_img FROM company_seals")->fetchAll() as $r) $seals[$r['company']]=$r;
    $seller=itc_buyer_reqs('jinjia');
