      $unit=(float)($it['unit_cny']??0);
      $total_line=round($unit*$it['qty'],2);
      $plat=strtoupper($it['source_platform']??'1688');
      $rows_html.='<tr><td>'.$n.'</td><td>'.htmlspecialchars($it['prod_name']??'—').'</td><td>'.$plat.'</td>'.
        '<td style="text-align:center">'.(int)$it['qty'].'</td>'.
