      '.sign-row{display:flex;gap:30px;margin-top:30px}'.
      '.sign-box{flex:1;text-align:center;border-top:1px solid #999;padding-top:8px;font-size:12px;color:#555}'.
      '.total-row{font-weight:700;background:#f7f9ff}</style></head><body>'.
      '<h2>ИНВОЙС / INVOICE №'.htmlspecialchars($inv['invoice_no']).'</h2>'.
      '<div class="sub">Дата / Date: '.date('d.m.Y',strtotime($inv['created_at'])).
        ' · Период / Period: '.$dt_from.' — '.$dt_to.'</div>'.
