  case 'ds_invoice_pay': {
    // Подтверждение оплаты SWIFT бухгалтером
    $s=authUser('itc'); require_staff($s,['accountant','chief_accountant']);
    $d=body();
    $iid=trim($d['invoice_id']??'');
    $swift=trim($d['swift_ref']??'');
    $paid_cny=(float)($d['paid_cny']??0);
    $notes=trim($d['notes']??'');
    if(!$iid) fail('invoice_id обязателен');
    if(!$swift) fail('Укажите SWIFT-референс');
    db()->prepare("UPDATE ds_invoices SET status='paid',paid_at=NOW(),paid_by=?,swift_ref=?,paid_cny=?,notes=? WHERE id=?")
      ->execute([$s['phone']??'',$swift,$paid_cny?:null,$notes?:null,$iid]);
    itc_log_add($s['phone']??'','ds_invoice_paid','ds_invoice',$iid,'SWIFT '.$swift.' · ¥'.$paid_cny);
    jout(['ok'=>true]);
