  // CRON: автоформирование DS-инвойса каждые 3 дня
  case 'ds_invoice_cron': {
    $cron_key=trim($_GET['cron_key']??''); $expected=defined('DS_CRON_KEY')?DS_CRON_KEY:'';
    if($expected&&$cron_key!==$expected){ http_response_code(403); exit; }
    $days=(int)(get_settings()['batch_period_days']??3); if($days<1)$days=3;
    $fee=(float)(get_settings()['jinjia_fee']??3);
    $last=db()->query("SELECT COUNT(*) FROM ds_invoices WHERE created_at>=(NOW()-INTERVAL {$days} DAY)")->fetchColumn();
    if($last>0){ jout(['ok'=>true,'skipped'=>true,'reason'=>'Инвойс за период уже существует']); break; }
    $q=db()->prepare("SELECT pc.id, pc.qty,
             COALESCE(NULLIF(pc.source_price_cny,0), dp.source_price_cny, 0) unit_cny,
             COALESCE(NULLIF(dp.source_platform,''),'1688') platform
        FROM ds_procurement pc
        LEFT JOIN ds_products dp ON dp.id=pc.ds_product_id
       WHERE pc.ds_invoice_id IS NULL
         AND pc.status='pending'
         AND pc.pay_route='alipay'
         AND pc.created_at >= (NOW() - INTERVAL ? DAY)");
    $q->execute([$days]); $items=$q->fetchAll();
    if(!$items){ jout(['ok'=>true,'skipped'=>true,'reason'=>'Нет заявок за период']); break; }
    $groups=[]; foreach($items as $it){ $groups[$it['platform']][]=$it; }
    $made=[];
    foreach($groups as $plat=>$rows){
      $goods=0; foreach($rows as $r){ $goods += (float)$r['unit_cny'] * (int)$r['qty']; }
      $goods=round($goods,2); $total=round($goods*(1+$fee/100),2);
      $iid='dsi'.substr(md5(uniqid('',true)),0,10);
      $ino='DS-'.strtoupper($plat).'-'.date('Ymd').'-'.strtoupper(substr($iid,-4));
      db()->prepare("INSERT INTO ds_invoices(id,invoice_no,dt_from,dt_to,platform,goods_cny,fee_pct,total_cny,status,created_by)
        VALUES(?,?,NOW()-INTERVAL ? DAY,NOW(),?,?,?,?,'draft','cron')")
        ->execute([$iid,$ino,$days,$plat,$goods,$fee,$total]);
      foreach($rows as $r){ db()->prepare("UPDATE ds_procurement SET ds_invoice_id=? WHERE id=?")->execute([$iid,$r['id']]); }
      $made[]=['no'=>$ino,'platform'=>$plat,'total_cny'=>$total,'items'=>count($rows)];
    }
    jout(['ok'=>true,'created'=>true,'invoices'=>$made]);
  }

  // --- DS: Пауза / возобновление ---
  case 'ds_product_pause': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??''); $reason=trim($d['reason']??'');
    if(!$id) fail('id обязателен');
    db()->prepare("UPDATE ds_products SET ds_status='paused_manual',pause_reason=?,paused_at=NOW(),paused_by=? WHERE id=?")->execute([$reason?:null,$s['phone']??'',$id]);
    $pq=db()->prepare('SELECT product_id FROM ds_products WHERE id=?'); $pq->execute([$id]); $row=$pq->fetch();
    if($row) try{ db()->prepare("UPDATE products SET blocked=1 WHERE id=?")->execute([$row['product_id']]); }catch(Exception $e){}
    try{ $lid='ds'.substr(md5(uniqid('',true)),0,12); db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$id,'manual_paused',$reason?:'Пауза менеджером']); }catch(Exception $e){}
    jout(['ok'=>true]);
  }
  case 'ds_product_resume': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    if(!$id) fail('id обязателен');
    db()->prepare("UPDATE ds_products SET ds_status='active',pause_reason=NULL,paused_at=NULL,paused_by=NULL,check_fail_count=0,source_available=1 WHERE id=?")->execute([$id]);
    $pq=db()->prepare('SELECT product_id FROM ds_products WHERE id=?'); $pq->execute([$id]); $row=$pq->fetch();
    if($row) try{ db()->prepare("UPDATE products SET blocked=0 WHERE id=?")->execute([$row['product_id']]); }catch(Exception $e){}
    try{ $lid='ds'.substr(md5(uniqid('',true)),0,12); db()->prepare('INSERT INTO ds_monitor_log(id,ds_product_id,event,details) VALUES(?,?,?,?)')->execute([$lid,$id,'resumed','Возобновлено']); }catch(Exception $e){}
    jout(['ok'=>true]);
  }
  case 'ds_check_one': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=trim($d['id']??'');
    if(!$id) fail('id обязателен');
    $pq=db()->prepare('SELECT id,source_url,source_platform,product_id,check_fail_count FROM ds_products WHERE id=?');
    $pq->execute([$id]); $dp=$pq->fetch(); if(!$dp) fail('Товар не найден');
    $result=ds_check_url($dp['source_url'],$dp['source_platform']);
    ds_apply_check_result($dp,$result);
    jout(['ok'=>true,'available'=>$result['available'],'status'=>$result['status']]);
  }
  case 'ds_monitor_cron': {
    $cron_key=trim($_GET['cron_key']??''); $expected=defined('DS_CRON_KEY')?DS_CRON_KEY:'';
    if($expected&&$cron_key!==$expected){ http_response_code(403); echo 'forbidden'; exit; }
    /* Берём не «кто дольше всех не проверялся», а «кто сильнее всех просрочен
       относительно СВОЕГО срока». Ходовой товар с проверкой недельной давности
       важнее мёртвого, который не трогали полгода. */
    try { db()->query("ALTER TABLE ds_products ADD COLUMN prio_tier TINYINT NOT NULL DEFAULT 3"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE ds_products ADD COLUMN tier_at DATETIME NULL"); } catch (Exception $e) {}

    // раз в сутки пересчитываем важность — на каждом прогоне это лишняя нагрузка
    try {
      $stale = db()->query("SELECT COUNT(*) FROM ds_products WHERE tier_at IS NULL OR tier_at < DATE_SUB(NOW(), INTERVAL 1 DAY)")->fetchColumn();
      if ((int)$stale > 0) ds_recalc_tiers();
    } catch (Exception $e) {}

    ds_archive_cols();   // поля архива должны существовать ДО запроса ниже
    /* СКОЛЬКО БРАТЬ ЗА ЗАПУСК — СЧИТАЕМ САМИ (25.08.2026, просьба Алексея).
       Раньше число стояло в строке запуска и молча устаревало при росте
       каталога. Теперь темп = «обойти всё за 90 дней» плюс догон очереди,
       если она накопилась (например, после массового завоза, когда партия
       товаров разом переваливает трёхмесячный рубеж).
       &n=... по-прежнему работает и перебивает расчёт — для ручных проб. */
    $CIRCLE_DAYS = 90;      // полный круг по каталогу
    $HARD_CAP    = 3000;    // потолок на один запуск, чтобы задание не висело
    $TIME_CAP    = 240;     // и не дольше 4 минут
    $started     = microtime(true);
    $manualN = isset($_GET['n']) ? max(1, min(2000, (int)$_GET['n'])) : 0;
    $limit = $manualN;
    if (!$limit) {
      $totalActive = 0; $queue = 0;
      try { $totalActive = (int)db()->query("SELECT COUNT(*) FROM ds_products WHERE ds_status<>'paused_manual' AND gone_at IS NULL")->fetchColumn(); } catch (Exception $e) {}
      try { $queue = (int)db()->query("SELECT COUNT(*) FROM ds_products
                                        WHERE ds_status<>'paused_manual' AND gone_at IS NULL
                                          AND COALESCE(last_price_check, created_at) < DATE_SUB(NOW(), INTERVAL ".$CIRCLE_DAYS." DAY)")->fetchColumn(); } catch (Exception $e) {}
      $base = (int)ceil($totalActive / $CIRCLE_DAYS);         // ровный темп
      $catchUp = (int)ceil(max(0, $queue - $base) / 7);       // хвост разгребаем за неделю
      $limit = max(10, min($HARD_CAP, $base + $catchUp));
      $plan = ['товаров_в_работе'=>$totalActive, 'очередь'=>$queue,
               'ровный_темп'=>$base, 'догон'=>$catchUp, 'взято_за_запуск'=>$limit];
      if ($base > $HARD_CAP) $plan['ВНИМАНИЕ'] = 'Каталог вырос: за один запуск в сутки полный круг за '.$CIRCLE_DAYS.' дней уже не укладывается. Запускайте задание дважды в сутки.';
    } else {
      $plan = ['задано_вручную'=>$limit];
    }
    /* КРУГ ПО ВСЕМУ КАТАЛОГУ ЗА 3 МЕСЯЦА (25.08.2026, решение Алексея).
       Берём самые давно не проверенные карточки — очередь выравнивается сама,
       без расписаний. Светофорные (ob_track) СЮДА НЕ ПОПАДАЮТ: у них своё,
       более частое расписание, и дёргать товар дважды за день незачем.
       Архив (пропавшие) идёт отдельным проходом ниже. */
    $trackIids = [];
    try { foreach (db()->query("SELECT num_iid FROM ob_track")->fetchAll() as $t) $trackIids[(string)$t['num_iid']] = 1; } catch (Exception $e) {}
    $rows = [];
    try {
      $rows = db()->query("SELECT id, source_url, source_platform, product_id, check_fail_count, prio_tier,
                                  COALESCE(last_price_check, created_at) AS base_at
                             FROM ds_products
                            WHERE ds_status <> 'paused_manual'
                              AND gone_at IS NULL
                              AND COALESCE(last_price_check, created_at) < DATE_SUB(NOW(), INTERVAL 90 DAY)
                            ORDER BY COALESCE(last_price_check, created_at) ASC, source_url ASC
                            LIMIT ".min(4000, $limit * 2 + 50))->fetchAll();
    } catch (Exception $e) {
      // старая схема без новых полей — работаем как раньше
      try { $rows = db()->query("SELECT id,source_url,source_platform,product_id,check_fail_count FROM ds_products WHERE ds_status<>'paused_manual' ORDER BY last_check_at ASC LIMIT $limit")->fetchAll(); }
      catch (Exception $e2) { $rows = []; }
    }
    $checked=0; $ap=0; $priced=0; $skipTrack=0; $noVar=0; $byTier=[1=>0,2=>0,3=>0];
    $seenOffers = [];
    foreach($rows as $dp){
      if ($checked >= $limit) break;
      // потолок по времени: остаток уйдёт на следующие сутки, ничего не теряется
      if ((microtime(true) - $started) > $TIME_CAP) { $stoppedByTime = true; break; }
      // светофорный — пропускаем, его проверит своя машинка
      if (preg_match('/offer\/(\d+)/', (string)$dp['source_url'], $mm) && isset($trackIids[$mm[1]])) { $skipTrack++; continue; }
      $newOffer = !empty($mm[1]) && !isset($seenOffers[$mm[1]]);
      if (!empty($mm[1])) $seenOffers[$mm[1]] = 1;
      // 1688 спрашиваем через API — оттуда и наличие, и цена нужного варианта
      $r = ds_check_1688_api($dp['source_url'], $dp['product_id']);
      if ($r === null) $r = ds_check_url($dp['source_url'],$dp['source_platform']);
      if (!empty($r['available']) && isset($r['price_cny'])) $priced++;
      if (!empty($r['available']) && isset($r['variant_exact']) && !$r['variant_exact']) $noVar++;
      ds_apply_check_result($dp,$r);
      try { db()->prepare("UPDATE ds_products SET last_price_check=NOW() WHERE id=?")->execute([$dp['id']]); } catch (Exception $e) {}
      $checked++; $t=(int)($dp['prio_tier'] ?? 3); if(isset($byTier[$t])) $byTier[$t]++;
      if(!$r['available'])$ap++;
      // ждём только когда реально ходили в сеть; остальные варианты той же
      // карточки берутся из памяти и задержки не требуют
      if ($newOffer) usleep(300000);
    }
    // второй проход — архив: переспрос пропавших, возврат живых, уборка мёртвых
    $arch = ds_archive_pass(30, 100);
    // сколько ещё ждёт очереди — по этому числу видно, укладываемся ли в 3 месяца
    $left = 0;
    try { $left = (int)db()->query("SELECT COUNT(*) FROM ds_products
                                     WHERE ds_status <> 'paused_manual' AND gone_at IS NULL
                                       AND COALESCE(last_price_check, created_at) < DATE_SUB(NOW(), INTERVAL 90 DAY)")->fetchColumn(); }
    catch (Exception $e) {}
    jout(['ok'=>true,'план'=>$plan,'проверено'=>$checked,'карточек_1688_спрошено'=>count($seenOffers),
          'остановлено_по_времени'=>!empty($stoppedByTime),
          'цена_обновлена'=>$priced,'вариант_не_опознан'=>$noVar,
          'пропущено_светофорных'=>$skipTrack,'пропало'=>$ap,'архив'=>$arch,'ждёт_очереди'=>$left,
          'checked'=>$checked,'auto_paused'=>$ap,'by_tier'=>$byTier,'left'=>$left]);
  }
  case 'ds_monitor_log': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $q=db()->query("SELECT l.*,p.name prod_name,dp.source_platform FROM ds_monitor_log l LEFT JOIN ds_products dp ON dp.id=l.ds_product_id LEFT JOIN products p ON p.id=dp.product_id ORDER BY l.created_at DESC LIMIT 80");
    try{ $ap=(int)db()->query("SELECT COUNT(*) FROM ds_products WHERE ds_status='paused_auto'")->fetchColumn(); }catch(Exception $e){ $ap=0; }
    jout(['ok'=>true,'log'=>$q->fetchAll(),'auto_paused_count'=>$ap]);
  }

  // ---- Парсинг PDD-ссылки (тест) ----
  case 'ds_parse_pdd_url': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $url=trim($d['url']??'');
    if(!$url) fail('URL не указан');
    $url=pdd_normalize_url($url);
    [$html,$code]=pdd_fetch($url);
    if(!$html||$code===0) jout(['ok'=>false,'error'=>'Не удалось загрузить страницу PDD (нет соединения)']);
    elseif($code>=400) jout(['ok'=>false,'error'=>"PDD вернул HTTP $code"]);
    else {
      $p=pdd_parse_html($html);
      if(!$p['name']) { jout(['ok'=>false,'error'=>'Данные не найдены. Попробуйте открыть ссылку вручную и убедитесь, что товар активен.']); break; }
      // Переводим/обогащаем название и описание (DeepSeek → откат на MyMemory)
      $enr = pdd_smart_translate($p['name'], $p['description'] ?? '');
      $name_ru = $enr['name'];
      $desc_ru = $enr['description'];

      // Автоопределение категории и дефолтного веса/объёма
      $guess = pdd_guess_category($p['name'], $name_ru, $p['cat_zh']??'');
      $weight_kg = $p['weight_kg_raw'] ?? $guess['weight_kg'];
      $vol_from_dims = $p['dims_cm'] ? pdd_dims_to_volume($p['dims_cm']) : null;
      $volume_m3 = $vol_from_dims ?? $guess['volume_m3'];

      // Обрабатываем SKU-варианты
      $skus_out = [];
      if (!empty($p['skus'])) {
        foreach ($p['skus'] as $sku) {
          $dims = pdd_parse_sku_dims($sku['name']);
          $wv   = pdd_sku_wv($dims, $guess, $guess);
          $skus_out[] = [
            'id'        => $sku['id'],
            'name'      => $sku['name'],
            'price_cny' => $sku['price_cny'],
            'img'       => $sku['img'],
            'qty'       => $sku['qty'],
            'weight_kg' => $wv['wt'],
            'volume_m3' => $wv['vol'],
            'dims_auto' => $wv['auto'],
          ];
        }
      }
      jout(['ok'=>true,
            'name_zh'=>$p['name'],'name_ru'=>$name_ru,'ai_source'=>$enr['source'],
            'price_cny'=>$p['price_cny'],'images'=>$p['images'],
            'description_ru'=>$desc_ru,'sizes'=>$p['sizes'],'colors'=>$p['colors'],
            'src'=>$p['src'],
            'weight_kg'=>round($weight_kg,3),
            'volume_m3'=>round($volume_m3,5),
            'cat_guess'=>$guess['cat'],
            'confidence'=>$guess['confidence'],
            'weight_from_pdd'=>($p['weight_kg_raw']!==null),
            'skus'=>$skus_out,
            'has_variants'=>count($skus_out)>1,
            'duplicate'=>ds_find_duplicate($url,'pdd'),
      ]);
    }
    break;
  }

  // ---- Создать карточку из PDD + DS-запись ----
  case 'ds_create_from_pdd': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $name  = trim($d['name']??'');
    $url   = trim($d['source_url']??'');
    if($url!=='' && empty($d['force']) && ($dup=ds_find_duplicate($url,'pdd'))){ jout(['ok'=>false,'duplicate'=>$dup,'error'=>'Этот товар уже заведён']); break; }
    $pcny  = (float)($d['source_price_cny']??0);
    $mgr   = trim($d['manager_id']??'');
    $tpl   = trim($d['weight_template_id']??'');
    $descr = trim($d['description']??'');
    $imgs  = is_array($d['images']??null)?$d['images']:[];
    $sizes = is_array($d['sizes']??null)?$d['sizes']:[];
    $colors= is_array($d['colors']??null)?$d['colors']:[];
    // Вес и объём — ВСЕГДА заполнены (из PDD, из категории, или фолбэк)
    $dwt  = isset($d['declared_weight_kg'])&&(float)$d['declared_weight_kg']>0 ? (float)$d['declared_weight_kg'] : 1.0;
    $dvol = isset($d['declared_volume_m3'])&&(float)$d['declared_volume_m3']>0 ? (float)$d['declared_volume_m3'] : 0.005;
    $catName = trim($d['cat_guess']??'Прочее')?:'Прочее';
    $oldPrub = isset($d['old_price_rub'])&&$d['old_price_rub']>0?(int)$d['old_price_rub']:null;
    if(!$name) fail('Название обязательно');
    if(!$url)  fail('URL обязателен');

    $cover   = count($imgs)?$imgs[0]:'';
    $gallery = json_encode(array_slice($imgs,0,10),JSON_UNESCAPED_UNICODE);
    // Цена всегда рассчитывается — вес/объём гарантированно есть
    $price   = ($pcny>0)?ds_calc_price_rub($pcny,$dvol,$dwt):0;

    // Создаём карточку в каталоге как DS-черновик
    $pid = pdd_gen_pid();
    $catName = itc_store_category($name);
    db()->prepare('INSERT INTO products(id,supplier_id,cat,subcat,name,price,old_price,goods_cny,volume_m3,descr,img,gallery,stock,original,mod_status,weight_kg) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0,0,?,?)')
      ->execute([$pid,ds_supplier_id(),$catName,'',$name,$price,$oldPrub?:0,$pcny?:0,$dvol,$descr,$cover,$gallery,'approved',$dwt]);
    stamp_creator($pid, $s);

    // Размеры / цвета → варианты
    $varItems=[];
    if($sizes){ foreach($sizes as $sz) $varItems[]=['name'=>(string)$sz,'gallery'=>[]]; $baseName='Размер'; }
    elseif($colors){ foreach($colors as $cl) $varItems[]=['name'=>(string)$cl,'gallery'=>[]]; $baseName='Цвет'; }
    if($varItems){
      $vp=['baseName'=>$baseName,'items'=>$varItems];
      try{ db()->prepare('UPDATE products SET variants=? WHERE id=?')->execute([json_encode($vp,JSON_UNESCAPED_UNICODE),$pid]); }catch(Exception $e){}
    }

    // DS-запись
    $dsid=gen_ds_id();
    db()->prepare('INSERT INTO ds_products(id,product_id,source_url,source_platform,source_price_cny,manager_id,declared_weight_kg,declared_volume_m3,weight_template_id,old_price_rub,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')
      ->execute([$dsid,$pid,$url,'pdd',$pcny?:null,$mgr?:null,$dwt,$dvol,$tpl?:null,$oldPrub,$s['phone']??'']);
    ds_mark_auto($dsid);
    ds_sync_product_price($dsid);

    jout(['ok'=>true,'product_id'=>$pid,'ds_id'=>$dsid,'price'=>$price,
          'msg'=>'✅ Карточка создана! Добавьте объём для расчёта цены.']);
    break;
  }


  // ============================================================
  //  1688 (onebound) — импорт карточек
  //  Схема: api.php (Reg.ru) → api-gw.onebound.cn → JSON
  //  Китайский сервер и Puppeteer НЕ участвуют.
  // ============================================================

  // Разобрать ссылку 1688 → num_iid (без обращения к API, бесплатно)
  case 'ob_parse_url': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $u = ob_normalize_url(trim($d['url'] ?? ''));
    jout($u);
    break;
  }

  // Забрать товар с 1688 и разложить в таблицы ob_* (карточку НЕ создаёт)
  case 'ob_fetch': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $GLOBALS['OB_CREATED_BY'] = $s['phone'] ?? '';
    $d=body();
    $url = trim($d['url'] ?? '');
    if($url==='') fail('URL обязателен');
    /* Приводим к обычному виду: с телефона прилетает текст с иероглифами и
       короткой ссылкой, импорт такого не понимает. */
    $urlWas = $url;
    $url = itc_1688_normalize($url);
    if (!preg_match('~offer/\d+~', $url)) {
      jout(['ok'=>false,'error'=>'Не удалось разобрать ссылку. Откройте товар на 1688 и скопируйте адрес вида detail.1688.com/offer/…','sent'=>mb_substr($urlWas,0,120)]);
    }

    $r = ob_import($url, ['force'=>!empty($d['force'])]);
    if(empty($r['ok'])){ jout(['ok'=>false,'error'=>$r['error'] ?? 'Ошибка импорта','error_code'=>$r['error_code'] ?? null]); break; }

    $p = $r['parsed'];

    // ЗАГОЛОВОК ПЕРЕВОДИМ СРАЗУ. Иначе менеджер видит в списке иероглифы и
    // не понимает, что загрузил. Это один вызов YandexGPT (~0.5 с).
    // Варианты и характеристики — по кнопке «Перевести»: у иного товара их
    // 140, на загрузке это верный таймаут.
    $titleRu = '';
    if (function_exists('ai_translate_field') && !empty($p['title_cn'])) {
      $GLOBALS['yx_ds_fallback'] = 0;
      $t = ai_translate_field($p['title_cn'], 'name');
      if ($t) {
        $titleRu = mb_substr($t, 0, 500);
        ob_exec("UPDATE ob_item SET title_ru=? WHERE num_iid=?", [$titleRu, $p['num_iid']]);
      }
      // №318: заголовок перевёл запасной движок — метка 3 «в очередь DeepSeek»
      if (!empty($GLOBALS['yx_ds_fallback'])) {
        try { ob_pdo()->exec("ALTER TABLE ob_item ADD COLUMN tr_ds TINYINT NOT NULL DEFAULT 0"); } catch (Throwable $e) {}
        try { ob_exec("UPDATE ob_item SET tr_ds=3 WHERE num_iid=?", [$p['num_iid']]); } catch (Throwable $e) {}
      }
    }

    jout([
      'ok'=>true,
      'num_iid'     => $p['num_iid'],
      'title_cn'    => $p['title_cn'],
      'title_ru'    => $titleRu,
      'price_from'  => $p['price_cny'],      // цена «от» — справочно
      'price_to'    => $p['price_max_cny'],  // цена «до»
      'sku_count'   => $p['sku_count'],
      'price_min_cny'=> $p['price_min_cny'],
      'ladder'      => $p['ladder'],
      'moq'         => $p['moq'],
      'stock'       => $p['stock'],
      'cat_guess'   => $p['itc_category'],
      'weight_kg'   => $p['weight_kg'],
      'volume_m3'   => $p['volume_m3'],
      'dims_source' => $p['dims_source'],
      'images'      => array_column($p['images']['main'],'url'),
      'desc_images' => array_column($p['images']['desc'],'url'),
      'skus'        => $p['skus'],
      'location'    => $p['location'],
      'detail_url'  => $p['detail_url'],
      'warning'     => $p['import_note'],
      'from_cache'  => !empty($r['from_cache']),
      'cost_cny'    => $r['cost_cny'] ?? 0,
    ]);
    break;
  }

  // Создать карточку каталога из данных 1688.
  // Переиспользует существующий конвейер DS: products + ds_products.
  case 'ds_create_from_1688': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $url = trim($d['source_url'] ?? '');
    if($url==='') fail('URL обязателен');

    // Проверка дублей — ds_source_key() уже умеет 1688
    if(empty($d['force']) && ($dup=ds_find_duplicate($url,'1688'))){
      jout(['ok'=>false,'duplicate'=>$dup,'error'=>'Этот товар уже заведён']); break;
    }

    // Данные берём из ob_item (уже разобраны кейсом ob_fetch)
    $u = ob_normalize_url($url);
    if(empty($u['ok'])) fail($u['error'] ?? 'Не удалось разобрать ссылку 1688');
    $it = ob_row("SELECT * FROM ob_item WHERE num_iid=?", [$u['num_iid']]);
    if(!$it) fail('Товар не загружен. Сначала выполните ob_fetch.');

    $name  = trim($d['name'] ?? '') ?: trim($it['title_ru'] ?? '');
    if(!$name) fail('Название обязательно (переведите заголовок)');

    $pcny  = isset($d['source_price_cny']) && (float)$d['source_price_cny']>0
             ? (float)$d['source_price_cny'] : (float)$it['price_cny'];
    $dwt   = isset($d['declared_weight_kg']) && (float)$d['declared_weight_kg']>0
             ? (float)$d['declared_weight_kg'] : ((float)$it['weight_kg'] ?: 1.0);
    $dvol  = isset($d['declared_volume_m3']) && (float)$d['declared_volume_m3']>0
             ? (float)$d['declared_volume_m3'] : ((float)$it['volume_m3'] ?: 0.005);
    $catName = trim($d['cat_guess'] ?? '') ?: ($it['itc_category'] ?: 'Прочее');
    $descr = trim($d['description'] ?? '') ?: (string)($it['desc_ru'] ?? '');
    $mgr   = trim($d['manager_id'] ?? '');
    $tpl   = trim($d['weight_template_id'] ?? '');
    $oldPrub = isset($d['old_price_rub']) && $d['old_price_rub']>0 ? (int)$d['old_price_rub'] : null;

    // Фото: обложка — выбранная в ob_img, остальные в галерею по порядку
    $imgs = is_array($d['images'] ?? null) ? $d['images'] : [];
    if(!$imgs){
      $rows = ob_all("SELECT COALESCE(url_s3,url_src) u, is_cover FROM ob_img
                       WHERE num_iid=? AND kind='main' ORDER BY is_cover DESC, sort ASC", [$u['num_iid']]);
      $imgs = array_column($rows,'u');
    }
    $cover   = count($imgs) ? $imgs[0] : '';
    $gallery = json_encode(array_slice($imgs,0,10), JSON_UNESCAPED_UNICODE);

    // АВТОПАРСИНГ: вес по материалу (объём × плотность), item_weight поставщика не берём.
    // group_material (если задан) приоритетнее названия. Ручной ввод — не трогаем.
    if(!empty($d['auto']) && $dvol > 0 && function_exists('ob_weight_density')){
      $gm = trim($d['group_material'] ?? '');
      $dwt = round($dvol * ob_weight_density($gm !== '' ? $gm : $name), 1);
      if($gm !== '') { /* материал запомним в карточке ниже */ }
    }

    $price = ($pcny>0) ? ds_calc_price_rub($pcny,$dvol,$dwt) : 0;

    $pid = pdd_gen_pid();
    $catName = itc_store_category($name);
    db()->prepare('INSERT INTO products(id,supplier_id,cat,subcat,name,price,old_price,goods_cny,volume_m3,descr,img,gallery,stock,original,mod_status,weight_kg) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0,0,?,?)')
      ->execute([$pid,ds_supplier_id(),$catName,'',$name,$price,$oldPrub?:0,$pcny?:0,$dvol,$descr,$cover,$gallery,'approved',$dwt]);
    stamp_creator($pid, $s);

    // Варианты из SKU 1688
    $skus = ob_all("SELECT properties_cn, properties_ru FROM ob_sku WHERE num_iid=? ORDER BY id", [$u['num_iid']]);
    $varItems=[];
    foreach($skus as $sk){
      $nm = trim((string)($sk['properties_ru'] ?: $sk['properties_cn']));
      // «0:3:颜色:灰色» → берём последнюю часть
      if($nm!==''){ $parts=explode(':',$nm); $nm=trim(end($parts)); }
      if($nm!=='') $varItems[]=['name'=>$nm,'gallery'=>[]];
    }
    if($varItems){
      $vp=['baseName'=>'Вариант','items'=>$varItems];
      try{ db()->prepare('UPDATE products SET variants=? WHERE id=?')->execute([json_encode($vp,JSON_UNESCAPED_UNICODE),$pid]); }catch(Exception $e){}
    }

    // DS-запись — платформа '1688'
    $dsid=gen_ds_id();
    db()->prepare('INSERT INTO ds_products(id,product_id,source_url,source_platform,source_price_cny,manager_id,declared_weight_kg,declared_volume_m3,weight_template_id,old_price_rub,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')
      ->execute([$dsid,$pid,$url,'1688',$pcny?:null,$mgr?:null,$dwt,$dvol,$tpl?:null,$oldPrub,$s['phone']??'']);
    ds_mark_auto($dsid);
    try{ db()->prepare('UPDATE ds_products SET parse_mode=? WHERE id=?')->execute([!empty($d['auto'])?'auto':'manual',$dsid]); }catch(Exception $e){}
    ds_sync_product_price($dsid);

    // Связываем ob_item с созданной карточкой
    ob_exec("UPDATE ob_item SET product_id=?, import_status='published' WHERE num_iid=?", [$pid, $u['num_iid']]);

    jout(['ok'=>true,'product_id'=>$pid,'ds_id'=>$dsid,'price'=>$price,
          'warning'=>$it['import_note'] ?: null,
          'msg'=>'✅ Карточка создана из 1688']);
    break;
  }

  // Пакетное создание карточек из вариантов 1688.
  // ПОЧЕМУ ПОВАРИАНТНО: у товара нет одной цены. Пример живого товара —
  // стол ¥57.46~¥422.50, где 57.46 = отдельный стул, 422.50 = стол+6 стульев.
  // item.price = цена «от». Одна карточка на такой товар бессмысленна.
  // Зеркало ds_create_batch_from_pdd.
  case 'ds_create_batch_from_1688': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $source_url = trim($d['source_url'] ?? '');
    $base_name  = trim($d['base_name'] ?? '');
    $split      = (int)($d['split'] ?? 0);   // 1 = каждый вариант отдельной карточкой
    if(!$source_url) fail('Нет URL');
    if(!$base_name)  fail('Нет названия товара');

    $addMissing = !empty($d['add_missing']);   // №305: дозавести только недостающие варианты
    if(empty($d['force']) && !$addMissing && ($dup=ds_find_duplicate($source_url,'1688'))){
      jout(['ok'=>false,'duplicate'=>$dup,'error'=>'Этот товар уже заведён']); break;
    }

    $u = ob_normalize_url($source_url);
    if(empty($u['ok'])) fail($u['error'] ?? 'Не удалось разобрать ссылку 1688');
    /* №305: какие варианты этого товара 1688 уже есть в каталоге. Сравниваем по
       «подписи» варианта — набору чисел (M6*34*135 → 6x34x135), а без чисел —
       по тексту. Новые варианты получают ту же общую часть названия, что и
       уже заведённые, и ту же ссылку-источник — встают в ту же карточку. */
    $sigOf = function($t){ $t = mb_strtolower((string)$t); if (preg_match_all('/\d+(?:[.,]\d+)?/u', $t, $mm) && count($mm[0])) return 'n:'.implode('x', str_replace(',', '.', $mm[0])); return 't:'.preg_replace('/[^\p{L}]+/u', '', $t); };
    $have = []; $famSrc = '';
    if ($addMissing) {
      try {
        $hq = db()->prepare("SELECT p.name, d.source_url FROM ds_products d JOIN products p ON p.id=d.product_id WHERE d.source_url LIKE ?");
        $hq->execute(['%'.$u['num_iid'].'%']);
        foreach ($hq->fetchAll() as $hr) {
          $nm = (string)$hr['name']; $pos = mb_strpos($nm, ' · ');
          if ($famSrc === '') { $famSrc = (string)$hr['source_url']; if ($pos !== false) $base_name = mb_substr($nm, 0, $pos); }
          $have[$sigOf($pos !== false ? mb_substr($nm, $pos + 3) : $nm)] = 1;
        }
      } catch (Exception $e) {}
      if ($famSrc !== '') $source_url = $famSrc;
    }
    $it = ob_row("SELECT * FROM ob_item WHERE num_iid=?", [$u['num_iid']]);
    if(!$it) fail('Товар не загружен. Сначала выполните ob_fetch.');

    $description = trim($d['description'] ?? '') ?: (string)($it['desc_ru'] ?? '');
    // Своего описания у 1688 нет — оно там картинками. Соберём из характеристик:
    // один запрос на товар, а не на каждый из 19 вариантов.
    if($description === '' && function_exists('ob_item_description')){
      try { $description = ob_item_description($u['num_iid']); }
      catch (Exception $e) { @error_log('[ds_create_batch] описание: '.$e->getMessage()); }
    }
    $cat_guess   = trim($d['cat_guess'] ?? '') ?: ($it['itc_category'] ?: 'Прочее');
    $mgr         = trim($d['manager_id'] ?? '');
    // АВТОПАРСИНГ: вес считаем сами по материалу, item_weight поставщика (часто
    // 60 кг «на коробку») игнорируем. $group_material — необязательное поле:
    // если менеджер задал материал на всю группу, он приоритетнее названия.
    $auto        = !empty($d['auto']);
    $x3          = !empty($d['x3']);   // режим кнопки ×3 (цена по себестоимости × множитель)
    $x3lvl       = (int)($d['x3_level'] ?? 0);
    $x3mult      = ($x3lvl>=1 && $x3lvl<=15) ? $x3lvl+1 : null;   // ×1→2 … ×5→6, ×10→11, ×15→16
    $x3levels    = is_array($d['x3_levels'] ?? null) ? $d['x3_levels'] : [];   // id варианта → уровень
    $group_mat   = trim($d['group_material'] ?? '');
    // Категория из ветки 1688, по которой шёл импорт «по категориям» — надёжнее,
    // чем угадывание по названию. Верхний уровень → категория, лист → подкатегория.
    $sub_from_cat = '';
    $catPath = is_array($d['cat_path'] ?? null)
      ? array_values(array_filter(array_map(function($x){return trim((string)$x);}, $d['cat_path'])))
      : [];
    if ($catPath) {
      $cat_guess = mb_substr($catPath[0], 0, 60);
      if (count($catPath) > 1) $sub_from_cat = mb_substr((string)end($catPath), 0, 60);
    }

    // Характеристики — таблицей под описанием. Покупатель спрашивает «что за
    // товар»: материал, тип, стиль отвечают на это лучше любого текста.
    $specRows = ob_all("SELECT name_ru,name_cn,value_ru,value_cn FROM ob_prop
                         WHERE num_iid=? ORDER BY sort LIMIT 20", [$u['num_iid']]);
    $specs = [];
    foreach($specRows as $sp){
      $n = trim((string)($sp['name_ru']  ?: $sp['name_cn']));
      $v = trim((string)($sp['value_ru'] ?: $sp['value_cn']));
      if($n==='' || $v==='') continue;
      if(has_cjk($n) || has_cjk($v)) continue;   // непереведённое покупателю не показываем
      if(mb_strlen($v) > 100) continue;          // «цвет» бывает списком на пол-экрана
      $specs[] = $n.': '.$v;
    }

    // Общая галерея товара
    $images = is_array($d['images'] ?? null) ? $d['images'] : [];
    if(!$images){
      $rows = ob_all("SELECT COALESCE(url_s3,url_src) u FROM ob_img
                       WHERE num_iid=? AND kind='main' ORDER BY is_cover DESC, sort ASC", [$u['num_iid']]);
      $images = array_column($rows,'u');
    }
    $cover   = count($images) ? $images[0] : '';
    $gallery = json_encode(array_slice($images,0,10), JSON_UNESCAPED_UNICODE);

    // Какие варианты заводим: из тела запроса, иначе все выбранные в ob_sku
    $pick = is_array($d['skus'] ?? null) ? $d['skus'] : null;
    /* №306: «Обновить с 1688» — берём ВСЕ варианты товара, лишние отсеет add_missing */
    if ($pick === null && !empty($d['all_skus']) && $addMissing) $pick = ob_all("SELECT * FROM ob_sku WHERE num_iid=? ORDER BY id", [$u['num_iid']]);
    if($pick===null){
      $pick = ob_all("SELECT * FROM ob_sku WHERE num_iid=? AND selected=1 AND product_id IS NULL ORDER BY id",
                     [$u['num_iid']]);
    }
    // Ничего не отмечено — карточки не создаём. Отбор только руками:
    // у одного товара бывает 69 вариантов, автоматом заводить нельзя.
    if(!count($pick)) fail('Ни один вариант не отмечен. Откройте ob_sku_list и отметьте нужные (ob_sku_select).');

    $created = []; $skipped = [];
    $base_name = itc_tr_name($base_name);   // №283: без иероглифов в названии
    foreach($pick as $sku){
      // Ключ варианта — для связи с ob_sku
      $props = trim((string)($sku['properties'] ?? ''));

      $sku_name = trim((string)($sku['name_ru'] ?? $sku['name'] ?? $sku['properties_cn'] ?? ''));
      if ($sku_name !== '' && has_cjk($sku_name)) $sku_name = itc_tr_name($sku_name);   // №283
      if ($addMissing && (isset($have[$sigOf($sku_name)]) || isset($have[$sigOf((string)($sku['properties_cn'] ?? ''))]))) { $skipped[] = ['name'=>$sku_name,'why'=>'уже есть в карточке']; continue; }
      $pcny     = (float)($sku['price_cny'] ?? 0);
      if($pcny <= 0){ $skipped[] = ['name'=>$sku_name,'why'=>'нет цены']; continue; }

      // ОБЪЁМ.
      // Куб фрахта стоит ~14 000 ₽, ошибка в объёме = продажа в убыток.
      // Если категория не опознана — объём НЕ выдумываем и НЕ ставим дефолт.
      // Карточка создаётся с volume=0, ds_sync_product_price() сам поставит
      // blocked=1 и цену NULL — покупатель её не увидит. Она попадает в очередь
      // ob_volume_queue: менеджер запрашивает 外箱尺寸 у фабрики, вносит объём
      // через ob_set_volume — карточка пересчитывается и публикуется сама.
      $vsrc = (string)($sku['vol_source'] ?? $it['vol_source'] ?? 'none');
      $dwt  = (float)($sku['weight_kg'] ?? 0);
      if($dwt <= 0) $dwt = (float)($it['weight_kg'] ?: 0);
      $dvol = (float)($sku['volume_m3'] ?? 0);
      if($dvol <= 0) $dvol = (float)($it['volume_m3'] ?: 0);
      // К ЦЕНЕ ДОПУСКАЕМ ТОЛЬКО ИЗМЕРЕННОЕ.
      // box_props — 包装尺寸 от поставщика, manual — замер менеджера. Им верим.
      // kd_category — догадка ds_kd_rules по названию ТОВАРА: имя варианта на
      // неё не влияет, поэтому одна цифра ложится на все 69 вариантов от 6.80
      // до 49 ¥. Верна максимум для одного. Именно так вышло 0.09 м3 вместо
      // 0.016 и цена 4414 ₽ вместо ~700.
      // Та же политика уже действовала в ob_auto_import — здесь её не было.
      // 'calibrated' — объём пересчитан от НАСТОЯЩЕГО замера одной коробки
      // через габариты изделия из названия. Не догадка: замер один, остальное
      // геометрия. См. ob_calibrate_from().
      if(!in_array($vsrc, ['box_props','manual','calibrated','ai'], true)){ $dvol = 0; $dwt = 0; }

      // АВТОПАРСИНГ: если объём есть (ему доверяем) — вес считаем по материалу:
      // объём × плотность. Материал берём из поля группы (приоритет) или из
      // названия варианта (проволока→55, пластик→45, металл→180 …). item_weight
      // поставщика (60 кг) в расчёт не идёт. Ручной парсинг ($auto=false) — как был.
      if($auto && $dvol > 0 && function_exists('ob_weight_density')){
        $matTxt = ($group_mat !== '') ? $group_mat : ($base_name.' '.$sku_name);
        $dwt = round($dvol * ob_weight_density($matTxt), 1);
      }

      if($split){
        $vv = ($sku_name !== '') ? $sku_name : ('№'.$sku['id']);
        $full_name = $base_name.' '.$vv;         // без « · » — магазин не склеит варианты в одну карточку
      } else {
        $full_name = $sku_name ? $base_name.' · '.$sku_name : $base_name;
      }
      $sku_img   = trim((string)($sku['img_s3'] ?? $sku['img_url'] ?? ''));
      $sku_cover = $sku_img ?: $cover;

      // Описание СВОЁ у каждого варианта: общий текст + чем именно этот
      // отличается + характеристики. Иначе на вопрос «что за товар» карточка
      // отвечает молчанием, а варианты неотличимы друг от друга.
      $descParts = [];
      if($description !== '') $descParts[] = $description;
      if($sku_name !== '')    $descParts[] = 'Этот вариант: '.$sku_name.'.';
      if($dvol > 0)           $descParts[] = 'Объём упаковки '.rtrim(rtrim(number_format($dvol,3,'.',''),'0'),'.').' м³'.
                                             ($dwt>0 ? ', вес '.rtrim(rtrim(number_format($dwt,2,'.',''),'0'),'.').' кг' : '').'.';
      if($specs)              $descParts[] = "\nХарактеристики:\n• ".implode("\n• ", $specs);
      $descFull = trim(implode("\n\n", $descParts));

      // Индивидуальный уровень ×N варианта (или общий)
      $lvlThis = isset($x3levels[$sku['id']]) ? (int)$x3levels[$sku['id']] : $x3lvl;
      $multThis = ($lvlThis>=1 && $lvlThis<=15) ? $lvlThis+1 : $x3mult;
      $price = $x3 ? ds_calc_price_x3($pcny, $multThis) : ds_calc_price_rub($pcny,$dvol,$dwt);
      $pid   = pdd_gen_pid();

      $cat_guess = itc_store_category($full_name);
      db()->prepare('INSERT INTO products(id,supplier_id,cat,subcat,name,price,goods_cny,volume_m3,descr,img,gallery,stock,original,mod_status,weight_kg) VALUES(?,?,?,?,?,?,?,?,?,?,?,0,0,?,?)')
        ->execute([$pid,ds_supplier_id(),$cat_guess,itc_store_subcat($cat_guess,$full_name),$full_name,$price,$pcny,$dvol,$descFull,$sku_cover,$gallery,'approved',$dwt]);
      stamp_creator($pid, $s);
      // Материал группы (если задан) запоминаем в карточке — останется приоритетом
      if($auto && $group_mat !== ''){
        try{ db()->prepare('UPDATE products SET material=? WHERE id=?')->execute([mb_substr($group_mat,0,80),$pid]); }catch(Exception $e){}
      }

      $dsid=gen_ds_id();
      db()->prepare('INSERT INTO ds_products(id,product_id,source_url,source_platform,source_price_cny,manager_id,declared_weight_kg,declared_volume_m3,created_by) VALUES(?,?,?,?,?,?,?,?,?)')
        ->execute([$dsid,$pid,$source_url,'1688',$pcny,$mgr?:null,$dwt,$dvol,$s['phone']??'']);
      ds_mark_auto($dsid);
      try{ db()->prepare('UPDATE ds_products SET parse_mode=?, x3_pending=?, x3_mult=? WHERE id=?')->execute([($x3?'x3':($auto?'auto':'manual')), ($x3?1:0), ($x3?$multThis:null), $dsid]); }catch(Exception $e){}
      ds_sync_product_price($dsid);

      if($props!=='') ob_exec("UPDATE ob_sku SET product_id=? WHERE num_iid=? AND properties=?",
                              [$pid, $u['num_iid'], $props]);

      $created[] = ['product_id'=>$pid,'ds_id'=>$dsid,'name'=>$full_name,
                    'price'=>$price,'price_cny'=>$pcny,
                    'volume_m3'=>$dvol,'weight_kg'=>$dwt,
                    'vol_source'=>$vsrc,
                    'awaiting_volume'=>($dvol<=0 ? 1 : 0),
                    'set_note'=>$sku['set_note'] ?? null];
    }

    ob_exec("UPDATE ob_item SET import_status='published' WHERE num_iid=?", [$u['num_iid']]);

    // ФОТО — ЗДЕСЬ, а не при загрузке товара. Причина в порядке действий:
    // ob_photos_sync_products() прописывает ссылки по product_id из ob_sku,
    // а при загрузке карточек ещё нет — product_id пустой. Фото уезжали в S3
    // и повисали: прописать их было некуда, карточка потом бралась со старой
    // ссылкой на alicdn и показывала покупателю пустой квадрат.
    // Теперь product_id только что проставлен строкой выше — самое время.
    $photos = null;
    if ($created && function_exists('ob_photos_process')) {
      try {
        // Перенесёт только то, чего ещё нет в S3 (в выборке стоит
        // url_s3 IS NULL), поэтому повторный вызов ничего не сломает
        $photos = ob_photos_process($u['num_iid'], ['kinds'=>['main','sku'], 'limit'=>20]);
      } catch (Exception $e) {
        @error_log('[ds_create_batch_from_1688] фото: '.$e->getMessage());
      }
    }

    // ВИДЕО — одно на товар. Ссылка на alicdn из РФ не открывается, поэтому
    // переносим ролик в S3 (как фото) и прописываем во все созданные карточки.
    // Тяжёлое/битое видео не должно валить создание карточек — всё в try.
    if ($created && !empty($it['video_url'])) {
      try {
        $vurl = ob_video_to_s3($it['video_url']);
        if ($vurl) {
          $vids = array_column($created, 'product_id');
          $vin  = implode(',', array_fill(0, count($vids), '?'));
          db()->prepare("UPDATE products SET video=? WHERE id IN ($vin)")
              ->execute(array_merge([$vurl], $vids));
          // и в ob_item — чтобы при повторном создании не качать заново
          ob_exec("UPDATE ob_item SET video_url=? WHERE num_iid=?", [$vurl, $u['num_iid']]);
        }
      } catch (Exception $e) { @error_log('[ds_create_batch_from_1688] видео: '.$e->getMessage()); }
    }

    // ПОИСКОВЫЕ СЛОВА — одни на товар (варианты ищутся одинаково). ИИ придумывает
    // русские фразы, покупатель находит товар по ним. Не валит создание карточек.
    if ($created && function_exists('ds_gen_search_tags')) {
      try {
        $tags = ds_gen_search_tags($base_name, $description, $cat_guess);
        if ($tags !== '') {
          $tids = array_column($created, 'product_id');
          $tin  = implode(',', array_fill(0, count($tids), '?'));
          db()->prepare("UPDATE products SET search_tags=? WHERE id IN ($tin)")
              ->execute(array_merge([$tags], $tids));
        }
      } catch (Exception $e) { @error_log('[ds_create_batch_from_1688] tags: '.$e->getMessage()); }
    }

    // Предупреждения по объёму комплектов — их надо проверить глазами
    $warn = array_values(array_filter(array_column($created,'set_note')));

    $n = count($created);
    $wait = count(array_filter($created, fn($c)=>$c['awaiting_volume']));
    $msg = "✅ Создано $n карточек из вариантов 1688";
    if($wait) $msg .= " · $wait ждут объём (скрыты от покупателей)";
    if($photos) $msg .= " · фото в S3: ".$photos['done'].($photos['failed']? ", не вышло: ".$photos['failed'] : "");
    jout(['ok'=>true,'created'=>$created,'count'=>$n,'awaiting_volume'=>$wait,
          'skipped'=>$skipped,'warnings'=>$warn,'photos'=>$photos,'msg'=>$msg]);
    break;
  }

  // ---- Прокси картинок 1688 ----
  // В выдаче поиска фото ведут на alicdn, а он из России не открывается:
  // менеджер видит пустые квадраты. Товар ещё не загружен, копии в S3 нет
  // и взять её неоткуда. Сервер Reg.ru до alicdn достаёт — это доказал
  // перенос 69 фото, — поэтому отдаём картинку через него.
  //
  // Домены ограничены жёстко: иначе это открытый прокси, через который
  // можно ходить куда угодно от имени нашего сервера.
  case 'ob_img_proxy': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $u = trim($_GET['u'] ?? '');
    if($u === '') fail('Нет ссылки');
    if(strpos($u,'//') === 0) $u = 'https:'.$u;
    $host = parse_url($u, PHP_URL_HOST);
    $sch  = parse_url($u, PHP_URL_SCHEME);
    if(!$host || !in_array($sch, ['http','https'], true)
       || !preg_match('/(^|\.)(alicdn\.com|1688\.com|taobao\.com)$/i', $host))
      fail('Домен не разрешён', 403);

    $ch = curl_init($u);
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER => true,
      CURLOPT_TIMEOUT        => 12,
      CURLOPT_FOLLOWLOCATION => false,   // редиректом можно увести на чужой домен
      CURLOPT_USERAGENT      => 'Mozilla/5.0',
      CURLOPT_REFERER        => 'https://detail.1688.com/',
    ]);
    $body = curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $ct   = (string)curl_getinfo($ch, CURLINFO_CONTENT_TYPE);
    curl_close($ch);

    if($body === false || $code !== 200) fail('Картинка не отдалась ('.$code.')', 502);
    if(strpos($ct, 'image/') !== 0) fail('Это не картинка', 415);
    if(strlen($body) > 4*1024*1024) fail('Слишком большая', 413);

    header('Content-Type: '.$ct);
    header('Content-Length: '.strlen($body));
    header('Cache-Control: private, max-age=86400');
    echo $body;
    exit;
  }

  // Видео 1688 для предпросмотра в админке (пока оно на alicdn и из РФ не
  // открывается). Тот же принцип, что ob_img_proxy, но для видео. Только лёгкое.
  case 'ob_video_proxy': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $u = trim($_GET['u'] ?? '');
    if($u === '') fail('Нет ссылки');
    if(strpos($u,'//') === 0) $u = 'https:'.$u;
    $host = parse_url($u, PHP_URL_HOST);
    $sch  = parse_url($u, PHP_URL_SCHEME);
    // Видео 1688 живёт на разных хостах Alibaba (cloud.video.taobao.com,
    // *.aliyuncs.com, *.alicdn.com и т.п.) и часто отдаётся через редирект.
    if(!$host || !in_array($sch, ['http','https'], true)
       || !preg_match('/(^|\.)(alicdn\.com|1688\.com|taobao\.com|tmall\.com|alibaba\.com|aliyuncs\.com|mmcdn\.cn|taobaocdn\.com|alivod\.com|ykimg\.com)$/i', $host))
      fail('Домен не разрешён', 403);
    $pathLow = strtolower((string)parse_url($u, PHP_URL_PATH));
    $ch = curl_init($u);
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER => true,
      CURLOPT_TIMEOUT        => 40,
      CURLOPT_CONNECTTIMEOUT => 15,
      CURLOPT_FOLLOWLOCATION => true,
      CURLOPT_MAXREDIRS      => 5,
      CURLOPT_PROTOCOLS      => CURLPROTO_HTTP | CURLPROTO_HTTPS,
      CURLOPT_REDIR_PROTOCOLS=> CURLPROTO_HTTP | CURLPROTO_HTTPS,
      CURLOPT_SSL_VERIFYPEER => false,
      CURLOPT_USERAGENT      => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
      CURLOPT_REFERER        => 'https://detail.1688.com/',
    ]);
    $body = curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $ct   = (string)curl_getinfo($ch, CURLINFO_CONTENT_TYPE);
    curl_close($ch);
    if($body === false || $code < 200 || $code >= 300) fail('Видео не отдалось ('.$code.')', 502);
    $looksVideo = (strpos($ct,'video/')===0) || (strpos($ct,'octet-stream')!==false) || $ct==='' ||
                  preg_match('/\.(mp4|m4v|webm|mov)$/', $pathLow);
    if(!$looksVideo) fail('Это не видео ('.$ct.')', 415);
    if(strlen($body) > 40*1024*1024) fail('Слишком большое для предпросмотра', 413);
    header('Content-Type: '.((strpos($ct,'video/')===0)?$ct:'video/mp4'));
    header('Content-Length: '.strlen($body));
    header('Accept-Ranges: none');
    header('Cache-Control: private, max-age=3600');
    echo $body;
    exit;
  }

  // ---- Список ЗАГРУЖЕННЫХ товаров 1688 ----
  // Такого кейса не было вовсе: все остальные ходят WHERE num_iid=?, то есть
  // менеджер, загрузив товар, терял его — вернуться можно было только помня
  // номер наизусть. Отсюда же и прогресс по каждому: сколько вариантов,
  // сколько отмечено, сколько заведено, осталась ли китайщина.
  case 'ob_items': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $myPhone = $s['phone'] ?? '';
    $q = trim($_GET['q'] ?? '');
    // Каждый сотрудник видит только свои загрузки. Старые записи без владельца — видны всем (переходный период).
    $where = "(i.created_by = ? OR i.created_by IS NULL OR i.created_by = '')"; $args = [$myPhone];
    if($q !== ''){
      $where .= " AND (i.num_iid LIKE ? OR i.title_ru LIKE ? OR i.title_cn LIKE ?)";
      $like = '%'.$q.'%'; $args[] = $like; $args[] = $like; $args[] = $like;
    }
    $rows = ob_all(
      "SELECT i.num_iid, i.title_ru, i.title_cn, i.price_cny, i.price_max_cny,
              i.shop_name, i.location, i.moq, i.detail_url, i.updated_at, i.itc_category, UNIX_TIMESTAMP(i.updated_at)*1000 AS ts,
              (SELECT COUNT(*) FROM ob_sku k WHERE k.num_iid=i.num_iid) sku_total,
              (SELECT COUNT(*) FROM ob_sku k WHERE k.num_iid=i.num_iid AND k.selected=1
                                              AND k.product_id IS NULL) sku_sel,
              (SELECT COUNT(*) FROM ob_sku k WHERE k.num_iid=i.num_iid
                                              AND k.product_id IS NOT NULL) sku_done,
              (SELECT COUNT(*) FROM ob_sku k WHERE k.num_iid=i.num_iid AND k.suggest=1
                                              AND k.product_id IS NULL) sku_sug,
              (SELECT COUNT(*) FROM ob_sku k WHERE k.num_iid=i.num_iid
                                              AND k.name_ru REGEXP '[一-龥]') sku_zh,
              (SELECT COALESCE(NULLIF(g.url_s3,''),g.url_src) FROM ob_img g
                WHERE g.num_iid=i.num_iid AND g.kind='main'
                ORDER BY g.is_cover DESC, g.sort ASC LIMIT 1) cover
         FROM ob_item i WHERE {$where} ORDER BY i.updated_at DESC LIMIT 60", $args);
    jout(['ok'=>true,'items'=>$rows,'count'=>count($rows)]);
  }

  // ---- Удалить группу целиком: товар + все его варианты ----
  // Что НЕ трогаем и почему:
  //   ob_raw  — кэш ответа onebound. Он и есть страховка: если товар удалили
  //             по ошибке, повторная загрузка возьмёт данные из кэша БЕСПЛАТНО.
  //             Снесём кэш — перезагрузка будет стоить вызов.
  //   ob_log  — история расходов. Затирать учёт потраченных денег нельзя.
  //   ob_seller — фабрика общая для многих товаров.
  //   products — карточки в магазине живут сами по себе. Если они заведены,
  //             тихо оборвать связь нельзя: спрашиваем подтверждение.
  case 'ob_sku_delete': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body(); $id=(int)($d['sku_id']??0);
    if(!$id) fail('Не указан вариант');
    $sk=ob_row("SELECT id,num_iid,product_id FROM ob_sku WHERE id=?", [$id]);
    if(!$sk) fail('Вариант не найден');
    if(!empty($sk['product_id'])) fail('У варианта уже есть карточка — удалять нельзя. Сначала удалите карточку в «Опубликованных».');
    ob_exec("DELETE FROM ob_sku WHERE id=?", [$id]);
    if(function_exists('ob_recalc_item')){ try{ ob_recalc_item($sk['num_iid']); }catch(Exception $e){} }
    jout(['ok'=>true,'num_iid'=>$sk['num_iid']]);
  }

  case 'ob_item_delete': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $iid = trim((string)($d['num_iid'] ?? ''));
    if($iid==='') fail('Не указан num_iid');

    $it = ob_row("SELECT num_iid,title_ru,title_cn FROM ob_item WHERE num_iid=?", [$iid]);
    if(!$it) fail('Товар не найден — возможно, уже удалён');

    $made = (int)(ob_row("SELECT COUNT(*) c FROM ob_sku
                           WHERE num_iid=? AND product_id IS NOT NULL", [$iid])['c'] ?? 0);

    // Есть карточки в магазине — без явного «да» не удаляем
    if($made && empty($d['force']))
      jout(['ok'=>false,'need_confirm'=>1,'made'=>$made,
            'error'=>'У этого товара заведено карточек в магазине: '.$made.
                     '. Они останутся в магазине и продолжат продаваться, но связь с 1688 '.
                     'оборвётся: цена перестанет обновляться. Удалять?']);

    $sku = (int)(ob_row("SELECT COUNT(*) c FROM ob_sku WHERE num_iid=?", [$iid])['c'] ?? 0);

    ob_exec("DELETE FROM ob_img        WHERE num_iid=?", [$iid]);
    ob_exec("DELETE FROM ob_prop       WHERE num_iid=?", [$iid]);
    ob_exec("DELETE FROM ob_price_tier WHERE num_iid=?", [$iid]);
    ob_exec("DELETE FROM ob_sku        WHERE num_iid=?", [$iid]);
    ob_exec("DELETE FROM ob_item       WHERE num_iid=?", [$iid]);

    try { itc_log_add(current_staff_id($s), 'ob_item_delete', 'ob_item', $iid,
                      ($it['title_ru'] ?: $it['title_cn']).' · вариантов: '.$sku); }
    catch (Exception $e) {}

    jout(['ok'=>true,'num_iid'=>$iid,'sku_deleted'=>$sku,
          'msg'=>'Удалено. Вариантов: '.$sku.
                 ($made? ' · карточек в магазине осталось: '.$made : '').
                 ' · повторная загрузка возьмётся из кэша, без вызова']);
  }

  // ---- Список вариантов товара для ручного отбора ----
  // На живом товаре 709411502301 оказалось 69 SKU. Автоматом не заводим:
  // менеджер смотрит цену и ратио фрахта, отмечает нужные галочками.
  case 'ob_sku_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $iid = trim($_GET['num_iid'] ?? '');
    if(!$iid){ $d=body(); $iid = trim($d['num_iid'] ?? ''); }
    if(!$iid) fail('Не указан num_iid');

    $it = ob_row("SELECT num_iid,title_cn,title_ru,price_cny,price_max_cny,sku_count,
                         moq,location,shop_name,itc_category,volume_m3,vol_source,
                         import_note,detail_url,desc_ru,video_url
                    FROM ob_item WHERE num_iid=?", [$iid]);
    if(!$it) fail('Товар не загружен. Сначала ob_fetch.');

    // img_url ведёт на alicdn, а он из России не открывается — в списке были
    // пустые квадраты. Отдаём перенесённую в S3 копию, если она есть.
    // Колонку проверяем: ob_all() глотает ошибку SQL и вернул бы пустой список.
    $hasS3 = (bool)ob_row("SHOW COLUMNS FROM ob_sku LIKE 'img_s3'");
    // Префикс s. обязателен: ниже появился LEFT JOIN products, и без него
    // MySQL не поймёт, из какой таблицы брать колонку
    $imgCol = $hasS3 ? "COALESCE(NULLIF(s.img_s3,''),s.img_url) AS img_url" : "s.img_url";
    $skus = ob_all("SELECT s.id,s.properties,s.properties_cn,s.name_ru,s.price_cny,s.quantity,
                           {$imgCol},
                           s.len_cm,s.wid_cm,s.hei_cm,s.volume_m3,s.weight_kg,s.vol_source,s.kd_cat,
                           s.is_set,s.set_qty,s.set_note,s.selected,s.suggest,s.suggest_note,
                           s.seller_warn,s.freight_ratio,s.product_id,
                           p.paused, p.blocked, p.price AS price_rub, p.mod_status
                      FROM ob_sku s
                 LEFT JOIN products p ON p.id = s.product_id
                     WHERE s.num_iid=? ORDER BY s.price_cny ASC, s.id ASC", [$iid]);

    // Сводка — чтобы менеджер сразу видел картину
    $n_sug = 0; $n_sel = 0; $n_done = 0;
    foreach($skus as $k){
      if($k['suggest']) $n_sug++;
      if($k['selected']) $n_sel++;
      if($k['product_id']) $n_done++;
    }
    $gal = ob_all("SELECT COALESCE(NULLIF(url_s3,''),url_src) u FROM ob_img
                    WHERE num_iid=? AND kind='main' ORDER BY is_cover DESC, sort ASC LIMIT 10",
                  [$iid]);
    $it['gallery'] = array_column($gal, 'u');

    // Характеристики: переведены, но до сих пор нигде не показывались.
    $it['props'] = ob_all("SELECT name_cn,value_cn,name_ru,value_ru FROM ob_prop
                            WHERE num_iid=? ORDER BY sort LIMIT 25", [$iid]);

    jout(['ok'=>true,'item'=>$it,'skus'=>$skus,
          'total'=>count($skus),'suggested'=>$n_sug,
          'selected'=>$n_sel,'created'=>$n_done,
          'freight_suspect'=>OB_FREIGHT_SUSPECT]);
  }

  // ---- Пересчёт рекомендаций по сохранённым данным ----
  // Не путать с ob_fetch: тот сносит ob_sku/ob_prop и вставляет заново,
  // затирая перевод и связь product_id. Здесь только счётные поля.
  case 'ob_recalc': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!function_exists('ob_recalc_item')) fail('ob_1688.php устарел — обновите файл');
    $d=body();
    $iid = trim($d['num_iid'] ?? $_GET['num_iid'] ?? '');
    if(!$iid) fail('Не указан num_iid');
    $r = ob_recalc_item($iid);
    jout(['ok'=>true] + $r + ['msg'=>'Пересчитано вариантов: '.$r['changed'].' из '.$r['total']]);
  }

  // ---- Приостановить / возобновить показ карточки ----
  // Отдельно от blocked: тот снимается автоматикой при пересчёте цены
  // (см. 'UPDATE products SET price=?, blocked=0'), и ручная пауза слетела
  // бы молча. Решение менеджера автоматика трогать не должна.
  case 'ob_sku_pause': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $pid = trim((string)($d['product_id'] ?? ''));
    if($pid==='') fail('Не указана карточка');
    $on = !empty($d['paused']) ? 1 : 0;

    $q = db()->prepare("SELECT id,name FROM products WHERE id=?"); $q->execute([$pid]);
    $p = $q->fetch();
    if(!$p) fail('Карточка не найдена');

    db()->prepare("UPDATE products SET paused=? WHERE id=?")->execute([$on, $pid]);
    try { itc_log_add(current_staff_id($s), $on?'product_pause':'product_resume',
                      'product', $pid, mb_substr((string)$p['name'],0,200)); }
    catch (Exception $e) {}

    jout(['ok'=>true,'product_id'=>$pid,'paused'=>$on,
          'msg'=>$on ? 'Показ приостановлен — покупателю карточка не видна'
                     : 'Показ возобновлён — карточка снова в магазине']);
  }

  // ---- Объём варианта: ответ фабрики ----
  // ob_set_volume требует ds_id, то есть работает только с УЖЕ созданной
  // карточкой и на другом экране. Менеджер смотрит на вариант, видит
  // «объём неизвестен» — и должен уйти куда-то ещё. Здесь он вписывает
  // 外箱尺寸 прямо там, где смотрит, ещё до создания карточки.
  case 'ob_sku_volume': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $id = (int)($d['sku_id'] ?? 0);
    if(!$id) fail('Не указан вариант');
    $sku = ob_row("SELECT id,num_iid,product_id,weight_kg,len_cm,wid_cm,hei_cm
                     FROM ob_sku WHERE id=?", [$id]);
    if(!$sku) fail('Вариант не найден');

    // ОБЪЁМ. Три способа, по убыванию точности:
    //   boxes[]   — список коробок, у каждой свои Д×Ш×В и количество.
    //               Шкаф едет в 2-3 коробках РАЗНОГО размера, одним
    //               полем Д×Ш×В это не описать.
    //   box_*_cm  — одна коробка (короткий путь).
    //   volume_m3 — менеджер посчитал сам.
    // pcs_per_box делит: одна коробка на несколько товаров.
    $pcs = max(1, (int)($d['pcs_per_box'] ?? 1));
    $vol = (float)($d['volume_m3'] ?? 0);

    $boxes = is_array($d['boxes'] ?? null) ? $d['boxes'] : [];
    if($vol <= 0 && $boxes){
      $vol = 0;
      foreach($boxes as $b){
        $bl=(float)($b['l']??0); $bw=(float)($b['w']??0); $bh=(float)($b['h']??0);
        $bn=max(1,(int)($b['n']??1));
        if($bl>0 && $bw>0 && $bh>0) $vol += ($bl/100)*($bw/100)*($bh/100)*$bn;
      }
      if($vol>0 && $pcs>1) $vol = $vol/$pcs;
      $vol = round($vol, 4);
    }
    if($vol <= 0){
      $bl=(float)($d['box_len_cm']??0); $bw=(float)($d['box_wid_cm']??0); $bh=(float)($d['box_hei_cm']??0);
      if($bl>0 && $bw>0 && $bh>0){
        $vol = ($bl/100)*($bw/100)*($bh/100);
        if($pcs>1) $vol = $vol/$pcs;
        $vol = round($vol,4);
      }
    }
    if($vol <= 0) fail('Укажите габариты коробки Д×Ш×В или готовый объём');

    // Самая вероятная ошибка: вписали габариты ИЗДЕЛИЯ, а не коробки —
    // они же прямо в названии варианта («длина 40 × ширина 30»), рука сама
    // тянется. Коэффициент выйдет 1.0 и пройдёт все проверки, а фрахт
    // окажется завышен в разы. Сверяем с габаритами изделия напрямую.
    if($boxes && count($boxes) === 1
       && $sku['len_cm'] && $sku['wid_cm'] && $sku['hei_cm']){
      $b = [(float)($boxes[0]['l']??0), (float)($boxes[0]['w']??0), (float)($boxes[0]['h']??0)];
      $i = [(float)$sku['len_cm'], (float)$sku['wid_cm'], (float)$sku['hei_cm']];
      sort($b); sort($i);
      $same = true;
      foreach([0,1,2] as $k2){ if(abs($b[$k2]-$i[$k2]) > 0.5){ $same=false; break; } }
      if($same && empty($d['confirm_same']))
        fail('Вы вписали габариты изделия (' . implode('×', $i) . ' см), а не коробки. '
           . 'Коробка обычно меньше — мебель едет разобранной. Проверьте ответ фабрики: нужен 外箱尺寸.');
    }

    $wt = (float)($d['weight_kg'] ?? 0);
    if($wt <= 0) $wt = (float)($sku['weight_kg'] ?: 0);
    if($wt <= 0) fail('Укажите вес — без него цена не считается');

    // vol_source='manual' — единственный способ пустить объём к цене,
    // см. ds_create_batch_from_1688
    ob_exec("UPDATE ob_sku SET volume_m3=?, weight_kg=?, vol_source='manual' WHERE id=?",
            [$vol, $wt, $id]);

    // Карточка уже заведена — пересчитываем ей цену тем же путём, что и
    // ob_set_volume, иначе данные разъедутся
    $card = null;
    if(!empty($sku['product_id'])){
      $ds = ob_row("SELECT id FROM ds_products WHERE product_id=?", [$sku['product_id']]);
      if($ds){
        db()->prepare('UPDATE ds_products SET declared_volume_m3=?, declared_weight_kg=? WHERE id=?')
            ->execute([$vol, $wt, $ds['id']]);
        ds_sync_product_price($ds['id']);
        $q = db()->prepare('SELECT price, blocked FROM products WHERE id=?');
        $q->execute([$sku['product_id']]); $card = $q->fetch() ?: null;
      }
    }

    if(function_exists('ob_recalc_item')) ob_recalc_item($sku['num_iid']);
    itc_log_add($s['phone']??'', 'volume_set', 'ob_sku', (string)$id, 'v='.$vol.' w='.$wt);

    $msg = 'Объём ' . $vol . ' м³, вес ' . $wt . ' кг';
    if($card) $msg .= ' · цена ' . (int)$card['price'] . ' ₽'
                    . (empty($card['blocked']) ? ' — карточка открыта покупателю' : ' — карточка скрыта');
    else      $msg .= ' — цена посчитается при создании карточки';
    jout(['ok'=>true,'volume_m3'=>$vol,'weight_kg'=>$wt,'card'=>$card,'msg'=>$msg]);
  }

  case 'ob_sku_volume_bulk': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $sid=(int)($d['sku_id']??0);
    $src = $sid ? ob_row("SELECT id,num_iid,len_cm,wid_cm,hei_cm,name_ru,properties,properties_cn FROM ob_sku WHERE id=?", [$sid]) : null;
    $iid = trim((string)($d['num_iid'] ?? ''));
    if($iid==='' && $src) $iid=(string)$src['num_iid'];
    if($iid==='') fail('Не указан товар');
    $pcs = max(1,(int)($d['pcs_per_box'] ?? 1));
    $vol = (float)($d['volume_m3'] ?? 0);
    if($vol<=0 && is_array($d['boxes'] ?? null)){
      foreach($d['boxes'] as $b){
        $bl=(float)($b['l']??0); $bw=(float)($b['w']??0); $bh=(float)($b['h']??0); $bn=max(1,(int)($b['n']??1));
        if($bl>0 && $bw>0 && $bh>0) $vol += ($bl/100)*($bw/100)*($bh/100)*$bn;
      }
      if($vol>0 && $pcs>1) $vol = $vol/$pcs;
      $vol = round($vol,4);
    }
    if($vol<=0) fail('Укажите объём (м³) или габариты коробки');
    $wt = (float)($d['weight_kg'] ?? 0);
    if($wt<=0) fail('Укажите вес — без него цена не считается');

    // ВАЖНО: проставляем только в варианты ТАКОГО ЖЕ размера изделия.
    // Стол 120×60×75 и стол 120×80×75 едут в РАЗНЫХ коробках — один объём
    // на оба ставить нельзя. Сверяем размер образца (len/wid/hei из названия)
    // с каждым вариантом; порядок сторон не важен (сортируем тройку).
    $srcSig = ob_dim_sig($src);
    if($srcSig === '')
      fail('У этого варианта не распознан размер изделия — «во все того же размера» не сработает. Заполните такие вручную.');

    $cand = db()->prepare("SELECT id,len_cm,wid_cm,hei_cm,name_ru,properties,properties_cn FROM ob_sku WHERE num_iid=? AND (product_id IS NULL OR product_id='')");
    $cand->execute([$iid]);
    $ids=[];
    foreach($cand as $c){
      if(ob_dim_sig($c) === $srcSig) $ids[]=(int)$c['id'];
    }
    if(!$ids) fail('Не нашлось вариантов такого же размера без карточки');

    $in = implode(',', array_fill(0,count($ids),'?'));
    $st = db()->prepare("UPDATE ob_sku SET volume_m3=?, weight_kg=?, vol_source='manual' WHERE id IN ($in)");
    $st->execute(array_merge([$vol,$wt],$ids));
    $cnt = $st->rowCount();
    if(function_exists('ob_recalc_item')) ob_recalc_item($iid);
    $sz = ob_dim_label($src);
    itc_log_add($s['phone']??'', 'volume_bulk', 'ob_item', $iid, 'v='.$vol.' w='.$wt.' n='.$cnt.' size='.$sz);
    jout(['ok'=>true,'count'=>$cnt,'volume_m3'=>$vol,'weight_kg'=>$wt,
          'msg'=>'Проставлено в варианты размера '.$sz.' см ('.$cnt.'): '.$vol.' м³, '.$wt.' кг']);
  }

  case 'ob_ai_size': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!(function_exists('yx_ready') && yx_ready())) fail('ИИ недоступен (нет ключей Яндекса YC_API_KEY/YC_FOLDER_ID)');
    $d=body();
    $iid=trim((string)($d['num_iid']??''));
    if($iid==='') fail('Не указан товар');
    $force = !empty($d['force']); // пересчитать заново, включая уже оценённые ИИ
    $skip = $force ? ['box_props','manual','calibrated'] : ['box_props','manual','calibrated','ai'];
    $item = ob_row("SELECT num_iid,title_ru,title_cn,itc_category FROM ob_item WHERE num_iid=?", [$iid]);
    if(!$item) fail('Товар не найден');
    $title = $item['title_ru'] ?: $item['title_cn'];
    $cat = $item['itc_category'] ?? '';
    // характеристики (нужны для оценки веса по материалу/наполнению)
    $props = ob_all("SELECT name_ru,name_cn,value_ru,value_cn FROM ob_prop WHERE num_iid=? ORDER BY sort LIMIT 25", [$iid]);
    $propStr='';
    foreach($props as $p){ $n=trim((string)($p['name_ru']?:$p['name_cn'])); $v=trim((string)($p['value_ru']?:$p['value_cn'])); if($n!==''&&$v!=='') $propStr.=$n.': '.$v."\n"; }
    // варианты без точного размера — группируем по размеру изделия (один вызов на размер)
    $skus = ob_all("SELECT id,name_ru,properties,properties_cn,len_cm,wid_cm,hei_cm,vol_source FROM ob_sku WHERE num_iid=? AND (product_id IS NULL OR product_id='')", [$iid]);
    $groups=[];
    foreach($skus as $k){
      $vs=$k['vol_source']??'';
      if(in_array($vs,$skip,true)) continue; // точный размер ИЛИ (без force) уже оценён ИИ — не трогаем
      $sig = ob_dim_sig($k) ?: 'nodim';
      if(!isset($groups[$sig])) $groups[$sig]=['sample'=>$k,'ids'=>[]];
      $groups[$sig]['ids'][]=$k['id'];
    }
    if(!$groups){ jout(['ok'=>true,'done'=>0,'cards'=>0,'msg'=>'Нечего оценивать — у всех вариантов уже есть точный размер']); break; }
    $done=0; $cnt=0;
    foreach($groups as $sig=>$g){
      $est = ob_ai_estimate_size($g['sample']['name_ru'] ?? '', $cat, $propStr, $title);
      if(!$est) continue;
      $ids=$g['ids']; $in=implode(',',array_fill(0,count($ids),'?'));
      db()->prepare("UPDATE ob_sku SET volume_m3=?, weight_kg=?, vol_source='ai' WHERE id IN ($in)")
          ->execute(array_merge([$est['volume_m3'],$est['weight_kg']],$ids));
      $done++; $cnt+=count($ids);
    }
    if(!$cnt) fail('ИИ не смог оценить (пустой ответ). Попробуйте ещё раз.');
    jout(['ok'=>true,'done'=>$done,'cards'=>$cnt,'msg'=>'ИИ оценил '.$cnt.' вариантов ('.$done.' размеров)']);
  }

  case 'ds_fill_weights': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $limit = max(1, min(300, (int)($d['limit'] ?? 150)));
    $rows = db()->query("SELECT id,name,descr,cat,material,goods_cny,volume_m3 FROM products WHERE (weight_kg IS NULL OR weight_kg<=0) AND volume_m3>0 AND blocked=0 LIMIT ".$limit)->fetchAll();
    if(!$rows){ jout(['ok'=>true,'done'=>0,'remaining'=>0,'msg'=>'У всех товаров с объёмом вес уже проставлен']); break; }
    $done=0;
    foreach($rows as $r){
      $vol=(float)$r['volume_m3']; if($vol<=0) continue;
      $matTxt = !empty($r['material']) ? $r['material'] : ($r['name'].' '.$r['cat'].' '.mb_substr((string)$r['descr'],0,300));
      $dens = function_exists('ob_weight_density') ? ob_weight_density($matTxt) : 190;
      $wt = round($vol*$dens, 1);
      if($wt<=0) continue;
      $price = calc_landed_rub((float)$r['goods_cny'], $vol, $wt, get_settings(), product_via_jinjia($r['id']));
      db()->prepare("UPDATE products SET weight_kg=?, price=? WHERE id=?")->execute([$wt,$price,$r['id']]);
      try{ db()->prepare("UPDATE ds_products SET declared_weight_kg=?, our_price_rub=? WHERE product_id=?")->execute([$wt,$price,$r['id']]); }catch(Exception $e){}
      $done++;
    }
    $rem = (int)db()->query("SELECT COUNT(*) FROM products WHERE (weight_kg IS NULL OR weight_kg<=0) AND volume_m3>0 AND blocked=0")->fetchColumn();
    jout(['ok'=>true,'done'=>$done,'remaining'=>$rem,'msg'=>'Проставлен вес: '.$done.' · осталось: '.$rem]);
  }

  case 'ob_sku_volume_clear': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $id=(int)($d['sku_id']??0);
    if(!$id) fail('Не указан вариант');
    $sku=ob_row("SELECT id,num_iid,product_id FROM ob_sku WHERE id=?", [$id]);
    if(!$sku) fail('Вариант не найден');
    if(!empty($sku['product_id'])) fail('У варианта уже есть карточка — размер меняйте в карточке товара');
    ob_exec("UPDATE ob_sku SET volume_m3=0, weight_kg=0, vol_source='none' WHERE id=?", [$id]);
    if(function_exists('ob_recalc_item')) ob_recalc_item($sku['num_iid']);
    itc_log_add($s['phone']??'', 'volume_clear', 'ob_sku', (string)$id, '');
    jout(['ok'=>true]);
  }

  case 'ds_gen_tags_missing': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $aiOk = (function_exists('yx_ready') && yx_ready()) || (defined('DEEPSEEK_API_KEY') && DEEPSEEK_API_KEY);
    if(!function_exists('ds_gen_search_tags') || !$aiOk) fail('ИИ недоступен: не настроен ни Яндекс (YC_API_KEY/YC_FOLDER_ID), ни DeepSeek');
    $d=body();
    $limit = max(1, min(8, (int)($d['limit'] ?? 5)));
    $rows = db()->query("SELECT id,name,descr,cat FROM products WHERE (search_tags IS NULL OR search_tags='') AND blocked=0 ORDER BY created_at DESC")->fetchAll();
    if(!count($rows)){ jout(['ok'=>true,'done'=>0,'cards'=>0,'remaining'=>0,'msg'=>'Все карточки уже с поисковыми словами']); break; }
    // Группируем по базовому названию (до « · ») — один вызов ИИ на товар
    $groups=[];
    foreach($rows as $r){ $base=trim(explode(' · ', (string)$r['name'])[0]); if(!isset($groups[$base])) $groups[$base]=['sample'=>$r,'ids'=>[]]; $groups[$base]['ids'][]=$r['id']; }
    $done=0; $cardsDone=0; $i=0;
    foreach($groups as $base=>$g){
      if($i++ >= $limit) break;
      $tags = ds_gen_search_tags($g['sample']['name'], $g['sample']['descr'] ?? '', $g['sample']['cat'] ?? '');
      if($tags==='') continue;
      $ids=$g['ids']; $in=implode(',',array_fill(0,count($ids),'?'));
      db()->prepare("UPDATE products SET search_tags=? WHERE id IN ($in)")->execute(array_merge([$tags],$ids));
      $done++; $cardsDone+=count($ids);
    }
    $rem = (int)db()->query("SELECT COUNT(*) FROM products WHERE (search_tags IS NULL OR search_tags='') AND blocked=0")->fetchColumn();
    jout(['ok'=>true,'done'=>$done,'cards'=>$cardsDone,'remaining'=>$rem,
          'msg'=>'Слова созданы для '.$cardsDone.' карточек · осталось товаров: '.$rem]);
  }

  // ---- Разложить замер на остальные варианты ----
  // У стеллажа 350 вариантов разного размера. Одну цифру на всех ставить
  // нельзя — это ошибка ds_kd_rules. Вбить 350 раз невозможно. Берём один
  // настоящий замер и раскладываем по габаритам из названий.
  case 'ob_calibrate': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!function_exists('ob_calibrate_from')) fail('ob_1688.php устарел — обновите файл');
    $d=body();
    $id = (int)($d['sku_id'] ?? 0);
    if(!$id) fail('Не указан вариант-образец');
    $r = ob_calibrate_from($id);
    if(!empty($r['error'])) fail($r['error']);

    $sku = ob_row("SELECT num_iid FROM ob_sku WHERE id=?", [$id]);
    if($sku && function_exists('ob_recalc_item')) ob_recalc_item($sku['num_iid']);

    $r['ok']  = true;
    $r['msg'] = 'Коэффициент упаковки ' . $r['factor'] . ' · пересчитано вариантов: '
              . $r['applied'] . ($r['skipped'] ? ', пропущено ' . $r['skipped'] : '');
    itc_log_add($s['phone']??'', 'calibrate', 'ob_sku', (string)$id, 'f='.$r['factor']);
    jout($r);
  }

  // ---- Отметить варианты галочками ----
  case 'ob_sku_select': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $iid = trim($d['num_iid'] ?? '');
    if(!$iid) fail('Не указан num_iid');

    // mode: set  — отметить ровно указанные (ids), остальные снять
    //       add  — добавить к отмеченным
    //       all  — отметить все
    //       none — снять все
    //       suggested — отметить только рекомендованные
    $mode = $d['mode'] ?? 'set';
    $ids  = is_array($d['ids'] ?? null) ? array_map('intval', $d['ids']) : [];

    if($mode === 'all'){
      ob_exec("UPDATE ob_sku SET selected=1 WHERE num_iid=? AND product_id IS NULL", [$iid]);
    } elseif($mode === 'none'){
      ob_exec("UPDATE ob_sku SET selected=0 WHERE num_iid=? AND product_id IS NULL", [$iid]);
    } elseif($mode === 'suggested'){
      ob_exec("UPDATE ob_sku SET selected=suggest WHERE num_iid=? AND product_id IS NULL", [$iid]);
    } elseif($mode === 'add'){
      if(!$ids) fail('Не указаны ids');
      $in = implode(',', array_fill(0, count($ids), '?'));
      ob_exec("UPDATE ob_sku SET selected=1 WHERE num_iid=? AND id IN ($in)",
              array_merge([$iid], $ids));
    } else {
      ob_exec("UPDATE ob_sku SET selected=0 WHERE num_iid=?", [$iid]);
      if($ids){
        $in = implode(',', array_fill(0, count($ids), '?'));
        ob_exec("UPDATE ob_sku SET selected=1 WHERE num_iid=? AND id IN ($in)",
                array_merge([$iid], $ids));
      }
    }

    $cnt = ob_row("SELECT COUNT(*) c FROM ob_sku WHERE num_iid=? AND selected=1", [$iid]);
    jout(['ok'=>true,'num_iid'=>$iid,'selected'=>(int)($cnt['c'] ?? 0),
          'msg'=>'Отмечено вариантов: ' . (int)($cnt['c'] ?? 0)]);
  }

  // =====================================================================
  //  АВТО-ДРОПШИППИНГ 1688
  //  Идея: ищем НЕ по произвольному слову, а по китайскому шаблону из
  //  ds_kd_rules(). Тогда найденное гарантированно попадает в ту же
  //  категорию — вес и объём известны сразу, очередь «уточнить объём»
  //  почти не наполняется.
  // =====================================================================

  // ---- Дерево категорий 1688: подтянуть уровень ----
  // cat_get отдаёт детей по cid. cid=0 — корень.
  // ВНИМАНИЕ: в ответе onebound ОПЕЧАТКА — «itmes»/«itme», а не «items»/«item».
  case 'ob_cat_sync': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $cid = (string)($d['cid'] ?? '0');

    $r = ob_call('cat_get', ['cid'=>$cid], ['cache'=>'yes']);
    if(empty($r['ok'])) jout(['ok'=>false,'error'=>$r['reason_ru'] ?? $r['reason'] ?? 'Ошибка',
                              'error_code'=>$r['error_code'] ?? null]);

    // КАК МЫ ЗДЕСЬ 11 РАЗ ЗАПЛАТИЛИ ЗА «ПУСТО»:
    //   cid=0  -> items > item   (нормально)
    //   cid=13 -> items > itme   (обёртка верная, вложенный ключ с опечаткой)
    // Цепочка ?? доходила до $d0['items'], забирала ОБЁРТКУ ['itme'=>[...]],
    // признавала её непустой — и запасной разбор ниже уже не запускался,
    // потому что стоял под «если пусто». Цикл искал id в обёртке, не находил
    // и писал «подкатегорий нет». Лог при этом показывал 0000 и billable=1:
    // 1688 отвечал полными данными, мы их выбрасывали.
    // Поэтому имена ключей больше не угадываем — ищем по ФОРМЕ.
    $d0   = $r['data'] ?? [];
    // Корень отдаёт список категорий. Ветка отдаёт саму себя, а детей прячет
    // в поле sub — это и есть весь второй уровень, за который мы платили
    // одиннадцать раз, получали его целиком и выбрасывали.
    if ((string)$cid === '0') {
      $list = ob_find_cat_list($d0);
    } else {
      $self = ob_cat_node_by_id($d0, $cid);
      $list = $self ? ob_cat_sub_list($self) : null;
      if (!$list) {   // вдруг ответят списком, как корень
        $l2 = ob_find_cat_list($d0);
        if ($l2) { $list = []; foreach ($l2 as $c) if ((string)($c['id'] ?? '') !== (string)$cid) $list[] = $c; }
      }
    }
    if(!is_array($list) || !$list){
      // Пусто — но пусто ли ВПРАВДУ? «Подкатегорий нет» и «мы не разобрали
      // формат» на экране неразличимы. Отдаём разбор ответа: имена ключей,
      // тип и размер каждого, первый элемент — по ним видно, что пришло.
      $sample = [];
      foreach(array_slice($d0, 0, 8, true) as $k=>$v){
        if(is_scalar($v) || $v===null){ $sample[$k] = $v; continue; }
        if(is_array($v)){
          $first = reset($v);
          $sample[$k] = ['ТИП'=>'массив', 'ЭЛЕМЕНТОВ'=>count($v),
                         'КЛЮЧИ'=>array_slice(array_keys($v), 0, 8),
                         'ПЕРВЫЙ'=>is_array($first) ? array_slice($first, 0, 6, true) : $first];
          continue;
        }
        $sample[$k] = gettype($v);
      }

      // И в БАЗУ. Ответ живёт только в момент запроса: не записав, мы каждый
      // раз платим за вызов заново, чтобы посмотреть то же самое. Смотреть:
      //   SELECT * FROM itc_log WHERE action='ob_cat_empty' ORDER BY id DESC;
      try {
        itc_log_add(current_staff_id($s), 'ob_cat_empty', 'ob_cat', $cid,
          mb_substr('код '.($r['error_code'] ?? '?').' | ключи: '.implode(', ', array_keys($d0)).
                    ' | '.json_encode($sample, JSON_UNESCAPED_UNICODE), 0, 900));
      } catch (Exception $e) {}

      jout(['ok'=>true,'cid'=>$cid,'added'=>0,'msg'=>'Подкатегорий нет',
            'code'=>$r['error_code'] ?? '', 'reason'=>$r['reason'] ?? '',
            'raw'=>array_keys($d0), 'sample'=>ob_shape($d0)]);
    }

    // Путь родителя — чтобы строить «家具 > 客厅家具 > 沙发»
    $parent = $cid !== '0' ? ob_row("SELECT name_cn,path_cn,level FROM ob_cat WHERE id=?", [$cid]) : null;
    $ppath  = $parent ? ($parent['path_cn'] ?: $parent['name_cn']) : '';
    $plevel = $parent ? (int)$parent['level'] : -1;

    $n=0; $self_skipped=0;
    ob_cat_save_tree($list, $cid==='0' ? 0 : $cid, $ppath, $plevel, $n);
    if($cid !== '0')
      ob_exec("UPDATE ob_cat SET kids_synced=1, has_kids=? WHERE id=?", [$n>0?1:0, $cid]);

    // ---- Русские имена: сразу, пока ветка свежая ----
    // Почему не lang=ru у onebound: их перевод класса D — ПЛАТНЫЙ, отдельным
    // вызовом за каждую ветку. Поэтому lang держим 'cn' (так в config.php) и
    // переводим сами — Яндекс вызовов 1688 не тратит.
    $tr = 0;
    if($n && function_exists('ob_cat_names_ru')){
      $need = ob_all("SELECT id,name_cn FROM ob_cat
                       WHERE pid=? AND name_cn<>'' AND (name_ru IS NULL OR name_ru='')",
                     [$cid==='0' ? 0 : $cid]);
      if($need){
        $ru = ob_cat_names_ru(array_column($need,'name_cn'));
        // Пусто = переводчик не отозвался. Не беда: ветка уже в базе,
        // перевод догонит кнопкой «Перевести имена» — без вызовов 1688.
        foreach($need as $i=>$row){
          $v = trim((string)($ru[$i] ?? ''));
          if($v==='' || $v===$row['name_cn']) continue;
          ob_exec("UPDATE ob_cat SET name_ru=? WHERE id=?", [$v, $row['id']]);
          $tr++;
        }
      }
    }

    jout(['ok'=>true,'cid'=>$cid,'added'=>$n,'translated'=>$tr,
          'self_skipped'=>$self_skipped,
          'cost_cny'=>$r['cost_cny'] ?? 0,
          // Сырой ответ отдаём ВСЕГДА. «added=1» выглядело успехом, а на деле
          // это была сама категория, записанная поверх себя.
          'raw'=>array_keys($d0), 'shape'=>ob_shape($d0),
          'msg'=>"Категорий подтянуто: $n".($tr? " · переведено: $tr" : "").
                 ($self_skipped? " · сама себя пропущена" : "")]);
  }

  // ---- Дерево категорий: показать уровень ----
  case 'ob_cat_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager','moderator']);
    $pid = (string)($_GET['pid'] ?? '0');

    // ОПИСАНИЕ КАТЕГОРИИ НЕ СОЧИНЯЕМ — оно уже есть в дереве.
    // «Что внутри» = перечисление подкатегорий. Это правда по построению
    // (не пересказ модели), стоит ноль вызовов и не устаревает.
    // SUBSTRING_INDEX режет до 6 имён: строка в списке, а не простыня.
    $rows = ob_all("SELECT c.id,c.pid,c.level,c.name_cn,c.name_ru,c.path_cn,c.has_kids,c.kids_synced,
                           c.itc_cat,c.itc_subcat,c.enabled,c.def_weight_kg,c.def_volume_m3,
                           c.def_note,c.imported,
                           (SELECT COUNT(*) FROM ob_cat k WHERE k.pid=c.id) AS kids,
                           (SELECT SUBSTRING_INDEX(
                                     GROUP_CONCAT(COALESCE(NULLIF(k.name_ru,''), k.name_cn)
                                                  ORDER BY (k.name_ru IS NULL OR k.name_ru='') ASC,
                                                           k.name_cn ASC
                                                  SEPARATOR ' · '),
                                     ' · ', 6)
                              FROM ob_cat k WHERE k.pid=c.id) AS inside
                      FROM ob_cat c WHERE c.pid=? ORDER BY c.name_cn", [$pid]);

    // Где мы находимся — для «хлебных крошек» и кнопки «наверх»
    $self = $pid !== '0'
      ? ob_row("SELECT id,pid,level,name_cn,name_ru,path_cn,kids_synced FROM ob_cat WHERE id=?", [$pid])
      : null;

    $total = ob_row("SELECT COUNT(*) c, SUM(enabled) e FROM ob_cat");
    jout(['ok'=>true,'pid'=>$pid,'items'=>$rows,'self'=>$self,
          'total'=>(int)($total['c'] ?? 0),'enabled'=>(int)($total['e'] ?? 0)]);
  }

  // ---- Перевести имена категорий (БЕЗ вызовов onebound) ----
  // Отдельно от ob_cat_sync намеренно: если перевод не догнал при загрузке
  // ветки, тянуть её заново ради имён — значит платить за то, что уже лежит
  // в базе. Здесь работаем только с тем, что уже скачано.
  case 'ob_cat_translate': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);

    // Не гадаем, почему не перевелось — проверяем и называем причину.
    if(!function_exists('yx_ready') || !function_exists('yx_gpt'))
      fail('ob_yandex.php не подключён: файла нет в папке api/ (он включается через @include_once — молча, без ошибки)');
    if(!yx_ready())
      fail('Ключи Яндекса не заданы: YC_API_KEY и YC_FOLDER_ID в api/config.php');

    $d=body();
    // 100 за раз = 4 запроса к GPT. Больше — рискуем таймаутом веб-запроса.
    $lim = min(200, max(1, (int)($d['limit'] ?? 100)));
    $need = ob_all("SELECT id,name_cn FROM ob_cat
                     WHERE name_cn<>'' AND (name_ru IS NULL OR name_ru='')
                     ORDER BY level, name_cn LIMIT $lim");
    if(!$need) jout(['ok'=>true,'translated'=>0,'left'=>0,'msg'=>'Все имена уже переведены']);

    $ru = ob_cat_names_ru(array_column($need,'name_cn'));

    $tr=0;
    foreach($need as $i=>$row){
      $v = trim((string)($ru[$i] ?? ''));
      if($v==='' || $v===$row['name_cn']) continue;
      ob_exec("UPDATE ob_cat SET name_ru=? WHERE id=?", [$v, $row['id']]);
      $tr++;
    }

    // Ни одного имени — молчать нельзя, иначе кнопка «сработала» вхолостую
    if(!$tr)
      fail('Ни одного имени перевести не вышло. Оба движка Яндекса молчат — '.
           'нажмите «Проверить перевод», там видно, какой именно.');

    $left = (int)(ob_row("SELECT COUNT(*) c FROM ob_cat
                           WHERE name_cn<>'' AND (name_ru IS NULL OR name_ru='')")['c'] ?? 0);
    jout(['ok'=>true,'translated'=>$tr,'left'=>$left,
          'msg'=>"Переведено: $tr".($left? " · осталось $left — нажмите ещё раз" : '')]);
  }

  // ---- Сырой ответ cat_get: посмотреть глазами, ничего не сохраняя ----
  // Понадобилось, когда 1688 отвечал кодом 0000 (успех, деньги списаны), а
  // подкатегорий не появлялось. Лог показывает только код, ob_raw хранит
  // лишь item_get — увидеть сам ответ было негде. Теперь есть где.
  case 'ob_cat_raw': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $cid = (string)($_GET['cid'] ?? '0');
    $r = ob_call('cat_get', ['cid'=>$cid], ['cache'=>'yes']);
    jout(['ok'=>true,'cid'=>$cid,
          'code'=>$r['error_code'] ?? '',
          'reason'=>$r['reason'] ?? '',
          'cached'=>!empty($r['data']['cache']) ? 1 : 0,
          'cost_cny'=>$r['cost_cny'] ?? 0,
          'len'=>strlen((string)($r['raw'] ?? '')),
          'raw'=>mb_substr((string)($r['raw'] ?? ''), 0, 4000)]);
  }

  // ---- Найти категорию по слову (по СВОЕЙ базе, без вызовов 1688) ----
  // «Открыл текстиль, а нужен шкаф» — без поиска по дереву единственный
  // способ найти ветку это угадывать, какую из 48 рубрик раскрывать.
  case 'ob_cat_search': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager','moderator']);
    $q = trim($_GET['q'] ?? '');
    if($q==='') fail('Задайте слово');
    $like = '%'.$q.'%';
    $rows = ob_all("SELECT c.id,c.pid,c.level,c.name_cn,c.name_ru,c.path_cn,
                           c.kids_synced,c.enabled,
                           (SELECT COUNT(*) FROM ob_cat k WHERE k.pid=c.id) AS kids,
                           (SELECT COALESCE(NULLIF(p.name_ru,''),p.name_cn)
                              FROM ob_cat p WHERE p.id=c.pid) AS parent_name
                      FROM ob_cat c
                     WHERE c.name_ru LIKE ? OR c.name_cn LIKE ?
                     ORDER BY c.level, c.name_ru LIMIT 60", [$like,$like]);
    $total = (int)(ob_row("SELECT COUNT(*) c FROM ob_cat")['c'] ?? 0);
    jout(['ok'=>true,'q'=>$q,'items'=>$rows,'found'=>count($rows),'total'=>$total]);
  }

  // ---- Настройка категории: наша группа, замеры, разрешение ----
  case 'ob_cat_save': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $id = (string)($d['id'] ?? '');
    if(!$id) fail('Не указана категория');

    $f=[]; $v=[];
    foreach(['name_ru','itc_cat','itc_subcat','def_note'] as $k)
      if(array_key_exists($k,$d)){ $f[]="$k=?"; $v[]=trim((string)$d[$k]) ?: null; }
    foreach(['def_weight_kg','def_volume_m3'] as $k)
      if(array_key_exists($k,$d)){ $f[]="$k=?"; $v[]=(float)$d[$k] ?: null; }
    if(array_key_exists('enabled',$d)){ $f[]="enabled=?"; $v[]=!empty($d['enabled'])?1:0; }
    if(!$f) fail('Нечего сохранять');

    $v[]=$id;
    ob_exec("UPDATE ob_cat SET ".implode(',',$f).", updated_at=NOW() WHERE id=?", $v);
    jout(['ok'=>true,'id'=>$id,'msg'=>'Сохранено']);
  }

  // ---- Категории, разрешённые для переливки ----
  case 'ob_cat_enabled': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $rows = ob_all("SELECT id,name_cn,name_ru,path_cn,itc_cat,itc_subcat,
                           def_weight_kg,def_volume_m3,def_note,imported
                      FROM ob_cat WHERE enabled=1 ORDER BY itc_cat, name_cn");
    jout(['ok'=>true,'items'=>$rows,'count'=>count($rows)]);
  }

  // ---- Поиск на 1688 (сухой прогон: ничего не создаём) ----
  // ===== ПОИСК 1688: избранное, папки, история (собственная база поставщиков) =====
  case 'obf_ensure': case 'obf_hist_add': case 'obf_hist_list': case 'obf_qtr':
  case 'obf_fav_toggle': case 'obf_fav_list': case 'obf_fav_move': case 'obf_fav_note': case 'obf_fav_del':
  case 'obf_folder_add': case 'obf_folder_ren': case 'obf_folder_del': case 'obf_state': {
    $s = authUser('itc'); $ph = $s['phone'] ?? '';
    // авто-создание таблиц — чтобы Алексею не запускать SQL руками
    try {
      db()->query("CREATE TABLE IF NOT EXISTS obf_folder (id INT AUTO_INCREMENT PRIMARY KEY, phone VARCHAR(32), name VARCHAR(120), parent_id INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) DEFAULT CHARSET=utf8mb4");
      db()->query("CREATE TABLE IF NOT EXISTS obf_fav (id INT AUTO_INCREMENT PRIMARY KEY, phone VARCHAR(32), num_iid VARCHAR(40), title TEXT, title_ru TEXT, price VARCHAR(40), img TEXT, url TEXT, seller VARCHAR(200), folder_id INT DEFAULT 0, note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_fav (phone, num_iid)) DEFAULT CHARSET=utf8mb4");
      db()->query("CREATE TABLE IF NOT EXISTS obf_hist (id INT AUTO_INCREMENT PRIMARY KEY, phone VARCHAR(32), q VARCHAR(200), cnt INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) DEFAULT CHARSET=utf8mb4");
    } catch (Exception $e) {}
    $d = body();

    if ($action === 'obf_ensure') { jout(['ok'=>true]); }

    if ($action === 'obf_qtr') {
      $q = trim($d['q'] ?? ''); $to = ($d['to'] ?? 'en') === 'zh' ? 'zh' : 'en';
      $pair = ($to === 'zh') ? 'ru|zh-CN' : 'ru|en';
      $out = $q;
      if ($q !== '') {
        $q = mb_substr($q, 0, 200);
        $url = 'https://api.mymemory.translated.net/get?q='.urlencode($q).'&langpair='.$pair;
        $ch = curl_init($url);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>8, CURLOPT_SSL_VERIFYPEER=>false, CURLOPT_USERAGENT=>'ITC/1.0']);
        $res = curl_exec($ch); curl_close($ch);
        if ($res) { $j = json_decode($res, true); $t = $j['responseData']['translatedText'] ?? ''; if (trim($t) !== '' && ($j['responseStatus'] ?? 0) == 200) $out = $t; }
      }
      jout(['ok'=>true, 'q'=>$q, 'to'=>$to, 'translated'=>$out]);
    }

    if ($action === 'obf_hist_add') {
      $q = mb_substr(trim($d['q'] ?? ''), 0, 200); $cnt = (int)($d['cnt'] ?? 0);
      if ($q !== '') { try { db()->prepare("INSERT INTO obf_hist (phone,q,cnt) VALUES (?,?,?)")->execute([$ph,$q,$cnt]); } catch(Exception $e){} }
      jout(['ok'=>true]);
    }
    if ($action === 'obf_hist_list') {
      $rows = []; try { $st=db()->prepare("SELECT q, MAX(cnt) cnt, MAX(created_at) ts, DATE(created_at) d FROM obf_hist WHERE phone=? GROUP BY q, DATE(created_at) ORDER BY ts DESC LIMIT 200"); $st->execute([$ph]); $rows=$st->fetchAll(); } catch(Exception $e){}
      jout(['ok'=>true,'history'=>$rows]);
    }

    if ($action === 'obf_folder_add') {
      $name = mb_substr(trim($d['name'] ?? ''), 0, 120); $parent=(int)($d['parent_id'] ?? 0);
      if ($name==='') fail('Введите название папки');
      db()->prepare("INSERT INTO obf_folder (phone,name,parent_id) VALUES (?,?,?)")->execute([$ph,$name,$parent]);
      jout(['ok'=>true,'id'=>db()->lastInsertId()]);
    }
    if ($action === 'obf_folder_ren') {
      $id=(int)($d['id']??0); $name=mb_substr(trim($d['name'] ?? ''),0,120);
      if($id&&$name!=='') db()->prepare("UPDATE obf_folder SET name=? WHERE id=? AND phone=?")->execute([$name,$id,$ph]);
      jout(['ok'=>true]);
    }
    if ($action === 'obf_folder_del') {
      $id=(int)($d['id']??0);
      if($id){ try{ db()->prepare("UPDATE obf_fav SET folder_id=0 WHERE folder_id=? AND phone=?")->execute([$id,$ph]); db()->prepare("UPDATE obf_folder SET parent_id=0 WHERE parent_id=? AND phone=?")->execute([$id,$ph]); db()->prepare("DELETE FROM obf_folder WHERE id=? AND phone=?")->execute([$id,$ph]); }catch(Exception $e){} }
      jout(['ok'=>true]);
    }

    if ($action === 'obf_fav_toggle') {
      $iid = trim($d['num_iid'] ?? ''); if($iid==='') fail('Нет товара');
      $ex = null; try { $st=db()->prepare("SELECT id FROM obf_fav WHERE phone=? AND num_iid=?"); $st->execute([$ph,$iid]); $ex=$st->fetchColumn(); } catch(Exception $e){}
      if ($ex) { db()->prepare("DELETE FROM obf_fav WHERE id=?")->execute([$ex]); jout(['ok'=>true,'saved'=>false]); }
      else {
        db()->prepare("INSERT INTO obf_fav (phone,num_iid,title,title_ru,price,img,url,seller,folder_id) VALUES (?,?,?,?,?,?,?,?,?)")
          ->execute([$ph,$iid,mb_substr($d['title']??'',0,500),mb_substr($d['title_ru']??'',0,500),mb_substr($d['price']??'',0,40),$d['img']??'',$d['url']??'',mb_substr($d['seller']??'',0,200),(int)($d['folder_id']??0)]);
        jout(['ok'=>true,'saved'=>true]);
      }
    }
    if ($action === 'obf_fav_move') {
      $iid=trim($d['num_iid']??''); $fid=(int)($d['folder_id']??0);
      if($iid!=='') db()->prepare("UPDATE obf_fav SET folder_id=? WHERE phone=? AND num_iid=?")->execute([$fid,$ph,$iid]);
      jout(['ok'=>true]);
    }
    if ($action === 'obf_fav_note') {
      $iid=trim($d['num_iid']??''); $note=mb_substr($d['note']??'',0,1000);
      if($iid!=='') db()->prepare("UPDATE obf_fav SET note=? WHERE phone=? AND num_iid=?")->execute([$note,$ph,$iid]);
      jout(['ok'=>true]);
    }
    if ($action === 'obf_fav_del') {
      $iid=trim($d['num_iid']??'');
      if($iid!=='') db()->prepare("DELETE FROM obf_fav WHERE phone=? AND num_iid=?")->execute([$ph,$iid]);
      jout(['ok'=>true]);
    }

    // Полное состояние: папки + избранное + счётчики (для экрана)
    if ($action === 'obf_state' || $action === 'obf_fav_list') {
      $folders=[]; try{ $st=db()->prepare("SELECT id,name,parent_id FROM obf_folder WHERE phone=? ORDER BY name"); $st->execute([$ph]); $folders=$st->fetchAll(); }catch(Exception $e){}
      $fid = isset($d['folder_id']) ? (int)$d['folder_id'] : -1; // -1 = все
      $favs=[]; try {
        if($fid>=0){ $st=db()->prepare("SELECT num_iid,title,title_ru,price,img,url,seller,folder_id,note,UNIX_TIMESTAMP(created_at)*1000 ts FROM obf_fav WHERE phone=? AND folder_id=? ORDER BY id DESC"); $st->execute([$ph,$fid]); }
        else { $st=db()->prepare("SELECT num_iid,title,title_ru,price,img,url,seller,folder_id,note,UNIX_TIMESTAMP(created_at)*1000 ts FROM obf_fav WHERE phone=? ORDER BY id DESC"); $st->execute([$ph]); }
        $favs=$st->fetchAll();
      } catch(Exception $e){}
      // счётчики по папкам
      $counts=[]; try{ $st=db()->prepare("SELECT folder_id, COUNT(*) c FROM obf_fav WHERE phone=? GROUP BY folder_id"); $st->execute([$ph]); foreach($st->fetchAll() as $r) $counts[(int)$r['folder_id']]=(int)$r['c']; }catch(Exception $e){}
      $favIds=[]; try{ $st=db()->prepare("SELECT num_iid FROM obf_fav WHERE phone=?"); $st->execute([$ph]); foreach($st->fetchAll() as $r) $favIds[]=$r['num_iid']; }catch(Exception $e){}
      jout(['ok'=>true,'folders'=>$folders,'favs'=>$favs,'counts'=>$counts,'fav_ids'=>$favIds]);
    }
    jout(['ok'=>true]);
  }

  case 'ob_auto_search': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $GLOBALS['OB_CREATED_BY'] = $s['phone'] ?? '';
    $d=body();
    $cat_id = (string)($d['cat_id'] ?? '');     // категория 1688 — основной путь
    $q      = trim($d['q'] ?? '');              // слово — запасной
    $want   = min(200, max(1, (int)($d['count'] ?? 20)));
    $page   = max(1, (int)($d['page'] ?? 1));

    // Ищем по КАТЕГОРИИ 1688: её имя — точный термин площадки,
    // а не наша догадка регуляркой по SEO-каше в заголовке.
    $cat = null;
    if($cat_id !== ''){
      $cat = ob_row("SELECT id,name_cn,name_ru,path_cn,itc_cat,def_weight_kg,def_volume_m3
                       FROM ob_cat WHERE id=?", [$cat_id]);
      if(!$cat) fail('Категория не найдена');
      if($q === '') $q = $cat['name_cn'];
    }
    if($q==='') fail('Выберите категорию или задайте слово');

    $found=[]; $dups=0; $calls=0; $diag=[]; $warn='';
    $pages = (int)ceil($want / 20);
    for($pg=$page; $pg < $page+$pages; $pg++){
      $sp = ['q'=>$q, 'page'=>$pg];
      // Параметр cat НЕ ШЛЁМ. Стоял с комментарием «если площадка примет —
      // сузит выдачу». Не приняла: item_search на него отвечает кодом 5000
      // «data error» со ссылкой на свою документацию, и выдача рушится
      // целиком. Тот же запрос без cat работает. Сужаем иначе — ищем по
      // китайскому имени категории: это термин самой площадки.
      $r = ob_call('item_search', $sp, ['cache'=>'yes']);
      $calls++;

      // Что РЕАЛЬНО пришло. Без этого «ничего не нашлось» неотличимо от
      // ошибки, от сбитого имени ключа и от пустой выдачи по рубрике.
      $d0 = is_array($r['data'] ?? null) ? $r['data'] : [];

      // У onebound в cat_get обнаружилась опечатка «itmes»/«itme».
      // Здесь читаем оба написания — тот же поставщик, та же вероятность.
      $items = $d0['items']['item']
            ?? $d0['itmes']['itme']
            ?? $d0['items']
            ?? $d0['itmes'] ?? [];
      if(is_array($items) && isset($items['num_iid'])) $items = [$items];
      $cnt = is_array($items) ? count($items) : 0;

      $diag[] = ['page'=>$pg, 'code'=>$r['error_code'] ?? '',
                 'reason'=>mb_substr((string)($r['reason'] ?? ''), 0, 200),
                 'items'=>$cnt, 'keys'=>array_keys($d0)];

      if(empty($r['ok'])){
        // Код ошибки, но товары в ответе есть — берём их. Выбросить молча
        // нельзя: за вызов уже заплачено, а данные пришли.
        if($cnt){ $warn = ($r['error_code'] ?? '').' '.($r['reason'] ?? ''); }
        else {
          if(!$found)
            // reason — то, что сказал САМ onebound. reason_ru — наша
            // расшифровка кода по таблице, она есть всегда и потому
            // раньше затирала настоящий текст.
            jout(['ok'=>false,
                  'error'=>trim((string)($r['reason'] ?? '')) ?: ($r['reason_ru'] ?? 'Ошибка поиска'),
                  'error_ru'=>$r['reason_ru'] ?? '',
                  'error_code'=>$r['error_code'] ?? null,
                  'q'=>$q,'cat_sent'=>$cat_id,'api_calls'=>$calls,'diag'=>$diag]);
          break;
        }
      }
      if(!is_array($items) || !$items) break;

      foreach($items as $it){
        if(count($found) >= $want) break 2;
        $iid = (string)($it['num_iid'] ?? '');
        if($iid==='') continue;
        $url = 'https://detail.1688.com/offer/'.$iid.'.html';

        // ОТСЕВ ДУБЛЕЙ — ds_find_duplicate уже умеет 1688 (ds_source_key)
        $dup = ds_find_duplicate($url, '1688');
        if($dup){ $dups++; continue; }
        // и то, что уже лежит в ob_item
        $have = ob_row("SELECT product_id FROM ob_item WHERE num_iid=? AND product_id IS NOT NULL", [$iid]);
        if($have){ $dups++; continue; }

        $found[] = [
          'num_iid' => $iid,
          'title'   => $it['title'] ?? '',
          'price'   => $it['price'] ?? null,
          'img'     => ob_fix_url($it['pic_url'] ?? ($it['pic'] ?? '')),
          'url'     => $url,
          'seller'  => $it['seller_nick'] ?? ($it['nick'] ?? ''),
        ];
      }
    }

    // Названия по-русски: менеджер выбирает глазами, а не расшифровывает
    // иероглифы. Переводим ПОСЛЕ отсева дублей — незачем возиться с тем, что
    // и так не покажем. Идёт через Яндекс: вызовы 1688 не тратятся.
    if($found && function_exists('ob_item_names_ru')){
      $ru = ob_item_names_ru(array_column($found,'title'));
      foreach($found as $i=>$row){
        $v = trim((string)($ru[$i] ?? ''));
        if($v!=='') $found[$i]['title_ru'] = $v;
      }
    }

    jout(['ok'=>true,'q'=>$q,'cat'=>$cat,'cat_sent'=>$cat_id,'found'=>count($found),
          'duplicates_skipped'=>$dups,'diag'=>$diag,'warn'=>trim($warn),
          'api_calls'=>$calls,'cost_cny'=>round($calls*0.022,3),'items'=>$found,
          'msg'=>'Найдено новых: '.count($found).($dups? ' · дублей пропущено: '.$dups : '')]);
  }

  // ---- Залить пачку: item_get + карточки по ВСЕМ вариантам ----
  // Вызывать порциями: фронтенд шлёт по 3-5 номеров и рисует прогресс,
  // иначе веб-запрос отвалится по таймауту.
  case 'ob_auto_import': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $GLOBALS['OB_CREATED_BY'] = $s['phone'] ?? '';
    $d=body();
    $ids = is_array($d['num_iids'] ?? null) ? $d['num_iids'] : [];
    if(!$ids) fail('Не переданы num_iids');
    if(count($ids) > 5) fail('Не больше 5 за раз — иначе таймаут');

    $toMod  = !empty($d['to_moderation']);
    $doPhoto= !isset($d['photos']) || !empty($d['photos']);
    $mgr    = trim($d['manager_id'] ?? '');
    $cat_id = (string)($d['cat_id'] ?? '');

    // Замеры менеджера по этой категории 1688. Если их нет — объём НЕ выдумываем,
    // карточка уйдёт в очередь «уточнить у фабрики». Так решил Алексей:
    // ds_kd_rules угадывает неверно, правду даёт только фабрика.
    $catRow = $cat_id !== ''
      ? ob_row("SELECT id,name_cn,name_ru,itc_cat,itc_subcat,def_weight_kg,def_volume_m3
                  FROM ob_cat WHERE id=?", [$cat_id])
      : null;
    $catVol = $catRow ? (float)($catRow['def_volume_m3'] ?? 0) : 0;
    $catWt  = $catRow ? (float)($catRow['def_weight_kg'] ?? 0) : 0;
    $catOur = $catRow ? trim((string)($catRow['itc_cat'] ?? '')) : '';

    $res=[]; $cards=0; $cost=0;
    foreach($ids as $iid){
      $iid = preg_replace('/\D/','',(string)$iid);
      if($iid==='') continue;
      $url = 'https://detail.1688.com/offer/'.$iid.'.html';

      // 1. Тянем товар
      $imp = ob_import($url, []);
      $cost += (float)($imp['cost_cny'] ?? 0);
      if(empty($imp['ok'])){
        $res[] = ['num_iid'=>$iid,'ok'=>false,'error'=>$imp['error'] ?? 'ошибка загрузки'];
        continue;
      }
      $p = $imp['parsed'];

      // 2. Отмечаем ВСЕ варианты — Алексей: показываем полный ассортимент
      ob_exec("UPDATE ob_sku SET selected=1 WHERE num_iid=? AND product_id IS NULL", [$iid]);

      // 3. Название: русское если переведено, иначе китайское (переведём позже)
      $base = trim((string)($p['title_ru'] ?? '')) ?: $p['title_cn'];

      // 4. Создаём карточки по всем вариантам
      if($cat_id !== '') ob_exec("UPDATE ob_item SET cat_id_1688=? WHERE num_iid=?", [$cat_id, $iid]);

      $picked = ob_all("SELECT * FROM ob_sku WHERE num_iid=? AND selected=1 AND product_id IS NULL ORDER BY id", [$iid]);
      $made = 0; $wait = 0;
      foreach($picked as $sku){
        $pcny = (float)($sku['price_cny'] ?? 0);
        if($pcny <= 0) continue;

        // ОБЪЁМ И ВЕС: только замеры менеджера по категории 1688.
        // Догадки ds_kd_rules НЕ используем — они дали 0.09 м3 вместо 0.016
        // на обувнице, цена вышла 4414 ₽ вместо ~700.
        $dvol = $catVol;
        $dwt  = $catWt;
        if($dvol <= 0) $wait++;

        $nm = trim((string)($sku['name_ru'] ?: $sku['properties_cn']));
        if($nm !== '' && function_exists('ob_sku_clean_name') && preg_match('/^\d+:\d+:/', $nm))
          $nm = ob_sku_clean_name($nm);
        $full = mb_substr(trim($base . ($nm !== '' ? ' · '.$nm : '')), 0, 250);

        $imgs = ob_all("SELECT COALESCE(url_s3,url_src) u FROM ob_img
                         WHERE num_iid=? AND kind='main' ORDER BY is_cover DESC, sort ASC LIMIT 10", [$iid]);
        $urls = array_column($imgs,'u');
        $cover = trim((string)($sku['img_s3'] ?: $sku['img_url'] ?: ($urls[0] ?? '')));

        $price = ($pcny>0 && $dvol>0) ? ds_calc_price_rub($pcny,$dvol,$dwt ?: 1) : 0;
        // Готовое (цена, фото, без иероглифов) — сразу в каталог. Недоделанное — в черновик.
        $st = ($price>0 && $cover!=='' && !preg_match('/[\x{4e00}-\x{9fff}]/u',$full)) ? 'approved' : 'draft';

        $pid = pdd_gen_pid();
        $catOur = itc_store_category($full);
        db()->prepare('INSERT INTO products(id,supplier_id,cat,subcat,name,price,goods_cny,volume_m3,descr,img,gallery,stock,original,mod_status,weight_kg) VALUES(?,?,?,?,?,?,?,?,?,?,?,0,0,?,?)')
          ->execute([$pid,ds_supplier_id(),$catOur ?: ($p['itc_category'] ?: 'Прочее'),
                     $catRow['itc_subcat'] ?? '',$full,$price,$pcny,$dvol,'',
                     $cover,json_encode(array_slice($urls,0,10),JSON_UNESCAPED_UNICODE),$st,$dwt]);
        stamp_creator($pid, $s);

        $dsid = gen_ds_id();
        db()->prepare('INSERT INTO ds_products(id,product_id,source_url,source_platform,source_price_cny,manager_id,declared_weight_kg,declared_volume_m3,created_by) VALUES(?,?,?,?,?,?,?,?,?)')
          ->execute([$dsid,$pid,$url,'1688',$pcny,$mgr?:null,$dwt,$dvol,$s['phone']??'']);
        ds_mark_auto($dsid);
        ds_sync_product_price($dsid);
        ob_exec("UPDATE ob_sku SET product_id=? WHERE id=?", [$pid,$sku['id']]);
        $made++; $cards++;
      }

      // 5. Фото в S3
      $ph = null;
      if($doPhoto && function_exists('ob_photos_process')){
        $ph = ob_photos_process($iid, ['kinds'=>['main'],'limit'=>8]);
      }

      $res[] = ['num_iid'=>$iid,'ok'=>true,
                'title'=>mb_substr($p['title_cn'],0,44),
                'cards'=>$made,'awaiting_volume'=>$wait,
                'photos'=>$ph['done'] ?? 0,
                'category'=>$catOur ?: $p['itc_category']];
    }

    jout(['ok'=>true,'items'=>$res,'cards_created'=>$cards,
          'cost_cny'=>round($cost,3),
          'msg'=>'Создано карточек: '.$cards]);
  }

  // ---- Все карточки 1688 по вкладкам ----
  // tab: volume | draft | pending | published | rejected | all
  case 'ob_cards_list': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager','moderator']);
    $tab = trim($_GET['tab'] ?? '');
    if(!$tab){ $d=body(); $tab = trim($d['tab'] ?? 'draft'); }

    $cond = "dp.source_platform='1688'";
    switch($tab){
      case 'volume':
        // Объёма нет ИЛИ он взят по категории и фрахт кратно дороже товара
        $cond .= " AND (dp.declared_volume_m3 IS NULL OR dp.declared_volume_m3 <= 0
                        OR sk.vol_source='ask'
                        OR (sk.vol_source='kd_category' AND sk.freight_ratio >= " . OB_FREIGHT_SUSPECT . "))";
        break;
      case 'draft':     $cond .= " AND p.mod_status='draft'"; break;
      case 'pending':   $cond .= " AND p.mod_status='pending'"; break;
      case 'published': $cond .= " AND p.mod_status='approved' AND p.blocked=0"; break;
      case 'rejected':  $cond .= " AND p.mod_status='rejected'"; break;
      case 'all':       break;
      default:          $cond .= " AND p.mod_status='draft'";
    }

    $rows = ob_all(
      "SELECT dp.id ds_id, dp.product_id, dp.source_url, dp.source_price_cny,
              dp.declared_volume_m3, dp.declared_weight_kg,
              p.name, p.img, p.cat, p.blocked, p.price, p.mod_status, p.stock,
              i.num_iid, i.title_cn, i.title_ru, i.location, i.shop_name,
              i.itc_category, i.moq, i.detail_url,
              sk.properties_cn, sk.name_ru, sk.len_cm, sk.wid_cm, sk.hei_cm,
              sk.vol_source, sk.kd_cat, sk.freight_ratio, sk.seller_warn,
              CASE
                WHEN dp.declared_volume_m3 IS NULL OR dp.declared_volume_m3 <= 0
                     THEN 'нет объёма'
                WHEN sk.vol_source='ask' THEN 'отправлено на уточнение'
                WHEN sk.freight_ratio >= " . OB_FREIGHT_SUSPECT . "
                     THEN CONCAT('фрахт в ', ROUND(sk.freight_ratio,1),
                                 ' раза дороже товара — категория «',
                                 COALESCE(sk.kd_cat,'?'), '» вероятно не та')
                ELSE NULL
              END AS why,
              (p.name REGEXP '[一-龥]') AS has_zh
         FROM ds_products dp
         JOIN products p   ON p.id = dp.product_id
    LEFT JOIN ob_item  i   ON i.detail_url = dp.source_url
    LEFT JOIN ob_sku   sk  ON sk.product_id = dp.product_id
        WHERE {$cond}
        ORDER BY dp.created_at DESC LIMIT 300");

    // Запрос фабрике — только для вкладки «ждут объём»
    if($tab === 'volume'){
      foreach($rows as &$r){
        $dims = ($r['len_cm'] && $r['wid_cm'] && $r['hei_cm'])
              ? "{$r['len_cm']}*{$r['wid_cm']}*{$r['hei_cm']}cm" : '';
        $skuName = trim((string)($r['name_ru'] ?? ''));
        if($skuName === '' && function_exists('ob_sku_clean_name'))
          $skuName = ob_sku_clean_name($r['properties_cn'] ?? '');
        $r['ask_factory'] = ob_ask_factory_text($r['title_cn'] ?? $r['name'], $skuName, $dims);
      }
      unset($r);
    }

    // Счётчики по всем вкладкам разом
    $c = ob_row(
      "SELECT
        SUM(dp.declared_volume_m3 IS NULL OR dp.declared_volume_m3<=0
            OR sk.vol_source='ask'
            OR (sk.vol_source='kd_category' AND sk.freight_ratio >= " . OB_FREIGHT_SUSPECT . ")) volume,
        SUM(p.mod_status='draft')    draft,
        SUM(p.mod_status='pending')  pending,
        SUM(p.mod_status='approved' AND p.blocked=0) published,
        SUM(p.mod_status='rejected') rejected,
        COUNT(*) all_cnt
       FROM ds_products dp
       JOIN products p ON p.id=dp.product_id
  LEFT JOIN ob_sku sk ON sk.product_id=dp.product_id
      WHERE dp.source_platform='1688'");

    jout(['ok'=>true,'tab'=>$tab,'items'=>$rows,'count'=>count($rows),
          'counters'=>[
            'volume'    => (int)($c['volume'] ?? 0),
            'draft'     => (int)($c['draft'] ?? 0),
            'pending'   => (int)($c['pending'] ?? 0),
            'published' => (int)($c['published'] ?? 0),
            'rejected'  => (int)($c['rejected'] ?? 0),
            'all'       => (int)($c['all_cnt'] ?? 0),
          ],
          'db_error'=>function_exists('ob_db_error')?ob_db_error():null]);
  }

  // ---- Отправить карточки 1688 на модерацию ----
  case 'ob_send_moderation': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $ids = is_array($d['product_ids'] ?? null) ? $d['product_ids'] : [];
    if(!$ids) fail('Не выбрано ни одной карточки');

    $ok=[]; $skip=[]; $photoFixed=0;
    foreach($ids as $pid){
      $p = ob_row("SELECT id,name,price,img,blocked FROM products WHERE id=?", [$pid]);
      if(!$p){ $skip[]=['id'=>$pid,'why'=>'не найдена']; continue; }
      // На модерацию — только готовое: с ценой, фото и без иероглифов
      if((float)$p['price'] <= 0){ $skip[]=['id'=>$pid,'name'=>$p['name'],'why'=>'нет цены — уточните объём']; continue; }

      // ФОТО ЗАБИРАЕМ САМИ, здесь. Это последняя точка перед покупателем:
      // дальше карточка уходит в магазин, и пустой квадрат увидит он.
      // Проверка ниже раньше ловила только ПУСТОЕ поле img, а ссылка на
      // alicdn не пустая — карточка проходила и показывала пустоту:
      // китайский CDN из России не открывается.
      $img = trim((string)$p['img']);
      if($img === '' || strpos($img, 'alicdn') !== false){
        $sk = ob_row("SELECT num_iid FROM ob_sku WHERE product_id=? LIMIT 1", [$pid]);
        if($sk && function_exists('ob_photos_process')){
          try {
            ob_photos_process($sk['num_iid'], ['kinds'=>['main','sku'], 'limit'=>20]);
            $p2  = ob_row("SELECT img FROM products WHERE id=?", [$pid]);
            $img = trim((string)($p2['img'] ?? ''));
            if($img !== '' && strpos($img, 'alicdn') === false) $photoFixed++;
          } catch (Exception $e) { @error_log('[ob_send_moderation] фото: '.$e->getMessage()); }
        }
      }
      if($img === '' || strpos($img, 'alicdn') !== false){
        $skip[]=['id'=>$pid,'name'=>$p['name'],
                 'why'=>$img==='' ? 'нет фото'
                                  : 'фото осталось на alicdn — покупателю будет пустой квадрат'];
        continue;
      }

      if(preg_match('/[\x{4e00}-\x{9fff}]/u', (string)$p['name'])){
        $skip[]=['id'=>$pid,'name'=>$p['name'],'why'=>'в названии иероглифы — нужен перевод']; continue;
      }
      db()->prepare("UPDATE products SET mod_status='approved' WHERE id=?")->execute([$pid]);
      itc_log_add($s['phone']??'', 'published', 'product', $pid, $p['name']);
      $ok[]=$pid;
    }
    jout(['ok'=>true,'sent'=>count($ok),'skipped'=>$skip,'photos_fetched'=>$photoFixed,
          'msg'=>'Отправлено на модерацию: '.count($ok)
                . ($photoFixed? ' · фото забрали в S3: '.$photoFixed : '')
                . (count($skip)? ' · пропущено '.count($skip):'')]);
  }

  // ---- Очередь «ждут объём» ----
  // Карточки без объёма заблокированы (blocked=1) и покупателю не видны.
  // Менеджер запрашивает 外箱尺寸 у фабрики и вносит через ob_set_volume.
  case 'ob_volume_queue': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager','moderator']);
    // В очередь попадают ТРИ случая:
    //   1) объёма нет вообще
    //   2) объём взят по категории И фрахт кратно дороже товара — значит
    //      категория скорее всего не та. Живой пример: обувница-этажерка
    //      получила объём шкафа (0.09 м3, 15 кг) -> цена 4414 ₽ вместо ~700.
    //   3) объём помечен вручную как требующий проверки (vol_source='ask')
    $rows = ob_all(
      "SELECT dp.id ds_id, dp.product_id, dp.source_url, dp.source_price_cny,
              dp.declared_volume_m3, dp.declared_weight_kg,
              p.name, p.img, p.cat, p.blocked, p.price,
              i.num_iid, i.title_cn, i.location, i.seller_nick, i.shop_name,
              i.itc_category, i.moq, i.detail_url,
              sk.properties_cn, sk.name_ru, sk.len_cm, sk.wid_cm, sk.hei_cm,
              sk.vol_source, sk.kd_cat, sk.freight_ratio, sk.seller_warn,
              CASE
                WHEN dp.declared_volume_m3 IS NULL OR dp.declared_volume_m3 <= 0
                     THEN 'нет объёма'
                WHEN sk.vol_source = 'ask' THEN 'отправлено на уточнение'
                WHEN sk.freight_ratio >= " . OB_FREIGHT_SUSPECT . "
                     THEN CONCAT('фрахт в ', ROUND(sk.freight_ratio,1),
                                 ' раза дороже товара — категория «',
                                 COALESCE(sk.kd_cat,'?'), '» вероятно не та')
                ELSE 'проверить'
              END AS why
         FROM ds_products dp
         JOIN products p   ON p.id = dp.product_id
    LEFT JOIN ob_item  i   ON i.detail_url = dp.source_url
    LEFT JOIN ob_sku   sk  ON sk.product_id = dp.product_id
        WHERE dp.source_platform='1688'
          AND (
                dp.declared_volume_m3 IS NULL
             OR dp.declared_volume_m3 <= 0
             OR sk.vol_source = 'ask'
             OR (sk.vol_source = 'kd_category' AND sk.freight_ratio >= " . OB_FREIGHT_SUSPECT . ")
          )
        ORDER BY sk.freight_ratio DESC, dp.created_at DESC LIMIT 300");

    // Заготовка запроса фабрике — менеджеру останется отправить
    foreach ($rows as &$r) {
      $dims = ($r['len_cm'] && $r['wid_cm'] && $r['hei_cm'])
            ? "{$r['len_cm']}*{$r['wid_cm']}*{$r['hei_cm']}cm" : '';
      // Чистое имя варианта, без рекламы продавца в поле 尺寸.
      // Сырое properties_cn выглядит как «0:46:颜色:白色帘4层长59.5cm【个人版】;1:0:尺寸:1.出厂价冲量…»
      $skuName = trim((string)($r['name_ru'] ?? ''));
      if ($skuName === '' && function_exists('ob_sku_clean_name')) {
          $skuName = ob_sku_clean_name($r['properties_cn'] ?? '');
      }
      $r['ask_factory'] = ob_ask_factory_text($r['title_cn'] ?? $r['name'], $skuName, $dims);
    }
    unset($r);

    $err = function_exists('ob_db_error') ? ob_db_error() : null;
    jout(['ok'=>true,'count'=>count($rows),'items'=>$rows,
          'db_error'=>$err]);   // если пусто и тут есть текст — смотреть сюда
  }

  // ---- Отправить карточку на уточнение объёма у фабрики ----
  // Менеджер видит, что объём странный -> жмёт кнопку -> карточка уходит
  // в очередь, скрывается от покупателей, ждёт ответа фабрики.
  case 'ob_ask_volume': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager','moderator']);
    $d=body();
    $ds_id = trim($d['ds_id'] ?? '');
    $pid   = trim($d['product_id'] ?? '');
    if(!$ds_id && !$pid) fail('Укажите ds_id или product_id');

    if(!$ds_id){
      $r = ob_row("SELECT id FROM ds_products WHERE product_id=? LIMIT 1", [$pid]);
      $ds_id = $r['id'] ?? '';
    }
    if(!$ds_id) fail('Карточка не найдена');

    $row = db()->prepare('SELECT product_id FROM ds_products WHERE id=?');
    $row->execute([$ds_id]); $row = $row->fetch();
    if(!$row) fail('Карточка не найдена');
    $pid = $row['product_id'];

    // Обнуляем объём -> ds_sync_product_price сам поставит blocked=1
    db()->prepare('UPDATE ds_products SET declared_volume_m3=0 WHERE id=?')->execute([$ds_id]);
    ob_exec("UPDATE ob_sku SET vol_source='ask' WHERE product_id=?", [$pid]);
    ds_sync_product_price($ds_id);

    $p = db()->prepare('SELECT name, blocked FROM products WHERE id=?');
    $p->execute([$pid]); $p = $p->fetch();
    itc_log_add($s['phone']??'', 'volume_ask', 'product', $pid, $p['name']??'');

    jout(['ok'=>true,'ds_id'=>$ds_id,'product_id'=>$pid,
          'blocked'=>(int)($p['blocked']??1),
          'msg'=>'Карточка скрыта и отправлена в очередь на уточнение объёма']);
  }

  // ---- Внести объём -> цена считается, карточка разблокируется сама ----
  case 'ob_set_volume': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager','moderator']);
    $d=body();
    $ds_id = trim($d['ds_id'] ?? '');
    if(!$ds_id) fail('Не указан ds_id');

    // Либо готовый объём, либо габариты коробки — посчитаем сами
    $vol = (float)($d['volume_m3'] ?? 0);
    if($vol <= 0){
      $bl=(float)($d['box_len_cm']??0); $bw=(float)($d['box_wid_cm']??0); $bh=(float)($d['box_hei_cm']??0);
      $pcs=(int)($d['pcs_per_box']??1);
      if($bl>0 && $bw>0 && $bh>0){
        $vol = ($bl/100)*($bw/100)*($bh/100);
        if($pcs>1) $vol = $vol/$pcs;      // коробка на несколько штук
        $vol = round($vol,4);
      }
    }
    if($vol <= 0) fail('Укажите volume_m3 или габариты коробки box_len_cm/box_wid_cm/box_hei_cm');

    $wt = (float)($d['weight_kg'] ?? 0);

    $row = db()->prepare('SELECT product_id, declared_weight_kg FROM ds_products WHERE id=?');
    $row->execute([$ds_id]); $row = $row->fetch();
    if(!$row) fail('Карточка не найдена');
    if($wt <= 0) $wt = (float)($row['declared_weight_kg'] ?: 0);
    if($wt <= 0) fail('Укажите weight_kg — вес нужен для расчёта');

    db()->prepare('UPDATE ds_products SET declared_volume_m3=?, declared_weight_kg=? WHERE id=?')
      ->execute([$vol,$wt,$ds_id]);

    // Тут происходит главное: цена считается и blocked снимается
    ds_sync_product_price($ds_id);

    // Синхронизируем ob_sku, чтобы данные не разъехались
    ob_exec("UPDATE ob_sku SET volume_m3=?, weight_kg=?, vol_source='manual' WHERE product_id=?",
            [$vol,$wt,$row['product_id']]);

    $p = db()->prepare('SELECT price, blocked, name FROM products WHERE id=?');
    $p->execute([$row['product_id']]); $p = $p->fetch();

    itc_log_add($s['phone']??'', 'volume_set', 'product', $row['product_id'], $p['name']??'');

    jout(['ok'=>true,'ds_id'=>$ds_id,'product_id'=>$row['product_id'],
          'volume_m3'=>$vol,'weight_kg'=>$wt,
          'price'=>$p['price']??null,'blocked'=>(int)($p['blocked']??1),
          'msg'=>empty($p['blocked'])
                 ? '✅ Объём внесён, цена рассчитана, карточка опубликована'
                 : '⚠️ Объём внесён, но карточка ещё заблокирована — проверьте цену закупки']);
  }

  // ---- Карточка глазами покупателя ----
  // Карточка в статусе draft/blocked на витрине не видна, поэтому отдаём
  // ровно те поля, которые увидит покупатель, — для окна предпросмотра.
  case 'ob_card_preview': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager','moderator']);
    $pid = trim($_GET['product_id'] ?? '');
    if(!$pid){ $d=body(); $pid = trim($d['product_id'] ?? ''); }
    if(!$pid) fail('Не указан product_id');

    $p = db()->prepare('SELECT id,cat,subcat,name,price,old_price,descr,img,gallery,
                               stock,mod_status,blocked,weight_kg,volume_m3,goods_cny,variants
                          FROM products WHERE id=?');
    $p->execute([$pid]); $p = $p->fetch();
    if(!$p) fail('Карточка не найдена');

    $p['gallery']  = json_decode($p['gallery'] ?: '[]', true) ?: [];
    $p['variants'] = json_decode($p['variants'] ?: 'null', true);

    // Данные 1688 по этому SKU — для панели закупки
    $sk = ob_row("SELECT s.num_iid,s.properties_cn,s.name_ru,s.price_cny,s.quantity,
                         s.len_cm,s.wid_cm,s.hei_cm,s.volume_m3 sku_vol,s.weight_kg sku_wt,
                         s.vol_source,s.kd_cat,s.freight_ratio,s.seller_warn,s.set_note,
                         i.title_cn,i.location,i.shop_name,i.detail_url,i.moq,i.stock ob_stock
                    FROM ob_sku s LEFT JOIN ob_item i ON i.num_iid=s.num_iid
                   WHERE s.product_id=? LIMIT 1", [$pid]);

    // Характеристики из props — то, что пойдёт покупателю
    $props = [];
    if($sk && !empty($sk['num_iid'])){
      $props = ob_all("SELECT name_cn,value_cn,name_ru,value_ru FROM ob_prop
                        WHERE num_iid=? ORDER BY sort LIMIT 20", [$sk['num_iid']]);
    }

    // Разбор цены — откуда взялись рубли
    $breakdown = null;
    if($sk && $sk['price_cny'] > 0){
      $st = get_settings();
      $kurs = (float)($st['kurs_cny'] ?? 13.2);
      $goods = $sk['price_cny'] * $kurs;
      $per_m3 = ((float)($st['freight_usd'] ?? 10000) * (float)($st['kurs_usd'] ?? 95))
              / max(1,(float)($st['cont_vol'] ?? 68));
      $freight = (float)$p['volume_m3'] * $per_m3;
      $breakdown = [
        'goods_cny' => (float)$sk['price_cny'],
        'kurs'      => $kurs,
        'goods_rub' => round($goods),
        'volume_m3' => (float)$p['volume_m3'],
        'per_m3'    => round($per_m3),
        'freight_rub' => round($freight),
        'other_rub' => max(0, round($p['price'] - $goods - $freight)),
        'total_rub' => (int)$p['price'],
      ];
    }

    jout(['ok'=>true,'product'=>$p,'sku'=>$sk,'props'=>$props,'breakdown'=>$breakdown]);
  }

  // ---- DeepSeek: диагностика ----
  // ai_translate_field() возвращает null и молча откатывается на MyMemory,
  // а тот переводит дословно («神器» -> «Артефакты»). Выясняем причину:
  // кончились токены / неверный ключ / не та модель / сеть.
  case 'ob_ds_check': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);

    $out = ['key_set' => defined('DEEPSEEK_API_KEY') && DEEPSEEK_API_KEY ? 'да' : 'НЕТ'];
    if ($out['key_set'] === 'НЕТ') { jout(['ok'=>false] + $out); break; }
    $out['key_tail'] = '…' . substr(DEEPSEEK_API_KEY, -6);

    // 1. Баланс — отдельная ручка, денег не тратит
    $ch = curl_init('https://api.deepseek.com/user/balance');
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>20,
      CURLOPT_HTTPHEADER=>['Authorization: Bearer '.DEEPSEEK_API_KEY],
      CURLOPT_SSL_VERIFYPEER=>false,
    ]);
    $bal = curl_exec($ch);
    $out['balance_http'] = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $out['balance_err']  = curl_error($ch) ?: null;
    curl_close($ch);
    $out['balance'] = json_decode($bal, true) ?: substr((string)$bal, 0, 300);

    // 2. Список моделей — проверяем имя deepseek-v4-flash
    $ch = curl_init('https://api.deepseek.com/models');
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>20,
      CURLOPT_HTTPHEADER=>['Authorization: Bearer '.DEEPSEEK_API_KEY],
      CURLOPT_SSL_VERIFYPEER=>false,
    ]);
    $mdl = curl_exec($ch);
    $out['models_http'] = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    $mj = json_decode($mdl, true);
    $out['models'] = isset($mj['data']) ? array_column($mj['data'], 'id')
                                        : substr((string)$mdl, 0, 300);

    // 3. Живой запрос — тот же, что делает ai_translate_field
    $payload = json_encode([
      'model'=>'deepseek-v4-flash',
      'messages'=>[['role'=>'user','content'=>'Переведи на русский: 鞋架']],
      'max_tokens'=>50, 'stream'=>false,
    ], JSON_UNESCAPED_UNICODE);
    $ch = curl_init('https://api.deepseek.com/chat/completions');
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true,
      CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.DEEPSEEK_API_KEY],
      CURLOPT_POSTFIELDS=>$payload, CURLOPT_TIMEOUT=>30, CURLOPT_SSL_VERIFYPEER=>false,
    ]);
    $raw = curl_exec($ch);
    $out['chat_http'] = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $out['chat_err']  = curl_error($ch) ?: null;
    curl_close($ch);
    $rj = json_decode($raw, true);
    $out['chat_answer'] = $rj['choices'][0]['message']['content'] ?? null;
    $out['chat_raw']    = $out['chat_answer'] ? null : substr((string)$raw, 0, 400);

    // Вердикт
    $v = [];
    if ($out['chat_http'] === 200 && $out['chat_answer']) {
      $v[] = 'DeepSeek РАБОТАЕТ — ответ: ' . $out['chat_answer'];
    } elseif ($out['chat_http'] === 401) {
      $v[] = 'НЕВЕРНЫЙ КЛЮЧ (401) — перевыпустить на platform.deepseek.com';
    } elseif ($out['chat_http'] === 402) {
      $v[] = 'КОНЧИЛИСЬ ДЕНЬГИ (402) — пополнить счёт. Личный Alipay не подойдёт, нужен корпоративный Jinjia через вкладку 企业';
    } elseif ($out['chat_http'] === 400) {
      $v[] = 'ОШИБКА ЗАПРОСА (400) — вероятно неверное имя модели «deepseek-v4-flash», см. список моделей выше';
    } elseif ($out['chat_http'] === 0) {
      $v[] = 'НЕТ СВЯЗИ с api.deepseek.com с сервера Reg.ru: ' . ($out['chat_err'] ?? '?');
    } else {
      $v[] = 'HTTP ' . $out['chat_http'] . ' — см. chat_raw';
    }
    $out['verdict'] = $v;

    jout(['ok'=>true] + $out);
  }

  // ---- ПЕРЕВОД: китайский -> русский через DeepSeek ----
  // Батчем: у товара бывает 69 вариантов, по одному было бы 69 запросов.
  case 'ob_translate': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!function_exists('ob_translate_item')) fail('ob_translate.php не подключён');
    $d=body();
    $iid = trim($d['num_iid'] ?? $_GET['num_iid'] ?? '');
    if(!$iid) fail('Не указан num_iid');
    $r = ob_translate_item($iid, ['force' => !empty($d['force'])]);
    if(empty($r['ok'])){ jout($r); break; }
    $r['msg'] = 'Переведено: название + ' . $r['skus'] . ' вариантов + '
              . $r['props'] . ' характеристик · запросов к переводчику: ' . $r['deepseek_calls'];
    jout($r);
  }

  // ---- №314: ПЕРЕВОД ВСЕГО КАТАЛОГА — состояние / управление / шаг ----
  case 'retr_status': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    jout(['ok'=>true, 'st'=>retr_out(retr_state())]);
  }
  case 'retr_ctl': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $cmd = (string)(body()['cmd'] ?? '');
    $st = retr_state();
    if ($cmd === 'start') {
      // №320 (решение Алексея 08.10): «Запустить» больше НЕ сбрасывает отметки.
      // Переведённое DeepSeek остаётся переведённым — берём только очередь.
      retr_col();
      $st = ['running'=>1,'paused'=>0,'after'=>'','ok'=>0,'err'=>0,'done'=>0,'started'=>date('Y-m-d H:i:s'),'finished'=>'','last'=>[],'msg'=>''];
    } elseif ($cmd === 'resume') {
      $st['running'] = 1; $st['finished'] = ''; $st['msg'] = ''; $st['paused'] = 0;
    } elseif ($cmd === 'retry') {
      retr_col();
      ob_exec("UPDATE ob_item SET tr_ds=0 WHERE tr_ds=2");   // ошибочные — ещё раз
      $st['running'] = 1; $st['finished'] = ''; $st['msg'] = ''; $st['paused'] = 0;
    } elseif ($cmd === 'pause') {
      $st['running'] = 0; $st['msg'] = 'Пауза'; $st['paused'] = 1;
    } else fail('Неизвестная команда');
    jout(['ok'=>true, 'st'=>retr_out(retr_save($st))]);
  }
  case 'retr_tick': {
    // Из приложения — по токену сотрудника; по расписанию — по ключу
    if (($_GET['key'] ?? '') !== 'itc-tr-0710') { $s=authUser('itc'); require_staff($s,['supervisor','manager']); }
    jout(['ok'=>true, 'st'=>retr_out(retr_tick(35))]);
  }

  // ---- ПЕРЕВОД: проверка, осталась ли китайщина ----
  case 'ob_translate_check': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!function_exists('ob_translate_check')) fail('ob_translate.php не подключён');
    $iid = trim($_GET['num_iid'] ?? '');
    if(!$iid){ $d=body(); $iid = trim($d['num_iid'] ?? ''); }
    if(!$iid) fail('Не указан num_iid');
    jout(['ok'=>true] + ob_translate_check($iid));
  }

  // ---- YANDEX: диагностика обоих движков ----
  case 'ob_yx_env': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!function_exists('yx_env')) fail('ob_yandex.php не подключён');
    jout(['ok'=>true, 'env'=>yx_env()]);
  }

  // ---- ФОТО: диагностика среды ----
  // Главный вопрос: достаёт ли Reg.ru до alicdn напрямую, или нужен
  // китайский прокси. Плюс: чем сжимать (GD/webp), работает ли S3.
  case 'ob_photo_env': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!function_exists('ob_photo_env')) fail('ob_photo.php не подключён');

    $env = ob_photo_env();

    // Пробуем настоящее фото с 1688
    $test = ob_row("SELECT url_src FROM ob_img WHERE kind='main' ORDER BY id LIMIT 1");
    $probe = null;
    if($test){
      $probe = ob_photo_probe($test['url_src']);
      $probe['url'] = $test['url_src'];
    }

    $verdict = [];
    if(!$env['gd'])        $verdict[] = 'НЕТ GD — сжимать нечем, обратиться в поддержку Reg.ru';
    elseif(!$env['gd_webp']) $verdict[] = 'GD есть, но без webp — будем жать в jpeg';
    else                   $verdict[] = 'GD + webp есть';
    if(!$env['s3_enabled']) $verdict[] = 'S3 выключен в config.php';
    if($probe){
      if(!empty($probe['direct']['ok']))      $verdict[] = 'alicdn достаётся НАПРЯМУЮ — прокси не нужен';
      elseif(!empty($probe['via_proxy']['ok'])) $verdict[] = 'alicdn только ЧЕРЕЗ ПРОКСИ (8.134.158.219)';
      else                                     $verdict[] = 'alicdn НЕ достаётся ни напрямую, ни через прокси';
    }

    jout(['ok'=>true,'env'=>$env,'probe'=>$probe,'verdict'=>$verdict]);
  }

  // ---- ФОТО: перенести фото товара в S3 ----
  case 'ob_photos': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    if(!function_exists('ob_photos_process')) fail('ob_photo.php не подключён');
    $d=body();
    $iid = trim($d['num_iid'] ?? $_GET['num_iid'] ?? '');
    if(!$iid) fail('Не указан num_iid');
    $r = ob_photos_process($iid, [
      'kinds' => $d['kinds'] ?? ['main','sku'],
      'limit' => (int)($d['limit'] ?? 20),
    ]);
    $r['msg'] = "Перенесено в S3: {$r['done']}, ошибок: {$r['failed']}"
              . ($r['was_mb'] ? " · {$r['was_mb']} МБ -> {$r['now_mb']} МБ (минус {$r['saved']})" : '');
    jout($r);
  }

  // Расход по вызовам onebound (тариф поштучный, 0.022¥ класс A)
  case 'ob_spend': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $days = ob_all("SELECT DATE(created_at) d, COUNT(*) calls, SUM(billable) billable,
                           ROUND(SUM(cost_cny),3) cny, SUM(from_cache) cached
                      FROM ob_log WHERE created_at > DATE_SUB(NOW(), INTERVAL 30 DAY)
                     GROUP BY DATE(created_at) ORDER BY d DESC");
    $tot = ob_row("SELECT COUNT(*) calls, SUM(billable) billable,
                          ROUND(SUM(cost_cny),2) cny, SUM(from_cache) cached
                     FROM ob_log");
    jout(['ok'=>true,'days'=>$days,'total'=>$tot]);
    break;
  }

  // Карточки с предупреждениями — проверить глазами перед публикацией
  case 'ob_warnings': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    // Сначала то, что грозит деньгами: объём не определён -> недосчёт фрахта ~3500 ₽
    $novol = ob_all("SELECT num_iid,title_cn,price_cny,price_max_cny,volume_m3,vol_source,
                            itc_category,import_status,product_id
                       FROM ob_item WHERE vol_source='none' OR vol_source IS NULL
                      ORDER BY updated_at DESC LIMIT 200");
    $sets  = ob_all("SELECT s.num_iid,s.properties_cn,s.price_cny,s.volume_m3,s.set_note,
                            i.title_cn
                       FROM ob_sku s JOIN ob_item i ON i.num_iid=s.num_iid
                      WHERE s.set_note LIKE 'ВНИМАНИЕ%' LIMIT 200");
    $rows  = ob_all("SELECT num_iid,title_cn,title_ru,price_cny,price_max_cny,sku_count,
                            volume_m3,vol_source,dims_source,import_note,import_status,product_id
                       FROM ob_item WHERE import_note IS NOT NULL AND import_note<>''
                      ORDER BY updated_at DESC LIMIT 200");
    jout(['ok'=>true,
          'no_volume'=>$novol,   // объём не определён — НЕ публиковать
          'bad_sets'=>$sets,     // комплекты с непонятым доп. предметом
          'items'=>$rows]);
    break;
  }


  // ---- Пакетное создание карточек из PDD-вариантов ----
  case 'ds_create_batch_from_pdd': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $base_name   = trim($d['base_name']??'');
    $source_url  = trim($d['source_url']??'');
    if($source_url!=='' && empty($d['force']) && ($dup=ds_find_duplicate($source_url,'pdd'))){ jout(['ok'=>false,'duplicate'=>$dup,'error'=>'Этот товар уже заведён']); break; }
    $description = trim($d['description']??'');
    $images      = is_array($d['images']??null)?$d['images']:[];
    $cat_guess   = trim($d['cat_guess']??'Прочее')?:'Прочее';
    $mgr         = trim($d['manager_id']??'');
    $skus        = is_array($d['skus']??null)?$d['skus']:[];
    if(!$base_name) fail('Нет названия товара');
    if(!$source_url) fail('Нет URL');
    if(!count($skus)) fail('Нет вариантов для создания');

    $cover   = count($images)?$images[0]:'';
    $gallery = json_encode(array_slice($images,0,10),JSON_UNESCAPED_UNICODE);
    $created = [];

    foreach ($skus as $sku) {
      if (empty($sku['selected'])) continue; // пропускаем снятые галочки
      $sku_name  = trim($sku['name']??'');
      $full_name = $sku_name ? $base_name.' · '.$sku_name : $base_name;
      $pcny      = (float)($sku['price_cny']??0);
      $dwt       = max(0.5, (float)($sku['weight_kg']??1.0));
      $dvol      = max(0.001,(float)($sku['volume_m3']??0.005));
      $sku_img   = trim($sku['img']??'');
      $sku_cover = $sku_img ?: $cover;

      $price = ($pcny>0)?ds_calc_price_rub($pcny,$dvol,$dwt):0;
      $pid   = pdd_gen_pid();

      $cat_guess = itc_store_category($full_name);
      db()->prepare('INSERT INTO products(id,supplier_id,cat,subcat,name,price,goods_cny,volume_m3,descr,img,gallery,stock,original,mod_status,weight_kg) VALUES(?,?,?,?,?,?,?,?,?,?,?,0,0,?,?)')
        ->execute([$pid,ds_supplier_id(),$cat_guess,itc_store_subcat($cat_guess,$full_name),$full_name,$price,$pcny?:0,$dvol,$description,$sku_cover,$gallery,'approved',$dwt]);
      stamp_creator($pid, $s);

      $dsid=gen_ds_id();
      db()->prepare('INSERT INTO ds_products(id,product_id,source_url,source_platform,source_price_cny,manager_id,declared_weight_kg,declared_volume_m3,created_by) VALUES(?,?,?,?,?,?,?,?,?)')
        ->execute([$dsid,$pid,$source_url,'pdd',$pcny?:null,$mgr?:null,$dwt,$dvol,$s['phone']??'']);
      ds_mark_auto($dsid);
      ds_sync_product_price($dsid);

      $created[] = ['product_id'=>$pid,'ds_id'=>$dsid,'name'=>$full_name,'price'=>$price];
    }

    $n = count($created);
    jout(['ok'=>true,'created'=>$created,'count'=>$n,
          'msg'=>"✅ Создано $n карточек в каталоге и DS"]);
    break;
  }

  // ---- Пересчёт группы по материалу (чинит старые карточки одним нажатием) ----
  // Берём переданные product_ids, каждому пересчитываем вес = объём × плотность
  // по материалу и обновляем цену через канонический ds_sync_product_price.
  // material — необязательный: если задан, применяется ко всем (приоритет) и
  // запоминается в карточках; если пусто — материал берётся из названия карточки.
  case 'ds_group_recalc': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $ids = is_array($d['product_ids'] ?? null) ? $d['product_ids'] : [];
    $mat = trim($d['material'] ?? '');
    if(!$ids) fail('Не переданы варианты для пересчёта');
    $done=0; $skipped=0;
    foreach($ids as $pid){
      $pid=(string)$pid;
      $pr=db()->prepare('SELECT id,name,cat,descr,volume_m3,goods_cny FROM products WHERE id=?');
      $pr->execute([$pid]); $row=$pr->fetch();
      if(!$row){ $skipped++; continue; }
      $vol=(float)$row['volume_m3'];
      if($vol<=0){ $skipped++; continue; }   // без объёма вес не считаем
      $matTxt = ($mat!=='') ? $mat : ($row['name'].' '.$row['cat'].' '.mb_substr((string)$row['descr'],0,200));
      $dens = function_exists('ob_weight_density') ? ob_weight_density($matTxt) : 190;
      $wt = round($vol*$dens,1);
      if($wt<=0){ $skipped++; continue; }
      // сохраняем вес (и материал, если задан группой)
      if($mat!=='') db()->prepare('UPDATE products SET material=?, weight_kg=? WHERE id=?')->execute([mb_substr($mat,0,80),$wt,$pid]);
      else          db()->prepare('UPDATE products SET weight_kg=? WHERE id=?')->execute([$wt,$pid]);
      // канонический пересчёт цены через ds_products (как при создании)
      $synced=false;
      try{
        $dq=db()->prepare('SELECT id FROM ds_products WHERE product_id=? ORDER BY id DESC LIMIT 1');
        $dq->execute([$pid]); $dsid=$dq->fetchColumn();
        if($dsid){
          db()->prepare('UPDATE ds_products SET declared_weight_kg=? WHERE id=?')->execute([$wt,$dsid]);
          ds_sync_product_price($dsid); $synced=true;
        }
      }catch(Exception $e){}
      // нет DS-записи — считаем цену напрямую
      if(!$synced){
        $gc=(float)$row['goods_cny'];
        if($gc>0){ $price=calc_landed_rub($gc,$vol,$wt,get_settings(),product_via_jinjia($pid)); db()->prepare('UPDATE products SET price=? WHERE id=?')->execute([$price,$pid]); }
      }
      $done++;
    }
    jout(['ok'=>true,'done'=>$done,'skipped'=>$skipped,
          'msg'=>'Пересчитано: '.$done.($skipped?' · пропущено (нет объёма): '.$skipped:'')]);
  }

  // ---- Пересчёт группы по системе ×N (3/4/5). «×N» = сверху N цен = множитель (N+1).
  // Переводит выбранные карточки в режим ×N (временная цена до замера на складе).
  case 'ds_group_x3_recalc': {
    $s=authUser('itc'); require_staff($s,['supervisor','manager']);
    $d=body();
    $ids = is_array($d['product_ids'] ?? null) ? $d['product_ids'] : [];
    $lvl = (int)($d['level'] ?? 3);
    if($lvl < 1) $lvl = 1;  if($lvl > 15) $lvl = 15;    // ×1..×15 (×1=себест.×2, ×10=×11, ×15=×16)
    $mult = $lvl + 1;                                  // ×3→4, ×4→5, ×5→6
    if(!$ids) fail('Не переданы варианты для пересчёта');
    $done=0; $skipped=0;
    foreach($ids as $pid){
      $pid=(string)$pid;
      $dq=db()->prepare('SELECT id FROM ds_products WHERE product_id=? ORDER BY id DESC LIMIT 1');
      $dq->execute([$pid]); $dsid=$dq->fetchColumn();
      if(!$dsid){ $skipped++; continue; }
      try{ db()->prepare('UPDATE ds_products SET x3_pending=1, x3_mult=? WHERE id=?')->execute([$mult,$dsid]); }catch(Exception $e){ $skipped++; continue; }
      ds_sync_product_price($dsid);
      $done++;
    }
    jout(['ok'=>true,'done'=>$done,'skipped'=>$skipped,'level'=>$lvl,
          'msg'=>'Пересчитано по ×'.$lvl.': '.$done]);
  }

  // Статистика эффективности: сколько карточек завёл каждый и когда, + загружено товаров.
  case 'itc_cards_stats': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant']);
    $cards=[];
    try{ $cards=db()->query("SELECT DATE(created_at) d, COALESCE(NULLIF(created_by,''),'—') who, COUNT(*) c FROM products WHERE created_at IS NOT NULL GROUP BY DATE(created_at), created_by ORDER BY d DESC, c DESC")->fetchAll(); }catch(Exception $e){}
    $loaded=[];
    try{ foreach(db()->query("SELECT DATE(created_at) d, COUNT(*) c FROM ob_item WHERE created_at IS NOT NULL GROUP BY DATE(created_at)")->fetchAll() as $r){ $loaded[$r['d']]=(int)$r['c']; } }
    catch(Exception $e){ try{ foreach(db()->query("SELECT DATE(updated_at) d, COUNT(*) c FROM ob_item GROUP BY DATE(updated_at)")->fetchAll() as $r){ $loaded[$r['d']]=(int)$r['c']; } }catch(Exception $e2){} }
    // сводка: сегодня и всего
    $today=date('Y-m-d'); $todayCards=0; $totalCards=0;
    foreach($cards as $r){ $totalCards+=(int)$r['c']; if($r['d']===$today) $todayCards+=(int)$r['c']; }
    jout(['ok'=>true,'cards'=>$cards,'loaded'=>$loaded,'today'=>$today,'today_cards'=>$todayCards,'total_cards'=>$totalCards]);
  }

  // ---- Заявка на открытие ПВЗ (публичная подача) ----
  case 'pvz_apply': {
    $d=body();
    $name=trim($d['name']??''); $phone=trim($d['phone']??'');
    if($name===''||$phone==='') fail('Укажите имя и телефон');
    $id=gen('pvza');
    // Таблица могла быть не создана миграцией — создаём при первой же заявке,
    // иначе вставка молча падала и заявка пропадала бесследно.
    try{ db()->query("CREATE TABLE IF NOT EXISTS pvz_applications (
      id VARCHAR(32) PRIMARY KEY,
      name VARCHAR(200) NULL, email VARCHAR(200) NULL, phone VARCHAR(40) NULL,
      legal_form VARCHAR(20) NULL, company VARCHAR(250) NULL,
      inn VARCHAR(20) NULL, kpp VARCHAR(20) NULL, legal_addr VARCHAR(300) NULL,
      city VARCHAR(120) NULL, pvz_addr VARCHAR(300) NULL,
      building_type VARCHAR(40) NULL, floor VARCHAR(40) NULL, area_m2 VARCHAR(20) NULL,
      comment VARCHAR(500) NULL, status VARCHAR(20) NOT NULL DEFAULT 'new',
      decided_by VARCHAR(120) NULL,
      created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); }catch(Exception $e){}
    // вид заявки и банковские реквизиты появились позже — колонки создаём при необходимости
    $kind=(trim($d['kind']??'')==='warehouse')?'warehouse':'pvz';
    try{ db()->query("ALTER TABLE pvz_applications ADD COLUMN kind VARCHAR(20) DEFAULT 'pvz'"); }catch(Exception $e){}
    try{ db()->query("ALTER TABLE pvz_applications ADD COLUMN bik VARCHAR(20) NULL"); }catch(Exception $e){}
    try{ db()->query("ALTER TABLE pvz_applications ADD COLUMN bank VARCHAR(200) NULL"); }catch(Exception $e){}
    try{ db()->query("ALTER TABLE pvz_applications ADD COLUMN account VARCHAR(40) NULL"); }catch(Exception $e){}
    try{ db()->query("ALTER TABLE pvz_applications ADD COLUMN reg_info VARCHAR(400) NULL"); }catch(Exception $e){}
    try{ db()->query("ALTER TABLE pvz_applications ADD COLUMN photos TEXT NULL"); }catch(Exception $e){}
    try{
      db()->prepare('INSERT INTO pvz_applications (id,name,email,phone,legal_form,company,inn,kpp,legal_addr,city,pvz_addr,building_type,floor,area_m2,comment,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
        ->execute([$id, mb_substr($name,0,200), mb_substr(trim($d['email']??''),0,200), mb_substr($phone,0,40),
          mb_substr(trim($d['legal_form']??''),0,20), mb_substr(trim($d['company']??''),0,250),
          mb_substr(trim($d['inn']??''),0,20), mb_substr(trim($d['kpp']??''),0,20), mb_substr(trim($d['legal_addr']??''),0,300),
          mb_substr(trim($d['city']??''),0,120), mb_substr(trim($d['pvz_addr']??''),0,300),
          mb_substr(trim($d['building_type']??''),0,40), mb_substr(trim($d['floor']??''),0,40), mb_substr(trim($d['area_m2']??''),0,20),
          mb_substr(trim($d['comment']??''),0,500), 'new']);
    }catch(Exception $e){
      error_log('pvz_apply INSERT: '.$e->getMessage());
      fail('Не удалось отправить заявку: '.$e->getMessage());
    }
    // открытые реестры: название банка по БИК и проверка компании по ИНН
    $bik=preg_replace('/\D/','',(string)($d['bik']??''));
    $bank=mb_substr(trim($d['bank']??''),0,200); $reg='';
    if($bik!==''){ try{ $bk=dadata_call('findById/bank',['query'=>$bik,'count'=>1]);
      if($bk && !empty($bk['suggestions'][0]['value'])) $bank=mb_substr($bk['suggestions'][0]['value'],0,200); }catch(Exception $e){} }
    $innQ=preg_replace('/\D/','',(string)($d['inn']??''));
    if(strlen($innQ)>=10){ try{ $pt=dadata_call('findById/party',['query'=>$innQ,'count'=>1]);
      if($pt && !empty($pt['suggestions'][0])){ $pd=$pt['suggestions'][0]['data']??[];
        $reg=trim(($pt['suggestions'][0]['value']??'').' \u00b7 '.($pd['state']['status']??'').(!empty($pd['ogrn'])?' \u00b7 ОГРН '.$pd['ogrn']:'')); }
      else { $reg='не найдено в реестре'; } }catch(Exception $e){} }
    // Фото приходят строками base64: заявку подаёт человек без входа в систему,
    // поэтому обычная загрузка файлов с токеном тут не работает.
    $ph=[]; 
    $front=itc_store_b64_image($d['photo_front'] ?? '');
    if($front!=='') $ph[]=['t'=>'front','u'=>$front];
    $ins=$d['photos_in'] ?? [];
    if(is_array($ins)){ $n=0; foreach($ins as $one){ if($n>=4) break;
      $u=itc_store_b64_image($one); if($u!==''){ $ph[]=['t'=>'in','u'=>$u]; $n++; } } }
    if(count($ph)){ try{ db()->prepare("UPDATE pvz_applications SET photos=? WHERE id=?")
      ->execute([json_encode($ph, JSON_UNESCAPED_UNICODE), $id]); }catch(Exception $e){} }
    try{ db()->prepare("UPDATE pvz_applications SET kind=?, bik=?, bank=?, account=?, reg_info=? WHERE id=?")
      ->execute([$kind,$bik,$bank,preg_replace('/\D/','',(string)($d['account']??'')),mb_substr($reg,0,400),$id]); }catch(Exception $e){}
    jout(['ok'=>true]);
  }
  case 'pvz_apps': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant','accountant']);
    /* Раньше запрос был жёстким и обёрнут в «молчаливый» catch: не хватало одной
       колонки — и список приходил ПУСТЫМ, будто заявок нет вовсе. Теперь сперва
       спрашиваем у таблицы, какие поля в ней есть, и берём только их. Ошибку, если
       она всё же случится, возвращаем текстом, а не прячем. */
    $have=[];
    try{ foreach(db()->query("SHOW COLUMNS FROM pvz_applications")->fetchAll() as $c) $have[$c['Field']]=1; }catch(Exception $e){}
    $base=['id','name','email','phone','legal_form','company','inn','kpp','legal_addr','city','pvz_addr','building_type','floor','area_m2','comment','status','decided_by'];
    $extra=['kind','bik','bank','account','reg_info','photos'];
    $cols=[];
    foreach(array_merge($base,$extra) as $c){ if(!$have || isset($have[$c])) $cols[]=$c; }
    if(!$cols) $cols=['id','name','phone','status'];
    $rows=[]; $err='';
    try{ $rows=db()->query("SELECT ".implode(',',$cols).",UNIX_TIMESTAMP(created_at)*1000 ts FROM pvz_applications ORDER BY (status='new') DESC, created_at DESC LIMIT 500")->fetchAll(); }
    catch(Exception $e){ $err=$e->getMessage(); }
    $pending=0; foreach($rows as $r){ if(($r['status']??'')==='new')$pending++; }
    jout(['ok'=>true,'apps'=>$rows,'pending'=>$pending,'total'=>count($rows),'error'=>$err]);
  }
  // ---- ПАРТНЁР: карточка своей точки (описание, фото, готовность) ----
  // ---- ИТК: принять точку в работу (снять отметку «готов к открытию») ----
  case 'wh_accept_ready': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','chief_accountant']);
    $d = body(); $id = trim($d['id'] ?? '');
    if ($id === '') fail('Не указана точка');
    try { db()->query("ALTER TABLE warehouses ADD COLUMN ready TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
    try { db()->prepare('UPDATE warehouses SET ready=0 WHERE id=?')->execute([$id]); }
    catch (Exception $e) { fail('Не удалось сохранить'); }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'wh_accept_ready', 'warehouse', $id, '');
    jout(['ok' => true]);
  }

  case 'pt_point_get': {
    /* №272: предпросмотр боссом/сотрудником — точку берём у того партнёра,
       чей кабинет открыт (pid), а не у того, кто смотрит. Как в partner_state. */
    $prevPid = $_GET['pid'] ?? '';
    if ($prevPid !== '') { authUser('itc'); $s = ['role' => 'partner', 'supplier_id' => $prevPid]; }
    else { $s = authUser('partner'); }
    try { db()->query("ALTER TABLE warehouses ADD COLUMN photos TEXT NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN descr TEXT NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN ready TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
    $wid = partner_wh($s);          // тот же помощник, что и в остальных разделах партнёра
    if (!$wid) jout(['ok' => true, 'point' => null]);
    $w = null;
    try { $q = db()->prepare('SELECT id,code,name,city,address,kind,parent_id,descr,photos,ready FROM warehouses WHERE id=?');
          $q->execute([$wid]); $w = $q->fetch(); } catch (Exception $e) {}
    if (!$w) jout(['ok' => true, 'point' => null]);
    // к какому складу прикреплена точка — партнёру полезно видеть, откуда придёт товар
    $parent = '';
    if (!empty($w['parent_id'])) {
      try { $p = db()->prepare('SELECT name,city FROM warehouses WHERE id=?'); $p->execute([$w['parent_id']]);
            $pr = $p->fetch(); if ($pr) $parent = trim(($pr['name'] ?? '').' · '.($pr['city'] ?? '')); } catch (Exception $e) {}
    }
    $w['parent_name'] = $parent;
    jout(['ok' => true, 'point' => $w]);
  }

  case 'pt_point_save': {
    $s = authUser('partner');
    $d = body();
    $wid = partner_wh($s);
    if (!$wid) fail('За вами ещё не закреплена точка');
    try { db()->query("ALTER TABLE warehouses ADD COLUMN photos TEXT NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN descr TEXT NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE warehouses ADD COLUMN ready TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}

    // Фото приходят строками: партнёр снимает вывеску и помещение с телефона.
    $ph = [];
    try { $cur = db()->prepare('SELECT photos FROM warehouses WHERE id=?'); $cur->execute([$wid]);
          $old = (string)$cur->fetchColumn();
          if ($old !== '') { $tmp = json_decode($old, true); if (is_array($tmp)) $ph = $tmp; } } catch (Exception $e) {}
    $add = $d['photos_add'] ?? [];
    if (is_array($add)) {
      $n = 0;
      foreach ($add as $one) {
        if (count($ph) >= 12) break;                      // разумный предел на точку
        if ($n >= 6) break;                               // за один раз не больше шести
        $u = itc_store_b64_image($one);
        if ($u !== '') { $ph[] = ['t' => 'point', 'u' => $u]; $n++; }
      }
    }
    // удаление по номеру
    $del = $d['photo_del'] ?? null;
    if ($del !== null && $del !== '' && isset($ph[(int)$del])) { array_splice($ph, (int)$del, 1); }

    $descr = mb_substr(trim($d['descr'] ?? ''), 0, 2000);
    $ready = !empty($d['ready']) ? 1 : 0;
    try {
      db()->prepare('UPDATE warehouses SET descr=?, photos=?, ready=? WHERE id=?')
        ->execute([$descr, json_encode($ph, JSON_UNESCAPED_UNICODE), $ready, $wid]);
    } catch (Exception $e) { fail('Не удалось сохранить: '.$e->getMessage()); }
    itc_log_add(mb_substr(trim($s['phone'] ?? ''),0,120), 'pt_point_save', 'warehouse', $wid, ($ready ? 'готов к открытию' : ''));
    jout(['ok' => true, 'photos' => $ph]);
  }

  /* Отправка партнёру телефона и кода доступа по СМС. Раньше код можно было
     только продиктовать голосом — партнёр записывал на слух и ошибался. */
  case 'partner_code_sms': {
    $s = authUser('itc'); require_staff($s, ['boss','chief_accountant','accountant','manager']);
    $d = body();
    $pid = trim($d['partner_id'] ?? '');
    if ($pid === '') fail('Не указан партнёр');
    $p = null;
    try { $q = db()->prepare('SELECT id,phone,code,name,status FROM partners WHERE id=?'); $q->execute([$pid]); $p = $q->fetch(); }
    catch (Exception $e) {}
    if (!$p) fail('Партнёр не найден');
    $phone = (string)($p['phone'] ?? '');
    $code  = (string)($p['code'] ?? '');
    if ($phone === '') fail('У партнёра не указан телефон');
    /* Кода могло не быть у партнёров, заведённых до этого обновления, — выдаём. */
    if ($code === '') {
      $code = strtoupper(substr(bin2hex(random_bytes(4)), 0, 6));
      try { db()->prepare('UPDATE partners SET code=?, status=? WHERE id=?')->execute([$code,'active',$pid]); }
      catch (Exception $e) { fail('Не удалось выдать код'); }
    }
    if (!function_exists('sms_send')) fail('Отправка SMS не настроена');
    $text = 'ITC GLOBAL: dostup v kabinet partnera. Telefon: '.$phone.', kod: '.$code.'. Vhod: itcpartner.store';
    $resp = sms_send($phone, $text);
    $ok = false;
    if (is_array($resp)) {
      if (($resp['status'] ?? '') === 'OK') {
        $ok = true;
        if (!empty($resp['sms']) && is_array($resp['sms'])) {
          $first = reset($resp['sms']);
          if (is_array($first) && ($first['status'] ?? '') !== 'OK') $ok = false;
        }
      }
    }
    if (!$ok) {
      $err = '';
      if (is_array($resp)) $err = (string)($resp['status_text'] ?? ($resp['status_code'] ?? ''));
      fail('SMS не отправлено'.($err !== '' ? ' ('.$err.')' : ''), 502);
    }
    itc_log_add(mb_substr(trim($d['by'] ?? ''),0,120), 'partner_code_sms', 'partner', $pid, $phone);
    jout(['ok'=>true,'phone'=>$phone,'code'=>$code]);
  }

  case 'pvz_app_decide': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant']);
    $d=body(); $id=trim($d['id']??''); $act=(($d['action']??'')==='approve')?'approved':'rejected';
    if($id==='') fail('Нет заявки');
    $by = mb_substr(trim($d['by']??''),0,120);

    /* ОДОБРЕНИЕ = ЗАПУСК ТОЧКИ.
       Раньше менялся только статус, а партнёра, склад и связь между ними заводили
       руками и заново. Теперь одобрение делает всё разом: заводит партнёра по
       телефону из заявки (иначе ему негде войти и нечем дозаполнять карточку),
       создаёт сам ПВЗ или склад, прикрепляет к выбранному хабу и переносит туда
       фотографии из заявки. */
    $created = null;
    if ($act === 'approved') {
      $app = null;
      try { $q=db()->prepare('SELECT * FROM pvz_applications WHERE id=?'); $q->execute([$id]); $app=$q->fetch(); } catch (Exception $e) {}
      if (!$app) fail('Заявка не найдена');

      $parent = trim($d['parent_id'] ?? '');          // склад-хаб, к которому крепим
      $kind   = (($app['kind'] ?? 'pvz') === 'warehouse') ? 'hub' : 'pvz';
      if ($kind === 'pvz' && $parent === '') fail('Выберите склад, к которому прикрепить пункт выдачи');

      $phone = preg_replace('/[^0-9+]/', '', (string)($app['phone'] ?? ''));
      $pname = trim((string)($app['company'] ?? '')) ?: trim((string)($app['name'] ?? ''));
      $city  = trim((string)($app['city'] ?? ''));
      $addr  = trim((string)($app['pvz_addr'] ?? ''));

      // 1. партнёр — по телефону из заявки, если такого ещё нет
      $pid = '';
      try {
        $r=itc_partner_by_phone($phone);
        if ($r) {
          $pid=$r['id'];
          /* Карточка могла остаться пустой после входа по СМС — дописываем имя. */
          if (trim((string)($r['name'] ?? ''))==='' && $pname!=='') {
            try { db()->prepare('UPDATE partners SET name=? WHERE id=?')->execute([mb_substr($pname,0,160),$pid]); } catch (Exception $e) {}
          }
        }
        else {
          $pid=gen('pt');
          db()->prepare('INSERT INTO partners (id,phone,name,status) VALUES (?,?,?,?)')
            ->execute([$pid,(ph_norm($phone) ?: $phone),mb_substr($pname,0,160),'active']);
        }
        /* КОД ДОСТУПА. Вход партнёра — телефон плюс код; без кода partner_login
           отвечает «Неверный код доступа». Раньше код выдавался только вручную,
           через экран «Партнёры / операторы», поэтому одобренный партнёр войти
           не мог вовсе. Теперь код заводится здесь же и возвращается сотруднику,
           чтобы продиктовать его партнёру. Уже выданный код не трогаем. */
        try {
          $cq=db()->prepare('SELECT code FROM partners WHERE id=?'); $cq->execute([$pid]);
          $ptCode=(string)$cq->fetchColumn();
          if ($ptCode==='') {
            $ptCode=strtoupper(substr(bin2hex(random_bytes(4)),0,6));
            db()->prepare('UPDATE partners SET code=?, status=? WHERE id=?')->execute([$ptCode,'active',$pid]);
          }
          /* Одобрение = доступ открыт. Раньше статус ставился только вместе с новым
             кодом: если код у человека уже был, он так и оставался «ожидает». */
          db()->prepare("UPDATE partners SET status='active' WHERE id=?")->execute([$pid]);
        } catch (Exception $e) { $ptCode=''; }
      } catch (Exception $e) {}

      /* 2. КОД ТОЧКИ. Буквенная часть обозначает ГОРОД и должна быть одна на весь
            город. Раньше её всегда считали транслитом, поэтому у второй точки в
            Краснодаре выходило KRA, хотя первая давно заведена как KRD — один
            город получал два разных обозначения. Теперь сперва смотрим, как этот
            город уже обозначен в базе, и берём ту же букву. Сам код всё равно
            остаётся уникальным: вторая точка станет KRD2, третья KRD3. */
      $code = '';
      try {
        $cq = db()->prepare("SELECT code FROM warehouses WHERE LOWER(TRIM(city))=LOWER(TRIM(?)) AND code<>'' ORDER BY id LIMIT 20");
        $cq->execute([$city]);
        foreach ($cq->fetchAll() as $cr) {
          $letters = strtoupper(preg_replace('/[^A-Za-z]/', '', (string)$cr['code']));
          if ($letters !== '') { $code = $letters; break; }   // берём обозначение первой точки города
        }
      } catch (Exception $e) {}
      if ($code === '') {
        $code = strtoupper(preg_replace('/[^A-Za-z]/','', translit_ru($city)));
        $code = $code!=='' ? mb_substr($code,0,3) : 'PVZ';
      }
      try {
        $n=1; $try=$code;
        while (true) {
          $c=db()->prepare('SELECT COUNT(*) FROM warehouses WHERE code=?'); $c->execute([$try]);
          if (!(int)$c->fetchColumn()) break;
          $n++; $try=$code.$n; if ($n>99) { $try=$code.substr((string)time(),-4); break; }
        }
        $code=$try;
      } catch (Exception $e) {}

      // 3. сама точка, прикреплённая к хабу
      $wid = gen('w');
      try {
        db()->prepare('INSERT INTO warehouses (id,code,name,city,country,address,active,kind,parent_id) VALUES (?,?,?,?,?,?,?,?,?)')
          ->execute([$wid,$code,mb_substr(($kind==='hub'?'Склад ':'ПВЗ ').$city,0,120),$city,'RU',mb_substr($addr,0,255),1,$kind,($parent?:null)]);
      } catch (Exception $e) { fail('Не удалось создать точку: '.$e->getMessage()); }

      // 4. закрепляем точку за партнёром
      if ($pid !== '') { try { db()->prepare('UPDATE partners SET warehouse_id=? WHERE id=?')->execute([$wid,$pid]); } catch (Exception $e) {} }

      // 5. фотографии из заявки переносим в карточку точки
      try { db()->query("ALTER TABLE warehouses ADD COLUMN photos TEXT NULL"); } catch (Exception $e) {}
      try { db()->query("ALTER TABLE warehouses ADD COLUMN descr TEXT NULL"); } catch (Exception $e) {}
      try { db()->query("ALTER TABLE warehouses ADD COLUMN ready TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
      if (!empty($app['photos'])) { try { db()->prepare('UPDATE warehouses SET photos=? WHERE id=?')->execute([$app['photos'],$wid]); } catch (Exception $e) {} }

      // 6. связываем заявку с созданной точкой
      try { db()->query("ALTER TABLE pvz_applications ADD COLUMN warehouse_id VARCHAR(32) NULL"); } catch (Exception $e) {}
      try { db()->prepare('UPDATE pvz_applications SET warehouse_id=? WHERE id=?')->execute([$wid,$id]); } catch (Exception $e) {}

      // 7. координаты по адресу из заявки — чтобы точка сразу была на карте (№264)
      itc_wh_autogeo($wid, true);

      $created = ['warehouse_id'=>$wid,'code'=>$code,'partner_id'=>$pid,'phone'=>$phone,
                  'access_code'=>($ptCode ?? ''), 'name'=>$pname];

      /* СООБЩАЕМ ПАРТНЁРУ ОБ ОДОБРЕНИИ (обновление №212).
         Раньше одобрение заводило партнёра, точку и код доступа — но человек об
         этом не узнавал: код надо было продиктовать вручную, и если сотрудник
         забывал, партнёр просто ждал. Теперь сообщение уходит само.
         Отправка ТИХАЯ: не получилось — заявка всё равно одобрена, а сотрудник
         увидит в ответе, дошло ли, и продиктует код сам. */
      $created['sms_sent'] = 0;
      $created['sms_err']  = '';
      if ($phone !== '' && ($ptCode ?? '') !== '' && function_exists('sms_send')) {
        // Только латиница: кириллица в СМС режет длину втрое и дорожает
        $txt = 'ITC GLOBAL: zayavka odobrena! Punkt vydachi '.$code
             .'. Vhod v kabinet: telefon '.$phone.', kod '.$ptCode.'. itcpartner.store';
        try {
          $r = sms_send($phone, $txt);
          $sok = false;
          if (is_array($r) && (($r['status'] ?? '') === 'OK')) {
            $sok = true;
            if (!empty($r['sms']) && is_array($r['sms'])) {
              $f = reset($r['sms']);
              if (is_array($f) && (($f['status'] ?? '') !== 'OK')) $sok = false;
            }
          }
          $created['sms_sent'] = $sok ? 1 : 0;
          if (!$sok && is_array($r)) $created['sms_err'] = (string)($r['status_text'] ?? ($r['status_code'] ?? ''));
        } catch (Exception $e) { $created['sms_err'] = 'сбой отправки'; }
        itc_log_add($by, 'pvz_app_sms', 'partner', $pid, ($created['sms_sent'] ? 'отправлено ' : 'НЕ отправлено ').$phone);
      }
    }

    try{ db()->prepare("UPDATE pvz_applications SET status=?, decided_by=?, decided_at=NOW() WHERE id=?")->execute([$act, $by, $id]); }
    catch(Exception $e){ fail('Ошибка сохранения'); }
    itc_log_add($by,'pvz_app_'.$act,'pvz_application',$id,($created?('точка '.$created['code']):''));
    jout(['ok'=>true,'status'=>$act,'created'=>$created]);
  }

  // ================= ПРОГРАММА «ТРЕЙДЕР ИТК» =================
  // Таблицы: trader_applications, traders, trader_positions (+ orders.trader_id, orders.trader_fee)

  // ---- Заявка на роль трейдера (публичная подача с экрана входа) ----
  case 'trader_apply': {
    $d=body();
    $name=trim($d['name']??''); $phone=trim($d['phone']??'');
    $inn=preg_replace('/\D/','',(string)($d['inn']??''));
    $bik=preg_replace('/\D/','',(string)($d['bik']??''));
    $acc=preg_replace('/\D/','',(string)($d['account']??''));
    $form=(trim($d['legal_form']??'')==='ИП')?'ИП':'Самозанятый';
    if($name===''||$phone==='') fail('Укажите ФИО и телефон');
    if(strlen($inn)!==12) fail('ИНН должен содержать 12 цифр');
    if(strlen($bik)!==9)  fail('БИК должен содержать 9 цифр');
    if(strlen($acc)!==20) fail('Расчётный счёт должен содержать 20 цифр');
    if(empty($d['pd_consent'])) fail('Нужно согласие на обработку персональных данных');
    // повторная заявка по тому же ИНН, пока предыдущая на рассмотрении
    try{
      $q=db()->prepare("SELECT id FROM trader_applications WHERE inn=? AND status='new' LIMIT 1");
      $q->execute([$inn]);
      if($q->fetch()) fail('Заявка с этим ИНН уже на рассмотрении');
    }catch(Exception $e){}
    $id=gen('tra');
    // открытые реестры: подставляем банк по БИК и проверяем ИП/юрлицо по ИНН
    $bankName=mb_substr(trim($d['bank']??''),0,200); $regInfo='';
    try{ $bk=dadata_call('findById/bank',['query'=>$bik,'count'=>1]);
         if($bk && !empty($bk['suggestions'][0]['value'])) $bankName=mb_substr($bk['suggestions'][0]['value'],0,200); }catch(Exception $e){}
    try{ $pt=dadata_call('findById/party',['query'=>$inn,'count'=>1]);
         if($pt && !empty($pt['suggestions'][0])){
           $pd=$pt['suggestions'][0]['data']??[];
           $regInfo=trim(($pt['suggestions'][0]['value']??'').' · '.($pd['state']['status']??'').(!empty($pd['ogrn'])?' · ОГРН '.$pd['ogrn']:''));
         } else { $regInfo='не найдено в реестре'; } }catch(Exception $e){}
    try{
      db()->prepare('INSERT INTO trader_applications (id,legal_form,ip_name,name,inn,ogrn,phone,email,bik,bank,account,city,goods,promo,comment,pd_consent,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?)')
        ->execute([$id,$form,
          mb_substr(trim($d['ip_name']??''),0,250), mb_substr($name,0,200), $inn,
          preg_replace('/\D/','',(string)($d['ogrn']??'')),
          mb_substr($phone,0,40), mb_substr(trim($d['email']??''),0,200),
          $bik, $bankName, $acc,
          mb_substr(trim($d['city']??''),0,120), mb_substr(trim($d['goods']??''),0,300),
          mb_substr(trim($d['promo']??''),0,300), mb_substr(trim($d['comment']??''),0,500), 'new']);
    }catch(Exception $e){ fail('Не удалось отправить заявку. Возможно, не выполнена миграция trader_applications.'); }
    if($regInfo!==''){ try{ db()->query("ALTER TABLE trader_applications ADD COLUMN reg_info VARCHAR(400) NULL"); }catch(Exception $e){}
      try{ db()->prepare("UPDATE trader_applications SET reg_info=? WHERE id=?")->execute([mb_substr($regInfo,0,400),$id]); }catch(Exception $e){} }
    jout(['ok'=>true]);
  }

  // ---- Список трейдеров и заявок (кабинет босса) ----
  case 'trader_list': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant','accountant','manager']);
    $mask=function($a){ $a=(string)$a; return strlen($a)>4 ? ('•••• '.substr($a,-4)) : $a; };
    $traders=[]; $apps=[];
    try{
      foreach(db()->query("SELECT id,name,legal_form,ip_name,inn,city,phone,email,bank,account,status,UNIX_TIMESTAMP(created_at)*1000 ts FROM traders ORDER BY created_at DESC LIMIT 500")->fetchAll() as $r){
        $r['account_masked']=$mask($r['account']??''); unset($r['account']);
        $r['positions']=0; $r['warehouse']=''; $r['sales30']=0; $r['turnover30']=0; $r['payable']=0;
        $traders[]=$r;
      }
    }catch(Exception $e){}
    // позиции и склад
    try{
      $cnt=[]; $wh=[];
      foreach(db()->query("SELECT trader_id, COUNT(*) c, MAX(warehouse_id) w FROM trader_positions WHERE status='active' GROUP BY trader_id")->fetchAll() as $r){
        $cnt[$r['trader_id']]=(int)$r['c']; $wh[$r['trader_id']]=$r['w'];
      }
      $whName=[];
      try{ foreach(db()->query("SELECT id,name,city FROM warehouses")->fetchAll() as $w){ $whName[$w['id']]=trim(($w['city']??'').' '.($w['name']??'')); } }catch(Exception $e){}
      foreach($traders as &$t){
        $t['positions']=$cnt[$t['id']]??0;
        $wid=$wh[$t['id']]??''; $t['warehouse']=$wid?($whName[$wid]??$wid):'';
      } unset($t);
    }catch(Exception $e){}
    // продажи за 30 дней и сумма к выплате
    try{
      $agg=[];
      foreach(db()->query("SELECT trader_id, COUNT(*) c, SUM(total) s, SUM(trader_fee) f FROM orders WHERE trader_id IS NOT NULL AND trader_id<>'' AND created_at > (NOW() - INTERVAL 30 DAY) GROUP BY trader_id")->fetchAll() as $r) $agg[$r['trader_id']]=$r;
      $pay=[];
      foreach(db()->query("SELECT trader_id, SUM(trader_fee) f FROM orders WHERE trader_id IS NOT NULL AND trader_id<>'' AND paid=1 AND payout_id IS NULL GROUP BY trader_id")->fetchAll() as $r) $pay[$r['trader_id']]=(float)$r['f'];
      foreach($traders as &$t){
        $a=$agg[$t['id']]??null;
        $t['sales30']=$a?(int)$a['c']:0;
        $t['turnover30']=$a?round((float)$a['s']):0;
        $t['payable']=round($pay[$t['id']]??0);
      } unset($t);
    }catch(Exception $e){}
    try{
      $sqlApps="SELECT id,legal_form,ip_name,name,inn,ogrn,phone,email,bik,bank,account,city,goods,promo,comment,status,reg_info,UNIX_TIMESTAMP(created_at)*1000 ts FROM trader_applications ORDER BY (status='new') DESC, created_at DESC LIMIT 300";
      $appRows=[];
      try{ $appRows=db()->query($sqlApps)->fetchAll(); }
      catch(Exception $e2){ $appRows=db()->query(str_replace(',reg_info','',$sqlApps))->fetchAll(); }
      foreach($appRows as $r){
        $r['account_masked']=$mask($r['account']??''); unset($r['account']);
        $apps[]=$r;
      }
    }catch(Exception $e){}
    $tok=dadata_token();
    jout(['ok'=>true,'traders'=>$traders,'apps'=>$apps,
          'dadata'=>['set'=>($tok!==''),'tail'=>($tok!==''?substr($tok,-4):'')]]);
  }

  // ---- Карточка трейдера: его позиции и как они продаются ----
  case 'trader_card': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant','accountant','manager']);
    $id=trim($_GET['id']??''); if($id==='') fail('Нет трейдера');
    $pos=[];
    try{
      $rows=db()->prepare("SELECT p.id, p.product_id, p.warehouse_id, p.markup_pct, pr.name pname, pr.price floor FROM trader_positions p LEFT JOIN products pr ON pr.id=p.product_id WHERE p.trader_id=? AND p.status='active' ORDER BY p.created_at DESC LIMIT 200");
      $rows->execute([$id]);
      $whName=[];
      try{ foreach(db()->query("SELECT id,name,city FROM warehouses")->fetchAll() as $w){ $whName[$w['id']]=trim(($w['city']??'').' '.($w['name']??'')); } }catch(Exception $e){}
      foreach($rows->fetchAll() as $r){
        $floor=(float)($r['floor']??0); $m=(float)($r['markup_pct']??0);
        $st=['sales30'=>0,'turnover30'=>0,'earned'=>0];
        try{
          $q=db()->prepare("SELECT COUNT(*) c, SUM(o.total) s, SUM(o.trader_fee) f FROM orders o JOIN order_items i ON i.order_id=o.id WHERE o.trader_id=? AND i.product_id=? AND o.created_at > (NOW() - INTERVAL 30 DAY)");
          $q->execute([$id,$r['product_id']]);
          $a=$q->fetch();
          if($a){ $st=['sales30'=>(int)$a['c'],'turnover30'=>round((float)$a['s']),'earned'=>round((float)$a['f'])]; }
        }catch(Exception $e){}
        $pos[]=['name'=>$r['pname']??'Товар','warehouse'=>$whName[$r['warehouse_id']]??($r['warehouse_id']??''),
                'floor'=>round($floor),'price'=>round($floor*(1+$m/100)),'markup_pct'=>$m,
                'sales30'=>$st['sales30'],'turnover30'=>$st['turnover30'],'earned'=>$st['earned']];
      }
    }catch(Exception $e){}
    jout(['ok'=>true,'positions'=>$pos]);
  }

  // ---- Решение по заявке: одобрить (создать трейдера) или отклонить ----
  case 'trader_decide': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant']);
    $d=body(); $id=trim($d['id']??'');
    $dec=trim($d['decision']??($d['action']??''));
    $act=($dec==='approve')?'approved':'rejected';
    if($id==='') fail('Нет заявки');
    $by=mb_substr(trim($d['by']??''),0,120);
    try{
      $q=db()->prepare("SELECT * FROM trader_applications WHERE id=?"); $q->execute([$id]); $a=$q->fetch();
    }catch(Exception $e){ $a=null; }
    if(!$a) fail('Заявка не найдена');
    if(($a['status']??'')!=='new') fail('Заявка уже обработана');
    $tid=null;
    if($act==='approved'){
      $tid=gen('trd');
      try{
        db()->prepare('INSERT INTO traders (id,name,legal_form,ip_name,inn,ogrn,phone,email,bik,bank,account,city,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')
          ->execute([$tid,$a['name'],$a['legal_form'],$a['ip_name'],$a['inn'],$a['ogrn'],$a['phone'],$a['email'],$a['bik'],$a['bank'],$a['account'],$a['city'],'active']);
      }catch(Exception $e){ fail('Не удалось создать трейдера. Возможно, не выполнена миграция traders.'); }
    }
    try{ db()->prepare("UPDATE trader_applications SET status=?, decided_by=?, decided_at=NOW(), trader_id=? WHERE id=?")->execute([$act,$by,$tid,$id]); }
    catch(Exception $e){ fail('Ошибка сохранения'); }
    itc_log_add($by,'trader_app_'.$act,'trader_application',$id,'');
    jout(['ok'=>true,'status'=>$act,'trader_id'=>$tid]);
  }


  // ---- Кабинет трейдера: всё для стартового экрана ----
  case 'trader_me': {
    $tid=''; $staffView=false;
    $asId=trim($_GET['as']??'');
    if($asId!==''){ $s=authUser('itc'); require_staff($s,['boss','chief_accountant','accountant','manager']); $tid=$asId; $staffView=true; }
    else { $s=authUser('trader'); $tid=$s['supplier_id']??'';
           if($tid===''){ try{ $q=db()->prepare("SELECT id FROM traders WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') LIMIT 1"); $q->execute([$s['phone']??'']); $tid=$q->fetchColumn()?:''; }catch(Exception $e){} } }
    if($tid==='') fail('Трейдер не найден');

    $trader=null;
    try{ $q=db()->prepare("SELECT id,name,legal_form,ip_name,inn,phone,email,city,bank,account,status,UNIX_TIMESTAMP(created_at)*1000 ts FROM traders WHERE id=?"); $q->execute([$tid]); $trader=$q->fetch()?:null; }catch(Exception $e){}
    if(!$trader) fail('Трейдер не найден');
    $acc=(string)($trader['account']??''); $trader['account_masked']=strlen($acc)>4?('•••• '.substr($acc,-4)):$acc; unset($trader['account']);

    // склады: все российские + мои
    $allWh=[]; $myWh=[];
    try{ $rowsW=[];
      try{ $rowsW=db()->query("SELECT id,code,name,city,country,region FROM warehouses ORDER BY city, name")->fetchAll(); }
      catch(Exception $e2){ $rowsW=db()->query("SELECT id,code,name,city,country FROM warehouses ORDER BY city, name")->fetchAll(); }
      foreach($rowsW as $w){
        if(($w['country']??'RU')!=='RU') continue;
        $reg=trim((string)($w['region']??'')); if($reg==='') $reg=$w['city']??'';
        $allWh[]=['id'=>$w['id'],'name'=>trim(($w['city']??'').' · '.($w['name']??'')),'city'=>$w['city']??'','region'=>$reg];
      } }catch(Exception $e){}
    try{ $q=db()->prepare("SELECT DISTINCT warehouse_id FROM trader_positions WHERE trader_id=?"); $q->execute([$tid]);
         foreach($q->fetchAll() as $r){ $myWh[]=$r['warehouse_id']; } }catch(Exception $e){}
    try{ $q=db()->prepare("SELECT warehouse_id FROM trader_warehouses WHERE trader_id=?"); $q->execute([$tid]);
         foreach($q->fetchAll() as $r){ if(!in_array($r['warehouse_id'],$myWh,true)) $myWh[]=$r['warehouse_id']; } }catch(Exception $e){}

    // позиции и заявки на позиции
    $pos=[];
    try{
      $q=db()->prepare("SELECT p.id,p.product_id,p.warehouse_id,p.markup_pct,p.status,p.req_name,p.req_desc,p.req_photo,p.req_price,UNIX_TIMESTAMP(p.created_at)*1000 ts, pr.name pname, pr.price floor FROM trader_positions p LEFT JOIN products pr ON pr.id=p.product_id WHERE p.trader_id=? ORDER BY p.created_at DESC LIMIT 300");
      $q->execute([$tid]);
      foreach($q->fetchAll() as $r){
        $floor=(float)($r['floor']??0); $m=(float)($r['markup_pct']??0);
        $price=$floor>0?round($floor*(1+$m/100)):0;
        $delta=$price-$floor;
        $sales=0; $earned=0;
        if(($r['status']??'')==='active' && $r['product_id']){
          try{ $q2=db()->prepare("SELECT COUNT(*) c, SUM(o.trader_fee) f FROM orders o JOIN order_items i ON i.order_id=o.id WHERE o.trader_id=? AND i.product_id=? AND o.created_at > (NOW() - INTERVAL 30 DAY)");
               $q2->execute([$tid,$r['product_id']]); $a=$q2->fetch();
               if($a){ $sales=(int)$a['c']; $earned=round((float)$a['f']); } }catch(Exception $e){}
        }
        $pos[]=['id'=>$r['id'],'status'=>$r['status'],'warehouse_id'=>$r['warehouse_id'],
                'name'=>($r['pname']??($r['req_name']??'Товар')),'floor'=>round($floor),'markup_pct'=>$m,
                'price'=>$price,'delta'=>round($delta),'payout'=>round($delta/1.22),
                'req_price'=>round((float)($r['req_price']??0)),'req_desc'=>$r['req_desc']??'','req_photo'=>$r['req_photo']??'',
                'sales30'=>$sales,'earned'=>$earned,'ts'=>$r['ts']];
      }
    }catch(Exception $e){}

    // деньги
    $bal=['earned'=>0,'reserve'=>0,'payable'=>0,'paid'=>0];
    try{
      $q=db()->prepare("SELECT SUM(trader_fee) f FROM orders WHERE trader_id=? AND paid=1"); $q->execute([$tid]); $bal['earned']=round((float)$q->fetchColumn());
      $q=db()->prepare("SELECT SUM(trader_fee) f FROM orders WHERE trader_id=? AND paid=1 AND payout_id IS NULL"); $q->execute([$tid]); $bal['payable']=round((float)$q->fetchColumn());
      $bal['paid']=$bal['earned']-$bal['payable'];
    }catch(Exception $e){}

    // статистика по QR за 30 дней
    $stats=['click'=>0,'install'=>0,'register'=>0,'order'=>0];
    try{
      $q=db()->prepare("SELECT kind, COUNT(*) c FROM trader_hits WHERE trader_id=? AND created_at > (NOW() - INTERVAL 30 DAY) GROUP BY kind");
      $q->execute([$tid]);
      foreach($q->fetchAll() as $r){ $stats[$r['kind']]=(int)$r['c']; }
    }catch(Exception $e){}
    try{
      $q=db()->prepare("SELECT COUNT(*) c FROM orders WHERE trader_id=? AND paid=1 AND created_at > (NOW() - INTERVAL 30 DAY)");
      $q->execute([$tid]); $stats['order']=(int)$q->fetchColumn();
    }catch(Exception $e){}
    jout(['ok'=>true,'trader'=>$trader,'all_wh'=>$allWh,'my_wh'=>$myWh,'positions'=>$pos,'balance'=>$bal,'stats'=>$stats,'site'=>'https://itcpartner.store','staff_view'=>$staffView,'markup_max'=>30]);
  }

  // ---- Трейдер добавляет себе склад ----
  case 'trader_wh_add': {
    $s=authUser('trader'); $tid=$s['supplier_id']??''; if($tid==='') fail('Трейдер не найден');
    $d=body(); $w=trim($d['warehouse_id']??''); if($w==='') fail('Выберите склад');
    try{ db()->prepare("INSERT INTO trader_warehouses (id,trader_id,warehouse_id) VALUES (?,?,?)")->execute([gen('trw'),$tid,$w]); }
    catch(Exception $e){ /* уже добавлен — не считаем ошибкой */ }
    jout(['ok'=>true]);
  }

  // ---- Трейдер подаёт заявку на товар ----
  case 'trader_pos_apply': {
    $s=authUser('trader'); $tid=$s['supplier_id']??''; if($tid==='') fail('Трейдер не найден');
    $d=body();
    $name=trim($d['name']??''); $w=trim($d['warehouse_id']??'');
    if($name==='') fail('Укажите название товара');
    if($w==='') fail('Выберите склад');
    $open=0;
    try{ $q=db()->prepare("SELECT COUNT(*) c FROM trader_positions WHERE trader_id=? AND status='new'"); $q->execute([$tid]); $open=(int)$q->fetchColumn(); }catch(Exception $e){}
    if($open>=5) fail('Уже 5 заявок на рассмотрении. Дождитесь решения по ним.');
    $cnt=0;
    try{ $q=db()->prepare("SELECT COUNT(*) c FROM trader_positions WHERE trader_id=? AND status='active'"); $q->execute([$tid]); $cnt=(int)$q->fetchColumn(); }catch(Exception $e){}
    if($cnt>=10) fail('Достигнут предел — 10 позиций. Освободите одну, чтобы добавить новую.');
    try{
      db()->prepare("INSERT INTO trader_positions (id,trader_id,warehouse_id,status,req_name,req_desc,req_photo,req_price) VALUES (?,?,?,'new',?,?,?,?)")
        ->execute([gen('trp'),$tid,$w,mb_substr($name,0,250),mb_substr(trim($d['desc']??''),0,1000),mb_substr(trim($d['photo']??''),0,500),(float)($d['price']??0)]);
    }catch(Exception $e){ fail('Не удалось отправить заявку. Возможно, не выполнена миграция trader_positions.'); }
    jout(['ok'=>true]);
  }

  // ---- Трейдер меняет свою надбавку ----
  case 'trader_markup_set': {
    $s=authUser('trader'); $tid=$s['supplier_id']??''; if($tid==='') fail('Трейдер не найден');
    $d=body(); $id=trim($d['id']??''); $m=(float)($d['markup_pct']??0);
    if($id==='') fail('Нет позиции');
    if($m<0) $m=0; if($m>30) fail('Максимальная надбавка — 30%');
    try{ db()->prepare("UPDATE trader_positions SET markup_pct=? WHERE id=? AND trader_id=?")->execute([$m,$id,$tid]); }
    catch(Exception $e){ fail('Не удалось сохранить'); }
    jout(['ok'=>true,'markup_pct'=>$m]);
  }


  // ---- Привязать акцию к QR-кампании (со стороны QR) ----
  case 'mkt_promo_bind': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body(); $tag=mb_substr(trim($d['tag']??''),0,60); $pid=trim($d['promo_id']??'');
    if($tag==='') fail('Нет кампании');
    try{
      itc_mkt_promo_ensure();
      /* Меняем ТОЛЬКО этот QR-код. Другие коды, ведущие на ту же акцию,
         остаются как были — в этом весь смысл. */
      db()->prepare("UPDATE mkt_campaign SET promo_id=? WHERE tag=?")->execute([($pid!==''?$pid:null), $tag]);
    }catch(Exception $e){ fail('Не удалось сохранить'); }
    jout(['ok'=>true]);
  }


  // ============ АКЦИИ КАК КАМПАНИИ ============
  // promos — сама акция (название, срок, привязка к рекламной кампании/QR)
  // promo_items — товары внутри неё
  // products.promo_until — производное поле: до какой даты товар в акции (максимум по всем акциям)
  case 'promos_list': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor','moderator']);
    $rows=[]; $mkt=[];
    try{
      foreach(db()->query("SELECT p.*, (SELECT COUNT(*) FROM promo_items i WHERE i.promo_id=p.id) items,
        (p.ends_at > NOW()) active FROM promos p WHERE p.status<>'deleted' ORDER BY p.created_at DESC LIMIT 200")->fetchAll() as $r) $rows[]=$r;
    }catch(Exception $e){}
    try{ foreach(db()->query("SELECT tag,name FROM mkt_campaign ORDER BY created_at DESC LIMIT 100")->fetchAll() as $r) $mkt[]=$r; }catch(Exception $e){}
    /* У акции может быть несколько QR-кодов — по одному на регион. Отдаём весь
       список; mkt_tag оставляем первым кодом, чтобы старые места не сломались. */
    $tagsBy = itc_promo_tags();
    foreach($rows as &$_r){
      $_r['mkt_tags'] = $tagsBy[$_r['id']] ?? [];
      $_r['mkt_tag']  = $_r['mkt_tags'][0] ?? '';
    } unset($_r);
    jout(['ok'=>true,'promos'=>$rows,'mkt'=>$mkt]);
  }

  case 'promo_save': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body(); $id=trim($d['id']??'');
    $title=mb_substr(trim($d['title']??''),0,150);
    $days=(int)($d['days']??0); if($days<1) $days=1; if($days>365) $days=365;
    $tag=mb_substr(trim($d['mkt_tag']??''),0,60);
    if($title==='') fail('Укажите название акции');
    try{
      if($id!==''){
        db()->prepare("UPDATE promos SET title=?, days=?, ends_at=DATE_ADD(NOW(), INTERVAL ? DAY) WHERE id=?")
          ->execute([$title,$days,$days,$id]);
      } else {
        $id=gen('pr');
        db()->prepare("INSERT INTO promos (id,title,days,ends_at,created_by) VALUES (?,?,?,DATE_ADD(NOW(), INTERVAL ? DAY),?)")
          ->execute([$id,$title,$days,$days,mb_substr(trim($d['by']??''),0,120)]);
      }
      /* Выбранный здесь QR-код ДОБАВЛЯЕТСЯ к акции. Остальные её коды не
         трогаем — снять код можно на экране QR-кампаний. */
      itc_mkt_promo_ensure();
      if($tag!=='') { try{ db()->prepare("UPDATE mkt_campaign SET promo_id=? WHERE tag=?")->execute([$id,$tag]); }catch(Exception $e){} }
    }catch(Exception $e){ fail('Не удалось сохранить. Возможно, не выполнена миграция promos.'); }
    promo_sync_products($id);
    jout(['ok'=>true,'id'=>$id]);
  }

  case 'promo_delete': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body(); $id=trim($d['id']??''); if($id==='') fail('Нет акции');
    $pids=[];
    try{ $q=db()->prepare("SELECT product_id FROM promo_items WHERE promo_id=?"); $q->execute([$id]); foreach($q->fetchAll() as $r) $pids[]=$r['product_id']; }catch(Exception $e){}
    try{ db()->prepare("UPDATE promos SET status='deleted' WHERE id=?")->execute([$id]);
         db()->prepare("DELETE FROM promo_items WHERE promo_id=?")->execute([$id]); }catch(Exception $e){ fail('Не удалось удалить'); }
    foreach($pids as $pid) promo_touch_product($pid);
    jout(['ok'=>true]);
  }

  case 'promo_items': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor','moderator']);
    $id=trim($_GET['id']??''); if($id==='') fail('Нет акции');
    $ids=[];
    try{ $q=db()->prepare("SELECT product_id FROM promo_items WHERE promo_id=?"); $q->execute([$id]); foreach($q->fetchAll() as $r) $ids[]=$r['product_id']; }catch(Exception $e){}
    jout(['ok'=>true,'product_ids'=>$ids]);
  }

  case 'promo_item_toggle': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body(); $id=trim($d['promo_id']??''); $pid=trim($d['product_id']??'');
    if($id===''||$pid==='') fail('Нет акции или товара');
    $in=false;
    try{ $q=db()->prepare("SELECT id FROM promo_items WHERE promo_id=? AND product_id=?"); $q->execute([$id,$pid]); $in=(bool)$q->fetchColumn(); }catch(Exception $e){}
    try{
      if($in) db()->prepare("DELETE FROM promo_items WHERE promo_id=? AND product_id=?")->execute([$id,$pid]);
      else    db()->prepare("INSERT INTO promo_items (id,promo_id,product_id) VALUES (?,?,?)")->execute([gen('pi'),$id,$pid]);
    }catch(Exception $e){ fail('Не удалось сохранить'); }
    promo_touch_product($pid);
    $until='';
    try{ $q=db()->prepare("SELECT promo_until FROM products WHERE id=?"); $q->execute([$pid]); $until=(string)$q->fetchColumn(); }catch(Exception $e){}
    jout(['ok'=>true,'in'=>!$in,'promo_until'=>$until]);
  }


  // ---- АКЦИИ: поставить товар в акцию на N дней или снять ----
  case 'promo_set': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor','moderator']);
    $d=body(); $pid=trim($d['product_id']??''); $days=(int)($d['days']??0);
    if($pid==='') fail('Нет товара');
    try{ db()->query("ALTER TABLE products ADD COLUMN promo_until DATETIME NULL"); }catch(Exception $e){}
    try{
      if($days>0){
        if($days>365) $days=365;
        db()->prepare("UPDATE products SET promo_until = DATE_ADD(NOW(), INTERVAL ? DAY) WHERE id=?")->execute([$days,$pid]);
      } else {
        db()->prepare("UPDATE products SET promo_until = NULL WHERE id=?")->execute([$pid]);
      }
    }catch(Exception $e){ fail('Не удалось сохранить'); }
    $until='';
    try{ $q=db()->prepare("SELECT promo_until FROM products WHERE id=?"); $q->execute([$pid]); $until=(string)$q->fetchColumn(); }catch(Exception $e){}
    itc_log_add(mb_substr(trim($d['by']??''),0,120),$days>0?'promo_on':'promo_off','product',$pid,(string)$days);
    jout(['ok'=>true,'promo_until'=>$until]);
  }


  // ============ ФАБРИКИ-ПОСТАВЩИКИ JINJIA (прямой контракт) ============
  // Закупочные фабрики: у них мы покупаем через Jinjia по прямому контракту.
  // Это НЕ продавцы маркетплейса. Контакты видят только менеджер, босс и бухгалтер.
  case 'jfact_list': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor','chief_accountant','accountant']);
    $rows=[]; $sups=[];
    try{
      foreach(db()->query("SELECT f.*, (SELECT COUNT(*) FROM products p WHERE p.jfactory_id=f.id) products FROM jfactories f WHERE f.status<>'deleted' ORDER BY f.created_at DESC LIMIT 500")->fetchAll() as $r) $rows[]=$r;
    }catch(Exception $e){}
    try{ foreach(db()->query("SELECT id,name FROM suppliers ORDER BY name LIMIT 300")->fetchAll() as $r) $sups[]=$r; }catch(Exception $e){}
    jout(['ok'=>true,'factories'=>$rows,'suppliers'=>$sups]);
  }

  case 'jfact_save': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    try { db()->query("ALTER TABLE jfactories ADD COLUMN contract_url VARCHAR(300) NULL"); } catch (Exception $e) {}
    try { db()->query("ALTER TABLE jfactories ADD COLUMN card_url VARCHAR(300) NULL"); } catch (Exception $e) {}   // фото визитки
    $d=body(); $id=trim($d['id']??'');
    $name=trim($d['name']??''); if($name==='') fail('Укажите название фабрики');
    $f=[ 'name'=>mb_substr($name,0,200),
         'name_zh'=>mb_substr(trim($d['name_zh']??''),0,200),
         'site'=>mb_substr(trim($d['site']??''),0,200),
         'contact_person'=>mb_substr(trim($d['contact_person']??''),0,120),
         'phone'=>mb_substr(trim($d['phone']??''),0,60),
         'wechat'=>mb_substr(trim($d['wechat']??''),0,60),
         'whatsapp'=>mb_substr(trim($d['whatsapp']??''),0,60),
         'email'=>mb_substr(trim($d['email']??''),0,120),
         'city'=>mb_substr(trim($d['city']??''),0,120),
         'address'=>mb_substr(trim($d['address']??''),0,300),
         'pay_moment'=>mb_substr(trim($d['pay_moment']??''),0,40),
         'cn_vat'=>mb_substr(trim($d['cn_vat']??''),0,10),
         'supplier_id'=>mb_substr(trim($d['supplier_id']??''),0,40),
         'contract_url'=>mb_substr(trim($d['contract_url']??''),0,300),
         'card_url'=>mb_substr(trim($d['card_url']??''),0,300),
         'note'=>mb_substr(trim($d['note']??''),0,1000) ];
    try{
      if($id!==''){
        $set=implode(',', array_map(function($k){return "$k=?";}, array_keys($f)));
        $st=db()->prepare("UPDATE jfactories SET $set WHERE id=?");
        $st->execute(array_merge(array_values($f),[$id]));
      } else {
        $id=gen('jf');
        $cols=implode(',', array_keys($f));
        $qs=implode(',', array_fill(0,count($f),'?'));
        db()->prepare("INSERT INTO jfactories (id,$cols,created_by) VALUES (?,$qs,?)")
          ->execute(array_merge([$id],array_values($f),[mb_substr(trim($d['by']??''),0,120)]));
      }
    }catch(Exception $e){ fail('Не удалось сохранить. Возможно, не выполнена миграция jfactories.'); }
    jout(['ok'=>true,'id'=>$id]);
  }

  case 'jfact_prods': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor','chief_accountant','accountant']);
    $id=trim($_GET['id']??''); if($id==='') fail('Нет фабрики');
    $rows=[];
    try{
      $q=db()->prepare("SELECT id,name,cat,price,goods_cny,volume_m3,weight_kg,img,stock,UNIX_TIMESTAMP(created_at)*1000 ts FROM products WHERE jfactory_id=? ORDER BY created_at DESC LIMIT 500");
      $q->execute([$id]); $rows=$q->fetchAll();
    }catch(Exception $e){}
    jout(['ok'=>true,'products'=>$rows]);
  }

  case 'jfact_prod_save': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body();
    $fid=trim($d['jfactory_id']??''); if($fid==='') fail('Нет фабрики');
    $name=trim($d['name']??''); if($name==='') fail('Укажите название товара');
    $price=(int)round((float)($d['price']??0)); if($price<=0) fail('Не рассчитана цена продажи');
    $sup='';
    try{ $q=db()->prepare("SELECT supplier_id FROM jfactories WHERE id=?"); $q->execute([$fid]); $sup=(string)$q->fetchColumn(); }catch(Exception $e){}
    // поставщик необязателен: пусто = товар от имени самой ИТК
    $gal=$d['gallery']??[]; if(!is_array($gal)) $gal=[];
    $cover=trim($d['img']??''); if($cover===''&&count($gal)) $cover=(string)$gal[0];
    $pid=gen('p');
    try{
      db()->prepare('INSERT INTO products(id,supplier_id,jfactory_id,cat,subcat,name,price,goods_cny,volume_m3,weight_kg,descr,img,gallery,stock,original,mod_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?)')
        ->execute([$pid,$sup,$fid,trim($d['cat']??'Прочее'),trim($d['subcat']??''),mb_substr($name,0,250),
                   $price,(int)($d['goods_cny']??0),(float)($d['volume_m3']??0),(float)($d['weight_kg']??0),
                   mb_substr(trim($d['descr']??''),0,4000),$cover,
                   json_encode($gal,JSON_UNESCAPED_UNICODE),(int)($d['stock']??0),'approved']);
    }catch(Exception $e){ fail('Не удалось сохранить товар. Возможно, не выполнена миграция products.jfactory_id.'); }
    try{ stamp_creator($pid,$s); }catch(Exception $e){}
    itc_log_add(mb_substr(trim($d['by']??''),0,120),'jfact_product_add','product',$pid,$fid);
    jout(['ok'=>true,'id'=>$pid]);
  }


  // ================= DaData: открытые данные по БИК и ИНН =================
  // Ключ хранится в settings под ключом dadata_token. Запросы идут с сервера,
  // чтобы ключ не светился в браузере.
  case 'dadata_token_set': {
    $sx=authUser('itc'); require_staff($sx,['boss']);
    $d=body(); $tok=trim($d['token']??'');
    try{ db()->prepare("INSERT INTO settings (k,v) VALUES ('dadata_token',?) ON DUPLICATE KEY UPDATE v=VALUES(v)")->execute([$tok]); }
    catch(Exception $e){ fail('Не удалось сохранить ключ'); }
    jout(['ok'=>true,'set'=>($tok!=='')]);
  }

  case 'bank_by_bik': {
    $bik=preg_replace('/\D/','',(string)($_GET['bik']??''));
    if(strlen($bik)!==9) jout(['ok'=>false,'error'=>'БИК должен содержать 9 цифр']);
    $r=dadata_call('findById/bank',['query'=>$bik,'count'=>1]);
    if(!$r||empty($r['suggestions'][0])) jout(['ok'=>false,'error'=>'Банк не найден']);
    $b=$r['suggestions'][0]; $dt=$b['data']??[];
    jout(['ok'=>true,'name'=>$b['value']??'','bik'=>$dt['bic']??$bik,
          'corr'=>$dt['correspondent_account']??'','city'=>($dt['address']['data']['city']??''),
          'status'=>$dt['state']['status']??'']);
  }

  case 'party_by_inn': {
    $inn=preg_replace('/\D/','',(string)($_GET['inn']??''));
    if(strlen($inn)<10) jout(['ok'=>false,'error'=>'ИНН указан неверно']);
    $r=dadata_call('findById/party',['query'=>$inn,'count'=>1]);
    if(!$r||empty($r['suggestions'][0])) jout(['ok'=>false,'error'=>'Не найдено в реестре']);
    $b=$r['suggestions'][0]; $dt=$b['data']??[];
    jout(['ok'=>true,'name'=>$b['value']??'','full_name'=>($dt['name']['full_with_opf']??''),
          'ogrn'=>$dt['ogrn']??'','type'=>$dt['type']??'','status'=>($dt['state']['status']??''),
          'address'=>($dt['address']['value']??'')]);
  }


  // ---- Отметка перехода по QR/ссылке трейдера (публично) ----
  case 'trader_hit': {
    $d=body(); $tid=trim($d['trader_id']??''); $kind=trim($d['kind']??'click');
    if($tid==='') jout(['ok'=>true]);
    if(!in_array($kind,['click','install','register'],true)) $kind='click';
    try{ db()->prepare("INSERT INTO trader_hits (id,trader_id,kind,product_id) VALUES (?,?,?,?)")
      ->execute([gen('trh'),$tid,$kind,mb_substr(trim($d['product_id']??''),0,40)]); }catch(Exception $e){}
    jout(['ok'=>true]);
  }


  // ---- Цены трейдеров для склада получения (публично, для витрины) ----
  case 'trader_prices': {
    $wh=trim($_GET['wh']??''); $out=[];
    if($wh!==''){
      try{
        $q=db()->prepare("SELECT p.product_id, p.markup_pct FROM trader_positions p JOIN warehouses w ON w.id=p.warehouse_id WHERE p.status='active' AND p.product_id IS NOT NULL AND p.product_id<>'' AND LOWER(TRIM(COALESCE(NULLIF(w.region,''),w.city)))=(SELECT LOWER(TRIM(COALESCE(NULLIF(region,''),city))) FROM warehouses WHERE id=?)");
        $q->execute([$wh]);
        foreach($q->fetchAll() as $r){ if((float)$r['markup_pct']>0) $out[$r['product_id']]=(float)$r['markup_pct']; }
      }catch(Exception $e){
        try{
          $q=db()->prepare("SELECT p.product_id, p.markup_pct FROM trader_positions p JOIN warehouses w ON w.id=p.warehouse_id WHERE p.status='active' AND p.product_id IS NOT NULL AND p.product_id<>'' AND LOWER(TRIM(w.city))=(SELECT LOWER(TRIM(city)) FROM warehouses WHERE id=?)");
          $q->execute([$wh]);
          foreach($q->fetchAll() as $r){ if((float)$r['markup_pct']>0) $out[$r['product_id']]=(float)$r['markup_pct']; }
        }catch(Exception $e2){}
      }
    }
    jout(['ok'=>true,'wh'=>$wh,'markups'=>$out]);
  }

  // ---- Заявки трейдеров на товар: список для менеджера/бухгалтера/босса ----
  case 'trader_reqs': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant','accountant','manager','supervisor','moderator']);
    $rows=[];
    try{
      foreach(db()->query("SELECT p.id,p.trader_id,p.warehouse_id,p.status,p.req_name,p.req_desc,p.req_photo,p.req_price,p.product_id,p.markup_pct,UNIX_TIMESTAMP(p.created_at)*1000 ts, t.name tname, t.phone tphone, t.city tcity, w.name wname, w.city wcity, pr.name pname, pr.price pprice FROM trader_positions p LEFT JOIN traders t ON t.id=p.trader_id LEFT JOIN warehouses w ON w.id=p.warehouse_id LEFT JOIN products pr ON pr.id=p.product_id ORDER BY (p.status='new') DESC, p.created_at DESC LIMIT 300")->fetchAll() as $r){
        $r['warehouse']=trim(($r['wcity']??'').' · '.($r['wname']??''));
        unset($r['wname'],$r['wcity']);
        $rows[]=$r;
      }
    }catch(Exception $e){}
    $pending=0; foreach($rows as $r){ if(($r['status']??'')==='new')$pending++; }
    jout(['ok'=>true,'reqs'=>$rows,'pending'=>$pending]);
  }

  // ---- Решение по заявке на товар ----
  case 'trader_req_decide': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant','manager','supervisor']);
    $d=body(); $id=trim($d['id']??''); $dec=trim($d['decision']??'');
    if($id==='') fail('Нет заявки');
    if($dec==='approve'){
      $pid=trim($d['product_id']??'');
      if($pid==='') fail('Укажите код товара из каталога');
      $ok=false;
      try{ $q=db()->prepare("SELECT id FROM products WHERE id=?"); $q->execute([$pid]); $ok=(bool)$q->fetchColumn(); }catch(Exception $e){}
      if(!$ok) fail('Товар с таким кодом не найден в каталоге');
      // один и тот же товар в одном регионе — только один трейдер
      try{
        $q=db()->prepare("SELECT p.id FROM trader_positions p JOIN warehouses w ON w.id=p.warehouse_id WHERE p.status='active' AND p.product_id=? AND LOWER(TRIM(COALESCE(NULLIF(w.region,''),w.city)))=(SELECT LOWER(TRIM(COALESCE(NULLIF(w2.region,''),w2.city))) FROM trader_positions p2 JOIN warehouses w2 ON w2.id=p2.warehouse_id WHERE p2.id=?) AND p.id<>? LIMIT 1");
        $q->execute([$pid,$id,$id]);
        if($q->fetchColumn()) fail('Этот товар уже ведёт другой трейдер на этом складе');
      }catch(Exception $e){}
      try{ db()->prepare("UPDATE trader_positions SET product_id=?, status='active', approved_at=NOW() WHERE id=?")->execute([$pid,$id]); }
      catch(Exception $e){ fail('Не удалось сохранить'); }
      itc_log_add(mb_substr(trim($d['by']??''),0,120),'trader_pos_approved','trader_position',$id,$pid);
      jout(['ok'=>true,'status'=>'active']);
    }
    try{ db()->prepare("UPDATE trader_positions SET status='rejected' WHERE id=?")->execute([$id]); }
    catch(Exception $e){ fail('Не удалось сохранить'); }
    itc_log_add(mb_substr(trim($d['by']??''),0,120),'trader_pos_rejected','trader_position',$id,'');
    jout(['ok'=>true,'status'=>'rejected']);
  }

  // ---- Реестр выплат трейдерам (бухгалтерия) ----
  case 'trader_payouts': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant','accountant']);
    $rows=[];
    try{
      foreach(db()->query("SELECT t.id,t.name,t.legal_form,t.inn,t.bank,t.account,t.phone, COALESCE(SUM(CASE WHEN o.paid=1 AND o.payout_id IS NULL THEN o.trader_fee ELSE 0 END),0) payable, COALESCE(SUM(CASE WHEN o.paid=1 THEN o.trader_fee ELSE 0 END),0) earned FROM traders t LEFT JOIN orders o ON o.trader_id=t.id GROUP BY t.id ORDER BY payable DESC")->fetchAll() as $r){
        $acc=(string)($r['account']??''); $r['account_masked']=strlen($acc)>4?('•••• '.substr($acc,-4)):$acc;
        $rows[]=$r;
      }
    }catch(Exception $e){}
    jout(['ok'=>true,'rows'=>$rows,'threshold'=>30000]);
  }

  // ---- Отметить выплату трейдеру ----
  case 'trader_payout_do': {
    $s=authUser('itc'); require_staff($s,['boss','chief_accountant']);
    $d=body(); $tid=trim($d['trader_id']??''); if($tid==='') fail('Нет трейдера');
    $pid=gen('tpay'); $sum=0;
    try{
      $q=db()->prepare("SELECT COALESCE(SUM(trader_fee),0) s FROM orders WHERE trader_id=? AND paid=1 AND payout_id IS NULL"); $q->execute([$tid]); $sum=round((float)$q->fetchColumn());
      if($sum<=0) fail('Нечего выплачивать');
      db()->prepare("UPDATE orders SET payout_id=? WHERE trader_id=? AND paid=1 AND payout_id IS NULL")->execute([$pid,$tid]);
    }catch(Exception $e){ fail('Не удалось провести выплату'); }
    itc_log_add(mb_substr(trim($d['by']??''),0,120),'trader_payout','trader',$tid,(string)$sum);
    jout(['ok'=>true,'payout_id'=>$pid,'sum'=>$sum]);
  }


  /* Массовый перенос товаров в другую категорию.
     Пришли ложки, лежащие в «Столах» — отмечаем галочками и переносим пачкой,
     не открывая каждую карточку. Одним UPDATE, чтобы не долбить базу по строке. */
  case 'products_move_cat': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','moderator']);
    $d = body();
    $ids = $d['ids'] ?? [];
    if (!is_array($ids) || !count($ids)) fail('Не выбрано ни одного товара');
    $ids = array_values(array_filter(array_map(function($x){ return trim((string)$x); }, $ids), function($x){ return $x !== ''; }));
    if (!count($ids)) fail('Не выбрано ни одного товара');
    if (count($ids) > 500) fail('За один раз не больше 500 товаров');
    $cat = trim((string)($d['cat'] ?? ''));
    if ($cat === '') fail('Не выбрана категория');
    $sub = trim((string)($d['subcat'] ?? ''));
    $moved = 0;
    try {
      $ph = implode(',', array_fill(0, count($ids), '?'));
      $sql = 'UPDATE products SET cat=?'.($sub !== '' ? ', subcat=?' : '')." WHERE id IN ($ph)";
      $args = ($sub !== '') ? array_merge([$cat, $sub], $ids) : array_merge([$cat], $ids);
      $q = db()->prepare($sql);
      $q->execute($args);
      $moved = (int)$q->rowCount();
    } catch (Exception $e) { fail('Не удалось перенести: '.$e->getMessage()); }
    try { itc_log_add(mb_substr(trim((string)($d['by'] ?? '')), 0, 120), 'products_move_cat', 'cat', $cat, (string)$moved); } catch (Exception $e) {}
    jout(['ok'=>true, 'moved'=>$moved, 'asked'=>count($ids), 'cat'=>$cat]);
  }

  /* Флаг видимости: показ состояния, заполнение и ночная сверка.
     Без параметров — только показывает. ?fill=1 — заполняет пачкой.
     ?cron=1 — то же для расписания, коротким ответом. */
  case 'itc_vis': {
    $cron_key = trim($_GET['cron_key'] ?? ''); $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
    if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
    @set_time_limit(600);
    header('Content-Type: text/plain; charset=utf-8');
    itc_vis_ensure();

    $cron = !empty($_GET['cron']);
    if ($cron) {
      /* Ночная сверка: молча подчищает расхождения. Нужна и при работающих
         триггерах — на случай прямых правок в базе мимо приложения. */
      $n = itc_vis_fill(50000);
      if (itc_vis_wrong() === 0) itc_vis_ready(true);
      echo "vis_fixed={$n}\n"; exit;
    }

    echo "=== ФЛАГ ВИДИМОСТИ ===\n";
    echo 'Триггеры базы: '.(itc_vis_triggers_ok() ? 'работают — флаг держится сам' : 'НЕ СОЗДАНЫ (нет прав) — нужна ночная сверка')."\n";

    if (!empty($_GET['fill'])) {
      $a = microtime(true);
      $n = itc_vis_fill(50000);
      echo 'Пересчитано строк: '.$n.' за '.round((microtime(true)-$a)*1000)." мс\n";
    }

    $wrong = itc_vis_wrong();
    echo 'Расходится с правдой: '.$wrong."\n";
    if ($wrong === 0) { itc_vis_ready(true); echo "Флаг заполнен целиком — витрина переведена на него.\n"; }
    elseif ($wrong > 0) { echo "Пока не переводим витрину. Откройте ссылку с &fill=1 (можно несколько раз).\n"; }

    $a = microtime(true); $vc = 0;
    try { $vc = (int)db()->query('SELECT COUNT(*) FROM products WHERE vis=1')->fetchColumn(); } catch (Exception $e) {}
    echo "\nСчёт по флагу: {$vc} видимых за ".round((microtime(true)-$a)*1000)." мс   <- было 836 мс\n";

    $a = microtime(true);
    try { db()->query("SELECT id,name,price,img FROM products WHERE vis=1 ORDER BY created_at DESC, id DESC LIMIT 60")->fetchAll(); } catch (Exception $e) {}
    echo 'Первая страница по флагу: '.round((microtime(true)-$a)*1000)." мс\n";

    echo "\nНочная сверка (добавить в расписание раз в сутки):\n";
    echo "  0 4 * * * curl -s \"https://itcpartner.store/api/api.php?action=itc_vis&cron=1\" > /dev/null\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* БАННЕРЫ ОТДЕЛЬНО И БЫСТРО.
     Раньше баннеры приезжали внутри большого общего ответа, а он у покупателя
     стартует после первой страницы витрины — баннер появлялся с задержкой.
     Эта выдача крошечная и запрашивается первым делом. */
  case 'banners_lite': {
    $abBg = false;   // №314 · пора обновить или очередь застряла — отдаём баннеры и дорисовываем после ответа
    try { $abc = ab_cfg(); $abj = ab_job_get(); if ($abc['on'] && time() - $abc['last'] > $abc['days'] * 86400 && !$abj) { $rr = ab_start(); $abBg = !empty($rr['ok']); } elseif ($abj && time() - (int)($abj['t'] ?? 0) > 240 && ab_lock_free()) $abBg = true; } catch (Throwable $e) {}   // №350 · пора обновить автобаннеры — запускаем в фоне
    $b = [];
    try {
      $b = db()->query('SELECT id,title,subtitle,img,link,pos_title,pos_sub,font_title,font_sub,size_title,size_sub,img_zoom,img_focus_x,img_focus_y
                        FROM banners WHERE active=1 AND (start_at IS NULL OR start_at <= CURDATE())
                        AND (end_at IS NULL OR end_at >= CURDATE()) ORDER BY sort, created_at')->fetchAll();
    } catch (Exception $e) {
      try { $b = db()->query('SELECT id,title,subtitle,img,link FROM banners WHERE active=1')->fetchAll(); } catch (Exception $e2) {}
    }
    if ($abBg) ab_reply_bg(['ok'=>true, 'banners'=>$b]);
    jout(['ok'=>true, 'banners'=>$b]);
  }

  /* СКОЛЬКО ВЕСЯТ БАННЕРЫ. Показывает вес каждой картинки — по нему видно,
     нужно ли их пережимать. Ничего не меняет.
     ИМЯ itc_banweight, а не itc_banners: команда с последним именем в файле уже
     есть (управление баннерами, требует входа), и моя оказалась бы второй —
     сработала бы первая, а в ответ прилетало «Не авторизован». */
  case 'itc_banweight': {
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(120);
    echo "=== БАННЕРЫ ===\n\n";
    $b = [];
    try { $b = db()->query('SELECT id,title,img FROM banners WHERE active=1 ORDER BY sort, created_at')->fetchAll(); }
    catch (Exception $e) { echo "не удалось прочитать список\n"; }
    if (!$b) { echo "Активных баннеров нет.\n\n=== КОНЕЦ ===\n"; exit; }
    $total = 0; $unknown = 0;
    foreach ($b as $row) {
      $url = (string)($row['img'] ?? '');
      $size = -1;
      if ($url !== '') {
        try {
          $ch = curl_init($url);
          curl_setopt_array($ch, [CURLOPT_NOBODY=>true, CURLOPT_RETURNTRANSFER=>true,
                                  CURLOPT_FOLLOWLOCATION=>true, CURLOPT_TIMEOUT=>10]);
          curl_exec($ch);
          $size = (int)curl_getinfo($ch, CURLINFO_CONTENT_LENGTH_DOWNLOAD);
          curl_close($ch);
        } catch (Exception $e) { $size = -1; }
      }
      if ($size > 0) { $total += $size; } else { $unknown++; }
      echo mb_substr((string)($row['title'] ?: $row['id']), 0, 40)."\n";
      echo "    ".($size > 0 ? number_format($size/1024, 0, ',', ' ')." КБ" : "вес неизвестен")."\n";
      echo "    ".mb_substr($url, 0, 95)."\n";
    }
    echo "\nВсего баннеров: ".count($b)."\n";
    echo "Общий вес: ".number_format($total/1024/1024, 2, ',', ' ')." МБ".($unknown?(" (у ".$unknown." вес не определился)"):"")."\n";
    echo "\nОриентир: баннер показывается полосой примерно 900×360 точек.\n";
    echo "Нормальный вес одного — 80–200 КБ. Всё, что больше 500 КБ, стоит пережать.\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* ПОЧЕМУ ДОЛГО ГРУЗИТСЯ ПРИЛОЖЕНИЕ.
     Замер на телефоне показал 4683 мс на получение каталога. Непонятно,
     сервер ли столько собирает ответ или ответ просто большой и едет по сети.
     Эта точка отвечает на вопрос: сколько сервер тратит на выборку, сколько
     весит готовый ответ и сжимается ли он при отдаче. Ничего не меняет. */
  case 'itc_boot': {
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(180);
    echo "=== ЗАПУСК ПРИЛОЖЕНИЯ ===\n\n";

    $t0 = microtime(true);
    $rows = [];
    try { $rows = db()->query('SELECT COUNT(*) FROM products')->fetchColumn(); } catch (Exception $e) {}
    echo "Товаров в базе: ".(int)$rows."\n\n";

    // Сколько сервер собирает тот же ответ, что уходит приложению
    $a = microtime(true); $prods = [];
    try {
      // ТОТ ЖЕ лёгкий запрос, что уходит приложению в bootstrap — без описаний и галерей
      $prods = db()->query(
        'SELECT id,supplier_id,cat,subcat,name,price,old_price,img,video,stock,clicks,color,original,
                ready_type,production_days,goods_cny,volume_m3,warehouse_id,blocked,paused,mod_status,
                discount_percent,promo_boost,sales_boost,sold,sold_real,sold_boost,old_price_rub,material,
                weight_kg,pcs_per_box,promo_until,created_at,created_by,jfactory_id,factory
         FROM products ORDER BY created_at DESC')->fetchAll();
    } catch (Exception $e) { echo "не удалось выбрать: ".$e->getMessage()."\n"; }
    $tSel = (microtime(true) - $a) * 1000;

    $a = microtime(true);
    $json = json_encode($prods, JSON_UNESCAPED_UNICODE);
    $tEnc = (microtime(true) - $a) * 1000;
    $raw = strlen((string)$json);

    $a = microtime(true);
    $gz = function_exists('gzencode') ? gzencode((string)$json, 6) : '';
    $tGz = (microtime(true) - $a) * 1000;

    $kb = function ($n) { return number_format($n / 1024, 0, ',', ' ').' КБ'; };

    // Сколько места занимает каждое поле — чтобы резать по цифрам, а не наугад
    $byField = [];
    if ($prods) {
      foreach ($prods as $row) {
        foreach ($row as $k => $v) {
          $byField[$k] = ($byField[$k] ?? 0) + strlen((string)$v) + strlen((string)$k) + 6;
        }
      }
      arsort($byField);
    }
    echo "Выборка из базы: ".round($tSel)." мс, строк: ".count($prods)."\n";
    echo "Упаковка в JSON: ".round($tEnc)." мс\n";
    echo "Размер ответа: ".$kb($raw)."\n";
    if ($gz !== '') {
      echo "Он же в сжатом виде: ".$kb(strlen($gz))." (сжатие за ".round($tGz)." мс)\n";
      echo "Выигрыш от сжатия: ".(int)round(100 - strlen($gz) / max($raw, 1) * 100)."%\n";
    }
    echo "\n";
    echo "Сжатие этой страницы: ".(in_array("ob_gzhandler", ob_list_handlers(), true) ? "ВКЛЮЧЕНО" : "нет")."\n";
    echo "Сжатие в настройках PHP: ";
    $z = ini_get('zlib.output_compression');
    echo ($z && $z !== '0' && $z !== 'Off') ? "включено (zlib)\n" : "выключено в PHP\n";
    echo "Браузер просит сжатие: ".(strpos((string)($_SERVER['HTTP_ACCEPT_ENCODING'] ?? ''), 'gzip') !== false ? "да" : "нет")."\n";
    echo "Модуль сервера: ".(function_exists('apache_get_modules') && in_array('mod_deflate', (array)apache_get_modules()) ? "mod_deflate есть" : "не видно (обычный режим PHP-FPM)")."\n";
    if ($byField) {
      echo "\n--- вес полей (что занимает место) ---\n";
      $n = 0;
      foreach ($byField as $k => $v) {
        if (++$n > 18) break;
        echo str_pad($k, 20).$kb($v)."  (".(int)round($v / max($raw,1) * 100)."%)\n";
      }
    }
    echo "\nВсего на этот отчёт: ".round((microtime(true) - $t0) * 1000)." мс\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* ОБЛОЖКА СТАВИТСЯ САМА.
     Мест, где в базу пишется новая карточка, в коде девять — расставлять
     правило руками значило бы что-то забыть, как было с флагом видимости.
     Поэтому тем же приёмом: триггеры базы. При любой записи товара, откуда бы
     она ни пришла (импорт с 1688, ручной ввод, правка), обложка берётся из
     первого снимка галереи. Фото на alicdn не подставляем — покупателю такие
     карточки не показываются. Триггеры стоят ПЕРЕД триггерами видимости,
     чтобы флаг считался уже по новой обложке.
     Без параметров — показывает состояние. &on=1 — включить. &off=1 — убрать. */
  case 'itc_imgauto': {
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(120);
    $has = function ($n) {
      try {
        $q = db()->prepare("SELECT COUNT(*) FROM information_schema.triggers
                            WHERE trigger_schema = DATABASE() AND trigger_name = ?");
        $q->execute([$n]);
        return (int)$q->fetchColumn() > 0;
      } catch (Exception $e) { return false; }
    };
    $body = "BEGIN
        DECLARE f VARCHAR(1024);
        IF NEW.gallery IS NOT NULL AND JSON_VALID(NEW.gallery) AND JSON_LENGTH(NEW.gallery) > 0 THEN
          SET f = JSON_UNQUOTE(JSON_EXTRACT(NEW.gallery, '$[0]'));
          IF f IS NOT NULL AND f <> '' AND f NOT LIKE '%alicdn%' THEN
            SET NEW.img = f;
          END IF;
        END IF;
      END";

    echo "=== ОБЛОЖКА СТАВИТСЯ САМА ===\n\n";

    if (isset($_GET['off'])) {
      foreach (['trg_prod_img_i','trg_prod_img_u'] as $t) {
        try { db()->exec("DROP TRIGGER IF EXISTS $t"); } catch (Exception $e) {}
      }
      echo "Убрано. Теперь обложка сама подставляться не будет.\n\n=== КОНЕЦ ===\n";
      exit;
    }

    if (isset($_GET['on'])) {
      foreach ([['trg_prod_img_i','INSERT','trg_prod_vis_i'], ['trg_prod_img_u','UPDATE','trg_prod_vis_u']] as $t) {
        try { db()->exec("DROP TRIGGER IF EXISTS {$t[0]}"); } catch (Exception $e) {}
        $ok = false;
        try {
          db()->exec("CREATE TRIGGER {$t[0]} BEFORE {$t[1]} ON products FOR EACH ROW PRECEDES {$t[2]} $body");
          $ok = true;
        } catch (Exception $e) {
          try { db()->exec("CREATE TRIGGER {$t[0]} BEFORE {$t[1]} ON products FOR EACH ROW $body"); $ok = true; }
          catch (Exception $e2) { echo "Не удалось завести {$t[0]}: ".$e2->getMessage()."\n"; }
        }
        if ($ok) echo "Заведён {$t[0]}\n";
      }
      echo "\n";
    }

    $i = $has('trg_prod_img_i'); $u = $has('trg_prod_img_u');
    echo "При добавлении товара: ".($i ? "работает" : "НЕ работает")."\n";
    echo "При изменении товара: ".($u ? "работает" : "НЕ работает")."\n\n";
    if (!$i || !$u) echo "Чтобы включить — откройте эту же ссылку с &on=1\n";
    else echo "Новые и изменённые карточки получают обложку из первого фото сами.\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* ОБЛОЖКА = ПЕРВОЕ ФОТО КАРТОЧКИ.
     У части товаров картинка в ленте (products.img) не совпадает с первым
     снимком галереи. Покупатель открывает карточку — и фото на глазах
     меняется. Приложение при сохранении товара давно ставит обложкой
     gallery[0], но старые строки разъехались.
     Без параметров — только показывает, сколько таких и примеры.
     &fix=1 — чинит пачкой по 5000, можно нажимать несколько раз.
     ВАЖНО: строки, где первое фото галереи ещё лежит на alicdn, НЕ трогаем —
     иначе карточка пропадёт у покупателя, ведь такие фото ему не показываются. */
  case 'itc_imgfix': {
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(300);
    $first = "JSON_UNQUOTE(JSON_EXTRACT(gallery,'$[0]'))";
    $where = "JSON_VALID(gallery) AND JSON_LENGTH(gallery) > 0
              AND $first IS NOT NULL AND $first <> '' AND $first <> IFNULL(img,'')";
    $safe  = "$where AND $first NOT LIKE '%alicdn%'";
    $ali   = "$where AND $first LIKE '%alicdn%'";
    $cnt = function ($w) { try { return (int)db()->query("SELECT COUNT(*) FROM products WHERE $w")->fetchColumn(); } catch (Exception $e) { return -1; } };

    echo "=== ОБЛОЖКА И ПЕРВОЕ ФОТО ===\n\n";
    $need = $cnt($safe); $skip = $cnt($ali);
    echo "Расходится и можно починить: $need\n";
    echo "Расходится, но первое фото ещё на alicdn — не трогаем: $skip\n\n";

    if (!isset($_GET['fix'])) {
      echo "Пока ничего не меняли.\n";
      echo "Чтобы починить — откройте эту же ссылку с &fix=1 (можно несколько раз,\nпока «можно починить» не станет 0).\n\n";
      echo "--- примеры (до 20) ---\n";
      try {
        $rows = db()->query("SELECT id,name,img,$first AS nf FROM products WHERE $safe LIMIT 20")->fetchAll();
        foreach ($rows as $r) {
          echo $r['id'].' · '.mb_substr((string)$r['name'],0,60)."\n";
          echo '    было: '.mb_substr((string)$r['img'],0,90)."\n";
          echo '    стало: '.mb_substr((string)$r['nf'],0,90)."\n";
        }
        if (!$rows) echo "нет таких\n";
      } catch (Exception $e) { echo "не удалось прочитать\n"; }
      echo "\n=== КОНЕЦ ===\n";
      exit;
    }

    $t0 = microtime(true); $done = 0;
    try {
      $st = db()->prepare("UPDATE products SET img = $first WHERE $safe LIMIT 5000");
      $st->execute();
      $done = $st->rowCount();
    } catch (Exception $e) { echo "Ошибка при исправлении: ".$e->getMessage()."\n"; }
    $left = $cnt($safe);
    echo "Исправлено за этот заход: $done (".round((microtime(true)-$t0)*1000)." мс)\n";
    echo "Осталось: $left\n";
    echo $left > 0 ? "\nОткройте ссылку ещё раз — доделает следующую пачку.\n"
                   : "\nГотово, обложки совпадают с первым фото карточки.\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* КАРТОЧКИ БЕЗ ФОТО. Открывается ссылкой, отвечает текстом. Показывает,
     сколько товаров вообще без картинки, сколько с картинкой ещё на alicdn
     (такие покупателю не показываются), и первые полсотни названий — чтобы
     было понятно, что именно чинить. Ничего не меняет. */
  /* ПРОВЕРКА КОРОТКОЙ ССЫЛКИ 1688 (обновление №213).
     Импорт говорит «не удалось развернуть», но не говорит почему. Здесь видно
     всё по шагам: дошёл ли запрос до 1688 вообще, какой был ответ, куда увела
     переадресация и нашёлся ли номер товара. Открывать так:
     ?action=itc_1688_test&u=<ссылка или весь текст с телефона> */
  case 'itc_1688_test': {
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(60);
    $raw = trim((string)($_GET['u'] ?? ''));
    echo "=== ПРОВЕРКА ССЫЛКИ 1688 ===\n\n";
    if ($raw === '') { echo "Ничего не прислано. Добавьте &u=ссылка\n"; exit; }
    echo "Прислано: ".mb_substr($raw, 0, 300)."\n";

    $url = '';
    if (preg_match('~https?://[^\s"\'<>）\)]+~u', $raw, $m)) $url = rtrim($m[0], '.,;');
    echo "Ссылка из текста: ".($url !== '' ? $url : 'НЕ НАЙДЕНА')."\n";
    $idIn = itc_1688_pick_id($raw);
    echo "Номер прямо в тексте: ".($idIn !== '' ? $idIn : 'нет')."\n\n";
    if ($url === '') { echo "Разворачивать нечего.\n=== КОНЕЦ ===\n"; exit; }

    echo "--- ЗАПРОС К 1688 ---\n";
    echo 'curl доступен: '.(function_exists('curl_init') ? 'да' : 'НЕТ — в этом вся причина')."\n";
    if (!function_exists('curl_init')) { echo "=== КОНЕЦ ===\n"; exit; }

    $ch = curl_init($url);
    curl_setopt_array($ch, [
      CURLOPT_RETURNTRANSFER => true,
      CURLOPT_FOLLOWLOCATION => true,
      CURLOPT_MAXREDIRS      => 5,
      CURLOPT_TIMEOUT        => 15,
      CURLOPT_SSL_VERIFYPEER => false,
      CURLOPT_USERAGENT      => 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1',
    ]);
    $t0   = microtime(true);
    $body = curl_exec($ch);
    $ms   = round((microtime(true) - $t0) * 1000);
    $err  = curl_error($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $fin  = (string)curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
    $hops = (int)curl_getinfo($ch, CURLINFO_REDIRECT_COUNT);
    curl_close($ch);

    echo "Время ответа: {$ms} мс\n";
    echo "Ошибка связи: ".($err !== '' ? $err : 'нет')."\n";
    echo "Код ответа: {$code}\n";
    echo "Переадресаций: {$hops}\n";
    echo "Куда привело: ".($fin !== '' ? $fin : '—')."\n";
    echo 'Размер ответа: '.strlen((string)$body)." байт\n\n";

    $idU = itc_1688_pick_id($fin);
    $idB = ($body !== false && $body !== '') ? itc_1688_pick_id((string)$body) : '';
    echo "Номер из адреса: ".($idU !== '' ? $idU : 'нет')."\n";
    echo "Номер из страницы: ".($idB !== '' ? $idB : 'нет')."\n\n";

    $id = $idIn ?: ($idU ?: $idB);
    if ($id !== '') echo "ИТОГ: товар найден → https://detail.1688.com/offer/{$id}.html\n";
    else {
      echo "ИТОГ: номер не найден.\n";
      if ($err !== '')       echo "Причина: сервер не смог достучаться до 1688 (см. ошибку связи выше).\n";
      elseif ($code >= 400)  echo "Причина: 1688 ответил отказом ({$code}) — вероятно, требует приложение или вход.\n";
      elseif ($hops === 0)   echo "Причина: переадресации по правилам сети не было — ссылку раскрывает сам сайт, скриптом.\n";
      else                   echo "Причина: страница пришла, но номера товара в ней нет.\n";

      /* РАЗБИРАЕМ ОТВЕТ ПО КУСКАМ.
         Раньше здесь стояло strip_tags + preg_replace, и на китайской странице
         разбор возвращал пустоту — видно было только предупреждение PHP.
         Теперь ничего не чистим: приводим к UTF-8 и показываем как есть,
         плюс отдельно выписываем все ссылки и длинные числа — номер товара
         почти наверняка среди них. */
      $b = (string)$body;
      if (!mb_check_encoding($b, 'UTF-8')) $b = @mb_convert_encoding($b, 'UTF-8', 'GBK,GB18030,UTF-8');
      $b = (string)$b;

      echo "\n--- ССЫЛКИ ВНУТРИ ОТВЕТА ---\n";
      if (preg_match_all('~https?:\\\\?/\\\\?/[^\s"\'<>\\\\]{6,200}~', $b, $mm) && !empty($mm[0])) {
        $seen = [];
        foreach ($mm[0] as $u2) {
          $u2 = str_replace('\\/', '/', $u2);
          if (isset($seen[$u2])) continue; $seen[$u2] = 1;
          echo '  '.mb_substr($u2, 0, 160)."\n";
          if (count($seen) >= 25) break;
        }
      } else echo "  ссылок не найдено\n";

      echo "\n--- ДЛИННЫЕ ЧИСЛА (кандидаты в номер товара) ---\n";
      if (preg_match_all('~\d{9,20}~', $b, $nn) && !empty($nn[0])) {
        $u3 = array_slice(array_values(array_unique($nn[0])), 0, 30);
        echo '  '.implode(', ', $u3)."\n";
      } else echo "  чисел не найдено\n";

      echo "\n--- ОТВЕТ ЦЕЛИКОМ (первые 1800 знаков) ---\n";
      echo mb_substr($b, 0, 1800)."\n";
    }
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  case 'itc_nophoto': {
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(120);
    echo "=== КАРТОЧКИ БЕЗ ФОТО ===\n\n";
    $q = function ($sql) { try { return (int)db()->query($sql)->fetchColumn(); } catch (Exception $e) { return -1; } };
    $all   = $q('SELECT COUNT(*) FROM products');
    $empty = $q("SELECT COUNT(*) FROM products WHERE img IS NULL OR TRIM(img)=''");
    $ali   = $q("SELECT COUNT(*) FROM products WHERE img LIKE '%alicdn%'");
    $blk   = $q("SELECT COUNT(*) FROM products WHERE (img IS NULL OR TRIM(img)='') AND blocked=0");
    echo "Всего товаров: $all\n";
    echo "Совсем без фото: $empty (из них не заблокированных: $blk)\n";
    echo "Фото ещё на alicdn (покупателю не видно): $ali\n\n";
    echo "Покупателю такие карточки НЕ показываются — их видят только сотрудники.\n\n";
    echo "--- первые 50 без фото ---\n";
    try {
      $rows = db()->query("SELECT id,name,cat FROM products WHERE img IS NULL OR TRIM(img)='' ORDER BY id DESC LIMIT 50")->fetchAll();
      foreach ($rows as $r) { echo $r['id'].' · '.mb_substr((string)$r['name'],0,70).' · '.(string)$r['cat']."\n"; }
      if (!$rows) echo "нет таких\n";
    } catch (Exception $e) { echo "не удалось прочитать\n"; }
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* ЭКОСИСТЕМА — ОБЩИЙ ЖУРНАЛ РАСЧЁТОВ.
     Расчёты менеджера лежат в его собственном браузере, поэтому босс их не
     видел. Теперь каждое сохранение, правка и удаление отправляются сюда и
     подписываются именем сотрудника. Ничего не перетирается: каждое действие —
     отдельная строка, поэтому видно и что было, и что стало. Список открыт
     ТОЛЬКО боссу; остальные видят лишь свою историю у себя в браузере. */
  case 'eco_hist_push': {
    $s = authUser('itc');
    eco_hist_ensure();
    $d = body();
    $rid = mb_substr(trim((string)($d['rid'] ?? '')), 0, 40);
    if ($rid === '') fail('Нет записи');
    $act  = mb_substr(trim((string)($d['act']  ?? '')), 0, 20);
    $ttl  = mb_substr(trim((string)($d['name'] ?? '')), 0, 190);
    $kind = mb_substr(trim((string)($d['kind'] ?? '')), 0, 30);
    $who  = trim((string)($s['name'] ?? ''));
    if ($who === '') $who = trim((string)($s['phone'] ?? ''));
    if ($who === '') $who = 'сотрудник';
    db()->prepare('INSERT INTO itc_eco_hist (rid,act,who,phone,title,kind,payload) VALUES (?,?,?,?,?,?,?)')
        ->execute([$rid, $act, $who, (string)($s['phone'] ?? ''), $ttl, $kind,
                   json_encode($d['data'] ?? null, JSON_UNESCAPED_UNICODE)]);
    jout(['ok'=>true]);
  }
  case 'eco_hist_list': {
    $s = authUser('itc');
    eco_hist_ensure();
    $sr = $s['staff_role'] ?? '';
    $boss = ($sr === 'boss' || $sr === '');
    if (!$boss) jout(['ok'=>true, 'boss'=>false, 'log'=>[]]);
    $rows = [];
    try {
      $rows = db()->query('SELECT id,rid,act,who,title,kind,created_at FROM itc_eco_hist ORDER BY id DESC LIMIT 300')->fetchAll();
    } catch (Exception $e) {}
    jout(['ok'=>true, 'boss'=>true, 'log'=>$rows]);
  }

  /* ОДНА ЗАПИСЬ ИЗ ОБЩЕГО ЖУРНАЛА ЦЕЛИКОМ (обновление №211).
     Сам расчёт давно сохраняется на сервере в поле payload, но список его не
     отдавал — и открыть чужой расчёт было нельзя, хотя данные лежали рядом.
     Здесь отдаём одну запись по её номеру, чтобы её можно было посмотреть. */
  case 'eco_hist_get': {
    $s = authUser('itc');
    eco_hist_ensure();
    $sr = $s['staff_role'] ?? '';
    if (!($sr === 'boss' || $sr === '')) jout(['ok'=>false, 'err'=>'Нет доступа']);
    $id = (int)($_GET['id'] ?? 0);
    if ($id < 1) jout(['ok'=>false, 'err'=>'Нет записи']);
    $row = null;
    try {
      $st = db()->prepare('SELECT id,rid,act,who,title,kind,payload,created_at FROM itc_eco_hist WHERE id=? LIMIT 1');
      $st->execute([$id]); $row = $st->fetch();
    } catch (Exception $e) {}
    if (!$row) jout(['ok'=>false, 'err'=>'Запись не найдена']);
    $row['data'] = json_decode((string)$row['payload'], true);
    unset($row['payload']);
    jout(['ok'=>true, 'rec'=>$row]);
  }

  /* ЭКОСИСТЕМА ИТК — общие настройки калькуляторов.
     Раньше курсы, пошлина, НДС и наценки были зашиты внутрь страницы: чтобы
     поменять цифру, надо было пересобирать файл. Теперь они лежат в базе,
     менять может любой сотрудник ИТК, и каждая правка ложится в журнал —
     видно кто, когда и что написал. Ничего не перетирается: новая правка —
     новая строка, старые остаются как история. */
  case 'eco_cfg': {
    $s = authUser('itc');
    eco_cfg_ensure();
    $row = null;
    try { $row = db()->query('SELECT cfg,who,created_at FROM itc_eco_cfg ORDER BY id DESC LIMIT 1')->fetch(); } catch (Exception $e) {}
    $cfg = $row ? json_decode($row['cfg'], true) : null;
    jout(['ok'=>true, 'cfg'=>is_array($cfg)?$cfg:null, 'who'=>$row['who']??'', 'at'=>$row['created_at']??'']);
  }
  case 'eco_cfg_save': {
    $s = authUser('itc');
    eco_cfg_ensure();
    $d = body();
    $cfg = $d['cfg'] ?? null;
    if (!is_array($cfg)) fail('Пустые настройки');
    $who = trim((string)($s['name'] ?? ''));
    if ($who === '') $who = trim((string)($s['phone'] ?? ''));
    if ($who === '') $who = 'сотрудник';
    $note = mb_substr(trim((string)($d['note'] ?? '')), 0, 240);
    db()->prepare('INSERT INTO itc_eco_cfg (cfg,who,note) VALUES (?,?,?)')
        ->execute([json_encode($cfg, JSON_UNESCAPED_UNICODE), $who, $note]);
    jout(['ok'=>true]);
  }
  case 'eco_cfg_log': {
    $s = authUser('itc');
    eco_cfg_ensure();
    $rows = [];
    try { $rows = db()->query('SELECT id,cfg,who,note,created_at FROM itc_eco_cfg ORDER BY id DESC LIMIT 50')->fetchAll(); } catch (Exception $e) {}
    jout(['ok'=>true, 'log'=>$rows]);
  }

  /* ЗАМЕР СКОРОСТИ. Приложение стало тормозить, и гадать я больше не хочу:
     эта точка засекает время каждого куска работы, который делает витрина,
     и показывает, что именно тянет. Открывается ссылкой, отвечает текстом. */
  case 'itc_perf': {
    $cron_key = trim($_GET['cron_key'] ?? ''); $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
    if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
    @set_time_limit(120);
    header('Content-Type: text/plain; charset=utf-8');
    $t = function () { return microtime(true); };
    $ms = function ($a) { return round((microtime(true) - $a) * 1000).' мс'; };

    echo "=== ЗАМЕР СКОРОСТИ ===\n\n";

    $a = $t(); $cnt = 0;
    try { $cnt = (int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn(); } catch (Exception $e) {}
    echo "Товаров в базе: {$cnt} · посчитано за ".$ms($a)."\n";

    $a = $t();
    try { db()->query('SHOW COLUMNS FROM products')->fetchAll(); } catch (Exception $e) {}
    echo "Опрос колонок (делается один раз на запрос): ".$ms($a)."\n";

    $vis = "(blocked=0 OR blocked IS NULL) AND (paused=0 OR paused IS NULL)
            AND (mod_status='approved' OR mod_status='' OR mod_status IS NULL)
            AND img IS NOT NULL AND img<>'' AND img NOT LIKE '%alicdn%'";
    $a = $t(); $vc = 0;
    try { $vc = (int)db()->query("SELECT COUNT(*) FROM products WHERE $vis")->fetchColumn(); } catch (Exception $e) {}
    echo "\nСчёт видимых товаров: {$vc} · ".$ms($a)."   <- это на каждой странице каталога\n";

    $a = $t();
    try { db()->query("SELECT COUNT(*) FROM products WHERE cat='Посуда' AND $vis")->fetchColumn(); } catch (Exception $e) {}
    echo "Счёт по одной категории: ".$ms($a)."\n";

    $a = $t();
    try { db()->query("SELECT id,name,price,img,cat FROM products WHERE $vis ORDER BY created_at DESC, id DESC LIMIT 60")->fetchAll(); } catch (Exception $e) {}
    echo "Первая страница ленты (60 карточек): ".$ms($a)."\n";

    $a = $t();
    try { db()->query("SELECT id,name,price,img,cat FROM products WHERE $vis ORDER BY created_at DESC, id DESC LIMIT 60 OFFSET 600")->fetchAll(); } catch (Exception $e) {}
    echo "Одиннадцатая страница (OFFSET 600): ".$ms($a)."\n";

    $a = $t();
    try { db()->query("SELECT * FROM products ORDER BY id DESC LIMIT 1")->fetchAll(); } catch (Exception $e) {}
    echo "Одна карточка целиком: ".$ms($a)."\n";

    /* ЗАМЕР ТЯЖЁЛЫХ МЕСТ, КОТОРЫЕ ПОЯВИЛИСЬ ПОЗЖЕ (обновление №202).
       Витрина, поиск, полоса «Рекомендуем» и похожие товары — это четыре
       разных запроса, и на большом каталоге они дорожают по-разному. Меряем
       каждый отдельно, чтобы не гадать, что именно станет узким местом.
       ВАЖНО: условие берём ТО ЖЕ, что реально стоит в витрине. Если флаг
       видимости заполнен, витрина ходит по нему и по индексу — мерить старым
       перебором значит мерить то, чего в бою уже нет. */
    $visReady = (itc_vis_ready() && ($cols0 = itc_products_columns()) && isset($cols0['vis']));
    $visNow   = $visReady ? 'vis=1' : $vis;
    $visP     = $visReady ? 'p.vis=1' : str_replace(
                  ['blocked', 'paused', 'mod_status', 'img'],
                  ['p.blocked', 'p.paused', 'p.mod_status', 'p.img'], $vis);
    echo "\n--- ЗАПРОСЫ ПОКУПАТЕЛЯ ---\n";
    echo 'Условие видимости: '.($visReady ? 'ПО ФЛАГУ vis (как в бою)' : 'старым перебором — флаг не заполнен')."\n";

    $a = $t(); $n1 = 0;
    try {
      $st = db()->prepare("SELECT id,name,price,img FROM products
                           WHERE $visNow AND LOWER(CONCAT_WS(' ', name, COALESCE(subcat,''), COALESCE(cat,''))) LIKE ?
                           ORDER BY created_at DESC LIMIT 400");
      $st->execute(['%стол%']); $n1 = count($st->fetchAll());
    } catch (Exception $e) { echo '  поиск — ошибка: '.mb_substr($e->getMessage(), 0, 80)."\n"; }
    echo "Поиск частого слова «стол»: найдено {$n1} · ".$ms($a)."\n";

    /* Редкое слово — худший случай: подходящих строк мало, поэтому база
       вынуждена перебрать таблицу до конца, а не остановиться на четырёхстах. */
    $a = $t(); $n1b = 0;
    try {
      $st = db()->prepare("SELECT id,name,price,img FROM products
                           WHERE $visNow AND LOWER(CONCAT_WS(' ', name, COALESCE(subcat,''), COALESCE(cat,''))) LIKE ?
                           ORDER BY created_at DESC LIMIT 400");
      $st->execute(['%щипцы для завивки%']); $n1b = count($st->fetchAll());
    } catch (Exception $e) {}
    echo "Поиск РЕДКОГО слова (худший случай): найдено {$n1b} · ".$ms($a)."\n";

    /* Полоса «Рекомендуем» — НОВЫЙ путь: верхушка по индексу (vis, sold, clicks),
       база читает сотню строк и останавливается. Разбор семейств и фабрик ушёл
       в PHP и от размера каталога не зависит. */
    $a = $t();
    try {
      db()->query("SELECT p.id, p.name, p.sold, p.clicks FROM products p
                   WHERE $visP ORDER BY p.sold DESC, p.clicks DESC, p.id DESC LIMIT 120")->fetchAll();
    } catch (Exception $e) { echo '  полоса — ошибка: '.mb_substr($e->getMessage(), 0, 80)."\n"; }
    echo "Полоса «Рекомендуем» (НОВЫЙ путь, по индексу): ".$ms($a)."   <- было 550 мс\n";

    /* Для сравнения — прежний способ, чтобы видеть, что именно мы выиграли. */
    $a = $t();
    try {
      db()->query("SELECT t.id, t.name FROM (
                     SELECT b.*, ROW_NUMBER() OVER (PARTITION BY b.maker ORDER BY b.pop DESC, b.id DESC) rn_sup
                     FROM (
                       SELECT p.id, p.name,
                              COALESCE(NULLIF(p.factory,''), p.supplier_id, '') AS maker,
                              COALESCE(p.sold,0)*1000000 + COALESCE(p.clicks,0) AS pop,
                              ROW_NUMBER() OVER (PARTITION BY LEFT(p.name,40) ORDER BY p.created_at DESC, p.id DESC) rn_fam
                       FROM products p WHERE $visP
                     ) b WHERE b.rn_fam = 1
                   ) t ORDER BY t.rn_sup, t.pop DESC, t.id DESC LIMIT 12")->fetchAll();
    } catch (Exception $e) {}
    echo "   (прежний способ, оконные функции по всей витрине): ".$ms($a)."\n";

    /* Похожие товары — НОВЫЙ путь: жёсткое ограничение категорией, она в индексе. */
    $a = $t(); $catProbe = '';
    try { $catProbe = (string)db()->query("SELECT cat FROM products WHERE cat IS NOT NULL AND cat<>'' LIMIT 1")->fetchColumn(); } catch (Exception $e) {}
    $a = $t();
    try {
      $st = db()->prepare("SELECT p.id, p.name, (CASE WHEN LOWER(p.name) LIKE ? THEN 10 ELSE 0 END) AS sim
                           FROM products p WHERE $visP AND p.cat = ? AND LOWER(p.name) LIKE ?
                           ORDER BY sim DESC, p.id DESC LIMIT 300");
      $st->execute(['%стол%', $catProbe, '%стол%']); $st->fetchAll();
    } catch (Exception $e) { echo '  похожие — ошибка: '.mb_substr($e->getMessage(), 0, 80)."\n"; }
    echo "Похожие товары (НОВЫЙ путь, внутри «{$catProbe}»): ".$ms($a)."   <- было 324 мс\n";

    $a = $t();
    try {
      $st = db()->prepare("SELECT p.id, p.name FROM products p WHERE $visP AND LOWER(p.name) LIKE ? LIMIT 300");
      $st->execute(['%стол%']); $st->fetchAll();
    } catch (Exception $e) {}
    echo "   (прежний способ, по всей витрине): ".$ms($a)."\n";

    /* Недостающие индексы можно доставить прямо отсюда: ?idx=1 */
    if (!empty($_GET['idx'])) {
      echo "\n--- ДОБАВЛЯЕМ ИНДЕКСЫ ---\n";
      foreach ([['idx_prod_mod','mod_status'],['idx_prod_blocked','blocked'],
                ['idx_prod_vis_pop','vis, sold, clicks'],['idx_prod_cat_vis','cat, vis']] as $one) {
        $a2 = microtime(true);
        try { db()->query('ALTER TABLE products ADD INDEX '.$one[0].' ('.$one[1].')'); echo '  '.$one[1].' — добавлен за '.round((microtime(true)-$a2)*1000)." мс\n"; }
        catch (Exception $e) { echo '  '.$one[1].' — уже есть или нельзя: '.mb_substr($e->getMessage(),0,60)."\n"; }
      }
    }

    echo "\n--- ИНДЕКСЫ таблицы products ---\n";
    $idx = [];
    try {
      foreach (db()->query('SHOW INDEX FROM products')->fetchAll() as $r) {
        $k = $r['Key_name']; if (!isset($idx[$k])) $idx[$k] = [];
        $idx[$k][] = $r['Column_name'];
      }
    } catch (Exception $e) {}
    foreach ($idx as $k => $cols) echo '  '.$k.' → '.implode(', ', $cols)."\n";
    foreach (['cat','created_at','mod_status','blocked'] as $c) {
      $found = false;
      foreach ($idx as $cols) if (isset($cols[0]) && $cols[0] === $c) $found = true;
      if (!$found) echo "  НЕТ индекса по «{$c}» — а по нему фильтруется витрина\n";
    }

    echo "\n--- ФОНОВОЕ ЗАДАНИЕ ИИ ---\n";
    try {
      $j = itc_ai_job_get();
      echo '  статус: '.($j['status'] ?? '?').' · дежурство: '.(!empty($j['watch']) ? 'включено' : 'выключено')."\n";
      echo '  в очереди: '.itc_ai_job_left($j['scope'] ?? 'other')."\n";
      echo '  последнее обновление: '.($j['updated_at'] ?? '—')."\n";
    } catch (Exception $e) {}

    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* УДАЛЕНИЕ МУСОРНЫХ КАРТОЧЕК той самой партии от 22.07.2026.
     Сорок восемь карточек, куда попал отказ ИИ, а после починки — машинный
     перевод вроде «Трансграничные дети сидят дома, режут игрушки». Алексей
     решил их удалить целиком. Ищем и по остаткам отказов, и по узнаваемым
     фразам машинного перевода. Сначала ТОЛЬКО ПОКАЗЫВАЕМ, удаляем по &del=1. */
  case 'itc_del_junk': {
    $cron_key = trim($_GET['cron_key'] ?? ''); $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
    if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
    @set_time_limit(180);
    header('Content-Type: text/plain; charset=utf-8');

    $marks = [
      '%не могу обсуждать%', '%Давайте поговорим о чём%',
      '%Трансграничные дети%', '%режут игрушки%', '%имитируют нарезанные%',
      '%Plugin Amazon Simulated%', '%Плагин Amazon Simulated%', '%Simulated Pine Leaf%',
      '%Ovilo Town Shop Treasure%',
      '%Детская стойка для обуви Детская стойка%',
      '%Имитация фруктовой модели%',
      '%Имитация листьев сосновой ветви%',
      '%кольцо два ханл магазин%',
    ];
    $rows = []; $seen = [];
    foreach ($marks as $lk) {
      try {
        $q = db()->prepare('SELECT id, name FROM products WHERE name LIKE ? LIMIT 300');
        $q->execute([$lk]);
        foreach ($q->fetchAll() as $r) { if (!isset($seen[$r['id']])) { $seen[$r['id']] = 1; $rows[] = $r; } }
      } catch (Exception $e) {}
    }

    echo "=== МУСОРНЫЕ КАРТОЧКИ ===\n";
    echo 'Найдено: '.count($rows)."\n\n";
    foreach ($rows as $r) echo '  '.$r['id'].' | '.mb_substr((string)$r['name'], 0, 80)."\n";

    if (empty($_GET['del'])) {
      echo "\nПока НИЧЕГО НЕ УДАЛЕНО — это только показ.\n";
      echo "Проверьте список выше. Если всё верно, добавьте к ссылке &del=1\n";
      echo "\n=== КОНЕЦ ===\n"; exit;
    }

    $del = 0;
    $dp = db()->prepare('DELETE FROM products WHERE id=?');
    $dd = db()->prepare('DELETE FROM ds_products WHERE product_id=?');
    foreach ($rows as $r) {
      try { $dd->execute([$r['id']]); } catch (Exception $e) {}   // сначала запись дропшиппинга
      try { $dp->execute([$r['id']]); $del++; } catch (Exception $e) {}
    }
    echo "\n--- УДАЛЕНО: {$del} ---\n";
    echo "Карточки убраны и из каталога, и из дропшиппинга.\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* Показать, сколько карточек испорчено отказом ИИ и какие именно.
     Открывается ссылкой в браузере, отвечает простым текстом. */
  case 'itc_badnames': {
    $cron_key = trim($_GET['cron_key'] ?? ''); $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
    if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
    @set_time_limit(120);
    header('Content-Type: text/plain; charset=utf-8');
    $bad = itc_find_bad_names(500);
    echo "=== КАРТОЧКИ С ОТКАЗОМ ИИ В НАЗВАНИИ ===\n";
    echo 'Найдено: '.count($bad)."\n\n";
    $withSrc = 0; $n = 0;
    foreach ($bad as $r) {
      $cn = itc_source_title_cn($r['id']);
      if ($cn !== '') $withSrc++;
      if ($n < 25) { $n++; echo '  '.$r['id'].' | '.mb_substr((string)$r['name'], 0, 80).' | исходник: '.($cn !== '' ? mb_substr($cn, 0, 40) : 'НЕТ')."\n"; }
    }
    echo "\nМожно перевести заново (есть китайский исходник): {$withSrc}\n";
    echo "Без исходника (придётся править руками): ".(count($bad) - $withSrc)."\n";

    /* ПОЧИНКА ПРЯМО ОТСЮДА: ?fix=1. Сделано ссылкой, а не кнопкой в кабинете,
       потому что случай разовый — испорченных карточек полсотни, а не поток. */
    if (!empty($_GET['fix'])) {
      $lim = (int)($_GET['limit'] ?? 50); if ($lim < 1 || $lim > 100) $lim = 50;
      echo "\n--- ПЕРЕВОДИМ ЗАНОВО (до {$lim} штук) ---\n";
      $fixed = 0; $failed = 0; $done = 0;
      $upd = db()->prepare('UPDATE products SET name=? WHERE id=?');
      foreach ($bad as $r) {
        if ($done >= $lim) break;
        $done++;
        $cn = itc_source_title_cn($r['id']);
        if ($cn === '') { echo '  '.$r['id']." — исходника нет, пропуск\n"; $failed++; continue; }
        /* Яндекс на этих названиях упирается и выдаёт отказ — тот самый, что
           и испортил карточки. Поэтому запасной путь: механический переводчик
           MyMemory. Он переводит топорно, но честно и никогда не отказывает. */
        $via = 'ИИ';
        $new = ai_translate_field($cn, 'name');
        if (!is_string($new) || $new === '' || itc_bad_ai_text($new)) {
          $via = 'машинный';
          $new = function_exists('pdd_translate') ? pdd_translate($cn) : '';
        }
        $new = trim((string)$new);
        // MyMemory при неудаче возвращает исходник — узнаём по иероглифам
        if ($new === '' || itc_bad_ai_text($new) || preg_match('/[\x{4e00}-\x{9fff}]/u', $new)) {
          echo '  '.$r['id']." — перевести не вышло ни одним способом\n"; $failed++; continue;
        }
        $new = mb_substr($new, 0, 200);
        $new = mb_strtoupper(mb_substr($new, 0, 1)).mb_substr($new, 1);
        try { $upd->execute([$new, $r['id']]); $fixed++; echo '  '.$r['id'].' ('.$via.') → '.mb_substr($new, 0, 70)."\n"; }
        catch (Exception $e) { $failed++; }
        usleep(300000);
      }
      echo "\nПереведено заново: {$fixed} · не вышло: {$failed}\n";
      echo "Если осталось — откройте ссылку ещё раз.\n";
    } else {
      echo "\nЧтобы перевести заново, добавьте к ссылке &fix=1\n";
    }
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }
  /* Перевести испорченные карточки заново из китайского исходника. */
  case 'itc_fix_badnames': {
    $s = authUser('itc'); require_staff($s, ['boss','supervisor']);
    $d = body();
    $lim = (int)($d['limit'] ?? 30); if ($lim < 1 || $lim > 100) $lim = 30;
    @set_time_limit(300);
    $bad = itc_find_bad_names(500);
    $fixed = 0; $noSrc = 0; $failed = 0; $done = 0; $samples = [];
    $upd = db()->prepare('UPDATE products SET name=? WHERE id=?');
    foreach ($bad as $r) {
      if ($done >= $lim) break;
      $done++;
      $cn = itc_source_title_cn($r['id']);
      if ($cn === '') { $noSrc++; continue; }
      $new = function_exists('ai_translate_field') ? ai_translate_field($cn, 'name') : null;
      if (!is_string($new) || $new === '' || itc_bad_ai_text($new)) { $failed++; continue; }
      $new = mb_substr(trim($new), 0, 200);
      try { $upd->execute([$new, $r['id']]); $fixed++; if (count($samples) < 5) $samples[] = $new; }
      catch (Exception $e) { $failed++; }
      usleep(300000);
    }
    try { itc_log_add(mb_substr(trim((string)($d['by'] ?? '')), 0, 120), 'fix_badnames', '', '', (string)$fixed); } catch (Exception $e) {}
    jout(['ok'=>true, 'total'=>count($bad), 'checked'=>$done, 'fixed'=>$fixed,
          'no_source'=>$noSrc, 'failed'=>$failed, 'left'=>max(0, count($bad) - $fixed),
          'samples'=>$samples]);
  }

  /* ДИАГНОСТИКА ИИ. Открывается ссылкой в браузере, отвечает обычным текстом.
     Один короткий запрос на трёх товарах — видно, какой движок отвечает,
     за сколько секунд и что именно вернул. Нужна, когда задание стоит на нуле
     и непонятно, где затык: в ключе, в балансе или в самом сервере. */
  case 'itc_ai_ping': {
    $cron_key = trim($_GET['cron_key'] ?? ''); $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
    if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
    @set_time_limit(120);
    header('Content-Type: text/plain; charset=utf-8');

    echo "=== ПРОВЕРКА ИИ ===\n";
    echo 'PHP max_execution_time = '.ini_get('max_execution_time')."\n";
    echo 'ob_yandex.php подключён: '.((function_exists('yx_gpt') && function_exists('yx_ready')) ? 'да' : 'НЕТ')."\n";
    if (function_exists('yx_ready')) { echo 'Яндекс готов (ключи на месте): '.(yx_ready() ? 'да' : 'НЕТ')."\n"; }
    echo 'Ключ DeepSeek в config.php: '.((defined('DEEPSEEK_API_KEY') && DEEPSEEK_API_KEY) ? 'есть' : 'НЕТ')."\n";
    if (function_exists('yx_env')) { echo "Настройки Яндекса: ".json_encode(yx_env(), JSON_UNESCAPED_UNICODE)."\n"; }

    $cats = [];
    try { foreach (db()->query('SELECT name FROM categories ORDER BY sort, name LIMIT 40')->fetchAll() as $c) { $n = trim((string)$c['name']); if ($n !== '') $cats[] = $n; } }
    catch (Exception $e) {}
    echo 'Категорий в справочнике: '.count($cats)."\n";
    if (!$cats) { echo "СТОП: справочник категорий пуст, ИИ не из чего выбирать.\n"; exit; }

    $rows = [];
    try {
      $q = db()->query("SELECT id, name, LEFT(COALESCE(descr,''),200) dsc FROM products WHERE (cat IS NULL OR cat='' OR cat='Прочее') ORDER BY id LIMIT 3");
      $rows = $q->fetchAll();
    } catch (Exception $e) {}
    if (!$rows) { echo "Товаров в «Прочее» не осталось — проверять нечего.\n"; exit; }
    echo "Пробуем на трёх товарах:\n";
    foreach ($rows as $r) echo '  - '.mb_substr((string)$r['name'], 0, 70)."\n";

    $sys = 'Ты товаровед. Для каждого номера выбери ОДНУ категорию из списка. Ответ строго JSON вида {"1":"Категория"}.';
    $list = []; $i = 0; foreach ($rows as $r) { $i++; $list[] = $i.'. '.mb_substr((string)$r['name'], 0, 200); }
    $user = "Категории:\n- ".implode("\n- ", $cats)."\n\nТовары:\n".implode("\n", $list);

    // --- Яндекс ---
    if (function_exists('yx_gpt') && function_exists('yx_ready') && yx_ready()) {
      $t = microtime(true);
      $out = null;
      try { $out = yx_gpt($sys, $user, 0.1, 400); } catch (Exception $e) { $out = 'ИСКЛЮЧЕНИЕ: '.$e->getMessage(); }
      $sec = round(microtime(true) - $t, 1);
      echo "\n--- YandexGPT: {$sec} сек ---\n";
      echo (is_string($out) && trim($out) !== '') ? ('ОТВЕТ: '.mb_substr(trim($out), 0, 300)."\n") : "ПУСТО (ответа нет)\n";
    } else {
      echo "\n--- YandexGPT: пропущен, не настроен ---\n";
    }

    // --- DeepSeek ---
    if (defined('DEEPSEEK_API_KEY') && DEEPSEEK_API_KEY) {
      $payload = json_encode([
        'model'=>'deepseek-v4-flash',
        'messages'=>[['role'=>'system','content'=>$sys],['role'=>'user','content'=>$user]],
        'response_format'=>['type'=>'json_object'],
        'temperature'=>0.1, 'max_tokens'=>400, 'stream'=>false,
      ], JSON_UNESCAPED_UNICODE);
      $t = microtime(true);
      $ch = curl_init('https://api.deepseek.com/chat/completions');
      curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER=>true, CURLOPT_POST=>true,
        CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.DEEPSEEK_API_KEY],
        CURLOPT_POSTFIELDS=>$payload, CURLOPT_TIMEOUT=>25, CURLOPT_CONNECTTIMEOUT=>8,
        CURLOPT_SSL_VERIFYPEER=>false,
      ]);
      $raw = curl_exec($ch); $http = curl_getinfo($ch, CURLINFO_HTTP_CODE); $err = curl_error($ch); curl_close($ch);
      $sec = round(microtime(true) - $t, 1);
      echo "\n--- DeepSeek: {$sec} сек, код ответа {$http} ---\n";
      if ($raw === false) echo 'ОШИБКА СЕТИ: '.$err."\n";
      else echo 'ОТВЕТ: '.mb_substr((string)$raw, 0, 400)."\n";
    } else {
      echo "\n--- DeepSeek: пропущен, ключа нет ---\n";
    }

    /* ПРОБА БОЕВОЙ ПАЧКИ. Короткий запрос на три товара проходит всегда, а
       раскладка шлёт по 12 штук с полным списком категорий — и падает. Значит
       дело в размере. Пробуем те же размеры, что в работе, и смотрим, на каком
       Яндекс замолкает. */
    if (function_exists('yx_gpt') && function_exists('yx_ready') && yx_ready()) {
      $big = [];
      try {
        $qb = db()->query("SELECT id, name FROM products WHERE (cat IS NULL OR cat='' OR cat='Прочее') ORDER BY id LIMIT 12");
        $big = $qb->fetchAll();
      } catch (Exception $e) {}
      $sysB = "Ты товаровед интернет-магазина товаров для дома. Тебе дают пронумерованный список товаров.\n".
        "Для КАЖДОГО номера выбери ОДНУ категорию строго из предложенного списка — по смыслу названия и описания.\n".
        "Новых категорий НЕ придумывай. Если ни одна не подходит — верни \"Прочее\".\n".
        "Ответ — СТРОГО валидный JSON без markdown вида {\"1\":\"Категория\",\"2\":\"Категория\"}, по одному ключу на каждый номер.";
      foreach ([12, 6, 3] as $n) {
        if (count($big) < 1) break;
        $part = array_slice($big, 0, $n);
        $ls = []; $k = 0;
        foreach ($part as $r) { $k++; $ls[] = $k.'. '.mb_substr((string)$r['name'], 0, 260); }
        $userB = "Категории:\n- ".implode("\n- ", $cats)."\n\nТовары:\n".implode("\n", $ls);
        foreach ([900, 400] as $mt) {
          $t = microtime(true);
          $out = null;
          try { $out = yx_gpt($sysB, $userB, 0.1, $mt); } catch (Exception $e) { $out = 'ИСКЛЮЧЕНИЕ: '.$e->getMessage(); }
          $sec = round(microtime(true) - $t, 1);
          $ok = (is_string($out) && trim($out) !== '');
          echo "\n--- боевая пачка: {$n} товаров, лимит ответа {$mt}, {$sec} сек ---\n";
          echo $ok ? ('ЕСТЬ ОТВЕТ, '.mb_strlen($out).' символов: '.mb_substr(trim($out), 0, 200)."\n") : "ПУСТО — вот на этом и падает\n";
          usleep(600000);
        }
      }
    }

    echo "\n=== КОНЕЦ ПРОВЕРКИ ===\n";
    exit;
  }

  // ---- Фоновое задание ИИ-раскладки: запуск / состояние / остановка / шаг ----
  case 'itc_ai_job_start': {
    $s = authUser('itc'); require_staff($s, ['boss','supervisor']);
    $d = body();
    $scope = ((($d['scope'] ?? 'other')) === 'all') ? 'all' : 'other';
    itc_ai_job_table();
    if (!empty($d['reset'])) { try { db()->query('UPDATE products SET ai_cat_at=NULL'); } catch (Exception $e) {} }
    $left = itc_ai_job_left($scope);
    try {
      db()->prepare("UPDATE itc_ai_job SET status='running', scope=?, total=?, done=0, moved=0, msg='', lock_at=NULL, started_at=NOW(), updated_at=NOW() WHERE id=1")
          ->execute([$scope, $left]);
    } catch (Exception $e) { fail('Не удалось запустить: '.$e->getMessage()); }
    try { itc_log_add(mb_substr(trim((string)($d['by'] ?? '')), 0, 120), 'ai_job_start', 'scope', $scope, (string)$left); } catch (Exception $e) {}
    jout(['ok'=>true, 'job'=>itc_ai_job_get(), 'left'=>$left]);
  }
  case 'itc_ai_job_status': {
    $s = authUser('itc'); require_staff($s, ['boss','supervisor','manager','moderator']);
    $job = itc_ai_job_get();
    jout(['ok'=>true, 'job'=>$job, 'left'=>itc_ai_job_left($job['scope'] ?? 'other')]);
  }
  /* Включение и выключение дежурства. Включили при завершённом задании —
     оно снова оживает и ждёт новые карточки. */
  case 'itc_ai_job_watch': {
    $s = authUser('itc'); require_staff($s, ['boss','supervisor']);
    $d = body();
    $on = !empty($d['on']) ? 1 : 0;
    itc_ai_job_table();
    $job = itc_ai_job_get();
    $scope = ((($d['scope'] ?? ($job['scope'] ?? 'other'))) === 'all') ? 'all' : 'other';
    try {
      if ($on) {
        /* Если очередь не пуста — включаем сразу в работу, а не в ожидание. */
        $newSt = (itc_ai_job_left($scope) > 0) ? 'running' : 'watch';
        db()->prepare("UPDATE itc_ai_job SET watch=1, status=?, scope=?, msg='', lock_at=NULL, updated_at=NOW() WHERE id=1")->execute([$newSt, $scope]);
      } else {
        $cur = (string)($job['status'] ?? 'idle');
        $newSt = ($cur === 'watch') ? 'idle' : $cur;
        db()->prepare("UPDATE itc_ai_job SET watch=0, status=?, updated_at=NOW() WHERE id=1")->execute([$newSt]);
      }
    } catch (Exception $e) { fail('Не удалось переключить: '.$e->getMessage()); }
    try { itc_log_add(mb_substr(trim((string)($d['by'] ?? '')), 0, 120), 'ai_job_watch', 'on', (string)$on, $scope); } catch (Exception $e) {}
    jout(['ok'=>true, 'job'=>itc_ai_job_get(), 'left'=>itc_ai_job_left($scope)]);
  }
  case 'itc_ai_job_stop': {
    $s = authUser('itc'); require_staff($s, ['boss','supervisor']);
    itc_ai_job_table();
    try { db()->query("UPDATE itc_ai_job SET status='idle', watch=0, msg='Остановлено вручную', lock_at=NULL, updated_at=NOW() WHERE id=1"); } catch (Exception $e) {}
    jout(['ok'=>true, 'job'=>itc_ai_job_get()]);
  }
  /* Шаг из приложения — пока экран открыт, помогаем крону идти быстрее.
     Бюджет маленький (40 секунд), чтобы запрос не отвалился по таймауту. */
  case 'itc_ai_job_work': {
    $s = authUser('itc'); require_staff($s, ['boss','supervisor']);
    @set_time_limit(120);
    list($proc, $moved, $left, $msg) = itc_ai_job_run(25);
    jout(['ok'=>true, 'processed'=>$proc, 'moved'=>$moved, 'left'=>$left, 'msg'=>$msg, 'job'=>itc_ai_job_get()]);
  }
  /* Шаг по расписанию — сюда стучится cron. Бюджет большой: чем реже
     расписание, тем важнее успеть побольше за один заход. */
  case 'itc_ai_job_cron': {
    $cron_key = trim($_GET['cron_key'] ?? ''); $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
    if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
    @set_time_limit(600);
    list($proc, $moved, $left, $msg) = itc_ai_job_run(100);
    header('Content-Type: text/plain; charset=utf-8');
    echo "processed=$proc moved=$moved left=$left $msg\n"; exit;
  }

  /* ИИ добирает то, что не разобрал словарь. Идём ПОРЦИЯМИ: за один вызов
     не больше 100 карточек, фронт зовёт снова, пока left не станет нулём.
     Каждая обработанная карточка помечается ai_cat_at — иначе те, кого ИИ
     тоже отнёс к «Прочее», выбирались бы снова и снова по кругу. */
  case 'itc_autocat_ai': {
    $s = authUser('itc'); require_staff($s, ['boss','supervisor']);
    $d = body();
    $lim = (int)($d['limit'] ?? 100); if ($lim < 10 || $lim > 300) $lim = 100;
    @set_time_limit(300);
    try { db()->query('ALTER TABLE products ADD COLUMN ai_cat_at DATETIME NULL'); } catch (Exception $e) {}
    if (!empty($d['reset'])) { try { db()->query('UPDATE products SET ai_cat_at=NULL'); } catch (Exception $e) {} }

    $cats = [];
    try { foreach (db()->query('SELECT name FROM categories ORDER BY sort, name')->fetchAll() as $c) { $n = trim((string)$c['name']); if ($n !== '' && $n !== 'Прочее') $cats[] = $n; } }
    catch (Exception $e) {}
    if (!$cats) fail('Список категорий пуст — сначала заведите категории');

    $aiScope = ((($d['scope'] ?? 'other')) === 'all') ? 'all' : 'other';
    $cond = ($aiScope === 'all') ? 'ai_cat_at IS NULL'
                                 : "(cat IS NULL OR cat='' OR cat='Прочее') AND ai_cat_at IS NULL";
    $left = 0;
    try { $left = (int)db()->query("SELECT COUNT(*) FROM products WHERE $cond")->fetchColumn(); } catch (Exception $e) {}
    $rows = [];
    try {
      $q = db()->prepare("SELECT id, name, cat, LEFT(COALESCE(descr,''),300) dsc FROM products WHERE $cond ORDER BY id LIMIT $lim");
      $q->execute(); $rows = $q->fetchAll();
    } catch (Exception $e) { fail('Не удалось выбрать товары: '.$e->getMessage()); }
    if (!$rows) jout(['ok'=>true, 'processed'=>0, 'moved'=>0, 'left'=>0, 'groups'=>[], 'ai_ok'=>true]);

    $ask = $cats; $ask[] = 'Прочее';
    $moved = 0; $counts = []; $answered = 0;
    $mark = db()->prepare('UPDATE products SET ai_cat_at=NOW() WHERE id=?');
    $upd  = db()->prepare('UPDATE products SET cat=?, ai_cat_at=NOW() WHERE id=?');
    foreach (array_chunk($rows, 8) as $chunk) {
      $res = itc_ai_cat_batch($chunk, $ask);
      $answered += count($res);
      foreach ($chunk as $r) {
        $c = $res[$r['id']] ?? '';
        if ($c !== '' && $c !== 'Прочее' && $c !== (string)($r['cat'] ?? '')) {
          $upd->execute([$c, $r['id']]); $moved++;
          $counts[$c] = ($counts[$c] ?? 0) + 1;
        } else {
          $mark->execute([$r['id']]);
        }
      }
    }
    arsort($counts);
    $out = []; foreach ($counts as $cn => $n) $out[] = ['cat'=>$cn, 'n'=>$n];
    try { itc_log_add(mb_substr(trim((string)($d['by'] ?? '')), 0, 120), 'itc_autocat_ai', 'ai', '', (string)$moved); } catch (Exception $e) {}
    jout(['ok'=>true, 'processed'=>count($rows), 'moved'=>$moved,
          'left'=>max(0, $left - count($rows)), 'groups'=>$out,
          'ai_ok'=>($answered > 0)]);
  }

  /* АВТО-РАСКЛАДКА ПО КАТЕГОРИЯМ.
     Сначала считаем, что куда уйдёт (mode=preview, ничего не пишем), человек
     смотрит и только потом применяет (mode=apply). Каталог 33 000 карточек,
     поэтому идём кусками по 2000 строк «от последнего id» — иначе PHP не хватит
     памяти, а при apply обычный OFFSET ещё и поехал бы после первых же правок.
     scope=other — трогаем только «Прочее» и пустые (безопасно, ручные правки
     остаются на месте); scope=all — пересобираем весь каталог. */
  case 'itc_autocat': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    $d = body();
    $apply = ((($d['mode'] ?? 'preview')) === 'apply');
    $scope = ((($d['scope'] ?? 'other')) === 'all') ? 'all' : 'other';
    /* Описание по умолчанию НЕ читаем: в нём полно чужих слов («подходит для
       кухни», «зеркальный блеск»), и товары уезжали не туда. Смысл описания
       разбирает ИИ — у него это получается, а у поиска по словам нет. */
    $useDsc = !empty($d['descr']);

    $where = ($scope === 'all') ? '' : " AND (cat IS NULL OR cat='' OR cat='Прочее') ";
    $counts = []; $samples = []; $scanned = 0; $changed = 0; $lastId = '';
    $upd = db()->prepare('UPDATE products SET cat=? WHERE id=?');
    try {
      while (true) {
        $q = db()->prepare("SELECT id, name, cat, LEFT(COALESCE(descr,''),400) dsc
                            FROM products WHERE id > ? $where ORDER BY id LIMIT 2000");
        $q->execute([$lastId]);
        $rows = $q->fetchAll();
        if (!$rows) break;
        foreach ($rows as $r) {
          $lastId = $r['id']; $scanned++;
          $c = $useDsc ? itc_store_category_deep($r['name'] ?? '', $r['dsc'] ?? '')
                       : itc_store_category($r['name'] ?? '');
          $counts[$c] = ($counts[$c] ?? 0) + 1;
          if (!isset($samples[$c])) $samples[$c] = [];
          if (count($samples[$c]) < 3) $samples[$c][] = mb_substr((string)($r['name'] ?? ''), 0, 70);
          if ($c !== (string)($r['cat'] ?? '')) {
            $changed++;
            if ($apply) $upd->execute([$c, $r['id']]);
          }
        }
        if (count($rows) < 2000) break;
      }
    } catch (Exception $e) { fail('Не удалось разложить: '.$e->getMessage()); }

    // Появившиеся категории заводим в справочник, иначе их не будет в списках
    if ($apply) {
      try {
        $mx = (int)(db()->query('SELECT COALESCE(MAX(sort),0) m FROM categories')->fetch()['m'] ?? 0);
        $ins = db()->prepare('INSERT IGNORE INTO categories (name,sort) VALUES (?,?)');
        foreach (array_keys($counts) as $cn) { if ($cn !== '' && $cn !== 'Прочее') { $mx++; $ins->execute([$cn, $mx]); } }
      } catch (Exception $e) {}
      try { itc_log_add(mb_substr(trim((string)($d['by'] ?? '')), 0, 120), 'itc_autocat', 'scope', $scope, (string)$changed); } catch (Exception $e) {}
    }

    arsort($counts);
    $out = [];
    foreach ($counts as $cn => $n) { $out[] = ['cat'=>$cn, 'n'=>$n, 'samples'=>($samples[$cn] ?? [])]; }
    $cats = [];
    try { foreach (db()->query('SELECT name FROM categories ORDER BY sort, name')->fetchAll() as $cr) $cats[] = $cr['name']; }
    catch (Exception $e) {}
    jout(['ok'=>true, 'applied'=>$apply, 'scope'=>$scope, 'scanned'=>$scanned, 'changed'=>$changed, 'groups'=>$out, 'categories'=>$cats]);
  }

  // Пересортировать категории всех товаров по надёжному категоризатору названия.
  /* НОВАЯ КАТЕГОРИЯ «ДЛЯ САЛОНОВ» (обновление №215).
     Сначала СМОТРИМ, что переедет, и только потом двигаем. На 35 тысячах
     карточек ошибка в правиле разъедется по всему каталогу, а откатывать
     нечем: прежняя категория нигде не хранится.
     Открывать так: ?action=itc_cat_salon — только показать;
     с &apply=1 — перенести. */
  /* СТАТИСТИКА ПО ПРИГЛАШЕНИЯМ ДЛЯ КАБИНЕТА (обновление №220).
     Отдаём только ЧИСЛА: имён и телефонов приглашённых здесь нет и не будет —
     это чужие персональные данные, а для дела достаточно количества и сумм. */
  case 'ref_stats': {
    /* Роль не проверяем: программа для физлица, но зайти в неё может и
       сотрудник, который смотрит магазин глазами покупателя. Требование
       роли «покупатель» отсекало его и показывало пустой экран. */
    $s = authUser();
    itc_ref_ensure();
    $phone = (string)($s['phone'] ?? '');
    $code  = itc_ref_code($phone);
    $out = ['ok'=>true,'code'=>$code,'invited'=>0,'bought'=>0,'sum'=>0,'earned'=>0,
            'l2'=>0,'l2bought'=>0,'l2sum'=>0,'l2earned'=>0,'accrued'=>0,'avail'=>0];

    if ($code !== '') {
      try {
        // первый круг — те, кто пришёл по моему коду
        $q = db()->prepare('SELECT phone FROM customers WHERE ref_by=?');
        $q->execute([$code]);
        $l1 = array_column($q->fetchAll(), 'phone');
        $out['invited'] = count($l1);

        if ($l1) {
          $in = implode(',', array_fill(0, count($l1), '?'));
          // покупки за последние 30 дней — только оплаченные
          $r = db()->prepare("SELECT COUNT(DISTINCT phone) c, COALESCE(SUM(total),0) s
                              FROM orders WHERE paid=1 AND created_at >= (NOW() - INTERVAL 30 DAY)
                              AND phone IN ($in)");
          $r->execute($l1);
          $row = $r->fetch();
          $out['bought'] = (int)($row['c'] ?? 0);
          $out['sum']    = (int)round((float)($row['s'] ?? 0));

          // второй круг — кого пригласили мои приглашённые
          $cq = db()->prepare("SELECT ref_code FROM customers WHERE phone IN ($in) AND ref_code IS NOT NULL AND ref_code<>''");
          $cq->execute($l1);
          $codes = array_column($cq->fetchAll(), 'ref_code');
          if ($codes) {
            $in2 = implode(',', array_fill(0, count($codes), '?'));
            $q2 = db()->prepare("SELECT phone FROM customers WHERE ref_by IN ($in2)");
            $q2->execute($codes);
            $l2 = array_column($q2->fetchAll(), 'phone');
            $out['l2'] = count($l2);
            if ($l2) {
              $in3 = implode(',', array_fill(0, count($l2), '?'));
              $r2 = db()->prepare("SELECT COUNT(DISTINCT phone) c, COALESCE(SUM(total),0) s
                                   FROM orders WHERE paid=1 AND created_at >= (NOW() - INTERVAL 30 DAY)
                                   AND phone IN ($in3)");
              $r2->execute($l2);
              $row2 = $r2->fetch();
              $out['l2bought'] = (int)($row2['c'] ?? 0);
              $out['l2sum']    = (int)round((float)($row2['s'] ?? 0));
            }
          }
        }
      } catch (Exception $e) {}

      // движения по бонусам: начислено всего и что уже можно тратить
      try {
        /* Траты пишем ОТРИЦАТЕЛЬНЫМИ строками с тем же статусом available —
           тогда остаток считается обычной суммой и не расходится с историей.
           «Начислено всего» траты не уменьшают: это итог за всё время. */
        $b = db()->prepare("SELECT
              COALESCE(SUM(CASE WHEN status IN ('accrued','available') AND amount > 0 THEN amount ELSE 0 END),0) accrued,
              COALESCE(SUM(CASE WHEN status='available' THEN amount ELSE 0 END),0) avail,
              COALESCE(SUM(CASE WHEN kind='ref1' THEN amount ELSE 0 END),0) e1,
              COALESCE(SUM(CASE WHEN kind='ref2' THEN amount ELSE 0 END),0) e2
              FROM itc_bonus WHERE phone=?");
        $b->execute([$phone]);
        $bb = $b->fetch();
        $out['accrued']  = (int)round((float)($bb['accrued'] ?? 0));
        $out['avail']    = (int)round((float)($bb['avail'] ?? 0));
        $out['earned']   = (int)round((float)($bb['e1'] ?? 0));
        $out['l2earned'] = (int)round((float)($bb['e2'] ?? 0));
      } catch (Exception $e) {}
    }
    jout($out);
  }

  /* СВОДКА ПО ПРОГРАММЕ ДЛЯ КАБИНЕТА БОССА (обновление №221).
     Здесь имена нужны: это ЕГО клиенты, и он вправе видеть, кто работает.
     Главная колонка — сколько приглашённых реально купили: она и отделяет
     тех, кто приводит покупателей, от тех, кто набивает список. */
  /* КОНВЕРТЫ ПОКУПАТЕЛЯ (обновление №222). */
  case 'env_list': {
    $s = authUser();
    $phone = (string)($s['phone'] ?? '');
    itc_env_burn($phone);
    $rows = [];
    try {
      $q = db()->prepare("SELECT id,amount,status,reason,sent_at,open_by,opened_at,spend_by
                          FROM itc_envelope WHERE phone=? AND status IN ('new','opened')
                          ORDER BY (status='new') DESC, id ASC");
      $q->execute([$phone]);
      foreach ($q->fetchAll() as $r) {
        $till = ($r['status'] === 'new') ? $r['open_by'] : $r['spend_by'];
        $days = null;
        if ($till) { $days = (int)floor((strtotime($till) - time()) / 86400); if ($days < 0) $days = 0; }
        $rows[] = ['id'=>(int)$r['id'],'amount'=>(int)round((float)$r['amount']),'status'=>$r['status'],
                   'reason'=>(string)$r['reason'],'till'=>$till,'days'=>$days];
      }
    } catch (Exception $e) {}
    $sum = 0; foreach ($rows as $r) if ($r['status'] === 'opened') $sum += $r['amount'];
    jout(['ok'=>true,'rows'=>$rows,'ready'=>$sum]);
  }

  case 'env_open': {
    $s = authUser();
    $phone = (string)($s['phone'] ?? '');
    itc_env_burn($phone);
    $d = body();
    $id = (int)($d['id'] ?? 0);
    if ($id < 1) fail('Не указан конверт');
    $row = null;
    try {
      $q = db()->prepare("SELECT id,amount,status FROM itc_envelope WHERE id=? AND phone=? LIMIT 1");
      $q->execute([$id, $phone]); $row = $q->fetch();
    } catch (Exception $e) {}
    if (!$row) fail('Конверт не найден');
    if ($row['status'] === 'burned') fail('Срок конверта истёк');
    if ($row['status'] !== 'new')    fail('Конверт уже открыт');
    /* Открыли — пошёл второй срок: 30 дней на трату. */
    try {
      db()->prepare("UPDATE itc_envelope SET status='opened', opened_at=NOW(),
                     spend_by=(NOW() + INTERVAL 30 DAY) WHERE id=? AND status='new'")->execute([$id]);
    } catch (Exception $e) { fail('Не удалось открыть'); }
    jout(['ok'=>true,'amount'=>(int)round((float)$row['amount'])]);
  }

  /* РАССЫЛКА КОНВЕРТОВ ИЗ КАБИНЕТА БОССА.
     Кому: всем · по уровню · одному телефону. Сумма и повод задаются им же. */
  /* НАЧИСЛИТЬ БОНУСЫ ВРУЧНУЮ (обновление №226).
     Нужно, чтобы проверить трату до того, как включатся автоматические
     начисления. Сразу кладём доступными: это ручная выдача, срока возврата
     ждать не от чего. */
  case 'bonus_grant': {
    $s = authUser('itc'); require_staff($s, ['boss']);
    itc_ref_ensure();
    $d = body();
    $amount = (int)($d['amount'] ?? 0);
    $phone1 = trim((string)($d['phone'] ?? ''));
    if ($amount === 0) fail('Укажите сумму');
    if ($phone1 === '') fail('Укажите телефон');
    $dig = preg_replace('/\D/', '', $phone1); $tail = substr($dig, -10);
    $q = db()->prepare("SELECT phone FROM customers
                        WHERE RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(phone,'+',''),'-',''),' ',''),'(',''), 10) = ? LIMIT 1");
    $q->execute([$tail]);
    $p = (string)$q->fetchColumn();
    if ($p === '') fail('Такого покупателя нет: '.$phone1);
    db()->prepare("INSERT INTO itc_bonus (phone,kind,amount,status,created_at) VALUES (?,'manual',?, 'available', NOW())")
        ->execute([$p, $amount]);
    itc_log_add(($s['name'] ?? ''), 'bonus_grant', 'bonus', $p, $amount.' ₽');
    jout(['ok'=>true,'phone'=>$p,'amount'=>$amount]);
  }

  /* Переключатель автовыдачи: читаем и сохраняем. */
  case 'env_auto': {
    $s = authUser('itc'); require_staff($s, ['boss']);
    $d = body();
    if (isset($d['save'])) {
      itc_set_put('env_reg_on', !empty($d['on']) ? '1' : '0');
      $amt = (int)($d['amount'] ?? 200);
      if ($amt > 0 && $amt <= 100000) itc_set_put('env_reg_amount', $amt);
      itc_log_add(($s['name'] ?? ''), 'env_auto', 'settings', '', (!empty($d['on'])?'включено ':'выключено ').$amt.' ₽');
    }
    jout(['ok'=>true,'on'=>(itc_set_get('env_reg_on','0')==='1'),'amount'=>(int)itc_set_get('env_reg_amount','200')]);
  }

  case 'env_send': {
    $s = authUser('itc'); require_staff($s, ['boss']);
    itc_ref_ensure();
    $d = body();
    $amount = (int)($d['amount'] ?? 0);
    $reason = mb_substr(trim((string)($d['reason'] ?? '')), 0, 120);
    $who    = (string)($d['who'] ?? 'all');       // all · level · phone
    $level  = (string)($d['level'] ?? '');
    $phone1 = trim((string)($d['phone'] ?? ''));
    if ($amount < 1)  fail('Укажите сумму конверта');
    if ($amount > 100000) fail('Слишком большая сумма');

    $targets = [];
    try {
      if ($who === 'phone') {
        if ($phone1 === '') fail('Укажите телефон');
        /* Телефон ищем ПО ЦИФРАМ, а не строкой. В базе он может лежать как
           +79184803066, 79184803066 или 8 (918) 480-30-66 — точное совпадение
           отсекало нужного человека, и рассылка молча уходила в никуда.
           Сверяем последние десять цифр: этого достаточно и для 8, и для +7. */
        $dig = preg_replace('/\D/', '', $phone1);
        $tail = substr($dig, -10);
        $q = db()->prepare("SELECT phone FROM customers
                            WHERE RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(phone,'+',''),'-',''),' ',''),'(',''), 10) = ?
                            LIMIT 5");
        $q->execute([$tail]);
        $targets = array_column($q->fetchAll(), 'phone');
        if (!$targets) fail('Такого покупателя нет. Проверьте номер: '.$phone1);
      } else {
        // считаем приглашённых, чтобы определить уровень каждого
        $inv = [];
        foreach (db()->query("SELECT ref_by, COUNT(*) c FROM customers WHERE ref_by IS NOT NULL AND ref_by<>'' GROUP BY ref_by")->fetchAll() as $r)
          $inv[(string)$r['ref_by']] = (int)$r['c'];
        foreach (db()->query("SELECT phone,ref_code FROM customers")->fetchAll() as $c) {
          $n = (isset($inv[(string)$c['ref_code']]) ? $inv[(string)$c['ref_code']] : 0);
          $lv = 'start';
          if ($n >= 150) $lv = 'brilliant'; elseif ($n >= 50) $lv = 'gold'; elseif ($n >= 3) $lv = 'silver';
          if ($who === 'all' || ($who === 'level' && $lv === $level)) $targets[] = $c['phone'];
        }
      }
    } catch (Exception $e) {}
    if (!$targets) jout(['ok'=>false,'error'=>'Некому отправлять — под условие никто не подошёл']);

    $sent = 0;
    try {
      $ins = db()->prepare("INSERT INTO itc_envelope (phone,amount,status,reason,sent_at,open_by)
                            VALUES (?,?,'new',?,NOW(),(NOW() + INTERVAL 7 DAY))");
      foreach ($targets as $p) { $ins->execute([$p, $amount, $reason]); $sent++; }
    } catch (Exception $e) {}
    itc_log_add(($s['name'] ?? ''), 'env_send', 'envelope', '', $amount.' ₽ × '.$sent);
    jout(['ok'=>true,'sent'=>$sent,'amount'=>$amount]);
  }

  /* ПРОВЕРКА КОНВЕРТОВ (обновление №224). Открывать в браузере:
     ?action=env_check&key=…&phone=+79184803066
     Показывает, что реально лежит в базе у этого номера — рассылка ушла или нет. */
  case 'env_check': {
    header('Content-Type: text/plain; charset=utf-8');
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) { echo "Нужен ключ\n"; exit; }
    itc_ref_ensure();
    $p = trim((string)($_GET['phone'] ?? ''));
    $dig = preg_replace('/\D/', '', $p); $tail = substr($dig, -10);
    echo "=== ПРОВЕРКА КОНВЕРТОВ ===\n\nИщем номер: ".$p." (последние 10 цифр: ".$tail.")\n\n";
    try {
      $q = db()->prepare("SELECT phone,name FROM customers
                          WHERE RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(phone,'+',''),'-',''),' ',''),'(',''), 10) = ?");
      $q->execute([$tail]);
      $cs = $q->fetchAll();
      echo "Найдено покупателей: ".count($cs)."\n";
      foreach ($cs as $c) {
        echo "  «".$c['phone']."» — ".$c['name']."\n";
        $e = db()->prepare("SELECT id,amount,status,reason,sent_at,open_by,spend_by FROM itc_envelope WHERE phone=? ORDER BY id DESC LIMIT 20");
        $e->execute([$c['phone']]);
        $rows = $e->fetchAll();
        echo "    конвертов: ".count($rows)."\n";
        foreach ($rows as $r)
          echo "      #".$r['id']." · ".(int)$r['amount']." ₽ · ".$r['status']." · выдан ".$r['sent_at']." · открыть до ".$r['open_by']."\n";
      }
      $all = db()->query("SELECT COUNT(*) c FROM itc_envelope")->fetch();
      echo "\nВсего конвертов в базе: ".(int)($all['c'] ?? 0)."\n";
    } catch (Exception $e) { echo "Ошибка: ".$e->getMessage()."\n"; }
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  case 'ref_admin': {
    $s = authUser('itc'); require_staff($s, ['boss','manager']);
    itc_ref_ensure();
    $lv = [['start',0],['silver',3],['gold',50],['brilliant',150]];
    $counts = ['start'=>0,'silver'=>0,'gold'=>0,'brilliant'=>0];
    $rows = [];
    try {
      // сколько людей привёл каждый код
      $inv = [];
      foreach (db()->query("SELECT ref_by, COUNT(*) c FROM customers
                            WHERE ref_by IS NOT NULL AND ref_by<>'' GROUP BY ref_by")->fetchAll() as $r) {
        $inv[(string)$r['ref_by']] = (int)$r['c'];
      }
      // все клиенты с их кодами
      $all = db()->query("SELECT phone,name,ref_code FROM customers")->fetchAll();
      foreach ($all as $c) {
        $code = (string)($c['ref_code'] ?? '');
        $n = ($code !== '' && isset($inv[$code])) ? $inv[$code] : 0;
        $code_lv = 'start';
        foreach ($lv as $x) { if ($n >= $x[1]) $code_lv = $x[0]; }
        $counts[$code_lv]++;
        if ($n > 0) $rows[] = ['phone'=>$c['phone'],'name'=>$c['name'],'code'=>$code,'invited'=>$n,'level'=>$code_lv];
      }
      // покупки приглашённых за 30 дней — по каждому пригласившему
      foreach ($rows as &$r) {
        $r['bought'] = 0; $r['sum'] = 0;
        try {
          $q = db()->prepare("SELECT COUNT(DISTINCT o.phone) c, COALESCE(SUM(o.total),0) s
                              FROM orders o JOIN customers cu ON cu.phone=o.phone
                              WHERE cu.ref_by=? AND o.paid=1 AND o.created_at >= (NOW() - INTERVAL 30 DAY)");
          $q->execute([$r['code']]);
          $x = $q->fetch();
          $r['bought'] = (int)($x['c'] ?? 0);
          $r['sum'] = (int)round((float)($x['s'] ?? 0));
        } catch (Exception $e) {}
        // подсветка: людей привёл, а покупок нет
        $r['flag'] = ($r['invited'] >= 3 && $r['bought'] === 0) ? 1 : 0;
      }
      unset($r);
      usort($rows, function($a,$b){ return $b['invited'] - $a['invited']; });
      $rows = array_slice($rows, 0, 100);
    } catch (Exception $e) {}
    /* СВЕРКА (23.08.2026). Раньше пустой список нельзя было отличить от
       поломки: «никто никого не пригласил» выглядит одинаково и когда
       ссылками не пользуются, и когда привязка не срабатывает. Теперь видно
       обе цифры — сколько людей вообще пришло по ссылке и у скольких есть
       свой код. */
    $chk = ['linked'=>0, 'with_code'=>0, 'total'=>0];
    try {
      $chk['total']     = (int)db()->query("SELECT COUNT(*) FROM customers")->fetchColumn();
      $chk['with_code'] = (int)db()->query("SELECT COUNT(*) FROM customers WHERE ref_code IS NOT NULL AND ref_code<>''")->fetchColumn();
      $chk['linked']    = (int)db()->query("SELECT COUNT(*) FROM customers WHERE ref_by IS NOT NULL AND ref_by<>''")->fetchColumn();
    } catch (Exception $e) {}
    jout(['ok'=>true,'counts'=>$counts,'rows'=>$rows,'check'=>$chk]);
  }

  case 'itc_cat_salon':
  case 'itc_cat_check': {
    /* Показ переезда для ЛЮБОЙ категории: ?action=itc_cat_check&cat=Подарки
       Старое имя itc_cat_salon оставлено рабочим — ссылка уже в ходу. */
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(600);
    /* ПОКАЗ — БЕЗ ВХОДА, ПЕРЕНОС — ПО КЛЮЧУ.
       Ссылку открывают в обычном браузере, где входа в кабинет нет: с проверкой
       входа она отвечала «Не авторизован» и посмотреть список было нельзя.
       Показ ничего не меняет, поэтому открыт — как остальные проверочные
       ссылки. А вот перенос трогает 35 тысяч карточек, и запускать его случайной
       ссылкой нельзя: для него нужен тот же ключ, что стоит у вас в расписании
       переноса фото. */
    $apply = !empty($_GET['apply']);
    if ($apply && !hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      echo "Для переноса нужен ключ. Добавьте к ссылке &key=… — он тот же, что в задании переноса фото.\n";
      exit;
    }

    $target = trim((string)($_GET['cat'] ?? 'Для салонов'));
    if ($target === '') $target = 'Для салонов';
    echo "=== КАТЕГОРИЯ «".$target."» ===\n";
    echo ($apply ? "Режим: ПЕРЕНОС\n\n" : "Режим: только показать (для переноса добавьте &apply=1)\n\n");

    $rows = [];
    try { $rows = db()->query("SELECT id,name,cat FROM products")->fetchAll(); } catch (Exception $e) {}
    $move = []; $from = [];
    foreach ($rows as $r) {
      if (itc_store_category($r['name']) !== $target) continue;
      $was = (string)($r['cat'] ?? '');
      if ($was === $target) continue;
      $move[] = $r;
      $from[$was === '' ? '(без категории)' : $was] = ($from[$was === '' ? '(без категории)' : $was] ?? 0) + 1;
    }
    echo 'Всего карточек: '.count($rows)."\n";
    echo 'Переедет в «'.$target.'»: '.count($move)."\n\n";

    if ($from) {
      echo "--- ОТКУДА ЗАБИРАЕМ ---\n";
      arsort($from);
      foreach ($from as $k => $v) echo '  '.$k.': '.$v."\n";
    }

    echo "\n--- ПЕРВЫЕ 40 НАЗВАНИЙ ---\n";
    $n = 0;
    foreach ($move as $r) {
      echo '  '.mb_substr((string)$r['name'], 0, 95)."\n";
      if (++$n >= 40) break;
    }

    if ($apply) {
      $ok = 0;
      try {
        $u = db()->prepare("UPDATE products SET cat=? WHERE id=?");
        foreach ($move as $r) { $u->execute([$target, $r['id']]); $ok++; }
      } catch (Exception $e) { echo "\nОшибка переноса: ".mb_substr($e->getMessage(), 0, 120)."\n"; }
      echo "\nПеренесено: {$ok}\n";
      itc_log_add('', 'cat_move', 'products', '', $target.': перенесено '.$ok);
    } else {
      echo "\nНичего не изменено. Если список верный — откройте эту же ссылку с &apply=1\n";
    }
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* ПОЛНЫЙ ПЕРЕСЧЁТ КАТЕГОРИЙ. Категории у нас вычисляются правилами, поэтому
     это же и способ отката: поправили правило — пересчитали, и всё разложилось
     заново. Ключ тот же, что у переноса салонов. */
  /* ПРОВЕРКА ЦЕН ПОСЛЕ ОШИБКИ С ВАРИАНТАМИ (24.08.2026).
     Пока отслеживание брало минимальную цену карточки, оно могло записать
     закупочную цену ЧУЖОГО варианта и пересчитать по ней витрину.
     Показ:   ?action=itc_price_check&key=МАСТЕР
     Починка: ?action=itc_price_check&key=МАСТЕР&fix=1

     ЧИНИМ НЕ ВСЁ ПОДРЯД. Цена товара законно меняется и сама — если просто
     вернуть цену с момента завоза, мы откатим честные подорожания по всему
     магазину, а это хуже исходной ошибки. Поэтому чиним только то, где виден
     ПОЧЕРК ошибки: у товара стоит ровно минимальная цена по карточке, а его
     собственный вариант стоит других денег. Всё прочее только показываем —
     разбираться руками. С &all=1 чинится и остальное, но это осознанный шаг.
     Сеть не дёргаем: сверка идёт по нашей базе, быстро и без нагрузки. */
  /* СКОЛЬКО ЗАПРОСОВ МЫ ТРАТИМ И ХВАТАЕТ ЛИ ЛИМИТА (25.08.2026).
     Прежде чем учить светофор тянуть цену через платный API, надо знать
     три вещи: сколько карточек под наблюдением, во сколько запросов это
     выльется по расписанию A=7 / B=21 / C=90 дней, и какой у нас потолок.
     Ничего не меняет — только считает и показывает.
     Открывать: ?action=itc_ob_limits&key=МАСТЕР
     Расход у посредника спрашиваем запросом ИЗ КЭША — он бесплатный. */
  /* СТАТИСТИКА КАТАЛОГА И АРХИВА (25.08.2026, просьба Алексея).
     Одним взглядом: сколько живых, сколько пропало и на каком они круге
     переспроса, сколько вернулось, удалено и оставлено из-за заказов.
     Открывать: ?action=itc_catalog_stats&key=МАСТЕР  (или боссом из кабинета) */
  /* СПИСОК НА УДАЛЕНИЕ (25.08.2026, просьба Алексея).
     Товар лежит в карантине месяц — вот он, весь, с датами и ценами.
     Смотреть:  ?action=itc_pending_delete&key=МАСТЕР
     Помиловать: ?action=itc_pending_delete&key=МАСТЕР&spare=<id ds-карточки>
                 (снимает приговор; товар остаётся в архиве и переспрашивается заново)
     Помиловать всех: ...&spare=all  — если увидел массовый сбой */
  /* ПРОВЕРКА ОДНОЙ КАРТОЧКИ С РАЗБОРОМ (25.08.2026).
     Показывает по каждому нашему товару этой карточки: какой у него код
     варианта, какую цену вернул 1688 именно по нему, опознался ли вариант
     и что стоит у нас. Ничего не меняет — только смотрит.
     ?action=itc_offer_probe&key=МАСТЕР&iid=930170387774 */
  /* №876: СТУПЕНЧАТЫЕ ЦЕНЫ 1688. Служебная проверка: какие поля про цену от
     количества (阶梯价), минимальный заказ и цену за одну штуку отдаёт onebound.
     Ничего не меняет и не сохраняет. &url= — ссылка или текст из приложения 1688. */
  /* №877: ДОСТАВКА ПО КИТАЮ В ЦЕНЕ. Шаг 1 — только смотрим, ничего не меняем.
     mode=probe (по умолчанию): где в кэше 1688 (ob_raw) лежит доставка продавца (post_fee) и у скольких товаров она есть.
     mode=preview: у каких товаров цена вырастет и насколько, если к закупке добавить доставку продавца. */
  /* №878: доставка по Китаю и минимальный заказ для корзины (без входа тоже — гостевая корзина) */
  case 'cart_cn_ship': {
    $d = body(); $ids = []; foreach ((array)($d['items'] ?? []) as $x) { $ids[] = is_array($x) ? (string)($x['id'] ?? '') : (string)$x; }
    $ids = array_slice(array_values(array_unique(array_filter($ids))), 0, 80);
    $r = itc_cn_ship($ids); $min = [];
    if ($ids) { $in = implode(',', array_fill(0, count($ids), '?')); $q = db()->prepare("SELECT id,price FROM products WHERE id IN ($in)"); $q->execute($ids);
      foreach ($q->fetchAll() as $p) { $mq = itc_min_qty($p['price']); if ($mq > 1) $min[$p['id']] = $mq; } }
    $c = itc_cn_ship_cfg();
    jout(['ok'=>true, 'rub'=>$r['rub'], 'groups'=>$r['groups'], 'min'=>$min ?: new stdClass(), 'cheap'=>$c['cheap'], 'minsum'=>$c['minsum']]);
  }

  case 'itc_postfee': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $okBoss = false; $ct = trim($_COOKIE['itc_t'] ?? '');
      if ($ct !== '') { try { $q = db()->prepare('SELECT role,staff_role FROM sessions WHERE token=? LIMIT 1'); $q->execute([$ct]); $r = $q->fetch();
        $okBoss = $r && $r['role'] === 'itc' && in_array((string)($r['staff_role'] ?? ''), ['boss',''], true); } catch (Exception $e) {} }
      if (!$okBoss) { $s=authUser('itc'); require_staff($s,['boss']); }
    }
    @set_time_limit(240);
    $cols = []; try { foreach (db()->query('SHOW COLUMNS FROM ob_raw')->fetchAll() as $c) $cols[$c['Field']] = $c['Type']; } catch (Exception $e) { fail('Нет таблицы кэша ob_raw: '.$e->getMessage()); }
    $idc = ''; foreach (['num_iid','iid','item_id','offer_id','id'] as $c) if (isset($cols[$c])) { $idc = $c; break; }
    $jc = ''; foreach (['raw','json','data','body','resp','response','payload'] as $c) if (isset($cols[$c])) { $jc = $c; break; }
    if ($jc === '') foreach ($cols as $c => $t) if (preg_match('~text|json|blob~i', $t)) { $jc = $c; break; }
    $out = ['ok'=>true, 'колонки_кэша'=>$cols, 'номер'=>$idc, 'ответ'=>$jc];
    if ($idc === '' || $jc === '') jout($out + ['ошибка'=>'не нашёл колонки с номером товара или ответом']);
    /* путь до post_fee — по одному образцу */
    $find = function($a, $pre) use (&$find) { if (!is_array($a)) return null; foreach ($a as $k => $v) { if ($k === 'post_fee') return array_merge($pre, [$k]); if (is_array($v) && !isset($v[0])) { $r = $find($v, array_merge($pre, [$k])); if ($r) return $r; } } return null; };
    $path = null; $smp = db()->query("SELECT `$jc` j FROM ob_raw ORDER BY RAND() LIMIT 20")->fetchAll();
    foreach ($smp as $sm) { $j = json_decode((string)$sm['j'], true); if (!is_array($j)) { $z = @gzuncompress((string)$sm['j']); if ($z === false) $z = @gzdecode((string)$sm['j']); if ($z !== false) $j = json_decode($z, true); } $pp = $find($j, []); if ($pp) { $path = $pp; break; } }
    $out['путь_post_fee'] = $path ? implode('.', $path) : null;
    if (!$path) jout($out + ['ошибка'=>'в образцах кэша поле доставки не найдено']);
    $jp = '$.' . implode('.', array_map(function($k){ return '"'.str_replace('"','',$k).'"'; }, $path));
    $cnt = db()->query("SELECT COUNT(*) n, SUM(CAST(JSON_UNQUOTE(JSON_EXTRACT(`$jc`, '$jp')) AS DECIMAL(10,2)) > 0) paid FROM ob_raw WHERE JSON_VALID(`$jc`)")->fetch();
    $out['товаров_в_кэше'] = (int)$cnt['n']; $out['с_платной_доставкой'] = (int)$cnt['paid'];
    if (($_GET['mode'] ?? '') !== 'preview') jout($out);
    /* предпросмотр: карточки 1688 с ценой, сравнение «сейчас» и «с доставкой» */
    $fee = [];
    foreach (db()->query("SELECT `$idc` iid, CAST(JSON_UNQUOTE(JSON_EXTRACT(`$jc`, '$jp')) AS DECIMAL(10,2)) f FROM ob_raw WHERE JSON_VALID(`$jc`)")->fetchAll() as $r) if ((float)$r['f'] > 0) $fee[(string)$r['iid']] = (float)$r['f'];
    $rows = db()->query("SELECT d.id, d.product_id, d.source_url, d.source_price_cny, d.declared_volume_m3, d.declared_weight_kg, d.x3_pending, d.x3_mult, p.name, p.price
                           FROM ds_products d JOIN products p ON p.id=d.product_id WHERE d.source_price_cny > 0 AND COALESCE(p.blocked,0)=0")->fetchAll();
    $list = []; $up = 0; $sumOld = 0; $sumNew = 0; $buckets = ['до 10%'=>0,'10–30%'=>0,'30–100%'=>0,'больше 100%'=>0];
    foreach ($rows as $r) {
      if (!preg_match('~offer/(\d+)~', (string)$r['source_url'], $m)) continue; $f = $fee[$m[1]] ?? 0; if ($f <= 0) continue;
      $c = (float)$r['source_price_cny'];
      if (!empty($r['x3_pending'])) { $mult = ($r['x3_mult'] > 0) ? (float)$r['x3_mult'] : null; $a = ds_calc_price_x3($c, $mult); $b = ds_calc_price_x3($c + $f, $mult); }
      elseif ((float)$r['declared_volume_m3'] > 0) { $a = ds_calc_price_rub($c, (float)$r['declared_volume_m3'], (float)$r['declared_weight_kg']); $b = ds_calc_price_rub($c + $f, (float)$r['declared_volume_m3'], (float)$r['declared_weight_kg']); }
      else continue;
      if ($b <= $a) continue; $up++; $pct = $a > 0 ? ($b - $a) / $a * 100 : 0; $sumOld += $a; $sumNew += $b;
      $buckets[$pct < 10 ? 'до 10%' : ($pct < 30 ? '10–30%' : ($pct < 100 ? '30–100%' : 'больше 100%'))]++;
      $list[] = ['товар'=>mb_substr((string)$r['name'], 0, 70), 'закупка_¥'=>$c, 'доставка_¥'=>$f, 'сейчас_₽'=>(int)$r['price'], 'по_расчёту_сейчас_₽'=>$a, 'с_доставкой_₽'=>$b, 'рост_%'=>round($pct)];
    }
    usort($list, function($x, $y){ return $y['рост_%'] <=> $x['рост_%']; });
    jout($out + ['карточек_1688'=>count($rows), 'вырастет_цена'=>$up, 'по_росту'=>$buckets, 'самые_большие_изменения'=>array_slice($list, 0, 40)]);
  }

  /* №… · ВСЕ ЗАКАЗЫ С КОНТАКТАМИ ПОКУПАТЕЛЕЙ (06.11.2026, просьба Алексея) — файл для Excel.
   Открывает только босс: по ссылке из браузера, где он вошёл в магазин. */
case 'orders_contacts': {
  $okBoss = false; $ct = trim($_COOKIE['itc_t'] ?? '');
  if ($ct !== '') {
    try { $q = db()->prepare('SELECT role,staff_role FROM sessions WHERE token=? LIMIT 1'); $q->execute([$ct]); $r = $q->fetch();
          $okBoss = $r && $r['role'] === 'itc' && in_array((string)($r['staff_role'] ?? ''), ['boss',''], true); } catch (Exception $e) {}
  }
  if (!$okBoss) { $s=authUser('itc'); require_staff($s,['boss']); }
  $st = ['new'=>'Новый','pending'=>'Ждёт оплаты','paid'=>'Оплачен','ordered'=>'Заказан у поставщика','china'=>'На складе в Китае','at_warehouse'=>'На складе','stock'=>'На складе','received'=>'Получен','done'=>'Выполнен','closed'=>'Закрыт','cancelled'=>'Отменён','canceled'=>'Отменён','rejected'=>'Отклонён'];
  $q = function($x){ return str_replace([';',"\r","\n","\t"], [',',' ',' ',' '], trim((string)$x)); };
  $ph = function($x){ $d = preg_replace('~\D~', '', (string)$x); if ($d === '') return ''; if (strlen($d) === 11 && $d[0] === '8') $d = '7' . substr($d, 1); if (strlen($d) === 10) $d = '7' . $d; return '+' . $d; };
  $cust = [];
  try { foreach (db()->query("SELECT phone,name,email,city FROM customers")->fetchAll() as $c) $cust[$c['phone']] = $c; } catch (Exception $e) {}
  $iq = db()->prepare("SELECT name,qty,price FROM order_items WHERE order_id=?");
  $rows = db()->query("SELECT o.*, DATE_FORMAT(o.created_at,'%d.%m.%Y %H:%i') dt FROM orders o ORDER BY o.created_at DESC")->fetchAll();
  $csv = "\xEF\xBB\xBF" . "№ заказа;Дата;Статус;Оплачен;Сумма, ₽;Покупатель (аккаунт);Телефон покупателя;E-mail;Получатель;Телефон получателя;Город;Адрес;Комментарий;Товары\r\n";
  $n = 0;
  foreach ($rows as $o) {
    $c = $cust[$o['phone']] ?? [];
    $iq->execute([$o['id']]); $it = [];
    foreach ($iq->fetchAll() as $i) $it[] = $q($i['name']) . ' × ' . (int)$i['qty'] . ' (' . rtrim(rtrim(number_format((float)$i['price'], 2, '.', ''), '0'), '.') . ' ₽)';
    $csv .= implode(';', [$q($o['num'] ?: $o['id']), $o['dt'], $st[$o['status'] ?? ''] ?? $q($o['status'] ?? ''), !empty($o['paid']) ? 'да' : 'нет',
      number_format((float)$o['total'], 0, ',', ''), $q($c['name'] ?? ''), $ph($o['phone']), $q(($o['email'] ?? '') ?: ($c['email'] ?? '')),
      $q($o['addr_name'] ?? ''), $ph($o['addr_phone'] ?? ''), $q(($o['addr_city'] ?? '') ?: ($c['city'] ?? '')), $q(trim(($o['addr_street'] ?? '') . ' ' . ($o['addr_zip'] ?? ''))), $q($o['addr_note'] ?? ''),
      implode(' | ', $it)]) . "\r\n";
    $n++;
  }
  header_remove('Content-Type');
  header('Content-Type: text/csv; charset=utf-8');
  header('Content-Disposition: attachment; filename="zakazy_kontakty_' . date('Y-m-d') . '.csv"');
  header('Cache-Control: no-store');
  echo $csv; exit;
}
case 'itc_price_tiers': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      /* Открывают ссылкой в браузере — токена в адресе нет. Берём вход босса
         из той же метки, по которой магазин узнаёт вошедшего (whoami). */
      $okBoss = false; $ct = trim($_COOKIE['itc_t'] ?? '');
      if ($ct !== '') {
        try { $q = db()->prepare('SELECT role,staff_role FROM sessions WHERE token=? LIMIT 1'); $q->execute([$ct]); $r = $q->fetch();
              $okBoss = $r && $r['role'] === 'itc' && in_array((string)($r['staff_role'] ?? ''), ['boss',''], true); } catch (Exception $e) {}
      }
      if (!$okBoss) { $s=authUser('itc'); require_staff($s,['boss']); }
    }
    $u = itc_1688_normalize((string)($_GET['url'] ?? ($_GET['iid'] ?? '')));
    $iid = preg_match('~offer/(\d+)~', $u, $m) ? $m[1] : '';
    if ($iid === '') fail('Не удалось разобрать ссылку: '.$u);
    $rr = ob_call('item_get', ['num_iid'=>$iid], ['cache'=>'no']);
    $dd = is_array($rr['data'] ?? null) ? $rr['data'] : [];
    $it = $dd['item'] ?? ($dd['items']['item'] ?? null);
    if (is_array($it) && isset($it[0]) && is_array($it[0])) $it = $it[0];
    if (!is_array($it)) { jout(['ok'=>false,'карточка'=>$iid,'код_ответа'=>($rr['error_code'] ?? null),'причина'=>($rr['reason'] ?? null),'верхние_поля'=>array_keys($dd)]); break; }
    $re = '~price|range|qty|quantity|min|num|sale|begin|step|amount|consign|daifa|fenxiao|wholesale|unit|freight|post|代发|起批|阶梯~iu';
    $found = [];
    $walk = function($a, $path, $depth) use (&$walk, &$found, $re) {
      if ($depth > 4 || count($found) > 80) return;
      foreach ($a as $k => $v) {
        $kp = $path === '' ? (string)$k : $path.'.'.$k;
        if (in_array((string)$k, ['desc','desc_img','item_imgs','prop_imgs','props_img','description'], true)) continue;
        if (preg_match($re, (string)$k)) {
          $j = json_encode($v, JSON_UNESCAPED_UNICODE);
          $found[$kp] = mb_strlen($j) > 1500 ? mb_substr($j, 0, 1500).'…' : $v;
        } elseif (is_array($v) && !isset($v[0])) {
          $walk($v, $kp, $depth + 1);
        }
      }
    };
    $walk($it, '', 0);
    $skus = $it['skus']['sku'] ?? ($it['skus'] ?? null);
    jout(['ok'=>true, 'карточка'=>$iid, 'название'=>($it['title'] ?? ''), 'поля_карточки'=>array_keys($it),
          'поля_про_цену_и_количество'=>$found,
          'пример_варианта'=>(is_array($skus) && isset($skus[0])) ? $skus[0] : $skus]);
    break;
  }

