        $vp = ob_variant_price($r['product_id'], $off);
        $rows[] = [
          'товар'            => $r['name'],
          'вариант'          => $r['вариант'],
          'код_варианта'     => $r['properties'],
          'spec_id'          => $r['spec_id'],
          'цена_у_нас_¥'     => $r['source_price_cny'],
          'цена_на_1688_¥'   => $vp['price'],
          'вариант_опознан'  => $vp['exact'] ? 'да' : 'НЕТ',
          'цена_на_витрине_₽'=> $r['price_rub'],
          'совпадает'        => ($vp['exact'] && $vp['price'] !== null && abs((float)$r['source_price_cny'] - (float)$vp['price']) < 0.01) ? 'да' : 'нет',
        ];
