  case 'itc_pending_delete': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    ds_archive_cols();
    $spare = trim((string)($_GET['spare'] ?? ''));
    $spared = 0;
    if ($spare !== '') {
      try {
        if ($spare === 'all') {
          $st = db()->prepare("UPDATE ds_products SET gone_result=NULL, gone_delete_at=NULL, gone_tries=0, gone_last_try=NULL WHERE gone_result='to_delete'");
          $st->execute(); $spared = $st->rowCount();
        } else {
          $st = db()->prepare("UPDATE ds_products SET gone_result=NULL, gone_delete_at=NULL, gone_tries=0, gone_last_try=NULL WHERE id=? AND gone_result='to_delete'");
          $st->execute([$spare]); $spared = $st->rowCount();
        }
      } catch (Exception $e) {}
    }
    $rows = [];
    try {
      $rows = db()->query("SELECT d.id, d.product_id, p.name, d.source_url, d.source_price_cny, p.price AS price_rub,
                                  DATE_FORMAT(d.gone_at,'%d.%m.%Y') AS пропал,
                                  DATE_FORMAT(d.gone_delete_at,'%d.%m.%Y') AS удалится,
                                  DATEDIFF(d.gone_delete_at, NOW()) AS дней_осталось
                             FROM ds_products d LEFT JOIN products p ON p.id=d.product_id
                            WHERE d.gone_result='to_delete'
                            ORDER BY d.gone_delete_at ASC LIMIT 500")->fetchAll();
    } catch (Exception $e) {}
    jout(['ok'=>true, 'помиловано'=>$spared, 'в_карантине'=>count($rows), 'товары'=>$rows]);
