  /* ЧТО СМОТРЯТ ПОКУПАТЕЛИ (25.08.2026, просьба Алексея).
     Журнал событий у нас вёлся давно, но использовался только для подбора
     рекомендаций конкретному человеку. Здесь тот же журнал читается в целом
     по магазину: какие категории и товары смотрят, что ищут и — главное —
     что смотрят, но не покупают. */
  /* КАКИМ АДРЕСОМ СЕРВЕР ВЫХОДИТ НАРУЖУ (02.09.2026).
     Нужно для белого списка IP у onebound. Адрес сайта в панели хостинга и
     адрес, с которого сервер ходит в интернет, на общем хостинге могут
     различаться — а ошибка здесь отрежет нам доступ к API.
     Спрашиваем у нескольких независимых служб и сверяем ответы.
     Открывать: ?action=itc_my_ip&key=МАСТЕР */
  /* №283: ПЕРЕВОД ОСТАВШИХСЯ КИТАЙСКИХ НАЗВАНИЙ. По 12 товаров за раз —
     экран вызывает повторно, пока не останется ни одного. ?count=1 — только
     посчитать. */
  case 'itc_fix_cjk_names': {
    $s=authUser('itc'); require_staff($s,['boss','supervisor','manager']);
    @set_time_limit(120);
    $rows = [];
    try { $rows = db()->query("SELECT id,name FROM products WHERE name REGEXP '[一-鿿]' ORDER BY id DESC LIMIT 3000")->fetchAll(); }
    catch (Exception $e) { foreach (db()->query("SELECT id,name FROM products ORDER BY id DESC LIMIT 20000")->fetchAll() as $r) if (has_cjk($r['name'])) $rows[] = $r; }
    $rows = array_values(array_filter($rows, function($r){ return has_cjk($r['name']); }));
    $total = count($rows);
    if (!empty($_GET['count'])) jout(['ok'=>true,'total'=>$total]);
    $skip = array_flip(array_filter(explode(',', (string)($_GET['skip'] ?? ''))));
    $fixed = 0; $failed = []; $done = 0;
    $up = db()->prepare('UPDATE products SET name=? WHERE id=?');
    foreach ($rows as $r) {
      if (isset($skip[$r['id']])) continue;
      if ($done >= 12) break;
      $done++;
      $nn = itc_tr_name($r['name']);
      if ($nn !== $r['name'] && !has_cjk($nn)) { $up->execute([$nn, $r['id']]); $fixed++; }
      elseif ($nn !== $r['name']) { $up->execute([$nn, $r['id']]); $failed[] = $r['id']; }
      else $failed[] = $r['id'];
    }
    jout(['ok'=>true,'total'=>$total,'fixed'=>$fixed,'failed'=>$failed,'left'=>max(0, $total - $fixed)]);
  }

  /* №285: СОЗДАТЬ ПАРТИЮ СКЛАДСКОГО ТОВАРА. Два входа:
     · сверх заказа — item_id позиции заказа (товар тот же, что купил покупатель);
     · закупка на склад — product_id варианта из каталога.
     Создаются qty единиц, у каждой свой номер и ключ. */
  case 'stock_batch_create': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    stock_tables();
    $d = body();
    $qty = (int)($d['qty'] ?? 0);
    if ($qty < 1 || $qty > 999) fail('Количество от 1 до 999');
    $pid = trim((string)($d['product_id'] ?? '')); $iid = trim((string)($d['item_id'] ?? ''));
    $src = 'purchase'; $oid = null; $onum = null;
    if ($iid !== '') {
      $q = db()->prepare('SELECT i.product_id, i.order_id, o.num FROM order_items i LEFT JOIN orders o ON o.id=i.order_id WHERE i.id=?'); $q->execute([$iid]); $r = $q->fetch();
      if (!$r) fail('Позиция заказа не найдена');
      $pid = (string)$r['product_id']; $oid = $r['order_id']; $onum = $r['num']; $src = 'surplus';
    }
    if ($pid === '') fail('Не выбран товар');
    $pq = db()->prepare('SELECT id,name,img FROM products WHERE id=?'); $pq->execute([$pid]); $p = $pq->fetch();
    if (!$p) fail('Товар не найден в каталоге');
    $who = trim((string)($s['name'] ?? '')) ?: 'ИТК';
    /* №303: защита от повторного нажатия — такая же партия за последние 2 минуты не создаётся второй раз */
    try { stock_cols();
      $dq = db()->prepare("SELECT id FROM stock_batches WHERE product_id=? AND qty=? AND source=? AND COALESCE(order_id,'')=? AND bought_at IS NULL AND created_at > NOW() - INTERVAL 2 MINUTE ORDER BY id LIMIT 1");
      $dq->execute([$pid, $qty, $src, (string)($oid ?? '')]); $dup = $dq->fetchColumn();
      if ($dup) jout(['ok'=>true,'batch_id'=>(int)$dup,'qty'=>$qty,'dup'=>1,'msg'=>'Такая партия уже создана: '.str_pad((string)$dup,4,'0',STR_PAD_LEFT)]);
    } catch (Exception $e) {}
    db()->prepare('INSERT INTO stock_batches (product_id,name,img,qty,source,order_id,order_num,note,created_by,created_at) VALUES (?,?,?,?,?,?,?,?,?,NOW())')
        ->execute([$pid, $p['name'], $p['img'], $qty, $src, $oid, $onum, mb_substr(trim((string)($d['note'] ?? '')), 0, 400), $who]);
    $bid = (int)db()->lastInsertId();
    $ins = db()->prepare("INSERT INTO stock_units (batch_id,seq,code,lbl_key,status,created_at) VALUES (?,?,?,?,'china',NOW())");
    for ($i = 1; $i <= $qty; $i++) $ins->execute([$bid, $i, stock_code($bid, $i, $qty), bin2hex(random_bytes(6))]);
    jout(['ok'=>true,'batch_id'=>$bid,'qty'=>$qty,'msg'=>'Партия '.str_pad((string)$bid,4,'0',STR_PAD_LEFT).' создана: '.$qty.' шт']);
  }

  /* №286: ВАРИАНТЫ ТОВАРА 1688, УЖЕ ЗАВЕДЁННЫЕ В КАТАЛОГ — для «На склад» в дропшиппинге. */
  case 'stock_products_by_src': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    $iid = preg_replace('/\D/', '', (string)($_GET['iid'] ?? ''));
    if ($iid === '') fail('Нет номера товара 1688');
    $q = db()->prepare("SELECT DISTINCT p.id,p.name,p.img FROM ds_products d JOIN products p ON p.id=d.product_id WHERE d.source_url LIKE ? AND COALESCE(p.blocked,0)=0 ORDER BY p.name LIMIT 200");
    $q->execute(['%'.$iid.'%']);
    jout(['ok'=>true,'rows'=>$q->fetchAll()]);
  }

  /* №287: ПРИХОД СКЛАДСКОГО ТОВАРА на склад в России — скан наклейки С-…
     Если единица уже продана (едет к покупателю) — отвечаем sold=1, экран
     передаёт скан в приёмку пункта выдачи. */
  case 'stock_receive': {
    $s = authUser();
    $role = $s['role'] ?? ''; $sr = $s['staff_role'] ?? '';
    $d = body();
    $u = stock_unit_by_code($d['code'] ?? '');
    if (!$u) fail('Это не складская наклейка');
    if ($u['status'] === 'sold') jout(['ok'=>true,'sold'=>1]);
    if ($role !== 'itc') fail('Приход складского товара делает склад ИТК', 403);
    require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    $who = trim((string)($s['name'] ?? '')) ?: 'Склад ИТК';
    $wh = ($sr === 'warehouse') ? (string)($s['supplier_id'] ?? '') : '';
    if (stock_wh_is_china($wh)) fail('Это склад в Китае. Складскую партию здесь подтверждают кнопкой «Партия доехала» в приёмке, а на приход наклейки С-… сканируют уже в России');
    if ($u['status'] === 'stock') {
      jout(['ok'=>true,'already'=>1,'msg'=>'! '.$u['code'].' уже принят '.date('d.m.Y H:i', strtotime($u['rcv_at'] ?: 'now')).' — второй раз не считается']);
    }
    stock_cells_ensure();
    $cell = 'ПРИЁМ';
    if (trim((string)($d['cell'] ?? '')) !== '') { $cc = stock_cell_by_code($d['cell']); if ($cc) $cell = $cc['code']; }
    db()->prepare("UPDATE stock_units SET status='stock', rcv_at=NOW(), rcv_by=?, wh_id=?, cell=? WHERE id=? AND status='china'")
        ->execute([$who.($u['_manual'] ? ' (вручную)' : ''), $wh, $cell, $u['id']]);
    try { db()->prepare('INSERT INTO stock_moves (unit_id,from_cell,to_cell,by_name,at) VALUES (?,?,?,?,NOW())')->execute([$u['id'], null, $cell, $who]); } catch (Exception $e) {}
    $cq = db()->prepare("SELECT COUNT(*) FROM stock_units WHERE batch_id=? AND status<>'china'"); $cq->execute([$u['batch_id']]); $got = (int)$cq->fetchColumn();
    if ($wh !== '' && function_exists('wh_log_add')) { try { wh_log_add($wh, $who, 'stock_in', $u['code'], ($u['_manual'] ? 'ВРУЧНУЮ · ' : '').mb_substr((string)$u['name'],0,60)); } catch (Throwable $e) {} }
    jout(['ok'=>true,'msg'=>'Принят '.$u['code'].' → '.$cell.' · партия '.str_pad((string)$u['batch_id'],4,'0',STR_PAD_LEFT).': '.$got.' из '.(int)$u['bqty'],'name'=>$u['name']]);
  }

  /* №287: К СБОРКЕ — позиции заказов, которые отдаём со склада, но ещё не собрали. */
  case 'stock_pick_list': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    stock_cols();
    $rows = db()->query("SELECT i.id, i.order_id, i.product_id, i.name, i.qty, i.sub_no, o.num, o.addr_name, w.name wname, p.img,
        (SELECT COUNT(*) FROM stock_units su WHERE su.order_item_id=i.id) picked
        FROM order_items i JOIN orders o ON o.id=i.order_id LEFT JOIN warehouses w ON w.id=o.warehouse_id LEFT JOIN products p ON p.id=i.product_id
        WHERE i.stock_reserved=1 AND o.paid=1 ORDER BY o.created_at LIMIT 300")->fetchAll();
    stock_cells_ensure();
    $cq = db()->prepare("SELECT u.cell, COUNT(*) n, MIN(COALESCE(c.sort,5000)) srt FROM stock_units u JOIN stock_batches b ON b.id=u.batch_id LEFT JOIN stock_cells c ON c.code=u.cell
                          WHERE b.product_id=? AND u.status='stock' AND (u.cell IS NULL OR u.cell<>'БРАК') GROUP BY u.cell ORDER BY srt");
    $out = [];
    foreach ($rows as $r) { if ((int)$r['picked'] >= (int)$r['qty']) continue;
      $cells = []; $srt = 99999;
      try { $cq->execute([$r['product_id']]); foreach ($cq->fetchAll() as $c) { $cells[] = ['cell'=>$c['cell'] ?: 'ПРИЁМ','n'=>(int)$c['n']]; $srt = min($srt, (int)$c['srt']); } } catch (Exception $e) {}
      $out[] = ['cells'=>$cells,'srt'=>$srt,'item_id'=>$r['id'],'num'=>$r['num'],'code'=>$r['sub_no'] ? $r['num'].'-'.(int)$r['sub_no'] : $r['num'],'name'=>$r['name'],'img'=>$r['img'],
                'qty'=>(int)$r['qty'],'picked'=>(int)$r['picked'],'client'=>$r['addr_name'],'pvz'=>$r['wname']]; }
    usort($out, function($a, $b){ return $a['srt'] <=> $b['srt']; });   // №289: по порядку адресов
    jout(['ok'=>true,'rows'=>$out]);
  }

  /* №287: СОБРАТЬ — кладовщик сканирует любую единицу нужного товара, и она
     привязывается к заказу покупателя. Наклейку не переклеивают: пункт выдачи
     по этой же наклейке поймёт, чей это товар. */
  case 'stock_pick': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    stock_cols();
    $d = body();
    $iid = trim((string)($d['item_id'] ?? ''));
    $iq = db()->prepare("SELECT i.id,i.order_id,i.product_id,i.qty,i.sub_no,i.stock_reserved,o.num,w.name wname FROM order_items i JOIN orders o ON o.id=i.order_id LEFT JOIN warehouses w ON w.id=o.warehouse_id WHERE i.id=?");
    $iq->execute([$iid]); $it = $iq->fetch();
    if (!$it || (int)$it['stock_reserved'] !== 1) fail('Позиция не отмечена к выдаче со склада');
    $u = stock_unit_by_code($d['code'] ?? '');
    if (!$u) fail('Это не складская наклейка');
    if ((string)$u['product_id'] !== (string)$it['product_id']) fail('Не тот товар: '.$u['code'].' — «'.$u['name'].'». Нужен другой вариант');
    if ($u['status'] === 'sold') fail('Единица '.$u['code'].' уже продана');
    if ($u['status'] !== 'stock') fail('Единица '.$u['code'].' ещё не принята на склад');
    if (($u['cell'] ?? '') === 'БРАК') fail('Единица '.$u['code'].' лежит в зоне БРАК — её не продаём');
    $pq = db()->prepare('SELECT COUNT(*) FROM stock_units WHERE order_item_id=?'); $pq->execute([$iid]); $picked = (int)$pq->fetchColumn();
    if ($picked >= (int)$it['qty']) fail('Эта позиция уже собрана полностью');
    db()->prepare("UPDATE stock_units SET status='sold', order_id=?, order_item_id=?, sold_at=NOW() WHERE id=? AND status='stock'")->execute([$it['order_id'], $iid, $u['id']]);
    $picked++;
    $code = $it['sub_no'] ? $it['num'].'-'.(int)$it['sub_no'] : $it['num'];
    jout(['ok'=>true,'left'=>max(0,(int)$it['qty']-$picked),'msg'=>$u['code'].' → заказ '.$code.($it['wname'] ? ' · везти на «'.$it['wname'].'»' : '').' · собрано '.$picked.' из '.(int)$it['qty']]);
  }

  /* №289: АДРЕСА СКЛАДА со счётчиком, сколько штук лежит на каждом. */
  case 'stock_cells': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    stock_cells_ensure();
    $rows = db()->query("SELECT c.id,c.code,c.kind,c.sort,(SELECT COUNT(*) FROM stock_units u WHERE u.cell=c.code AND u.status='stock') n FROM stock_cells c ORDER BY c.sort")->fetchAll();
    jout(['ok'=>true,'rows'=>array_map(function($r){ return ['id'=>(int)$r['id'],'code'=>$r['code'],'kind'=>$r['kind'],'n'=>(int)$r['n']]; }, $rows)]);
  }
  case 'stock_cell_add_pallet': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','warehouse']);
    stock_cells_ensure();
    $n = (int)db()->query("SELECT COUNT(*) FROM stock_cells WHERE kind='pallet'")->fetchColumn() + 1;
    $code = 'П-'.str_pad((string)$n, 2, '0', STR_PAD_LEFT);
    db()->prepare('INSERT IGNORE INTO stock_cells (code,kind,sort) VALUES (?,?,?)')->execute([$code, 'pallet', 1000 + $n]);
    jout(['ok'=>true,'code'=>$code,'msg'=>'Добавлено паллетное место '.$code]);
  }
  /* Что лежит по адресу — для поиска и инвентаризации. */
  case 'stock_cell_view': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    $c = stock_cell_by_code($_GET['code'] ?? '');
    if (!$c) fail('Адрес не найден');
    $q = db()->prepare("SELECT u.code,u.seq,b.name,b.id bid FROM stock_units u JOIN stock_batches b ON b.id=u.batch_id WHERE u.cell=? AND u.status='stock' ORDER BY b.id,u.seq LIMIT 500");
    $q->execute([$c['code']]);
    jout(['ok'=>true,'cell'=>$c['code'],'units'=>$q->fetchAll()]);
  }
  /* №289: РАЗЛОЖИТЬ / ПЕРЕМЕСТИТЬ. Выбран адрес — сканируем штуки подряд.
     Не принятая ещё штука (едет из Китая) сразу и принимается, и раскладывается. */
  case 'stock_place': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    $d = body();
    $c = stock_cell_by_code($d['cell'] ?? '');
    if (!$c) fail('Сначала отсканируйте наклейку полки');
    $u = stock_unit_by_code($d['code'] ?? '');
    if (!$u) fail('Это не складская наклейка');
    if ($u['status'] === 'sold') fail($u['code'].' уже продан и привязан к заказу — его не раскладывают, а везут на пункт');
    $who = trim((string)($s['name'] ?? '')) ?: 'Склад ИТК';
    if (($s['staff_role'] ?? '') === 'warehouse' && stock_wh_is_china((string)($s['supplier_id'] ?? ''))) fail('Раскладка по адресам — на складе в России');
    $from = $u['cell'] ?: null;
    if ($u['status'] === 'china') {
      $wh = (($s['staff_role'] ?? '') === 'warehouse') ? (string)($s['supplier_id'] ?? '') : '';
      db()->prepare("UPDATE stock_units SET status='stock', rcv_at=NOW(), rcv_by=?, wh_id=?, cell=? WHERE id=?")->execute([$who, $wh, $c['code'], $u['id']]);
    } else {
      if ($from === $c['code']) jout(['ok'=>true,'msg'=>$u['code'].' уже лежит в '.$c['code']]);
      db()->prepare('UPDATE stock_units SET cell=? WHERE id=?')->execute([$c['code'], $u['id']]);
    }
    try { db()->prepare('INSERT INTO stock_moves (unit_id,from_cell,to_cell,by_name,at) VALUES (?,?,?,?,NOW())')->execute([$u['id'], $from, $c['code'], $who]); } catch (Exception $e) {}
    // подсказка: где ещё лежит такой же товар
    $hint = '';
    try { $hq = db()->prepare("SELECT DISTINCT u.cell FROM stock_units u JOIN stock_batches b ON b.id=u.batch_id WHERE b.product_id=? AND u.status='stock' AND u.cell IS NOT NULL AND u.cell NOT IN (?, 'ПРИЁМ') LIMIT 3");
          $hq->execute([$u['product_id'], $c['code']]); $o = $hq->fetchAll(PDO::FETCH_COLUMN); if ($o) $hint = ' · такой же товар лежит ещё в '.implode(', ', $o); } catch (Exception $e) {}
    $nq = db()->prepare("SELECT COUNT(*) FROM stock_units WHERE cell=? AND status='stock'"); $nq->execute([$c['code']]);
    jout(['ok'=>true,'msg'=>$u['code'].($u['status']==='china' ? ' принят и положен в ' : ' → ').$c['code'].' · на месте '.(int)$nq->fetchColumn().' шт'.$hint]);
  }

  /* №290: ЗОНЫ НАПРАВЛЕНИЙ для склада в Китае — все пункты и склады с кодом. */
  case 'zones_list': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    $rows = db()->query("SELECT id,code,name,city,kind FROM warehouses WHERE code IS NOT NULL AND code<>'' ORDER BY code")->fetchAll();
    jout(['ok'=>true,'rows'=>$rows]);
  }

  /* №298: ЗАКУПКА НА СКЛАД В «ТОВАРЕ НА ВЫКУП». Партии, которые ещё не
     выкуплены на 1688: и «закупка на склад», и «сверх заказа» (докупить
     лишние штуки вместе с заказом покупателя). */
  case 'stock_buy_list': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','accountant','chief_accountant','wh_manager','wh_keeper','warehouse']);
    stock_cols();
    $rows = db()->query("SELECT b.id,b.product_id,COALESCE(NULLIF((SELECT p.name FROM products p WHERE p.id=b.product_id),''),b.name) name,COALESCE(NULLIF((SELECT p.img FROM products p WHERE p.id=b.product_id),''),b.img) img,b.qty,b.source,b.order_num,b.created_by,UNIX_TIMESTAMP(b.created_at)*1000 ts,
        (SELECT d.source_url FROM ds_products d WHERE d.product_id=b.product_id LIMIT 1) src,
        (SELECT d.source_price_cny FROM ds_products d WHERE d.product_id=b.product_id LIMIT 1) cny
        FROM stock_batches b WHERE b.bought_at IS NULL ORDER BY b.id DESC LIMIT 200")->fetchAll();
    $out = [];
    foreach ($rows as $r) $out[] = ['id'=>(int)$r['id'],'num'=>str_pad((string)$r['id'],4,'0',STR_PAD_LEFT),'pid'=>$r['product_id'],'name'=>$r['name'],'img'=>$r['img'],
      'qty'=>(int)$r['qty'],'source'=>$r['source'],'order_num'=>$r['order_num'],'by'=>$r['created_by'],'ts'=>(int)$r['ts'],'src'=>$r['src'],'cny'=>$r['cny'] !== null ? (float)$r['cny'] : null];
    jout(['ok'=>true,'rows'=>$out]);
  }
  case 'stock_buy_mark': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','accountant','chief_accountant','wh_manager','wh_keeper','warehouse']);
    stock_cols();
    $d = body(); $bid = (int)($d['batch_id'] ?? 0);
    $who = trim((string)($s['name'] ?? '')) ?: 'ИТК';
    db()->prepare('UPDATE stock_batches SET bought_at=NOW(), bought_by=?, buy_ref=? WHERE id=? AND bought_at IS NULL')
        ->execute([$who, mb_substr(trim((string)($d['ref'] ?? '')), 0, 120), $bid]);
    jout(['ok'=>true,'msg'=>'Партия '.str_pad((string)$bid,4,'0',STR_PAD_LEFT).' отмечена как выкупленная']);
  }

  /* №299: СКЛАДСКИЕ ПАРТИИ В ПРИЁМКЕ НА СКЛАДЕ В КИТАЕ. Выкупленные партии
     ждут на складе в Китае; склад подтверждает «партия доехала», печатает
     наклейки С-… и отправляет в Россию. Подтверждённые видны ещё 14 дней. */
  case 'stock_cn_list': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','accountant','chief_accountant','wh_manager','wh_keeper','wh_worker','warehouse']);
    stock_cols();
    $rows = db()->query("SELECT b.id,b.product_id,COALESCE(NULLIF((SELECT p.name FROM products p WHERE p.id=b.product_id),''),b.name) name,COALESCE(NULLIF((SELECT p.img FROM products p WHERE p.id=b.product_id),''),b.img) img,b.qty,b.source,b.order_num,b.buy_ref,b.bought_by,
        UNIX_TIMESTAMP(b.bought_at)*1000 bts, UNIX_TIMESTAMP(b.cn_rcv_at)*1000 rts, b.cn_rcv_by
        FROM stock_batches b WHERE b.bought_at IS NOT NULL AND (b.cn_rcv_at IS NULL OR b.cn_rcv_at > NOW() - INTERVAL 14 DAY)
        ORDER BY (b.cn_rcv_at IS NULL) DESC, b.id DESC LIMIT 200")->fetchAll();
    $out = [];
    foreach ($rows as $r) $out[] = ['id'=>(int)$r['id'],'num'=>str_pad((string)$r['id'],4,'0',STR_PAD_LEFT),'pid'=>$r['product_id'],'name'=>$r['name'],'img'=>$r['img'],
      'qty'=>(int)$r['qty'],'source'=>$r['source'],'order_num'=>$r['order_num'],'ref'=>$r['buy_ref'],'bought_by'=>$r['bought_by'],
      'bts'=>(int)$r['bts'],'rts'=>$r['rts'] ? (int)$r['rts'] : 0,'rcv_by'=>$r['cn_rcv_by']];
    jout(['ok'=>true,'rows'=>$out]);
  }
  case 'stock_cn_accept': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    stock_cols();
    $d = body(); $bid = (int)($d['batch_id'] ?? 0);
    $who = trim((string)($s['name'] ?? '')) ?: 'Склад ИТК';
    db()->prepare('UPDATE stock_batches SET cn_rcv_at=NOW(), cn_rcv_by=? WHERE id=? AND cn_rcv_at IS NULL')->execute([$who, $bid]);
    jout(['ok'=>true,'msg'=>'Партия '.str_pad((string)$bid,4,'0',STR_PAD_LEFT).' доехала на склад в Китае']);
  }

  /* №302: ПЕРЕИМЕНОВАТЬ ВЕСЬ ТОВАР. Меняет общую часть названия (до « · »)
     сразу у всех вариантов одного товара 1688; вариант (цвет, размер)
     после « · » остаётся у каждого свой. */
  case 'product_rename_family': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    $d = body(); $id = (string)($d['id'] ?? ''); $base = trim(preg_replace('/\s+/u', ' ', (string)($d['base'] ?? '')));
    $base = trim(str_replace('·', '-', $base));
    if ($id === '' || mb_strlen($base) < 3) fail('Введите новое название товара');
    if (mb_strlen($base) > 200) $base = mb_substr($base, 0, 200);
    $ids = [$id];
    try {
      $q = db()->prepare("SELECT source_url FROM ds_products WHERE product_id=? AND source_url IS NOT NULL AND source_url<>'' LIMIT 1"); $q->execute([$id]); $src = (string)($q->fetchColumn() ?: '');
      if ($src !== '') { $q2 = db()->prepare('SELECT DISTINCT product_id FROM ds_products WHERE source_url=?'); $q2->execute([$src]); $ids = array_values(array_unique(array_merge($ids, $q2->fetchAll(PDO::FETCH_COLUMN)))); }
    } catch (Exception $e) {}
    $sel = db()->prepare('SELECT name FROM products WHERE id=?'); $up = db()->prepare('UPDATE products SET name=? WHERE id=?');
    $out = []; $n = 0;
    foreach ($ids as $pid) {
      $sel->execute([$pid]); $old = $sel->fetchColumn(); if ($old === false) continue;
      $pos = mb_strpos((string)$old, ' · ');
      $new = $base.($pos !== false ? mb_substr((string)$old, $pos) : '');
      if ($new !== $old) { $up->execute([$new, $pid]); $n++; }
      $out[] = ['id'=>$pid, 'name'=>$new];
    }
    jout(['ok'=>true, 'items'=>$out, 'msg'=>'Переименовано вариантов: '.$n]);
  }

  /* №303: УДАЛИТЬ ПАРТИЮ (только ещё не выкупленную) и УБРАТЬ ПОВТОРЫ. */
  case 'stock_batch_delete': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    stock_cols();
    $bid = (int)(body()['batch_id'] ?? 0);
    $q = db()->prepare('SELECT bought_at, cn_rcv_at FROM stock_batches WHERE id=?'); $q->execute([$bid]); $b = $q->fetch();
    if (!$b) fail('Партия не найдена');
    /* №304: можно удалить и выкупленную, пока она не подтверждена на складе в Китае
       и ни одна штука не принята в России (это ошибочный повтор) */
    if (!empty($b['cn_rcv_at'])) fail('Партия уже подтверждена на складе — удалить нельзя');
    $mq = db()->prepare("SELECT COUNT(*) FROM stock_units WHERE batch_id=? AND status<>'china'"); $mq->execute([$bid]);
    if ((int)$mq->fetchColumn() > 0) fail('Часть штук уже принята — удалить нельзя');
    db()->prepare('DELETE FROM stock_units WHERE batch_id=?')->execute([$bid]);
    db()->prepare('DELETE FROM stock_batches WHERE id=?')->execute([$bid]);
    jout(['ok'=>true,'msg'=>'Партия '.str_pad((string)$bid,4,'0',STR_PAD_LEFT).' удалена']);
  }
  case 'stock_dedupe': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    stock_cols();
    /* №304: повторы ищем среди невыкупленных и среди выкупленных, но ещё не
       подтверждённых в Китае партий, где ни одна штука не принята. Остаётся
       самая ранняя партия каждого варианта; выкупленную оставляем охотнее. */
    $rows = db()->query("SELECT b.id, b.product_id, b.qty, b.source, COALESCE(b.order_id,'') oid, (b.bought_at IS NOT NULL) bought
        FROM stock_batches b WHERE b.cn_rcv_at IS NULL AND NOT EXISTS (SELECT 1 FROM stock_units u WHERE u.batch_id=b.id AND u.status<>'china')
        ORDER BY (b.bought_at IS NULL), b.id")->fetchAll();
    $seen = []; $del = [];
    foreach ($rows as $r) { $k = $r['product_id'].'|'.$r['qty'].'|'.$r['source'].'|'.$r['oid']; if (isset($seen[$k])) $del[] = (int)$r['id']; else $seen[$k] = 1; }
    $du = db()->prepare('DELETE FROM stock_units WHERE batch_id=?'); $db2 = db()->prepare('DELETE FROM stock_batches WHERE id=?');
    foreach ($del as $id) { $du->execute([$id]); $db2->execute([$id]); }
    jout(['ok'=>true,'deleted'=>count($del),'msg'=>count($del) ? 'Удалено повторов: '.count($del) : 'Повторов нет']);
  }

  /* №306: ссылка 1688 товара — для кнопки «Обновить с 1688» в карточке */
  case 'ds_source_of': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    $q = db()->prepare("SELECT source_url FROM ds_products WHERE product_id=? AND source_url IS NOT NULL AND source_url<>'' LIMIT 1");
    $q->execute([(string)($_GET['id'] ?? '')]); $src = (string)($q->fetchColumn() ?: '');
    if ($src === '' || stripos($src, '1688') === false) fail('У этого товара нет ссылки на 1688');
    jout(['ok'=>true,'url'=>$src]);
  }

  /* №307: ОТГРУЗКА «КИТАЙ → РОССИЯ». Партии, подтверждённые на складе в Китае,
     собираются в отгрузку (перевозчик, номер машины/контейнера/трек). Пока
     отгрузка в пути — её штуки числятся «в пути». В Гвардейском штуки
     принимаются сканом как обычно, а отгрузка показывает, сколько доехало.
     «Закрыть отгрузку» фиксирует приход и список того, что не доехало. */
  case 'stock_ship_candidates': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse']);
    stock_cols();
    $rows = db()->query("SELECT b.id,b.qty,b.product_id,COALESCE(NULLIF((SELECT p.name FROM products p WHERE p.id=b.product_id),''),b.name) name,
        COALESCE(NULLIF((SELECT p.img FROM products p WHERE p.id=b.product_id),''),b.img) img
        FROM stock_batches b WHERE b.cn_rcv_at IS NOT NULL AND b.ship_id IS NULL ORDER BY b.id")->fetchAll();
    jout(['ok'=>true,'rows'=>array_map(function($r){ return ['id'=>(int)$r['id'],'num'=>str_pad((string)$r['id'],4,'0',STR_PAD_LEFT),'qty'=>(int)$r['qty'],'name'=>$r['name'],'img'=>$r['img']]; }, $rows)]);
  }
  case 'stock_ship_create': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','warehouse']);
    stock_cols();
    $d = body(); $ids = array_values(array_filter(array_map('intval', (array)($d['batch_ids'] ?? []))));
    if (!$ids) fail('Отметьте хотя бы одну партию');
    $who = trim((string)($s['name'] ?? '')) ?: 'Склад ИТК';
    db()->prepare("INSERT INTO stock_shipments (carrier,ref,note,status,created_by,sent_at) VALUES (?,?,?,'sent',?,NOW())")
        ->execute([mb_substr(trim((string)($d['carrier'] ?? '')),0,120), mb_substr(trim((string)($d['ref'] ?? '')),0,160), mb_substr(trim((string)($d['note'] ?? '')),0,400), $who]);
    $sid = (int)db()->lastInsertId();
    $in = implode(',', array_fill(0, count($ids), '?'));
    $up = db()->prepare("UPDATE stock_batches SET ship_id=? WHERE id IN ($in) AND ship_id IS NULL AND cn_rcv_at IS NOT NULL");
    $up->execute(array_merge([$sid], $ids));
    jout(['ok'=>true,'id'=>$sid,'num'=>'ОТ-'.str_pad((string)$sid,4,'0',STR_PAD_LEFT),'batches'=>$up->rowCount(),'msg'=>'Отгрузка ОТ-'.str_pad((string)$sid,4,'0',STR_PAD_LEFT).' отправлена: партий '.$up->rowCount()]);
  }
  case 'stock_ships': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor','wh_manager','wh_keeper','wh_worker','warehouse','accountant','chief_accountant']);
    stock_cols();
    $rows = db()->query("SELECT sh.*, UNIX_TIMESTAMP(sh.sent_at)*1000 sts, UNIX_TIMESTAMP(sh.arrived_at)*1000 ats,
        (SELECT COUNT(*) FROM stock_batches b WHERE b.ship_id=sh.id) nb,
        (SELECT COUNT(*) FROM stock_units u JOIN stock_batches b ON b.id=u.batch_id WHERE b.ship_id=sh.id) nu,
        (SELECT COUNT(*) FROM stock_units u JOIN stock_batches b ON b.id=u.batch_id WHERE b.ship_id=sh.id AND u.status<>'china') nr
        FROM stock_shipments sh ORDER BY (sh.arrived_at IS NULL) DESC, sh.id DESC LIMIT 100")->fetchAll();
    jout(['ok'=>true,'rows'=>array_map(function($r){ return ['id'=>(int)$r['id'],'num'=>'ОТ-'.str_pad((string)$r['id'],4,'0',STR_PAD_LEFT),'carrier'=>$r['carrier'],'ref'=>$r['ref'],'note'=>$r['note'],
      'by'=>$r['created_by'],'sts'=>(int)$r['sts'],'ats'=>$r['ats'] ? (int)$r['ats'] : 0,'closed_by'=>$r['closed_by'],'nb'=>(int)$r['nb'],'nu'=>(int)$r['nu'],'nr'=>(int)$r['nr']]; }, $rows)]);
  }
  case 'stock_ship_view': {
