    foreach ($oq->fetchAll(PDO::FETCH_COLUMN) as $oid) {
      $lq = db()->prepare("SELECT COUNT(*) FROM order_items oi WHERE oi.order_id=? AND COALESCE(oi.stock_reserved,0)=0
          AND NOT EXISTS (SELECT 1 FROM pack_items p JOIN pack_boxes b ON b.id=p.box_id WHERE p.kind='item' AND p.ref_id=oi.id AND b.status IN ('shipped','arrived'))");
      $lq->execute([$oid]);
      if ((int)$lq->fetchColumn() === 0) db()->prepare("UPDATE orders SET wh_shipped_at=COALESCE(wh_shipped_at,NOW()), status=IF(status IN ('created','confirmed','at_warehouse','in_container'),'shipping',status) WHERE id=?")->execute([$oid]);
    }
    jout(['ok'=>true,'n'=>$u->rowCount()]);
