  /* №291: ПРОВЕРКА КАТЕГОРИЙ. Только показывает. Сколько живых товаров в каждой
     категории и подкатегории (вариантов и отдельных товаров — «семей»), и что
     лежит в «Прочем» / без подкатегории — чтобы решить, какие категории добавить. */
  case 'itc_cat_stats': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) { $s=authUser('itc'); require_staff($s,['boss']); }
    header('Content-Type: text/plain; charset=utf-8');
    header('Content-Disposition: attachment; filename="kategorii-'.date('Y-m-d').'.txt"');   // сразу скачивается файлом
    $head = function($n){ $n=(string)$n; $i=mb_strpos($n,' · '); return trim($i!==false ? mb_substr($n,0,$i) : $n); };
    $rows = db()->query("SELECT p.id,p.cat,p.subcat,p.name FROM products p WHERE COALESCE(p.blocked,0)=0")->fetchAll();
    $cats = []; $tot = 0; $fam = [];
    foreach ($rows as $r) {
      $c = trim((string)($r['cat'] ?? '')) ?: '(без категории)'; $sc = trim((string)($r['subcat'] ?? '')) ?: '(без подкатегории)';
      $h = $head($r['name']); $tot++;
      if (!isset($cats[$c])) $cats[$c] = ['v'=>0,'f'=>[],'sub'=>[]];
      $cats[$c]['v']++; $cats[$c]['f'][$h] = 1;
      if (!isset($cats[$c]['sub'][$sc])) $cats[$c]['sub'][$sc] = ['v'=>0,'f'=>[]];
      $cats[$c]['sub'][$sc]['v']++; $cats[$c]['sub'][$sc]['f'][$h] = 1;
    }
    uasort($cats, function($a,$b){ return count($b['f']) <=> count($a['f']); });
    $o = "ПРОВЕРКА КАТЕГОРИЙ · ".date('d.m.Y H:i')."\nЖивых карточек (вариантов): $tot\n\n";
    $dict = [];
    try { foreach (db()->query('SELECT name FROM categories ORDER BY sort, name')->fetchAll() as $c) $dict[] = $c['name']; } catch (Exception $e) {}
    $o .= "Категории в справочнике (".count($dict)."): ".implode(', ', $dict)."\n\n";
    foreach ($cats as $c => $d) {
      $o .= "■ $c — товаров ".count($d['f']).", вариантов {$d['v']}\n";
      uasort($d['sub'], function($a,$b){ return count($b['f']) <=> count($a['f']); });
      foreach ($d['sub'] as $sc => $sd) {
        $o .= "    · $sc — ".count($sd['f'])." (вар. {$sd['v']})";
        if ($sc === '(без подкатегории)' || count($sd['f']) >= 40) { $ex = array_slice(array_keys($sd['f']), 0, $sc === '(без подкатегории)' ? 40 : 8); $o .= "\n        пример: ".implode(' | ', array_map(function($x){ return mb_substr($x,0,60); }, $ex)); }
        $o .= "\n";
      }
    }
    foreach (['Прочее','(без категории)'] as $gen) {
      if (empty($cats[$gen])) continue;
      $o .= "\n\n===== ВСЁ, ЧТО В «$gen» (".count($cats[$gen]['f'])." товаров) =====\n";
      foreach (array_keys($cats[$gen]['f']) as $h) $o .= mb_substr($h,0,90)."\n";
    }
    echo $o; exit;
  }

  /* №293: ПЕРЕСОРТИРОВКА КАТЕГОРИЙ.
     mode=preview — скачивается отчёт «что куда переедет», ничего не меняется.
     mode=apply   — переносит по 3000 карточек за шаг, страница сама идёт дальше.
     Правило переноса: категорию меняем, только если товар лежит в «Прочем»/без
     категории, в переименованной/объединённой категории, или новые правила
     нашли для него одну из НОВЫХ категорий (красота, аксессуары, одежда,
     игрушки, подарки) или исправили явный промах (коврики, зоотовары).
     Ручной выбор категории в остальных случаях не трогаем. */
  case 'itc_recat': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) { $s=authUser('itc'); require_staff($s,['boss']); }
    @set_time_limit(300);
    $mode = (string)($_GET['mode'] ?? 'preview');
    $newCats = ['Красота и уход','Аксессуары','Одежда и обувь','Игрушки и игры','Подарки','Новый год'];
    $oldNames = ['Спорт и отдых','Энергетика','Полка для обуви','Офисные принадлежности'];
    $decide = function($r) use ($newCats, $oldNames) {
      $cur = trim((string)($r['cat'] ?? '')); $nm = (string)$r['name'];
      $calc = itc_store_category($nm);
      $new = $cur;
      if (in_array($cur, $oldNames, true)) $new = in_array($calc, $newCats, true) ? $calc : itc_cat_v2_rename($cur);
      elseif ($cur === 'Подарки') $new = $cur;
      elseif ($cur === '' || $cur === 'Прочее') $new = ($calc !== 'Прочее') ? $calc : 'Прочее';
      elseif (in_array($calc, $newCats, true) && $calc !== $cur) $new = $calc;
      elseif ($calc === 'Зоотовары' && $cur === 'Детская') $new = $calc;
      elseif ($calc === 'Текстиль' && $cur === 'Инструменты') $new = $calc;
      elseif ($cur === 'Новый год' && $calc !== 'Новый год') $new = ($calc !== 'Прочее') ? $calc : 'Декор';   // №312: ошибочно попавшие — обратно
      $new = itc_cat_v2_rename($new);
      $curSub = trim((string)($r['subcat'] ?? ''));
      $sub = itc_store_subcat($new, $nm);
      if ($sub === '') $sub = (mb_substr($curSub, -1) === '.' || $new !== $cur) ? '' : $curSub;
      return [$new, $sub];
    };
    if ($mode === 'apply') {
      $off = max(0, (int)($_GET['off'] ?? 0)); $step = 3000;
      if ($off === 0) {
        try {
          $mx = (int)(db()->query('SELECT COALESCE(MAX(sort),0) m FROM categories')->fetch()['m'] ?? 0);
          $ins = db()->prepare('INSERT IGNORE INTO categories (name,sort) VALUES (?,?)');
          foreach (array_merge($newCats, ['Для салонов','Для ресторанов','Для гостиниц']) as $nc) $ins->execute([$nc, ++$mx]);
          foreach (['Спорт и отдых'=>'Спорт, туризм и отдых','Энергетика'=>'Энергетика и отопление'] as $o => $n) {
            $q = db()->prepare('SELECT sort FROM categories WHERE name=?'); $q->execute([$o]); $srt = $q->fetchColumn();
            if ($srt !== false) { db()->prepare('DELETE FROM categories WHERE name=?')->execute([$o]); $ins->execute([$n, (int)$srt]); } else $ins->execute([$n, ++$mx]);
          }
          foreach (['Полка для обуви','Офисные принадлежности'] as $o) db()->prepare('DELETE FROM categories WHERE name=?')->execute([$o]);
          /* №311: «Новый год» — сезонная, ставим первой в списке категорий */
          $ny = db()->prepare("SELECT sort FROM categories WHERE name='Новый год'"); $ny->execute(); $nys = $ny->fetchColumn();
          $mn = (int)(db()->query("SELECT COALESCE(MIN(sort),0) FROM categories WHERE name<>'Новый год'")->fetchColumn());
          if ($nys !== false && (int)$nys >= $mn) db()->prepare("UPDATE categories SET sort=? WHERE name='Новый год'")->execute([$mn - 1]);
        } catch (Exception $e) {}
      }
      $q = db()->prepare("SELECT id,name,cat,subcat FROM products ORDER BY id LIMIT $step OFFSET $off"); $q->execute(); $rows = $q->fetchAll();
      $up = db()->prepare('UPDATE products SET cat=?, subcat=? WHERE id=?'); $moved = 0;
      foreach ($rows as $r) { list($nc, $ns) = $decide($r); if ($nc !== (string)$r['cat'] || $ns !== (string)($r['subcat'] ?? '')) { $up->execute([$nc, $ns, $r['id']]); $moved++; } }
      $total = (int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn();
      $next = $off + $step; $done = count($rows) < $step;
      header('Content-Type: text/html; charset=utf-8');
      if ($done) { try { if (function_exists('itc_cache_flush')) itc_cache_flush(); } catch (Throwable $e) {}
        echo '<meta name="viewport" content="width=device-width,initial-scale=1"><div style="font:18px Arial;padding:20px"><b>Готово.</b> Пересортировка закончена: проверено '.$total.' карточек.<br>В последнем шаге изменено: '.$moved.'.</div>'; exit; }
      $url = '?action=itc_recat&mode=apply&key='.urlencode((string)($_GET['key'] ?? '')).'&off='.$next;
      echo '<meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="1;url='.htmlspecialchars($url).'"><div style="font:18px Arial;padding:20px">Пересортировка… обработано <b>'.min($next,$total).'</b> из <b>'.$total.'</b> (изменено в шаге: '.$moved.').<br>Не закрывайте страницу — она продолжит сама.</div>'; exit;
    }
    // ПРЕДПРОСМОТР
    header('Content-Type: text/plain; charset=utf-8');
    header('Content-Disposition: attachment; filename="peresortirovka-'.date('Y-m-d').'.txt"');
    $head = function($n){ $n=(string)$n; $i=mb_strpos($n,' · '); return trim($i!==false ? mb_substr($n,0,$i) : $n); };
    $rows = db()->query("SELECT id,name,cat,subcat FROM products WHERE COALESCE(blocked,0)=0")->fetchAll();
    $mv = []; $sub = []; $after = []; $stay = [];
    foreach ($rows as $r) {
      list($nc, $ns) = $decide($r); $h = $head($r['name']); $cur = trim((string)$r['cat']) ?: '(без категории)';
      $after[$nc][$h] = 1;
      if ($nc !== (string)$r['cat']) { $k = $cur.'  →  '.$nc; if (!isset($mv[$k])) $mv[$k] = []; $mv[$k][$h] = 1; }
      $sub[$nc][$ns !== '' ? $ns : '(без подкатегории)'][$h] = 1;
      if ($nc === 'Прочее') $stay[$h] = 1;
    }
    uasort($mv, function($a,$b){ return count($b) <=> count($a); });
    $o = "ПЕРЕСОРТИРОВКА — ПРЕДПРОСМОТР · ".date('d.m.Y H:i')."\nНичего не изменено. Ниже — что куда переедет (число = разных товаров).\n\n";
    $o .= "=== ПЕРЕНОСЫ ===\n";
    foreach ($mv as $k => $hs) { $o .= count($hs)."  ".$k."\n      пример: ".implode(' | ', array_map(function($x){ return mb_substr($x,0,55); }, array_slice(array_keys($hs),0,6)))."\n"; }
    $o .= "\n=== КАТЕГОРИИ ПОСЛЕ ПЕРЕНОСА (товаров) и ПОДКАТЕГОРИИ ===\n";
    uasort($after, function($a,$b){ return count($b) <=> count($a); });
    foreach ($after as $c => $hs) { $o .= "■ $c — ".count($hs)."\n"; $sc = $sub[$c] ?? []; uasort($sc, function($a,$b){ return count($b) <=> count($a); }); foreach ($sc as $sn => $sh) $o .= "    · $sn — ".count($sh)."\n"; }
    $o .= "\n=== ОСТАЁТСЯ В «ПРОЧЕМ» (".count($stay).") ===\n".implode("\n", array_map(function($x){ return mb_substr($x,0,90); }, array_keys($stay)))."\n";
    echo $o; exit;
  }

  /* №293: подкатегории категории — для фильтра в витрине */
  case 'cat_subcats': {
