  case 'itc_grp_check': {
    /* №281: ПРОВЕРКА СКЛЕЙКИ ВАРИАНТОВ. Только показывает, ничего не меняет.
       Магазин собирает варианты в одну карточку по общей ссылке-источнику 1688
       и показывает в выборе только живые (не заблокированные, не на паузе,
       прошедшие модерацию). Здесь видно по каждому товару 1688: сколько
       вариантов заведено, какие живые, какие спрятаны и почему. */
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    $q = trim((string)($_GET['q'] ?? ''));
    $args = []; $w = "d.source_url IS NOT NULL AND d.source_url<>''";
    if ($q !== '') { $w .= ' AND p.name LIKE ?'; $args[] = '%'.$q.'%'; }
    $st = db()->prepare("SELECT d.source_url, p.id, p.name, p.price, COALESCE(p.blocked,0) bl, COALESCE(p.paused,0) pa, COALESCE(p.mod_status,'') ms,
                                COALESCE(d.parse_mode,'') pm, COALESCE(d.x3_pending,0) x3p, d.ds_status
                           FROM ds_products d JOIN products p ON p.id=d.product_id
                          WHERE $w ORDER BY d.id DESC LIMIT 600");
    try { $st->execute($args); $rows = $st->fetchAll(); }
    catch (Exception $e) {
      $st = db()->prepare("SELECT d.source_url, p.id, p.name, p.price, COALESCE(p.blocked,0) bl, 0 pa, COALESCE(p.mod_status,'') ms, '' pm, 0 x3p, '' ds_status
                             FROM ds_products d JOIN products p ON p.id=d.product_id WHERE $w ORDER BY d.id DESC LIMIT 600");
      $st->execute($args); $rows = $st->fetchAll();
    }
    $g = []; $order = [];
    foreach ($rows as $r) {
      $k = $r['source_url'];
      if (!isset($g[$k])) { $g[$k] = ['ссылка'=>$k,'ключ_склейки'=>substr(md5($k),0,10),'вариантов'=>0,'живых'=>0,'спрятано'=>[],'как_заведено'=>[],'варианты'=>[]]; $order[] = $k; }
      $why = [];
      if ((int)$r['bl']) $why[] = 'заблокирован';
      if ((int)$r['pa']) $why[] = 'на паузе';
      if ($r['ms'] !== '' && $r['ms'] !== 'approved') $why[] = 'модерация: '.$r['ms'];
      if ((int)$r['x3p']) $why[] = 'ждёт замера (×N)';
      $g[$k]['вариантов']++;
      if (!$why || $why === ['ждёт замера (×N)']) $g[$k]['живых']++; else $g[$k]['спрятано'][] = mb_substr($r['name'],0,40).' — '.implode(', ', $why);
      $g[$k]['как_заведено'][$r['pm'] ?: '—'] = 1;
      if (count($g[$k]['варианты']) < 6) $g[$k]['варианты'][] = mb_substr($r['name'],0,70).' · '.(int)$r['price'].' ₽';
    }
    $out = [];
    foreach (array_slice($order, 0, 40) as $k) { $x = $g[$k]; $x['как_заведено'] = implode(', ', array_keys($x['как_заведено'])); $x['спрятано'] = array_slice($x['спрятано'],0,8); $out[] = $x; }
    jout(['ok'=>true,'поиск'=>$q,'товаров_1688'=>count($out),'товары'=>$out]);
  }

  case 'itc_pvz_check': {
    /* №272: ПРОВЕРКА ПУНКТА. Только показывает, ничего не меняет.
       Ищет точки по слову (q), партнёров при них и все заказы за 90 дней,
       связанные с этими точками любым способом, и для каждого заказа пишет,
       видит ли его партнёр в «Движении» и если нет — почему. */
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    $qw = trim((string)($_GET['q'] ?? 'Красногвард'));
    if ($qw === '') fail('Укажите q');
    $like = '%'.$qw.'%';
    $cols = [];
    try { foreach (db()->query('SHOW COLUMNS FROM orders')->fetchAll() as $c) $cols[$c['Field']] = 1; } catch (Exception $e) {}
    $hasDest = isset($cols['dest_warehouse_id']); $hasFrom = isset($cols['oversize_from']); $hasMoved = isset($cols['oversize_moved']);
    $whs = [];
    $wq = db()->prepare('SELECT * FROM warehouses WHERE name LIKE ? OR city LIKE ? OR address LIKE ? OR code LIKE ?');
    $wq->execute([$like,$like,$like,$like]);
    foreach ($wq->fetchAll() as $w) $whs[$w['id']] = ['id'=>$w['id'],'код'=>$w['code'] ?? '','название'=>$w['name'] ?? '','город'=>$w['city'] ?? '','адрес'=>$w['address'] ?? '','вид'=>$w['kind'] ?? '','родитель'=>$w['parent_id'] ?? ''];
    $partners = []; $pWh = [];
    $pq = db()->prepare('SELECT id,name,phone,status,warehouse_id FROM partners WHERE name LIKE ? OR warehouse_id IN (SELECT id FROM warehouses WHERE name LIKE ? OR city LIKE ? OR address LIKE ?)');
    $pq->execute([$like,$like,$like,$like]);
    foreach ($pq->fetchAll() as $p) {
      $partners[] = ['id'=>$p['id'],'имя'=>$p['name'],'телефон'=>$p['phone'],'статус'=>$p['status'],'точка'=>$p['warehouse_id'] ?: '— НЕТ —'];
      if ($p['warehouse_id']) $pWh[$p['warehouse_id']] = $p['name'];
    }
    $ids = array_keys($whs);
    $where = ['addr_city LIKE ?','addr_street LIKE ?','addr_note LIKE ?']; $args = [$like,$like,$like];
    if ($ids) {
      $in = implode(',', array_fill(0, count($ids), '?'));
      $where[] = "warehouse_id IN ($in)"; $args = array_merge($args, $ids);
      if ($hasDest) { $where[] = "dest_warehouse_id IN ($in)"; $args = array_merge($args, $ids); }
      if ($hasFrom) { $where[] = "oversize_from IN ($in)"; $args = array_merge($args, $ids); }
    }
    $sel = 'id,num,status,paid,warehouse_id,addr_city,addr_street,UNIX_TIMESTAMP(created_at) ts'.($hasDest?',dest_warehouse_id':'').($hasFrom?',oversize_from':'').($hasMoved?',oversize_moved':'');
    $oq = db()->prepare("SELECT $sel FROM orders WHERE created_at > NOW() - INTERVAL 90 DAY AND (".implode(' OR ', $where).") ORDER BY created_at DESC LIMIT 200");
    $oq->execute($args);
    $orders = [];
    foreach ($oq->fetchAll() as $o) {
      $tot = 0; $big = 0;
      try { $iq = db()->prepare('SELECT COUNT(*) c, SUM(CASE WHEN COALESCE(oversize,0)=1 THEN 1 ELSE 0 END) b FROM order_items WHERE order_id=?');
            $iq->execute([$o['id']]); $r = $iq->fetch(); $tot = (int)$r['c']; $big = (int)$r['b']; }
      catch (Exception $e) { try { $iq = db()->prepare('SELECT COUNT(*) FROM order_items WHERE order_id=?'); $iq->execute([$o['id']]); $tot = (int)$iq->fetchColumn(); } catch (Exception $e2) {} }
      $wid = (string)$o['warehouse_id'];
      $why = [];
      if ((int)$o['paid'] !== 1) $why[] = 'не оплачен';
      if ($wid === '') $why[] = 'точка в заказе не указана';
      elseif (!isset($pWh[$wid])) $why[] = 'привязан к точке '.$wid.(isset($whs[$wid]) ? ' ('.$whs[$wid]['название'].')' : '').', а у партнёра другая точка';
      if ($tot > 0 && $big >= $tot) $why[] = 'все позиции крупногабаритные';
      if ($tot === 0) $why[] = 'в заказе нет позиций';
      $orders[] = ['заказ'=>$o['num'],'дата'=>date('d.m.Y H:i', (int)$o['ts']),'оплачен'=>(int)$o['paid'],'статус'=>$o['status'],
                   'точка_в_заказе'=>$wid ?: '—','точка_куда_отгружен'=>$hasDest ? ($o['dest_warehouse_id'] ?: '—') : 'нет графы',
                   'крупногабарит_перенесён_с'=>$hasFrom ? ($o['oversize_from'] ?: '—') : 'нет графы',
                   'город'=>$o['addr_city'],'позиций'=>$tot,'из_них_крупных'=>$big,
                   'партнёр_видит'=>$why ? 'НЕТ' : 'да','почему_не_видит'=>$why ? implode('; ', $why) : ''];
    }
    jout(['ok'=>true,'слово'=>$qw,'точки'=>array_values($whs),'партнёры'=>$partners,'заказов'=>count($orders),'заказы'=>$orders]);
  }

  case 'itc_my_ip': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    $out = ['ok'=>true, 'адрес_сайта_по_панели'=>'31.31.197.45'];
    $seen = [];
    foreach ([
      'https://api.ipify.org',
      'https://ifconfig.me/ip',
      'https://icanhazip.com',
    ] as $u) {
      $ip = '';
      try {
        $ch = curl_init($u);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>8, CURLOPT_SSL_VERIFYPEER=>false]);
        $r = curl_exec($ch); curl_close($ch);
        $ip = trim((string)$r);
      } catch (Exception $e) {}
      $host = parse_url($u, PHP_URL_HOST);
      if (preg_match('/^\d+\.\d+\.\d+\.\d+$/', $ip)) { $out['службы'][$host] = $ip; $seen[$ip] = ($seen[$ip] ?? 0) + 1; }
      else { $out['службы'][$host] = 'не ответила'; }
    }
    arsort($seen);
    $best = $seen ? array_key_first($seen) : null;
    $out['исходящий_адрес'] = $best ?: 'не удалось определить';
    if ($best) {
      $out['совпадает_с_панелью'] = ($best === '31.31.197.45') ? 'да' : 'НЕТ — в белый список нужен именно исходящий';
      $out['для_onebound'] = $best;
    }
    if (count($seen) > 1) $out['ВНИМАНИЕ'] = 'Службы вернули разные адреса — у хостинга их несколько. Все адреса из списка «службы» нужно внести в белый список.';
