  case 'itc_interest': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    itc_events_ensure();
    $days = (int)($_GET['days'] ?? 30);
    if ($days < 1 || $days > 3650) $days = 30;
    $since = date('Y-m-d H:i:s', time() - $days * 86400);
    $out = ['ok'=>true, 'days'=>$days];

    // Общие числа. Смотрим и просмотры, и сколько разных людей смотрело —
    // один человек, открывший карточку 50 раз, это не популярность.
    try {
      $r = db()->prepare("SELECT COUNT(*) n, COUNT(DISTINCT uid) people FROM user_events WHERE kind='view' AND created_at>=?");
      $r->execute([$since]); $out['просмотров'] = $r->fetch();
    } catch (Exception $e) {}

    // Категории
    try {
      $q = db()->prepare("SELECT cat, COUNT(*) n, COUNT(DISTINCT uid) people
                            FROM user_events
                           WHERE kind='view' AND cat IS NOT NULL AND cat<>'' AND created_at>=?
                        GROUP BY cat ORDER BY n DESC LIMIT 15");
      $q->execute([$since]);
      $out['категории'] = $q->fetchAll();
    } catch (Exception $e) { $out['категории'] = []; }

    // Товары: просмотры + сколько купили за тот же срок
    try {
      $q = db()->prepare("SELECT e.product_id, p.name, p.cat, p.price,
                                 COUNT(*) n, COUNT(DISTINCT e.uid) people
                            FROM user_events e LEFT JOIN products p ON p.id=e.product_id
                           WHERE e.kind='view' AND e.product_id IS NOT NULL AND e.created_at>=?
                        GROUP BY e.product_id, p.name, p.cat, p.price
                        ORDER BY n DESC LIMIT 30");
      $q->execute([$since]);
      $rows = $q->fetchAll();
      $ids = [];
      foreach ($rows as $r) if (!empty($r['product_id'])) $ids[] = $r['product_id'];
      $sold = [];
      if ($ids) {
        $in = implode(',', array_fill(0, count($ids), '?'));
        try {
          $sq = db()->prepare("SELECT i.product_id, COALESCE(SUM(i.qty),0) qty
                                 FROM order_items i JOIN orders o ON o.id=i.order_id
                                WHERE o.paid=1 AND o.created_at>=? AND i.product_id IN ($in)
                             GROUP BY i.product_id");
          $sq->execute(array_merge([$since], $ids));
          foreach ($sq->fetchAll() as $sr) $sold[(string)$sr['product_id']] = (int)$sr['qty'];
        } catch (Exception $e) {}
      }
      $top = []; $cold = [];
      foreach ($rows as $r) {
        $r['куплено'] = $sold[(string)$r['product_id']] ?? 0;
        $top[] = $r;
        // Смотрят много, а не покупают — самое ценное в этом экране
        if ((int)$r['куплено'] === 0 && (int)$r['people'] >= 3) $cold[] = $r;
      }
      $out['товары'] = array_slice($top, 0, 20);
      $out['смотрят_но_не_покупают'] = array_slice($cold, 0, 15);
    } catch (Exception $e) { $out['товары'] = []; }

    // Что ищут
    try {
      $q = db()->prepare("SELECT q, COUNT(*) n FROM user_events
                           WHERE kind='search' AND q IS NOT NULL AND q<>'' AND created_at>=?
                        GROUP BY q ORDER BY n DESC LIMIT 20");
      $q->execute([$since]);
      $out['запросы'] = $q->fetchAll();
    } catch (Exception $e) { $out['запросы'] = []; }

    // В корзину — по категориям, чтобы видеть разрыв «смотрят / кладут»
    try {
      $q = db()->prepare("SELECT cat, COUNT(*) n FROM user_events
                           WHERE kind='cart' AND cat IS NOT NULL AND cat<>'' AND created_at>=?
                        GROUP BY cat ORDER BY n DESC LIMIT 15");
      $q->execute([$since]);
      $out['в_корзину_по_категориям'] = $q->fetchAll();
    } catch (Exception $e) { $out['в_корзину_по_категориям'] = []; }

    jout($out);
  }

  case 'itc_catalog_stats': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    ds_archive_cols();
    $one = function($sql) { try { return (int)db()->query($sql)->fetchColumn(); } catch (Exception $e) { return -1; } };
    $out = ['ok'=>true];

    $out['каталог'] = [
      'всего_карточек' => $one("SELECT COUNT(*) FROM ds_products"),
    ];
    $out['каталог']['в_продаже']          = $one("SELECT COUNT(*) FROM ds_products WHERE ds_status='active' AND gone_at IS NULL");
    $out['каталог']['снято_вручную']      = $one("SELECT COUNT(*) FROM ds_products WHERE ds_status='paused_manual'");
    $out['каталог']['с_1688']             = $one("SELECT COUNT(*) FROM ds_products WHERE source_url LIKE '%1688.com/offer/%'");

    $out['архив_пропавших'] = [
      'всего_в_архиве'          => $one("SELECT COUNT(*) FROM ds_products WHERE gone_at IS NOT NULL"),
      'ждут_первого_переспроса' => $one("SELECT COUNT(*) FROM ds_products WHERE gone_at IS NOT NULL AND gone_result IS NULL AND gone_tries=0"),
      'переспрошены_один_раз'   => $one("SELECT COUNT(*) FROM ds_products WHERE gone_at IS NOT NULL AND gone_result IS NULL AND gone_tries=1"),
      'мёртвые_оставлены'       => $one("SELECT COUNT(*) FROM ds_products WHERE gone_result='kept'"),
      'ждут_удаления_месяц'     => $one("SELECT COUNT(*) FROM ds_products WHERE gone_result='to_delete'"),
      'удалятся_на_днях'        => $one("SELECT COUNT(*) FROM ds_products WHERE gone_result='to_delete' AND gone_delete_at <= DATE_ADD(NOW(), INTERVAL 3 DAY)"),
    ];

    $out['за_30_дней'] = [
      'вернулось_в_продажу' => $one("SELECT COUNT(*) FROM ds_monitor_log WHERE event='revived'  AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)"),
      'удалено_насовсем'    => $one("SELECT COUNT(*) FROM ds_monitor_log WHERE event='deleted'  AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)"),
      'оставлено_с_историей'=> $one("SELECT COUNT(*) FROM ds_monitor_log WHERE event='archived' AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)"),
      'ушло_в_архив'        => $one("SELECT COUNT(*) FROM ds_monitor_log WHERE event='auto_paused' AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)"),
    ];

    // Обход каталога: успеваем ли за 3 месяца
    $wait = $one("SELECT COUNT(*) FROM ds_products WHERE ds_status<>'paused_manual' AND gone_at IS NULL
                    AND COALESCE(last_price_check, created_at) < DATE_SUB(NOW(), INTERVAL 90 DAY)");
    $out['обход_каталога'] = [
      'ждёт_очереди_сейчас' => $wait,
      'проверено_за_сутки'  => $one("SELECT COUNT(*) FROM ds_products WHERE last_price_check >= DATE_SUB(NOW(), INTERVAL 1 DAY)"),
      'проверено_за_30_дней'=> $one("SELECT COUNT(*) FROM ds_products WHERE last_price_check >= DATE_SUB(NOW(), INTERVAL 30 DAY)"),
      'ни_разу_не_проверено'=> $one("SELECT COUNT(*) FROM ds_products WHERE last_price_check IS NULL"),
    ];
    // Темп считается сам — тот же расчёт, что и при запуске обхода
    $act  = $one("SELECT COUNT(*) FROM ds_products WHERE ds_status<>'paused_manual' AND gone_at IS NULL");
    $base = ($act > 0) ? (int)ceil($act / 90) : 0;
    $catch= ($wait > 0) ? (int)ceil(max(0, $wait - $base) / 7) : 0;
    $out['темп_обхода'] = [
      'ровный_темп_в_сутки' => $base,
      'догон_очереди'       => $catch,
      'возьмёт_за_запуск'   => max(10, min(3000, $base + $catch)),
      'полный_круг_дней'    => ($base > 0) ? 90 : 0,
      'пояснение'           => 'Число считается само по размеру каталога — в задании его указывать не нужно',
    ];

    // Светофор — что проверяется чаще
    $tiers = ['A'=>0,'B'=>0,'C'=>0];
    try { foreach (db()->query("SELECT tier, COUNT(*) c FROM ob_track GROUP BY tier")->fetchAll() as $t)
            if (isset($tiers[$t['tier']])) $tiers[$t['tier']] = (int)$t['c']; } catch (Exception $e) {}
    $out['светофор_карточек'] = $tiers;

    // Расход запросов
    try {
      $out['запросы'] = db()->query("SELECT
              SUM(billable=1 AND created_at >= CURDATE()) AS платных_сегодня,
              SUM(billable=1 AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)) AS платных_за_30_дней,
              ROUND(SUM(CASE WHEN created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN cost_cny ELSE 0 END),2) AS юаней_за_30_дней
            FROM ob_log")->fetch();
    } catch (Exception $e) {}

    jout($out);
  }

  case 'itc_ob_limits': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    $intv = ['A'=>7, 'B'=>21, 'C'=>90];
    $out = ['ok'=>true];

    // 1. Что под наблюдением
    $byTier = ['A'=>0,'B'=>0,'C'=>0,'прочее'=>0];
    $iids = [];
    try {
      foreach (db()->query("SELECT num_iid,tier FROM ob_track")->fetchAll() as $t) {
        $tr = (string)$t['tier'];
        if (isset($byTier[$tr])) $byTier[$tr]++; else $byTier['прочее']++;
        $iids[(string)$t['num_iid']] = $tr;
      }
    } catch (Exception $e) {}
    $out['под_наблюдением'] = $byTier;
    $out['карточек_всего']  = count($iids);

    // 2. Сколько запросов это даёт
    $perDay = 0;
    foreach ($intv as $tr=>$days) if ($days > 0) $perDay += $byTier[$tr] / $days;
    $out['расписание_дней']   = $intv;
    $out['запросов_в_сутки']  = round($perDay, 1);
    $out['запросов_в_месяц']  = (int)round($perDay * 30);

    // 3. Охват: по скольким товарам цена вообще может обновиться правильно
    $cov = ['товаров_1688'=>0, 'из_них_под_наблюдением'=>0, 'вариант_опознаётся'=>0, 'варианта_нет'=>0];
    try {
      $rows = db()->query("SELECT d.product_id, d.source_url FROM ds_products d WHERE d.source_url LIKE '%1688.com/offer/%'")->fetchAll();
      $skuOk = [];
      try { foreach (db()->query("SELECT product_id FROM ob_sku WHERE spec_id IS NOT NULL AND spec_id<>''")->fetchAll() as $sk) $skuOk[(string)$sk['product_id']] = 1; } catch (Exception $e) {}
      foreach ($rows as $r) {
        $cov['товаров_1688']++;
        if (preg_match('/offer\/(\d+)/', (string)$r['source_url'], $m) && isset($iids[$m[1]])) {
          $cov['из_них_под_наблюдением']++;
          if (isset($skuOk[(string)$r['product_id']])) $cov['вариант_опознаётся']++; else $cov['варианта_нет']++;
        }
      }
    } catch (Exception $e) {}
    $out['охват'] = $cov;
    $out['не_под_наблюдением'] = $cov['товаров_1688'] - $cov['из_них_под_наблюдением'];

    // 4. Сколько уже тратим по нашему журналу
    try {
      $lg = db()->query("SELECT
              SUM(created_at >= CURDATE()) AS всего_сегодня,
              SUM(billable=1 AND created_at >= CURDATE()) AS платных_сегодня,
              SUM(billable=1 AND created_at >= DATE_SUB(NOW(), INTERVAL 7 DAY))  AS платных_за_7_дней,
              SUM(billable=1 AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)) AS платных_за_30_дней,
              ROUND(SUM(CASE WHEN created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN cost_cny ELSE 0 END),2) AS юаней_за_30_дней
            FROM ob_log")->fetch();
      $out['наш_журнал'] = $lg;
    } catch (Exception $e) { $out['наш_журнал'] = 'журнал недоступен: '.$e->getMessage(); }

    // 5. Что говорит сам посредник (бесплатно — из кэша)
    $out['лимит_посредника'] = 'не удалось узнать';
    $probe = null;
    foreach (array_keys($iids) as $one) { $probe = $one; break; }
    if (!$probe) { try { $probe = (string)db()->query("SELECT num_iid FROM ob_sku LIMIT 1")->fetchColumn(); } catch (Exception $e) {} }
    if ($probe) {
      $r = ob_call('item_get', ['num_iid'=>$probe], ['cache'=>'yes']);
      $info = (string)($r['data']['api_info'] ?? '');
      if ($info !== '') {
        $out['лимит_посредника'] = $info;   // вида «today:123 max:10000»
        if (preg_match('/today:\s*(\d+).*?max:\s*(\d+)/i', $info, $mm)) {
          $today = (int)$mm[1]; $max = (int)$mm[2];
          $out['израсходовано_сегодня'] = $today;
          $out['потолок_в_сутки']       = $max;
          $need = $out['запросов_в_сутки'];
          $out['вердикт'] = ($max <= 0)
            ? 'потолок не пришёл — уточнить у onebound'
            : (($need + $today) < $max * 0.8
                ? 'лимита хватает с запасом'
                : (($need + $today) < $max ? 'впритык — стоит взять пакет побольше' : 'ЛИМИТА НЕ ХВАТИТ — нужен другой тариф'));
        }
      } else {
        $out['лимит_посредника'] = 'ответ без строки api_info (код '.($r['error_code'] ?? '?').')';
      }
    }
    jout($out);
  }

  case 'itc_price_check': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    $fix = !empty($_GET['fix']);
    $all = !empty($_GET['all']);
    $rows = db()->query("SELECT d.id ds_id, d.product_id, d.source_price_cny cur_cny,
                                sk.price_cny sku_cny, sk.num_iid,
                                p.name prod_name, p.price prod_rub
                           FROM ds_products d
                           JOIN ob_sku sk ON sk.product_id = d.product_id
                           LEFT JOIN products p ON p.id = d.product_id
                          WHERE sk.price_cny IS NOT NULL AND sk.price_cny > 0")->fetchAll();
    // минимальная цена по каждой карточке — с ней и сравниваем «почерк»
    $minByOffer = [];
    try {
      foreach (db()->query("SELECT num_iid, MIN(price_cny) m FROM ob_sku WHERE price_cny>0 GROUP BY num_iid")->fetchAll() as $mr)
        $minByOffer[(string)$mr['num_iid']] = (float)$mr['m'];
    } catch (Exception $e) {}
    $bad = []; $fixed = 0; $total = 0; $bugs = 0;
    foreach ($rows as $r) {
      $total++;
      $cur = ($r['cur_cny'] === null) ? null : (float)$r['cur_cny'];
      $sku = (float)$r['sku_cny'];
      if ($cur !== null && abs($cur - $sku) < 0.01) continue;
      $min = $minByOffer[(string)$r['num_iid']] ?? null;
      $isBug = ($cur !== null && $min !== null && abs($cur - $min) < 0.01 && abs($sku - $min) >= 0.01);
      if ($isBug) $bugs++;
      $item = ['product_id'=>$r['product_id'], 'name'=>$r['prod_name'],
               'num_iid'=>$r['num_iid'], 'was_cny'=>$cur, 'should_cny'=>$sku,
               'price_rub_was'=>$r['prod_rub'],
               'diag'=>($isBug ? 'цена чужого варианта (минимальная по карточке)'
                               : 'разошлось по другой причине — проверить руками')];
      if ($fix && ($isBug || $all)) {
        try {
          db()->prepare("UPDATE ds_products SET source_price_cny=? WHERE id=?")->execute([$sku, $r['ds_id']]);
          if (function_exists('ds_sync_product_price')) ds_sync_product_price($r['ds_id']);
          $pq = db()->prepare("SELECT price FROM products WHERE id=?"); $pq->execute([$r['product_id']]);
          $item['price_rub_now'] = $pq->fetchColumn();
          $item['fixed'] = 1;
          $fixed++;
        } catch (Exception $e) { $item['error'] = $e->getMessage(); }
      }
      $bad[] = $item;
    }
    // Сначала самые крупные расхождения — по ним и убыток самый заметный
    usort($bad, function($a,$b){
      $da = abs((float)$a['should_cny'] - (float)($a['was_cny'] ?? 0));
      $db2= abs((float)$b['should_cny'] - (float)($b['was_cny'] ?? 0));
      return $db2 <=> $da;
    });
    jout(['ok'=>true, 'mode'=>($fix ? ($all?'починка ВСЕГО':'починка следов ошибки') : 'только показ'),
          'checked'=>$total, 'mismatch'=>count($bad), 'looks_like_bug'=>$bugs, 'fixed'=>$fixed,
          'hint'=>'Добавьте &fix=1 чтобы починить помеченные «цена чужого варианта». Остальное — руками.',
          'items'=>array_slice($bad, 0, 200)]);
  }

  case 'itc_recategorize': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) {
      $s=authUser('itc'); require_staff($s,['boss']);
    }
    $rows=db()->query("SELECT id,name,cat FROM products")->fetchAll();
    $upd=db()->prepare("UPDATE products SET cat=? WHERE id=?");
    $counts=[]; $changed=0; $total=0;
    foreach($rows as $r){
      $total++;
      $c=itc_store_category($r['name']);
      if($c!==($r['cat']??'')){ $upd->execute([$c,$r['id']]); $changed++; }
      $counts[$c]=($counts[$c]??0)+1;
    }
    arsort($counts);
    jout(['ok'=>true,'total'=>$total,'changed'=>$changed,'counts'=>$counts]);
  }

  // Босс: опубликовать ВСЁ (кроме заблокированных) + диагностика статусов.
  case 'products_publish_all': {
    $s=authUser('itc'); require_staff($s,['boss','manager','moderator']);
    $diag=function(){
      $r=['total'=>0,'approved'=>0,'draft'=>0,'pending'=>0,'rejected'=>0,'empty'=>0,'blocked'=>0,'visible'=>0];
      try{
        $r['total']   =(int)db()->query("SELECT COUNT(*) c FROM products")->fetch()['c'];
        $r['blocked'] =(int)db()->query("SELECT COUNT(*) c FROM products WHERE blocked=1")->fetch()['c'];
        $r['approved']=(int)db()->query("SELECT COUNT(*) c FROM products WHERE mod_status='approved'")->fetch()['c'];
        $r['draft']   =(int)db()->query("SELECT COUNT(*) c FROM products WHERE mod_status='draft'")->fetch()['c'];
        $r['pending'] =(int)db()->query("SELECT COUNT(*) c FROM products WHERE mod_status='pending'")->fetch()['c'];
        $r['rejected']=(int)db()->query("SELECT COUNT(*) c FROM products WHERE mod_status='rejected'")->fetch()['c'];
        $r['empty']   =(int)db()->query("SELECT COUNT(*) c FROM products WHERE mod_status IS NULL OR mod_status=''")->fetch()['c'];
        $r['visible'] =(int)db()->query("SELECT COUNT(*) c FROM products WHERE (blocked=0 OR blocked IS NULL) AND (mod_status IS NULL OR mod_status='' OR mod_status='approved')")->fetch()['c'];
      }catch(Exception $e){}
      return $r;
    };
    $before=$diag();
    $n=0;
    try{ $n=db()->exec("UPDATE products SET mod_status='approved' WHERE (blocked=0 OR blocked IS NULL) AND COALESCE(mod_status,'')<>'approved'"); }
    catch(Exception $e){ fail('Ошибка публикации: '.$e->getMessage()); }
    $after=$diag();
    jout(['ok'=>true,'published'=>(int)$n,'before'=>$before,'after'=>$after]);
  }

  // Босс: только диагностика (без изменений) — где застряли товары.
