  // Полные данные одной карточки (тяжёлые поля) — грузятся при открытии товара.
  case 'product_full': {
    $d=body(); $id=trim($d['id'] ?? '');
    if($id==='') fail('Нет id');
    $r=null;
    try{ $q=db()->prepare("SELECT descr,video,gallery,specs,assembled,boxes,variants,search_tags,material FROM products WHERE id=? LIMIT 1"); $q->execute([$id]); $r=$q->fetch(); }
    catch(Exception $e){ try{ $q=db()->prepare("SELECT descr,gallery,specs,assembled,boxes,variants FROM products WHERE id=? LIMIT 1"); $q->execute([$id]); $r=$q->fetch(); }catch(Exception $e2){} }
    if(!$r) fail('Товар не найден');
    /* №282: ВАРИАНТЫ ТОВАРА. Покупатель грузит витрину по страницам, и других
       вариантов того же товара 1688 у него в памяти нет — выбор «Выберите
       вариант» не появлялся, «Купить» вело сразу к оплате. Отдаём ключ склейки
       и всех живых соседей с той же ссылкой 1688. */
    $grpKey = ''; $members = [];
    try {
      $sq = db()->prepare("SELECT source_url FROM ds_products WHERE product_id=? AND source_url IS NOT NULL AND source_url<>'' LIMIT 1"); $sq->execute([$id]);
      $src = (string)($sq->fetchColumn() ?: '');
      if ($src !== '') {
        $grpKey = substr(md5($src),0,10);
        $mq = db()->prepare("SELECT p.id,p.supplier_id,p.cat,p.subcat,p.name,p.price,p.old_price,p.goods_cny,p.volume_m3,p.img,p.stock,p.original,p.blocked,p.mod_status,p.weight_kg,p.color
                               FROM ds_products d JOIN products p ON p.id=d.product_id
                              WHERE d.source_url=? AND COALESCE(p.blocked,0)=0 LIMIT 150");
        $mq->execute([$src]);
        foreach ($mq->fetchAll() as $m) { $m['grp'] = $grpKey; $m['ds'] = 1; $members[] = $m; }
      }
    } catch (Exception $e) {}
    $stockRu = 0; try { $stockRu = stock_available($id); } catch (Throwable $e) {}
    /* №327: ОСНОВНЫЕ ПОЛЯ ТОВАРА ТОЖЕ ОТДАЁМ. Раньше здесь были только тяжёлые
       поля (описание, фото, характеристики). Если товара не было в памяти
       телефона (экран выкупа, а с №326 — любой экран сотрудника до загрузки
       каталога), карточка собиралась без названия, категории и цены:
       «0 ₽», категория «Диваны», пустое название. */
    $base = [];
    try {
      $bq = db()->prepare('SELECT id,supplier_id,cat,subcat,name,price,old_price,img,stock,clicks,color,original,
                ready_type,production_days,goods_cny,volume_m3,warehouse_id,blocked,paused,mod_status,
                discount_percent,promo_boost,sales_boost,old_price_rub,weight_kg,pcs_per_box,promo_until,
                created_at,created_by,jfactory_id,factory,moderated_by,moderated_at
                FROM products WHERE id=? LIMIT 1');
      $bq->execute([$id]); $base = $bq->fetch() ?: [];
      if ($base) {
        $base['blocked'] = ((int)($base['blocked'] ?? 0) || (int)($base['paused'] ?? 0)) ? 1 : 0;
        try { $sn = db()->prepare('SELECT name FROM suppliers WHERE id=?'); $sn->execute([$base['supplier_id']]); $base['supplier_name'] = (string)($sn->fetchColumn() ?: ''); } catch (Exception $e) { $base['supplier_name'] = ''; }
        $base['jf'] = stripos($base['supplier_name'], 'Jinjia') !== false ? 1 : 0;
        $base['ds'] = 0;
      }
    } catch (Exception $e) { $base = []; }
    jout(['ok'=>true,'product'=>$base + [
      'id'=>$id, 'grp'=>$grpKey, 'grp_members'=>$members, 'stock_ru'=>$stockRu,
      'descr'=>$r['descr'] ?? '', 'video'=>$r['video'] ?? '', 'gallery'=>$r['gallery'] ?? '',
      'specs'=>$r['specs'] ?? '', 'assembled'=>$r['assembled'] ?? '',
      'boxes'=>$r['boxes'] ?? '', 'variants'=>$r['variants'] ?? '',
      'search_tags'=>$r['search_tags'] ?? '', 'material'=>$r['material'] ?? ''
    ]]);
  }

  // ---- Поиск по каталогу (по всей базе: название/описание/характеристики/ключевые слова/подкатегория) ----
  /* ПОЛНОТЕКСТОВЫЙ ПОИСК: создание указателя и замер (обновление №206).
     Открывать так: ?action=itc_ft — покажет состояние и время поиска.
     С &make=1 создаёт указатель, с &drop=1 убирает его и возвращает всё как было. */
  case 'itc_ft': {
    $cron_key = trim($_GET['cron_key'] ?? ''); $expected = defined('DS_CRON_KEY') ? DS_CRON_KEY : '';
    if ($expected && $cron_key !== $expected) { http_response_code(403); echo 'forbidden'; exit; }
    @set_time_limit(900);
    header('Content-Type: text/plain; charset=utf-8');

    $have = itc_products_columns();
    $has  = function ($n) use ($have) { return !$have || isset($have[$n]); };
    $cols = [];
    foreach (itc_ft_cols() as $c) if ($has($c)) $cols[] = $c;

    echo "=== ПОЛНОТЕКСТОВЫЙ ПОИСК ===\n";
    echo 'Колонки указателя: '.implode(', ', $cols)."\n";

    if (!empty($_GET['drop'])) {
      $a = microtime(true);
      try { db()->query('ALTER TABLE products DROP INDEX idx_prod_ft'); echo 'Указатель убран за '.round((microtime(true)-$a)*1000)." мс\n"; }
      catch (Exception $e) { echo 'Убрать не вышло: '.mb_substr($e->getMessage(), 0, 90)."\n"; }
      itc_ft_ready(false);
      echo "Поиск вернулся к прежнему способу.\n\n=== КОНЕЦ ===\n"; exit;
    }

    if (!empty($_GET['make'])) {
      if (count($cols) < 1) { echo "Нет ни одной колонки для указателя.\n=== КОНЕЦ ===\n"; exit; }
      $a = microtime(true);
      try {
        db()->query('ALTER TABLE products ADD FULLTEXT INDEX idx_prod_ft ('.implode(',', $cols).')');
        echo 'Указатель построен за '.round((microtime(true)-$a)*1000)." мс\n";
      } catch (Exception $e) { echo 'Построить не вышло: '.mb_substr($e->getMessage(), 0, 120)."\n"; }
    }

    $exists = itc_ft_exists();
    echo 'Указатель на месте: '.($exists ? 'да' : 'НЕТ — откройте эту же ссылку с &make=1')."\n";

    /* Переводим поиск на указатель только когда он действительно построен —
       иначе покупатель увидел бы пустую выдачу. */
    if ($exists) { itc_ft_ready(true); echo "Поиск переведён на указатель.\n"; }
    else { itc_ft_ready(false); }

    // Сравнение на редком слове — это и есть худший случай
    $probe = trim($_GET['q'] ?? 'щипцы для завивки');
    $ws = preg_split('/[\s,;\.]+/u', mb_strtolower($probe), -1, PREG_SPLIT_NO_EMPTY);
    echo "\nПроверочное слово: «{$probe}»\n";

    $hayParts = [];
    foreach ($cols as $c) $hayParts[] = ($c === 'name') ? 'name' : "COALESCE($c,'')";
    $hay = "LOWER(CONCAT_WS(' ', ".implode(', ', $hayParts)."))";
    $a = microtime(true); $n0 = 0;
    try {
      $st = db()->prepare("SELECT id FROM products WHERE $hay LIKE ? LIMIT 400");
      $st->execute(['%'.mb_strtolower($probe).'%']); $n0 = count($st->fetchAll());
    } catch (Exception $e) {}
    echo 'Прежний способ (перебор): найдено '.$n0.' за '.round((microtime(true)-$a)*1000)." мс\n";

    if ($exists) {
      $terms = itc_ft_terms($ws);
      $expr = ''; foreach ($terms as $t) $expr .= '+'.$t.'* ';
      $a = microtime(true); $n1 = 0;
      try {
        $st = db()->prepare("SELECT id FROM products
                             WHERE MATCH(".implode(',', $cols).") AGAINST (? IN BOOLEAN MODE) LIMIT 400");
        $st->execute([trim($expr)]); $n1 = count($st->fetchAll());
      } catch (Exception $e) { echo 'Ошибка поиска по указателю: '.mb_substr($e->getMessage(), 0, 90)."\n"; }
      echo 'По указателю: найдено '.$n1.' за '.round((microtime(true)-$a)*1000)." мс\n";
      echo 'Запрос к указателю: '.trim($expr)."\n";
    }

    echo "\nЕсли что-то пойдёт не так — откройте эту ссылку с &drop=1, поиск вернётся к прежнему способу.\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  /* СОСТОЯНИЕ ПЕРЕНОСА ФОТО (обновление №207).
     Товар, у которого картинка ещё лежит на alicdn, покупателю НЕ виден —
     так устроено условие видимости. Значит скорость переноса фото прямо
     определяет, сколько карточек человек вообще увидит в каталоге.
     Эта команда ничего не переносит, только считает. При каждом открытии она
     запоминает остаток и время, а в следующий раз показывает, сколько ушло за
     прошедший срок — по этому и видно, работает ли перенос сам по себе. */
  case 'itc_photos_stat': {
    header('Content-Type: text/plain; charset=utf-8');
    @set_time_limit(120);
    echo "=== ПЕРЕНОС ФОТО ===\n\n";

    $total = 0; $hidden = 0; $noimg = 0; $visible = 0;
    try { $total   = (int)db()->query("SELECT COUNT(*) FROM products")->fetchColumn(); } catch (Exception $e) {}
    try { $hidden  = (int)db()->query("SELECT COUNT(*) FROM products WHERE img LIKE '%alicdn%'")->fetchColumn(); } catch (Exception $e) {}
    try { $noimg   = (int)db()->query("SELECT COUNT(*) FROM products WHERE img IS NULL OR img=''")->fetchColumn(); } catch (Exception $e) {}
    try { $visible = (int)db()->query("SELECT COUNT(*) FROM products WHERE vis=1")->fetchColumn(); } catch (Exception $e) {}

    echo "Всего карточек: {$total}\n";
    echo "Видит покупатель: {$visible}\n";
    echo "СКРЫТО из-за фото на alicdn: {$hidden}\n";
    echo "Скрыто из-за пустого фото: {$noimg}\n";

    $left = -1;
    if (function_exists('ob_row')) {
      try {
        $lr = ob_row("SELECT COUNT(DISTINCT num_iid) c FROM ob_img
                      WHERE (url_s3 IS NULL OR url_s3='') AND kind IN ('main','sku')");
        $left = (int)($lr['c'] ?? 0);
      } catch (Exception $e) {}
    }
    echo "\nТоваров в очереди на перенос: ".($left < 0 ? 'не удалось посчитать' : $left)."\n";

    /* Отметка прошлого раза — по ней и считаем скорость. */
    $prevV = null; $age = 0;
    try {
      db()->query("CREATE TABLE IF NOT EXISTS itc_cnt_cache (
        k VARCHAR(120) NOT NULL PRIMARY KEY, v INT NOT NULL, ts DATETIME NOT NULL
      ) DEFAULT CHARSET=utf8mb4");
      $r = db()->query("SELECT v, ts, TIMESTAMPDIFF(SECOND, ts, NOW()) age
                        FROM itc_cnt_cache WHERE k='photo_left_mark'")->fetch();
      if ($r) { $prevV = (int)$r['v']; $age = (int)$r['age']; }
    } catch (Exception $e) {}

    if ($prevV === null) {
      echo "\nЭто первое измерение — отметка поставлена.\n";
      echo "Откройте эту же ссылку ещё раз минут через десять-пятнадцать,\n";
      echo "и станет видно, идёт перенос сам по себе или стоит.\n";
    } else {
      $moved = $prevV - $left;
      $mins  = $age / 60;
      echo "\nПрошлое измерение: {$prevV} в очереди, ".round($mins)." мин назад\n";
      if ($age < 120) {
        echo "Слишком мало времени прошло — подождите хотя бы десять минут.\n";
      } elseif ($moved <= 0) {
        echo "ПЕРЕНОС НЕ ИДЁТ: за это время очередь не уменьшилась.\n";
        echo "Значит команда по расписанию не запускается.\n";
      } else {
        $perHour = $moved / ($mins / 60);
        echo "Перенесено за это время: {$moved} · это ".round($perHour)." товаров в час\n";
        if ($perHour > 0 && $left > 0) {
          $hoursLeft = $left / $perHour;
          echo 'На текущую очередь при такой скорости уйдёт: '.round($hoursLeft, 1)." ч (".round($hoursLeft / 24, 1)." сут)\n";
          $h500 = 500000 / $perHour;
          echo 'На полмиллиона при такой скорости ушло бы: '.round($h500 / 24)." сут\n";
        }
      }
    }
    try { db()->prepare('REPLACE INTO itc_cnt_cache (k,v,ts) VALUES (?,?,NOW())')->execute(['photo_left_mark', max(0, $left)]); } catch (Exception $e) {}

    echo "\nКоманда переноса по расписанию (если её нет — добавить):\n";
    echo "  * * * * * curl -s \"https://itcpartner.store/api/api.php?action=ob_photos_cron&key=ВАШ_КЛЮЧ\" > /dev/null\n";
    echo "\n=== КОНЕЦ ===\n";
    exit;
  }

  case 'catalog_search': {
    $q = trim($_GET['q'] ?? '');
    if ($q === '') jout(['ok'=>true,'products'=>[], 'count'=>0]);
    // Сотрудник? (по токену) — тогда показываем и черновики/без фото
    $staff = false;
    $t = $_GET['t'] ?? '';
    if ($t) { try { $ss = db()->prepare("SELECT role FROM sessions WHERE token=?"); $ss->execute([$t]); if ($ss->fetchColumn() === 'itc') $staff = true; } catch (Exception $e) {} }
    $have = [];
    try { foreach (db()->query("SHOW COLUMNS FROM products")->fetchAll() as $c) { $have[strtolower($c['Field'])] = true; } } catch (Exception $e) {}
    $has = function($c) use ($have) { return isset($have[strtolower($c)]); };
    // Слова запроса + грубый стем (обрезаем окончание) — чтобы ловить склонения
    $ql = mb_strtolower($q);
    $words = preg_split('/[\s,;\.]+/u', $ql, -1, PREG_SPLIT_NO_EMPTY);
    $stems = [];
    foreach ($words as $w) {
      if (mb_strlen($w) < 2) continue;
      /* Обрезаем окончание, но у коротких слов только одну букву: от «столы»
         должно оставаться «стол», а не «сто» — иначе в выдачу лезут стойки и
         столешницы. */
      $n = mb_strlen($w);
      if ($n >= 7)     $s = mb_substr($w, 0, $n - 2);
      elseif ($n >= 5) $s = mb_substr($w, 0, $n - 1);
      else             $s = $w;
      $s = str_replace(['\\','%','_'], ['\\\\','\\%','\\_'], $s);
      $stems[] = $s;
    }
    if (!$stems) jout(['ok'=>true,'products'=>[], 'count'=>0]);
    $hayCols = ['name'];
    foreach (['subcat','cat','material','search_tags','descr'] as $c) { if ($has($c)) $hayCols[] = $c; }
    $hayParts = [];
    foreach ($hayCols as $c) { $hayParts[] = ($c === 'name') ? 'name' : "COALESCE($c,'')"; }
    $hay = "LOWER(CONCAT_WS(' ', ".implode(', ', $hayParts)."))";
    /* №328 · ПОИСК ПО СМЫСЛУ. DeepSeek один раз объясняет, как ещё называются товары по
       такому запросу («аккумулятор» → повербанк, батарея, LiFePO4…), ответ хранится месяц
       и общий для всех покупателей — поэтому быстро и дёшево даже при тысячах человек.
       Спрашиваем сразу, если запрос из трёх и больше слов (человек описывает своими словами),
       или вторым проходом, если обычный поиск нашёл мало. */
    require_once __DIR__ . '/ai_lib.php';
    $aiTerms = itc_ai_terms($q, false);
    if ($aiTerms === null && count($words) >= 3) $aiTerms = itc_ai_terms($q, true);
    $aiPass = 0;
    itc_search_again:
    $conds = []; $params = [];
    foreach ($stems as $s) { $conds[] = "$hay LIKE ?"; $params[] = '%'.$s.'%'; }
    $origCond = '('.implode(' AND ', $conds).')';
    // --- Синонимы: если запрос относится к группе, добавляем OR по всем терминам группы ---
    $synGroups = [
      ['повербанк','повер банк','пауэрбанк','паур банк','power bank','powerbank','внешний аккумулятор','портативн','аккумулятор','заряд','power'],
      ['батаре','аккумулятор','элемент питания','крона','пальчиков','аккумуляторн'],
      ['генератор','электрогенератор','бензогенератор','дизельгенератор','электростанц','power station','инвертор','мотогенератор'],
      ['трансформатор','преобразовател','инвертор','конвертер','блок питания','адаптер','стабилизатор','выпрямител'],
      ['кабель','провод','шнур','usb','type-c','зарядн кабель','удлинител'],
      ['лампа','лампочк','светильник','светодиод','led','фонар','подсветк','прожектор','ночник'],
      ['наушник','гарнитур','earbuds','headphones','tws','airpods','вкладыш','беспроводн наушник'],
      ['часы','смарт-часы','смарт часы','smart watch','watch','браслет','фитнес-браслет'],
      ['колонк','динамик','speaker','саундбар','акустик','bluetooth колонк','музыкальн колонк'],
      ['телефон','смартфон','phone','гаджет','мобильн'],
      ['вентилятор','кулер','fan','обдув','охлажден'],
      ['обогреватель','тепловентилятор','нагреватель','heater','тепловая пушк','конвектор'],
      ['пылесос','vacuum','робот-пылесос'],
      ['камер','видеокамер','webcam','экшн-камер','видеорегистратор'],
      ['зарядн','зарядка','зарядник','charger','адаптер питания','сзу','беспроводн зарядк'],
      ['кондиционер','сплит-систем','ac','климат'],
      ['холодильник','fridge','морозильник','минибар'],
      ['инструмент','дрель','шуруповерт','болгарк','перфоратор','лобзик'],
      ['рюкзак','сумка','backpack','баул','портфель'],
      ['ноутбук','laptop','нетбук'],
      ['монитор','дисплей','экран','screen'],
      ['мышь','мышка','mouse','клавиатур','keyboard'],
      ['проектор','projector','мультимедийн проектор'],
      ['увлажнитель','humidifier','аромадиффузор','диффузор'],
    ];
    $expand = [];
    foreach ($synGroups as $grp) {
      $hit = false;
      foreach ($grp as $term) {
        $t = mb_strtolower($term);
        if ($t === '') continue;
        if (mb_stripos($ql, $t) !== false) { $hit = true; break; }
        foreach ($stems as $sw) {
          $swr = str_replace(['\\%','\\_','\\\\'], ['%','_','\\'], $sw);
          if (mb_strlen($swr) >= 3 && (mb_stripos($t, $swr) !== false || mb_stripos($swr, $t) !== false)) { $hit = true; break; }
        }
        if ($hit) break;
      }
      if ($hit) { foreach ($grp as $term) { $tt = mb_strtolower($term); if ($tt !== '') $expand[$tt] = true; } }
    }
    if ($aiTerms) foreach ($aiTerms as $tt) $expand[$tt] = true;
    $orParts = [$origCond];
    foreach (array_keys($expand) as $term) {
      $esc = str_replace(['\\','%','_'], ['\\\\','\\%','\\_'], $term);
      $orParts[] = "$hay LIKE ?"; $params[] = '%'.$esc.'%';
    }
    $visCond = '';
    if (!$staff) {
      if ($has('blocked'))    $visCond .= " AND (blocked=0 OR blocked IS NULL)";
      if ($has('paused'))     $visCond .= " AND (paused=0 OR paused IS NULL)";
      if ($has('mod_status')) $visCond .= " AND (mod_status IS NULL OR mod_status NOT IN ('pending','rejected'))";
    }
    $where = '('.implode(' OR ', $orParts).')'.$visCond;
    /* factory нужна для перемешивания: поставщик у нас почти всегда один
       (Jinjia), а вот фабрика-производитель у товаров разная — чередуем по ней. */
    $base = ['id','supplier_id','factory','cat','subcat','name','price','old_price','img','video','stock','clicks','color','original','goods_cny','volume_m3','warehouse_id','blocked','mod_status','material','search_tags','descr','created_at','discount_percent','weight_kg'];
    $selCols = [];
    foreach ($base as $c) { if ($c === 'id' || $has($c)) $selCols[] = $c; }
    $colSql = implode(',', $selCols);
    $order = $has('created_at') ? 'created_at DESC' : 'id DESC';
    $rows = []; $errMsg = ''; $ftUsed = false;

    /* СНАЧАЛА ПРОБУЕМ УКАЗАТЕЛЬ (обновление №206).
       Если он построен — ищем по нему. Если его нет, он сломался или ничего не
       нашёл, спокойно уходим на прежний перебор: выдача покупателю не должна
       зависеть от того, успели мы построить указатель или нет. */
    $ftCols = [];
    foreach (itc_ft_cols() as $c) if ($has($c)) $ftCols[] = $c;
    if (itc_ft_ready() && count($ftCols)) {
      $terms = itc_ft_terms($words);
      if (count($terms)) {
        $expr = ''; foreach ($terms as $tm) $expr .= '+'.$tm.'* ';
        $expr = trim($expr);
        $ftMatch = 'MATCH('.implode(',', $ftCols).') AGAINST (? IN BOOLEAN MODE)';
        /* БЕРЁМ САМЫЕ ПОДХОДЯЩИЕ, А НЕ САМЫЕ СВЕЖИЕ.
           Сначала я оставил прежний порядок «сначала новые» — и в четыреста
           отобранных строк попадали только последние завезённые товары, а
           настоящие совпадения оставались за бортом. Поэтому упорядочиваем по
           тому, насколько строка подходит запросу; окончательный порядок всё
           равно считается ниже, в разборе. */
        try {
          $st = db()->prepare("SELECT $colSql, ($ftMatch) AS ftrel FROM products
                               WHERE $ftMatch{$visCond} ORDER BY ftrel DESC, $order LIMIT 400");
          $st->execute([$expr, $expr]);
          $rows = $st->fetchAll();
          $ftUsed = true;
        } catch (Exception $e) { $errMsg = $e->getMessage(); $rows = []; $ftUsed = false; }

        /* Синонимы. Указатель не умеет выразить «все слова запроса ИЛИ любой
           синоним» одним запросом, поэтому синонимы спрашиваем отдельно и
           доклады­ваем к найденному. Срабатывает редко, поэтому дёшево. */
        if ($ftUsed && count($expand)) {
          $synTerms = itc_ft_terms(array_keys($expand));
          if (count($synTerms)) {
            $sexpr = implode(' ', array_map(function ($x) { return $x.'*'; }, array_slice($synTerms, 0, 20)));
            try {
              $st = db()->prepare("SELECT $colSql FROM products WHERE $ftMatch{$visCond} ORDER BY $order LIMIT 200");
              $st->execute([$sexpr]);
              $seenId = [];
              foreach ($rows as $r0) $seenId[(string)$r0['id']] = 1;
              foreach ($st->fetchAll() as $r1) {
                if (isset($seenId[(string)$r1['id']])) continue;
                $seenId[(string)$r1['id']] = 1; $rows[] = $r1;
              }
            } catch (Exception $e) {}
          }
        }
      }
    }

    // Прежний способ — если указатель не использовался или не дал ничего
    if (!$ftUsed || !count($rows)) {
      try { $st = db()->prepare("SELECT $colSql FROM products WHERE $where ORDER BY $order LIMIT 400"); $st->execute($params); $rows = $st->fetchAll(); }
      catch (Exception $e) { $errMsg = $e->getMessage(); $rows = []; }
    }
    $snmap = []; try { foreach (db()->query('SELECT id,name FROM suppliers')->fetchAll() as $s0) $snmap[$s0['id']] = $s0['name']; } catch (Exception $e) {}
    $out = [];
    foreach ($rows as $p) {
      if (!$staff) { $img = (string)($p['img'] ?? ''); if ($img === '' || mb_stripos($img, 'alicdn') !== false) continue; }
      $nm = mb_strtolower($p['name'] ?? ''); $tg = mb_strtolower($p['search_tags'] ?? '');
      $sb = mb_strtolower($p['subcat'] ?? ''); $ds = mb_strtolower($p['descr'] ?? '');
      $score = 0;
      foreach ($stems as $s) {
        $su = str_replace(['\\%','\\_','\\\\'], ['%','_','\\'], $s); // вернуть экранирование для сравнения
        if (mb_stripos($nm, $su) !== false) $score += 10;
        if (mb_stripos($tg, $su) !== false) $score += 6;
        if (mb_stripos($sb, $su) !== false) $score += 4;
        if (mb_stripos($ds, $su) !== false) $score += 2;
      }
      if (mb_stripos($nm, $ql) !== false) $score += 15; // точная фраза в названии
      foreach (array_keys($expand) as $et) { if (mb_stripos($nm, $et) !== false) { $score += 5; } elseif (mb_stripos($tg, $et) !== false || mb_stripos($ds, $et) !== false) { $score += 2; } }
      $p['supplier_name'] = $snmap[$p['supplier_id']] ?? '';
      $p['ds'] = 0; $p['jf'] = 0;
      unset($p['descr']); // описание на клиент не тащим (тяжёлое)
      $p['_score'] = $score;
      $out[] = $p;
    }
    usort($out, function($a, $b){ if ($b['_score'] !== $a['_score']) return $b['_score'] - $a['_score']; return strcmp((string)($b['created_at'] ?? ''), (string)($a['created_at'] ?? '')); });
    /* Разводим соседей: подряд не должны идти одна и та же модель и товары
       одной фабрики. Ничего не выбрасываем — только меняем порядок. */
    $out = itc_mix_spread($out, 150);
    // мало нашли и DeepSeek ещё не спрашивали — спрашиваем и ищем ещё раз
    if (count($out) < 8 && $aiTerms === null && !$aiPass) {
      $aiPass = 1; $aiTerms = itc_ai_terms($q, true);
      if ($aiTerms) { $rows = []; $errMsg = ''; $ftUsed = false; goto itc_search_again; }
    }
    $diag = null;
    if (count($out) === 0) {
      $diag = ['total'=>0,'blocked'=>0,'name_match'=>0,'any_match'=>0,'staff'=>($staff?1:0),'ver'=>'v452','err'=>($errMsg?substr($errMsg,0,140):'')];
      $raw = mb_strtolower($q);
      $rawLike = '%'.str_replace(['\\','%','_'], ['\\\\','\\%','\\_'], $raw).'%';
      try { $diag['total'] = (int)db()->query("SELECT COUNT(*) FROM products")->fetchColumn(); } catch (Exception $e) {}
      try { $diag['blocked'] = (int)db()->query("SELECT COUNT(*) FROM products WHERE blocked=1")->fetchColumn(); } catch (Exception $e) {}
      try { $st = db()->prepare("SELECT COUNT(*) FROM products WHERE LOWER(name) LIKE ?"); $st->execute([$rawLike]); $diag['name_match'] = (int)$st->fetchColumn(); } catch (Exception $e) {}
      try { $st = db()->prepare("SELECT COUNT(*) FROM products WHERE $hay LIKE ?"); $st->execute([$rawLike]); $diag['any_match'] = (int)$st->fetchColumn(); } catch (Exception $e) {}
    }
    jout(['ok'=>true, 'products'=>$out, 'count'=>count($out), 'diag'=>$diag, 'staff'=>($staff?1:0), 'ft'=>($ftUsed?1:0), 'ai'=>($aiTerms ? count($aiTerms) : 0), 'ver'=>'v453']);
  }

  // ---- Оживить «зависшие» карточки 1688: цена по себестоимости ×N, снять блокировку ----
  case 'ob_revive_stuck_x3': {
    $s = authUser('itc'); require_staff($s, ['boss','manager','supervisor']);
    $mult = (float)($_GET['mult'] ?? 4); if ($mult < 1 || $mult > 20) $mult = 4;
    // Зависшие = заблокированные товары, привязанные к ds_products, с известной себестоимостью
    $rows = [];
    try { $rows = db()->query("SELECT d.id ds_id FROM ds_products d JOIN products p ON p.id=d.product_id WHERE p.blocked=1 AND d.source_price_cny>0")->fetchAll(); }
    catch (Exception $e) { jout(['ok'=>false,'error'=>'Ошибка выборки']); }
    $fixed = 0;
    foreach ($rows as $r) {
      try {
        db()->prepare("UPDATE ds_products SET x3_pending=1, x3_mult=? WHERE id=?")->execute([$mult, $r['ds_id']]);
        ds_sync_product_price($r['ds_id']); // сама поставит цену ×N и blocked=0
        $fixed++;
      } catch (Exception $e) {}
    }
    jout(['ok'=>true, 'fixed'=>$fixed, 'total'=>count($rows), 'mult'=>$mult]);
  }

  // Ручной промо-подъём товара в ленте (0 — обычный, 1..3 — сила подъёма).
  case 'product_boost': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    $d=body(); $id=trim($d['id'] ?? ''); $lvl=(int)($d['level'] ?? 0);
    if($id==='') fail('Нет id');
    if($lvl<0)$lvl=0; if($lvl>3)$lvl=3;
    try{ db()->prepare("UPDATE products SET promo_boost=? WHERE id=?")->execute([$lvl,$id]); }
    catch(Exception $e){ fail('Ошибка (нужна миграция promo_boost?)'); }
    jout(['ok'=>true,'level'=>$lvl]);
  }

  // Тест-режим: включить/выключить группировку вариантов в одну карточку.
  case 'set_group_variants': {
    $s=authUser('itc'); require_staff($s,['boss']);
    $d=body(); $on=!empty($d['on'])?1:0;
    try{ db()->prepare("INSERT INTO settings (k,v) VALUES ('group_variants',?) ON DUPLICATE KEY UPDATE v=VALUES(v)")->execute([$on]); }
    catch(Exception $e){ fail('Ошибка сохранения'); }
    jout(['ok'=>true,'on'=>$on]);
  }

  // Массовый перенос фото 1688 на S3 партиями (чинит уже импортированные товары).
  case 'ob_photos_bulk': {
    $s=authUser('itc'); require_staff($s,['boss','manager','supervisor']);
    if(!function_exists('ob_photos_process')) fail('ob_photo.php не подключён');
    $d=body();
    $n=(int)($d['n'] ?? 15); if($n<1)$n=15; if($n>40)$n=40;
    $iids=[]; 
    try{ $iids = ob_all("SELECT DISTINCT num_iid FROM ob_img WHERE (url_s3 IS NULL OR url_s3='') AND kind IN ('main','sku') ORDER BY num_iid DESC LIMIT ".$n); }catch(Exception $e){}
    $items=0; $done=0; $fail=0;
    foreach($iids as $row){
      try{ $r = ob_photos_process($row['num_iid'], ['kinds'=>['main','sku'],'limit'=>20]); $done += (int)($r['done']??0); $fail += (int)($r['failed']??0); }
      catch(Exception $e){}
      $items++;
    }
    $left=0;
    try{ $lr = ob_row("SELECT COUNT(DISTINCT num_iid) c FROM ob_img WHERE (url_s3 IS NULL OR url_s3='') AND kind IN ('main','sku')"); $left=(int)($lr['c']??0); }catch(Exception $e){}
    // Заодно проставляем фабрику новым товарам: перенос фото и так гоняется по свежему
    // импорту, а вписывать это в семь мест, где создаётся карточка, — верный способ забыть.
    $fac = ['done'=>0,'left'=>0]; try{ $fac = itc_factory_fill(200); }catch(Exception $e){}
    jout(['ok'=>true,'items'=>$items,'done'=>$done,'failed'=>$fail,'left'=>$left,'fabriki'=>$fac]);
  }

  // Cron: круглосуточный автоперенос фото на S3 (без логина, защита ключом).
  case 'ob_photos_cron': {
    if (!hash_equals('a7f3c9e15b2d84itc', (string)($_GET['key'] ?? ''))) fail('forbidden', 403);
    if (!function_exists('ob_photos_process')) { jout(['ok'=>false,'error'=>'ob_photo.php не подключён']); break; }
    $iids = [];
    try { $iids = ob_all("SELECT DISTINCT num_iid FROM ob_img WHERE (url_s3 IS NULL OR url_s3='') AND kind IN ('main','sku') ORDER BY num_iid DESC LIMIT 30"); } catch (Exception $e) {}
    $items=0; $done=0; $fail=0;
    foreach ($iids as $row) {
      try { $r = ob_photos_process($row['num_iid'], ['kinds'=>['main','sku'],'limit'=>20]); $done += (int)($r['done']??0); $fail += (int)($r['failed']??0); } catch (Exception $e) {}
      $items++;
    }
    $left=0;
    try { $lr = ob_row("SELECT COUNT(DISTINCT num_iid) c FROM ob_img WHERE (url_s3 IS NULL OR url_s3='') AND kind IN ('main','sku')"); $left=(int)($lr['c']??0); } catch (Exception $e) {}
    $fac = ['done'=>0,'left'=>0]; try{ $fac = itc_factory_fill(200); }catch(Exception $e){}
    jout(['ok'=>true,'items'=>$items,'done'=>$done,'failed'=>$fail,'left'=>$left,'fabriki'=>$fac]);
  }

  // Этап A модульности: постраничная выдача каталога для витрины.
  // Аддитивный эндпоинт — bootstrap и старый путь не трогаются. Сортировка по
  // хранимым колонкам (быстро даже на 100k). Тяжёлые поля — по product_full.
  // ---- проставить фабрику-производителя в карточках (можно открыть ссылкой) ----
  case 'factory_fill': {
    $key = trim($_GET['key'] ?? '');
    if ($key !== 'a7f3c9e15b2d84itc') { try { authUser('itc'); } catch (Exception $e) { fail('Нет доступа', 403); } }
    jout(itc_factory_fill((int)($_GET['n'] ?? 2000)));
  }

  // ---- другие товары той же фабрики ----
  case 'factory_products': {
    itc_factory_ensure();
    $fid = trim($_GET['factory'] ?? '');
    $skip = trim($_GET['skip'] ?? '');
    $lim = (int)($_GET['limit'] ?? 12); if ($lim < 1) $lim = 12; if ($lim > 40) $lim = 40;
    $off = (int)($_GET['offset'] ?? 0); if ($off < 0) $off = 0;
    if ($fid === '') jout(['ok' => true, 'products' => [], 'total' => 0]);
    $rows = []; $total = 0;
    $w = "p.factory = ? AND (p.blocked=0 OR p.blocked IS NULL) AND (p.paused=0 OR p.paused IS NULL)
          AND p.img IS NOT NULL AND p.img<>'' AND p.img NOT LIKE '%alicdn%'";
    $a = [$fid];
    if ($skip !== '') { $w .= " AND p.id <> ?"; $a[] = $skip; }
    try { $c = db()->prepare("SELECT COUNT(*) c FROM products p WHERE $w"); $c->execute($a); $total = (int)$c->fetchColumn(); } catch (Exception $e) {}
    try {
      $q = db()->prepare("SELECT p.id,p.name,p.price,p.old_price,p.img,p.cat,p.supplier_id
                            FROM products p WHERE $w ORDER BY p.id DESC LIMIT $lim OFFSET $off");
      $q->execute($a); $rows = $q->fetchAll();
    } catch (Exception $e) {}
    jout(['ok' => true, 'products' => $rows, 'total' => $total, 'offset' => $off, 'factory' => $fid]);
  }

  // ---- запись интереса: просмотр карточки, поиск, добавление в корзину ----
  // ---- восстановление входа: приложение потеряло токен, но cookie цела ----
  // ---- выход: гасим cookie, чтобы вход не восстановился ----
  case 'logout_cookie': {
    try {
      $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
      if (PHP_VERSION_ID >= 70300) setcookie('itc_t', '', ['expires'=>time()-3600,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Lax']);
      else setcookie('itc_t', '', time()-3600, '/', '', $secure, true);
    } catch (Exception $e) {}
    jout(['ok' => true]);
  }

  case 'whoami': {
    $t = trim($_COOKIE['itc_t'] ?? '');
    if ($t === '') jout(['ok' => false]);
    try {
      $q = db()->prepare('SELECT token,phone,role,supplier_id,staff_role FROM sessions WHERE token=? LIMIT 1');
      $q->execute([$t]);
      $r = $q->fetch();
      if (!$r) jout(['ok' => false]);
      itc_set_token_cookie($t);           // продлеваем срок при каждом заходе
      jout(['ok' => true, 'token' => $r['token'], 'phone' => $r['phone'], 'role' => $r['role'],
            'supplier_id' => $r['supplier_id'], 'staff_role' => ($r['staff_role'] ?? '')]);
    } catch (Exception $e) { jout(['ok' => false]); }
  }

  case 'track_event': {
    itc_events_ensure();
    $d = body();
    $uid = mb_substr(trim($d['uid'] ?? ''), 0, 64);
    $kind = trim($d['kind'] ?? 'view');
    if (!in_array($kind, ['view','search','cart'], true)) $kind = 'view';
    if ($uid === '') jout(['ok' => true, 'skipped' => 1]);
    $pid = mb_substr(trim($d['product_id'] ?? ''), 0, 32);
    $cat = mb_substr(trim($d['cat'] ?? ''), 0, 120);
    $q   = mb_substr(trim($d['q'] ?? ''), 0, 160);
    // категорию не берём на веру — читаем из карточки товара
    if ($pid !== '') {
      try { $g = db()->prepare('SELECT cat FROM products WHERE id=?'); $g->execute([$pid]);
            $row = $g->fetch(); if ($row && !empty($row['cat'])) $cat = $row['cat']; } catch (Exception $e) {}
    }
    try { db()->prepare('INSERT INTO user_events (uid,kind,product_id,cat,q) VALUES (?,?,?,?,?)')
            ->execute([$uid, $kind, ($pid !== '' ? $pid : null), ($cat !== '' ? $cat : null), ($q !== '' ? $q : null)]); }
    catch (Exception $e) {}
    jout(['ok' => true]);
  }

  /* ---- Полосы «Новинки», «Акции», «Скидки» страницами с сервера ----
     Раньше эти три экрана строились из ОБЩЕГО списка товаров, и только ради них
     покупателю фоном скачивался весь каталог. Здесь тот же отбор делает база:
     условия видимости те же, что в витрине, плюс своё условие на каждый вид. */
  case 'strip_page': {
    $kind   = strtolower(trim($_GET['kind'] ?? 'news'));
    if (!in_array($kind, ['news', 'promo', 'deals', 'rec'], true)) $kind = 'news';
    $limit  = (int)($_GET['limit'] ?? 60);  if ($limit < 1) $limit = 60; if ($limit > 240) $limit = 240;   // №268: порции полос втрое крупнее
    $offset = (int)($_GET['offset'] ?? 0);  if ($offset < 0) $offset = 0;

    itc_factory_ensure();
    $have = itc_products_columns();
    $has  = function ($n) use ($have) { return !$have || isset($have[$n]); };

    // Видимость — точно как в catalog_page, иначе покупателю приедет то, чего он видеть не должен
    $where = "1=1";
    if ($has('blocked')) $where .= " AND (p.blocked=0 OR p.blocked IS NULL)";
    if ($has('paused'))  $where .= " AND (p.paused=0 OR p.paused IS NULL)";
    if ($has('vis') && itc_vis_ready()) {
      $where = "p.vis=1";
    } else {
      if ($has('mod_status')) $where .= " AND (p.mod_status='approved' OR p.mod_status='' OR p.mod_status IS NULL)";
      $where .= " AND p.img IS NOT NULL AND p.img<>'' AND p.img NOT LIKE '%alicdn%'";
    }
    // Своё условие для каждого вида
    if ($kind === 'promo') {
      if (!$has('promo_until')) jout(['ok' => true, 'products' => [], 'total' => 0, 'has_more' => false]);
      $where .= " AND p.promo_until IS NOT NULL AND p.promo_until > NOW()";
    } elseif ($kind === 'deals') {
      $where .= " AND p.old_price IS NOT NULL AND p.old_price > p.price AND p.price > 0";
    }

    $total = itc_count_cached('strip:'.$kind.':'.md5($where),
                              "SELECT COUNT(*) c FROM products p WHERE $where", [], 300);

    $base  = ['id','supplier_id','cat','name','price','old_price','img','video','stock','clicks','color','original','ready_type','production_days'];
    $extra = ['subcat','mod_status','discount_percent','promo_until','blocked','paused','created_at','factory','sold'];
    $cols  = [];
    foreach (array_merge($base, $extra) as $c) if ($has($c)) $cols[] = 'p.'.$c;
    $ordCol = $has('created_at') ? 'created_at' : 'id';
    $ordIn  = $has('created_at') ? 'p.created_at DESC, p.id DESC' : 'p.id DESC';
    $makerExp = $has('factory') ? "COALESCE(NULLIF(p.factory,''), p.supplier_id, '')" : "COALESCE(p.supplier_id,'')";
    /* Порядок случайный, но стабильный в пределах суток: иначе при переходе на
       вторую страницу товары перемешались бы и пошли повторы. */
    $shuffle = 'CRC32(CONCAT(p.id, ' . db()->quote((string)date('Ymd')) . '))';
    $discExp = "CASE WHEN p.old_price > p.price AND p.old_price > 0 THEN (p.old_price - p.price) / p.old_price ELSE 0 END";
    /* Популярность для полосы «Рекомендуем»: продажи весомее просмотров, поэтому
       умножаем их на миллион — ровно так это считалось в приложении. */
    $popExp  = ($has('sold') ? 'COALESCE(p.sold,0)' : '0').' * 1000000 + '.($has('clicks') ? 'COALESCE(p.clicks,0)' : '0');

    /* «РЕКОМЕНДУЕМ» — БЫСТРЫЙ ПУТЬ (обновление №204).
       Нам нужна всего дюжина самых ходовых карточек. Берём верхушку прямо по
       индексу (vis, sold, clicks) — база читает несколько сотен строк и
       останавливается, а не пересчитывает витрину целиком. Семейства и фабрики
       разбираются дальше в PHP, см. itc_strip_spread. */
    if ($kind === 'rec') {
      $pool = ($offset + $limit) * 8;
      if ($pool < 120) $pool = 120;
      if ($pool > 600) $pool = 600;
      $ordPop = ($has('sold') ? 'p.sold DESC, ' : '').($has('clicks') ? 'p.clicks DESC, ' : '').'p.id DESC';
      $rows = [];
      try {
        $st = db()->prepare("SELECT ".implode(',', $cols).", s.name AS supplier_name
                             FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
                             WHERE $where ORDER BY $ordPop LIMIT $pool");
        $st->execute(); $rows = $st->fetchAll();
      } catch (Exception $e) { $rows = []; }
      $out = itc_strip_spread($rows, $offset, $limit);
      jout(['ok' => true, 'kind' => $kind, 'products' => $out, 'total' => $total,
            'has_more' => (count($rows) > $offset + $limit)]);
    }

    $rows = []; $done = false;
    try {
      $outer = implode(',', array_map(function ($c) { return 't.'.substr($c, 2); }, $cols));
      /* Одна модель приезжает десятком почти одинаковых карточек. Оставляем от
         семейства одну — самую свежую (в приложении это делалось перебором всего
         каталога), а потом раскладываем по фабрикам «по кругу», чтобы подряд не
         шли товары одного производителя. */
      if     ($kind === 'deals') $outerOrd = 't.rn_sup, t.disc DESC, t.id DESC';
      elseif ($kind === 'promo') $outerOrd = 't.rn_sup, t.shuf, t.id DESC';
      elseif ($kind === 'rec')   $outerOrd = 't.rn_sup, t.pop DESC, t.id DESC';
      else                       $outerOrd = 't.rn_sup, t.'.$ordCol.' DESC, t.id DESC';
      /* Внутри одной фабрики для «Рекомендуем» первым должен идти самый ходовой
         товар, а не самый свежий — иначе полоса перестаёт быть рекомендацией. */
      $supOrd = ($kind === 'rec') ? 'b.pop DESC, b.id DESC' : 'b.'.$ordCol.' DESC, b.id DESC';
      $sql = "SELECT $outer, t.supplier_name FROM (
                SELECT b.*, ROW_NUMBER() OVER (PARTITION BY b.maker ORDER BY $supOrd) rn_sup
                FROM (
                  SELECT ".implode(',', $cols).", s.name AS supplier_name,
                         $makerExp AS maker,
                         $shuffle AS shuf,
                         $discExp AS disc,
                         $popExp AS pop,
                         ROW_NUMBER() OVER (PARTITION BY LEFT(p.name,40) ORDER BY $ordIn) rn_fam
                  FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
                  WHERE $where
                ) b
                WHERE b.rn_fam = 1
              ) t
              ORDER BY $outerOrd
              LIMIT $limit OFFSET $offset";
      $st = db()->prepare($sql); $st->execute(); $rows = $st->fetchAll(); $done = true;
    } catch (Exception $e) { $done = false; }
    if (!$done) {
      // Откат для баз без оконных функций: без склейки семейств, просто по порядку
      try {
        if     ($kind === 'deals') $ord = "($discExp) DESC, p.id DESC";
        elseif ($kind === 'promo') $ord = "$shuffle, p.id DESC";
        elseif ($kind === 'rec')   $ord = "($popExp) DESC, p.id DESC";
        else                       $ord = $ordIn;
        $st = db()->prepare("SELECT ".implode(',', $cols).", s.name AS supplier_name
                             FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
                             WHERE $where ORDER BY $ord LIMIT $limit OFFSET $offset");
        $st->execute(); $rows = $st->fetchAll();
      } catch (Exception $e2) { $rows = []; }
    }
    jout(['ok' => true, 'kind' => $kind, 'products' => $rows, 'total' => $total,
          'has_more' => (count($rows) >= $limit)]);
  }

  /* ПОХОЖИЕ ТОВАРЫ — ТЕПЕРЬ СЧИТАЕТ СЕРВЕР (обновление №201).
     Раньше приложение разбирало на слова весь каталог у себя в памяти, и ради
     одного этого блока покупателю качался полный список товаров. Здесь тот же
     отбор делает база: берём подкатегорию и значимые слова названия, считаем
     очки и отдаём готовый список. */
  case 'similar_products': {
    $pid   = trim($_GET['id'] ?? '');
    $limit = (int)($_GET['limit'] ?? 20); if ($limit < 1) $limit = 20; if ($limit > 40) $limit = 40;
    if ($pid === '') jout(['ok' => true, 'products' => [], 'total' => 0]);

    $have = itc_products_columns();
    $has  = function ($n) use ($have) { return !$have || isset($have[$n]); };

    // Сам товар — от него пляшем
    $meCols = ['id', 'name', 'price'];
    foreach (['cat', 'subcat'] as $c) if ($has($c)) $meCols[] = $c;
    $me = null;
    try {
      $st = db()->prepare("SELECT ".implode(',', $meCols)." FROM products WHERE id=? LIMIT 1");
      $st->execute([$pid]); $me = $st->fetch();
    } catch (Exception $e) { $me = null; }
    if (!$me) jout(['ok' => true, 'products' => [], 'total' => 0]);

    $sub  = trim((string)($me['subcat'] ?? ''));
    $cat  = trim((string)($me['cat']    ?? ''));
    $base = (float)($me['price'] ?? 0);

    /* Значимые слова названия: короче четырёх букв не берём, больше трёх штук
       не берём. Окончание грубо обрезаем, чтобы ловить склонения. */
    $words = preg_split('/[^\p{L}\p{N}]+/u', mb_strtolower((string)$me['name']), -1, PREG_SPLIT_NO_EMPTY);
    $stems = [];
    foreach ($words as $w) {
      if (mb_strlen($w) < 4) continue;
      $s = (mb_strlen($w) >= 6) ? mb_substr($w, 0, mb_strlen($w) - 2) : $w;
      $stems[] = str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $s);
      if (count($stems) >= 3) break;
    }
    $subOk = ($sub !== '' && $has('subcat'));
    if (!$stems && !$subOk) jout(['ok' => true, 'products' => [], 'total' => 0]);

    // Видимость — точно такая же, как у витрины и полос
    $where = "1=1";
    if ($has('blocked')) $where .= " AND (p.blocked=0 OR p.blocked IS NULL)";
    if ($has('paused'))  $where .= " AND (p.paused=0 OR p.paused IS NULL)";
    if ($has('vis') && itc_vis_ready()) {
      $where = "p.vis=1";
    } else {
      if ($has('mod_status')) $where .= " AND (p.mod_status='approved' OR p.mod_status='' OR p.mod_status IS NULL)";
      $where .= " AND p.img IS NOT NULL AND p.img<>'' AND p.img NOT LIKE '%alicdn%'";
    }

    // Очки: общее слово в названии весомее подкатегории, категория почти не в счёт
    $scoreParts = []; $scoreParams = [];
    foreach ($stems as $s) { $scoreParts[] = "(CASE WHEN LOWER(p.name) LIKE ? THEN 10 ELSE 0 END)"; $scoreParams[] = '%'.$s.'%'; }
    if ($subOk)                      { $scoreParts[] = "(CASE WHEN p.subcat = ? THEN 5 ELSE 0 END)"; $scoreParams[] = $sub; }
    if ($cat !== '' && $has('cat'))  { $scoreParts[] = "(CASE WHEN p.cat = ? THEN 2 ELSE 0 END)";    $scoreParams[] = $cat; }
    if ($base > 0)                   { $scoreParts[] = "GREATEST(0, 3 - ABS(COALESCE(p.price,0) - ?) / ? * 3)"; $scoreParams[] = $base; $scoreParams[] = $base; }
    $scoreExp = $scoreParts ? implode(' + ', $scoreParts) : '0';

    // Кого вообще рассматриваем: общее слово в названии ИЛИ та же подкатегория
    $matchParts = []; $matchParams = [];
    foreach ($stems as $s) { $matchParts[] = "LOWER(p.name) LIKE ?"; $matchParams[] = '%'.$s.'%'; }
    if ($subOk)            { $matchParts[] = "p.subcat = ?";         $matchParams[] = $sub; }

    $cols = [];
    foreach (['id','supplier_id','cat','subcat','name','price','old_price','img','video','stock','clicks',
              'color','original','ready_type','production_days','mod_status','discount_percent',
              'promo_until','blocked','paused','created_at','factory','sold'] as $c) {
      if ($c === 'id' || $has($c)) $cols[] = 'p.'.$c;
    }

    /* ЖЁСТКО ОГРАНИЧИВАЕМ ОТБОР КАТЕГОРИЕЙ (обновление №204).
       Поиск куска слова внутри названия база ускорить не умеет — ей приходится
       читать все строки подряд: замер показал 324 мс на 35 тысячах, то есть
       около четырёх с половиной секунд на полумиллионе. Категория же
       проиндексирована, и внутри неё строк в десятки раз меньше. Похожий товар
       из чужой категории всё равно не похожий, так что теряем мы немного. */
    $hard = ''; $hardParams = [];
    if ($cat !== '' && $has('cat')) { $hard = " AND p.cat = ?"; $hardParams[] = $cat; }

    $sql = "SELECT ".implode(',', $cols).", s.name AS supplier_name, ($scoreExp) AS sim
            FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
            WHERE $where AND p.id<>?{$hard} AND (".implode(' OR ', $matchParts).")
            ORDER BY sim DESC, p.id DESC
            LIMIT 300";
    $params = array_merge($scoreParams, [$pid], $hardParams, $matchParams);

    $rows = [];
    try { $st = db()->prepare($sql); $st->execute($params); $rows = $st->fetchAll(); }
    catch (Exception $e) { $rows = []; }

    // От семейства одна карточка, фабрики по кругу — тем же разбором, что и полосы
    $out = itc_strip_spread($rows, 0, $limit);

    jout(['ok' => true, 'products' => $out, 'total' => count($out), 'cat' => $cat]);
  }

  case 'catalog_page': {
    // логирование запроса — ниже, когда посчитаем, сколько нашлось
    $limit = (int)($_GET['limit'] ?? 60); if ($limit < 1) $limit = 60; if ($limit > 120) $limit = 120;
    $offset = (int)($_GET['offset'] ?? 0); if ($offset < 0) $offset = 0;
    $cat = trim($_GET['cat'] ?? '');
    $q = trim($_GET['q'] ?? '');
    // База у разных установок отличается: часть колонок могла не доехать миграцией.
    // Спрашиваем у самой таблицы, что в ней есть, и строим запрос только из этих колонок —
    // иначе одна отсутствующая колонка роняет всю витрину и покупатель видит пустой каталог.
    itc_factory_ensure();          // колонка factory должна существовать до опроса схемы
    $have = itc_products_columns();
    $has = function ($n) use ($have) { return !$have || isset($have[$n]); };

    $where = "1=1";
    if ($has('blocked')) $where .= " AND (p.blocked=0 OR p.blocked IS NULL)";
    if ($has('paused'))  $where .= " AND (p.paused=0 OR p.paused IS NULL)";
    $args = [];
    // Витрина покупателя: те же условия видимости, что и в приложении, — иначе страница
    // приходит наполовину пустой (прошедшие модерацию + фото уже перенесено с 1688).
    if ((int)($_GET['all'] ?? 0) !== 1) {
      /* Готовый флаг вместо четырёх проверок — по нему работает индекс.
         Пока флаг не заполнен целиком, считаем по-старому. */
      if ($has('vis') && itc_vis_ready()) {
        $where = "p.vis=1";
      } else {
        if ($has('mod_status')) $where .= " AND (p.mod_status='approved' OR p.mod_status='' OR p.mod_status IS NULL)";
        $where .= " AND p.img IS NOT NULL AND p.img<>'' AND p.img NOT LIKE '%alicdn%'";
      }
    }
    if ($cat !== '' && $cat !== 'all') { $where .= " AND p.cat=?"; $args[] = $cat; }
    $subF = trim((string)($_GET['sub'] ?? ''));   // №293: фильтр подкатегории
    if ($subF !== '' && $has('subcat')) { $where .= " AND p.subcat=?"; $args[] = $subF; }
    if ($q !== '') { $where .= " AND p.name LIKE ?"; $args[] = '%'.$q.'%'; }
    $total = itc_count_cached('cat:'.md5($where.'|'.json_encode($args)),
                              "SELECT COUNT(*) c FROM products p WHERE $where", $args, 300);
    /* Пишем в журнал только ПЕРВУЮ страницу: при прокрутке тот же запрос
       прилетает снова, и без этого условия один поиск считался бы за пять. */
    if ($q !== '' && $offset === 0) itc_search_log($q, $total);
    $rows = [];
    try {
      // Простой запрос по первичному ключу — без подзапросов и без NOT LIKE (быстро даже на 100k).
      $base = ['id','supplier_id','cat','name','price','old_price','img','video','stock','clicks','color','original','ready_type','production_days'];
      $extra = ['subcat','mod_status','discount_percent','promo_until','blocked','paused','created_at','factory'];
      $cols = [];
      foreach (array_merge($base, $extra) as $c) if ($has($c)) $cols[] = 'p.'.$c;
      $ord = $has('created_at') ? 'p.created_at DESC, p.id DESC' : 'p.id DESC';
      // Импорт приходит пачками: одна модель — десятки почти одинаковых карточек подряд.
      // Раскладываем ленту «по кругу»: сперва по одному товару каждого названия и каждой
      // фабрики, потом вторые, потом третьи. Требует оконных функций (MySQL 8),
      // поэтому ниже есть откат на обычную сортировку по дате.
      // ===== Умная лента =====
      // На каждые 10 карточек: 4 под интересы покупателя, 3 популярных, 2 новинки,
      // 1 случайная — чтобы лента не замыкалась. Если интересов ещё нет (новый
      // покупатель), их доля просто схлопывается и остаётся нормальная витрина.
      $me = mb_substr(trim($_GET['me'] ?? ''), 0, 64);
      $myCats = ($me !== '') ? itc_user_cats($me) : [];
      $mixed = false;
      try {
        $ordIn  = $has('created_at') ? 'p.created_at DESC, p.id DESC' : 'p.id DESC';
        /* Популярность СГЛАЖИВАЕМ. Раньше это была прямая сумма просмотров и продаж,
           поэтому один товар с 61 просмотром намертво занимал первое место — и чем
           дольше он там висел, тем больше набирал просмотров. Продажа весит больше
           просмотра, а сам показатель ограничен сверху: набрав потолок, товар
           перестаёт отрываться от остальных. */
        $popExp = $has('sold')
          ? 'LEAST(20, COALESCE(p.sold,0)*3 + LEAST(10, COALESCE(p.clicks,0)))'
          : 'LEAST(10, COALESCE(p.clicks,0))';
        /* И перемешиваем: порядок стабилен в пределах дня и посетителя, но назавтра
           наверх выходят другие товары. Иначе витрина выглядит застывшей. */
        $seed = (string)date('Ymd') . '|' . $me;
        $shuffle = 'CRC32(CONCAT(p.id, ' . db()->quote($seed) . '))';
        $newExp = $has('created_at') ? '(p.created_at >= DATE_SUB(NOW(), INTERVAL 60 DAY))' : '0';
        $ordCol = $has('created_at') ? 'created_at' : 'id';
        // Разводим по ФАБРИКЕ-производителю: поставщик у нас один (Jinjia), он закупает
        // у разных фабрик, и без этого вся витрина выглядела как товар одного продавца.
        // Где фабрика ещё не проставлена — падаем обратно на поставщика.
        $makerExp = $has('factory') ? "COALESCE(NULLIF(p.factory,''), p.supplier_id, '')" : "COALESCE(p.supplier_id,'')";
        $catArgs = [];
        if ($myCats) { $catIn = 'p.cat IN ('.implode(',', array_fill(0, count($myCats), '?')).')'; $catArgs = $myCats; }
        else { $catIn = '0'; }
        $outer = implode(',', array_map(function ($c) { return 't.'.substr($c, 2); }, $cols));
        // Одна фабрика заливает витрину десятками почти одинаковых карточек — тот же
        // товар в другом размере, иногда даже с тем же фото. Поэтому считаем два
        // номера: внутри СЕМЕЙСТВА (поставщик + начало названия, 40 знаков — этого
        // хватает, чтобы «столик 90 см» и «столик 100 см» попали в одну группу)
        // и внутри ПОСТАВЩИКА. Лента строится по номеру внутри поставщика: сперва
        // по одной карточке от каждого, потом по второй, и так далее. Остальные
        // варианты уезжают далеко вниз, а рядом их всё равно видно в «похожих».
        $sql = "SELECT $outer, t.supplier_name FROM (
                  SELECT c.*,
                    CASE c.stream
                      WHEN 1 THEN FLOOR((c.rn-1)/4)*10 + MOD(c.rn-1,4)
                      WHEN 2 THEN FLOOR((c.rn-1)/3)*10 + 4 + MOD(c.rn-1,3)
                      WHEN 3 THEN FLOOR((c.rn-1)/2)*10 + 7 + MOD(c.rn-1,2)
                      ELSE (c.rn-1)*10 + 9
                    END AS pos
                  FROM (
                    SELECT b.*, ROW_NUMBER() OVER (PARTITION BY b.stream ORDER BY b.rn_sup, b.rn_fam, FLOOR(b.pop/7) DESC, b.shuf, b.$ordCol DESC, b.id DESC) rn
                    FROM (
                      SELECT a.*, ROW_NUMBER() OVER (PARTITION BY a.maker ORDER BY a.rn_fam, FLOOR(a.pop/7) DESC, a.shuf, a.$ordCol DESC, a.id DESC) rn_sup
                      FROM (
                        SELECT ".implode(',', $cols).", s.name AS supplier_name,
                               $popExp AS pop,
                        $shuffle AS shuf,
                               CASE WHEN $catIn THEN 1
                                    WHEN $popExp > 0 THEN 2
                                    WHEN $newExp THEN 3
                                    ELSE 4 END AS stream,
                               ROW_NUMBER() OVER (PARTITION BY $makerExp, LEFT(p.name,40) ORDER BY $ordIn) rn_fam,
                               $makerExp AS maker
                        FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
                        WHERE $where
                      ) a
                    ) b
                  ) c
                ) t
                ORDER BY t.pos, t.id DESC
                LIMIT $limit OFFSET $offset";
        $st = db()->prepare($sql); $st->execute(array_merge($catArgs, $args)); $rows = $st->fetchAll(); $mixed = true;
      } catch (Exception $e) { $mixed = false; }
      if (!$mixed) {
        $sql = "SELECT ".implode(',', $cols).", s.name AS supplier_name
                FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
                WHERE $where ORDER BY $ord LIMIT $limit OFFSET $offset";
        $st = db()->prepare($sql); $st->execute($args); $rows = $st->fetchAll();
      }
    } catch (Exception $e) {
      // Последняя страховка: минимальный набор полей без сортировки по дате.
      try {
        $st = db()->prepare("SELECT p.id,p.supplier_id,p.cat,p.name,p.price,p.old_price,p.img,p.stock, s.name AS supplier_name
                             FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
                             WHERE $where ORDER BY p.id DESC LIMIT $limit OFFSET $offset");
        $st->execute($args); $rows = $st->fetchAll();
      } catch (Exception $e2) { jout(['ok'=>false,'error'=>$e2->getMessage()]); break; }
    }
    // Обогащение (рейтинг, продажи, дропшиппинг) — отдельными лёгкими запросами только по id страницы.
    if ($rows) {
      $ids = array_map(function ($r) { return $r['id']; }, $rows);
      $ph = implode(',', array_fill(0, count($ids), '?'));
      $rat = []; $sld = []; $dsmap = [];
      try { $rq = db()->prepare("SELECT product_id, ROUND(AVG(rating),1) a, COUNT(*) c FROM reviews WHERE product_id IN ($ph) GROUP BY product_id"); $rq->execute($ids); foreach ($rq->fetchAll() as $x) { $rat[$x['product_id']] = $x; } } catch (Exception $e) {}
      try { $sq = db()->prepare("SELECT i.product_id pid, COALESCE(SUM(i.qty),0) s FROM order_items i JOIN orders o ON o.id=i.order_id AND o.paid=1 WHERE i.product_id IN ($ph) GROUP BY i.product_id"); $sq->execute($ids); foreach ($sq->fetchAll() as $x) { $sld[$x['pid']] = (int)$x['s']; } } catch (Exception $e) {}
      /* №282: ключ склейки вариантов (общая ссылка 1688) — как в bootstrap.
         Без него у покупателя в карточке не появлялось «Выберите вариант». */
      $grpmap = [];
      try { $dq = db()->prepare("SELECT product_id, source_url FROM ds_products WHERE product_id IN ($ph)"); $dq->execute($ids);
            foreach ($dq->fetchAll() as $x) { $dsmap[$x['product_id']] = 1; if (!isset($grpmap[$x['product_id']]) && (string)$x['source_url'] !== '') $grpmap[$x['product_id']] = substr(md5($x['source_url']),0,10); } } catch (Exception $e) {}
      foreach ($rows as &$r) { $r['rating_avg'] = $rat[$r['id']]['a'] ?? 0; $r['reviews_count'] = (int)($rat[$r['id']]['c'] ?? 0); $r['sold'] = $sld[$r['id']] ?? 0; $r['ds'] = $dsmap[$r['id']] ?? 0; $r['grp'] = $grpmap[$r['id']] ?? ''; } unset($r);
    }
    /* РАЗВОДИМ СОСЕДЕЙ ВНУТРИ СТРАНИЦЫ.
       Запрос выше уже отодвигает варианты одной модели вниз, но когда у фабрики
       мало товаров, они всё равно встают рядом — подряд десяток одинаковых
       картинок с разной ценой. Здесь только МЕНЯЕМ ПОРЯДОК уже отобранных
       карточек: состав страницы не трогаем, поэтому постраничность остаётся
       прежней и повторов при докрутке не появится. */
    $rows = itc_mix_spread($rows);
    jout(['ok'=>true,'products'=>$rows,'total'=>$total,'offset'=>$offset,'limit'=>$limit,'has_more'=>($offset + count($rows) < $total)]);
  }

  default:
    fail('Неизвестное действие', 404);

  }

} catch (Throwable $e) {
  fail('Ошибка сервера: ' . $e->getMessage(), 500);
}

