function itc_seal_html($seals, $co) {
  $s = $seals[$co] ?? [];
  $seal = $s['seal_img'] ?? ''; $sign = $s['sign_img'] ?? '';
  $h = '';
  if ($sign) $h .= '<img src="'.htmlspecialchars($sign).'" style="max-height:60px;vertical-align:middle">';
  if ($seal) $h .= '<img src="'.htmlspecialchars($seal).'" style="max-height:90px;vertical-align:middle;margin-left:-20px">';
  return $h ?: '<span style="color:#999">(печать / 盖章)</span>';
}
function supplier_contract_html($sup, $seals) {
  $payCo = ($sup['pay_company'] === 'jinjia') ? 'jinjia' : 'itk';
  $buyer = itc_buyer_reqs($payCo);
  $rd = json_decode($sup['reg_data'] ?: '{}', true) ?: [];
  $no = htmlspecialchars($sup['contract_no'] ?: '—');
  $date = $sup['contract_at'] ? date('d.m.Y', strtotime($sup['contract_at'])) : date('d.m.Y');
  $sname = htmlspecialchars($sup['name'] ?: '');
  $szh = htmlspecialchars($sup['zh'] ?: '');
  // реквизиты продавца из reg_data
  $sr = [];
  if (!empty($rd['inn']))   $sr[] = 'ИНН / 纳税人识别号: '.htmlspecialchars($rd['inn']).(!empty($rd['kpp'])?' · КПП: '.htmlspecialchars($rd['kpp']):'');
  if (!empty($rd['ogrn']))  $sr[] = 'ОГРН: '.htmlspecialchars($rd['ogrn']);
  if (!empty($rd['usci']))  $sr[] = 'USCC / 统一社会信用代码: '.htmlspecialchars($rd['usci']);
  if (!empty($rd['legal'])) $sr[] = 'Представитель / 法定代表人: '.htmlspecialchars($rd['legal']);
  if (!empty($rd['address']))$sr[]= 'Адрес / 地址: '.htmlspecialchars($rd['address']);
  if (!empty($rd['bank']))  $sr[] = 'Банк / 开户行: '.htmlspecialchars($rd['bank']);
  if (!empty($rd['account']))$sr[]= 'Счёт / 账号: '.htmlspecialchars($rd['account']);
  if (!empty($rd['bik']))   $sr[] = 'БИК: '.htmlspecialchars($rd['bik']);
  if (!empty($rd['swift'])) $sr[] = 'SWIFT: '.htmlspecialchars($rd['swift']);
  $srHtml = implode('<br>', $sr);
  $buyerRows = implode('<br>', array_map('htmlspecialchars', $buyer['rows']));
  $sealBuyer = itc_seal_html($seals, $buyer['seal']);
  $secs = [
    ['1. Предмет договора','第一条 合同标的',
     'Продавец обязуется передавать в собственность Покупателя товар (мебель, комплектующие, сантехника и иные товары) партиями, а Покупатель — принимать и оплачивать его. Наименование, количество и цена согласуются в спецификациях/инвойсах на каждую партию.',
     '卖方应分批向买方交付货物（家具、配件、卫浴及其他货物）的所有权，买方应接收并付款。每批货物的名称、数量及价格在规格书/发票中约定。'],
    ['2. Цена и оплата','第二条 价格与付款',
     'Цены указываются в спецификациях/инвойсах в китайских юанях (CNY). Оплата — банковским переводом. Момент оплаты (предоплата / по поступлению на склад / по факту получения) определяется отдельно и указывается в спецификации.',
     '价格以人民币（CNY）在规格书/发票中列明。付款方式为银行转账。付款时点（预付款/到仓付款/收货后付款）另行约定并在规格书中注明。'],
    ['3. Поставка','第三条 交货',
     'Поставка партиями на условиях, согласованных в спецификации (Инкотермс 2020). Отгрузка со склада Продавца в КНР с доставкой на склад Покупателя.',
     '按规格书约定的条件（2020年国际贸易术语通则）分批交货。货物自卖方在华仓库发出并运至买方仓库。'],
    ['4. Качество','第四条 质量',
     'Качество товара должно соответствовать образцам и техническим характеристикам. Продавец гарантирует, что товар свободен от прав третьих лиц.',
     '货物质量应符合样品及技术规格。卖方保证货物不存在第三方权利。'],
    ['5. Форс-мажор','第五条 不可抗力',
     'Стороны освобождаются от ответственности при обстоятельствах непреодолимой силы, возникших после заключения договора.',
     '因合同订立后发生的不可抗力，双方免除责任。'],
    ['6. Применимое право и споры','第六条 适用法律与争议',
     'К договору применяется материальное право РФ. Споры — в МКАС при ТПП РФ (г. Москва).',
     '本合同适用俄罗斯联邦实体法。争议提交俄罗斯联邦工商会国际商事仲裁院（莫斯科）。'],
    ['7. Срок действия','第七条 有效期',
     'Договор вступает в силу с даты подписания и действует до 31 декабря следующего года с автопродлением на год, если ни одна сторона не заявит о прекращении.',
     '本合同自签署之日起生效，有效期至次年12月31日，如无一方声明终止则自动顺延一年。'],
  ];
  $secRows = '';
  foreach ($secs as $x) {
    $secRows .= '<tr><td><b>'.$x[0].'</b><br>'.$x[2].'</td><td><b>'.$x[1].'</b><br>'.$x[3].'</td></tr>';
  }
  $css = 'body{font-family:"Times New Roman",Georgia,serif;font-size:13px;color:#111;margin:24px;line-height:1.4}'
       . 'h1{text-align:center;font-size:18px;margin:0}.sub{text-align:center;color:#555;margin:2px 0 16px}'
       . 'table{width:100%;border-collapse:collapse}td{border:1px solid #bbb;padding:8px;vertical-align:top;width:50%}'
       . '.req td{width:50%}.noprint{margin:16px 0}@media print{.noprint{display:none}}'
       . 'button{padding:10px 16px;font-size:14px;border:0;border-radius:8px;background:#112C93;color:#fff;cursor:pointer}';
  $html = '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Договор '.$no.'</title><style>'.$css.'</style></head><body>'
    . '<div class="noprint"><button onclick="window.print()">🖨 Скачать / печать в PDF</button></div>'
    . '<h1>ДОГОВОР ПОСТАВКИ № '.$no.'</h1><div class="sub">供货合同 № '.$no.' · '.$date.'</div>'
    . '<table><tr><td>Настоящий договор заключён между Покупателем — <b>'.$buyer['ru'].'</b> и Продавцом — <b>'.$sname.'</b>'.($szh?' ('.$szh.')':'').'.</td>'
    . '<td>本合同由买方 <b>'.$buyer['zh'].'</b> 与卖方 <b>'.($szh?:$sname).'</b> 签订。</td></tr>'
    . $secRows . '</table>'
    . '<table style="margin-top:16px" class="req"><tr>'
    . '<td><b>ПОКУПАТЕЛЬ / 买方</b><br>'.$buyer['ru'].'<br>'.$buyerRows.'<br><br>Подпись и печать / 签章:<br>'.$sealBuyer.'</td>'
    . '<td><b>ПРОДАВЕЦ / 卖方</b><br>'.$sname.($szh?' / '.$szh:'').'<br>'.$srHtml.'<br><br>Подпись и печать / 签章:<br><span style="color:#999">(поставьте свою печать / 请盖章)</span></td>'
    . '</tr></table></body></html>';
  return $html;
}

