// ЭТАП 3: документы партии (спецификация / инвойс / упаковочный лист)
function batch_doc_html($type, $batch, $sup, $items, $seals) {
  $payCo = ($sup['pay_company'] === 'jinjia') ? 'jinjia' : 'itk';
  $buyer = itc_buyer_reqs($payCo);
  $no = htmlspecialchars($batch['batch_no'] ?: $batch['id']);
  $date = date('d.m.Y', strtotime($batch['created_at'] ?: 'now'));
  $sname = htmlspecialchars($sup['name'] ?: '');
  $szh = htmlspecialchars($sup['zh'] ?: '');
  $rd = json_decode($sup['reg_data'] ?: '{}', true) ?: [];
  $titles = ['spec'=>'Спецификация / 规格书','invoice'=>'Инвойс · Invoice / 发票','packing'=>'Упаковочный лист · Packing List / 装箱单'];
  $ttl = $titles[$type] ?? $titles['spec'];
  $isPack = ($type === 'packing');
  $rowsHtml=''; $totCny=0; $totQty=0; $totW=0; $totV=0; $totBoxes=0; $i=1;
  foreach ($items as $it) {
    $qty=(int)$it['qty']; $cny=(float)$it['goods_cny']; $w=(float)$it['weight_kg']; $v=(float)$it['volume_m3']; $ppb=(int)$it['pcs_per_box'];
    $sum=$qty*$cny; $rw=$qty*$w; $rv=$qty*$v; $boxes=($ppb>0)?(int)ceil($qty/$ppb):0;
    $totCny+=$sum; $totQty+=$qty; $totW+=$rw; $totV+=$rv; $totBoxes+=$boxes;
    if ($isPack) {
      $rowsHtml.='<tr><td>'.$i.'</td><td>'.htmlspecialchars($it['name']).'</td><td class="c">'.$qty.'</td><td class="c">'.($boxes?:'—').'</td><td class="c">'.round($rw,2).'</td><td class="c">'.round($rv,4).'</td></tr>';
    } else {
      $rowsHtml.='<tr><td>'.$i.'</td><td>'.htmlspecialchars($it['name']).'</td><td class="c">'.$qty.'</td><td class="c">'.number_format($cny,2,'.',' ').'</td><td class="c">'.number_format($sum,2,'.',' ').'</td></tr>';
    }
    $i++;
  }
  if ($isPack) {
    $thead='<tr><th>№</th><th>Товар / 商品</th><th>Кол-во / 数量</th><th>Мест / 件数</th><th>Вес кг / 重量</th><th>Объём м³ / 体积</th></tr>';
    $tfoot='<tr class="tot"><td colspan="2">ИТОГО / 合计</td><td class="c">'.$totQty.'</td><td class="c">'.$totBoxes.'</td><td class="c">'.round($totW,2).'</td><td class="c">'.round($totV,4).'</td></tr>';
  } else {
    $thead='<tr><th>№</th><th>Товар / 商品</th><th>Кол-во / 数量</th><th>Цена CNY / 单价</th><th>Сумма CNY / 金额</th></tr>';
    $tfoot='<tr class="tot"><td colspan="2">ИТОГО / 合计</td><td class="c">'.$totQty.'</td><td></td><td class="c">'.number_format($totCny,2,'.',' ').' ¥</td></tr>';
  }
  $sealBuyer = itc_seal_html($seals, $buyer['seal']);
  $css='body{font-family:"Times New Roman",Georgia,serif;font-size:12px;color:#111;margin:22px;line-height:1.35}'
     .'h1{text-align:center;font-size:16px;margin:0 0 2px}.sub{text-align:center;color:#555;margin:0 0 14px}'
     .'.hdr{display:flex;justify-content:space-between;gap:12px;margin-bottom:10px;font-size:12px}'
     .'table.g{width:100%;border-collapse:collapse;margin-top:6px}table.g th,table.g td{border:1px solid #999;padding:5px 7px}'
     .'table.g th{background:#eef1fb}.c{text-align:center}.tot{font-weight:bold;background:#f7f7f7}'
     .'.sign{display:flex;justify-content:space-between;margin-top:22px;gap:20px;font-size:12px}'
     .'.noprint{margin:14px 0}@media print{.noprint{display:none}}button{padding:10px 16px;border:0;border-radius:8px;background:#112C93;color:#fff;cursor:pointer;font-size:14px}';
  $money = $isPack ? '' : ('<div style="margin-top:8px;font-size:13px"><b>Итого к оплате поставщику / 应付卖方: '.number_format($totCny,2,'.',' ').' CNY (¥)</b></div>');
  $html='<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$ttl.' '.$no.'</title><style>'.$css.'</style></head><body>'
    .'<div class="noprint"><button onclick="window.print()">🖨 Скачать / печать в PDF</button></div>'
    .'<h1>'.$ttl.'</h1><div class="sub">№ '.$no.' · '.$date.'</div>'
    .'<div class="hdr"><div><b>Продавец / 卖方:</b><br>'.$sname.($szh?' / '.$szh:'').(!empty($rd['address'])?'<br>'.htmlspecialchars($rd['address']):'').'</div>'
    .'<div style="text-align:right"><b>Покупатель / 买方:</b><br>'.$buyer['ru'].'</div></div>'
    .'<table class="g"><thead>'.$thead.'</thead><tbody>'.$rowsHtml.$tfoot.'</tbody></table>'.$money
    .'<div class="sign"><div><b>Продавец / 卖方</b><br><br>______________ / '.$sname.'<br><span style="color:#999">(печать·подпись / 签章)</span></div>'
    .'<div style="text-align:right"><b>Покупатель / 买方</b><br>'.$sealBuyer.'</div></div>'
    .'</body></html>';
  return $html;
}

