// ЭТАП 5: управляемые поставщики
function current_staff_id($s) {
  $ph = $s['phone'] ?? '';
  if (!$ph) return '';
  try { $q = db()->prepare("SELECT id FROM staff WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') LIMIT 1"); $q->execute([$ph]); return (string)$q->fetchColumn(); }
  catch (Exception $e) { return ''; }
}
// Человеко-читаемое имя того, кто завёл карточку (для счётчика эффективности).
function creator_label($s) {
  static $cache = [];
  $ph = $s['phone'] ?? '';
  if (isset($cache[$ph])) return $cache[$ph];
  $label = '';
  try { $q = db()->prepare("SELECT name FROM staff WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') LIMIT 1"); $q->execute([$ph]); $n = $q->fetchColumn(); if ($n) $label = (string)$n; }
  catch (Exception $e) {}
  if ($label === '') { $sr = $s['staff_role'] ?? ''; $label = ($sr === 'boss' || $sr === '') ? 'Босс' : ($ph ? ('Тел '.$ph) : 'Сотрудник'); }
  return $cache[$ph] = $label;
}
// Проставляем создателя карточке (не перезаписываем, если уже стоит).
function itc_store_b64_image($b64) {
  global $S3_ENABLED, $S3_PUBLIC_URL;
  if (!is_string($b64) || $b64 === '') return '';
  $pos = strpos($b64, 'base64,');
  if ($pos !== false) $b64 = substr($b64, $pos + 7);
  $bin = base64_decode($b64, true);
  if ($bin === false || strlen($bin) < 200) return '';
  if (strlen($bin) > 8 * 1024 * 1024) return '';
  $tmp = tempnam(sys_get_temp_dir(), 'pva');
  if (!$tmp) return '';
  @file_put_contents($tmp, $bin);
  if (@getimagesize($tmp) === false) { @unlink($tmp); return ''; }   // не картинка — не берём
  $ext = 'jpg'; $src = $tmp; $made = null;
  if (function_exists('ob_img_compress')) {
    $cp = ob_img_compress($tmp);
    if (!empty($cp['ok'])) { $src = $made = $cp['path']; $ext = $cp['ext']; }
  }
  $name = gen('pv') . '.' . $ext;
  $url = '';
  if ($S3_ENABLED && s3_put_object($name, $src, s3_content_type($ext))) {
    $url = rtrim($S3_PUBLIC_URL, '/') . '/' . $name;
  } else {
    $dir = __DIR__ . '/../uploads';
    if (!is_dir($dir)) @mkdir($dir, 0755, true);
    if (@copy($src, $dir . '/' . $name)) $url = '/uploads/' . $name;
  }
  @unlink($tmp); if ($made) @unlink($made);
  return $url;
}
// ===== Интересы покупателя =====
// Персональной истории просмотров в базе не было вообще: был только общий счётчик
// кликов на товаре. Без неё «показ по интересам» работал бы лишь для тех, кто уже
// покупал. Заводим лёгкий журнал событий: одна строка на просмотр карточки, поиск
// или добавление в корзину.
// ===== ФАБРИКА-ПРОИЗВОДИТЕЛЬ =====
// Поставщик у нас один — Jinjia, она закупает у разных фабрик. Разводить витрину
// надо по фабрике, а её название лежит далеко: products → ds_products.source_url
// → ob_item.detail_url → shop_name / seller_nick. Гонять этот двойной JOIN на
// каждой странице витрины по 32 000 товаров нельзя, поэтому название фабрики
// один раз переносим в саму карточку товара.
// Наша собственная запись поставщика. Карточки «от имени ИТК» привязываются к ней,
// иначе они висят вообще без поставщика и не попадают ни в один счётчик.
// Латиница из русского названия — для кода точки вроде «ЯЛТ» → «YAL»
// Журнал пересчёта цен после замера на складе
function recalc_log_ensure() {
  static $d = false; if ($d) return; $d = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS price_recalc (
    id INT AUTO_INCREMENT PRIMARY KEY,
    procurement_id VARCHAR(64), product_id VARCHAR(64), ds_id VARCHAR(64),
    old_rub INT, new_rub INT, diff_rub INT, diff_pct INT,
    weight_kg DECIMAL(10,2), volume_m3 DECIMAL(10,4),
    source_order_id VARCHAR(64), by_phone VARCHAR(40),
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_prod (product_id)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); } catch (Exception $e) {}
}
function translit_ru($t) {
  $m = ['а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d','е'=>'e','ё'=>'e','ж'=>'zh','з'=>'z','и'=>'i',
        'й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t',
        'у'=>'u','ф'=>'f','х'=>'h','ц'=>'c','ч'=>'ch','ш'=>'sh','щ'=>'sch','ъ'=>'','ы'=>'y','ь'=>'',
        'э'=>'e','ю'=>'yu','я'=>'ya'];
  $t = mb_strtolower(trim((string)$t));
  $out = '';
  $len = mb_strlen($t);
  for ($i=0; $i<$len; $i++) {
    $ch = mb_substr($t,$i,1);
    $out .= isset($m[$ch]) ? $m[$ch] : $ch;
  }
  return $out;
}
function itc_own_supplier_ensure() {
  static $done = false;
  if ($done) return; $done = true;
  try { db()->query("ALTER TABLE suppliers ADD COLUMN is_own TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
}
function itc_own_supplier_id() {
  itc_own_supplier_ensure();
  try { $r = db()->query("SELECT id FROM suppliers WHERE is_own=1 ORDER BY created_at LIMIT 1")->fetch();
        if ($r && !empty($r['id'])) return $r['id']; } catch (Exception $e) {}
  return '';
}
/* Колонки products спрашиваем ОДИН раз за запрос и запоминаем: этим списком
   пользуются и подготовка схемы, и сборка витрины. */
/* ===== ПОЛНОТЕКСТОВЫЙ ПОИСК ПО НАЗВАНИЯМ =====
   Поиск куска слова внутри текста база ускорить не умеет: замер показал 408 мс
   на 35 тысячах, когда слово РЕДКОЕ и остановиться раньше времени нельзя. На
   полумиллионе это около шести секунд. Полнотекстовый индекс устроен наоборот:
   в нём хранится список слов и номера карточек, где каждое встречается — искать
   по нему всё равно что искать слово в алфавитном указателе книги, а не читать
   книгу целиком. Время перестаёт зависеть от размера каталога.
   Индекс намеренно НЕ включает описание: оно тяжёлое, а искать по нему почти
   не приходится — название, теги и подкатегория покрывают запросы. */
/* №328 · Как ещё называются товары по запросу покупателя — ответ DeepSeek, общий кэш на 30 дней.
   $ask=false — только посмотреть в кэше (null, если там нет). Пустой ответ кэшируем на 10 минут,
   чтобы при сбое DeepSeek не спрашивать на каждое нажатие. */
function itc_ai_terms($q, $ask) {
  $qn = mb_strtolower(trim(preg_replace('/\s+/u', ' ', $q)));
  if ($qn === '' || mb_strlen($qn) > 120 || !function_exists('itcai_ask')) return null;
  $key = md5('st1|' . $qn);
  $c = itcai_cache_get('st', $key, 86400 * 30);
  if (is_array($c)) { if (!empty($c['t'])) return $c['t']; if (($c['at'] ?? 0) > time() - 600) return []; }
  if (!$ask) return null;
  $sys = "Ты помогаешь поиску интернет-магазина товаров из Китая (электроника, дом, инструмент, одежда, мебель, автотовары и др.). "
       . "Покупатель написал запрос. Верни ТОЛЬКО JSON {\"t\": [...]} — 8–20 слов и коротких фраз в нижнем регистре, "
       . "которыми такие товары называются в каталоге: синонимы, конкретные виды товара, английские названия, разговорные варианты. "
       . "Слова давай корнями без окончаний, чтобы ловить склонения. Если запрос — описание задачи («для кемпинга», «подарок папе»), "
       . "назови конкретные товары. Пример: «аккумулятор» → [\"аккумулятор\",\"повербанк\",\"power bank\",\"внешний аккумулятор\",\"батаре\",\"lifepo4\",\"li-ion\",\"элемент питания\"].";
  $j = itcai_json(itcai_ask($sys, $q, 300, 8, true));
  $t = [];
  foreach ((array)($j['t'] ?? []) as $w) { $w = mb_strtolower(trim((string)$w)); if (mb_strlen($w) >= 3 && mb_strlen($w) <= 40) $t[] = $w; }
  $t = array_slice(array_values(array_unique($t)), 0, 20);
  itcai_cache_put('st', $key, ['t' => $t, 'at' => time()]);
  return $t;
}

function itc_ft_cols() { return ['name', 'search_tags', 'subcat', 'material']; }
function itc_ft_exists() {
  try {
    $n = (int)db()->query("SELECT COUNT(*) FROM information_schema.statistics
                           WHERE table_schema = DATABASE() AND table_name = 'products'
                             AND index_name = 'idx_prod_ft'")->fetchColumn();
    return $n > 0;
  } catch (Exception $e) { return false; }
}
function itc_ft_ready($set = null) {
  try {
    db()->query("CREATE TABLE IF NOT EXISTS itc_cnt_cache (
      k VARCHAR(120) NOT NULL PRIMARY KEY, v INT NOT NULL, ts DATETIME NOT NULL
    ) DEFAULT CHARSET=utf8mb4");
    if ($set !== null) {
      db()->prepare('REPLACE INTO itc_cnt_cache (k,v,ts) VALUES (?,?,NOW())')->execute(['ft_ready', $set ? 1 : 0]);
      return (bool)$set;
    }
    $v = db()->query("SELECT v FROM itc_cnt_cache WHERE k='ft_ready'")->fetchColumn();
    return $v !== false && (int)$v === 1;
  } catch (Exception $e) { return false; }
}
/* Слова запроса в вид, понятный полнотекстовому поиску. Окончание обрезаем и
   ставим звёздочку — так «столы» находит «стол» и «столик».
   ОСТОРОЖНО С ДЛИНОЙ. Сначала я резал по две буквы у всего от пяти букв, и
   «столы» превращалось в «сто» — а звёздочка после трёх букв ловит «стойку»,
   «столешницу», «сток». Поиск «Столы» показывал сушилки. Поэтому у коротких
   слов режем только одну букву. */
function itc_ft_terms($words) {
  $out = [];
  foreach ((array)$words as $w) {
    $t = preg_replace('/[^\p{L}\p{N}]/u', '', mb_strtolower((string)$w));
    if ($t === '' || $t === null) continue;
    $n = mb_strlen($t);
    if ($n >= 7)      $t = mb_substr($t, 0, $n - 2);
    elseif ($n >= 5)  $t = mb_substr($t, 0, $n - 1);
    if (mb_strlen($t) < 3) continue;   // короче трёх букв полнотекстовый поиск не индексирует
    $out[] = $t;
  }
  return array_values(array_unique($out));
}
function itc_products_columns() {
  static $cols = null;
  if ($cols !== null) return $cols;
  $cols = [];
  try { foreach (db()->query("SHOW COLUMNS FROM products")->fetchAll() as $c) $cols[$c['Field']] = 1; }
  catch (Exception $e) {}
  return $cols;
}
/* РАЗБОР ВЫДАЧИ БЕЗ ОКОННЫХ ФУНКЦИЙ.
   Одна модель лежит в базе десятком почти одинаковых карточек, а товары одной
   фабрики идут пачками подряд. Раньше и то и другое разбирали оконные функции
   ПО ВСЕЙ ВИТРИНЕ — замер показал 550 мс на 35 тысячах, то есть около восьми
   секунд на полумиллионе. Теперь база отдаёт несколько сотен строк по индексу,
   а разбор идёт здесь: от семейства оставляем одну карточку и раскладываем по
   фабрикам «по кругу». На трёхстах строках это доли миллисекунды и, главное,
   не зависит от размера каталога. */
/* ПЕРЕМЕШИВАНИЕ ВЫДАЧИ.
   В отличие от itc_strip_spread здесь НИЧЕГО НЕ ВЫБРАСЫВАЕТСЯ: варианты одного
   товара — это разные размеры и цены, покупателю они нужны. Плохо только то,
   что они идут подряд десятками одинаковых картинок. Поэтому раскладываем «по
   кругу» на двух уровнях: сперва чередуем фабрики, внутри фабрики чередуем
   карточки одной модели. Соседями одинаковые картинки уже не окажутся, а
   порядок по важности почти сохраняется — фабрики идут в том порядке, в каком
   встретился их лучший товар. */
function itc_mix_spread($rows, $limit = 0) {
  $byMaker = [];
  foreach ($rows as $r) {
    $m = trim((string)($r['factory'] ?? ''));
    if ($m === '') $m = (string)($r['supplier_id'] ?? '');
    $fam = mb_strtolower(mb_substr((string)($r['name'] ?? ''), 0, 40));
    if (!isset($byMaker[$m])) $byMaker[$m] = [];
    if (!isset($byMaker[$m][$fam])) $byMaker[$m][$fam] = [];
    $byMaker[$m][$fam][] = $r;
  }
  $out = [];
  while (true) {
    $moved = false;
    foreach (array_keys($byMaker) as $m) {
      /* Берём из САМОГО МНОГОЧИСЛЕННОГО семейства этой фабрики. Если брать по
         очереди, крупное семейство доживает до конца и вываливается хвостом из
         десятка одинаковых картинок подряд — ровно то, на что жаловались.
         А так оно растягивается по всей выдаче. */
      $best = null; $bestN = 0;
      foreach ($byMaker[$m] as $fk => $list) {
        $n = count($list);
        if ($n > $bestN) { $bestN = $n; $best = $fk; }
      }
      if ($best === null) { unset($byMaker[$m]); continue; }
      $out[] = array_shift($byMaker[$m][$best]);
      if (!count($byMaker[$m][$best])) unset($byMaker[$m][$best]);
      $moved = true;
      if ($limit && count($out) >= $limit) return $out;
    }
    if (!$moved) break;
  }
  return $out;
}
function itc_strip_spread($rows, $offset = 0, $limit = 12) {
  $seen = []; $keep = [];
  foreach ($rows as $r) {
    $fam = mb_strtolower(mb_substr((string)($r['name'] ?? ''), 0, 40));
    if ($fam !== '' && isset($seen[$fam])) continue;
    $seen[$fam] = true; $keep[] = $r;
  }
  $byMaker = [];
  foreach ($keep as $r) {
    $m = trim((string)($r['factory'] ?? ''));
    if ($m === '') $m = (string)($r['supplier_id'] ?? '');
    $byMaker[$m][] = $r;
  }
  $out = []; $need = $offset + $limit;
  while (count($out) < $need) {
    $moved = false;
    foreach ($byMaker as $m => $list) {
      if (!count($byMaker[$m])) continue;
      $out[] = array_shift($byMaker[$m]);
      $moved = true;
      if (count($out) >= $need) break;
    }
    if (!$moved) break;
  }
  return array_slice($out, $offset, $limit);
}
function itc_factory_ensure() {
  static $done = false;
  if ($done) return; $done = true;
  /* Раньше здесь на КАЖДЫЙ запрос витрины выполнялся ALTER, который всегда
     падал с ошибкой «колонка уже есть». Замер показал: 226 мс впустую на
     каждом открытии каталога. Теперь сначала смотрим схему и трогаем таблицу,
     только если колонки действительно нет. */
  $cols = itc_products_columns();
  if ($cols && isset($cols['factory'])) return;
  try { db()->query("ALTER TABLE products ADD COLUMN factory VARCHAR(200) NULL"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE products ADD INDEX idx_factory (factory)"); } catch (Exception $e) {}
}
/* ===== ФЛАГ ВИДИМОСТИ ТОВАРА =====
   Витрина отбирала товары четырьмя условиями, одно из которых — поиск куска
   текста внутри адреса картинки. Такое база вынуждена перебирать целиком:
   836 мс на 33 тысячах карточек, а впереди полмиллиона. Поэтому ответ считаем
   заранее и держим в колонке vis, по ней стоит индекс.

   Поддерживают флаг ТРИГГЕРЫ базы, а не наш код: мест, где меняется товар,
   почти восемьдесят, и вручную мы бы неизбежно что-то забыли. Триггер ловит
   любое изменение, откуда бы оно ни пришло. Если хостинг триггеры запрещает —
   остаётся ночная сверка, она же подчищает любые расхождения. */
function itc_vis_expr($p = '') {
  return "(CASE WHEN ({$p}blocked=0 OR {$p}blocked IS NULL)
                 AND ({$p}paused=0 OR {$p}paused IS NULL)
                 AND ({$p}mod_status='approved' OR {$p}mod_status='' OR {$p}mod_status IS NULL)
                 AND {$p}img IS NOT NULL AND {$p}img<>'' AND {$p}img NOT LIKE '%alicdn%'
            THEN 1 ELSE 0 END)";
}
function itc_vis_ensure() {
  static $done = false;
  if ($done) return; $done = true;
  $cols = itc_products_columns();
  if ($cols && !isset($cols['vis'])) {
    try { db()->query('ALTER TABLE products ADD COLUMN vis TINYINT NOT NULL DEFAULT 0'); } catch (Exception $e) {}
    try { db()->query('ALTER TABLE products ADD INDEX idx_prod_vis (vis, created_at)'); } catch (Exception $e) {}
  }
  // Триггеры создаём один раз; если уже есть или нет прав — просто идём дальше.
  $e = itc_vis_expr('NEW.');
  try { db()->query("CREATE TRIGGER trg_prod_vis_i BEFORE INSERT ON products FOR EACH ROW SET NEW.vis = $e"); } catch (Exception $ex) {}
  try { db()->query("CREATE TRIGGER trg_prod_vis_u BEFORE UPDATE ON products FOR EACH ROW SET NEW.vis = $e"); } catch (Exception $ex) {}
}
/* Есть ли триггеры на самом деле — по этому решаем, нужна ли частая сверка. */
function itc_vis_triggers_ok() {
  try {
    $n = (int)db()->query("SELECT COUNT(*) FROM information_schema.triggers
                           WHERE event_object_table='products' AND trigger_name LIKE 'trg_prod_vis%'")->fetchColumn();
    return $n >= 2;
  } catch (Exception $e) { return false; }
}
/* Пересчёт пачками. Трогаем только строки, где флаг разошёлся с правдой. */
function itc_vis_fill($limit = 20000) {
  itc_vis_ensure();
  $expr = itc_vis_expr('');
  $fixed = 0;
  try {
    $st = db()->prepare("UPDATE products SET vis = $expr WHERE vis <> $expr LIMIT ".(int)$limit);
    $st->execute();
    $fixed = $st->rowCount();
  } catch (Exception $e) {}
  return $fixed;
}
/* Сколько строк ещё расходится — ноль означает, что флаг можно использовать. */
function itc_vis_wrong() {
  $expr = itc_vis_expr('');
  try { return (int)db()->query("SELECT COUNT(*) FROM products WHERE vis <> $expr")->fetchColumn(); }
  catch (Exception $e) { return -1; }
}
/* Витрина переходит на флаг только после полного заполнения — иначе покупатель
   увидел бы пустой каталог. Отметку держим в том же кэше счётчиков. */
function itc_vis_ready($set = null) {
  try {
    db()->query("CREATE TABLE IF NOT EXISTS itc_cnt_cache (
      k VARCHAR(120) NOT NULL PRIMARY KEY, v INT NOT NULL, ts DATETIME NOT NULL
    ) DEFAULT CHARSET=utf8mb4");
    if ($set !== null) {
      db()->prepare('REPLACE INTO itc_cnt_cache (k,v,ts) VALUES (?,?,NOW())')->execute(['vis_ready', $set ? 1 : 0]);
      return (bool)$set;
    }
    $v = db()->query("SELECT v FROM itc_cnt_cache WHERE k='vis_ready'")->fetchColumn();
    return $v !== false && (int)$v === 1;
  } catch (Exception $e) { return false; }
}

/* Счёт товаров для витрины. Условие видимости содержит NOT LIKE по картинке,
   а такое база вынуждена перебирать целиком: замер показал 989 мс на каждой
   странице каталога. Число меняется редко, поэтому держим его в кэше. */
function itc_count_cached($key, $sql, $args, $ttl = 300) {
  static $ready = false;
  $ttl = (int)$ttl;
  try {
    if (!$ready) {
      db()->query("CREATE TABLE IF NOT EXISTS itc_cnt_cache (
        k VARCHAR(120) NOT NULL PRIMARY KEY, v INT NOT NULL, ts DATETIME NOT NULL
      ) DEFAULT CHARSET=utf8mb4");
      $ready = true;
    }
    $q = db()->prepare("SELECT v FROM itc_cnt_cache WHERE k=? AND ts > (NOW() - INTERVAL {$ttl} SECOND)");
    $q->execute([$key]);
    $v = $q->fetchColumn();
    if ($v !== false && $v !== null) return (int)$v;
  } catch (Exception $e) {}
  $n = 0;
  try { $c = db()->prepare($sql); $c->execute($args); $n = (int)$c->fetchColumn(); } catch (Exception $e) {}
  try { db()->prepare('REPLACE INTO itc_cnt_cache (k,v,ts) VALUES (?,?,NOW())')->execute([$key, $n]); } catch (Exception $e) {}
  return $n;
}
// Проставляет фабрику там, где её ещё нет. Возвращает, сколько заполнено и сколько осталось.
// Проставляет фабрику там, где её ещё нет. Возвращает, сколько заполнено и сколько осталось.
// MySQL не разрешает LIMIT в UPDATE с JOIN, поэтому сперва выбираем пачку, потом
// обновляем группами: у фабрик мало разных названий, выходит несколько запросов.
function itc_factory_fill($limit = 2000) {
  itc_factory_ensure();
  $limit = max(1, min(20000, (int)$limit));
  $pairs = [];
  try {
    $q = db()->query("SELECT p.id, LEFT(COALESCE(NULLIF(TRIM(i.shop_name),''), TRIM(i.seller_nick)),200) f
                        FROM products p
                        JOIN ds_products dp ON dp.product_id = p.id
                        JOIN ob_item i      ON i.detail_url  = dp.source_url
                       WHERE (p.factory IS NULL OR p.factory = '')
                         AND COALESCE(NULLIF(TRIM(i.shop_name),''), TRIM(i.seller_nick)) <> ''
                       LIMIT $limit");
    $pairs = $q->fetchAll();
  } catch (Exception $e) { return ['ok' => false, 'error' => $e->getMessage()]; }

  $byFactory = [];
  foreach ($pairs as $r) { $byFactory[$r['f']][] = $r['id']; }
  $done = 0;
  foreach ($byFactory as $fname => $ids) {
    foreach (array_chunk($ids, 500) as $chunk) {
      $ph = implode(',', array_fill(0, count($chunk), '?'));
      try {
        $st = db()->prepare("UPDATE products SET factory=? WHERE id IN ($ph)");
        $st->execute(array_merge([$fname], $chunk));
        $done += $st->rowCount();
      } catch (Exception $e) {}
    }
  }
  $left = 0;
  try { $left = (int)db()->query("SELECT COUNT(*) c FROM products p
                                    JOIN ds_products dp ON dp.product_id = p.id
                                    JOIN ob_item i      ON i.detail_url  = dp.source_url
                                   WHERE (p.factory IS NULL OR p.factory = '')
                                     AND COALESCE(NULLIF(TRIM(i.shop_name),''), TRIM(i.seller_nick)) <> ''")->fetch()['c']; }
  catch (Exception $e) {}
  $facts = 0;
  try { $facts = (int)db()->query("SELECT COUNT(DISTINCT factory) c FROM products WHERE factory IS NOT NULL AND factory<>''")->fetch()['c']; }
  catch (Exception $e) {}
  return ['ok' => true, 'done' => $done, 'left' => $left, 'fabrik_vsego' => $facts];
}
function itc_events_ensure() {
  static $done = false;
  if ($done) return; $done = true;
  try {
    db()->query("CREATE TABLE IF NOT EXISTS user_events (
      id BIGINT AUTO_INCREMENT PRIMARY KEY,
      uid VARCHAR(64) NOT NULL,
      kind VARCHAR(16) NOT NULL,
      product_id VARCHAR(32) NULL,
      cat VARCHAR(120) NULL,
      q VARCHAR(160) NULL,
      created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
      KEY k_uid (uid, created_at),
      KEY k_cat (uid, cat)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  } catch (Exception $e) {}
}
// Топ-категории покупателя: что смотрел за 90 дней плюс что покупал (покупка весит больше).
function itc_user_cats($uid, $limit = 6) {
  $uid = trim((string)$uid);
  if ($uid === '') return [];
  itc_events_ensure();
  $w = [];
  try {
    $q = db()->prepare("SELECT cat, COUNT(*) c FROM user_events
                        WHERE uid=? AND cat IS NOT NULL AND cat<>'' AND created_at > DATE_SUB(NOW(), INTERVAL 90 DAY)
                        GROUP BY cat ORDER BY c DESC LIMIT 20");
    $q->execute([$uid]);
    foreach ($q->fetchAll() as $r) $w[$r['cat']] = ($w[$r['cat']] ?? 0) + (int)$r['c'];
  } catch (Exception $e) {}
  // покупки — сигнал сильнее просмотра
  try {
    $q2 = db()->prepare("SELECT p.cat, COUNT(*) c FROM order_items i
                         JOIN orders o ON o.id=i.order_id
                         JOIN products p ON p.id=i.product_id
                         WHERE (o.phone=? OR o.user_id=?) AND p.cat IS NOT NULL AND p.cat<>''
                         GROUP BY p.cat");
    $q2->execute([$uid, $uid]);
    foreach ($q2->fetchAll() as $r) $w[$r['cat']] = ($w[$r['cat']] ?? 0) + 5 * (int)$r['c'];
  } catch (Exception $e) {}
  if (!$w) return [];
  arsort($w);
  return array_slice(array_keys($w), 0, $limit);
}
function stamp_creator($pid, $s) {
  if (!$pid) return;
  try { db()->prepare("UPDATE products SET created_by=? WHERE id=? AND (created_by IS NULL OR created_by='')")->execute([creator_label($s), $pid]); }
  catch (Exception $e) {}
}
function staff_is_boss($s) { $sr = $s['staff_role'] ?? ''; return ($sr === 'boss' || $sr === ''); }
function staff_can_see_all($s) { $sr = $s['staff_role'] ?? ''; return ($sr === 'boss' || $sr === '' || $sr === 'supervisor'); }

