// ===== Акции: пересчёт производного поля products.promo_until =====
// Товар в акции до самой поздней даты среди всех живых акций, где он числится.
function promo_touch_product($pid) {
  $pid = trim((string)$pid); if ($pid === '') return;
  try {
    $q = db()->prepare("SELECT MAX(p.ends_at) FROM promo_items i JOIN promos p ON p.id=i.promo_id
                        WHERE i.product_id=? AND p.status<>'deleted' AND p.ends_at > NOW()");
    $q->execute([$pid]);
    $until = $q->fetchColumn();
    if ($until) db()->prepare("UPDATE products SET promo_until=? WHERE id=?")->execute([$until, $pid]);
    else        db()->prepare("UPDATE products SET promo_until=NULL WHERE id=?")->execute([$pid]);
  } catch (Exception $e) { /* колонки может ещё не быть */ }
}
function promo_sync_products($promoId) {
  $promoId = trim((string)$promoId); if ($promoId === '') return;
  try {
    $q = db()->prepare("SELECT product_id FROM promo_items WHERE promo_id=?");
    $q->execute([$promoId]);
    foreach ($q->fetchAll() as $r) promo_touch_product($r['product_id']);
  } catch (Exception $e) {}
}

// ===== Вызов DaData (открытые реестры: банки по БИК, компании и ИП по ИНН) =====
function dadata_token() {
  try { $q=db()->prepare("SELECT v FROM settings WHERE k='dadata_token'"); $q->execute(); return trim((string)$q->fetchColumn()); }
  catch (Exception $e) { return ''; }
}
/* ===== КООРДИНАТЫ ТОЧЕК =====
   Координаты берём у DaData, а не у Яндекс-геокодера: у Яндекса полученные
   данные ЗАПРЕЩЕНО сохранять, их можно только показать на карте и забыть.
   DaData берёт координаты из OpenStreetMap и хранить их разрешает — значит
   считаем один раз при заведении точки и держим у себя. Показывать эти точки
   на карте Яндекса при этом можно. */
function itc_wh_geo_ensure() {
  static $done = false;
  if ($done) return;
  $done = true;
  try { db()->query("ALTER TABLE warehouses ADD COLUMN lat DECIMAL(10,7) NULL"); } catch (Exception $e) {}
  try { db()->query("ALTER TABLE warehouses ADD COLUMN lon DECIMAL(10,7) NULL"); } catch (Exception $e) {}
}
/* КООРДИНАТЫ САМИ ПО АДРЕСУ (обновление №264).
   Раньше координаты считались только по кнопке «Определить координаты всем
   сразу». Точка, заведённая из одобренной заявки или с изменённым адресом,
   оставалась без координат — и молча пропадала с карты пунктов выдачи.
   Теперь это вызывается само при каждом сохранении адреса.
   $force = пересчитать даже если координаты уже есть (адрес сменился).
   Метку, поставленную вручную (geo_manual=1), не трогаем никогда.
   Ошибки справочника не роняют сохранение: не нашли — точка просто без метки. */
function itc_wh_autogeo($id, $force = false) {
  $id = trim((string)$id);
  if ($id === '') return null;
  try {
    itc_wh_geo_ensure();
    try { db()->query("ALTER TABLE warehouses ADD COLUMN geo_manual TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
    $q = db()->prepare('SELECT id,city,address,lat,lon,geo_manual FROM warehouses WHERE id=?');
    $q->execute([$id]);
    $w = $q->fetch();
    if (!$w) return null;
    if ((int)($w['geo_manual'] ?? 0) === 1) return null;
    if (!$force && $w['lat'] !== null && $w['lon'] !== null) return null;
    $addr = trim(trim((string)($w['city'] ?? '')).' '.trim((string)($w['address'] ?? '')));
    if ($addr === '') return null;
    $g = itc_geocode($addr);
    if (!$g) return null;
    db()->prepare('UPDATE warehouses SET lat=?, lon=? WHERE id=?')->execute([$g['lat'], $g['lon'], $id]);
    return $g;
  } catch (Exception $e) { return null; }
}
/* Координаты по адресу. Возвращает [lat, lon, точность] или null. */
/* ===== ССЫЛКА 1688 ИЗ ТЕЛЕФОНА → ОБЫЧНАЯ ССЫЛКА НА ТОВАР (обновление №213) =====
   С телефона приложение 1688 делится не адресом товара, а целым куском текста
   с иероглифами, кодом вида ￥2CGWAwf30V4aa￥ и короткой ссылкой
   https://qr.1688.com/s/XXXXXX. Импорт такого не понимал и отвечал ошибкой —
   менеджеру приходилось открывать товар на компьютере и копировать адрес там.
   Здесь приводим что угодно к виду detail.1688.com/offer/<номер>.html:
   выдёргиваем ссылку из текста, разворачиваем короткую по переадресации,
   вытаскиваем номер товара. Если развернуть не вышло — возвращаем как было,
   и импорт ответит своей обычной ошибкой. */
function itc_1688_pick_id($text) {
  $t = (string)$text;
  /* Прямой вид: .../offer/1058158736933.html или offerId=1058158736933 */
  if (preg_match('~offer[/=](\d{6,20})~i', $t, $m)) return $m[1];
  if (preg_match('~["\']?(?:offerId|offer_id|num_iid)["\']?\s*[:=]\s*["\']?(\d{6,20})~i', $t, $m)) return $m[1];
  /* ЗАКОДИРОВАННЫЙ ВИД — так его прячет короткая ссылка.
     Страница qr.1688.com отдаёт заглушку, а настоящий адрес лежит внутри неё
     в рамке для приложения: wireless1688://…plugin?url=https%3A%2F%2Fm.1688.com
     %2Foffer%2F1058158736933.html%3F… Косые чёрточки там записаны как %2F,
     поэтому обычный поиск «offer/» его не видит. Раскрываем и ищем снова. */
  if (preg_match('~offer%2F(\d{6,20})~i', $t, $m)) return $m[1];
  $dec = @rawurldecode($t);
  if ($dec !== '' && $dec !== $t) {
    if (preg_match('~offer[/=](\d{6,20})~i', $dec, $m)) return $m[1];
    if (preg_match('~["\']?(?:offerId|offer_id|num_iid)["\']?\s*[:=]\s*["\']?(\d{6,20})~i', $dec, $m)) return $m[1];
  }
  return '';
}
function itc_1688_follow($url, $depth = 0) {
  if ($depth > 4) return ['url' => $url, 'body' => ''];
  $ch = @curl_init($url);
  if (!$ch) return ['url' => $url, 'body' => ''];
  curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_FOLLOWLOCATION => true,
    CURLOPT_MAXREDIRS      => 5,
    CURLOPT_TIMEOUT        => 12,
    CURLOPT_SSL_VERIFYPEER => false,
    // Мобильный «представитель»: короткие ссылки отдают телефонную страницу,
    // а с обычным настольным заголовком часто уводят на заглушку приложения.
    CURLOPT_USERAGENT      => 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1',
  ]);
  $body  = curl_exec($ch);
  $final = (string)curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
  curl_close($ch);
  return ['url' => ($final !== '' ? $final : $url), 'body' => (string)$body];
}
function itc_1688_normalize($raw) {
  $raw = trim((string)$raw);
  if ($raw === '') return '';

  // Один номер товара — этого достаточно
  if (preg_match('~^\d{6,20}$~', $raw)) return 'https://detail.1688.com/offer/'.$raw.'.html';

  // Номер прямо в тексте ссылки
  $id = itc_1688_pick_id($raw);
  if ($id !== '') return 'https://detail.1688.com/offer/'.$id.'.html';

  // Достаём ссылку из присланного куска текста
  $url = '';
  if (preg_match('~https?://[^\s"\'<>）\)]+~u', $raw, $m)) $url = rtrim($m[0], '.,;');
  if ($url === '') return $raw;

  // Короткая ссылка — разворачиваем по переадресации
  if (preg_match('~(qr\.1688\.com|m\.tb\.cn|qr\.alibaba\.com|1688\.com/s/)~i', $url)) {
    $r  = itc_1688_follow($url);
    $id = itc_1688_pick_id($r['url']);
    if ($id === '' && $r['body'] !== '') $id = itc_1688_pick_id($r['body']);
    if ($id !== '') return 'https://detail.1688.com/offer/'.$id.'.html';
    return $r['url'] !== '' ? $r['url'] : $url;
  }
  return $url;
}
/* ===== ОСНОВА БОНУСНОЙ ПРОГРАММЫ (обновление №220) =====
   Здесь только УЧЁТ: личный код, привязка приглашённого и подсчёт статистики.
   НАЧИСЛЕНИЙ ПОКА НЕТ — ждём ответа бухгалтера по налогам. Таблица движений
   заведена заранее, чтобы включить начисления одной правкой, не трогая
   структуру базы на работающем магазине. */
function itc_ref_ensure() {
  static $done = false;
  if ($done) return; $done = true;
  foreach ([
    "ALTER TABLE customers ADD COLUMN ref_code VARCHAR(16) NULL",
    "ALTER TABLE customers ADD COLUMN ref_by VARCHAR(16) NULL",
    "ALTER TABLE customers ADD COLUMN ref_by_at DATETIME NULL",
    "ALTER TABLE customers ADD UNIQUE KEY uniq_ref_code (ref_code)",
    "ALTER TABLE customers ADD KEY idx_ref_by (ref_by)",
  ] as $q) { try { db()->query($q); } catch (Exception $e) {} }
  try {
    /* КРАСНЫЕ КОНВЕРТЫ — отдельный счётчик, с общими бонусами не смешивается.
       Два срока: открыть за 7 дней, потратить за 30 дней после открытия.
       Оба храним датами, а не «сколько осталось»: считать остаток нужно на
       момент показа, иначе он застынет на числе, записанном при выдаче. */
    db()->query("CREATE TABLE IF NOT EXISTS itc_envelope (
      id BIGINT AUTO_INCREMENT PRIMARY KEY,
      phone VARCHAR(32) NOT NULL,
      amount DECIMAL(12,2) NOT NULL DEFAULT 0,
      status VARCHAR(12) NOT NULL DEFAULT 'new',   /* new · opened · spent · burned */
      reason VARCHAR(120) NULL,
      sent_at DATETIME NOT NULL,
      open_by DATETIME NOT NULL,
      opened_at DATETIME NULL,
      spend_by DATETIME NULL,
      order_id VARCHAR(40) NULL,
      KEY idx_env_phone (phone, status)
    ) DEFAULT CHARSET=utf8mb4");
  } catch (Exception $e) {}
  try {
    db()->query("CREATE TABLE IF NOT EXISTS itc_bonus (
      id BIGINT AUTO_INCREMENT PRIMARY KEY,
      phone VARCHAR(32) NOT NULL,
      kind VARCHAR(16) NOT NULL,          /* ref1 · ref2 · envelope */
      amount DECIMAL(12,2) NOT NULL DEFAULT 0,
      status VARCHAR(16) NOT NULL DEFAULT 'accrued',  /* accrued · available · spent · burned */
      order_id VARCHAR(40) NULL,
      from_phone VARCHAR(32) NULL,
      available_at DATETIME NULL,
      created_at DATETIME NOT NULL,
      KEY idx_bonus_phone (phone, status)
    ) DEFAULT CHARSET=utf8mb4");
  } catch (Exception $e) {}
}

/* Личный код клиента. Выдаём при первом обращении и больше не меняем:
   он уходит в QR и в ссылки, которые люди уже разослали. */
/* НАСТРОЙКА АВТОВЫДАЧИ КОНВЕРТА ЗА РЕГИСТРАЦИЮ (обновление №227).
   Отдельной таблицы настроек в проекте нет, заводим маленькую свою: пара
   «ключ — значение». Так же потом лягут и другие переключатели программы. */
function itc_set_get($k, $def = '') {
  try {
    db()->query("CREATE TABLE IF NOT EXISTS itc_settings (
      k VARCHAR(64) NOT NULL PRIMARY KEY, v VARCHAR(255) NULL, at DATETIME NULL
    ) DEFAULT CHARSET=utf8mb4");
    $q = db()->prepare('SELECT v FROM itc_settings WHERE k=? LIMIT 1');
    $q->execute([$k]);
    $v = $q->fetchColumn();
    return ($v === false || $v === null) ? $def : (string)$v;
  } catch (Exception $e) { return $def; }
}
function itc_set_put($k, $v) {
  try {
    itc_set_get($k);   // заодно создаст таблицу
    db()->prepare('REPLACE INTO itc_settings (k,v,at) VALUES (?,?,NOW())')->execute([$k, (string)$v]);
  } catch (Exception $e) {}
}

/* Гасим просроченные конверты. Вызываем перед каждым показом: отдельного
   расписания заводить не нужно, а показать сгоревший как живой нельзя. */
function itc_env_burn($phone = '') {
  itc_ref_ensure();
  try {
    if ($phone !== '') {
      db()->prepare("UPDATE itc_envelope SET status='burned' WHERE phone=? AND status='new' AND open_by < NOW()")->execute([$phone]);
      db()->prepare("UPDATE itc_envelope SET status='burned' WHERE phone=? AND status='opened' AND spend_by IS NOT NULL AND spend_by < NOW()")->execute([$phone]);
    } else {
      db()->query("UPDATE itc_envelope SET status='burned' WHERE status='new' AND open_by < NOW()");
      db()->query("UPDATE itc_envelope SET status='burned' WHERE status='opened' AND spend_by IS NOT NULL AND spend_by < NOW()");
    }
  } catch (Exception $e) {}
}

function itc_ref_code($phone) {
  itc_ref_ensure();
  $phone = trim((string)$phone);
  if ($phone === '') return '';
  try {
    $q = db()->prepare('SELECT ref_code FROM customers WHERE phone=? LIMIT 1');
    $q->execute([$phone]);
    $code = (string)$q->fetchColumn();
    if ($code !== '') return $code;
  } catch (Exception $e) { return ''; }
  for ($i = 0; $i < 6; $i++) {
    $try = strtoupper(substr(bin2hex(random_bytes(5)), 0, 8));
    try {
      db()->prepare('UPDATE customers SET ref_code=? WHERE phone=? AND (ref_code IS NULL OR ref_code="")')->execute([$try, $phone]);
      $q = db()->prepare('SELECT ref_code FROM customers WHERE phone=? LIMIT 1');
      $q->execute([$phone]);
      $code = (string)$q->fetchColumn();
      if ($code !== '') return $code;
    } catch (Exception $e) { /* совпал код — пробуем ещё раз */ }
  }
  return '';
}

function itc_geocode($query) {
  $q = trim((string)$query);
  if ($q === '') return null;
  $r = dadata_call('suggest/address', ['query' => $q, 'count' => 1]);
  if (!$r || empty($r['suggestions'][0]['data'])) return null;
  $d = $r['suggestions'][0]['data'];
  $lat = isset($d['geo_lat']) ? (float)$d['geo_lat'] : 0;
  $lon = isset($d['geo_lon']) ? (float)$d['geo_lon'] : 0;
  if (!$lat || !$lon) return null;
  return ['lat' => $lat, 'lon' => $lon,
          'qc' => isset($d['qc_geo']) ? (int)$d['qc_geo'] : 9,
          'value' => (string)($r['suggestions'][0]['value'] ?? $q)];
}
/* Расстояние между двумя точками по земле, в километрах. */
function itc_km($lat1, $lon1, $lat2, $lon2) {
  $R = 6371.0;
  $dLat = deg2rad($lat2 - $lat1);
  $dLon = deg2rad($lon2 - $lon1);
  $a = sin($dLat/2)*sin($dLat/2) + cos(deg2rad($lat1))*cos(deg2rad($lat2))*sin($dLon/2)*sin($dLon/2);
  return $R * 2 * atan2(sqrt($a), sqrt(1-$a));
}

function dadata_call($method, $payload) {
  $tok = dadata_token();
  if ($tok === '') return null;
  $url = 'https://suggestions.dadata.ru/suggestions/api/4_1/rs/' . $method;
  $ch = curl_init($url);
  curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_POST => true,
    CURLOPT_TIMEOUT => 8,
    CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE),
    CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Accept: application/json', 'Authorization: Token ' . $tok],
  ]);
  $res = curl_exec($ch);
  $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
  curl_close($ch);
  if ($code !== 200 || !$res) return null;
  $j = json_decode($res, true);
  return is_array($j) ? $j : null;
}

/* Токен кладём ещё и в cookie от СЕРВЕРА. На iPhone Safari сам вычищает
   хранилище приложения, и человек оказывается разлогинен, хотя ничего не делал.
   Серверная cookie переживает эту чистку, и вход восстанавливается сам. */
function itc_set_token_cookie($token) {
  try {
    $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
    if (PHP_VERSION_ID >= 70300) {
      setcookie('itc_t', $token, [
        'expires'  => time() + 365*24*3600,
        'path'     => '/',
        'secure'   => $secure,
        'httponly' => true,
        'samesite' => 'Lax',
      ]);
    } else {
      setcookie('itc_t', $token, time() + 365*24*3600, '/; SameSite=Lax', '', $secure, true);
    }
  } catch (Exception $e) {}
}
function make_session($phone, $role, $supplierId, $staffRole = '') {
  $token = gen('t') . substr(bin2hex(random_bytes(8)), 0, 10);
  try {
    db()->prepare('INSERT INTO sessions (token,phone,role,supplier_id,staff_role) VALUES (?,?,?,?,?)')
        ->execute([$token, $phone, $role, $supplierId, $staffRole]);
  } catch (Exception $e) {
    db()->prepare('INSERT INTO sessions (token,phone,role,supplier_id) VALUES (?,?,?,?)')
        ->execute([$token, $phone, $role, $supplierId]);
  }
  itc_set_token_cookie($token);
  return $token;
}
