// ---- №321 · «Мои приложения» ----
function apps_known() { return ['metro', 'esim']; }   // metro = «Мой Гуанчжоу», esim = «eSIM Китай»; следующие приложения добавляем сюда

// ============================================================
//  №325 · eSIM «Интернет в Китае» — продажа eSIM через провайдера eSIM Access.
//  Клиент платит в магазине (Робокасса, как обычный заказ), после оплаты сервер сам
//  заказывает eSIM у провайдера и отдаёт QR-код в приложение «eSIM Китай».
//  Настройки (таблица settings): esim_access_code, esim_secret_key — ключи консоли
//  console.esimaccess.com; esim_markup_pct — наценка в % (с №302 — 70%);
//  esim_usd_rub — курс $→₽ (пусто = kurs_usd из расчёта «под ключ»); esim_round — округление ₽.
//  Деньги провайдеру: баланс в консоли пополняется заранее (карта), API списывает с него.
// ============================================================
function esim_table() {
  static $done = false; if ($done) return; $done = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS esim_orders (
    id VARCHAR(24) NOT NULL PRIMARY KEY,
    order_id VARCHAR(24) NOT NULL,
    phone VARCHAR(32) NOT NULL,
    package_code VARCHAR(64) NOT NULL,
    package_name VARCHAR(200) NOT NULL DEFAULT '',
    volume BIGINT NOT NULL DEFAULT 0,
    days INT NOT NULL DEFAULT 0,
    usd_cost DECIMAL(10,4) NOT NULL DEFAULT 0,
    rub_price INT NOT NULL DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'new',
    provider_order_no VARCHAR(64) NULL,
    esim_tran_no VARCHAR(64) NULL,
    iccid VARCHAR(32) NULL,
    ac VARCHAR(255) NULL,
    qr_url VARCHAR(255) NULL,
    short_url VARCHAR(255) NULL,
    smdp_status VARCHAR(32) NULL,
    esim_status VARCHAR(32) NULL,
    order_usage BIGINT NOT NULL DEFAULT 0,
    expired_time VARCHAR(40) NULL,
    error VARCHAR(500) NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL,
    checked_at TIMESTAMP NULL,
    INDEX (order_id), INDEX (phone), INDEX (status)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci"); }
  catch (Throwable $e) { try { db()->query("CREATE TABLE IF NOT EXISTS esim_orders (id VARCHAR(24) NOT NULL PRIMARY KEY, order_id VARCHAR(24) NOT NULL, phone VARCHAR(32) NOT NULL, package_code VARCHAR(64) NOT NULL, package_name VARCHAR(200) NOT NULL DEFAULT '', volume BIGINT NOT NULL DEFAULT 0, days INT NOT NULL DEFAULT 0, usd_cost DECIMAL(10,4) NOT NULL DEFAULT 0, rub_price INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'new', provider_order_no VARCHAR(64) NULL, esim_tran_no VARCHAR(64) NULL, iccid VARCHAR(32) NULL, ac VARCHAR(255) NULL, qr_url VARCHAR(255) NULL, short_url VARCHAR(255) NULL, smdp_status VARCHAR(32) NULL, esim_status VARCHAR(32) NULL, order_usage BIGINT NOT NULL DEFAULT 0, expired_time VARCHAR(40) NULL, error VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL, checked_at TIMESTAMP NULL, INDEX (order_id), INDEX (phone), INDEX (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); } catch (Throwable $e2) { error_log('esim_table: '.$e2->getMessage()); } }
}
function esim_cfg() {
  if (empty($GLOBALS['esim_mk70_done'])) { $GLOBALS['esim_mk70_done'] = 1; try { if ((string)itc_setting('esim_mk70', '') === '') { esim_set('esim_markup_pct', 70); esim_set('esim_mk70', '1'); @unlink(__DIR__ . '/.esim_plans.json'); } } catch (Throwable $e) {} }
  static $cfg = null; if ($cfg !== null && empty($GLOBALS['esim_cfg_dirty'])) return $cfg; $GLOBALS['esim_cfg_dirty'] = 0;
  $usd = (float)itc_setting('esim_usd_rub', 0);
  $src = 'manual';
  if ($usd <= 0) { $st = get_settings(); $usd = (float)($st['kurs_usd'] ?? 95); $src = 'calc'; }
  return $cfg = [
    'usd_src'=> $src,
    'access' => trim((string)itc_setting('esim_access_code', '')),
    'secret' => trim((string)itc_setting('esim_secret_key', '')),
    'markup' => (float)itc_setting('esim_markup_pct', 70),
    'usd'    => $usd,
    'round'  => max(1, (int)itc_setting('esim_round', 10)),
    'auth'   => (string)itc_setting('esim_auth_mode', ''),   // '' = ещё не выяснили, 'simple' | 'hmac_secret' | 'hmac_access'
  ];
}
function esim_set($k, $v) { $GLOBALS['esim_cfg_dirty'] = 1; db()->prepare('INSERT INTO settings (k,v) VALUES (?,?) ON DUPLICATE KEY UPDATE v=VALUES(v)')->execute([$k, (string)$v]); }
// Один вызов к провайдеру. Пробуем способы подписи по очереди и запоминаем рабочий.
function esim_call($path, $body = [], $timeout = 25) {
  $c = esim_cfg();
  if ($c['access'] === '') return ['success'=>false, 'errorMsg'=>'Не заданы ключи eSIM Access (Управление → eSIM)'];
  $json = json_encode((object)$body, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
  $modes = $c['auth'] ? [$c['auth']] : ['simple', 'hmac_secret', 'hmac_access'];
  $last = null;
  foreach ($modes as $m) {
    $h = ['Content-Type: application/json', 'RT-AccessCode: '.$c['access']];
    if ($m === 'simple') { if ($c['secret'] !== '') $h[] = 'RT-SecretKey: '.$c['secret']; }
    else {
      $key = ($m === 'hmac_secret' && $c['secret'] !== '') ? $c['secret'] : $c['access'];
      $ts = (string)(int)round(microtime(true) * 1000); $rid = bin2hex(random_bytes(16));
      $sig = strtolower(hash_hmac('sha256', $ts.$rid.$c['access'].$json, $key));
      $h[] = 'RT-Timestamp: '.$ts; $h[] = 'RT-RequestID: '.$rid; $h[] = 'RT-Signature: '.$sig;
      if ($c['secret'] !== '') $h[] = 'RT-SecretKey: '.$c['secret'];
    }
    $ch = curl_init('https://api.esimaccess.com/api/v1/open'.$path);
    curl_setopt_array($ch, [CURLOPT_POST=>true, CURLOPT_POSTFIELDS=>$json, CURLOPT_HTTPHEADER=>$h, CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>$timeout, CURLOPT_CONNECTTIMEOUT=>8]);
    $raw = curl_exec($ch); $err = curl_error($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    if ($raw === false) { $last = ['success'=>false, 'errorMsg'=>'Нет связи с провайдером: '.$err]; continue; }
    $r = json_decode($raw, true);
    if (!is_array($r)) { $last = ['success'=>false, 'errorMsg'=>'Непонятный ответ провайдера (HTTP '.$code.')']; continue; }
    $authFail = (!empty($r['errorCode']) && in_array((string)$r['errorCode'], ['401001','401','403'], true)) || $code === 401 || $code === 403;
    if ($authFail) { $last = $r; continue; }
    if (!$c['auth'] && !empty($r['success'])) { try { esim_set('esim_auth_mode', $m); } catch (Throwable $e) {} }
    return $r;
  }
  return $last ?: ['success'=>false, 'errorMsg'=>'Провайдер не ответил'];
}
function esim_rub($usd) { $c = esim_cfg(); $r = $usd * $c['usd'] * (1 + $c['markup'] / 100); return (int)(ceil($r / $c['round']) * $c['round']); }
function esim_gb($bytes) { $g = $bytes / 1073741824; return $g >= 1 ? (abs($g - round($g)) < 0.05 ? (string)round($g) : number_format($g, 1, ',', '')) : (string)round($bytes / 1048576).' МБ'; }
// Тарифы Китая у провайдера (кэш 6 часов)
// №332 · все тарифы провайдера (все страны) — кэш в файле на 6 часов
function esim_all($force = false) {
  static $mem = null; if ($mem !== null && !$force) return $mem;
  $f = __DIR__ . '/.esim_plans.json';
  if (!$force && is_file($f)) { $j = json_decode((string)@file_get_contents($f), true); if (is_array($j) && !empty($j['list']) && time() - (int)($j['ts'] ?? 0) < 6*3600) return $mem = $j['list']; }
  @set_time_limit(120);
  $r = esim_call('/package/list', ['locationCode'=>'', 'type'=>'', 'slug'=>'', 'packageCode'=>'', 'iccid'=>''], 90);
  if (empty($r['success'])) { $j = is_file($f) ? json_decode((string)@file_get_contents($f), true) : null; return $mem = ((is_array($j) && !empty($j['list'])) ? $j['list'] : []); }
  $L = [];
  foreach (($r['obj']['packageList'] ?? []) as $p) {
    if (($p['durationUnit'] ?? 'DAY') !== 'DAY') continue;
    $locs = array_values(array_filter(array_map('trim', explode(',', strtoupper((string)($p['location'] ?? '')))), function($c){ return preg_match('/^[A-Z]{2}$/', $c); }));
    if (!$locs) continue;
    $nets = [];
    if (count($locs) === 1) $nets = array_slice(array_values(array_unique(array_filter(array_map(function($n){ return (string)($n['operatorName'] ?? ''); }, (array)($p['locationNetworkList'][0]['operatorList'] ?? []))))), 0, 4);
    $L[] = ['code'=>(string)$p['packageCode'], 'name'=>(string)($p['name'] ?? ''), 'volume'=>(int)($p['volume'] ?? 0), 'days'=>(int)($p['duration'] ?? 0),
            'usd'=>round(((int)($p['price'] ?? 0)) / 10000, 4), 'topup'=>(int)($p['supportTopUpType'] ?? 0) === 2,
            'daily'=>(int)($p['dataType'] ?? 0) === 2 || stripos((string)($p['name'] ?? ''), '/day') !== false, 'locs'=>$locs, 'multi'=>count($locs) > 1, 'nets'=>$nets];
  }
  if ($L) { $tmp = $f . '.tmp'; if (@file_put_contents($tmp, json_encode(['ts'=>time(), 'list'=>$L], JSON_UNESCAPED_UNICODE)) !== false) @rename($tmp, $f); }
  return $mem = $L;
}
// тарифы одной страны (по умолчанию Китай): свои и региональные, где эта страна есть
function esim_plans($force = false, $loc = 'CN') {
  $loc = strtoupper(preg_replace('/[^A-Za-z]/', '', (string)$loc)) ?: 'CN';
  $L = array_values(array_filter(esim_all($force), function($p) use ($loc) { return in_array($loc, $p['locs'] ?? [], true); }));
  usort($L, function($a, $b) { return $a['multi'] <=> $b['multi'] ?: $b['daily'] <=> $a['daily'] ?: $a['days'] <=> $b['days'] ?: $a['volume'] <=> $b['volume']; });
  return $L;
}
function esim_plan_find($code) { foreach (esim_all() as $p) if ($p['code'] === $code) return $p; return null; }
// страны: сколько своих тарифов и самая низкая цена
function esim_countries() {
  $C = [];
  foreach (esim_all() as $p) foreach ($p['locs'] as $c) {
    if (!isset($C[$c])) $C[$c] = ['c'=>$c, 'n'=>0, 'm'=>0, 'min'=>null];
    if (count($p['locs']) === 1) { $C[$c]['n']++; if ($C[$c]['min'] === null || $p['usd'] < $C[$c]['min']) $C[$c]['min'] = $p['usd']; } else $C[$c]['m']++;
  }
  foreach ($C as &$x) { $x['rub'] = $x['min'] !== null ? esim_rub($x['min']) : 0; unset($x['min']); } unset($x);
  return array_values($C);
}
// №340 · общий рисовальщик Wanxiang: prompt → байты картинки (или ['err'=>...])
function ds_art_cfg_file($key, $base) { @file_put_contents(__DIR__ . '/config_art.php', "<?php\nreturn " . var_export(['key'=>$key, 'base'=>$base], true) . ";\n", LOCK_EX); }
// №346 · примерный счётчик расходов рисовалки (юани): по дням и месяцам
function art_spend_add($yuan) { try { foreach (['art_spend_d' . date('Ymd'), 'art_spend_m' . date('Ym'), 'art_spend_all'] as $k) db()->prepare("INSERT INTO settings (k,v) VALUES (?,?) ON DUPLICATE KEY UPDATE v=CAST(v AS DECIMAL(12,3))+VALUES(v)")->execute([$k, (string)$yuan]); } catch (Throwable $e) {} }
function ds_draw($prompt, $size = '1024*1024', $neg = 'text, letters, words, watermark, logo, flag, blurry', $model = 'wanx2.1-t2i-turbo') {
  $key = trim((string)itc_setting('dashscope_key', ''));
  if ($key === '') return ['err'=>'Не задан ключ рисовалки (Управление → eSIM → Картинки стран)'];
  $bases = []; $own = trim((string)itc_setting('dashscope_base', ''));
  if ($own !== '') $bases[] = rtrim($own, '/');
  if (strpos($key, 'sk-ws-') === 0) $bases[] = 'https://ws-2rnql6jpngl5mbmt.cn-beijing.maas.aliyuncs.com/api/v1';
  $bases[] = 'https://dashscope.aliyuncs.com/api/v1'; $bases = array_values(array_unique($bases));
  $body = json_encode(['model'=>$model, 'input'=>['prompt'=>mb_substr($prompt, 0, 780), 'negative_prompt'=>$neg], 'parameters'=>['size'=>$size, 'n'=>1]], JSON_UNESCAPED_UNICODE);
  $task = ''; $base = ''; $why = '';
  foreach ($bases as $b) {
    $ch = curl_init($b . '/services/aigc/text2image/image-synthesis');
    curl_setopt_array($ch, [CURLOPT_POST=>true, CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>25, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_HTTPHEADER=>['Content-Type: application/json', 'Authorization: Bearer ' . $key, 'X-DashScope-Async: enable'], CURLOPT_POSTFIELDS=>$body]);
    $raw = curl_exec($ch); $err = curl_error($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    $j = json_decode((string)$raw, true); $task = (string)($j['output']['task_id'] ?? '');
    if ($task !== '') { $base = $b; if ($own === '' && $b !== 'https://dashscope.aliyuncs.com/api/v1') { try { esim_set('dashscope_base', $b); } catch (Throwable $e) {} } break; }
    $why = trim((string)($j['code'] ?? '') . ' ' . (string)($j['message'] ?? ($err ?: ('HTTP ' . $code))));
    if (stripos($why, 'Arrearage') !== false || stripos($why, 'quota') !== false) break;
  }
  if ($task === '') {
    if (stripos($why, 'Arrearage') !== false) return ['err'=>'На счёте Alibaba Cloud нет денег, а бесплатный запас кончился. Пополните счёт Alibaba Cloud (充值) — достаточно 20–30 юаней.'];
    if (stripos($why, 'InvalidApiKey') !== false) return ['err'=>'Ключ рисовалки не подходит — проверьте, что вставлен целиком'];
    return ['err'=>'Рисовалка не приняла задание: ' . mb_substr($why, 0, 200)];
  }
  if (!is_file(__DIR__ . '/config_art.php')) ds_art_cfg_file($key, $base);
  @set_time_limit(150); $url = '';
  for ($i = 0; $i < 35; $i++) {
    sleep(3);
    $ch = curl_init($base . '/tasks/' . rawurlencode($task)); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>15, CURLOPT_HTTPHEADER=>['Authorization: Bearer ' . $key]]);
    $t = json_decode((string)curl_exec($ch), true); curl_close($ch);
    $st = (string)($t['output']['task_status'] ?? '');
    if ($st === 'SUCCEEDED') { $url = (string)($t['output']['results'][0]['url'] ?? ''); art_spend_add($model === 'wanx2.1-t2i-plus' ? 0.2 : 0.14); break; }
    if (in_array($st, ['FAILED', 'CANCELED', 'UNKNOWN'], true)) return ['err'=>'Не нарисовалось: ' . mb_substr((string)($t['output']['message'] ?? $st), 0, 200)];
  }
  if ($url === '') return ['err'=>'Рисовалка долго думает — нажмите ещё раз'];
  $ch = curl_init($url); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>40, CURLOPT_FOLLOWLOCATION=>true]); $img = curl_exec($ch); curl_close($ch);
  return $img ? ['img'=>$img] : ['err'=>'Не удалось скачать картинку'];
}
