  } catch (Throwable $e) {}
}
// №345 · правка фото товара моделью Qwen-Image-Edit: товар остаётся как есть, фон и обстановка — новые
function ds_edit($dataUri, $prompt, $neg = '', $size = '', $alt = '') {
  $key = trim((string)itc_setting('dashscope_key', ''));
  if ($key === '') return ['err'=>'Не задан ключ рисовалки (Управление → eSIM → Картинки стран)'];
  $bases = []; $own = trim((string)itc_setting('dashscope_base', ''));
  if ($own !== '') $bases[] = rtrim($own, '/');
  if (strpos($key, 'sk-ws-') === 0) $bases[] = 'https://ws-2rnql6jpngl5mbmt.cn-beijing.maas.aliyuncs.com/api/v1';
  $bases[] = 'https://dashscope.aliyuncs.com/api/v1'; $bases = array_values(array_unique($bases));
  $par = ['negative_prompt'=>$neg ?: ' ', 'watermark'=>false, 'n'=>1]; if ($size !== '') $par['size'] = $size;
  @set_time_limit(240); $why = ''; $url = '';
  $tries = [];
  // №316 · модель правки фото: какая есть в рабочей области Alibaba — та и работает (запоминаем удачную)
  $models = array_values(array_unique(array_filter([(string)itc_setting('dashscope_edit_model', ''), 'qwen-image-2.1-pro', 'wan2.7-image-pro', 'qwen-image-2.1', 'wan2.7-image', 'qwen-image-edit-plus', 'qwen-image-edit'])));
  foreach ($bases as $b) foreach ($models as $md) foreach (array_values(array_filter([$dataUri, $alt])) as $src) $tries[] = [$b, $src, $md];   // сначала само фото внутри запроса, запасной путь — ссылка на фото
  $noModel = [];
  foreach ($tries as $t) {
    $b = $t[0];
    if (isset($noModel[$b . '|' . $t[2]])) continue;
    $body = json_encode(['model'=>$t[2], 'input'=>['messages'=>[['role'=>'user', 'content'=>[['image'=>$t[1]], ['text'=>mb_substr($prompt, 0, 790)]]]]], 'parameters'=>$par], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    $ch = curl_init($b . '/services/aigc/multimodal-generation/generation');
    curl_setopt_array($ch, [CURLOPT_POST=>true, CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>150, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_HTTPHEADER=>['Content-Type: application/json', 'Authorization: Bearer ' . $key], CURLOPT_POSTFIELDS=>$body]);
    $raw = curl_exec($ch); $err = curl_error($ch); $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
    $j = json_decode((string)$raw, true);
    foreach ((array)($j['output']['choices'][0]['message']['content'] ?? []) as $c) if (!empty($c['image'])) { $url = (string)$c['image']; break; }
    if ($url !== '') { art_spend_add(strpos($t[2], 'wan') === 0 ? 0.5 : 0.25); try { esim_set('dashscope_edit_model', $t[2]); } catch (Throwable $e) {} break; }
    $why = trim((string)($j['code'] ?? '') . ' ' . (string)($j['message'] ?? ($err ?: ('HTTP ' . $code))));
    if (stripos($why, 'Model not exist') !== false || stripos($why, 'model not found') !== false || stripos($why, 'AccessDenied') !== false) $noModel[$b . '|' . $t[2]] = 1;
    if (stripos($why, 'Arrearage') !== false) break;
  }
  if ($url === '') {
    if (stripos($why, 'Arrearage') !== false) return ['err'=>'На счёте Alibaba Cloud нет денег — пополните счёт (充值)'];
    return ['err'=>'Не получилось обработать фото: ' . mb_substr($why, 0, 200)];
  }
  $ch = curl_init($url); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>40, CURLOPT_FOLLOWLOCATION=>true]); $img = curl_exec($ch); curl_close($ch);
  return $img ? ['img'=>$img] : ['err'=>'Не удалось скачать картинку'];
}
// ===== №350 · АВТОБАННЕРЫ: ИИ раз в N дней делает 5–6 баннеров из разных товаров магазина =====
// Товар — с его фото (фон заменяет Qwen-Image-Edit на сцену по смыслу: диван — семья дома, отвертка — мастер в рабочей форме),
// текст и цена — поверх картинки, баннер ведёт на карточку товара. Баннеры автопоказа — id с «ab».
function ab_cfg() {
  $k = (string)itc_setting('autoban_key', '');
  if ($k === '') { $k = bin2hex(random_bytes(12)); try { esim_set('autoban_key', $k); } catch (Throwable $e) {} }
  return ['on'=>itc_setting('autoban_on', '0') === '1', 'days'=>max(1, min(14, (int)itc_setting('autoban_days', 3))), 'n'=>max(3, min(8, (int)itc_setting('autoban_n', 6))),
          'prio'=>(string)itc_setting('autoban_prio', 'генератор, зарядная станция, электростанция'), 'last'=>(int)itc_setting('autoban_last', 0), 'key'=>$k,
          'mode'=>itc_setting('autoban_mode', 'all') === 'one' ? 'one' : 'all'];   // №343 · 'one' — за раз меняем один баннер: новый встаёт первым, самый старый уходит
}
function ab_cur_count() { try { return (int)db()->query("SELECT COUNT(*) FROM banners WHERE id LIKE 'ab%'")->fetchColumn(); } catch (Throwable $e) { return 0; } }
function ab_cur_pids() { $o = []; try { foreach (db()->query("SELECT link FROM banners WHERE id LIKE 'ab%'")->fetchAll() as $r) if (preg_match('~[?&]p=([^&]+)~', (string)$r['link'], $m)) $o[] = rawurldecode($m[1]); } catch (Throwable $e) {} return $o;
}
// №315 · очередь и список показанных — в файлах: в поле настроек длинный текст обрезался, и задание терялось
function ab_file($n) { return __DIR__ . '/.autoban_' . $n . '.json'; }
function ab_job_get() { $f = ab_file('job'); $j = is_file($f) ? json_decode((string)@file_get_contents($f), true) : null; return is_array($j) ? $j : null; }
function ab_job_set($j) { $f = ab_file('job'); if (!$j) { @unlink($f); return; } $t = $f . '.tmp'; if (@file_put_contents($t, json_encode($j, JSON_UNESCAPED_UNICODE)) !== false) @rename($t, $f); }
function ab_used_get() { $f = ab_file('used'); $u = is_file($f) ? json_decode((string)@file_get_contents($f), true) : null; return is_array($u) ? $u : []; }
function ab_used_set($u) { @file_put_contents(ab_file('used'), json_encode(array_values($u))); }
// выбор товаров: разные категории, без повторов последних показов; часть — из «приоритетных» слов
function ab_pick($n, $prio) {
  // №313 · запасные выборки: если в базе нет какого-то столбца или все фото с alicdn — всё равно находим товары
  $Q = ["SELECT id, name, cat, subcat, price, old_price, clicks, UNIX_TIMESTAMP(created_at) cts, img FROM products WHERE vis=1 AND (blocked=0 OR blocked IS NULL) AND (paused=0 OR paused IS NULL)
     AND (mod_status='approved' OR mod_status='' OR mod_status IS NULL) AND price>0 AND img IS NOT NULL AND img<>'' AND img NOT LIKE '%alicdn%' ORDER BY RAND() LIMIT 600",
        "SELECT id, name, cat, subcat, price, old_price, clicks, UNIX_TIMESTAMP(created_at) cts, img FROM products WHERE vis=1 AND (blocked=0 OR blocked IS NULL) AND price>0 AND img IS NOT NULL AND img<>'' ORDER BY RAND() LIMIT 600",
        "SELECT id, name, cat, subcat, price, img FROM products WHERE vis=1 AND (blocked=0 OR blocked IS NULL) AND price>0 AND img IS NOT NULL AND img<>'' ORDER BY RAND() LIMIT 600",
        "SELECT id, name, cat, '' subcat, price, img FROM products WHERE (blocked=0 OR blocked IS NULL) AND price>0 AND img IS NOT NULL AND img<>'' ORDER BY RAND() LIMIT 600"];
  $rows = []; $why = '';
  foreach ($Q as $q) { try { $rows = db()->query($q)->fetchAll(); if (count($rows) >= $n) break; } catch (Throwable $e) { $why = $e->getMessage(); } }
  if (!$rows && $why !== '') esim_set('autoban_err', 'выборка товаров: ' . mb_substr($why, 0, 150));
  foreach ($rows as &$rw) { $im = (string)$rw['img']; if ($im !== '' && $im[0] === '[') { $a = json_decode($im, true); $rw['img'] = is_array($a) && $a ? (string)(is_array($a[0]) ? ($a[0]['url'] ?? '') : $a[0]) : ''; } } unset($rw);
  $rows = array_values(array_filter($rows, function($r){ return $r['img'] !== ''; }));
  $used = ab_used_get();
  $words = array_values(array_filter(array_map(function($w){ return mb_strtolower(trim($w)); }, preg_split('/[,;\n]+/u', $prio))));
  $fresh = array_values(array_filter($rows, function($r) use ($used) { return !in_array($r['id'], $used, true); }));
  if (count($fresh) < $n) $fresh = $rows;
  $pick = []; $cats = []; $subs = [];
  $take = function($r) use (&$pick, &$cats, &$subs) { $pick[] = $r; $cats[mb_strtolower((string)$r['cat'])] = 1; $subs[mb_strtolower((string)$r['subcat'] ?: (string)$r['name'])] = 1; };
  $isPrio = function($r) use ($words) { $t = mb_strtolower($r['name'] . ' ' . $r['cat'] . ' ' . $r['subcat']); foreach ($words as $w) if ($w !== '' && mb_strpos($t, $w) !== false) return true; return false; };
  $pq = (int)ceil($n / 3);
  foreach ($fresh as $r) { if (count($pick) >= $pq) break; if ($isPrio($r) && !isset($subs[mb_strtolower((string)$r['subcat'] ?: (string)$r['name'])])) $take($r); }
  foreach ($fresh as $r) { if (count($pick) >= $n) break; if (in_array($r, $pick, true)) continue; if (isset($cats[mb_strtolower((string)$r['cat'])])) continue; $take($r); }
  foreach ($fresh as $r) { if (count($pick) >= $n) break; if (in_array($r, $pick, true)) continue; if (isset($subs[mb_strtolower((string)$r['subcat'] ?: (string)$r['name'])])) continue; $take($r); }
  return $pick;
}
function ab_price($p) { $v = (float)$p; return $v > 0 ? number_format($v, 0, ',', ' ') . ' ₽' : ''; }
// ===== №317 · баннер как реклама: слева тёмная плашка с названием, выгодой и ценой (шрифт Roboto), справа товар без фона в сцене =====
function ab_font($w) { $f = dirname(__DIR__) . '/fonts/Roboto-' . $w . '.ttf'; return is_file($f) ? $f : ''; }
// фото с белым/светлым ровным фоном? (иначе — посторонний фон, надписи: такой товар на баннер не берём)
function ab_plain_bg($im) {
  $w = imagesx($im); $h = imagesy($im); $ok = 0; $n = 0;
  for ($i = 0; $i < 120; $i++) {
    $t = $i / 120; $pts = [[(int)($t * ($w - 1)), 0], [(int)($t * ($w - 1)), $h - 1], [0, (int)($t * ($h - 1))], [$w - 1, (int)($t * ($h - 1))]];
    foreach ($pts as $pt) { $c = imagecolorat($im, $pt[0], $pt[1]); $r = ($c >> 16) & 255; $g = ($c >> 8) & 255; $b = $c & 255; $n++; if (min($r, $g, $b) > 226 && max($r, $g, $b) - min($r, $g, $b) < 24) $ok++; }
  }
  return $n && $ok / $n >= 0.82;
}
// вырезать товар: светлый фон, связанный с краями, делаем прозрачным
function ab_cutout($src, $max = 760) {
  $k = min(1, $max / max(imagesx($src), imagesy($src))); $w = max(1, (int)(imagesx($src) * $k)); $h = max(1, (int)(imagesy($src) * $k));
  $im = imagecreatetruecolor($w, $h); imagealphablending($im, false); imagesavealpha($im, true);
  imagecopyresampled($im, $src, 0, 0, 0, 0, $w, $h, imagesx($src), imagesy($src));
  $seen = array_fill(0, $w * $h, 0); $q = new SplQueue();
  $isBg = function($x, $y) use ($im) { $c = imagecolorat($im, $x, $y); $r = ($c >> 16) & 255; $g = ($c >> 8) & 255; $b = $c & 255; return min($r, $g, $b) > 222 && max($r, $g, $b) - min($r, $g, $b) < 28; };
  for ($x = 0; $x < $w; $x++) { $q->enqueue([$x, 0]); $q->enqueue([$x, $h - 1]); }
  for ($y = 0; $y < $h; $y++) { $q->enqueue([0, $y]); $q->enqueue([$w - 1, $y]); }
  $tr = imagecolorallocatealpha($im, 255, 255, 255, 127);
  while (!$q->isEmpty()) {
    list($x, $y) = $q->dequeue(); $i = $y * $w + $x; if ($seen[$i]) continue; $seen[$i] = 1;
    if (!$isBg($x, $y)) continue;
    imagesetpixel($im, $x, $y, $tr);
    if ($x > 0) $q->enqueue([$x - 1, $y]); if ($x < $w - 1) $q->enqueue([$x + 1, $y]); if ($y > 0) $q->enqueue([$x, $y - 1]); if ($y < $h - 1) $q->enqueue([$x, $y + 1]);
  }
  // обрезаем пустые края, чтобы товар стоял на «полу», а не висел
  $x0 = $w; $y0 = $h; $x1 = -1; $y1 = -1;
  for ($y = 0; $y < $h; $y += 2) for ($x = 0; $x < $w; $x += 2) if (!$seen[$y * $w + $x] || ((imagecolorat($im, $x, $y) >> 24) & 127) < 100) { if (!$seen[$y * $w + $x] || true) { $a = (imagecolorat($im, $x, $y) >> 24) & 127; if ($a < 100) { if ($x < $x0) $x0 = $x; if ($y < $y0) $y0 = $y; if ($x > $x1) $x1 = $x; if ($y > $y1) $y1 = $y; } } }
  if ($x1 > $x0 && $y1 > $y0) { $cw = $x1 - $x0 + 2; $ch = $y1 - $y0 + 2; $c2 = imagecreatetruecolor($cw, $ch); imagealphablending($c2, false); imagesavealpha($c2, true);
    imagecopy($c2, $im, 0, 0, $x0, $y0, $cw, $ch); imagedestroy($im); $im = $c2; }
  return $im;
}
function ab_wrap($text, $font, $size, $maxw, $lines = 2) {
  $words = preg_split('/\s+/u', trim($text)); $out = []; $cur = '';
  foreach ($words as $wd) { $try = $cur === '' ? $wd : $cur . ' ' . $wd; $bb = imagettfbbox($size, 0, $font, $try);
    if ($bb[2] - $bb[0] > $maxw && $cur !== '') { $out[] = $cur; $cur = $wd; if (count($out) >= $lines) break; } else $cur = $try; }
  if (count($out) < $lines && $cur !== '') $out[] = $cur;
  return array_slice($out, 0, $lines);
}
function ab_rrect($im, $x1, $y1, $x2, $y2, $r, $col) {
  imagefilledrectangle($im, $x1 + $r, $y1, $x2 - $r, $y2, $col); imagefilledrectangle($im, $x1, $y1 + $r, $x2, $y2 - $r, $col);
  foreach ([[$x1 + $r, $y1 + $r], [$x2 - $r, $y1 + $r], [$x1 + $r, $y2 - $r], [$x2 - $r, $y2 - $r]] as $c) imagefilledellipse($im, $c[0], $c[1], $r * 2, $r * 2, $col);
}
// текст поверх: тёмная плашка слева, название, выгода, цена, «Подробнее»
// №321 · цвета текста под тему и настроение: где-то белый, где-то красный, жёлтый, кислотный, приглушённый
function ab_pal() { return ['white'=>[255,255,255], 'yellow'=>[255,214,64], 'red'=>[255,59,48], 'orange'=>[255,140,0], 'lime'=>[198,255,0], 'pink'=>[255,64,170], 'cyan'=>[0,229,255],
  'green'=>[60,210,100], 'cream'=>[255,240,214], 'coral'=>[255,120,100], 'gold'=>[230,190,110], 'sky'=>[150,210,255], 'navy'=>[17,44,147], 'black'=>[25,25,30], 'wine'=>[150,20,50]]; }
function ab_mood_cols($mood) {
  $M = ['acid'=>[['white','lime'],['white','pink'],['black','lime'],['white','cyan']], 'bold'=>[['white','orange'],['white','red'],['white','yellow']],
        'muted'=>[['cream','cream'],['white','gold'],['white','coral']], 'warm'=>[['cream','yellow'],['white','orange'],['white','gold']],
        'clean'=>[['navy','red'],['black','red'],['white','sky']], 'fresh'=>[['white','green'],['white','yellow'],['navy','orange']],
        'cool'=>[['white','sky'],['white','cyan'],['cream','red']], 'dark'=>[['white','gold'],['cream','red'],['white','yellow']]];
  $L = $M[$mood] ?? $M['bold']; return $L[array_rand($L)];
}
// №323 · рекламные знаки — только правдивые: скидка и старая цена — если есть в магазине, «Хит продаж» — если товар часто смотрят, «Новинка» — если добавлен за месяц
function ab_badges($p, $season) {
  $B = []; $old = (int)($p['old'] ?? 0); $pr = (int)$p['price'];
  if ($old > $pr && $pr > 0) { $d = (int)round(100 - $pr * 100 / $old); if ($d >= 5 && $d <= 90) $B[] = ['Скидка', '−' . $d . '%', 'sale', 'percent']; }
  if ((int)($p['clicks'] ?? 0) >= 40) { $B[] = ['Хит', 'продаж', 'hit', 'flame']; $B[] = ['Популярное', '', 'hit', 'flame']; }
  if ((int)($p['cts'] ?? 0) > time() - 30 * 86400) { $B[] = ['Новинка', '', 'new', 'gift']; $B[] = ['Только', 'поступило', 'new', 'gift']; }
  if ($season) { $B[] = ['Сезонное', 'предложение', 'season', 'check']; $B[] = ['Самое', 'время', 'season', 'check']; }
  $B[] = ['Супер', 'цена', 'super', 'bolt']; $B[] = ['Выгодная', 'цена', 'good', 'bolt']; $B[] = ['Прямо', 'с фабрики', 'factory', 'check'];
  $B[] = ['Без', 'посредников', 'factory', 'check']; $B[] = ['Цена от', 'производителя', 'factory', 'check']; $B[] = ['Доставка', 'по России', 'ship', 'truck'];
  return $B;
}
// №324 · формы знаков и значки-рисунки
function ab_star5($o, $cx, $cy, $r, $col) { $pts = []; for ($i = 0; $i < 10; $i++) { $a = M_PI / 5 * $i - M_PI / 2; $rr = $i % 2 ? $r * 0.5 : $r; $pts[] = (int)($cx + cos($a) * $rr); $pts[] = (int)($cy + sin($a) * $rr); } imagefilledpolygon($o, $pts, $col); }
function ab_ribbon($o, $cx, $cy, $w, $h, $col) { $x1 = $cx - $w / 2; $x2 = $cx + $w / 2; $y1 = $cy - $h / 2; $y2 = $cy + $h / 2; $n = $h * 0.35;
  imagefilledpolygon($o, [(int)($x1 - $n), (int)$y1, (int)$x2 + (int)$n, (int)$y1, (int)$x2, (int)$cy, (int)$x2 + (int)$n, (int)$y2, (int)($x1 - $n), (int)$y2, (int)$x1, (int)$cy], $col); }
function ab_tagshape($o, $cx, $cy, $w, $h, $col, $hole) { $x1 = $cx - $w / 2 + $h / 2; $x2 = $cx + $w / 2; $y1 = $cy - $h / 2; $y2 = $cy + $h / 2;
  imagefilledpolygon($o, [(int)($cx - $w / 2), (int)$cy, (int)$x1, (int)$y1, (int)$x2, (int)$y1, (int)$x2, (int)$y2, (int)$x1, (int)$y2], $col); imagefilledellipse($o, (int)($x1 - $h * 0.12), (int)$cy, 14, 14, $hole); }
function ab_icon($o, $t, $x, $y, $s, $col) {   // значок в квадрате s×s, левый верх (x,y)
  $c = $col; $m = $s / 2;
  if ($t === 'bolt') imagefilledpolygon($o, [(int)($x + $s * .58), (int)$y, (int)($x + $s * .15), (int)($y + $s * .58), (int)($x + $s * .45), (int)($y + $s * .58), (int)($x + $s * .35), (int)($y + $s), (int)($x + $s * .85), (int)($y + $s * .38), (int)($x + $s * .55), (int)($y + $s * .38)], $c);
  elseif ($t === 'flame') { imagefilledellipse($o, (int)($x + $m), (int)($y + $s * .66), (int)($s * .7), (int)($s * .66), $c); imagefilledpolygon($o, [(int)($x + $s * .17), (int)($y + $s * .62), (int)($x + $s * .5), (int)$y, (int)($x + $s * .83), (int)($y + $s * .62)], $c); }
  elseif ($t === 'check') { imagesetthickness($o, max(3, (int)($s / 7))); imageline($o, (int)($x + $s * .15), (int)($y + $s * .55), (int)($x + $s * .42), (int)($y + $s * .82), $c); imageline($o, (int)($x + $s * .42), (int)($y + $s * .82), (int)($x + $s * .9), (int)($y + $s * .2), $c); imagesetthickness($o, 1); }
  elseif ($t === 'truck') { imagefilledrectangle($o, (int)$x, (int)($y + $s * .2), (int)($x + $s * .6), (int)($y + $s * .7), $c); imagefilledpolygon($o, [(int)($x + $s * .62), (int)($y + $s * .35), (int)($x + $s * .85), (int)($y + $s * .35), (int)($x + $s), (int)($y + $s * .55), (int)($x + $s), (int)($y + $s * .7), (int)($x + $s * .62), (int)($y + $s * .7)], $c);
