      imagearc($o, $x1 + $r, $y1 + $r, $r * 2, $r * 2, 180, 270, $pcol); imagearc($o, $x2 - $r, $y1 + $r, $r * 2, $r * 2, 270, 360, $pcol); imagearc($o, $x1 + $r, $y2 - $r, $r * 2, $r * 2, 90, 180, $pcol); imagearc($o, $x2 - $r, $y2 - $r, $r * 2, $r * 2, 0, 90, $pcol);
      imageline($o, $x1 + $r, $y1, $x2 - $r, $y1, $pcol); imageline($o, $x1 + $r, $y2, $x2 - $r, $y2, $pcol); imageline($o, $x1, $y1 + $r, $x1, $y2 - $r, $pcol); imageline($o, $x2, $y1 + $r, $x2, $y2 - $r, $pcol); imagesetthickness($o, 1);
