// ===== №328 · текст не на людях и не на товаре =====
// ИИ, который понимает картинки, отмечает людей и товар (рамки 0–1000). Модель — какая есть в рабочей области.
function ds_vl($dataUri, $prompt) {
  $key = trim((string)itc_setting('dashscope_key', '')); if ($key === '') return '';
  $bases = []; $own = trim((string)itc_setting('dashscope_base', '')); if ($own !== '') $bases[] = rtrim($own, '/');
  if (strpos($key, 'sk-ws-') === 0) $bases[] = 'https://ws-2rnql6jpngl5mbmt.cn-beijing.maas.aliyuncs.com/api/v1';
  $bases[] = 'https://dashscope.aliyuncs.com/api/v1'; $bases = array_values(array_unique($bases));
  $models = array_values(array_unique(array_filter([(string)itc_setting('dashscope_vl_model', ''), 'qwen3-vl-plus', 'qwen-vl-max', 'qwen3-vl-flash', 'qwen-vl-plus'])));
  foreach ($bases as $b) foreach ($models as $md) {
    $body = json_encode(['model'=>$md, 'input'=>['messages'=>[['role'=>'user', 'content'=>[['image'=>$dataUri], ['text'=>$prompt]]]]]], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    $ch = curl_init($b . '/services/aigc/multimodal-generation/generation');
    curl_setopt_array($ch, [CURLOPT_POST=>true, CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>60, CURLOPT_CONNECTTIMEOUT=>10, CURLOPT_HTTPHEADER=>['Content-Type: application/json', 'Authorization: Bearer ' . $key], CURLOPT_POSTFIELDS=>$body]);
    $raw = curl_exec($ch); curl_close($ch); $j = json_decode((string)$raw, true);
    $txt = ''; foreach ((array)($j['output']['choices'][0]['message']['content'] ?? []) as $c) if (isset($c['text'])) $txt .= $c['text'];
    if ($txt !== '') { try { esim_set('dashscope_vl_model', $md); } catch (Throwable $e) {} art_spend_add(0.01); return $txt; }
    if (stripos((string)($j['code'] ?? ''), 'Arrearage') !== false) return '';
  }
  return '';
}
function ab_boxes($o) {
  $W = imagesx($o); $H = imagesy($o); $sm = imagecreatetruecolor(1000, 400); imagecopyresampled($sm, $o, 0, 0, 0, 0, 1000, 400, $W, $H);
  ob_start(); imagejpeg($sm, null, 80); $jp = ob_get_clean(); imagedestroy($sm);
  $t = ds_vl('data:image/jpeg;base64,' . base64_encode($jp), 'Find all people (whole body or visible parts) and the main advertised product on this image. Answer ONLY JSON: {"people":[[x1,y1,x2,y2],...],"product":[[x1,y1,x2,y2]]} with coordinates from 0 to 1000 (x across width, y across height). No text outside JSON.');
  $B = [];
  if ($t !== '' && preg_match('~\{.*\}~s', $t, $m) && is_array($jj = json_decode($m[0], true))) {
    foreach (['people'=>1.0, 'product'=>1.6] as $k => $wgt) foreach ((array)($jj[$k] ?? []) as $bx) if (is_array($bx) && count($bx) >= 4) {
      $x1 = max(0, min(1000, (float)$bx[0])); $y1 = max(0, min(1000, (float)$bx[1])); $x2 = max(0, min(1000, (float)$bx[2])); $y2 = max(0, min(1000, (float)$bx[3]));
      if ($x2 > $x1 && $y2 > $y1) $B[] = [$x1 * $W / 1000, $y1 * $H / 1000, $x2 * $W / 1000, $y2 * $H / 1000, $wgt]; }
  }
  return $B;
}
// карта «занятости» картинки: резкие края и кожа (лица, руки) — туда текст не ставим
function ab_busy($o) {
  $gw = 150; $gh = 60; $g = imagecreatetruecolor($gw, $gh); imagecopyresampled($g, $o, 0, 0, 0, 0, $gw, $gh, imagesx($o), imagesy($o));
  $Y = []; $S = [];
  for ($y = 0; $y < $gh; $y++) for ($x = 0; $x < $gw; $x++) { $c = imagecolorat($g, $x, $y); $r = ($c >> 16) & 255; $gg = ($c >> 8) & 255; $b = $c & 255;
    $l = 0.299 * $r + 0.587 * $gg + 0.114 * $b; $cb = 128 - 0.169 * $r - 0.331 * $gg + 0.5 * $b; $cr = 128 + 0.5 * $r - 0.419 * $gg - 0.081 * $b;
    $Y[$y][$x] = $l; $S[$y][$x] = ($l > 60 && $cr > 137 && $cr < 173 && $cb > 80 && $cb < 128) ? 1 : 0; }
  imagedestroy($g); $E = [];
  for ($y = 0; $y < $gh; $y++) for ($x = 0; $x < $gw; $x++) { $dx = $x + 1 < $gw ? abs($Y[$y][$x + 1] - $Y[$y][$x]) : 0; $dy = $y + 1 < $gh ? abs($Y[$y + 1][$x] - $Y[$y][$x]) : 0; $E[$y][$x] = min(60, $dx + $dy) / 60 + $S[$y][$x] * 1.2; }
  return [$E, $gw, $gh];
}
// только текст: название, выгода, цена (при скидке — зачёркнутая старая и «−N%»). Место — где нет людей и товара.
function ab_text2($o, $title, $sub, $price, $tc, $pc, $old = '', $disc = '') {
  $fb = ab_font('Black'); $fm = ab_font('Medium'); if ($fb === '' || !function_exists('imagettftext')) return false;
  $W = imagesx($o); $H = imagesy($o); imagealphablending($o, true);
  $boxes = []; try { $boxes = ab_boxes($o); } catch (Throwable $e) {}
  if (!$boxes) $boxes[] = [$W * 0.5, $H * 0.03, $W * 0.98, $H * 0.97, 1.2];   // ИИ не ответил — товар мы сами ставили справа
  list($E, $gw, $gh) = ab_busy($o);
