    $L = []; foreach ($big ? [60, 54, 48, 42] : [48, 42, 38, 34] as $sz) { $L = ab_wrap($title, $fb, $sz, $maxw, 3); if (count($L) <= 2) break; }
    if (count($L) > 2) { $L = array_slice($L, 0, 2); $L[1] = rtrim($L[1], ' ,.') . '…'; }
    $ss = $big ? 30 : 26; $ps = $big ? 64 : 54; $SL = $sub !== '' ? ab_wrap($sub, $fm, $ss, $maxw, 2) : [];
    $h = count($L) * (int)($sz * 1.25) + ($SL ? 12 + count($SL) * (int)($ss * 1.4) : 0) + ($price !== '' ? 22 + ($old !== '' ? 40 : 0) + (int)($ps * 1.3) : 0);
    $w = 0; foreach ($L as $ln) { $bb = imagettfbbox($sz, 0, $fb, $ln); $w = max($w, $bb[2] - $bb[0]); } foreach ($SL as $ln) { $bb = imagettfbbox($ss, 0, $fm, $ln); $w = max($w, $bb[2] - $bb[0]); }
    if ($price !== '') { $bb = imagettfbbox($ps, 0, $fb, $price); $w = max($w, $bb[2] - $bb[0] + 160); }
    return ['L'=>$L, 'sz'=>$sz, 'SL'=>$SL, 'ss'=>$ss, 'ps'=>$ps, 'h'=>$h, 'w'=>min($maxw + 20, $w)];
  };
  $best = null;
  foreach ([[720, true], [560, true], [480, false]] as $v) { $Lo = $lay($v[0], $v[1]);
    foreach (['left', 'right'] as $side) foreach (['top', 'mid', 'bot'] as $vp) {
      $x0 = $side === 'left' ? 60 : $W - 60 - $Lo['w']; $y0 = $vp === 'top' ? 40 : ($vp === 'mid' ? (int)(($H - $Lo['h']) / 2) : $H - 40 - $Lo['h']); if ($y0 < 20) $y0 = 20;
      $r = [$x0 - 14, $y0 - 14, $x0 + $Lo['w'] + 14, $y0 + $Lo['h'] + 14]; $area = ($r[2] - $r[0]) * ($r[3] - $r[1]);
      $ov = 0; foreach ($boxes as $b) { $ix = max(0, min($r[2], $b[2]) - max($r[0], $b[0])); $iy = max(0, min($r[3], $b[3]) - max($r[1], $b[1])); $ov += $ix * $iy * $b[4]; }
      $bs = 0; $nn = 0; for ($gy = (int)max(0, $r[1] * $gh / $H); $gy < min($gh, $r[3] * $gh / $H); $gy++) for ($gx = (int)max(0, $r[0] * $gw / $W); $gx < min($gw, $r[2] * $gw / $W); $gx++) { $bs += $E[$gy][$gx]; $nn++; }
