  $lum = $n ? $sum / $n : 100; $P = ab_pal(); if (!isset($P[$tc])) $tc = 'white'; if (!isset($P[$pc])) $pc = 'yellow';
  $lo = function($k) use ($P) { return 0.3 * $P[$k][0] + 0.59 * $P[$k][1] + 0.11 * $P[$k][2]; };
  if ($lum > 160 && $lo($tc) > 150) $tc = 'navy'; if ($lum < 110 && $lo($tc) < 90) $tc = 'white';
  if ($lum > 160 && $lo($pc) > 200) $pc = 'red'; if ($lum < 110 && $lo($pc) < 70) $pc = 'yellow';
