  if ($price !== '') { $y += 22; $ps = $Lo['ps'];
    if ($old !== '') { $ob = imagettfbbox(30, 0, $fm, $old); $sh(30, $x0 + 2, $y + 30, $wh, $fm, $old); imagesetthickness($o, 4); imageline($o, $x0 - 2, $y + 22, $x0 + 8 + $ob[2] - $ob[0], $y + 16, $pcol); imagesetthickness($o, 1); $y += 40; }
    $sh($ps, $x0, $y + $ps, $pcol, $fb, $price);
    if ($disc !== '') { $bb = imagettfbbox($ps, 0, $fb, $price); $sh((int)($ps * 0.62), $x0 + $bb[2] - $bb[0] + 24, $y + $ps - 4, $pcol, $fb, $disc); } }
  return true;
}
// один баннер: сцена от DeepSeek → товар в сцене (правка фото Alibaba, а если её нет — сцена + вырезанный товар) → текст и цена на картинке
// №319 · чтобы баннеры в наборе не были однотипными: у каждого свой свет, обстановка, цвет, люди и план
function ab_style($i) {
  $L = [
    ['bright daylight, clean white Scandinavian interior, cool fresh tones, wide shot', 'a man in his 30s', 'clean'],
    ['cozy evening, warm lamps and golden light, deep rich colors, medium shot', 'a happy couple', 'warm'],
    ['bold pop-art style photo, acid neon colors, vivid magenta, lime and cyan accents, high contrast', 'young friends', 'acid'],
    ['muted film photography, desaturated soft colors, calm and elegant, matte look', 'a woman in her 40s', 'muted'],
    ['outdoors in summer nature, green garden or countryside, sunny, airy, wide shot', 'a family with two children', 'fresh'],
    ['modern urban loft, concrete and wood, bold teal and orange accents, dynamic angle', 'a teenager with a parent', 'bold'],
    ['winter outside the window, cozy warm home, contrast of cold and warm light', 'grandparents', 'cool'],
    ['dramatic dark moody studio light, deep shadows, luxury feel', 'a craftsman in work clothes', 'dark'],
  ];
  return $L[$i % count($L)];
}
function ab_make($p, $idx = 0) {
