  $sys = 'Ты придумываешь рекламный баннер интернет-магазина ИТК ГЛОБАЛ для одного товара. Ответь ТОЛЬКО JSON: {"scene_en":"описание обстановки на английском для ИИ-фотографа: где товар используется, живая реалистичная сцена С ЛЮДЬМИ, которые пользуются этим товаром или рядом с ним (диван — семья отдыхает в гостиной; холодильник — семья на кухне; отвёртка и инструменты — мастер в рабочей форме за работой; генератор и зарядная станция — семья на даче или в кемпинге вечером; детские товары — ребёнок с мамой; одежда — человек носит её). Люди европейской внешности, естественные, без надписей",'
       . '"season":"true, если товар особенно нужен именно в это время года (сейчас ' . (string)['', 'январь', 'февраль', 'март', 'апрель', 'май', 'июнь', 'июль', 'август', 'сентябрь', 'октябрь', 'ноябрь', 'декабрь'][(int)date('n')] . '), иначе false",'
       . '"topic":"короткая тематическая подпись по смыслу товара, 2–3 слова, правда без выдумок (Для уютного дома, Для дачи, Для мастера, На кухню, Для детской)",'
       . '"title_color":"цвет названия под тему и настроение баннера, одно из: white, cream, navy, black, yellow","price_color":"цвет цены, контрастный и подходящий к теме: red, yellow, orange, white, lime, pink, cyan, green, gold, coral",'
       . '"title":"что это за товар простыми словами, начни с названия вида товара (Генератор…, Отвёртка…, Диван…), до 30 символов","sub":"одна главная выгода по-русски, до 42 символов, без цены и без выдуманных цифр"}';
  $j = itcai_json((string)itcai_ask($sys, 'Товар: ' . $p['name'] . "\nКатегория: " . $p['cat'] . ' / ' . $p['subcat'] . "\nСтиль этого баннера: " . $sty[0] . "\nКто в кадре (если подходит к товару): " . $sty[1], 500, 30, true));
  $scene = (string)($j['scene_en'] ?? 'a realistic home interior where this product is used') . '. Visual style and color mood: ' . $sty[0] . '. People in the background: ' . $sty[1] . ' (if it fits the product). Close product-focused advertising shot.';
