    $sw = imagesx($out); $sh = (int)round($sw * $H / $W); if ($sh > imagesy($out)) { $sh = imagesy($out); $sw = (int)round($sh * $W / $H); }   // без растягивания: обрезаем по краям
    imagecopyresampled($o, $out, 0, 0, (int)((imagesx($out) - $sw) / 2), (int)((imagesy($out) - $sh) / 2), $W, $H, $sw, $sh); imagedestroy($out); }
