  if (!$o && !$plain) { imagedestroy($im); return ['skip'=>1, 'err'=>(!empty($r['err']) ? $r['err'] : 'на фото посторонний фон')]; }
  if (!$o) {
    $sc = ds_draw('Wide professional lifestyle advertising photo with real people: ' . $scene . '. Free space on the right side of the frame for the product, natural light, realistic, no text, no letters, no logos.', '1280*720', 'text, letters, words, watermark, logo, cartoon, deformed', 'wanx2.1-t2i-plus');
    if (!empty($sc['err'])) { imagedestroy($im); return ['err'=>'сцена: ' . $sc['err']]; }
    $bg = @imagecreatefromstring($sc['img']); if (!$bg) { imagedestroy($im); return ['err'=>'не получилась сцена']; }
    $o = imagecreatetruecolor($W, $H);
    $sw = imagesx($bg); $sh = (int)round($sw * $H / $W); if ($sh > imagesy($bg)) { $sh = imagesy($bg); $sw = (int)round($sh * $W / $H); }
    imagecopyresampled($o, $bg, 0, 0, (int)((imagesx($bg) - $sw) / 2), (int)((imagesy($bg) - $sh) / 2), $W, $H, $sw, $sh); imagedestroy($bg);
    $cut = ab_cutout($im);
    $k2 = min(560 / imagesx($cut), 520 / imagesy($cut)); $w2 = (int)(imagesx($cut) * $k2); $h2 = (int)(imagesy($cut) * $k2);
    $x2 = $W - $w2 - 70; $y2 = $H - $h2 - 30;
