  $tc = (string)($j['title_color'] ?? ''); $pc = (string)($j['price_color'] ?? '');
  if (!isset(ab_pal()[$tc]) || random_int(0, 1)) $tc = $mc[0];   // половина — по выбору ИИ, половина — по настроению стиля, чтобы не повторялось
  if (!isset(ab_pal()[$pc]) || random_int(0, 1)) $pc = $mc[1];
