  // чистый (только цена) → один знак → чистый → два элемента → один знак → чистый …
  $lvl = [0, 1, 0, 2, 1, 0, 1, 2][$idx % 8];
  $sale = $B[0][2] === 'sale';
  if ($sale && $lvl === 0) $lvl = 1;   // настоящая скидка — всегда видна
  $deco = ['pc'=>$pc, 'pstyle'=>$lvl === 0 ? [0, 0, 1][random_int(0, 2)] : random_int(0, 4), 'center'=>random_int(0, 1),
           'swoosh'=>$lvl > 0 && random_int(0, 2) === 0, 'stars'=>$lvl === 2 && random_int(0, 1), 'confetti'=>$lvl === 2 && in_array($sty[2] ?? '', ['acid', 'bold', 'fresh'], true) && random_int(0, 1)];
