    $tp = trim((string)($j['topic'] ?? ''));
    if ($cands && random_int(0, 1)) { $deco['corner'] = $cands[array_rand($cands)]; $ck = $pickc(5); $deco['ccol'] = $col($ck); $deco['ctc'] = $txc($ck); }
    elseif ($tp !== '' && mb_strlen($tp) <= 26) { $deco['topic'] = $tp; $deco['ticon'] = ['check', 'bolt', 'flame', 'gift', 'truck'][random_int(0, 4)]; }
  }
