}
// №312 · один баннер из очереди. 'idle' — очереди нет, 'more' — есть ещё, 'done' — закончили
function ab_step() {
  $j = ab_job_get(); if (!$j) return 'idle';
  $i = (int)$j['i'];
  if ($i < count($j['items'])) {
    $j['t'] = time(); $j['i'] = $i + 1; ab_job_set($j);      // сразу двигаем — двойной запуск не нарисует одно и то же
    $it = $j['items'][$i];
    for ($tries = 0; $tries < 8; $tries++) {
      try { $r = ab_make($it, $i + (int)($j['shift'] ?? 0)); } catch (Throwable $e) { $r = ['err'=>mb_substr($e->getMessage(), 0, 120)]; }
      if (empty($r['skip'])) break;
      $jj = ab_job_get() ?: $j; if (empty($jj['spare'])) break;   // №317 · фото с посторонним фоном — берём запасной товар
      $it = array_shift($jj['spare']); $jj['items'][$i] = $it; ab_job_set($jj); $j = $jj;
    }
    $j = ab_job_get() ?: $j;
    if (!empty($r['err'])) $j['err'][] = mb_substr($it['name'], 0, 30) . ': ' . $r['err']; else $j['done'][] = $r;
    $j['t'] = time(); ab_job_set($j);
    if (stripos((string)($r['err'] ?? ''), 'денег') !== false || stripos((string)($r['err'] ?? ''), 'Arrearage') !== false) { ab_finish($j); return 'done'; }
  }
  if ((int)$j['i'] >= count($j['items'])) { ab_finish($j); return 'done'; }
  return 'more';
}
// №314 · рисовать на сервере самому: ответили странице — и дорисовываем всю очередь в этом же запросе.
// Замок autoban_lock, чтобы два запроса не рисовали одновременно.
function ab_lock_free() { return time() - (int)itc_setting('autoban_lock', 0) > 150; }
function ab_run_loop() {
  if (!ab_lock_free()) return;
  ignore_user_abort(true); @set_time_limit(1200); $t0 = time();
  for ($k = 0; $k < 12 && time() - $t0 < 1000; $k++) {
    esim_set('autoban_lock', (string)time());
    $st = ab_step(); if ($st !== 'more') break;
  }
  esim_set('autoban_lock', '0');
}
function ab_reply_bg($arr) {
  ignore_user_abort(true); @set_time_limit(1200);
  $b = json_encode($arr, JSON_UNESCAPED_UNICODE);
  while (ob_get_level() > 0) @ob_end_clean();
  if (!headers_sent()) { header('Content-Type: application/json; charset=utf-8'); header('Connection: close'); header('Content-Encoding: none'); header('Content-Length: ' . strlen($b)); }
  echo $b; @flush();
  if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request();
  ab_run_loop(); exit;
}
// запустить следующий шаг в фоне (отдельным коротким запросом к себе же)
function ab_kick() {
  $c = ab_cfg(); $u = 'https://' . preg_replace('/[^a-z0-9.\-]/i', '', (string)($_SERVER['HTTP_HOST'] ?? 'itcpartner.store')) . '/api/api.php?action=autoban_step&key=' . $c['key'];
  $ch = curl_init($u); curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT_MS=>1500, CURLOPT_NOSIGNAL=>1]); @curl_exec($ch); curl_close($ch);
}
function ab_start($force = false, $mode = '') {
  $c = ab_cfg(); $j = ab_job_get();
  if ($j && time() - (int)($j['t'] ?? 0) < 1800) return ['ok'=>true, 'busy'=>1];
  // №343 · режим «по одному»: рисуем один баннер (если баннеров ещё нет совсем — сразу весь набор)
  $one = $c['mode'] === 'one' && $mode !== 'all' && ab_cur_count() > 0;
  $need = $one ? 1 : $c['n'];
  if ($one) { $u = ab_used_get(); foreach (ab_cur_pids() as $pp) if (!in_array($pp, $u, true)) $u[] = $pp; ab_used_set($u); }   // те, что уже висят, второй раз не берём
  try { $L = ab_pick($need, $c['prio']); $ids = array_column($L, 'id'); foreach (ab_pick(max(8, $need * 7), '') as $x) if (!in_array($x['id'], $ids, true)) { $L[] = $x; $ids[] = $x['id']; } } catch (Throwable $e) { $L = []; esim_set('autoban_err', 'выбор товаров: ' . mb_substr($e->getMessage(), 0, 150)); }
  if (!$L) { if ((string)itc_setting('autoban_err', '') === '') esim_set('autoban_err', 'нет подходящих товаров с фото и ценой'); esim_set('autoban_last', (string)time()); return ['ok'=>false, 'error'=>(string)itc_setting('autoban_err', 'нет подходящих товаров')]; }
  esim_set('autoban_err', '');
  $mp = function($r){ return ['id'=>$r['id'], 'name'=>$r['name'], 'cat'=>$r['cat'], 'subcat'=>$r['subcat'], 'price'=>$r['price'], 'old'=>(int)($r['old_price'] ?? 0), 'clicks'=>(int)($r['clicks'] ?? 0), 'cts'=>(int)($r['cts'] ?? 0), 'img'=>$r['img']]; };
  $L = array_map($mp, $L);
  ab_job_set(['t'=>time(), 'shift'=>random_int(0, 7), 'items'=>array_slice($L, 0, $need), 'spare'=>array_slice($L, $need), 'one'=>$one ? 1 : 0, 'i'=>0, 'done'=>[], 'err'=>[]]);
  return ['ok'=>true, 'n'=>min($need, count($L))];
}
function ab_finish($j) {
  if (!$j['done']) { ab_job_set(null); esim_set('autoban_last', (string)time()); esim_set('autoban_err', mb_substr(implode('; ', array_slice($j['err'], 0, 3)), 0, 240)); return; }   // не вышло — следующая попытка через N дней или по кнопке
  $keep = [];
  if (!empty($j['one'])) {   // №343 · новый — первым, остальные сдвигаются, самый старый (последний) уходит
    $n = ab_cfg()['n'];
    $keep = db()->query("SELECT id FROM banners WHERE id LIKE 'ab%' ORDER BY sort, id")->fetchAll(PDO::FETCH_COLUMN);
    $keep = array_slice($keep, 0, max(0, $n - count($j['done'])));
    if ($keep) db()->query("DELETE FROM banners WHERE id LIKE 'ab%' AND id NOT IN ('" . implode("','", array_map(function($x){ return preg_replace('/[^a-z0-9]/i', '', $x); }, $keep)) . "')");
    else db()->query("DELETE FROM banners WHERE id LIKE 'ab%'");
    $up = db()->prepare('UPDATE banners SET sort=?, active=1 WHERE id=?');
    foreach ($keep as $k => $id) $up->execute([500 + count($j['done']) + $k, $id]);
  } else db()->query("DELETE FROM banners WHERE id LIKE 'ab%'");
  db()->query("UPDATE banners SET active=0 WHERE id NOT LIKE 'ab%'");   // №351 · старые баннеры выключаем (не удаляем — их можно включить обратно в «Рекламе»)
  foreach ($j['done'] as $i => $b) {
    db()->prepare('INSERT INTO banners (id,title,subtitle,img,link,active,sort,pos_title,pos_sub,font_title,font_sub,size_title,size_sub) VALUES (?,?,?,?,?,1,?,?,?,?,?,?,?)')
       ->execute(['ab' . substr(md5($b['pid'] . microtime()), 0, 10), !empty($b['baked']) ? '' : $b['title'], !empty($b['baked']) ? '' : $b['sub'], $b['img'], '/?p=' . rawurlencode($b['pid']), 500 + $i, 'ml', 'ml', 'Roboto', 'Roboto', 40, 20]);
  }
  $used = array_slice(array_merge(array_column($j['done'], 'pid'), ab_used_get()), 0, 90);
  ab_used_set($used); esim_set('autoban_last', (string)time()); esim_set('autoban_err', mb_substr(implode('; ', array_slice($j['err'], 0, 3)), 0, 240));
  ab_job_set(null);
}
