  $r = ds_draw($prompt, '1024*1024', 'text, letters, numbers, digits, words, signs, watermark, logo, brand, close-up faces, deformed hands, blurry, low quality, dull colors', 'wanx2.1-t2i-plus');
  if (!empty($r['err'])) return ['ok'=>false, 'error'=>$r['err']];
  $f = esim_art_dir() . '/' . $k . '.jpg'; $im = @imagecreatefromstring($r['img']);
  if ($im) { $o = imagecreatetruecolor(512, 512); imagecopyresampled($o, $im, 0, 0, 0, 0, 512, 512, imagesx($im), imagesy($im)); @imagejpeg($o, $f, 85); imagedestroy($o); imagedestroy($im); }
  else @file_put_contents($f, $r['img']);
  return ['ok'=>is_file($f), 'c'=>$k, 'v'=>(int)@filemtime($f)];
}
function esim_art_make($c, $name) {
  $key = trim((string)itc_setting('dashscope_key', ''));
  if ($key === '') return ['ok'=>false, 'error'=>'Не задан ключ рисовалки (DashScope)'];
  $hint = ['CN'=>'the Great Wall of China winding over green mountains at sunset', 'TH'=>'tropical turquoise sea, white sand beach with palm trees and long-tail boats, Thai temple in the distance', 'VN'=>'Ha Long Bay limestone islands and a traditional boat', 'TR'=>'Istanbul mosque domes and hot air balloons over Cappadocia',
           'AE'=>'Dubai skyscrapers and desert dunes', 'EG'=>'the pyramids of Giza and the Nile', 'GE'=>'Caucasus mountains and an old stone church', 'JP'=>'Mount Fuji, cherry blossoms and a red torii gate', 'KR'=>'Seoul palace with mountains',
           'HK'=>'Hong Kong skyline at Victoria Harbour', 'MO'=>'Macau ruins of St. Paul and colorful streets', 'ID'=>'Bali rice terraces and a Balinese temple', 'MY'=>'Petronas towers and tropical forest', 'SG'=>'Marina Bay Sands and gardens',
           'IN'=>'the Taj Mahal', 'LK'=>'tea plantations and a tropical beach', 'MV'=>'water villas over a turquoise lagoon', 'KZ'=>'steppe, mountains and Astana tower', 'UZ'=>'Samarkand blue domes', 'KG'=>'mountain lake and yurts',
           'AM'=>'Mount Ararat and an ancient monastery', 'RS'=>'Belgrade fortress on the river', 'ME'=>'Adriatic bay with an old town', 'US'=>'Statue of Liberty and New York skyline', 'FR'=>'the Eiffel Tower', 'IT'=>'the Colosseum and Italian coast',
           'ES'=>'Sagrada Familia and Spanish beach', 'DE'=>'Neuschwanstein castle', 'GB'=>'Big Ben and a red bus', 'WORLD'=>'an airplane wing above the clouds at sunrise seen from the window'];
  $subj = substr($c, -2) === '_R' ? $name : ($hint[$c] ?? ('the most famous landmark and typical nature of ' . $name));
  $prompt = 'Professional travel photography, award-winning National Geographic style photo of ' . $subj . ', ' . ($c === 'WORLD' ? 'world travel concept' : (substr($c, -2) === '_R' ? 'regional travel' : $name)) . ', golden hour light, vivid but natural colors, sharp details, wide angle, realistic, high resolution, no text, no letters, no flags, no watermark';
  $r = ds_draw($prompt, '1024*1024', 'text, letters, words, watermark, logo, flag, cartoon, illustration, drawing, painting, 3d render, close-up faces, blurry, low quality', 'wanx2.1-t2i-plus');
  if (!empty($r['err'])) return ['ok'=>false, 'error'=>$r['err']];
  $img = $r['img'];
  $f = esim_art_dir() . '/' . $c . '.jpg';
  $im = @imagecreatefromstring($img);
  if ($im) { $o = imagecreatetruecolor(768, 768); imagecopyresampled($o, $im, 0, 0, 0, 0, 768, 768, imagesx($im), imagesy($im)); @imagejpeg($o, $f, 82); imagedestroy($o); imagedestroy($im); }
  else @file_put_contents($f, $img);
  return ['ok'=>is_file($f), 'c'=>$c, 'v'=>(int)@filemtime($f)];
}
function esim_rk() { $c = esim_cfg(); return ['k'=>$c['usd'] * (1 + $c['markup'] / 100), 'r'=>$c['round']]; }
// №331 · тариф «в день» (безлимит: быстрый трафик на день, дальше медленно) берётся на N дней. Возвращает [usd, дни, название].
function esim_pick($plan, $days) {
  if (empty($plan['daily'])) return [(float)$plan['usd'], (int)$plan['days'], (string)$plan['name']];
  $n = max(1, min(365, (int)$days ?: 1));
  return [esim_day_usd((float)$plan['usd'], $n), $n, $plan['name'].' · '.$n.' дн.'];
}
// №302 · скидка провайдера на тарифы «в день» за много дней (как в консоли eSIM Access):
// 1–4 дня −4%, 5–9 −8%, 10–19 −11%, 20–29 −15%, 30–365 −18%.
function esim_day_disc($n) { $n = (int)$n; return $n >= 30 ? 0.18 : ($n >= 20 ? 0.15 : ($n >= 10 ? 0.11 : ($n >= 5 ? 0.08 : 0.04))); }
function esim_day_usd($usd, $n) { return round($usd * $n * (1 - esim_day_disc($n)), 4); }
function esim_plan_out($p, $staff = false) {
  $o = ['code'=>$p['code'], 'name'=>$p['name'], 'gb'=>esim_gb($p['volume']), 'volume'=>$p['volume'], 'days'=>$p['days'], 'rub'=>esim_rub($p['usd']), 'topup'=>$p['topup'], 'daily'=>!empty($p['daily']), 'multi'=>!empty($p['multi']), 'nets'=>$p['nets'] ?? [], 'locs'=>$p['locs'] ?? ['CN']];
  if (!empty($p['daily'])) { $o['rub_d'] = []; foreach (array_merge(range(1, 30), [60, 90, 180, 365]) as $n) $o['rub_d'][(string)$n] = esim_rub(esim_day_usd($p['usd'], $n)); $o['rub'] = $o['rub_d']['1']; }   // №338 · любые дни 1–30 и 60/90/180/365
  if ($staff) $o['usd'] = $p['usd'];
  return $o;
}
function esim_row_out($r, $staff = false) {
  $o = ['id'=>$r['id'], 'order_id'=>$r['order_id'], 'name'=>$r['package_name'], 'gb'=>esim_gb((int)$r['volume']), 'volume'=>(int)$r['volume'], 'days'=>(int)$r['days'], 'rub'=>(int)$r['rub_price'],
        'status'=>$r['status'], 'iccid'=>$r['iccid'], 'ac'=>$r['ac'], 'qr'=>$r['qr_url'], 'short'=>$r['short_url'], 'smdp'=>$r['smdp_status'], 'esim'=>$r['esim_status'],
        'used'=>(int)$r['order_usage'], 'used_gb'=>esim_gb((int)$r['order_usage']), 'expires'=>$r['expired_time'], 'created'=>$r['created_at'], 'error'=>$r['error'], 'daily'=>stripos((string)$r['package_name'], '/day') !== false ? 1 : 0];
  try { $pl = esim_plan_find((string)$r['package_code']); $o['locs'] = $pl ? ($pl['locs'] ?? []) : []; } catch (Throwable $e) { $o['locs'] = []; }
  if ($staff) { $o['phone'] = $r['phone']; $o['usd'] = (float)$r['usd_cost']; $o['provider_order'] = $r['provider_order_no']; $o['tran'] = $r['esim_tran_no']; }
  return $o;
}
// Заказ у провайдера после оплаты. Идемпотентно: transactionId = наш id.
function esim_provision($id) {
  esim_table();
  $q = db()->prepare("SELECT e.*, IF(e.order_id='gift',1,COALESCE(o.paid,0)) paid FROM esim_orders e LEFT JOIN orders o ON o.id=e.order_id WHERE e.id=?"); $q->execute([$id]); $e = $q->fetch();
  if (!$e) return ['ok'=>false, 'error'=>'не найден'];
  if ((int)$e['paid'] !== 1) return ['ok'=>false, 'error'=>'не оплачен'];
  if ($e['status'] === 'ready') return ['ok'=>true];
  $upd = db()->prepare('UPDATE esim_orders SET status=?, error=?, updated_at=NOW() WHERE id=?');
  if (!$e['provider_order_no']) {
    $upd->execute(['provisioning', null, $id]);
    $pi = ['packageCode'=>$e['package_code'], 'count'=>1];
    $pl = esim_plan_find($e['package_code']); if ($pl && !empty($pl['daily'])) $pi['periodNum'] = max(1, (int)$e['days']);   // №331 · безлимит «в день» на N дней
    $r = esim_call('/esim/order', ['transactionId'=>$e['id'], 'packageInfoList'=>[$pi]]);
    $dup = !empty($r['errorCode']) && (string)$r['errorCode'] === '310402';
    if (empty($r['success']) && !$dup) {
      $msg = (string)($r['errorMsg'] ?? 'ошибка заказа'); if (!empty($r['errorCode']) && (string)$r['errorCode'] === '200007') $msg = 'У провайдера закончился баланс — пополните в консоли eSIM Access';
      $upd->execute(['failed', mb_substr($msg, 0, 490), $id]); return ['ok'=>false, 'error'=>$msg];
    }
    if (!$dup) db()->prepare('UPDATE esim_orders SET provider_order_no=? WHERE id=?')->execute([(string)($r['obj']['orderNo'] ?? ''), $id]);
  }
  // забираем профиль (ICCID и QR появляются через 3–10 секунд)
  for ($i = 0; $i < 5; $i++) {
    if (esim_refresh($id, true)) return ['ok'=>true];
    sleep(2);
  }
  $upd->execute(['provisioning', 'ждём профиль у провайдера', $id]);
  return ['ok'=>false, 'error'=>'профиль ещё готовится'];
}
// Обновить состояние eSIM у провайдера (по orderNo или transactionId). true — профиль есть.
function esim_refresh($id, $force = false) {
  $q = db()->prepare('SELECT * FROM esim_orders WHERE id=?'); $q->execute([$id]); $e = $q->fetch();
  if (!$e) return false;
  if (!$force && $e['checked_at'] && time() - strtotime($e['checked_at']) < 300) return !empty($e['iccid']);
  $body = $e['provider_order_no'] ? ['orderNo'=>$e['provider_order_no'], 'iccid'=>'', 'pager'=>['pageNum'=>1, 'pageSize'=>5]] : ['orderNo'=>'', 'iccid'=>'', 'transactionId'=>$e['id'], 'pager'=>['pageNum'=>1, 'pageSize'=>5]];
  $r = esim_call('/esim/query', $body);
  db()->prepare('UPDATE esim_orders SET checked_at=NOW() WHERE id=?')->execute([$id]);
  if (empty($r['success'])) return !empty($e['iccid']);
  $p = null; foreach (($r['obj']['esimList'] ?? []) as $x) { if (!empty($x['iccid'])) { $p = $x; break; } }
  if (!$p) return false;
  db()->prepare('UPDATE esim_orders SET status=?, provider_order_no=COALESCE(NULLIF(provider_order_no,\'\'),?), esim_tran_no=?, iccid=?, ac=?, qr_url=?, short_url=?, smdp_status=?, esim_status=?, order_usage=?, expired_time=?, error=NULL, updated_at=NOW() WHERE id=?')
    ->execute(['ready', (string)($p['orderNo'] ?? ''), (string)($p['esimTranNo'] ?? ''), (string)$p['iccid'], (string)($p['ac'] ?? ''), (string)($p['qrCodeUrl'] ?? ''), (string)($p['shortUrl'] ?? ''),
               (string)($p['smdpStatus'] ?? ''), (string)($p['esimStatus'] ?? ''), (int)($p['orderUsage'] ?? 0), (string)($p['expiredTime'] ?? ''), $id]);
  return true;
}
function esim_after_paid($orderId) {
  esim_table();
  try { $q = db()->prepare("SELECT id FROM esim_orders WHERE order_id=? AND status IN ('new','paid','failed','provisioning')"); $q->execute([$orderId]);
        foreach ($q->fetchAll() as $r) esim_provision($r['id']); } catch (Throwable $e) { error_log('esim_after_paid: '.$e->getMessage()); }
}

function apps_table() {
  static $done = false; if ($done) return; $done = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS customer_apps (phone VARCHAR(32) NOT NULL, app VARCHAR(32) NOT NULL, granted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, granted_by VARCHAR(100) NULL, PRIMARY KEY (phone, app)) DEFAULT CHARSET=utf8mb4"); } catch (Exception $e) {}
}
function apps_of($phone) {
  apps_table();
  try { $st = db()->prepare("SELECT app FROM customer_apps WHERE phone=? OR REPLACE(phone,' ','')=REPLACE(?,' ','')"); $st->execute([$phone, $phone]); return array_values(array_unique(array_map(function($r){return $r['app'];}, $st->fetchAll()))); }
  catch (Exception $e) { return []; }
}
function require_staff($s, $roles) {
  $sr = $s['staff_role'] ?? '';
  if ($sr === 'boss' || $sr === 'bossacct' || $sr === '') return; // boss/бухгалтер/старая сессия — полный доступ
  if (!in_array($sr, $roles, true)) fail('Недостаточно прав для этого действия', 403);
}

// Контекст сотрудника склада: [warehouse_id, конкретная_роль]. Для входа по общему коду склада роль = ''.
function wh_ctx($s) {
  if (($s['role'] ?? '') !== 'itc' || ($s['staff_role'] ?? '') !== 'warehouse') return [null, ''];
  $whid = $s['supplier_id'] ?? '';
  $wr = '';
  try {
    $q = db()->prepare("SELECT role FROM staff WHERE REPLACE(phone,' ','')=REPLACE(?,' ','') AND warehouse_id=? AND role IN ('wh_manager','wh_keeper','wh_worker') LIMIT 1");
    $q->execute([$s['phone'] ?? '', $whid]);
    $wr = $q->fetchColumn() ?: '';
  } catch (Exception $e) {}
  return [$whid, $wr];
}

// Склад, закреплённый за партнёром (для сессии role=partner). '' если не назначен.
/* №274: постоянный номер товара внутри заказа (1, 2, 3…), по порядку позиций.
   Выдаётся один раз и больше не меняется. Возвращает [id позиции => номер]. */
function itc_item_subno_many($oids) {
  static $col = false;
  $out = [];
  if (!$oids) return $out;
  if (!$col) { try { db()->query("ALTER TABLE order_items ADD COLUMN sub_no INT NULL"); } catch (Exception $e) {} $col = true; }
  $oids = array_values($oids);
  $in = implode(',', array_fill(0, count($oids), '?'));
  $q = db()->prepare("SELECT id, order_id, sub_no FROM order_items WHERE order_id IN ($in) ORDER BY order_id, id");
  $q->execute($oids);
  $by = [];
  foreach ($q->fetchAll() as $r) $by[$r['order_id']][] = $r;
  $up = db()->prepare('UPDATE order_items SET sub_no=? WHERE id=?');
  foreach ($by as $list) {
    $mx = 0;
    foreach ($list as $r) if ((int)$r['sub_no'] > $mx) $mx = (int)$r['sub_no'];
    foreach ($list as $r) {
      $n = (int)$r['sub_no'];
      if ($n <= 0) { $n = ++$mx; try { $up->execute([$n, $r['id']]); } catch (Exception $e) {} }
      $out[$r['id']] = $n;
    }
  }
  return $out;
}

/* №276: СОСТОЯНИЕ КАЖДОГО ТОВАРА ЗАКАЗА для выдачи по частям.
   point — лежит на пункте и не выдан; handed — выдан; way — ещё едет;
   big — крупногабарит, выдаётся со склада, а не с пункта.
   Старая приёмка заказа целиком (wh_received_at) = все товары на пункте,
   старая выдача целиком (picked_up_at) = все выданы. */
function itc_items_cols() {
  static $done = false; if ($done) return; $done = true;
  foreach (["ALTER TABLE order_items ADD COLUMN pvz_rcv_at DATETIME NULL",
            "ALTER TABLE order_items ADD COLUMN pvz_rcv_wh VARCHAR(64) NULL",
            "ALTER TABLE order_items ADD COLUMN handed_at DATETIME NULL",
            "ALTER TABLE order_items ADD COLUMN handed_wh VARCHAR(64) NULL",
            "ALTER TABLE order_items ADD COLUMN ret_status VARCHAR(16) NULL",
            "ALTER TABLE order_items ADD COLUMN memo_at DATETIME NULL",
            "ALTER TABLE order_items ADD COLUMN pvz_shelf VARCHAR(12) NULL"] as $sq) { try { db()->query($sq); } catch (Exception $e) {} }
}
function itc_items_state($oid) {
  itc_items_cols();
  $out = ['items'=>[], 'total'=>0, 'point'=>0, 'handed'=>0, 'way'=>0, 'big'=>0, 'ret'=>0];
  try {
    $oq = db()->prepare('SELECT o.num,o.wh_received_at,o.dest_received_at,o.picked_up_at,w.kind FROM orders o LEFT JOIN warehouses w ON w.id=o.warehouse_id WHERE o.id=?');
    $oq->execute([$oid]); $o = $oq->fetch();
  } catch (Exception $e) { $o = null; }
  if (!$o) return $out;
  itc_item_subno_many([$oid]);
  try {
    $q = db()->prepare('SELECT i.id,i.product_id,i.name,i.qty,i.price,i.sub_no,COALESCE(i.oversize,0) ov,i.pvz_rcv_at,i.handed_at,i.ret_status,i.pvz_shelf,p.img,p.weight_kg FROM order_items i LEFT JOIN products p ON p.id=i.product_id WHERE i.order_id=? ORDER BY i.sub_no,i.id');
    $q->execute([$oid]); $rows = $q->fetchAll();
  } catch (Exception $e) {
    /* запасной путь: без веса и статуса возврата, чтобы выдача не встала */
    try { $q = db()->prepare('SELECT i.id,i.product_id,i.name,i.qty,i.price,i.sub_no,0 ov,i.pvz_rcv_at,i.handed_at,NULL ret_status,p.img,0 weight_kg FROM order_items i LEFT JOIN products p ON p.id=i.product_id WHERE i.order_id=? ORDER BY i.sub_no,i.id');
          $q->execute([$oid]); $rows = $q->fetchAll(); } catch (Exception $e2) { $rows = []; }
  }
  $arrived = !empty($o['wh_received_at']) || !empty($o['dest_received_at']);
  $isPvz = (($o['kind'] ?? '') === 'pvz');
  foreach ($rows as $r) {
    if (!empty($r['ret_status']) && $r['ret_status'] !== 'rejected') $st = 'ret';          // №278: отказ / возврат
    elseif (!empty($r['handed_at']) || !empty($o['picked_up_at'])) $st = 'handed';
    elseif ($isPvz && (int)$r['ov'] === 1) $st = 'big';
    elseif (!empty($r['pvz_rcv_at']) || $arrived) $st = 'point';
    else $st = 'way';
    $out[$st]++;
    if ($st !== 'big' && $st !== 'ret') $out['total']++;
    $out['items'][] = ['shelf'=>(string)($r['pvz_shelf'] ?? ''), 'id'=>$r['id'], 'pid'=>$r['product_id'] ?? '', 'price'=>(int)($r['price'] ?? 0), 'heavy'=>(((int)$r['ov'] === 1) || ((float)($r['weight_kg'] ?? 0) > 5)) ? 1 : 0, 'code'=>$o['num'].'-'.(int)$r['sub_no'], 'name'=>$r['name'], 'qty'=>(int)$r['qty'], 'img'=>$r['img'] ?? '', 'st'=>$st];
  }
  return $out;
}
/* Кто сканирует на пункте: точка и имя для журнала. Пункт (партнёр) или оператор склада. */
function pvz_ctx($s) {
  $role = $s['role'] ?? ''; $sr = $s['staff_role'] ?? '';
  $wh = ''; $who = '';
  if ($role === 'partner') {
    try { $pq = db()->prepare('SELECT warehouse_id,name FROM partners WHERE id=?'); $pq->execute([$s['supplier_id']]); $pr = $pq->fetch();
          $wh = $pr['warehouse_id'] ?? ''; $who = ($pr['name'] ?? '') ?: 'Партнёр'; } catch (Exception $e) {}
  } elseif ($role === 'itc' && $sr === 'warehouse') {
    $wh = $s['supplier_id'] ?? '';
    try { $nq=db()->prepare('SELECT name FROM warehouses WHERE id=?'); $nq->execute([$wh]); $who=($nq->fetchColumn()?:'Склад').' · оператор'; } catch (Exception $e) { $who='Оператор'; }
  } else {
    fail('Доступно пункту выдачи или оператору склада', 403);
  }
  if (!$wh) fail('За вами не закреплена точка');
  return [$wh, $who];
}
function pickup_tokens_table() {
  static $done = false; if ($done) return; $done = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS pickup_tokens (token VARCHAR(40) NOT NULL PRIMARY KEY, order_id VARCHAR(64) NOT NULL, day DATE NOT NULL, created_at DATETIME NOT NULL, KEY order_day (order_id, day))"); } catch (Exception $e) {}
}
/* Найти заказ по QR покупателя. QR действует только в день выдачи. */
function pickup_by_token($raw, $wh) {
  pickup_tokens_table();
  $k = '';
  $j = json_decode(trim((string)$raw), true);
  if (is_array($j) && ($j['t'] ?? '') === 'p' && !empty($j['k'])) $k = (string)$j['k'];
  elseif (preg_match('/^[a-f0-9]{16}$/', trim((string)$raw))) $k = trim((string)$raw);
  if ($k === '') fail('Это не QR покупателя для получения');
  $tq = db()->prepare('SELECT order_id, day, (day = CURDATE()) today FROM pickup_tokens WHERE token=?');
  $tq->execute([$k]); $t = $tq->fetch();
  if (!$t) fail('QR не найден. Попросите покупателя открыть QR заново');
  if ((int)$t['today'] !== 1) fail('QR устарел: он действовал '.date('d.m.Y', strtotime($t['day'])).'. Попросите покупателя открыть QR заново — на сегодня будет новый');
  $oq = db()->prepare('SELECT o.id,o.num,o.phone,o.addr_name,o.warehouse_id,o.dest_warehouse_id,o.picked_up_at,w.name wname FROM orders o LEFT JOIN warehouses w ON w.id=o.warehouse_id WHERE o.id=? AND o.paid=1');
  $oq->execute([$t['order_id']]); $o = $oq->fetch();
  if (!$o) fail('Заказ не найден');
  if ($o['warehouse_id'] !== $wh && ($o['dest_warehouse_id'] ?? '') !== $wh) fail('Этот заказ получают в другом пункте: '.($o['wname'] ?: 'не указан'));
  $o['token'] = $k;
  return $o;
}

/* №278: ВОЗВРАТЫ. Одна заявка — один товар (один номер М-1069-2). */
