/* №280: ПАМЯТКА О ВОЗВРАТЕ — выдаётся при каждой выдаче (п. 3–4 ст. 26.1 ЗоЗПП).
   Без неё срок отказа от товара без брака — 3 месяца вместо 7 дней. */
function return_memo_text() {
  return 'Памятка о возврате. Товар без недостатков можно вернуть в течение 7 дней после получения, если сохранены его товарный вид, потребительские свойства, упаковка и документ о покупке; расходы на обратную доставку несёт покупатель. '
       . 'Товар с недостатками — в течение гарантийного срока, а если он не установлен — в течение 2 лет со дня получения. '
       . 'Заявление подаётся в личном кабинете: «Заявление на возврат». Деньги возвращаются в течение 10 дней со дня требования. ООО «Интернациональная Торговая Компания».';
}
/* Уведомление боссам ИТК (как об оплате заказа). */
function notify_boss($title, $text, $url = '/') {
  try {
    $tails = [];
    foreach (db()->query("SELECT phone FROM staff WHERE role='boss' AND active=1")->fetchAll(PDO::FETCH_COLUMN) as $ph) { $t = ph_tail10($ph); if ($t !== '') $tails[$t] = true; }
    if (!$tails) return 0;
    fcm_table(); $toks = [];
    foreach (db()->query('SELECT token,phone FROM push_tokens')->fetchAll() as $r) if (isset($tails[ph_tail10($r['phone'])])) $toks[] = $r['token'];
    if (!$toks) return 0;
    $r = fcm_send($toks, $title, $text, $url); return (int)($r['sent'] ?? 0);
  } catch (Throwable $e) { return 0; }
}
/* Заказ по коду: QR покупателя, наклейка товара (М-1069-2) или номер заказа.
   Возвращает [заказ, номер товара или 0]. Проверяет, что заказ этой точки. */
function order_for_return($raw, $wh) {
  $raw = trim((string)$raw);
  $j = json_decode($raw, true);
  if (is_array($j) && ($j['t'] ?? '') === 'p') { $o = pickup_by_token($raw, $wh); return [$o, 0]; }
  $rk = (is_array($j) && !empty($j['c'])) ? (string)($j['k'] ?? '') : null;
  if (is_array($j) && !empty($j['c'])) $raw = (string)$j['c'];
  $raw = strtoupper(strtr($raw, ['М'=>'M','м'=>'M',' '=>'']));
  $sub = 0;
  if (preg_match('/^(.*\d)-(\d{1,3})$/', $raw, $m)) { $raw = $m[1]; $sub = (int)$m[2]; }
  $digits = preg_replace('/\D/', '', $raw);
  if ($digits === '') fail('Не удалось разобрать номер');
  $oq = db()->prepare("SELECT o.id,o.num,o.phone,o.addr_name,o.warehouse_id,o.dest_warehouse_id,o.picked_up_at,w.name wname FROM orders o LEFT JOIN warehouses w ON w.id=o.warehouse_id WHERE REGEXP_REPLACE(o.num,'[^0-9]','')=? AND o.paid=1 ORDER BY o.created_at DESC LIMIT 1");
  $oq->execute([$digits]); $o = $oq->fetch();
  if (!$o) fail('Заказ не найден');
  if ($o['warehouse_id'] !== $wh && ($o['dest_warehouse_id'] ?? '') !== $wh) fail('Этот заказ не вашей точки: '.($o['wname'] ?: 'другой пункт'));
  /* №284: наклейка товара по скану — проверяем ключ */
  if ($rk !== null && $sub > 0) {
    itc_item_subno_many([$o['id']]); $km = itc_item_keys_many([$o['id']]);
    $iq = db()->prepare('SELECT id FROM order_items WHERE order_id=? AND sub_no=? LIMIT 1'); $iq->execute([$o['id'], $sub]); $iid = $iq->fetchColumn();
    $real = $iid ? (string)($km[$iid] ?? '') : '';
    if ($rk === '' || $real === '' || !hash_equals($real, $rk)) fail('Наклейка не подлинная: ключ не совпадает. Сообщите в ИТК');
  }
  return [$o, $sub];
}

/* №284: ЗАЩИТА НАКЛЕЕК ОТ ПОДДЕЛКИ. У каждой позиции заказа и у каждого
   заказа свой секретный ключ — случайная строка, создаётся один раз. Ключ
   зашит в QR наклейки; сервер принимает наклейку, только если ключ совпал.
   Номер с бумажки без ключа уже не пройдёт как скан. */
function itc_item_keys_many($oids) {
  static $col = false; $out = [];
  if (!$oids) return $out;
  if (!$col) { try { db()->query("ALTER TABLE order_items ADD COLUMN lbl_key VARCHAR(24) NULL"); } catch (Exception $e) {} $col = true; }
  $oids = array_values($oids); $in = implode(',', array_fill(0, count($oids), '?'));
  try {
    $q = db()->prepare("SELECT id, lbl_key FROM order_items WHERE order_id IN ($in)"); $q->execute($oids);
    $up = db()->prepare('UPDATE order_items SET lbl_key=? WHERE id=? AND (lbl_key IS NULL OR lbl_key=\'\')');
    foreach ($q->fetchAll() as $r) {
      $k = (string)($r['lbl_key'] ?? '');
      if ($k === '') { $k = bin2hex(random_bytes(6)); $up->execute([$k, $r['id']]); }
      $out[$r['id']] = $k;
    }
  } catch (Exception $e) {}
  return $out;
}
function order_lbl_keys($oids) {
  static $col = false; $out = [];
  if (!$oids) return $out;
  if (!$col) { try { db()->query("ALTER TABLE orders ADD COLUMN lbl_key VARCHAR(24) NULL"); } catch (Exception $e) {} $col = true; }
  $oids = array_values($oids); $in = implode(',', array_fill(0, count($oids), '?'));
  try {
    $q = db()->prepare("SELECT id, lbl_key FROM orders WHERE id IN ($in)"); $q->execute($oids);
    $up = db()->prepare('UPDATE orders SET lbl_key=? WHERE id=? AND (lbl_key IS NULL OR lbl_key=\'\')');
    foreach ($q->fetchAll() as $r) {
      $k = (string)($r['lbl_key'] ?? '');
      if ($k === '') { $k = bin2hex(random_bytes(6)); $up->execute([$k, $r['id']]); }
      $out[$r['id']] = $k;
    }
  } catch (Exception $e) {}
  return $out;
}
/* Скан коробки: если пришла наклейка-QR (JSON), ключ обязан совпасть с ключом заказа. */
function scan_key_check($oid) {
  if (empty($GLOBALS['scan_json'])) return;          // номер введён руками — проверяется отдельно
  $k = (string)($GLOBALS['scan_key'] ?? '');
  $m = order_lbl_keys([$oid]); $real = (string)($m[$oid] ?? '');
  if ($k === '' || $real === '' || !hash_equals($real, $k)) fail('Наклейка не подлинная: ключ не совпадает. Не принимайте коробку, сообщите в ИТК');
}

/* №285: СКЛАДСКОЙ ТОВАР ИТК (запас в России). Партия = один вариант товара,
   единица = одна штука со своей наклейкой С-партия-номер и секретным ключом.
   Наклейка клеится один раз в Китае и больше не переклеивается. */
function stock_tables() {
  static $done = false; if ($done) return; $done = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS stock_batches (
      id INT AUTO_INCREMENT PRIMARY KEY, product_id VARCHAR(64) NOT NULL, name VARCHAR(400) NULL, img TEXT NULL,
      qty INT NOT NULL DEFAULT 0, source VARCHAR(16) NOT NULL DEFAULT 'purchase', order_id VARCHAR(64) NULL, order_num VARCHAR(40) NULL,
      note VARCHAR(400) NULL, created_by VARCHAR(160) NULL, created_at DATETIME NOT NULL, KEY prod (product_id))"); } catch (Exception $e) {}
  try { db()->query("CREATE TABLE IF NOT EXISTS stock_units (
      id INT AUTO_INCREMENT PRIMARY KEY, batch_id INT NOT NULL, seq INT NOT NULL, code VARCHAR(40) NOT NULL, lbl_key VARCHAR(24) NOT NULL,
      status VARCHAR(16) NOT NULL DEFAULT 'china', cell VARCHAR(40) NULL, rcv_at DATETIME NULL, rcv_by VARCHAR(160) NULL,
      order_id VARCHAR(64) NULL, order_item_id VARCHAR(64) NULL, sold_at DATETIME NULL, created_at DATETIME NOT NULL,
      UNIQUE KEY code (code), KEY batch (batch_id), KEY st (status))"); } catch (Exception $e) {}
}
/* №287: ОСТАТОК И РЕЗЕРВ. Резерв — позиция заказа, которую отдадим со склада
   (stock_reserved=1); пока кладовщик не привязал к ней единицы, она «съедает»
   свободный остаток. Свободно = на складе − ещё не собранные резервы. */
function stock_cols() {
  static $done = false; if ($done) return; $done = true;
  stock_tables();
  foreach (["ALTER TABLE order_items ADD COLUMN stock_reserved TINYINT NOT NULL DEFAULT 0",
            "ALTER TABLE stock_units ADD COLUMN wh_id VARCHAR(64) NULL",
            "ALTER TABLE stock_batches ADD COLUMN bought_at DATETIME NULL",
            "ALTER TABLE stock_batches ADD COLUMN bought_by VARCHAR(160) NULL",
            "ALTER TABLE stock_batches ADD COLUMN buy_ref VARCHAR(120) NULL",
            "ALTER TABLE stock_batches ADD COLUMN cn_rcv_at DATETIME NULL",
            "ALTER TABLE stock_batches ADD COLUMN cn_rcv_by VARCHAR(160) NULL",
            "ALTER TABLE stock_batches ADD COLUMN ship_id INT NULL",
            "ALTER TABLE stock_batches ADD COLUMN container_id VARCHAR(64) NULL",
            "ALTER TABLE stock_shipments ADD COLUMN container_id VARCHAR(64) NULL",
            "CREATE TABLE IF NOT EXISTS stock_shipments (id INT AUTO_INCREMENT PRIMARY KEY, carrier VARCHAR(120) NULL, ref VARCHAR(160) NULL, note VARCHAR(400) NULL,
               status VARCHAR(12) NOT NULL DEFAULT 'sent', created_by VARCHAR(160) NULL, sent_at DATETIME NOT NULL, arrived_at DATETIME NULL, closed_by VARCHAR(160) NULL)"] as $sq) { try { db()->query($sq); } catch (Exception $e) {} }
}
function stock_available($pid) {
  stock_cols();
  try {
    $q = db()->prepare("SELECT COUNT(*) FROM stock_units u JOIN stock_batches b ON b.id=u.batch_id WHERE b.product_id=? AND u.status='stock' AND (u.cell IS NULL OR u.cell<>'БРАК')");
    $q->execute([$pid]); $on = (int)$q->fetchColumn();
    $r = db()->prepare("SELECT COALESCE(SUM(GREATEST(i.qty - (SELECT COUNT(*) FROM stock_units su WHERE su.order_item_id=i.id),0)),0)
                          FROM order_items i WHERE i.product_id=? AND i.stock_reserved=1");
    $r->execute([$pid]); $res = (int)$r->fetchColumn();
    return max(0, $on - $res);
  } catch (Exception $e) { return 0; }
}
/* Заказ оплачен: сколько штук отдаём со склада в России. Кто раньше оплатил,
   тому и достаётся остаток. Хватает на всё — вся позиция со склада. Хватает
   на часть (на складе 5, заказали 7) — позиция делится на две строки: 5 шт со
   склада и 2 шт под выкуп в Китае, у каждой свой номер и наклейка.
   Возвращает, сколько штук зарезервировано на складе. */
function stock_reserve_part($orderId, $itemId, $pid, $qty) {
  stock_cols();
  try {
    $q = db()->prepare('SELECT * FROM order_items WHERE id=?'); $q->execute([$itemId]); $row = $q->fetch(PDO::FETCH_ASSOC);
    if (!$row) return 0;
    if ((int)$row['stock_reserved'] === 1) return (int)$row['qty'];
    $qty = (int)$row['qty'];
    $av = stock_available($pid);
    if ($qty < 1 || $av < 1) return 0;
    if ($av >= $qty) { db()->prepare('UPDATE order_items SET stock_reserved=1 WHERE id=?')->execute([$itemId]); return $qty; }
    // делим позицию: $av со склада, остальное — новая строка под выкуп в Китае
    $rest = $qty - $av;
    $new = $row; unset($new['id']);
    foreach (['sub_no','lbl_key','pvz_rcv_at','pvz_rcv_wh','handed_at','handed_wh','memo_at','ret_status'] as $k) if (array_key_exists($k, $new)) $new[$k] = null;
    $new['qty'] = $rest; $new['stock_reserved'] = 0;
    $cols = array_keys($new);
    $sql = 'INSERT INTO order_items ('.implode(',', array_map(function($c){ return '`'.$c.'`'; }, $cols)).') VALUES ('.implode(',', array_fill(0, count($cols), '?')).')';
    db()->beginTransaction();
    db()->prepare('UPDATE order_items SET qty=?, stock_reserved=1 WHERE id=?')->execute([$av, $itemId]);
    db()->prepare($sql)->execute(array_values($new));
    db()->commit();
    return $av;
  } catch (Exception $e) { try { if (db()->inTransaction()) db()->rollBack(); } catch (Exception $e2) {} return 0; }
}
/* Разбор складской наклейки: QR {"t":"s","c":"С-0045-07","k":…} или номер руками. */
function stock_unit_by_code($raw) {
  stock_cols();
  $raw = trim((string)$raw); $j = json_decode($raw, true);
  $isScan = is_array($j) && (($j['t'] ?? '') === 's');
  $code = $isScan ? (string)($j['c'] ?? '') : $raw;
  $code = strtoupper(strtr($code, ['С'=>'C','с'=>'C',' '=>'']));
  if (!preg_match('/^C-(\d{1,6})-(\d{1,3})$/', $code, $m)) return null;
  $q = db()->prepare("SELECT u.*, b.product_id, b.name, b.qty bqty FROM stock_units u JOIN stock_batches b ON b.id=u.batch_id WHERE u.batch_id=? AND u.seq=?");
  $q->execute([(int)$m[1], (int)$m[2]]); $u = $q->fetch();
  if (!$u) fail('Складская наклейка '.$code.' не найдена');
  if ($isScan) { $k = (string)($j['k'] ?? ''); if ($k === '' || !hash_equals((string)$u['lbl_key'], $k)) fail('Наклейка не подлинная: ключ не совпадает. Не принимайте товар, сообщите в ИТК'); }
  $u['_manual'] = !$isScan;
  return $u;
}

/* №289: АДРЕСА СКЛАДА В ГВАРДЕЙСКОМ. Стеллажи А Б В Г Д Е Ж И (без З — путается
   с цифрой 3), полки 1–5 снизу вверх: «Б-3». Паллетные места на полу П-01…,
   зоны ПРИЁМ (принято, не разложено) и БРАК (не продаётся). Адрес — отдельная
   наклейка на полке; товар к адресу привязывает система, наклейку товара не трогаем. */
function stock_cells_ensure() {
  static $done = false; if ($done) return; $done = true;
  stock_cols();
  try { db()->query("CREATE TABLE IF NOT EXISTS stock_cells (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) NOT NULL, kind VARCHAR(10) NOT NULL, sort INT NOT NULL DEFAULT 0, UNIQUE KEY code (code))"); } catch (Exception $e) {}
  try { db()->query("CREATE TABLE IF NOT EXISTS stock_moves (id INT AUTO_INCREMENT PRIMARY KEY, unit_id INT NOT NULL, from_cell VARCHAR(20) NULL, to_cell VARCHAR(20) NULL, by_name VARCHAR(160) NULL, at DATETIME NOT NULL, KEY u (unit_id))"); } catch (Exception $e) {}
  try {
    if ((int)db()->query('SELECT COUNT(*) FROM stock_cells')->fetchColumn() > 0) return;
    $ins = db()->prepare('INSERT IGNORE INTO stock_cells (code,kind,sort) VALUES (?,?,?)');
    $ins->execute(['ПРИЁМ','zone',0]);
    $racks = ['А','Б','В','Г','Д','Е','Ж','И'];
    foreach ($racks as $ri => $r) for ($sh = 1; $sh <= 5; $sh++) $ins->execute([$r.'-'.$sh, 'shelf', 100 + $ri * 10 + $sh]);
    for ($n = 1; $n <= 10; $n++) $ins->execute(['П-'.str_pad((string)$n, 2, '0', STR_PAD_LEFT), 'pallet', 1000 + $n]);
    $ins->execute(['БРАК','zone',9999]);
  } catch (Exception $e) {}
}
/* Адрес по скану: QR {"t":"cell","i":id} или адрес, набранный руками («б-3», «П-02»). */
function stock_cell_by_code($raw) {
  stock_cells_ensure();
  $raw = trim((string)$raw); $j = json_decode($raw, true);
  if (is_array($j) && ($j['t'] ?? '') === 'cell') {
    $q = db()->prepare('SELECT * FROM stock_cells WHERE id=?'); $q->execute([(int)($j['i'] ?? 0)]); $c = $q->fetch();
    return $c ?: null;
  }
  $code = mb_strtoupper(str_replace(' ', '', $raw));
  $code = strtr($code, ['A'=>'А','B'=>'В','E'=>'Е','P'=>'П','.'=>'-','_'=>'-']);
  if ($code === 'ПРИЕМ') $code = 'ПРИЁМ';
  $q = db()->prepare('SELECT * FROM stock_cells WHERE code=?'); $q->execute([$code]); $c = $q->fetch();
  return $c ?: null;
}
function stock_is_cell_scan($raw) {
  $j = json_decode(trim((string)$raw), true);
  return is_array($j) && ($j['t'] ?? '') === 'cell';
}

/* №300: склад в Китае не может ставить складской товар на приход в России */
function stock_wh_is_china($wh) {
  if ((string)$wh === '') return false;
  try { $q = db()->prepare('SELECT country, city FROM warehouses WHERE id=?'); $q->execute([$wh]); $w = $q->fetch();
        return $w && preg_match('/кита|china|^cn$|中国|广州|佛山|义乌|深圳/ui', trim((string)$w['country']).' '.trim((string)$w['city'])); } catch (Exception $e) { return false; }
}

/* №310: СБОРНЫЕ КОРОБКИ. Мелкий товар (позиции заказов М-… и складские
   штуки С-…) кладётся в одну коробку К-… со своим QR и ключом. В контейнер
   грузятся коробки. В России один скан коробки принимает всё содержимое;
   недостача всплывает при разборе. Зона коробки — склад-получатель в России
   (хаб): все вещи в коробке едут в одну зону. */
function pack_tables() {
  static $done = false; if ($done) return; $done = true;
  foreach (["CREATE TABLE IF NOT EXISTS pack_boxes (id INT AUTO_INCREMENT PRIMARY KEY, zone VARCHAR(32) NULL, zone_wh VARCHAR(64) NULL,
              status VARCHAR(12) NOT NULL DEFAULT 'open', lbl_key VARCHAR(32) NOT NULL, weight DECIMAL(8,2) NULL, note VARCHAR(255) NULL,
              created_by VARCHAR(160) NULL, created_at DATETIME NOT NULL, closed_at DATETIME NULL, shipped_at DATETIME NULL,
              arrived_at DATETIME NULL, arrived_by VARCHAR(160) NULL, ship_ref VARCHAR(80) NULL)",
            "CREATE TABLE IF NOT EXISTS pack_items (id INT AUTO_INCREMENT PRIMARY KEY, box_id INT NOT NULL, kind VARCHAR(8) NOT NULL,
              ref_id VARCHAR(64) NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(255) NULL, order_id VARCHAR(64) NULL,
              added_at DATETIME NOT NULL, missing TINYINT NOT NULL DEFAULT 0, KEY(box_id), KEY(kind, ref_id))",
            "ALTER TABLE order_items ADD COLUMN ru_rcv_at DATETIME NULL"] as $sq) { try { db()->exec($sq); } catch (Exception $e) {} }
}
function pack_code($id) { return 'К-'.str_pad((string)$id, 4, '0', STR_PAD_LEFT); }
/* Хаб (склад в России), куда едет заказ: пункт → его родительский склад */
function pack_hub_of_wh($whId) {
  if ((string)$whId === '') return null;
  $q = db()->prepare('SELECT id,code,kind,parent_id FROM warehouses WHERE id=?'); $q->execute([$whId]); $w = $q->fetch();
  if (!$w) return null;
  if (($w['kind'] ?? '') === 'pvz' && !empty($w['parent_id'])) { $q->execute([$w['parent_id']]); $p = $q->fetch(); if ($p) return ['id'=>$p['id'],'code'=>$p['code']]; }
  return ['id'=>$w['id'],'code'=>$w['code']];
}
function pack_central_hub() {
  try { $q = db()->query("SELECT id,code FROM warehouses WHERE code='GVS' LIMIT 1"); $w = $q->fetch(); if ($w) return $w; } catch (Exception $e) {}
  return ['id'=>'', 'code'=>'GVS'];
}
/* Разобрать наклейку: позиция заказа М-… или складская штука С-… (с проверкой ключа) */
function pack_resolve($raw) {
  $raw = trim((string)$raw); $j = json_decode($raw, true);
  if ((is_array($j) && ($j['t'] ?? '') === 's') || preg_match('/^\s*[СC]-\d{1,6}-\d{1,3}\s*$/u', $raw)) {
    stock_cols(); $u = stock_unit_by_code($raw);
    if (!$u) fail('Складская наклейка не распознана');
    if (is_array($j) && (string)($j['k'] ?? '') !== '' && !empty($u['lbl_key']) && !hash_equals((string)$u['lbl_key'], (string)$j['k'])) fail('Наклейка '.$u['code'].' не подлинная');
    $nq = db()->prepare("SELECT COALESCE(NULLIF(p.name,''),b.name) FROM stock_batches b LEFT JOIN products p ON p.id=b.product_id WHERE b.id=?"); $nq->execute([$u['batch_id']]);
    $hub = null;
    if ($u['status'] === 'sold' && !empty($u['order_id'])) { $oq = db()->prepare('SELECT warehouse_id FROM orders WHERE id=?'); $oq->execute([$u['order_id']]); $hub = pack_hub_of_wh($oq->fetchColumn()); }
    if (!$hub) $hub = pack_central_hub();
    return ['kind'=>'unit','ref'=>(string)$u['id'],'code'=>$u['code'],'name'=>(string)$nq->fetchColumn(),'order_id'=>$u['order_id'] ?? null,'zone'=>$hub['code'],'zone_wh'=>$hub['id'],'status'=>$u['status']];
  }
  $isScan = is_array($j); $key = $isScan ? (string)($j['k'] ?? '') : '';
  $c = (is_array($j) && !empty($j['c'])) ? (string)$j['c'] : $raw;
  $c = strtoupper(strtr($c, ['М'=>'M','м'=>'M',' '=>'']));
  if (!preg_match('/^(.*\d)-(\d{1,3})$/', $c, $m)) fail('Это не наклейка товара: '.$c);
  $digits = preg_replace('/\D/', '', $m[1]); $sub = (int)$m[2];
  $oq = db()->prepare("SELECT id,num,warehouse_id FROM orders WHERE REGEXP_REPLACE(num,'[^0-9]','')=? AND paid=1 ORDER BY created_at DESC LIMIT 1");
  $oq->execute([$digits]); $o = $oq->fetch();
  if (!$o) fail('Заказ для '.$c.' не найден');
  itc_items_cols(); itc_item_subno_many([$o['id']]);
  $iq = db()->prepare('SELECT id,name FROM order_items WHERE order_id=? AND sub_no=? LIMIT 1'); $iq->execute([$o['id'], $sub]); $it = $iq->fetch();
  if (!$it) fail('В заказе '.$o['num'].' нет товара '.$sub);
  if ($isScan) { $km = itc_item_keys_many([$o['id']]); $rk = (string)($km[$it['id']] ?? ''); if ($key === '' || $rk === '' || !hash_equals($rk, $key)) fail('Наклейка '.$o['num'].'-'.$sub.' не подлинная'); }
  $hub = pack_hub_of_wh($o['warehouse_id']) ?: pack_central_hub();
  return ['kind'=>'item','ref'=>(string)$it['id'],'code'=>$o['num'].'-'.$sub,'name'=>(string)$it['name'],'order_id'=>$o['id'],'zone'=>$hub['code'],'zone_wh'=>$hub['id'],'manual'=>!$isScan];
}
function pack_box_by_qr($raw) {
  pack_tables(); $j = json_decode(trim((string)$raw), true); $id = 0; $key = null;
  if (is_array($j) && ($j['t'] ?? '') === 'pk') { $id = (int)($j['i'] ?? 0); $key = (string)($j['k'] ?? ''); }
  elseif (preg_match('/^\s*[КK]-?(\d{1,6})\s*$/u', (string)$raw, $m)) $id = (int)$m[1];
  if (!$id) return null;
  $q = db()->prepare('SELECT * FROM pack_boxes WHERE id=?'); $q->execute([$id]); $b = $q->fetch();
  if (!$b) return null;
  if ($key !== null && $key !== '' && !hash_equals((string)$b['lbl_key'], $key)) fail('Наклейка коробки '.pack_code($id).' не подлинная');
  return $b;
}
function pack_is_box_qr($raw) { $j = json_decode(trim((string)$raw), true); return (is_array($j) && ($j['t'] ?? '') === 'pk') || preg_match('/^\s*[КK]-\d{1,6}\s*$/u', (string)$raw); }
function pack_box_out($b, $withItems = false) {
  $cq = db()->prepare("SELECT COUNT(*) n, SUM(kind='item') ni, SUM(kind='unit') nu, SUM(missing) nm FROM pack_items WHERE box_id=?"); $cq->execute([$b['id']]); $c = $cq->fetch();
  $o = ['id'=>(int)$b['id'],'code'=>pack_code($b['id']),'zone'=>$b['zone'],'status'=>$b['status'],'key'=>$b['lbl_key'],'weight'=>$b['weight'] !== null ? (float)$b['weight'] : null,
        'n'=>(int)$c['n'],'ni'=>(int)$c['ni'],'nu'=>(int)$c['nu'],'nm'=>(int)$c['nm'],'by'=>$b['created_by'],
        'ts'=>strtotime($b['created_at'])*1000,'shipped'=>$b['shipped_at'] ? strtotime($b['shipped_at'])*1000 : 0,'arrived'=>$b['arrived_at'] ? strtotime($b['arrived_at'])*1000 : 0];
  if ($withItems) { $iq = db()->prepare('SELECT id,kind,code,name,missing FROM pack_items WHERE box_id=? ORDER BY id'); $iq->execute([$b['id']]);
    $o['items'] = array_map(function($r){ return ['id'=>(int)$r['id'],'kind'=>$r['kind'],'code'=>$r['code'],'name'=>$r['name'],'missing'=>(int)$r['missing']]; }, $iq->fetchAll()); }
  return $o;
}
/* Приход коробки в России: складские штуки — в зону ПРИЁМ, позиции заказов —
   «на складе в России»; когда все позиции заказа приняты — заказ на складе. */
function pack_receive_box($b, $who, $wh) {
  pack_tables(); stock_cols();
  $iq = db()->prepare('SELECT * FROM pack_items WHERE box_id=? AND missing=0'); $iq->execute([$b['id']]);
  $nu = 0; $ni = 0; $orders = [];
  foreach ($iq->fetchAll() as $it) {
    if ($it['kind'] === 'unit') {
      $u = db()->prepare("UPDATE stock_units SET status='stock', rcv_at=NOW(), rcv_by=?, wh_id=?, cell='ПРИЁМ' WHERE id=? AND status='china'");
      $u->execute([$who, $wh, $it['ref_id']]); if ($u->rowCount()) { $nu++; try { db()->prepare("INSERT INTO stock_moves (unit_id,from_cell,to_cell,by_name,at) VALUES (?,NULL,'ПРИЁМ',?,NOW())")->execute([$it['ref_id'], $who]); } catch (Exception $e) {} }
      $s2 = db()->prepare("UPDATE stock_units SET rcv_at=COALESCE(rcv_at,NOW()) WHERE id=? AND status IN ('sold','reserved')"); $s2->execute([$it['ref_id']]);
    } else {
      $u = db()->prepare('UPDATE order_items SET ru_rcv_at=NOW() WHERE id=? AND ru_rcv_at IS NULL'); $u->execute([$it['ref_id']]); if ($u->rowCount()) $ni++;
      if (!empty($it['order_id'])) $orders[$it['order_id']] = 1;
    }
  }
  foreach (array_keys($orders) as $oid) {
    $lq = db()->prepare('SELECT COUNT(*) FROM order_items WHERE order_id=? AND ru_rcv_at IS NULL AND COALESCE(stock_reserved,0)=0'); $lq->execute([$oid]);
    if ((int)$lq->fetchColumn() === 0) {
      db()->prepare("UPDATE orders SET dest_received_at=COALESCE(dest_received_at,NOW()), status=IF(status IN ('done'),status,'at_dest') WHERE id=?")->execute([$oid]);
    }
  }
  db()->prepare("UPDATE pack_boxes SET status='arrived', arrived_at=NOW(), arrived_by=? WHERE id=? AND arrived_at IS NULL")->execute([$who, $b['id']]);
  return [$nu, $ni, count($orders)];
}

function stock_code($batchId, $seq, $qty) {
  return 'С-'.str_pad((string)$batchId, 4, '0', STR_PAD_LEFT).'-'.str_pad((string)$seq, $qty > 99 ? 3 : 2, '0', STR_PAD_LEFT);
}

/* №309: ЗАКАЗ ЦЕЛИКОМ НА СКЛАДЕ В КИТАЕ. «Подтверждение складом» отмечало
   позиции принятыми, но статус заказа не менялся, и экран «Контейнер» (он
   берёт заказы «на складе в Гуанчжоу») их не видел. Как только приняты все
   позиции заказа (кроме тех, что отдаём со склада в России), ставим статус. */
function itc_order_mark_at_wh($oid) {
  try {
    $q = db()->prepare("SELECT COUNT(*) FROM ds_procurement WHERE order_id=? AND status<>'received'"); $q->execute([$oid]);
    if ((int)$q->fetchColumn() > 0) return false;
    $sr = '';
    try { db()->query('SELECT stock_reserved FROM order_items LIMIT 1'); $sr = ' AND COALESCE(i.stock_reserved,0)=0'; } catch (Exception $e) {}
    $q2 = db()->prepare("SELECT COUNT(*) FROM order_items i WHERE i.order_id=?$sr
        AND NOT EXISTS (SELECT 1 FROM ds_procurement x WHERE x.order_id=i.order_id AND x.product_id=i.product_id)
        AND NOT EXISTS (SELECT 1 FROM order_accept a WHERE a.order_id=i.order_id AND a.supplier_id=i.supplier_id)");
    $q2->execute([$oid]);
    if ((int)$q2->fetchColumn() > 0) return false;
    $u = db()->prepare("UPDATE orders SET status='at_warehouse' WHERE id=? AND status IN ('created','confirmed')"); $u->execute([$oid]);
    return $u->rowCount() > 0;
  } catch (Exception $e) { return false; }
}

function partner_wh($s) {
  if (($s['role'] ?? '') !== 'partner') return '';
  try { $q=db()->prepare('SELECT warehouse_id FROM partners WHERE id=?'); $q->execute([$s['supplier_id'] ?? '']); return $q->fetchColumn() ?: ''; }
  catch (Exception $e) { return ''; }
}

function s3_content_type($ext) {
  $m = ['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','gif'=>'image/gif',
        'mp4'=>'video/mp4','webm'=>'video/webm','mov'=>'video/quicktime','m4v'=>'video/x-m4v'];
  return $m[$ext] ?? 'application/octet-stream';
}

// Загрузка объекта в S3 (AWS Signature V4, path-style, public-read). Возвращает true/false.
function s3_put_base64($dataUrl) {
  global $S3_ENABLED, $S3_PUBLIC_URL;
  if (empty($S3_ENABLED) || !$dataUrl) return '';
  if (!preg_match('#^data:image/(\w+);base64,(.+)$#s', $dataUrl, $m)) return '';
  $ext = strtolower($m[1]); if ($ext === 'jpeg') $ext = 'jpg';
  if (!in_array($ext, ['jpg','png','webp','gif'], true)) $ext = 'jpg';
  $bin = base64_decode($m[2]); if ($bin === false || strlen($bin) < 10) return '';
  if (strlen($bin) > 8 * 1024 * 1024) return '';   // не больше 8 МБ
  $tmp = @tempnam(sys_get_temp_dir(), 'sup'); if (!$tmp) return '';
  @file_put_contents($tmp, $bin);
  $name = 'support/' . gmdate('Ymd') . '/' . bin2hex(random_bytes(7)) . '.' . $ext;
  $put = s3_put_object($name, $tmp, s3_content_type($ext));
  @unlink($tmp);
  if (!$put) return '';
  return rtrim((string)$S3_PUBLIC_URL, '/') . '/' . $name;
}

function s3_put_object($key, $localPath, $contentType) {
  global $S3_ENDPOINT, $S3_REGION, $S3_BUCKET, $S3_ACCESS_KEY, $S3_SECRET_KEY;
  $host = $S3_ENDPOINT; $region = $S3_REGION ?: 'ru-1'; $service = 's3';
  $payload = file_get_contents($localPath);
  if ($payload === false) return false;
  $payloadHash = hash('sha256', $payload);
  $amzDate = gmdate('Ymd\THis\Z'); $dateStamp = gmdate('Ymd'); $acl = 'public-read';
  $canonicalUri = '/' . $S3_BUCKET . '/' . $key;
  $canonicalHeaders = "content-type:$contentType\nhost:$host\nx-amz-acl:$acl\nx-amz-content-sha256:$payloadHash\nx-amz-date:$amzDate\n";
  $signedHeaders = 'content-type;host;x-amz-acl;x-amz-content-sha256;x-amz-date';
  $canonicalRequest = "PUT\n$canonicalUri\n\n$canonicalHeaders\n$signedHeaders\n$payloadHash";
  $scope = "$dateStamp/$region/$service/aws4_request";
  $stringToSign = "AWS4-HMAC-SHA256\n$amzDate\n$scope\n" . hash('sha256', $canonicalRequest);
  $kDate = hash_hmac('sha256', $dateStamp, 'AWS4' . $S3_SECRET_KEY, true);
  $kRegion = hash_hmac('sha256', $region, $kDate, true);
  $kService = hash_hmac('sha256', $service, $kRegion, true);
  $kSigning = hash_hmac('sha256', 'aws4_request', $kService, true);
  $signature = hash_hmac('sha256', $stringToSign, $kSigning);
  $auth = "AWS4-HMAC-SHA256 Credential=$S3_ACCESS_KEY/$scope, SignedHeaders=$signedHeaders, Signature=$signature";
  $ch = curl_init("https://$host$canonicalUri");
  curl_setopt_array($ch, [
    CURLOPT_CUSTOMREQUEST => 'PUT',
    CURLOPT_POSTFIELDS => $payload,
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_TIMEOUT => 120,
    CURLOPT_HTTPHEADER => [
      "Content-Type: $contentType",
      "x-amz-acl: $acl",
      "x-amz-content-sha256: $payloadHash",
      "x-amz-date: $amzDate",
      "Authorization: $auth",
    ],
  ]);
  $resp = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
  return ($code >= 200 && $code < 300);
}

// Скачать файл по URL во временный файл. Сервер в Гуанчжоу достаёт alicdn
// напрямую. Потолок по размеру — чтобы тяжёлый ролик не завалил память/диск.
function ob_download_to_file($url, $dest, $maxBytes = 0) {
  if (!$url || !function_exists('curl_init')) return false;
  $fp = @fopen($dest, 'wb');
  if (!$fp) return false;
  $ch = curl_init($url);
  curl_setopt_array($ch, [
    CURLOPT_FILE => $fp,
    CURLOPT_FOLLOWLOCATION => true,
    CURLOPT_MAXREDIRS => 5,
    CURLOPT_CONNECTTIMEOUT => 20,
    CURLOPT_TIMEOUT => 180,
    CURLOPT_SSL_VERIFYPEER => false,
    CURLOPT_SSL_VERIFYHOST => 0,
    CURLOPT_USERAGENT => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
    CURLOPT_NOPROGRESS => false,
    CURLOPT_BUFFERSIZE => 262144,
    CURLOPT_PROGRESSFUNCTION => function($ch,$dt,$dn,$ut,$un) use ($maxBytes) {
      return ($maxBytes > 0 && $dn > $maxBytes) ? 1 : 0;   // превысил лимит — рвём
    },
  ]);
  $ok = curl_exec($ch);
  $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
  curl_close($ch);
  fclose($fp);
  if (!$ok || $code < 200 || $code >= 400) { @unlink($dest); return false; }
  if (@filesize($dest) < 1024) { @unlink($dest); return false; }  // пусто/битое
  return true;
}

// Видео 1688 → S3. Ссылка alicdn из РФ не открывается — переносим ролик к себе,
// как фото. Возвращает публичную ссылку selstorage или '' при неудаче.
function ob_video_to_s3($url) {
  global $S3_ENABLED, $S3_PUBLIC_URL;
  $url = trim((string)$url);
  if ($url === '' || empty($S3_ENABLED) || !function_exists('s3_put_object')) return '';
  // Уже у нас в облаке — не перезаливаем
  if (strpos($url, 'selstorage') !== false ||
      ($S3_PUBLIC_URL && strpos($url, rtrim((string)$S3_PUBLIC_URL,'/')) !== false)) return $url;
  $path = parse_url($url, PHP_URL_PATH) ?: '';
  $ext  = strtolower(pathinfo($path, PATHINFO_EXTENSION));
  if (!in_array($ext, ['mp4','webm','mov','m4v'], true)) $ext = 'mp4';
  $tmp = @tempnam(sys_get_temp_dir(), 'obv');
  if (!$tmp) return '';
  if (!ob_download_to_file($url, $tmp, 50 * 1024 * 1024)) { @unlink($tmp); return ''; }
  $name = 'v' . bin2hex(random_bytes(6)) . '.' . $ext;
  $put  = s3_put_object($name, $tmp, s3_content_type($ext));
  @unlink($tmp);
  if (!$put) return '';
  return rtrim((string)$S3_PUBLIC_URL, '/') . '/' . $name;
}

// Разбор размера прямо из названия варианта: «… 60*40», «80×48», «120*60*75».
// Нужен, когда парсер не разложил размер в отдельные поля len/wid/hei.
function ob_dims_from_name($x) {
  $name = (string)(($x['name_ru'] ?? '') ?: ($x['properties'] ?? '') ?: ($x['properties_cn'] ?? ''));
  if ($name === '') return [];
  if (preg_match('/(\d{2,3})\s*[*xXхХ×]\s*(\d{2,3})(?:\s*[*xXхХ×]\s*(\d{2,3}))?/u', $name, $m)) {
    $nn = [(float)$m[1], (float)$m[2]];
    if (!empty($m[3])) $nn[] = (float)$m[3];
    return $nn;
  }
  return [];
}
// Подпись размера изделия из имеющихся измерений (2D «80×40» или 3D «80×40×75»).
// Порядок сторон не важен — сортируем. Меньше двух измерений = размер неясен.
function ob_dim_sig($x) {
  $d = [];
  if ((float)($x['len_cm'] ?? 0) > 0) $d[] = round((float)$x['len_cm'], 1);
  if ((float)($x['wid_cm'] ?? 0) > 0) $d[] = round((float)$x['wid_cm'], 1);
  if ((float)($x['hei_cm'] ?? 0) > 0) $d[] = round((float)$x['hei_cm'], 1);
  if (count($d) < 2) $d = array_map(fn($v)=>round((float)$v,1), ob_dims_from_name($x));
  if (count($d) < 2) return '';
  sort($d);
  return implode('x', $d);
}
function ob_dim_label($x) {
  $d = [];
  if ((float)($x['len_cm'] ?? 0) > 0) $d[] = (float)$x['len_cm'];
  if ((float)($x['wid_cm'] ?? 0) > 0) $d[] = (float)$x['wid_cm'];
  if ((float)($x['hei_cm'] ?? 0) > 0) $d[] = (float)$x['hei_cm'];
  if (count($d) < 2) $d = ob_dims_from_name($x);
  if (!$d) return '';
  return implode('×', array_map(fn($v)=>rtrim(rtrim(number_format((float)$v,1,'.',''),'0'),'.'), $d));
}
