  $def = ['req_company'=>'ООО «Интернациональная Торговая Компания»','req_inn'=>'9701313336','req_kpp'=>'','req_addr'=>'','req_bank'=>'','req_bik'=>'','req_account'=>'','req_corr'=>'','req_director'=>'','req_vat'=>'Без НДС'];
  try { foreach (db()->query("SELECT k,v FROM settings WHERE k LIKE 'req_%'")->fetchAll() as $r) $def[$r['k']] = $r['v']; } catch (Exception $e) {}
