function ensure_ref_code($pid) {
  try {
    $q = db()->prepare('SELECT ref_code FROM partners WHERE id=?'); $q->execute([$pid]); $rc = $q->fetchColumn();
    if ($rc) return $rc;
    for ($i = 0; $i < 8; $i++) {
      $code = strtoupper(substr(bin2hex(random_bytes(4)), 0, 6));
      $chk = db()->prepare('SELECT 1 FROM partners WHERE ref_code=?'); $chk->execute([$code]);
      if (!$chk->fetch()) { db()->prepare('UPDATE partners SET ref_code=? WHERE id=?')->execute([$code, $pid]); return $code; }
    }
  } catch (Exception $e) {}
  return '';
}
// Процент партнёру от суммы продаж по типу склада: ПВЗ = 5%, обычный склад (хаб) = 3%
/* ВОЗНАГРАЖДЕНИЕ ПАРТНЁРА = БАЗОВАЯ СТАВКА + БОНУС НА РАЗВИТИЕ.
   База постоянная: ПВЗ 6%, склад 3%. Бонус на развитие — временный, по
   31.12.2026, свой в каждом регионе, назначает администрация. Суммарно выходит
   столько же, сколько платили раньше (8% и 5%), но часть выплаты теперь срочная
   и отзывная, а не обязательство навсегда. */
if (!defined('ITC_BONUS_UNTIL')) define('ITC_BONUS_UNTIL', '2026-12-31');   // основное объявление — в начале файла (№269)
/* Версия условий для партнёров. Меняем её, когда правим существенные пункты
   оферты, — тогда партнёр подтверждает новую редакцию заново, и мы всегда знаем,
   с каким именно текстом он согласился. */
if (!defined('ITC_OFFER_VER')) define('ITC_OFFER_VER', '2026-08-02');   // основное объявление — в начале файла (№269)
function itc_partner_base_pct($kind) { return ((string)($kind ?? 'hub') === 'pvz') ? 6 : 3; }

/* КРУПНОГАБАРИТ: что пункт выдачи физически принять не может.
   Пороги вынесены в настройки, чтобы менялись без правки кода. */
function itc_oversize_limits() {
  $c = get_settings();
  return [
    'm3' => (float)($c['oversize_m3'] ?? 0.15),   // больше — только склад
    'kg' => (float)($c['oversize_kg'] ?? 25),
  ];
}
function itc_is_oversize($vol, $wt) {
  $l = itc_oversize_limits();
  return (($vol > 0 && $vol > $l['m3']) || ($wt > 0 && $wt > $l['kg']));
}

/* После замера: крупногабаритную ПОЗИЦИЮ помечаем, а не переводим весь заказ.
   Логистика всё равно идёт через родительский склад: туда приходит вся партия,
   мелочь едет дальше на пункт выдачи, а крупное просто не догружается и ждёт
   покупателя на складе. Поэтому заказ может выдаваться в двух местах сразу. */
/* ОБОРОТ ПАРТНЁРА СЧИТАЕТСЯ ПО ПОЗИЦИЯМ, а не по всему заказу.
   Пункт выдачи получает за то, что реально выдал: крупногабаритные позиции
   к нему не приезжают, значит и в его оборот не идут. Склад, наоборот, получает
   за свои заказы плюс за крупногабарит из заказов своих пунктов — он его хранит
   и выдаёт сам. */
function itc_partner_turnover($whId, $kind) {
  if (!$whId) return 0.0;
  try { db()->query("ALTER TABLE order_items ADD COLUMN oversize TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
  $sum = 0.0;
  if (($kind ?? 'hub') === 'pvz') {
    try {
      $q = db()->prepare("SELECT COALESCE(SUM(i.price*i.qty),0)
                            FROM orders o JOIN order_items i ON i.order_id=o.id
                           WHERE o.warehouse_id=? AND o.paid=1
                             AND (i.oversize=0 OR i.oversize IS NULL)");
      $q->execute([$whId]); $sum = (float)$q->fetchColumn();
    } catch (Exception $e) {
      try { $q=db()->prepare("SELECT COALESCE(SUM(i.price*i.qty),0) FROM orders o JOIN order_items i ON i.order_id=o.id WHERE o.warehouse_id=? AND o.paid=1");
            $q->execute([$whId]); $sum=(float)$q->fetchColumn(); } catch (Exception $e2) {}
    }
    return $sum;
  }
  // склад: собственные заказы целиком
  try {
    $q = db()->prepare("SELECT COALESCE(SUM(i.price*i.qty),0)
                          FROM orders o JOIN order_items i ON i.order_id=o.id
                         WHERE o.warehouse_id=? AND o.paid=1");
    $q->execute([$whId]); $sum = (float)$q->fetchColumn();
  } catch (Exception $e) {}
  // плюс крупногабарит, оставшийся у него от заказов подчинённых пунктов
  try {
    $q2 = db()->prepare("SELECT COALESCE(SUM(i.price*i.qty),0)
                           FROM orders o
                           JOIN order_items i ON i.order_id=o.id AND i.oversize=1
                           JOIN warehouses w ON w.id=o.warehouse_id AND w.parent_id=?
                          WHERE o.paid=1");
    $q2->execute([$whId]); $sum += (float)$q2->fetchColumn();
  } catch (Exception $e) {}
  return $sum;
}

function itc_mark_oversize_items($productId, $vol, $wt) {
  if (!$productId || !itc_is_oversize($vol, $wt)) return [];
  try { db()->query("ALTER TABLE order_items ADD COLUMN oversize TINYINT(1) NOT NULL DEFAULT 0"); } catch (Exception $e) {}
  $touched = [];
  try {
    $q = db()->prepare("SELECT o.id, o.num, o.phone, o.warehouse_id,
                               w.kind, w.parent_id, w.name wname,
                               pw.name pname, pw.city pcity, pw.address paddr
                          FROM orders o
                          JOIN order_items i ON i.order_id = o.id AND i.product_id = ?
                          JOIN warehouses w  ON w.id  = o.warehouse_id
                     LEFT JOIN warehouses pw ON pw.id = w.parent_id
                         WHERE o.paid = 1 AND w.kind = 'pvz' AND w.parent_id IS NOT NULL
                         GROUP BY o.id");
    $q->execute([$productId]);
    $rows = $q->fetchAll();
  } catch (Exception $e) { return []; }

  foreach ($rows as $o) {
    // помечаем только эту позицию — остальное едет на пункт как обычно
    try { db()->prepare("UPDATE order_items SET oversize=1 WHERE order_id=? AND product_id=?")
            ->execute([$o['id'], $productId]); }
    catch (Exception $e) { continue; }

    // сколько позиций осталось для пункта
    $rest = 0;
    try { $c = db()->prepare("SELECT COUNT(*) FROM order_items WHERE order_id=? AND (oversize=0 OR oversize IS NULL)");
          $c->execute([$o['id']]); $rest = (int)$c->fetchColumn(); } catch (Exception $e) {}

    $addr = trim(($o['pcity'] ?? '').(!empty($o['paddr']) ? ', '.$o['paddr'] : ''));
    $allBig = ($rest === 0);
    // Везти на пункт нечего — тогда и место выдачи заказа меняем на склад
    if ($allBig) {
      try { db()->prepare("UPDATE orders SET warehouse_id=?, oversize_moved=1, oversize_from=?, oversize_at=NOW() WHERE id=?")
              ->execute([$o['parent_id'], $o['warehouse_id'], $o['id']]); } catch (Exception $e) {}
    } else {
      try { db()->prepare("UPDATE orders SET oversize_moved=2, oversize_at=NOW() WHERE id=?")->execute([$o['id']]); } catch (Exception $e) {}
    }

    if (function_exists('wp_send_to_phone') && !empty($o['phone'])) {
      $title = $allBig ? ('📦 Заказ '.$o['num'].': выдача со склада')
                       : ('📦 Заказ '.$o['num'].': часть выдаётся со склада');
      $text  = $allBig
        ? ('Товар крупногабаритный — в пункте выдачи его принять нельзя. Забрать заказ можно на складе'.($addr ? ': '.$addr : '').'.')
        : ('Крупногабаритные позиции остаются на складе'.($addr ? ' ('.$addr.')' : '').', остальное приедет в ваш пункт выдачи.');
      try { wp_send_to_phone(db(), $o['phone'], $title, $text, '/'); } catch (Exception $e) {}
    }
    itc_log_add('система', 'oversize_item', 'order', $o['id'], ($allBig ? 'весь заказ на склад' : 'позиция остаётся на складе'));
    $touched[] = ['num'=>$o['num'],'all'=>$allBig];
  }
  return $touched;
}

/* Журнал принятия условий партнёрами. Хранится каждая версия отдельной строкой,
   а не перезаписывается: понадобится доказать, с каким текстом человек
   согласился и когда именно. */
