  static $d = false; if ($d) return; $d = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS partner_offer (
    id INT AUTO_INCREMENT PRIMARY KEY,
    partner_id VARCHAR(32) NOT NULL,
    phone VARCHAR(40) NULL,
    kind VARCHAR(10) NULL,
