  static $d = false; if ($d) return; $d = true;
  try { db()->query("CREATE TABLE IF NOT EXISTS partner_bonus (
    id INT AUTO_INCREMENT PRIMARY KEY,
    region VARCHAR(120) NOT NULL,
    kind VARCHAR(10) NOT NULL DEFAULT 'pvz',
