      seen TINYINT NOT NULL DEFAULT 0,
      UNIQUE KEY u_hash (hash), KEY k_got (got_at)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  try { db()->exec('ALTER TABLE itc_sms ADD COLUMN ru TEXT NULL'); } catch (Throwable $e) {}
  try { db()->exec("ALTER TABLE itc_sms ADD COLUMN who VARCHAR(80) NOT NULL DEFAULT ''"); } catch (Throwable $e) {}
  $d = true;
}
