/* ============================================================
   №354 · ОТЕЛИ — бронирование гостиниц в приложении «Отели ИТК».
   Источники: «own» — гостиницы по прямому договору (заводятся боссом,
   ведутся в кабинете гостиницы); позже — поставщики («Островок»,
   RateHawk, Ctrip) через htl_providers(). Клиент платит в рублях через
   заказ магазина (Робокасса), гостиница получает цену минус комиссию.
   ============================================================ */
function htl_tables() {
  static $d = false; if ($d) return;
  $p = db();
  $p->exec("CREATE TABLE IF NOT EXISTS htl_hotels (
      id VARCHAR(24) PRIMARY KEY, src VARCHAR(16) NOT NULL DEFAULT 'own', ext_id VARCHAR(64) NOT NULL DEFAULT '',
      name VARCHAR(190) NOT NULL, name_local VARCHAR(190) NOT NULL DEFAULT '', city VARCHAR(120) NOT NULL DEFAULT '', city_local VARCHAR(120) NOT NULL DEFAULT '',
      country CHAR(2) NOT NULL DEFAULT 'CN', address VARCHAR(400) NOT NULL DEFAULT '', address_local VARCHAR(400) NOT NULL DEFAULT '',
      lat DECIMAL(10,6) NULL, lng DECIMAL(10,6) NULL, stars TINYINT NOT NULL DEFAULT 0, descr TEXT NULL, photos TEXT NULL, amen TEXT NULL,
      checkin VARCHAR(8) NOT NULL DEFAULT '14:00', checkout VARCHAR(8) NOT NULL DEFAULT '12:00', cur CHAR(3) NOT NULL DEFAULT 'CNY',
      phone VARCHAR(40) NOT NULL DEFAULT '', wechat VARCHAR(80) NOT NULL DEFAULT '', email VARCHAR(120) NOT NULL DEFAULT '',
      commission DECIMAL(5,2) NOT NULL DEFAULT 15, status VARCHAR(12) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL,
      KEY k_city (city), KEY k_status (status)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $p->exec("CREATE TABLE IF NOT EXISTS htl_staff (
      hotel_id VARCHAR(24) NOT NULL, phone VARCHAR(20) NOT NULL, name VARCHAR(120) NOT NULL DEFAULT '', PRIMARY KEY (hotel_id, phone), KEY k_phone (phone)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $p->exec("CREATE TABLE IF NOT EXISTS htl_rooms (
      id VARCHAR(24) PRIMARY KEY, hotel_id VARCHAR(24) NOT NULL, name VARCHAR(190) NOT NULL, beds VARCHAR(120) NOT NULL DEFAULT '',
      guests TINYINT NOT NULL DEFAULT 2, area SMALLINT NOT NULL DEFAULT 0, descr TEXT NULL, photos TEXT NULL, amen TEXT NULL,
      price INT NOT NULL DEFAULT 0, qty SMALLINT NOT NULL DEFAULT 1, breakfast TINYINT NOT NULL DEFAULT 0, free_cancel_days TINYINT NOT NULL DEFAULT 1,
      active TINYINT NOT NULL DEFAULT 1, sort SMALLINT NOT NULL DEFAULT 0, KEY k_hotel (hotel_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $p->exec("CREATE TABLE IF NOT EXISTS htl_cal (
      room_id VARCHAR(24) NOT NULL, day DATE NOT NULL, price INT NULL, avail SMALLINT NULL, closed TINYINT NOT NULL DEFAULT 0, PRIMARY KEY (room_id, day)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $p->exec("CREATE TABLE IF NOT EXISTS htl_bookings (
      id VARCHAR(24) PRIMARY KEY, num VARCHAR(20) NOT NULL, order_id VARCHAR(40) NOT NULL DEFAULT '', phone VARCHAR(20) NOT NULL,
      hotel_id VARCHAR(24) NOT NULL, room_id VARCHAR(24) NOT NULL, src VARCHAR(16) NOT NULL DEFAULT 'own', ext_ref VARCHAR(80) NOT NULL DEFAULT '',
      date_in DATE NOT NULL, date_out DATE NOT NULL, nights SMALLINT NOT NULL, guests TINYINT NOT NULL DEFAULT 1, rooms TINYINT NOT NULL DEFAULT 1,
      guest_name VARCHAR(190) NOT NULL DEFAULT '', guest_phone VARCHAR(40) NOT NULL DEFAULT '', note VARCHAR(600) NOT NULL DEFAULT '',
      total_cur INT NOT NULL DEFAULT 0, cur CHAR(3) NOT NULL DEFAULT 'CNY', rub_total INT NOT NULL DEFAULT 0, commission DECIMAL(5,2) NOT NULL DEFAULT 0,
      status VARCHAR(12) NOT NULL DEFAULT 'new', hotel_note VARCHAR(600) NOT NULL DEFAULT '', created_at DATETIME NOT NULL, paid_at DATETIME NULL, answered_at DATETIME NULL,
      KEY k_phone (phone), KEY k_hotel (hotel_id, date_in), KEY k_order (order_id), KEY k_room (room_id, date_in)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  $d = true;
}
function htl_id($p) { return $p . date('ymd') . substr(bin2hex(random_bytes(5)), 0, 8); }
function htl_s($v, $n) { return mb_substr(trim((string)($v ?? '')), 0, $n); }
function htl_cfg() {
  $st = get_settings(); $n = function ($k, $d) use ($st) { return isset($st[$k]) && is_numeric($st[$k]) ? (float)$st[$k] : $d; };
  return ['cny'=>$n('kurs_cny', 13.2), 'usd'=>$n('kurs_usd', 95), 'fx'=>(float)itc_setting('htl_fx_pct', 3), 'comm'=>(float)itc_setting('htl_comm_default', 15), 'hold'=>30];
}
/* Цена для клиента в рублях: цена гостиницы × курс × (1 + запас на курс), вверх до 10 ₽ */
function htl_rub($amount, $cur) {
  $c = htl_cfg(); $k = $cur === 'RUB' ? 1 : ($cur === 'USD' ? $c['usd'] : $c['cny']);
  $r = $amount * $k * ($cur === 'RUB' ? 1 : (1 + $c['fx'] / 100));
  return (int)(ceil($r / 10) * 10);
}
function htl_json($v) { $a = json_decode((string)$v, true); return is_array($a) ? $a : []; }
function htl_dates($in, $out) {
  if (!preg_match('~^\d{4}-\d{2}-\d{2}$~', (string)$in) || !preg_match('~^\d{4}-\d{2}-\d{2}$~', (string)$out)) return null;
  $a = strtotime($in); $b = strtotime($out); if (!$a || !$b || $b <= $a) return null;
  if ($a < strtotime(date('Y-m-d')) - 86400) return null;   // вчера ещё можно (часовые пояса)
  $n = (int)round(($b - $a) / 86400); if ($n < 1 || $n > 60) return null;
  return [$in, $out, $n];
}
/* Сколько номеров этого типа свободно и сколько стоит каждая ночь (в валюте гостиницы) */
function htl_room_quote($room, $in, $out, $nights, $exceptBooking = '') {
  $cal = [];
  $q = db()->prepare('SELECT day, price, avail, closed FROM htl_cal WHERE room_id=? AND day>=? AND day<?'); $q->execute([$room['id'], $in, $out]);
  foreach ($q->fetchAll() as $r) $cal[$r['day']] = $r;
  $busy = [];
  $hold = htl_cfg()['hold'];
  $q = db()->prepare("SELECT date_in, date_out, rooms FROM htl_bookings WHERE room_id=? AND id<>? AND date_in<? AND date_out>? AND (status IN ('paid','confirmed') OR (status='new' AND created_at > NOW() - INTERVAL $hold MINUTE))");
  $q->execute([$room['id'], $exceptBooking, $out, $in]);
  foreach ($q->fetchAll() as $b) for ($t = max(strtotime($b['date_in']), strtotime($in)); $t < min(strtotime($b['date_out']), strtotime($out)); $t += 86400) { $k = date('Y-m-d', $t); $busy[$k] = ($busy[$k] ?? 0) + (int)$b['rooms']; }
  $free = PHP_INT_MAX; $sum = 0; $per = [];
  for ($i = 0; $i < $nights; $i++) {
    $k = date('Y-m-d', strtotime($in) + $i * 86400); $c = $cal[$k] ?? null;
    if ($c && (int)$c['closed']) { $free = 0; }
    $cap = ($c && $c['avail'] !== null) ? (int)$c['avail'] : (int)$room['qty'];
    $free = min($free, max(0, $cap - ($busy[$k] ?? 0)));
    $pr = ($c && $c['price'] !== null && (int)$c['price'] > 0) ? (int)$c['price'] : (int)$room['price'];
    if ($pr <= 0) $free = 0;
    $sum += $pr; $per[] = $pr;
  }
  return ['free'=>$free === PHP_INT_MAX ? 0 : $free, 'total'=>$sum, 'per'=>$per];
}
function htl_photo_urls($json) { return array_values(array_filter(array_map('strval', htl_json($json)))); }
function htl_hotel_out($h, $full = false) {
  $o = ['id'=>$h['id'], 'src'=>$h['src'], 'name'=>$h['name'], 'name_local'=>$h['name_local'], 'city'=>$h['city'], 'city_local'=>$h['city_local'], 'country'=>$h['country'],
        'address'=>$h['address'], 'address_local'=>$h['address_local'], 'stars'=>(int)$h['stars'], 'photos'=>htl_photo_urls($h['photos']),
        'lat'=>$h['lat'] !== null ? (float)$h['lat'] : null, 'lng'=>$h['lng'] !== null ? (float)$h['lng'] : null, 'cur'=>$h['cur'], 'status'=>$h['status']];
  if ($full) $o += ['descr'=>(string)$h['descr'], 'amen'=>htl_json($h['amen']), 'checkin'=>$h['checkin'], 'checkout'=>$h['checkout'], 'phone'=>$h['phone'], 'wechat'=>$h['wechat'], 'email'=>$h['email'], 'commission'=>(float)$h['commission']];
  return $o;
}
function htl_room_out($r) {
  return ['id'=>$r['id'], 'name'=>$r['name'], 'beds'=>$r['beds'], 'guests'=>(int)$r['guests'], 'area'=>(int)$r['area'], 'descr'=>(string)$r['descr'], 'photos'=>htl_photo_urls($r['photos']),
          'amen'=>htl_json($r['amen']), 'price'=>(int)$r['price'], 'qty'=>(int)$r['qty'], 'breakfast'=>(int)$r['breakfast'], 'free_cancel_days'=>(int)$r['free_cancel_days'], 'active'=>(int)$r['active']];
}
/* Поставщики (Островок, RateHawk, Ctrip): подключаются, когда будут ключи.
   Каждый возвращает гостиницы в том же виде, что и свои. Пока пусто. */
function htl_providers() { return []; }
function htl_provider_search($city, $in, $out, $guests) {
  $out_ = [];
  foreach (htl_providers() as $p) { try { $fn = 'htl_prov_' . $p . '_search'; if (function_exists($fn)) $out_ = array_merge($out_, (array)$fn($city, $in, $out, $guests)); } catch (Throwable $e) {} }
  return $out_;
}
/* Права в кабинете гостиницы: сотрудник гостиницы по телефону или босс ИТК */
function htl_is_boss($s) { return ($s['role'] ?? '') === 'itc' && in_array(($s['staff_role'] ?? ''), ['boss', ''], true); }
function htl_my_hotels($s) {
  htl_tables();
  if (htl_is_boss($s)) return db()->query('SELECT * FROM htl_hotels ORDER BY created_at DESC')->fetchAll();
  $t = ph_tail10((string)($s['phone'] ?? '')); if ($t === '') return [];
  $q = db()->prepare('SELECT h.* FROM htl_hotels h JOIN htl_staff s ON s.hotel_id=h.id WHERE RIGHT(' . ph_sql('s.phone') . ',10)=? ORDER BY h.name'); $q->execute([$t]);
  return $q->fetchAll();
}
function htl_can($s, $hotelId) { foreach (htl_my_hotels($s) as $h) if ($h['id'] === $hotelId) return $h; fail('Нет доступа к этой гостинице', 403); }
function htl_hotel_phones($hotelId) { $q = db()->prepare('SELECT phone FROM htl_staff WHERE hotel_id=?'); $q->execute([$hotelId]); return $q->fetchAll(PDO::FETCH_COLUMN); }
function htl_booking_out($b, $forHotel = false) {
  $o = ['id'=>$b['id'], 'num'=>$b['num'], 'hotel_id'=>$b['hotel_id'], 'room_id'=>$b['room_id'], 'date_in'=>$b['date_in'], 'date_out'=>$b['date_out'], 'nights'=>(int)$b['nights'],
        'guests'=>(int)$b['guests'], 'rooms'=>(int)$b['rooms'], 'guest_name'=>$b['guest_name'], 'guest_phone'=>$b['guest_phone'], 'note'=>$b['note'], 'status'=>$b['status'],
        'hotel_note'=>$b['hotel_note'], 'created_at'=>$b['created_at'], 'paid_at'=>$b['paid_at'], 'hotel'=>(string)($b['hname'] ?? ''), 'room'=>(string)($b['rname'] ?? '')];
  if ($forHotel) { $o['total_cur'] = (int)$b['total_cur']; $o['cur'] = $b['cur']; $o['commission'] = (float)$b['commission']; $o['payout'] = (int)floor($b['total_cur'] * (1 - $b['commission'] / 100)); }
  else { $o['rub_total'] = (int)$b['rub_total']; $o['pay_url'] = '/robokassa.php?rk=pay&order=' . rawurlencode($b['order_id']); }
  return $o;
}
function htl_booking_row($id) { $q = db()->prepare('SELECT b.*, h.name hname, r.name rname FROM htl_bookings b LEFT JOIN htl_hotels h ON h.id=b.hotel_id LEFT JOIN htl_rooms r ON r.id=b.room_id WHERE b.id=?'); $q->execute([$id]); return $q->fetch(); }
/* Оплата пришла → бронь «оплачена», гостинице уведомление: подтвердить */
function htl_sync_paid($b) {
  if (!$b || $b['status'] !== 'new' || $b['order_id'] === '') return $b;
  $q = db()->prepare('SELECT paid FROM orders WHERE id=?'); $q->execute([$b['order_id']]);
  if ((int)$q->fetchColumn() !== 1) return $b;
  $u = db()->prepare("UPDATE htl_bookings SET status='paid', paid_at=NOW() WHERE id=? AND status='new'"); $u->execute([$b['id']]);
  if ($u->rowCount() > 0) {
    $txt = $b['num'] . ' · ' . date('d.m', strtotime($b['date_in'])) . '–' . date('d.m', strtotime($b['date_out'])) . ' · ' . ($b['rname'] ?? '') . ' · ' . $b['guest_name'];
    foreach (htl_hotel_phones($b['hotel_id']) as $ph) { try { itc_push_phone($ph, 'Новая бронь — подтвердите', $txt, '/apps/hotels/?cab=1'); } catch (Throwable $e) {} }
    try { notify_boss('Отели: оплачена бронь ' . $b['num'], ($b['hname'] ?? '') . ' · ' . $txt, '/apps/hotels/?cab=1'); } catch (Throwable $e) {}
  }
  return htl_booking_row($b['id']);
}
function htl_after_paid($orderId) {
  htl_tables();
  $q = db()->prepare('SELECT id FROM htl_bookings WHERE order_id=?'); $q->execute([$orderId]);
  foreach ($q->fetchAll(PDO::FETCH_COLUMN) as $id) htl_sync_paid(htl_booking_row($id));
}
/* Фото: присылают как data:image/…;base64 — уменьшаем до 1600 по длинной стороне */
function htl_save_photo($data, $hotelId) {
  if (!preg_match('~^data:image/(jpeg|jpg|png|webp);base64,~', (string)$data)) fail('Нужна картинка');
  $bin = base64_decode(substr($data, strpos($data, ',') + 1)); if (!$bin || strlen($bin) > 15 * 1048576) fail('Фото слишком большое');
  $im = @imagecreatefromstring($bin); if (!$im) fail('Не удалось прочитать фото');
  $w = imagesx($im); $h = imagesy($im); $k = min(1, 1600 / max($w, $h)); $nw = (int)round($w * $k); $nh = (int)round($h * $k);
  $o = imagecreatetruecolor($nw, $nh); imagefill($o, 0, 0, imagecolorallocate($o, 255, 255, 255)); imagecopyresampled($o, $im, 0, 0, 0, 0, $nw, $nh, $w, $h);
  $dir = dirname(__DIR__) . '/uploads/htl/' . preg_replace('~[^a-z0-9]~i', '', $hotelId); if (!is_dir($dir)) @mkdir($dir, 0775, true);
  $f = bin2hex(random_bytes(8)) . '.jpg'; @imagejpeg($o, $dir . '/' . $f, 84); imagedestroy($o); imagedestroy($im);
  if (!is_file($dir . '/' . $f)) fail('Не удалось сохранить фото', 500);
  return '/uploads/htl/' . preg_replace('~[^a-z0-9]~i', '', $hotelId) . '/' . $f;
}
function htl_clean_photos($a) { return array_values(array_slice(array_filter(array_map('strval', (array)$a), function ($u) { return preg_match('~^/uploads/htl/[a-z0-9]+/[a-f0-9]+\.jpg$~i', $u) || preg_match('~^https://~', $u); }), 0, 30)); }
function htl_clean_list($a, $n = 40) { return array_values(array_slice(array_filter(array_map(function ($x) { return htl_s($x, 80); }, (array)$a)), 0, $n)); }
